fn bi_clear() -> Result<Value> {
    // CSI 2J (clear screen) + CSI H (cursor home)
    Ok(Value::Str("\u{1b}[2J\u{1b}[H".to_string()))
}

fn bi_echo(args: &[Value], input: Option<Value>) -> Result<Value> {
    // `"hello" | echo()` answered "": the dispatch row dropped the pipe
    // input, so a piped value vanished. With no arguments, echo the subject.
    if args.is_empty() {
        if let Some(v) = input {
            return Ok(Value::Str(format_value_one_line(&v)));
        }
    }
    let mut s = String::new();
    for (i, v) in args.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(&format_value_one_line(v));
    }
    Ok(Value::Str(s))
}

fn bi_print(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Determine the target Value (either piped input or first arg).
    let target = if let Some(v) = input {
        v
    } else {
        args.into_iter()
            .next()
            .ok_or_else(|| crate::safety::arg_err("print expects a value"))?
    };

    // (Removed an unused strip_ansi helper; tests have their own)

    // Print the pretty display to stdout. `display_full`, not
    // `display_inline`: the latter caps at 80 characters, which silently threw
    // away the tail of anything longer that a script tried to print.
    let pretty =
        crate::value::pretty::display_full(&target, &crate::value::pretty::Theme::for_stdout());
    println!("{}", pretty);

    // Helper to strip ANSI color sequences from a string
    fn strip_ansi(s: &str) -> String {
        let mut out = String::new();
        let mut it = s.chars().peekable();
        while let Some(ch) = it.next() {
            if ch == '\x1b' {
                if let Some('[') = it.peek() {
                    it.next();
                    while let Some(&c) = it.peek() {
                        it.next();
                        if c == 'm' {
                            break;
                        }
                    }
                    continue;
                }
            }
            out.push(ch);
        }
        out
    }

    // Return behavior: always return the pretty inline display (ANSI stripped)
    // as a `Str`. This keeps the REPL and tests consistent regardless of
    // whether the input was a bare string or another value.
    Ok(Value::Str(strip_ansi(&pretty)))
}

/// http_get — fetch one http(s) URL. Usage: http_get(url) or url | http_get.
/// Returns {url, status, headers, body}. The URL passes the network guard and
/// the SSRF rules, and each redirect target passes the same rules before it is
/// followed, at most 5 of them. A non-2xx status is an answer, not a failure.
/// The body is read up to 16 MiB; more is E_BUDGET_EXCEEDED. A request that gets
/// no answer is a coded E_IO, never an empty body. Invalid UTF-8 is replaced.
fn bi_http_get(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use std::io::Read as _;
    net_refuse_in_transaction("http_get")?;
    if args.len() > 1 {
        return Err(crate::safety::arg_err(format!(
            "http_get takes one URL, got {}",
            args.len()
        )));
    }
    let url_val = match (input, args.into_iter().next()) {
        (Some(_), Some(_)) => {
            return Err(crate::safety::arg_err(
                "http_get takes its URL either as an argument or piped in, not both",
            ))
        }
        (Some(v), None) | (None, Some(v)) => v,
        (None, None) => return Err(crate::safety::arg_err("http_get expects URL string/uri")),
    };
    let url = match url_val {
        Value::Str(s) | Value::Uri(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "http_get",
                "a URL String",
                other.type_name(),
            ))
        }
    };
    guard_network("http_get", &url)?;
    let validated_url = validate_http_url("http_get", &url)?;
    let client = http_redirect_client()?;
    let mut resp = client
        .get(&validated_url)
        .send()
        .map_err(|e| net_io_error("http_get", "request", &e))?;
    let status = i64::from(resp.status().as_u16());
    let mut headers_rec = BTreeMap::<String, Value>::new();
    for (k, v) in resp.headers().iter() {
        headers_rec.insert(
            k.to_string(),
            Value::Str(String::from_utf8_lossy(v.as_bytes()).into_owned()),
        );
    }
    let mut bytes = Vec::new();
    std::io::Read::take(&mut resp, HTTP_BODY_MAX + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| net_io_error("http_get", "reading the body", &e))?;
    if bytes.len() as u64 > HTTP_BODY_MAX {
        return Err(crate::safety::budget_exceeded(
            "http_get",
            format!("the body is more than {HTTP_BODY_MAX} bytes"),
            "fetch a smaller resource",
        ));
    }
    let mut out = BTreeMap::<String, Value>::new();
    out.insert("url".into(), Value::Str(validated_url));
    out.insert("status".into(), Value::Int(status));
    out.insert("headers".into(), Value::Record(headers_rec));
    out.insert(
        "body".into(),
        Value::Str(String::from_utf8_lossy(&bytes).into_owned()),
    );
    Ok(Value::Record(out))
}

fn bi_call(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    // call <name> [args...]
    let name_val = args
        .first()
        .cloned()
        .ok_or_else(|| crate::safety::bad_arg("call", "a builtin name", "nothing"))?;
    let name = match name_val {
        Value::Str(s) | Value::Uri(s) => s,
        other => {
            return Err(crate::safety::arg_err(format!(
                "call: expected String builtin name, got {:?}",
                other
            )));
        }
    };
    // remaining args (after name)
    let mut rem: Vec<Value> = Vec::new();
    for v in args.into_iter().skip(1) {
        rem.push(v);
    }
    // If input was provided, pass it as pipe input to the called builtin
    call_with_input(&name, rem, input, env)
}

// --------------- Data / pipeline builtins ---------------

fn bi_map(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let piped = input.is_some();
    let lam_val = if piped {
        arg("map", &args, 0, "a lambda")?
    } else {
        arg("map", &args, 1, "a lambda")?
    };
    let lam = need_lambda(lam_val, "map")?;
    // The array is owned here -- piped or the first argument -- so it is
    // consumed, not copied. This cloned the whole input before starting and
    // then every element again for the lambda.
    let arr_val = match input {
        Some(v) => v,
        None => args
            .first()
            .cloned()
            .ok_or_else(|| crate::safety::bad_arg("map", "an array", "nothing"))?,
    };
    expect_array("map", &arr_val)?;
    let Value::Array(items) = arr_val else {
        unreachable!("expect_array accepted it")
    };
    // Both `fn(x, i)` and `fn(x)` are supported. This used to be discovered by
    // calling with two arguments and retrying with one on failure, which made
    // three copies of every element (`.cloned()`, `v_clone`, and the call's
    // own `v.clone()`) to keep the retry path alive. The lambda knows its own
    // arity, so ask it once.
    let two_arg = lam.params.len() == 2;
    let mut out = Vec::with_capacity(items.len());
    if items.is_empty() {
        return Ok(Value::Array(out));
    }
    with_param_slots(lam, env, |env| {
        for (i, v) in items.into_iter().enumerate() {
            let y = if two_arg {
                call_lambda_owned(lam, vec![v, Value::Int(i as i64)], env, false)?.0
            } else {
                call_lambda_one(lam, v, env, false)?.0
            };
            out.push(y);
        }
        Ok(Value::Array(out))
    })
}

fn bi_where(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let piped = input.is_some();
    let lam_val = if piped {
        arg("where", &args, 0, "a lambda")?
    } else {
        arg("where", &args, 1, "a lambda")?
    };
    let lam = need_lambda(lam_val, "where")?;
    // See `bi_map`: the array is consumed. Each element is moved into the
    // predicate and handed back, so a kept element is never copied.
    let arr_val = match input {
        Some(v) => v,
        None => args
            .first()
            .cloned()
            .ok_or_else(|| crate::safety::bad_arg("where", "an array", "nothing"))?,
    };
    expect_array("where", &arr_val)?;
    let Value::Array(items) = arr_val else {
        unreachable!("expect_array accepted it")
    };
    // See `bi_map`: ask the lambda its arity once instead of calling twice and
    // keeping three copies of each element alive to make the retry possible.
    let two_arg = lam.params.len() == 2;
    let mut out = Vec::new();
    if items.is_empty() {
        return Ok(Value::Array(out));
    }
    with_param_slots(lam, env, |env| {
        for (i, v) in items.into_iter().enumerate() {
            let (keep_val, v) = if two_arg {
                let (k, mut back) =
                    call_lambda_owned(lam, vec![v, Value::Int(i as i64)], env, true)?;
                (k, back.swap_remove(0))
            } else {
                let (k, back) = call_lambda_one(lam, v, env, true)?;
                (k, back.unwrap_or(Value::Null))
            };
            match keep_val {
                Value::Bool(true) => out.push(v),
                Value::Bool(false) => {}
                other => {
                    return Err(crate::safety::arg_err(format!(
                        "where predicate must return Bool, got {:?}",
                        other
                    )))
                }
            }
        }
        Ok(Value::Array(out))
    })
}

fn bi_reduce(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    // Cases:
    //  - piping:  [1,2,3] | reduce fn(a,b)=>... 0
    //  - direct:  reduce [1,2,3] fn(a,b)=>... 0
    // Determine arr, lambda index and init index without moving `input`
    let piped = input.is_some();
    if !piped && args.len() < 3 {
        return Err(crate::safety::bad_arg(
            "reduce",
            "<array> <fn(acc,x)> <init>",
            "nothing",
        ));
    }
    let (lam_idx, init_idx) = if piped {
        (0usize, 1usize)
    } else {
        (1usize, 2usize)
    };

    let lam = need_lambda(arg("reduce", &args, lam_idx, "a lambda")?, "reduce")?;
    let init = arg("reduce", &args, init_idx, "an initial value")?.clone();
    // Select arity before running the body. Retrying on any error copied the
    // accumulator and hid an indexed lambda's body error behind an arity error.
    let indexed = lam.params.len() == 3;
    let arr_val = input.unwrap_or_else(|| args[0].clone());
    expect_array("reduce", &arr_val)?;
    let Value::Array(arr) = arr_val else {
        unreachable!("expect_array accepted it")
    };

    let mut acc = init;
    if arr.is_empty() {
        return Ok(acc);
    }
    with_param_slots(lam, env, |env| {
        for (i, v) in arr.into_iter().enumerate() {
            let mut values = vec![acc, v];
            if indexed {
                values.push(Value::Int(i as i64));
            }
            acc = call_lambda_owned(lam, values, env, false)?.0;
        }
        Ok(acc)
    })
}

fn bi_take(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (arr_val, n_idx) = if let Some(input_val) = input {
        // SECURITY: Replace .unwrap() with explicit match (CVSS 7.1)
        (input_val, 0usize)
    } else {
        if args.len() < 2 {
            return Err(crate::safety::bad_arg("take", "<array> <n>", "nothing"));
        }
        (args[0].clone(), 1usize)
    };

    let n = expect_int(
        "take",
        args.get(n_idx)
            .ok_or_else(|| crate::safety::arg_err("take missing n"))?,
    )?;
    let arr = expect_array("take", &arr_val)?;

    let take_n = if n < 0 { 0 } else { n as usize };
    Ok(Value::Array(arr.iter().take(take_n).cloned().collect()))
}

fn bi_keys(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(crate::safety::arg_err(
            "keys: requires a Record as input or argument",
        ));
    };

    match val {
        Value::Record(map) => {
            let keys: Vec<Value> = map.keys().map(|k| Value::Str(k.clone())).collect();
            Ok(Value::Array(keys))
        }
        _ => Err(crate::safety::arg_err(format!(
            "keys: requires a Record, got {:?}",
            val
        ))),
    }
}

fn bi_values(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(crate::safety::arg_err(
            "values: requires a Record as input or argument",
        ));
    };

    match val {
        Value::Record(map) => {
            let values: Vec<Value> = map.values().cloned().collect();
            Ok(Value::Array(values))
        }
        _ => Err(crate::safety::arg_err(format!(
            "values: requires a Record, got {:?}",
            val
        ))),
    }
}

fn bi_sum(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let arr = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(crate::safety::arg_err(
            "sum: requires an Array as input or argument",
        ));
    };

    match arr {
        Value::Array(items) => {
            let mut int_sum: i64 = 0;
            let mut float_sum: f64 = 0.0;
            let mut has_float = false;

            for item in items {
                match item {
                    Value::Int(n) => {
                        if has_float {
                            float_sum += n as f64;
                        } else {
                            int_sum += n;
                        }
                    }
                    Value::Float(f) => {
                        if !has_float {
                            float_sum = int_sum as f64;
                            has_float = true;
                        }
                        float_sum += f;
                    }
                    _ => {
                        return Err(crate::safety::arg_err(format!(
                            "sum: array must contain only numbers, got {:?}",
                            item
                        )))
                    }
                }
            }

            if has_float {
                Ok(Value::Float(float_sum))
            } else {
                Ok(Value::Int(int_sum))
            }
        }
        _ => Err(crate::safety::arg_err(format!(
            "sum: requires an Array, got {:?}",
            arr
        ))),
    }
}

fn bi_unique(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let array = if let Some(input) = input {
        match input {
            Value::Array(arr) => arr,
            Value::Str(s) => {
                let lines: Vec<Value> =
                    s.lines().map(|line| Value::Str(line.to_string())).collect();
                lines
            }
            _ => {
                return Err(crate::safety::arg_err(
                    "unique: input must be an array or string",
                ))
            }
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Array(arr) => arr.clone(),
            other => {
                return Err(crate::safety::bad_arg(
                    "unique",
                    "argument: Array",
                    other.type_name(),
                ))
            }
        }
    } else {
        return Err(crate::safety::bad_arg(
            "unique",
            "a piped Array or String",
            "a direct call with no subject",
        ));
    };

    // True unique - removes all duplicates (not just consecutive)
    let mut seen = std::collections::HashSet::new();
    let mut unique = Vec::new();

    for item in array {
        let key = format!("{:?}", item);
        if seen.insert(key) {
            unique.push(item);
        }
    }

    Ok(Value::Array(unique))
}

fn bi_avg(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let arr = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(crate::safety::arg_err(
            "avg: requires an Array as input or argument",
        ));
    };

    match arr {
        Value::Array(items) => {
            if items.is_empty() {
                return Ok(Value::Float(f64::NAN));
            }

            let mut sum: f64 = 0.0;
            for item in &items {
                match item {
                    Value::Int(n) => sum += *n as f64,
                    Value::Float(f) => sum += *f,
                    _ => {
                        return Err(crate::safety::arg_err(format!(
                            "avg: array must contain only numbers, got {:?}",
                            item
                        )))
                    }
                }
            }

            Ok(Value::Float(sum / items.len() as f64))
        }
        _ => Err(crate::safety::arg_err(format!(
            "avg: requires an Array, got {:?}",
            arr
        ))),
    }
}

fn bi_product(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let arr = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(crate::safety::arg_err(
            "product: requires an Array as input or argument",
        ));
    };

    match arr {
        Value::Array(items) => {
            let mut int_product: i64 = 1;
            let mut float_product: f64 = 1.0;
            let mut has_float = false;

            for item in items {
                match item {
                    Value::Int(n) => {
                        if has_float {
                            float_product *= n as f64;
                        } else {
                            int_product = int_product.checked_mul(n).ok_or_else(|| {
                                crate::safety::bad_arg(
                                    "product",
                                    "a product within Int range",
                                    "integer overflow",
                                )
                            })?;
                        }
                    }
                    Value::Float(f) => {
                        if !has_float {
                            float_product = int_product as f64;
                            has_float = true;
                        }
                        float_product *= f;
                    }
                    _ => {
                        return Err(crate::safety::bad_arg(
                            "product",
                            "an array of numbers",
                            item.type_name(),
                        ))
                    }
                }
            }

            if has_float {
                Ok(Value::Float(float_product))
            } else {
                Ok(Value::Int(int_product))
            }
        }
        _ => Err(crate::safety::arg_err(format!(
            "product: requires an Array, got {:?}",
            arr
        ))),
    }
}

// --------------- Configuration builtins ---------------

/// Get the entire configuration as a Record
fn bi_config(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let config = get_config();
    let mut map = BTreeMap::new();

    // Shell settings
    let mut shell = BTreeMap::new();
    shell.insert(
        "show_banner".to_string(),
        Value::Bool(config.shell.show_banner),
    );
    shell.insert("show_tips".to_string(), Value::Bool(config.shell.show_tips));
    shell.insert("vi_mode".to_string(), Value::Bool(config.shell.vi_mode));
    shell.insert("auto_cd".to_string(), Value::Bool(config.shell.auto_cd));
    shell.insert(
        "glob_expansion".to_string(),
        Value::Bool(config.shell.glob_expansion),
    );
    shell.insert(
        "command_correction".to_string(),
        Value::Bool(config.shell.command_correction),
    );
    shell.insert(
        "bell_style".to_string(),
        Value::Str(config.shell.bell_style.clone()),
    );
    map.insert("shell".to_string(), Value::Record(shell));

    // Color settings
    let mut colors = BTreeMap::new();
    colors.insert("enabled".to_string(), Value::Bool(config.colors.enabled));
    colors.insert("theme".to_string(), Value::Str(config.colors.theme.clone()));
    colors.insert("force".to_string(), Value::Bool(config.colors.force));
    colors.insert(
        "true_color".to_string(),
        Value::Bool(config.colors.true_color),
    );
    map.insert("colors".to_string(), Value::Record(colors));

    // Prompt settings
    let mut prompt = BTreeMap::new();
    prompt.insert(
        "format".to_string(),
        Value::Str(config.prompt.format.clone()),
    );
    prompt.insert("show_git".to_string(), Value::Bool(config.prompt.show_git));
    prompt.insert(
        "show_time".to_string(),
        Value::Bool(config.prompt.show_time),
    );
    prompt.insert(
        "time_threshold_ms".to_string(),
        Value::Int(config.prompt.time_threshold_ms as i64),
    );
    map.insert("prompt".to_string(), Value::Record(prompt));

    // AI settings
    let mut ai = BTreeMap::new();
    ai.insert(
        "default_provider".to_string(),
        Value::Str(config.ai.default_provider.clone()),
    );
    ai.insert(
        "default_model".to_string(),
        Value::Str(config.ai.default_model.clone()),
    );
    ai.insert(
        "suggestions".to_string(),
        Value::Bool(config.ai.suggestions),
    );
    ai.insert(
        "max_tokens".to_string(),
        Value::Int(config.ai.max_tokens as i64),
    );
    ai.insert(
        "temperature".to_string(),
        Value::Float(config.ai.temperature as f64),
    );
    ai.insert("streaming".to_string(), Value::Bool(config.ai.streaming));
    ai.insert(
        "max_agent_steps".to_string(),
        Value::Int(config.ai.max_agent_steps as i64),
    );
    map.insert("ai".to_string(), Value::Record(ai));

    // History settings
    let mut history = BTreeMap::new();
    history.insert("enabled".to_string(), Value::Bool(config.history.enabled));
    history.insert(
        "max_size".to_string(),
        Value::Int(config.history.max_size as i64),
    );
    history.insert(
        "ignore_duplicates".to_string(),
        Value::Bool(config.history.ignore_duplicates),
    );
    history.insert(
        "ignore_space".to_string(),
        Value::Bool(config.history.ignore_space),
    );
    history.insert("share".to_string(), Value::Bool(config.history.share));
    history.insert(
        "timestamps".to_string(),
        Value::Bool(config.history.timestamps),
    );
    map.insert("history".to_string(), Value::Record(history));

    Ok(Value::Record(map))
}

/// Get a specific config value by path (e.g., "colors.theme" or "ai.default_model")
fn bi_config_get(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "config_get: requires a path argument (e.g., \"colors.theme\")",
        ));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "config_get",
                "path: String",
                other.type_name(),
            ))
        }
    };

    let config = get_config();
    let parts: Vec<&str> = path.split('.').collect();

    match parts.as_slice() {
        // Shell settings
        ["shell", "show_banner"] => Ok(Value::Bool(config.shell.show_banner)),
        ["shell", "show_tips"] => Ok(Value::Bool(config.shell.show_tips)),
        ["shell", "vi_mode"] => Ok(Value::Bool(config.shell.vi_mode)),
        ["shell", "auto_cd"] => Ok(Value::Bool(config.shell.auto_cd)),
        ["shell", "glob_expansion"] => Ok(Value::Bool(config.shell.glob_expansion)),
        ["shell", "command_correction"] => Ok(Value::Bool(config.shell.command_correction)),
        ["shell", "bell_style"] => Ok(Value::Str(config.shell.bell_style.clone())),

        // Color settings
        ["colors", "enabled"] => Ok(Value::Bool(config.colors.enabled)),
        ["colors", "theme"] => Ok(Value::Str(config.colors.theme.clone())),
        ["colors", "force"] => Ok(Value::Bool(config.colors.force)),
        ["colors", "true_color"] => Ok(Value::Bool(config.colors.true_color)),

        // Prompt settings
        ["prompt", "format"] => Ok(Value::Str(config.prompt.format.clone())),
        ["prompt", "show_git"] => Ok(Value::Bool(config.prompt.show_git)),
        ["prompt", "show_time"] => Ok(Value::Bool(config.prompt.show_time)),
        ["prompt", "time_threshold_ms"] => Ok(Value::Int(config.prompt.time_threshold_ms as i64)),

        // AI settings
        ["ai", "default_provider"] => Ok(Value::Str(config.ai.default_provider.clone())),
        ["ai", "default_model"] => Ok(Value::Str(config.ai.default_model.clone())),
        ["ai", "suggestions"] => Ok(Value::Bool(config.ai.suggestions)),
        ["ai", "max_tokens"] => Ok(Value::Int(config.ai.max_tokens as i64)),
        ["ai", "temperature"] => Ok(Value::Float(config.ai.temperature as f64)),
        ["ai", "streaming"] => Ok(Value::Bool(config.ai.streaming)),
        ["ai", "max_agent_steps"] => Ok(Value::Int(config.ai.max_agent_steps as i64)),

        // History settings
        ["history", "enabled"] => Ok(Value::Bool(config.history.enabled)),
        ["history", "max_size"] => Ok(Value::Int(config.history.max_size as i64)),
        ["history", "ignore_duplicates"] => Ok(Value::Bool(config.history.ignore_duplicates)),
        ["history", "ignore_space"] => Ok(Value::Bool(config.history.ignore_space)),
        ["history", "share"] => Ok(Value::Bool(config.history.share)),
        ["history", "timestamps"] => Ok(Value::Bool(config.history.timestamps)),

        _ => Err(crate::safety::not_found("config_get", "config path", &path)),
    }
}

/// Set a config value (saves to config file)
/// Note: This modifies the config file but changes only take effect after reload
/// The settable paths, for the refusal that names them.
const CONFIG_SETTABLE: &str = "colors.enabled|theme|force|true_color, shell.show_banner|show_tips|vi_mode|auto_cd, ai.default_model|default_provider|max_tokens|streaming, history.enabled|max_size";

/// Refuse a value the config path cannot hold, before the file is read. Every
/// settable path has a fixed type and range; `max_tokens` used to be cast with
/// `as u32`, so -1 became 4294967295 and was saved.
fn config_value_ok(path: &str, value: &Value) -> Result<()> {
    const B: &str = "config_set";
    const BOOL_PATHS: &[&str] = &[
        "colors.enabled",
        "colors.force",
        "colors.true_color",
        "shell.show_banner",
        "shell.show_tips",
        "shell.vi_mode",
        "shell.auto_cd",
        "ai.streaming",
        "history.enabled",
    ];
    let refuse = |expected: String| {
        crate::safety::bad_arg(B, &expected, &format!("{} {value}", value.type_name()))
    };
    if BOOL_PATHS.contains(&path) {
        return match value {
            Value::Bool(_) => Ok(()),
            _ => Err(refuse(format!("{path}: Bool"))),
        };
    }
    match path {
        "colors.theme" => match value {
            Value::Str(s)
                if (1..=64).contains(&s.len())
                    && s.chars()
                        .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') =>
            {
                Ok(())
            }
            _ => Err(refuse(
                "colors.theme: a String of 1 to 64 letters, digits, '_' or '-'".to_string(),
            )),
        },
        "ai.default_model" | "ai.default_provider" => match value {
            Value::Str(s)
                if !s.trim().is_empty() && s.len() <= 256 && !s.chars().any(char::is_control) =>
            {
                Ok(())
            }
            _ => Err(refuse(format!(
                "{path}: a non-blank String of at most 256 bytes without control characters"
            ))),
        },
        "ai.max_tokens" => match value {
            Value::Int(n) if (1..=i64::from(u32::MAX)).contains(n) => Ok(()),
            _ => Err(refuse(
                "ai.max_tokens: an Int in 1..=4294967295".to_string(),
            )),
        },
        "history.max_size" => match value {
            Value::Int(n) if (1..=1_000_000).contains(n) => Ok(()),
            _ => Err(refuse(
                "history.max_size: an Int in 1..=1000000".to_string(),
            )),
        },
        _ => Err(crate::safety::bad_arg(
            B,
            &format!("a settable path: {CONFIG_SETTABLE}"),
            path,
        )),
    }
}

/// config_set(path, value) - set one config value and save the config file.
/// The path and value are checked before the file is read; a value of the
/// wrong type or outside its range is E_BAD_ARG and nothing is saved.
fn bi_config_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "config_set";
    k8s_no_input(B, &input)?;
    let path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        Some(other) => return Err(crate::safety::bad_arg(B, "path: String", other.type_name())),
        None => {
            return Err(crate::safety::arg_err(
                "config_set requires path and value arguments",
            ))
        }
    };
    let value = args
        .get(1)
        .ok_or_else(|| crate::safety::arg_err("config_set requires path and value arguments"))?;
    config_value_ok(&path, value)?;

    let mut config = ShellConfig::load().map_err(|e| {
        crate::safety::bad_state(
            B,
            &format!("the config file could not be read: {e}"),
            "config_path",
        )
    })?;
    match (path.as_str(), value) {
        ("colors.enabled", Value::Bool(v)) => config.colors.enabled = *v,
        ("colors.theme", Value::Str(v)) => config.colors.theme = v.clone(),
        ("colors.force", Value::Bool(v)) => config.colors.force = *v,
        ("colors.true_color", Value::Bool(v)) => config.colors.true_color = *v,

        ("shell.show_banner", Value::Bool(v)) => config.shell.show_banner = *v,
        ("shell.show_tips", Value::Bool(v)) => config.shell.show_tips = *v,
        ("shell.vi_mode", Value::Bool(v)) => config.shell.vi_mode = *v,
        ("shell.auto_cd", Value::Bool(v)) => config.shell.auto_cd = *v,

        ("ai.default_model", Value::Str(v)) => config.ai.default_model = v.clone(),
        ("ai.default_provider", Value::Str(v)) => config.ai.default_provider = v.clone(),
        ("ai.max_tokens", Value::Int(v)) => config.ai.max_tokens = *v as u32,
        ("ai.streaming", Value::Bool(v)) => config.ai.streaming = *v,

        ("history.enabled", Value::Bool(v)) => config.history.enabled = *v,
        ("history.max_size", Value::Int(v)) => config.history.max_size = *v as usize,
        // config_value_ok admits only the pairs above; a refusal here would be
        // a coded one rather than a panic.
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                &format!("a settable path: {CONFIG_SETTABLE}"),
                &path,
            ))
        }
    }

    config.save().map_err(|e| {
        crate::safety::bad_state(
            B,
            &format!("the config file could not be written: {e}"),
            "config_path",
        )
    })?;
    let shown = match value {
        Value::Str(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Int(n) => n.to_string(),
        other => other.type_name().to_string(),
    };
    Ok(Value::Str(format!("Config saved: {path} = {shown}")))
}

/// Get config file paths
fn bi_config_path() -> Result<Value> {
    let mut map = BTreeMap::new();
    map.insert(
        "config_file".to_string(),
        Value::Str(ShellConfig::config_file().to_string_lossy().to_string()),
    );
    map.insert(
        "config_dir".to_string(),
        Value::Str(ShellConfig::config_dir().to_string_lossy().to_string()),
    );
    map.insert(
        "data_dir".to_string(),
        Value::Str(ShellConfig::data_dir().to_string_lossy().to_string()),
    );
    map.insert(
        "cache_dir".to_string(),
        Value::Str(ShellConfig::cache_dir().to_string_lossy().to_string()),
    );
    map.insert(
        "history_file".to_string(),
        Value::Str(ShellConfig::history_file().to_string_lossy().to_string()),
    );
    map.insert(
        "plugins_dir".to_string(),
        Value::Str(ShellConfig::plugins_dir().to_string_lossy().to_string()),
    );
    map.insert(
        "init_script".to_string(),
        Value::Str(ShellConfig::init_script().to_string_lossy().to_string()),
    );
    Ok(Value::Record(map))
}

/// Initialize config directories and create default config file
fn bi_config_init(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "config_init";
    // Takes no arguments (declared so) and no pipeline input.
    k8s_no_input(B, &input)?;
    if !args.is_empty() {
        return Err(crate::safety::bad_arg(
            B,
            "no arguments",
            &format!("{} argument(s)", args.len()),
        ));
    }
    ShellConfig::init_dirs().map_err(|e| {
        crate::safety::bad_state(
            B,
            &format!("the config directories could not be created: {e}"),
            "config_path",
        )
    })?;

    let config_file = ShellConfig::config_dir().join("config.toml");
    if !config_file.exists() {
        let default_config = ShellConfig::generate_default_config();
        fs::write(&config_file, default_config)
            .map_err(|e| crate::safety::fs_error(B, &config_file, &e))?;
        Ok(Value::Str(format!(
            "Created config file: {}",
            config_file.display()
        )))
    } else {
        Ok(Value::Str(format!(
            "Config file already exists: {}",
            config_file.display()
        )))
    }
}

/// Reload configuration from disk
fn bi_config_reload() -> Result<Value> {
    // The failure was an uncoded string; success was the prose
    // "Configuration reloaded".
    reload_config().map_err(|e| {
        crate::safety::bad_state(
            "config_reload",
            &format!("the configuration could not be reloaded: {e}"),
            "fix the config file (see config_path()) and reload",
        )
    })?;
    Ok(Value::Bool(true))
}

