/// feature_disable(name) - Disable a runtime feature
/// Args:
///   - name: String - Feature name to disable
/// Returns: Bool - true if the feature was disabled, false if it wasn't enabled
///
/// Example:
///   feature_disable("experimental")
fn bi_feature_disable(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = if let Some(input_val) = input {
        match input_val {
            Value::Str(s) => s,
            other => {
                return Err(crate::safety::bad_arg(
                    "feature_disable",
                    "feature name: String",
                    other.type_name(),
                ))
            }
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            other => {
                return Err(crate::safety::bad_arg(
                    "feature_disable",
                    "feature name: String",
                    other.type_name(),
                ))
            }
        }
    } else {
        return Err(crate::safety::arg_err(
            "feature_disable: requires feature name argument",
        ));
    };

    let mut features = FEATURE_FLAGS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("feature_disable", "the feature table"))?;
    let removed = features.remove(&name);
    Ok(Value::Bool(removed))
}

/// feature_set(name, enabled) - Set a runtime feature to enabled or disabled
/// Args:
///   - name: String - Feature name
///   - enabled: Bool - true to enable, false to disable
/// Returns: Bool - true (always succeeds)
///
/// Example:
///   feature_set("ai", true)       # Enable "ai" feature
///   feature_set("debug", false)   # Disable "debug" feature
fn bi_feature_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "feature_set";
    // Piped: the name is the subject and the one argument is `enabled`.
    // Direct: name and enabled are both arguments. Surplus arguments are
    // refused in either form, not dropped.
    let (name_value, enabled_value) = match input {
        Some(subject) => match args.as_slice() {
            [enabled] => (subject, enabled.clone()),
            _ => {
                return Err(crate::safety::arg_err(format!(
                    "{B}: piped, it takes exactly one argument (enabled), got {}",
                    args.len()
                )))
            }
        },
        None => match args.as_slice() {
            [name, enabled] => (name.clone(), enabled.clone()),
            _ => {
                return Err(crate::safety::arg_err(format!(
                    "{B} requires name and enabled arguments, got {}",
                    args.len()
                )))
            }
        },
    };
    let name = match name_value {
        Value::Str(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                B,
                "feature name: String",
                other.type_name(),
            ))
        }
    };
    let enabled = match enabled_value {
        Value::Bool(b) => b,
        other => {
            return Err(crate::safety::bad_arg(
                B,
                "enabled: Bool",
                other.type_name(),
            ))
        }
    };
    // A flag name is a short identifier. Anything else is refused rather than
    // stored, where it could never be matched by the feature it was meant for.
    if name.is_empty()
        || name.len() > 128
        || !name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ':'))
    {
        return Err(crate::safety::bad_arg(
            B,
            "feature name: 1 to 128 letters, digits, '_', '-', '.' or ':'",
            &format!("{name:?}"),
        ));
    }
    let mut features = FEATURE_FLAGS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("feature_set", "the feature table"))?;
    if enabled {
        features.insert(name);
    } else {
        features.remove(&name);
    }
    Ok(Value::Bool(true))
}

// ===================== Distributed Computing Builtins =====================

/// cluster_create(name) - Create a new compute cluster
/// Args:
///   - name: String - Cluster name (optional, defaults to "default")
/// Returns: Record with cluster info
fn bi_cluster_create(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.len() > 1 {
        return Err(crate::safety::bad_arg(
            "cluster_create",
            "at most one name argument",
            &format!("{} arguments", args.len()),
        ));
    }
    // A name that is not a string used to become "default" with no word.
    let name = match input.or_else(|| args.first().cloned()) {
        None => "default".to_string(),
        Some(Value::Str(s)) if !s.is_empty() && s.len() <= 128 => s,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "cluster_create",
                "a cluster name: a non-empty string of at most 128 bytes",
                other.type_name(),
            ))
        }
    };

    // The cluster is stored in this process's registry, where cluster_status
    // counts it. Nothing is started and no node is contacted. Nodes added with
    // cluster_add_node join a separate process-wide node registry that does not
    // record which cluster they belong to.
    let created_at = chrono::Utc::now().to_rfc3339();
    {
        let mut clusters = CLUSTERS
            .write()
            .map_err(|_| crate::safety::lock_poisoned("cluster_create", "the cluster registry"))?;
        if clusters.contains_key(&name) {
            return Err(crate::safety::bad_arg(
                "cluster_create",
                "a cluster name not already in use in this process",
                &format!("{name:?}, which is already a cluster"),
            ));
        }
        if clusters.len() >= CLUSTER_MAX {
            return Err(crate::safety::budget_exceeded(
                "cluster_create",
                format!("{CLUSTER_MAX} clusters are already stored in this process"),
                "this process has no cluster removal; start a new process to reset the registry",
            ));
        }
        clusters.insert(name.clone(), created_at.clone());
    }

    let mut record = BTreeMap::new();
    record.insert("name".to_string(), Value::Str(name));
    record.insert("status".to_string(), Value::Str("created".to_string()));
    record.insert("created_at".to_string(), Value::Str(created_at));
    Ok(Value::Record(record))
}

/// Most clusters one process stores. The registry has no removal builtin.
const CLUSTER_MAX: usize = 64;

/// cluster_add_node(id, address, capabilities?) - Add a node to the cluster
/// Args:
///   - id: String - Node identifier
///   - address: String - Node address (e.g., "192.168.1.10:8080")
///   - capabilities: Array - Optional list of capabilities
/// Returns: Record with node info
fn bi_cluster_add_node(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (id, address) = if let Some(Value::Record(rec)) = input.clone() {
        // Record input: {id: "...", address: "..."}
        let id = rec
            .get("id")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("cluster_add_node: missing 'id' in record"))?;
        let address = rec
            .get("address")
            .map(|v| v.to_display_string())
            .ok_or_else(|| {
                crate::safety::arg_err("cluster_add_node: missing 'address' in record")
            })?;
        (id, address)
    } else if args.len() >= 2 {
        let id = args[0].to_display_string();
        let address = args[1].to_display_string();
        (id, address)
    } else {
        return Err(crate::safety::arg_err(
            "cluster_add_node: requires id and address arguments",
        ));
    };

    if args.len() > 3 {
        return Err(crate::safety::bad_arg(
            "cluster_add_node",
            "at most 3 arguments: id, address, capabilities",
            &format!("{} arguments", args.len()),
        ));
    }
    if id.is_empty() || address.is_empty() || address.chars().any(char::is_whitespace) {
        return Err(crate::safety::bad_arg(
            "cluster_add_node",
            "a non-empty id and an address with no whitespace",
            &format!("id '{id}', address '{address}'"),
        ));
    }

    let capabilities = match args.get(2) {
        None => vec!["compute".to_string(), "storage".to_string()],
        // An array of strings or nothing. Anything else used to become an
        // empty capability list with no error.
        Some(Value::Array(arr)) => {
            let mut caps = Vec::with_capacity(arr.len());
            for c in arr {
                match c {
                    Value::Str(s) => caps.push(s.clone()),
                    other => {
                        return Err(crate::safety::bad_arg(
                            "cluster_add_node",
                            "capabilities: Array<String>",
                            other.type_name(),
                        ))
                    }
                }
            }
            caps
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "cluster_add_node",
                "capabilities: Array<String>",
                other.type_name(),
            ))
        }
    };

    let node = ClusterNode {
        id: id.clone(),
        address: address.clone(),
        capabilities: capabilities.clone(),
        status: NodeStatus::Registered,
        load: 0.0,
        last_heartbeat: std::time::Instant::now(),
    };

    let mut nodes = CLUSTER_NODES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("cluster_add_node", "the cluster node table"))?;
    nodes.insert(id.clone(), node);

    let mut record = BTreeMap::new();
    record.insert("id".to_string(), Value::Str(id));
    record.insert("address".to_string(), Value::Str(address));
    record.insert(
        "capabilities".to_string(),
        Value::Array(capabilities.into_iter().map(Value::Str).collect()),
    );
    // Nothing contacted the node, so it is not "online": it is registered in
    // this process. Liveness is not checked by anything in this builtin.
    record.insert("status".to_string(), Value::Str("registered".to_string()));

    Ok(Value::Record(record))
}

/// cluster_remove_node(id) - Remove a node from the cluster
fn bi_cluster_remove_node(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let id = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("cluster_remove_node", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("cluster_remove_node: requires node id"))?;

    let mut nodes = CLUSTER_NODES.write().map_err(|_| {
        crate::safety::lock_poisoned("cluster_remove_node", "the cluster node table")
    })?;

    let removed = nodes.remove(&id).is_some();
    Ok(Value::Bool(removed))
}

/// cluster_status() - Get cluster status
fn bi_cluster_status(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let nodes = CLUSTER_NODES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("cluster_status", "the cluster node table"))?;

    let jobs = DISTRIBUTED_JOBS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("cluster_status", "the distributed job table"))?;
    let clusters = CLUSTERS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("cluster_status", "the cluster registry"))?;

    let online_count = nodes
        .values()
        .filter(|n| n.status == NodeStatus::Online)
        .count();
    let busy_count = nodes
        .values()
        .filter(|n| n.status == NodeStatus::Busy)
        .count();
    // Nodes added by cluster_add_node are registered, not checked, so they are
    // counted here and not as online.
    let registered_count = nodes
        .values()
        .filter(|n| n.status == NodeStatus::Registered)
        .count();
    let pending_jobs = jobs
        .values()
        .filter(|j| j.status == JobStatus::Pending)
        .count();
    let running_jobs = jobs
        .values()
        .filter(|j| j.status == JobStatus::Running)
        .count();
    let avg_load: f32 = if nodes.is_empty() {
        0.0
    } else {
        nodes.values().map(|n| n.load).sum::<f32>() / nodes.len() as f32
    };

    let mut record = BTreeMap::new();
    record.insert("clusters".to_string(), Value::Int(clusters.len() as i64));
    record.insert(
        "cluster_names".to_string(),
        Value::Array(clusters.keys().map(|k| Value::Str(k.clone())).collect()),
    );
    record.insert("total_nodes".to_string(), Value::Int(nodes.len() as i64));
    record.insert("online_nodes".to_string(), Value::Int(online_count as i64));
    record.insert(
        "registered_nodes".to_string(),
        Value::Int(registered_count as i64),
    );
    record.insert("busy_nodes".to_string(), Value::Int(busy_count as i64));
    record.insert("total_jobs".to_string(), Value::Int(jobs.len() as i64));
    record.insert("pending_jobs".to_string(), Value::Int(pending_jobs as i64));
    record.insert("running_jobs".to_string(), Value::Int(running_jobs as i64));
    record.insert("average_load".to_string(), Value::Float(avg_load as f64));

    Ok(Value::Record(record))
}

/// cluster_nodes() - List all nodes in the cluster
fn bi_cluster_nodes(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let nodes = CLUSTER_NODES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("cluster_nodes", "the cluster node table"))?;

    let node_list: Vec<Value> = nodes
        .values()
        .map(|node| {
            let mut record = BTreeMap::new();
            record.insert("id".to_string(), Value::Str(node.id.clone()));
            record.insert("address".to_string(), Value::Str(node.address.clone()));
            record.insert(
                "status".to_string(),
                Value::Str(node.status.as_str().to_string()),
            );
            record.insert("load".to_string(), Value::Float(node.load as f64));
            record.insert(
                "capabilities".to_string(),
                Value::Array(
                    node.capabilities
                        .iter()
                        .map(|c| Value::Str(c.clone()))
                        .collect(),
                ),
            );
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(node_list))
}

/// job_submit(name, task, priority?) - Refused. The distributed job table has no
/// executor behind it: a job submitted here would stay pending for ever, and the
/// status it reported would be a promise nothing keeps. No job id is issued, and
/// nothing is run through a shell.
fn bi_job_submit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("job_submit", &input)?;
    collab_text_arg("job_submit", "name", args.first(), 128)?;
    collab_text_arg("job_submit", "task", args.get(1), 4096)?;
    match args.get(2) {
        None | Some(Value::Int(_)) => {}
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "job_submit",
                "priority: Int",
                other.type_name(),
            ))
        }
    }
    Err(crate::safety::unimplemented(
        "job_submit",
        "there is no job executor, so a submitted job would never run and no job id is issued",
        "run the task directly in this session",
    ))
}

/// job_status(job_id) - The status of a job in the distributed job table.
fn bi_job_status(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("job_status", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("job_status: requires job_id"))?;

    let jobs = DISTRIBUTED_JOBS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("job_status", "the distributed job table"))?;

    let job = jobs
        .get(&job_id)
        .ok_or_else(|| crate::safety::not_found("job_status", "job", &job_id.to_string()))?;

    let mut record = BTreeMap::new();
    record.insert("job_id".to_string(), Value::Str(job.id.clone()));
    record.insert("name".to_string(), Value::Str(job.name.clone()));
    record.insert(
        "status".to_string(),
        Value::Str(job.status.as_str().to_string()),
    );
    record.insert("priority".to_string(), Value::Int(job.priority as i64));
    if let Some(node_id) = &job.node_id {
        record.insert("node_id".to_string(), Value::Str(node_id.clone()));
    }

    Ok(Value::Record(record))
}

/// job_cancel(job_id) - Cancel a pending or running job. A job that has already
/// finished or been cancelled is refused, not reported as a silent false.
fn bi_job_cancel(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("job_cancel", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("job_cancel: requires job_id"))?;

    let mut jobs = DISTRIBUTED_JOBS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("job_cancel", "the distributed job table"))?;

    let job = jobs
        .get_mut(&job_id)
        .ok_or_else(|| crate::safety::not_found("job_cancel", "job", &job_id.to_string()))?;
    match job.status {
        JobStatus::Pending | JobStatus::Running => {
            job.status = JobStatus::Cancelled;
            Ok(Value::Bool(true))
        }
        _ => Err(crate::safety::bad_state(
            "job_cancel",
            &format!(
                "job {job_id} is {}; only a pending or running job cancels",
                job.status.as_str()
            ),
            "job_status",
        )),
    }
}

/// job_results(job_id) - Get the results of a completed job
fn bi_job_results(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("job_results", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("job_results: requires job_id"))?;

    let results = JOB_RESULTS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("job_results", "the job result store"))?;

    if let Some(result_values) = results.get(&job_id) {
        Ok(Value::Array(result_values.clone()))
    } else {
        Ok(Value::Array(vec![]))
    }
}

/// job_list() - List all jobs
fn bi_job_list(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let jobs = DISTRIBUTED_JOBS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("job_list", "the distributed job table"))?;

    let job_list: Vec<Value> = jobs
        .values()
        .map(|job| {
            let mut record = BTreeMap::new();
            record.insert("job_id".to_string(), Value::Str(job.id.clone()));
            record.insert("name".to_string(), Value::Str(job.name.clone()));
            record.insert(
                "status".to_string(),
                Value::Str(job.status.as_str().to_string()),
            );
            record.insert("priority".to_string(), Value::Int(job.priority as i64));
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(job_list))
}

/// remote_exec(node_id, command), or the same two fields as a Record piped in:
/// not implemented. No SSH or cluster transport is wired, so the command is not
/// sent to the node. Once it is, the remote node runs `command` through its
/// login shell, because ssh hands the string to the remote shell; a caller must
/// treat `command` as shell input. Arguments are checked first: a plain node
/// name, a non-empty command of at most 8 KiB, and a node that is registered.
fn bi_remote_exec(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "remote_exec";
    let (node, command) = match input {
        Some(Value::Record(rec)) => {
            if !args.is_empty() {
                return Err(crate::safety::arg_err(
                    "remote_exec: give the node and command as arguments or as a piped Record, not both",
                ));
            }
            for key in rec.keys() {
                if key != "node_id" && key != "command" {
                    return Err(crate::safety::arg_err(format!(
                        "remote_exec: unknown field {key:?}; the fields are node_id and command"
                    )));
                }
            }
            let text = |field: &str| -> Result<String> {
                match rec.get(field) {
                    Some(Value::Str(s)) => Ok(s.clone()),
                    Some(other) => Err(crate::safety::arg_err(format!(
                        "remote_exec: {field} must be a String, got {}",
                        other.type_name()
                    ))),
                    None => Err(crate::safety::arg_err(format!(
                        "remote_exec: missing '{field}'"
                    ))),
                }
            };
            (text("node_id")?, text("command")?)
        }
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "remote_exec: a piped input must be a Record with node_id and command, got {}",
                other.type_name()
            )))
        }
        None => {
            k8s_max_args(B, &args, 2)?;
            let node = k8s_need(B, "a node id", &args, 0, pkg_plain)?;
            let command = match args.get(1) {
                Some(Value::Str(s)) => s.clone(),
                Some(other) => {
                    return Err(crate::safety::arg_err(format!(
                        "remote_exec: command must be a String, got {}",
                        other.type_name()
                    )))
                }
                None => {
                    return Err(crate::safety::arg_err(
                        "remote_exec requires node_id and command",
                    ))
                }
            };
            (node, command)
        }
    };
    let node_id = pkg_plain(B, "node id", &node)?;
    if command.trim().is_empty() || command.contains('\0') || command.len() > OPS_MAX_COMMAND {
        return Err(crate::safety::arg_err(format!(
            "remote_exec: command must be non-empty, without NUL, and at most {OPS_MAX_COMMAND} bytes"
        )));
    }
    let known = CLUSTER_NODES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("remote_exec", "the cluster node table"))?
        .contains_key(&node_id);
    if !known {
        return Err(crate::safety::not_found(B, "node", &node_id));
    }
    Err(crate::safety::unimplemented(
        B,
        &format!(
            "the command was not sent to node {node_id:?}: no SSH or cluster transport is wired"
        ),
        "use ssh_exec for a remote command",
    ))
}

/// aggregate_results(results, strategy?) - Aggregate results from distributed computation
fn bi_aggregate_results(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Piped: the results are the input and the strategy is the only argument.
    // Unpiped: results, then strategy. The strategy used to be read from
    // position 1 either way, so `[..] | aggregate_results("sum")` silently
    // aggregated with "concat".
    let (results, strategy_arg) = match input {
        Some(v) => {
            if args.len() > 1 {
                return Err(crate::safety::bad_arg(
                    "aggregate_results",
                    "with piped input, at most one argument: the strategy",
                    &format!("{} arguments", args.len()),
                ));
            }
            (v, args.first())
        }
        None => {
            if args.len() > 2 {
                return Err(crate::safety::bad_arg(
                    "aggregate_results",
                    "results, then an optional strategy",
                    &format!("{} arguments", args.len()),
                ));
            }
            let r = args.first().cloned().ok_or_else(|| {
                crate::safety::arg_err("aggregate_results: requires results array")
            })?;
            (r, args.get(1))
        }
    };

    let results = match results {
        Value::Array(arr) => arr,
        other => {
            return Err(crate::safety::bad_arg(
                "aggregate_results",
                "results: Array",
                other.type_name(),
            ))
        }
    };

    let strategy = match strategy_arg {
        None => "concat".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "aggregate_results",
                "strategy: a string (concat, sum, count, first, last)",
                other.type_name(),
            ))
        }
    };

    match strategy.as_str() {
        "concat" => Ok(Value::Array(results)),
        "sum" => {
            // A non-number used to be skipped, so the sum of a list with a
            // failed element looked like a sum of the rest. Refuse it.
            let mut sum = 0.0f64;
            for (i, v) in results.iter().enumerate() {
                match v {
                    Value::Int(n) => sum += *n as f64,
                    Value::Float(f) if f.is_finite() => sum += *f,
                    other => {
                        return Err(crate::safety::bad_arg(
                            "aggregate_results",
                            &format!("results[{i}]: a finite number for strategy \"sum\""),
                            other.type_name(),
                        ))
                    }
                }
            }
            Ok(Value::Float(sum))
        }
        "count" => Ok(Value::Int(results.len() as i64)),
        "first" | "last" => {
            let pick = if strategy == "first" {
                results.first()
            } else {
                results.last()
            };
            // An empty list has no first or last element: that is a failure,
            // not a Null answer.
            pick.cloned().ok_or_else(|| {
                crate::safety::bad_arg(
                    "aggregate_results",
                    &format!("a non-empty results array for strategy \"{strategy}\""),
                    "an empty array",
                )
            })
        }
        other => Err(crate::safety::bad_arg(
            "aggregate_results",
            "strategy: one of concat, sum, count, first, last",
            other,
        )),
    }
}

// ===================== Advanced AI Builtins =====================

/// rag_index(content, source?, metadata?) - Index a document for RAG
fn bi_rag_index(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // The index lives for the whole process and every document is kept, so
    // both the size of one document and the number held are bounded.
    const MAX_DOC_BYTES: usize = 1 << 20;
    const MAX_DOCS: usize = 10_000;

    // Piped, the content is the input and `args` are source and metadata.
    // Unpiped, `args` are content, source and metadata. Reading source from
    // `args[1]` either way dropped a piped source without a word.
    let (content_in, rest): (Option<Value>, &[Value]) = match input {
        Some(v) => (Some(v), &args[..]),
        None => (args.first().cloned(), args.get(1..).unwrap_or(&[])),
    };
    if rest.len() > 2 {
        return Err(crate::safety::bad_arg(
            "rag_index",
            "at most 3 arguments: content, source, metadata",
            &format!("{} arguments", args.len()),
        ));
    }
    let content = match content_in {
        Some(Value::Str(s)) if s.len() <= MAX_DOC_BYTES => s,
        Some(Value::Str(s)) => {
            return Err(crate::safety::budget_exceeded(
                "rag_index",
                format!("content is {} bytes; the limit is {MAX_DOC_BYTES}", s.len()),
                "index a smaller document or split it",
            ))
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "rag_index",
                "content: a string",
                other.type_name(),
            ))
        }
        None => return Err(crate::safety::arg_err("rag_index: requires content")),
    };

    let source = match rest.first() {
        None | Some(Value::Null) => "unknown".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "rag_index",
                "source: a string",
                other.type_name(),
            ))
        }
    };

    let metadata: HashMap<String, String> = match rest.get(1) {
        None | Some(Value::Null) => HashMap::new(),
        Some(Value::Record(rec)) => rec
            .iter()
            .map(|(k, v)| (k.clone(), v.to_display_string()))
            .collect(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "rag_index",
                "metadata: a Record",
                other.type_name(),
            ))
        }
    };

    let mut index = RAG_INDEX
        .write()
        .map_err(|_| crate::safety::lock_poisoned("rag_index", "the RAG index"))?;
    if index.chunks.len() >= MAX_DOCS {
        return Err(crate::safety::budget_exceeded(
            "rag_index",
            format!("the index already holds {MAX_DOCS} documents"),
            "the index is process-local and has no removal; start a new process",
        ));
    }

    let doc_id = index.add_document(&content, &source, metadata);

    let mut record = BTreeMap::new();
    record.insert("doc_id".to_string(), Value::Str(doc_id));
    record.insert("source".to_string(), Value::Str(source));
    record.insert("chunk_count".to_string(), Value::Int(1));
    record.insert(
        "total_docs".to_string(),
        Value::Int(index.chunks.len() as i64),
    );

    Ok(Value::Record(record))
}

/// Most chunks rag_search returns, and most rag_query gathers into its context.
const RAG_SEARCH_MAX_TOP_K: usize = 100;
const RAG_QUERY_MAX_TOP_K: usize = 20;

/// The query and `top_k` of a rag call. Piped, the query is the input and
/// `args` holds only `top_k`; called directly, `args` is `query, top_k`. The
/// old code read `top_k` from `args[1]` either way, so a piped count was
/// ignored. `top_k` must be an integer from 1 up to `ceiling`: a negative
/// count used to wrap through `as usize`, and anything else fell back to the
/// default without a word.
fn rag_query_top_k(
    builtin: &str,
    args: &[Value],
    input: Option<Value>,
    default: usize,
    ceiling: usize,
) -> Result<(String, usize)> {
    let (query_v, rest): (Value, &[Value]) = match input {
        Some(v) => (v, args),
        None => match args.split_first() {
            Some((first, rest)) => (first.clone(), rest),
            None => return Err(crate::safety::arg_err(format!("{builtin}: requires query"))),
        },
    };
    if rest.len() > 1 {
        return Err(crate::safety::bad_arg(
            builtin,
            "at most 2 arguments when called directly (query, top_k); 1 when piped (top_k)",
            &format!("{} arguments", args.len()),
        ));
    }
    let query = key_arg(builtin, query_v)?;
    let top_k = match rest.first() {
        None | Some(Value::Null) => default,
        Some(Value::Int(n)) if *n < 1 => {
            return Err(crate::safety::bad_arg(
                builtin,
                "top_k: an integer from 1 up",
                &n.to_string(),
            ))
        }
        Some(Value::Int(n)) if *n as u128 > ceiling as u128 => {
            return Err(crate::safety::budget_exceeded(
                builtin,
                format!("top_k {n} is above the limit {ceiling}"),
                "ask for fewer chunks",
            ))
        }
        Some(Value::Int(n)) => *n as usize,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "top_k: an integer",
                other.type_name(),
            ))
        }
    };
    Ok((query, top_k))
}

/// rag_search(query, top_k?) - Search indexed documents
fn bi_rag_search(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (query, top_k) = rag_query_top_k("rag_search", &args, input, 5, RAG_SEARCH_MAX_TOP_K)?;

    let index = RAG_INDEX
        .read()
        .map_err(|_| crate::safety::lock_poisoned("rag_search", "the RAG index"))?;

    let results = index.search(&query, top_k);

    let result_values: Vec<Value> = results
        .iter()
        .map(|(chunk, score)| {
            let mut record = BTreeMap::new();
            record.insert("doc_id".to_string(), Value::Str(chunk.id.clone()));
            record.insert("content".to_string(), Value::Str(chunk.content.clone()));
            record.insert("source".to_string(), Value::Str(chunk.source.clone()));
            record.insert("score".to_string(), Value::Float(*score as f64));
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(result_values))
}

/// rag_query(query, top_k?) - Search and generate a response using RAG
fn bi_rag_query(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (query, top_k) = rag_query_top_k("rag_query", &args, input, 3, RAG_QUERY_MAX_TOP_K)?;

    let index = RAG_INDEX
        .read()
        .map_err(|_| crate::safety::lock_poisoned("rag_query", "the RAG index"))?;

    let results = index.search(&query, top_k);

    // Build context from retrieved documents
    let context: String = results
        .iter()
        .map(|(chunk, _)| chunk.content.as_str())
        .collect::<Vec<_>>()
        .join("\n\n");

    let mut record = BTreeMap::new();
    record.insert("query".to_string(), Value::Str(query));
    record.insert("context".to_string(), Value::Str(context));
    record.insert(
        "sources".to_string(),
        Value::Array(
            results
                .iter()
                .map(|(chunk, _)| Value::Str(chunk.source.clone()))
                .collect(),
        ),
    );
    record.insert("doc_count".to_string(), Value::Int(results.len() as i64));

    Ok(Value::Record(record))
}

/// rag_clear() - Clear the RAG index
fn bi_rag_clear(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut index = RAG_INDEX
        .write()
        .map_err(|_| crate::safety::lock_poisoned("rag_clear", "the RAG index"))?;

    let count = index.chunks.len();
    index.clear();

    Ok(Value::Int(count as i64))
}

/// The optional properties record of a `kg_*` call: absent or null is empty,
/// a Record is taken, and anything else is refused rather than dropped.
fn kg_properties(builtin: &str, v: Option<&Value>) -> Result<HashMap<String, String>> {
    match v {
        None | Some(Value::Null) => Ok(HashMap::new()),
        Some(Value::Record(rec)) => Ok(rec
            .iter()
            .map(|(k, v)| (k.clone(), v.to_display_string()))
            .collect()),
        Some(other) => Err(crate::safety::bad_arg(
            builtin,
            "properties: a Record",
            other.type_name(),
        )),
    }
}

/// kg_add(type, name, properties?) - Add an entity to the knowledge graph
fn bi_kg_add(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const MAX_ENTITIES: usize = 100_000;
    if args.len() > 3 {
        return Err(crate::safety::bad_arg(
            "kg_add",
            "at most 3 arguments: type, name, properties",
            &format!("{} arguments", args.len()),
        ));
    }
    // Only a Record is documented as piped input; anything else was dropped.
    if matches!(&input, Some(v) if !matches!(v, Value::Record(_))) {
        return Err(crate::safety::bad_arg(
            "kg_add",
            "piped input: a Record {type, name, properties?}",
            input.as_ref().map_or("nothing", |v| v.type_name()),
        ));
    }
    let (entity_type, name) = if let Some(Value::Record(rec)) = input {
        let entity_type = rec
            .get("type")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("kg_add: missing 'type'"))?;
        let name = rec
            .get("name")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("kg_add: missing 'name'"))?;
        (entity_type, name)
    } else if args.len() >= 2 {
        (args[0].to_display_string(), args[1].to_display_string())
    } else {
        return Err(crate::safety::arg_err("kg_add: requires type and name"));
    };

    let properties = kg_properties("kg_add", args.get(2))?;

    let mut kg = KNOWLEDGE_GRAPH
        .write()
        .map_err(|_| crate::safety::lock_poisoned("kg_add", "the knowledge graph"))?;
    if kg.entities.len() >= MAX_ENTITIES {
        return Err(crate::safety::budget_exceeded(
            "kg_add",
            format!("the knowledge graph already holds {MAX_ENTITIES} entities"),
            "the graph is process-local and has no removal; start a new process",
        ));
    }

    let entity_id = kg.add_entity(&entity_type, &name, properties);

    let mut record = BTreeMap::new();
    record.insert("entity_id".to_string(), Value::Str(entity_id));
    record.insert("type".to_string(), Value::Str(entity_type));
    record.insert("name".to_string(), Value::Str(name));

    Ok(Value::Record(record))
}

/// kg_relate(source_id, target_id, relation_type, properties?) - Add a relation
fn bi_kg_relate(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.len() > 4 {
        return Err(crate::safety::bad_arg(
            "kg_relate",
            "at most 4 arguments: source, target, relation, properties",
            &format!("{} arguments", args.len()),
        ));
    }
    if matches!(&input, Some(v) if !matches!(v, Value::Record(_))) {
        return Err(crate::safety::bad_arg(
            "kg_relate",
            "piped input: a Record {source, target, relation, properties?}",
            input.as_ref().map_or("nothing", |v| v.type_name()),
        ));
    }
    let (source_id, target_id, relation_type) = if let Some(Value::Record(rec)) = input {
        let source = rec
            .get("source")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("kg_relate: missing 'source'"))?;
        let target = rec
            .get("target")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("kg_relate: missing 'target'"))?;
        let rel_type = rec
            .get("relation")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("kg_relate: missing 'relation'"))?;
        (source, target, rel_type)
    } else if args.len() >= 3 {
        (
            args[0].to_display_string(),
            args[1].to_display_string(),
            args[2].to_display_string(),
        )
    } else {
        return Err(crate::safety::arg_err(
            "kg_relate: requires source_id, target_id, and relation_type",
        ));
    };

    let properties = kg_properties("kg_relate", args.get(3))?;

    let mut kg = KNOWLEDGE_GRAPH
        .write()
        .map_err(|_| crate::safety::lock_poisoned("kg_relate", "the knowledge graph"))?;

    let relation_id = kg.add_relation(&source_id, &target_id, &relation_type, properties)?;

    let mut record = BTreeMap::new();
    record.insert("relation_id".to_string(), Value::Str(relation_id));
    record.insert("source".to_string(), Value::Str(source_id));
    record.insert("target".to_string(), Value::Str(target_id));
    record.insert("relation_type".to_string(), Value::Str(relation_type));

    Ok(Value::Record(record))
}

/// kg_query(pattern) - Query the knowledge graph
fn bi_kg_query(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let pattern = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("kg_query", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("kg_query: requires pattern"))?;

    let kg = KNOWLEDGE_GRAPH
        .read()
        .map_err(|_| crate::safety::lock_poisoned("kg_query", "the knowledge graph"))?;

    let results = kg.query(&pattern);
    Ok(Value::Array(results))
}

/// kg_entities() - List all entities in the knowledge graph
fn bi_kg_entities(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let kg = KNOWLEDGE_GRAPH
        .read()
        .map_err(|_| crate::safety::lock_poisoned("kg_entities", "the knowledge graph"))?;

    let entities: Vec<Value> = kg
        .entities
        .values()
        .map(|entity| {
            let mut record = BTreeMap::new();
            record.insert("id".to_string(), Value::Str(entity.id.clone()));
            record.insert("type".to_string(), Value::Str(entity.entity_type.clone()));
            record.insert("name".to_string(), Value::Str(entity.name.clone()));
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(entities))
}

/// kg_relations() - List all relations in the knowledge graph
fn bi_kg_relations(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let kg = KNOWLEDGE_GRAPH
        .read()
        .map_err(|_| crate::safety::lock_poisoned("kg_relations", "the knowledge graph"))?;

    let relations: Vec<Value> = kg
        .relations
        .iter()
        .map(|rel| {
            let mut record = BTreeMap::new();
            record.insert("id".to_string(), Value::Str(rel.id.clone()));
            record.insert("source".to_string(), Value::Str(rel.source_id.clone()));
            record.insert("target".to_string(), Value::Str(rel.target_id.clone()));
            record.insert("type".to_string(), Value::Str(rel.relation_type.clone()));
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(relations))
}

/// semantic_cache(query, response) - Store a response in the semantic cache
fn bi_semantic_cache(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const MAX_QUERY_BYTES: usize = 4096;
    const MAX_RESPONSE_BYTES: usize = 256 * 1024;
    if args.len() > 2 {
        return Err(crate::safety::bad_arg(
            "semantic_cache",
            "at most 2 arguments: query, response",
            &format!("{} arguments", args.len()),
        ));
    }
    if matches!(&input, Some(v) if !matches!(v, Value::Record(_))) {
        return Err(crate::safety::bad_arg(
            "semantic_cache",
            "piped input: a Record {query, response}",
            input.as_ref().map_or("nothing", |v| v.type_name()),
        ));
    }
    let (query, response) = if let Some(Value::Record(rec)) = input {
        let query = rec
            .get("query")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("semantic_cache: missing 'query'"))?;
        let response = rec
            .get("response")
            .map(|v| v.to_display_string())
            .ok_or_else(|| crate::safety::arg_err("semantic_cache: missing 'response'"))?;
        (query, response)
    } else if args.len() >= 2 {
        (args[0].to_display_string(), args[1].to_display_string())
    } else {
        return Err(crate::safety::arg_err(
            "semantic_cache: requires query and response",
        ));
    };
    if query.is_empty() || query.len() > MAX_QUERY_BYTES {
        return Err(crate::safety::bad_arg(
            "semantic_cache",
            &format!("a query of 1 to {MAX_QUERY_BYTES} bytes"),
            &format!("{} bytes", query.len()),
        ));
    }
    if response.len() > MAX_RESPONSE_BYTES {
        return Err(crate::safety::budget_exceeded(
            "semantic_cache",
            format!(
                "response is {} bytes; the limit is {MAX_RESPONSE_BYTES}",
                response.len()
            ),
            "cache a shorter response",
        ));
    }

    let mut cache = SEMANTIC_CACHE
        .write()
        .map_err(|_| crate::safety::lock_poisoned("semantic_cache", "the semantic cache"))?;

    cache.put(&query, &response);

    let (entries, hits) = cache.stats();
    let mut record = BTreeMap::new();
    record.insert("cached".to_string(), Value::Bool(true));
    record.insert("total_entries".to_string(), Value::Int(entries as i64));
    record.insert("total_hits".to_string(), Value::Int(hits as i64));

    Ok(Value::Record(record))
}

/// semantic_cache_get(query) - Try to get a cached response
fn bi_semantic_cache_get(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let query = input
        .or_else(|| args.first().cloned())
        .map(|v| key_arg("semantic_cache_get", v))
        .transpose()?
        .ok_or_else(|| crate::safety::arg_err("semantic_cache_get: requires query"))?;

    let mut cache = SEMANTIC_CACHE
        .write()
        .map_err(|_| crate::safety::lock_poisoned("semantic_cache_get", "the semantic cache"))?;

    if let Some(response) = cache.get(&query) {
        let mut record = BTreeMap::new();
        record.insert("hit".to_string(), Value::Bool(true));
        record.insert("response".to_string(), Value::Str(response));
        Ok(Value::Record(record))
    } else {
        let mut record = BTreeMap::new();
        record.insert("hit".to_string(), Value::Bool(false));
        Ok(Value::Record(record))
    }
}

/// semantic_cache_clear() - Clear the semantic cache
fn bi_semantic_cache_clear(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut cache = SEMANTIC_CACHE
        .write()
        .map_err(|_| crate::safety::lock_poisoned("semantic_cache_clear", "the semantic cache"))?;

    let (count, _) = cache.stats();
    cache.clear();

    Ok(Value::Int(count as i64))
}

// --------------- AI / Agents wrappers (optional) ---------------

/// The most steps one agent or swarm run may take. Each step can be a model
/// call, so an unbounded `max_steps` is an unbounded bill.
const MAX_AGENT_STEPS: i64 = 1000;

/// The keys an agent or swarm config record may carry. Any other key is
/// refused: the body used to ignore it, so a caller who set `model_uri` got a
/// run on whatever model the environment picked, with no error.
const AGENT_CONFIG_KEYS: &[&str] = &["goal", "tools", "max_steps", "dry_run"];

/// One agent or swarm call, with every argument checked before anything runs.
struct AgentCall {
    goal: String,
    tools: Vec<String>,
    max_steps: usize,
    dry_run: bool,
}

/// Read the arguments of `agent(...)` or `swarm(...)` in each of their forms:
///
/// - a config record, as the argument or as the piped input;
/// - `goal, [tools...], [max_steps], [dry_run]`, with the tools as Strings or
///   as one Array of them;
/// - `goal, json`, where `json` is a JSON object whose keys are the config.
///
/// Every argument is either used or refused. A surplus argument, or one of the
/// wrong type, used to be dropped and the run went ahead without it. Nothing
/// here calls a model, so a refusal costs no rate-limit budget and no tokens.
fn parse_agent_call(
    builtin: &str,
    args: &[Value],
    input: Option<&Value>,
    default_steps: usize,
) -> Result<AgentCall> {
    if let Some(piped) = input {
        return match piped {
            Value::Record(cfg) if args.is_empty() => {
                agent_config(builtin, cfg.clone(), default_steps)
            }
            Value::Record(_) => Err(crate::safety::arg_err(format!(
                "{builtin}: a piped config takes no other arguments"
            ))),
            other => Err(crate::safety::arg_err(format!(
                "{builtin}: piped input must be a config record, got {}",
                other.type_name()
            ))),
        };
    }
    let goal_raw = match args.first() {
        Some(Value::Record(cfg)) => {
            if args.len() > 1 {
                return Err(surplus_arg(builtin, &args[1]));
            }
            return agent_config(builtin, cfg.clone(), default_steps);
        }
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "a goal String, or a config Record",
                other.type_name(),
            ))
        }
        None => return Err(crate::safety::bad_arg(builtin, "a goal String", "nothing")),
    };

    // A JSON object as the second argument is a whole config; the goal is the
    // first argument.
    if let Some(Value::Str(s)) = args.get(1) {
        let text = s.trim();
        if text.starts_with('{') {
            let json: serde_json::Value = serde_json::from_str(text).map_err(|e| {
                crate::safety::arg_err(format!("{builtin}: config JSON does not parse: {e}"))
            })?;
            let mut cfg = match Value::from_json(&json) {
                Value::Record(cfg) => cfg,
                _ => {
                    return Err(crate::safety::arg_err(format!(
                        "{builtin}: config JSON must be an object"
                    )))
                }
            };
            cfg.insert("goal".into(), Value::Str(goal_raw));
            // Positional max_steps and dry_run may follow, as the form
            // `goal, json, [max_steps], [dry_run]` documents; they override the config.
            let mut j = 2usize;
            if let Some(Value::Int(n)) = args.get(j) {
                cfg.insert("max_steps".into(), Value::Int(*n));
                j += 1;
            }
            if let Some(Value::Bool(b)) = args.get(j) {
                cfg.insert("dry_run".into(), Value::Bool(*b));
                j += 1;
            }
            if let Some(extra) = args.get(j) {
                return Err(surplus_arg(builtin, extra));
            }
            return agent_config(builtin, cfg, default_steps);
        }
    }

    let goal =
        validate_ai_prompt(&goal_raw).context(format!("{builtin}: goal validation failed"))?;
    let mut i = 1usize;
    let mut tools: Vec<String> = Vec::new();
    while let Some(Value::Str(name)) = args.get(i) {
        tools.push(name.clone());
        i += 1;
    }
    if tools.is_empty() {
        if let Some(Value::Array(items)) = args.get(i) {
            tools = agent_strings(builtin, items, "tools array must contain strings")?;
            i += 1;
        }
    }
    let mut max_steps = default_steps;
    if let Some(Value::Int(n)) = args.get(i) {
        max_steps = steps_arg(builtin, *n)?;
        i += 1;
    }
    let mut dry_run = false;
    if let Some(Value::Bool(b)) = args.get(i) {
        dry_run = *b;
        i += 1;
    }
    if let Some(extra) = args.get(i) {
        return Err(surplus_arg(builtin, extra));
    }
    check_tools(builtin, &tools)?;
    Ok(AgentCall {
        goal,
        tools,
        max_steps,
        dry_run,
    })
}

/// Read a config record: `goal` is required; `tools`, `max_steps` and `dry_run`
/// are optional and each is type-checked rather than defaulted when wrong.
fn agent_config(
    builtin: &str,
    cfg: BTreeMap<String, Value>,
    default_steps: usize,
) -> Result<AgentCall> {
    if let Some(key) = cfg
        .keys()
        .find(|k| !AGENT_CONFIG_KEYS.contains(&k.as_str()))
    {
        return Err(crate::safety::arg_err(format!(
            "{builtin} config has no key '{key}'; its keys are goal, tools, max_steps, dry_run"
        )));
    }
    let goal_raw = match cfg.get("goal") {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(format!(
                "{builtin} config requires {{goal: String}}"
            )))
        }
    };
    let goal =
        validate_ai_prompt(&goal_raw).context(format!("{builtin}: goal validation failed"))?;
    let tools = match cfg.get("tools") {
        None => Vec::new(),
        Some(Value::Array(items)) => {
            agent_strings(builtin, items, "config tools must be an array of strings")?
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "tools: Array of String",
                other.type_name(),
            ))
        }
    };
    let max_steps = match cfg.get("max_steps") {
        None => default_steps,
        Some(Value::Int(n)) => steps_arg(builtin, *n)?,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "max_steps: Int",
                other.type_name(),
            ))
        }
    };
    let dry_run = match cfg.get("dry_run") {
        None => false,
        Some(Value::Bool(b)) => *b,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "dry_run: Bool",
                other.type_name(),
            ))
        }
    };
    check_tools(builtin, &tools)?;
    Ok(AgentCall {
        goal,
        tools,
        max_steps,
        dry_run,
    })
}

fn agent_strings(builtin: &str, items: &[Value], message: &str) -> Result<Vec<String>> {
    items
        .iter()
        .map(|v| match v {
            Value::Str(s) => Ok(s.clone()),
            _ => Err(crate::safety::arg_err(format!("{builtin}: {message}"))),
        })
        .collect()
}

fn steps_arg(builtin: &str, n: i64) -> Result<usize> {
    if (1..=MAX_AGENT_STEPS).contains(&n) {
        Ok(n as usize)
    } else {
        Err(crate::safety::bad_arg(
            builtin,
            &format!("max_steps: Int in 1..={MAX_AGENT_STEPS}"),
            &n.to_string(),
        ))
    }
}

/// Refuse a tool name no builtin answers to. The agent would otherwise learn
/// this only when the model asked for that tool, after the model had run.
fn check_tools(builtin: &str, tools: &[String]) -> Result<()> {
    for tool in tools {
        if !crate::builtins::is_dispatched(tool) {
            return Err(crate::safety::not_found(builtin, "tool", tool));
        }
    }
    Ok(())
}

fn surplus_arg(builtin: &str, extra: &Value) -> anyhow::Error {
    crate::safety::arg_err(format!(
        "{builtin}: unexpected {} argument; the form is goal, [tools...], [max_steps], [dry_run]",
        extra.type_name()
    ))
}

/// Refuse a piped value for a builtin that takes none, so it is never dropped
/// without a word.
fn refuse_pipeline_input(builtin: &str, input: &Option<Value>) -> Result<()> {
    if input.is_some() {
        return Err(crate::safety::arg_err(format!(
            "{builtin} takes no pipeline input"
        )));
    }
    Ok(())
}

fn bi_agent(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let call = parse_agent_call("agent", &args, input.as_ref(), 8)?;
    // SECURITY: Rate limit agent calls (CVSS 7.8). This runs after the
    // arguments are read, so a refused call does not spend the budget.
    check_rate_limit("bi_agent", 10, Duration::from_secs(60))
        .context("Agent rate limit exceeded")?;
    let tools: Vec<&str> = call.tools.iter().map(String::as_str).collect();
    let out = crate::ai::agents::run_sync(&call.goal, &tools, call.max_steps, call.dry_run, env)?;
    Ok(Value::Str(out))
}

fn bi_swarm(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let call = parse_agent_call("swarm", &args, input.as_ref(), 12)?;
    let tools: Vec<&str> = call.tools.iter().map(String::as_str).collect();
    let out =
        crate::ai::agents::swarm::run_sync(&call.goal, &tools, call.max_steps, call.dry_run, env)?;
    Ok(Value::Str(out))
}

// --------------- File system commands ---------------

fn bi_ls(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path_str = if args.is_empty() {
        ".".to_string()
    } else {
        match &args[0] {
            Value::Str(s) => s.clone(),
            other => {
                return Err(crate::safety::bad_arg(
                    "ls",
                    "path: String",
                    other.type_name(),
                ))
            }
        }
    };

    // `ls("src/*.rs")` lists the matches themselves, as `ls src/*.rs` does.
    let paths: Vec<std::path::PathBuf> =
        if crate::posix::has_glob_meta(&path_str) && !std::path::Path::new(&path_str).exists() {
            expand_glob_for("ls", &path_str)?
                .into_iter()
                .map(std::path::PathBuf::from)
                .collect()
        } else {
            if !std::path::Path::new(&path_str).exists() {
                return Err(crate::safety::not_found("ls", "directory", &path_str));
            }
            // SECURITY: Validate path to prevent traversal attacks (CVSS 8.2)
            let validated_path = validate_read_path(&path_str)?;
            fs::read_dir(&validated_path)
                .map_err(|e| crate::safety::fs_error("ls", &validated_path, &e))?
                .map(|e| e.map(|e| e.path()))
                .collect::<std::io::Result<Vec<_>>>()
                .map_err(|e| crate::safety::fs_error("ls", &validated_path, &e))?
        };
    let mut files = Vec::new();

    for path in paths {
        // A dangling symlink is listed as itself, as ls(1) lists it; it used to
        // fail the whole directory with E_NOT_FOUND.
        let metadata = fs::metadata(&path)
            .or_else(|e| match fs::symlink_metadata(&path) {
                Ok(link) if link.file_type().is_symlink() => Ok(link),
                _ => Err(e),
            })
            .map_err(|e| crate::safety::fs_error("ls", &path, &e))?;
        let name = path
            .file_name()
            .ok_or_else(|| crate::safety::arg_err("ls: invalid filename"))?
            .to_string_lossy()
            .to_string();

        // Extract file extension
        let ext = path
            .extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_default();

        let mut record = BTreeMap::new();
        record.insert("name".to_string(), Value::Str(name));
        record.insert(
            "path".to_string(),
            Value::Str(path.to_string_lossy().to_string()),
        );
        record.insert("ext".to_string(), Value::Str(ext));
        record.insert("is_dir".to_string(), Value::Bool(metadata.is_dir()));
        record.insert("size".to_string(), Value::Int(metadata.len() as i64));

        if let Ok(modified) = metadata.modified() {
            if let Ok(duration) = modified.duration_since(std::time::UNIX_EPOCH) {
                record.insert(
                    "modified".to_string(),
                    Value::Int(duration.as_secs() as i64),
                );
            }
        }

        files.push(Value::Record(record));
    }

    Ok(Value::Array(files))
}

fn bi_pwd() -> Result<Value> {
    let current_dir = std::env::current_dir()?;
    Ok(Value::Str(current_dir.to_string_lossy().to_string()))
}

fn bi_cat(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if let Some(input) = input {
        return Ok(input);
    }

    if args.is_empty() {
        return Err(crate::safety::arg_err("cat: no file specified"));
    }

    let path_str = match &args[0] {
        Value::Str(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "cat",
                "path: String",
                other.type_name(),
            ))
        }
    };

    // A glob reads every match, in order, as `cat src/*.rs` does -- unless a
    // file with that literal name exists.
    if crate::posix::has_glob_meta(path_str) && !std::path::Path::new(path_str).exists() {
        let paths = expand_glob_for("cat", path_str)?;
        let files: Vec<&String> = paths
            .iter()
            .filter(|p| std::path::Path::new(p).is_file())
            .collect();
        if files.is_empty() {
            return Err(crate::safety::not_found("cat", "file matching", path_str));
        }
        let mut all = String::new();
        for p in files {
            all.push_str(&cat_one(p)?);
        }
        return Ok(Value::Str(all));
    }
    Ok(Value::Str(cat_one(path_str)?))
}

fn cat_one(path_str: &str) -> Result<String> {
    // A missing parent directory made validate_read_path fail with an uncoded
    // "Failed to canonicalize parent directory".
    if !std::path::Path::new(path_str).exists() {
        return Err(crate::safety::not_found("cat", "file", path_str));
    }
    // SECURITY: Validate path to prevent traversal attacks (CVSS 8.2)
    let validated_path = validate_read_path(path_str)?;

    // SECURITY FIX (MED-001): Check file size before reading
    let metadata = fs::metadata(&validated_path)
        .map_err(|e| crate::safety::fs_error("cat", &validated_path, &e))?;
    check_file_size_limit(metadata.len()).context("cat: file too large")?;

    fs::read_to_string(&validated_path)
        .map_err(|e| crate::safety::fs_error("cat", &validated_path, &e))
}

fn bi_read_text(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("read_text: no file specified"));
    }

    let path_str = match &args[0] {
        Value::Str(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "read_text",
                "path: String",
                other.type_name(),
            ))
        }
    };

    // SECURITY: Validate path to prevent traversal attacks
    let validated_path = validate_read_path(path_str)?;

    // SECURITY FIX (MED-001): Check file size before reading
    let metadata = fs::metadata(&validated_path)
        .map_err(|e| crate::safety::fs_error("read_text", &validated_path, &e))?;
    check_file_size_limit(metadata.len()).context("read_text: file too large")?;

    let content = fs::read_to_string(&validated_path)
        .map_err(|e| crate::safety::fs_error("read_text", &validated_path, &e))?;

    Ok(Value::Str(content))
}

fn bi_head(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (count, content) = match input {
        Some(Value::Str(content)) => (args.first().map(|v| line_count("head", v)).transpose()?.unwrap_or(10), content),
        Some(_) => return Err(crate::safety::arg_err("head piped input must be String")),
        None => match args.as_slice() {
            [Value::Str(path)] => (10, line_read("head", path)?),
            [Value::Str(path), count] => (line_count("head", count)?, line_read("head", path)?),
            [count, Value::Str(path)] => (line_count("head", count)?, line_read("head", path)?),
            _ => return Err(crate::safety::arg_err("head requires a file path and optional count, or count then path, or a piped String")),
        },
    };
    Ok(Value::Str(
        content.lines().take(count).collect::<Vec<_>>().join("\n"),
    ))
}

fn line_count(builtin: &str, value: &Value) -> Result<usize> {
    let Value::Int(n) = value else {
        return Err(crate::safety::arg_err(format!(
            "{builtin} count must be a nonnegative Int"
        )));
    };
    usize::try_from(*n).map_err(|_| {
        crate::safety::arg_err(format!(
            "{builtin} count must be a nonnegative representable Int"
        ))
    })
}

/// Read a whole text file a caller named, up to the resource limit
/// (`max_file_size_mb`, 100 MiB by default). A larger file is
/// E_BUDGET_EXCEEDED, not an allocation the size of the file. The limit is
/// enforced on the bytes read, not only on the size the metadata reports, so a
/// file that grows, or a device or pipe that reports 0, is held to it too.
/// Path validation stays with the caller.
fn read_text_capped(builtin: &str, path: impl AsRef<std::path::Path>) -> Result<String> {
    read_text_capped_at(
        builtin,
        path.as_ref(),
        crate::security::max_file_size_bytes()?,
    )
}

fn read_text_capped_at(builtin: &str, path: &std::path::Path, max: u64) -> Result<String> {
    let bytes = read_bytes_capped_at(builtin, path, max)?;
    // The error `read_to_string` gave for bytes that are not UTF-8, unchanged.
    String::from_utf8(bytes).map_err(|_| {
        crate::safety::fs_error(
            builtin,
            path,
            &std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "stream did not contain valid UTF-8",
            ),
        )
    })
}

/// Read a whole binary file a caller named, up to the resource limit, as
/// `read_text_capped` does for text. Path validation stays with the caller.
fn read_bytes_capped(builtin: &str, path: impl AsRef<std::path::Path>) -> Result<Vec<u8>> {
    read_bytes_capped_at(
        builtin,
        path.as_ref(),
        crate::security::max_file_size_bytes()?,
    )
}

fn read_bytes_capped_at(builtin: &str, path: &std::path::Path, max: u64) -> Result<Vec<u8>> {
    use std::io::Read;
    let over = || {
        crate::safety::budget_exceeded(
            builtin,
            format!(
                "{builtin}: `{}` is larger than {} MiB",
                path.display(),
                max / (1024 * 1024)
            ),
            "read a part of the file (head, tail, line_read) or raise max_file_size_mb",
        )
    };
    let file = fs::File::open(path).map_err(|e| crate::safety::fs_error(builtin, path, &e))?;
    if file.metadata().is_ok_and(|m| m.len() > max) {
        return Err(over());
    }
    let mut bytes = Vec::new();
    file.take(max.saturating_add(1))
        .read_to_end(&mut bytes)
        .map_err(|e| crate::safety::fs_error(builtin, path, &e))?;
    if bytes.len() as u64 > max {
        return Err(over());
    }
    Ok(bytes)
}

/// Whether a capped read failed because the path does not exist. The capped
/// readers report I/O errors as `SafetyError`s, so the `io::ErrorKind` is gone.
fn capped_read_not_found(e: &anyhow::Error) -> bool {
    e.downcast_ref::<crate::safety::SafetyError>()
        .is_some_and(|s| s.code == crate::safety::ErrorCode::NotFound)
}

fn line_read(builtin: &str, path: &str) -> Result<String> {
    use std::io::Read;
    const MAX_BYTES: u64 = 64 * 1024 * 1024;
    let path = validate_read_path(path)?;
    let metadata = fs::metadata(&path).map_err(|e| crate::safety::fs_error(builtin, &path, &e))?;
    if metadata.len() > MAX_BYTES {
        return Err(crate::safety::budget_exceeded(
            builtin,
            "file exceeds 64 MiB".into(),
            "use a smaller file",
        ));
    }
    if !metadata.is_file() {
        return Err(crate::safety::arg_err(format!(
            "{builtin} requires a regular UTF-8 file"
        )));
    }
    let file = fs::File::open(&path).map_err(|e| crate::safety::fs_error(builtin, &path, &e))?;
    let mut content = String::new();
    file.take(MAX_BYTES + 1)
        .read_to_string(&mut content)
        .map_err(|e| crate::safety::fs_error(builtin, &path, &e))?;
    if content.len() as u64 > MAX_BYTES {
        return Err(crate::safety::budget_exceeded(
            builtin,
            "file exceeds 64 MiB".into(),
            "use a smaller file",
        ));
    }
    Ok(content)
}

fn bi_tail(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (count, content) = if let Some(value) = input {
        let Value::Str(content) = value else {
            return Err(crate::safety::arg_err("tail piped input must be String"));
        };
        let count = match args.first() {
            None => 10,
            Some(value) => line_count("tail", value)?,
        };
        (count, content)
    } else {
        match args.as_slice() {
            [Value::Str(path)] => (10,line_read("tail", path)?),
            [Value::Str(path),count] => (line_count("tail", count)?,line_read("tail", path)?),
            [count,Value::Str(path)] => (line_count("tail", count)?,line_read("tail", path)?),
            _=>return Err(crate::safety::arg_err("tail requires a file path and optional count, or count then path, or a piped String")),
        }
    };
    let mut lines: Vec<_> = content.lines().rev().take(count).collect();
    lines.reverse();
    Ok(Value::Str(lines.join("\n")))
}

/// The most entries one directory walk may return. A walk over `/` or `C:\`
/// could otherwise build an array of every file on the disk before anyone saw
/// it. Past this the walk is refused with E_BUDGET_EXCEEDED, not cut short: a
/// shorter listing presented as the whole is the silent wrong answer.
pub(crate) const WALK_MAX_ENTRIES: usize = 1_000_000;

/// The refusal for a walk that would return more than `max` entries.
fn walk_over(builtin: &str, max: usize) -> anyhow::Error {
    crate::safety::budget_exceeded(
        builtin,
        format!("more than {max} entries; the listing would be partial, so nothing was returned"),
        "narrow the root, or filter with a pattern or depth",
    )
}

/// Refuses when a walk that already holds `len` entries cannot take one more
/// without exceeding `max`.
fn check_walk_room(builtin: &str, len: usize, max: usize) -> Result<()> {
    if len >= max {
        return Err(walk_over(builtin, max));
    }
    Ok(())
}

/// Adds `v` to a walk's output, or refuses once the output is at the cap.
fn push_capped(builtin: &str, out: &mut Vec<Value>, v: Value, max: usize) -> Result<()> {
    check_walk_room(builtin, out.len(), max)?;
    out.push(v);
    Ok(())
}

fn bi_find(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let (path_str, pattern) = if args.len() >= 2 {
        match (&args[0], &args[1]) {
            (Value::Str(p), Value::Str(pat)) => (p.clone(), Some(pat.clone())),
            _ => {
                return Err(crate::safety::arg_err(
                    "find: path and pattern must be strings",
                ))
            }
        }
    } else if args.len() == 1 {
        match &args[0] {
            Value::Str(p) => (p.clone(), None),
            other => {
                return Err(crate::safety::bad_arg(
                    "find",
                    "path: String",
                    other.type_name(),
                ))
            }
        }
    } else {
        (".".to_string(), None)
    };

    // SECURITY: Validate path to prevent traversal attacks (CVSS 8.2)
    let validated_path = validate_read_path(&path_str)?;

    let mut results = Vec::new();

    // A walk error used to be dropped, so an unreadable directory vanished
    // from the listing and the rest was returned as the whole answer.
    for entry in WalkDir::new(&validated_path) {
        let entry = match entry {
            Ok(entry) => entry,
            Err(e) => {
                return Err(match e.io_error() {
                    Some(io) => crate::safety::fs_error(
                        "find",
                        e.path().unwrap_or(validated_path.as_path()),
                        io,
                    ),
                    None => crate::safety::bad_state(
                        "find",
                        &e.to_string(),
                        "a tree without symbolic-link loops",
                    ),
                });
            }
        };
        let path_str = entry.path().to_string_lossy().to_string();

        if let Some(ref pattern) = pattern {
            // Simple glob matching: support * for any characters
            let filename = entry.file_name().to_string_lossy();
            if shell_glob(
                &pattern.chars().collect::<Vec<_>>(),
                &filename.chars().collect::<Vec<_>>(),
            ) {
                push_capped("find", &mut results, Value::Str(path_str), WALK_MAX_ENTRIES)?;
            }
        } else {
            push_capped("find", &mut results, Value::Str(path_str), WALK_MAX_ENTRIES)?;
        }
    }

    Ok(Value::Array(results))
}

// `find`'s patterns go through `shell_glob`. This used a matcher that knew
// four forms -- `*`, `*.ext`, `prefix*` and an exact name -- and treated
// anything else as an exact name, so `find("a*b.rs")`, `find("?.rs")` and
// `find("[ab].rs")` silently found nothing. `shell_glob` is a strict superset
// of those four, so no pattern that worked before behaves differently.

fn bi_sort(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let reverse = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-r" || s == "--reverse"));

    let array = if let Some(input) = input {
        match input {
            Value::Array(arr) => arr,
            Value::Str(s) => {
                let lines: Vec<Value> =
                    s.lines().map(|line| Value::Str(line.to_string())).collect();
                lines
            }
            _ => {
                return Err(crate::safety::arg_err(
                    "sort: input must be an array or string",
                ))
            }
        }
    } else {
        return Err(crate::safety::bad_arg(
            "sort",
            "a piped Array or String",
            "a direct call with no subject",
        ));
    };

    let mut sorted = array;
    sorted.sort_by(|a, b| {
        let cmp = match (a, b) {
            (Value::Str(s1), Value::Str(s2)) => s1.cmp(s2),
            (Value::Int(i1), Value::Int(i2)) => i1.cmp(i2),
            (Value::Float(f1), Value::Float(f2)) => {
                f1.partial_cmp(f2).unwrap_or(std::cmp::Ordering::Equal)
            }
            _ => std::cmp::Ordering::Equal,
        };
        if reverse {
            cmp.reverse()
        } else {
            cmp
        }
    });

    Ok(Value::Array(sorted))
}

fn bi_uniq(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let _count = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-c" || s == "--count"));

    let array = if let Some(input) = input {
        match input {
            Value::Array(arr) => arr,
            Value::Str(s) => {
                let lines: Vec<Value> =
                    s.lines().map(|line| Value::Str(line.to_string())).collect();
                lines
            }
            _ => {
                return Err(crate::safety::arg_err(
                    "uniq: input must be an array or string",
                ))
            }
        }
    } else {
        return Err(crate::safety::bad_arg(
            "uniq",
            "a piped Array or String",
            "a direct call with no subject",
        ));
    };

    let mut unique = Vec::new();
    let mut last: Option<&Value> = None;

    for item in &array {
        if last != Some(item) {
            unique.push(item.clone());
            last = Some(item);
        }
    }

    Ok(Value::Array(unique))
}

fn bi_wc(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let lines_only = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-l" || s == "--lines"));
    let words_only = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-w" || s == "--words"));
    let chars_only = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-c" || s == "--chars"));

    let content_came_from_pipe = input.is_some();
    let content = if let Some(input) = input {
        match input {
            Value::Str(s) => s,
            other => {
                return Err(crate::safety::bad_arg(
                    "wc",
                    "input: String",
                    other.type_name(),
                ))
            }
        }
    } else if !args.is_empty() {
        let path = match &args[0] {
            Value::Str(s) if !s.starts_with('-') => s,
            other => {
                return Err(crate::safety::bad_arg(
                    "wc",
                    "a piped String, or a file path as the first argument",
                    other.type_name(),
                ))
            }
        };
        read_text_capped("wc", path)?
    } else {
        return Err(crate::safety::bad_arg(
            "wc",
            "a piped String",
            "a direct call with no subject",
        ));
    };
    // An unknown flag ("-x", "--bogus") was ignored and every count returned.
    let flags = if content_came_from_pipe {
        &args[..]
    } else {
        &args[1..]
    };
    for f in flags {
        if !matches!(f, Value::Str(s) if matches!(s.as_str(), "-l" | "--lines" | "-w" | "--words" | "-c" | "--chars"))
        {
            return Err(crate::safety::bad_arg(
                "wc",
                "a flag -l, -w or -c",
                &f.to_display_string(),
            ));
        }
    }

    let line_count = content.lines().count();
    let word_count = content.split_whitespace().count();
    let char_count = content.chars().count();

    let mut result = BTreeMap::new();

    if lines_only {
        result.insert("lines".to_string(), Value::Int(line_count as i64));
    } else if words_only {
        result.insert("words".to_string(), Value::Int(word_count as i64));
    } else if chars_only {
        result.insert("chars".to_string(), Value::Int(char_count as i64));
    } else {
        result.insert("lines".to_string(), Value::Int(line_count as i64));
        result.insert("words".to_string(), Value::Int(word_count as i64));
        result.insert("chars".to_string(), Value::Int(char_count as i64));
    }

    Ok(Value::Record(result))
}

fn bi_grep(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("grep: pattern required"));
    }

    let pattern = match &args[0] {
        Value::Str(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "grep",
                "pattern: String",
                other.type_name(),
            ))
        }
    };

    let case_insensitive = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-i" || s == "--ignore-case"));
    let invert = args
        .iter()
        .any(|arg| matches!(arg, Value::Str(s) if s == "-v" || s == "--invert-match"));

    let content = if let Some(input) = input {
        match input {
            Value::Str(s) => s,
            Value::Array(arr) => {
                let lines: Vec<String> = arr
                    .iter()
                    .filter_map(|v| {
                        if let Value::Str(s) = v {
                            Some(s.clone())
                        } else {
                            None
                        }
                    })
                    .collect();
                lines.join("\n")
            }
            _ => {
                return Err(crate::safety::arg_err(
                    "grep: input must be a string or array",
                ))
            }
        }
    } else if args.len() > 1 {
        let path = match &args[1] {
            Value::Str(s) if !s.starts_with('-') => s,
            _ => {
                return Err(crate::safety::bad_arg(
                    "grep",
                    "a piped String, or a file path as the second argument",
                    "nothing",
                ))
            }
        };
        read_text_capped("grep", path)?
    } else {
        return Err(crate::safety::bad_arg(
            "grep",
            "a piped String, or a file path as the second argument",
            "a direct call with no subject",
        ));
    };

    // The declaration always said "text or regex"; the body only ever did a
    // substring search, so `grep("^version", "Cargo.toml")` answered [] --
    // an empty result for a pattern every grep user writes. The pattern is
    // now what grep takes: a POSIX basic regular expression.
    let re = crate::posix::bre_to_regex(pattern)
        .and_then(|r| {
            regex::RegexBuilder::new(&r)
                .case_insensitive(case_insensitive)
                .build()
                .ok()
        })
        .ok_or_else(|| {
            crate::safety::bad_arg(
                "grep",
                "a basic regular expression (back-references are not supported)",
                pattern,
            )
        })?;
    let matching_lines: Vec<Value> = content
        .lines()
        .filter(|line| re.is_match(line) != invert)
        .map(|line| Value::Str(line.to_string()))
        .collect();

    Ok(Value::Array(matching_lines))
}

// --------------- Formatting helpers ---------------

fn format_value_one_line(v: &Value) -> String {
    // keep this consistent with your pretty module; simplified for echo
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => b.to_string(),
        Value::Int(n) => n.to_string(),
        Value::Float(x) => x.to_string(),
        Value::Str(s) => s.clone(),
        Value::Uri(s) => s.clone(),
        Value::Array(a) => format!("[len={}]", a.len()),
        Value::Record(_) => "{…}".into(),
        Value::Table(t) => format!("<Table rows={}>", t.rows.len()),
        Value::Lambda(_) => "<lambda>".into(),
        Value::AsyncLambda(_) => "<async lambda>".into(),
        Value::Future(_) => "<future>".into(),
        Value::Builtin(b) => format!("<builtin:{}>", b.name),
        Value::Error(msg) => format!("Error: {}", msg),
    }
}

// Helper function to convert Value to string representation
fn value_to_string(value: &Value) -> String {
    match value {
        Value::Str(s) => s.clone(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => f.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Uri(s) => s.clone(),
        Value::Array(a) => format!("[len={}]", a.len()),
        Value::Record(_) => "{…}".into(),
        Value::Table(t) => format!("<Table rows={}>", t.rows.len()),
        Value::Lambda(_) => "<lambda>".into(),
        Value::AsyncLambda(_) => "<async lambda>".into(),
        Value::Future(_) => "<future>".into(),
        Value::Null => "<null>".into(),
        Value::Error(msg) => format!("Error: {}", msg),
        Value::Builtin(b) => format!("<builtin:{}>", b.name),
    }
}

// =============== PowerShell-style Parameter Binding ===============

/// PowerShell-style parameter binding result
// =============== PowerShell-style Cmdlets ===============

/// Get-Files: PowerShell-style file listing.
///
/// Grammar: at most one path, given positionally or as -Path / -p; -Recurse /
/// -r; and -Filter / -f with a substring of the name. The path comes from the
/// pipe or from the arguments, never both. Anything outside that grammar is
/// refused before the filesystem is read.
fn bi_get_files(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "Get-Files";
    let mut path_arg: Option<String> = None;
    let mut recurse = false;
    let mut filter: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let Value::Str(token) = &args[i] else {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: arguments must be strings, got {}",
                args[i].type_name()
            )));
        };
        match token.as_str() {
            "-Recurse" | "-r" => {
                recurse = true;
                i += 1;
            }
            "-Path" | "-p" | "-Filter" | "-f" => {
                let Some(Value::Str(value)) = args.get(i + 1) else {
                    return Err(crate::safety::arg_err(format!(
                        "{NAME}: {token} needs a string value"
                    )));
                };
                let slot = if matches!(token.as_str(), "-Path" | "-p") {
                    &mut path_arg
                } else {
                    &mut filter
                };
                if slot.is_some() {
                    return Err(crate::safety::arg_err(format!(
                        "{NAME}: {token} is given more than once"
                    )));
                }
                *slot = Some(value.clone());
                i += 2;
            }
            other if other.starts_with('-') => {
                return Err(crate::safety::arg_err(format!(
                    "{NAME}: unknown parameter {other}"
                )));
            }
            _ => {
                if path_arg.is_some() {
                    return Err(crate::safety::arg_err(format!(
                        "{NAME}: the path is given more than once"
                    )));
                }
                path_arg = Some(token.clone());
                i += 1;
            }
        }
    }

    let path = match (input, path_arg) {
        (None, None) => ".".to_string(),
        (None, Some(path)) => path,
        (Some(Value::Str(piped)), None) => piped,
        (Some(other), None) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: pipeline input must be a path string, got {}",
                other.type_name()
            )))
        }
        (Some(_), Some(_)) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: the path is both piped and given as an argument; give it once"
            )))
        }
    };

    let mut files = Vec::new();
    if recurse {
        for entry in WalkDir::new(&path).min_depth(1) {
            let entry = entry.map_err(|e| walk_failure(&path, e))?;
            let metadata = entry.metadata().map_err(|e| walk_failure(&path, e))?;
            let name = entry.file_name().to_string_lossy().to_string();
            if filter.as_ref().is_some_and(|p| !name.contains(p.as_str())) {
                continue;
            }
            let full = entry.path().to_string_lossy().to_string();
            push_capped(
                NAME,
                &mut files,
                file_record(name, full, &metadata),
                WALK_MAX_ENTRIES,
            )?;
        }
    } else {
        let listing =
            fs::read_dir(&path).map_err(|e| crate::safety::fs_error("get_files", &path, &e))?;
        for entry in listing {
            let entry = entry.map_err(|e| crate::safety::fs_error("get_files", &path, &e))?;
            let metadata = entry
                .metadata()
                .map_err(|e| crate::safety::fs_error("get_files", entry.path(), &e))?;
            let name = entry.file_name().to_string_lossy().to_string();
            if filter.as_ref().is_some_and(|p| !name.contains(p.as_str())) {
                continue;
            }
            let full = entry.path().to_string_lossy().to_string();
            push_capped(
                NAME,
                &mut files,
                file_record(name, full, &metadata),
                WALK_MAX_ENTRIES,
            )?;
        }
    }

    Ok(Value::Array(files))
}

fn file_record(name: String, full_name: String, metadata: &fs::Metadata) -> Value {
    let mut file_obj = BTreeMap::new();
    file_obj.insert("Name".to_string(), Value::Str(name));
    file_obj.insert("FullName".to_string(), Value::Str(full_name));
    file_obj.insert("IsDirectory".to_string(), Value::Bool(metadata.is_dir()));
    file_obj.insert("Length".to_string(), Value::Int(metadata.len() as i64));
    if let Ok(modified) = metadata.modified() {
        if let Ok(duration) = modified.duration_since(std::time::UNIX_EPOCH) {
            file_obj.insert(
                "LastWriteTime".to_string(),
                Value::Int(duration.as_secs() as i64),
            );
        }
    }
    Value::Record(file_obj)
}

/// A walk that cannot read an entry is a failure, not a shorter listing.
fn walk_failure(path: &str, e: walkdir::Error) -> anyhow::Error {
    match e.io_error() {
        Some(io) => crate::safety::fs_error("get_files", path, io),
        None => crate::safety::bad_state(
            "Get-Files",
            &format!("{path}: {e}"),
            "a tree without symbolic-link loops",
        ),
    }
}

/// Get-Content: PowerShell-style file content reading, one element per line.
///
/// The path comes from the pipe or from a single argument, never both.
fn bi_get_content(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "Get-Content";
    if args.len() > 1 {
        return Err(crate::safety::arg_err(format!(
            "{NAME}: takes one path, got {} arguments",
            args.len()
        )));
    }
    let path = match (input, args.into_iter().next()) {
        (None, None) => return Err(crate::safety::arg_err(format!("{NAME}: no path provided"))),
        (None, Some(Value::Str(path))) | (Some(Value::Str(path)), None) => path,
        (None, Some(other)) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: path must be a string, got {}",
                other.type_name()
            )))
        }
        (Some(other), None) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: pipeline input must be a path string, got {}",
                other.type_name()
            )))
        }
        (Some(_), Some(_)) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: the path is both piped and given as an argument; give it once"
            )))
        }
    };

    let content = read_text_capped("get_content", &path)?;

    // Return as array of lines (PowerShell style)
    let lines: Vec<Value> = content
        .lines()
        .map(|line| Value::Str(line.to_string()))
        .collect();

    Ok(Value::Array(lines))
}

/// Select-Object: PowerShell-style property selection.
///
/// Each argument names a property to keep on every piped record. A piped item
/// that is not a record is refused, not passed through unchanged.
fn bi_select_object(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "Select-Object";
    let input =
        input.ok_or_else(|| crate::safety::arg_err("Select-Object: requires pipeline input"))?;

    if args.is_empty() {
        return Ok(input);
    }
    if let Some(bad) = args.iter().find(|a| !matches!(a, Value::Str(_))) {
        return Err(crate::safety::arg_err(format!(
            "{NAME}: property names must be strings, got {}",
            bad.type_name()
        )));
    }

    match input {
        Value::Array(arr) => {
            let mut results = Vec::with_capacity(arr.len());
            for item in &arr {
                results.push(select_properties(item, &args)?);
            }
            Ok(Value::Array(results))
        }
        other => select_properties(&other, &args),
    }
}

fn select_properties(value: &Value, properties: &[Value]) -> Result<Value> {
    let Value::Record(record) = value else {
        return Err(crate::safety::bad_arg(
            "Select-Object",
            "a record to select properties from",
            value.type_name(),
        ));
    };
    let mut selected = BTreeMap::new();
    for prop in properties {
        if let Value::Str(prop_name) = prop {
            if let Some(val) = record.get(prop_name) {
                selected.insert(prop_name.clone(), val.clone());
            }
        }
    }
    Ok(Value::Record(selected))
}

/// Where-Object: PowerShell-style filtering.
///
/// Two forms: `where-object(fn(element) => Bool)`, or
/// `where-object(property, operator, value)`. Both need a piped array.
/// The cmdlet name in `Where-Object` messages, kept out of the format strings
/// because tests/no_raw_shell_interpolation.rs reads a cmdlet name inside a
/// `format!` as a PowerShell command being built.
const WHERE_OBJECT: &str = "Where-Object";

fn bi_where_object(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    const NAME: &str = "Where-Object";
    let input =
        input.ok_or_else(|| crate::safety::arg_err("Where-Object: requires pipeline input"))?;

    match args.first() {
        None => Err(crate::safety::arg_err(
            "Where-Object: requires filter condition",
        )),
        // Lambda filtering: the existing where logic.
        Some(Value::Lambda(_)) => {
            if args.len() != 1 {
                return Err(crate::safety::arg_err(format!(
                    "{NAME}: a lambda filter takes one argument, got {}",
                    args.len()
                )));
            }
            bi_where(args.clone(), Some(input), env)
        }
        // PowerShell-style property filtering: where Status -eq "Running"
        Some(Value::Str(property)) => {
            if args.len() != 3 {
                return Err(crate::safety::arg_err(format!(
                    "{NAME}: property filtering takes a property, an operator and a value, got {} arguments",
                    args.len()
                )));
            }
            filter_by_property(&input, property, &args[1], &args[2])
        }
        Some(other) => Err(crate::safety::arg_err(format!(
            "{NAME}: the filter must be a lambda or a property name, got {}",
            other.type_name()
        ))),
    }
}

fn filter_by_property(
    input: &Value,
    property: &str,
    operator: &Value,
    target: &Value,
) -> Result<Value> {
    let op_str = match operator {
        Value::Str(s) => s.as_str(),
        other => {
            return Err(crate::safety::arg_err(format!(
                "{WHERE_OBJECT}: operator must be a string, got {}",
                other.type_name()
            )))
        }
    };

    // Checked before any element is read: a bad operator is refused even when
    // the array is empty or no element carries the property.
    match op_str {
        "-eq" | "==" | "-ne" | "!=" => {}
        "-like" => {
            if !matches!(target, Value::Str(_)) {
                return Err(crate::safety::arg_err(format!(
                    "{WHERE_OBJECT}: -like needs a string value, got {}",
                    target.type_name()
                )));
            }
        }
        "-gt" | ">" | "-lt" | "<" | "-ge" | ">=" | "-le" | "<=" => {
            if !matches!(target, Value::Int(_) | Value::Float(_) | Value::Str(_)) {
                return Err(crate::safety::arg_err(format!(
                    "{WHERE_OBJECT}: {op_str} needs a number or a string value, got {}",
                    target.type_name()
                )));
            }
        }
        other => {
            return Err(crate::safety::bad_arg(
                "Where-Object",
                "an operator: -eq -ne -gt -lt -ge -le -like",
                other,
            ))
        }
    }

    let Value::Array(items) = input else {
        return Err(crate::safety::bad_arg(
            "Where-Object",
            "an array as the piped subject",
            input.type_name(),
        ));
    };

    let mut results = Vec::new();
    for item in items {
        let Value::Record(record) = item else {
            continue;
        };
        let Some(value) = record.get(property) else {
            continue;
        };
        let matches = match op_str {
            "-eq" | "==" => value == target,
            "-ne" | "!=" => value != target,
            "-gt" | ">" => compare_values(value, target, std::cmp::Ordering::Greater),
            "-lt" | "<" => compare_values(value, target, std::cmp::Ordering::Less),
            "-ge" | ">=" => {
                compare_values(value, target, std::cmp::Ordering::Greater) || value == target
            }
            "-le" | "<=" => {
                compare_values(value, target, std::cmp::Ordering::Less) || value == target
            }
            // "-like" is the only operator left, and its target is a string.
            _ => {
                matches!((value, target), (Value::Str(v), Value::Str(t)) if v.contains(t.as_str()))
            }
        };
        if matches {
            results.push(item.clone());
        }
    }
    Ok(Value::Array(results))
}

fn compare_values(a: &Value, b: &Value, expected: std::cmp::Ordering) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y) == expected,
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y) == Some(expected),
        (Value::Int(x), Value::Float(y)) => (*x as f64).partial_cmp(y) == Some(expected),
        (Value::Float(x), Value::Int(y)) => x.partial_cmp(&(*y as f64)) == Some(expected),
        (Value::Str(x), Value::Str(y)) => x.cmp(y) == expected,
        _ => false,
    }
}

/// ForEach-Object: PowerShell-style iteration
fn bi_foreach_object(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    // This is essentially the same as map, but with PowerShell naming
    bi_map(args, input, env)
}

/// Sort-Object: PowerShell-style sorting, by value or by one property.
fn bi_sort_object(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "Sort-Object";
    let input =
        input.ok_or_else(|| crate::safety::arg_err("Sort-Object: requires pipeline input"))?;

    if args.len() > 1 {
        return Err(crate::safety::arg_err(format!(
            "{NAME}: sorts by one property, got {} arguments",
            args.len()
        )));
    }
    let property = match args.first() {
        None => None,
        Some(Value::Str(property)) => Some(property.as_str()),
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: property name must be a string, got {}",
                other.type_name()
            )))
        }
    };

    let mut arr = match input {
        Value::Array(arr) => arr,
        other => {
            return Err(crate::safety::bad_arg(
                NAME,
                "an array as the piped subject",
                other.type_name(),
            ))
        }
    };

    match property {
        None => arr.sort_by(compare_values_for_sort),
        Some(property) => {
            if let Some(other) = arr.iter().find(|v| !matches!(v, Value::Record(_))) {
                return Err(crate::safety::bad_arg(
                    NAME,
                    "records when sorting by a property",
                    other.type_name(),
                ));
            }
            arr.sort_by(|a, b| {
                compare_values_for_sort(
                    &get_property_value(a, property),
                    &get_property_value(b, property),
                )
            });
        }
    }
    Ok(Value::Array(arr))
}

fn get_property_value(value: &Value, property: &str) -> Value {
    match value {
        Value::Record(record) => record
            .get(property)
            .cloned()
            .unwrap_or(Value::Str("".to_string())),
        _ => value.clone(),
    }
}

fn compare_values_for_sort(a: &Value, b: &Value) -> std::cmp::Ordering {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal),
        (Value::Int(x), Value::Float(y)) => (*x as f64)
            .partial_cmp(y)
            .unwrap_or(std::cmp::Ordering::Equal),
        (Value::Float(x), Value::Int(y)) => x
            .partial_cmp(&(*y as f64))
            .unwrap_or(std::cmp::Ordering::Equal),
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        _ => std::cmp::Ordering::Equal,
    }
}

/// Group-Object: PowerShell-style grouping
fn bi_group_object(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let input =
        input.ok_or_else(|| crate::safety::arg_err("Group-Object: requires pipeline input"))?;

    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "Group-Object: requires property name",
        ));
    }

    let property = match &args[0] {
        Value::Str(s) => s,
        _ => {
            return Err(crate::safety::arg_err(
                "Group-Object: property name must be a string",
            ))
        }
    };

    match input {
        Value::Array(arr) => {
            let mut groups = BTreeMap::new();

            for item in arr {
                let key = get_property_value(&item, property);
                let key_str = value_to_string(&key);
                groups.entry(key_str).or_insert_with(Vec::new).push(item);
            }

            let mut result = Vec::new();
            for (key, items) in groups {
                let mut group = BTreeMap::new();
                group.insert("Name".to_string(), Value::Str(key));
                group.insert("Count".to_string(), Value::Int(items.len() as i64));
                group.insert("Group".to_string(), Value::Array(items));
                result.push(Value::Record(group));
            }

            Ok(Value::Array(result))
        }
        _ => Err(crate::safety::arg_err(
            "Group-Object: input must be an array",
        )),
    }
}

/// Measure-Object: PowerShell-style count and, for one property, its statistics.
///
/// A piped array is measured element by element; any other piped value counts
/// as a single element. Statistics come from the numeric values of the property.
fn bi_measure_object(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "Measure-Object";
    let input =
        input.ok_or_else(|| crate::safety::arg_err("Measure-Object: requires pipeline input"))?;

    if args.len() > 1 {
        return Err(crate::safety::arg_err(format!(
            "{NAME}: takes one property name, got {} arguments",
            args.len()
        )));
    }
    let property = match args.first() {
        None => None,
        Some(Value::Str(property)) => Some(property.as_str()),
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "{NAME}: property name must be a string, got {}",
                other.type_name()
            )))
        }
    };

    let items = match input {
        Value::Array(arr) => arr,
        other => vec![other],
    };

    let mut result = BTreeMap::new();
    result.insert("Count".to_string(), Value::Int(items.len() as i64));

    if let Some(property) = property {
        let values: Vec<f64> = items
            .iter()
            .filter_map(|item| match item {
                Value::Record(record) => match record.get(property) {
                    Some(Value::Int(i)) => Some(*i as f64),
                    Some(Value::Float(f)) => Some(*f),
                    _ => None,
                },
                _ => None,
            })
            .collect();

        if !values.is_empty() {
            let sum: f64 = values.iter().sum();
            let avg = sum / values.len() as f64;
            let min = values.iter().fold(f64::INFINITY, |a, &b| a.min(b));
            let max = values.iter().fold(f64::NEG_INFINITY, |a, &b| a.max(b));

            result.insert("Sum".to_string(), Value::Float(sum));
            result.insert("Average".to_string(), Value::Float(avg));
            result.insert("Minimum".to_string(), Value::Float(min));
            result.insert("Maximum".to_string(), Value::Float(max));
        }
    }

    Ok(Value::Record(result))
}

// =============== Nushell-style Data Commands ===============

/// from-json: Parse JSON into structured data
fn bi_from_json(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let json_str = if let Some(input) = input {
        match input {
            Value::Str(s) => s,
            _ => {
                return Err(crate::safety::arg_err(
                    "from-json: input must be a JSON string",
                ))
            }
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => {
                return Err(crate::safety::arg_err(
                    "from-json: argument must be a JSON string",
                ))
            }
        }
    } else {
        return Err(crate::safety::arg_err("from-json: no JSON input provided"));
    };

    // A bare `?` here surfaced serde's message as E_UNKNOWN with exit 1, the
    // one uncoded failure left in benches/agentic/errors.mjs (malformed-json).
    let parsed: serde_json::Value = serde_json::from_str(&json_str).map_err(|e| {
        // `from_json("issues.json")` -- the parser handed a path -- was every
        // AetherShell attempt a small model made in the local E7 run. It stays
        // an error (the text is not JSON), but the repair is mechanical, so
        // the hint names it.
        let path = json_str.trim();
        if !path.is_empty() && path.len() < 4096 && std::path::Path::new(path).is_file() {
            return anyhow::Error::new(crate::safety::SafetyError {
                code: crate::safety::ErrorCode::BadArg,
                message: format!("from_json: {path:?} is a file name, not JSON text"),
                builtin: "from_json".to_string(),
                hint: format!(
                    "read and parse the file with open({path:?}), or cat({path:?}) | from_json"
                ),
                approval: None,
                did_you_mean: vec![format!("open({path:?})")],
                expected: "JSON text".to_string(),
                got: "a file path".to_string(),
            });
        }
        crate::safety::bad_arg("from_json", "valid JSON", &e.to_string())
    })?;
    Ok(json_to_value(parsed))
}

/// to-json: Convert structured data to JSON
fn bi_to_json(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let value = input.ok_or_else(|| crate::safety::arg_err("to-json: requires pipeline input"))?;

    let pretty = args
        .first()
        .and_then(|arg| match arg {
            Value::Bool(b) => Some(*b),
            Value::Str(s) => Some(s == "pretty" || s == "true"),
            _ => None,
        })
        .unwrap_or(false);

    let json_val = value_to_json(value);
    let json_str = if pretty {
        serde_json::to_string_pretty(&json_val)?
    } else {
        serde_json::to_string(&json_val)?
    };

    Ok(Value::Str(json_str))
}

/// Format bytes into a human-readable string (e.g. "1.5G", "100M", "4.0K")
fn format_bytes(bytes: i64) -> String {
    let abs = bytes.unsigned_abs();
    if abs >= 1_073_741_824 {
        format!("{:.1}G", bytes as f64 / 1_073_741_824.0)
    } else if abs >= 1_048_576 {
        format!("{:.1}M", bytes as f64 / 1_048_576.0)
    } else if abs >= 1024 {
        format!("{:.1}K", bytes as f64 / 1024.0)
    } else {
        format!("{}B", bytes)
    }
}

fn json_to_value(json: serde_json::Value) -> Value {
    match json {
        // Was `Value::Str("null")`: every JSON null reached the value space as
        // a four-letter string. It printed identically, so nothing looked
        // wrong, but `typeof(from_json("null"))` said String, `x == null` never
        // matched a null field, and AECON tagged the column as ambiguous.
        serde_json::Value::Null => Value::Null,
        serde_json::Value::Bool(b) => Value::Bool(b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Int(i)
            } else if let Some(f) = n.as_f64() {
                Value::Float(f)
            } else {
                Value::Str(n.to_string())
            }
        }
        serde_json::Value::String(s) => Value::Str(s),
        serde_json::Value::Array(arr) => Value::Array(arr.into_iter().map(json_to_value).collect()),
        serde_json::Value::Object(obj) => {
            let mut map = BTreeMap::new();
            for (k, v) in obj {
                map.insert(k, json_to_value(v));
            }
            Value::Record(map)
        }
    }
}

fn value_to_json(value: Value) -> serde_json::Value {
    match value {
        Value::Str(s) => serde_json::Value::String(s),
        Value::Int(i) => serde_json::Value::Number(serde_json::Number::from(i)),
        Value::Float(f) => serde_json::Value::Number(
            serde_json::Number::from_f64(f).unwrap_or_else(|| serde_json::Number::from(0)),
        ),
        Value::Bool(b) => serde_json::Value::Bool(b),
        Value::Array(arr) => serde_json::Value::Array(arr.into_iter().map(value_to_json).collect()),
        Value::Record(map) => {
            let mut obj = serde_json::Map::new();
            for (k, v) in map {
                obj.insert(k, value_to_json(v));
            }
            serde_json::Value::Object(obj)
        }
        _ => serde_json::Value::String(value_to_string(&value)),
    }
}

/// from-csv: Parse CSV into structured data
fn bi_from_csv(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let csv_str = if let Some(input) = input {
        match input {
            Value::Str(s) => s,
            _ => {
                return Err(crate::safety::arg_err(
                    "from-csv: input must be a CSV string",
                ))
            }
        }
    } else {
        return Err(crate::safety::arg_err("from-csv: requires CSV input"));
    };

    let mut reader = csv::Reader::from_reader(csv_str.as_bytes());
    let headers: Vec<String> = reader.headers()?.iter().map(|h| h.to_string()).collect();

    let mut results = Vec::new();
    for record in reader.records() {
        let record = record?;
        let mut row = BTreeMap::new();

        for (i, field) in record.iter().enumerate() {
            if let Some(header) = headers.get(i) {
                // Try to parse as number, otherwise keep as string
                let value = if let Ok(int_val) = field.parse::<i64>() {
                    Value::Int(int_val)
                } else if let Ok(float_val) = field.parse::<f64>() {
                    Value::Float(float_val)
                } else if let Ok(bool_val) = field.parse::<bool>() {
                    Value::Bool(bool_val)
                } else {
                    Value::Str(field.to_string())
                };
                row.insert(header.clone(), value);
            }
        }
        results.push(Value::Record(row));
    }

    Ok(Value::Array(results))
}

/// to-csv: Convert structured data to CSV
fn bi_to_csv(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let input = input.ok_or_else(|| crate::safety::arg_err("to-csv: requires pipeline input"))?;

    match input {
        Value::Array(arr) => {
            if arr.is_empty() {
                return Ok(Value::Str(String::new()));
            }

            // Get headers from first record
            let headers = if let Value::Record(first_record) = &arr[0] {
                first_record.keys().cloned().collect::<Vec<_>>()
            } else {
                return Err(crate::safety::arg_err(
                    "to-csv: input must be array of records",
                ));
            };

            let mut csv_output = String::new();

            // Write headers
            csv_output.push_str(&headers.join(","));
            csv_output.push('\n');

            // Write data rows
            for item in arr {
                if let Value::Record(record) = item {
                    let row: Vec<String> = headers
                        .iter()
                        .map(|header| {
                            record
                                .get(header)
                                .map(|v| csv_escape(&value_to_string(v)))
                                .unwrap_or_default()
                        })
                        .collect();
                    csv_output.push_str(&row.join(","));
                    csv_output.push('\n');
                }
            }

            Ok(Value::Str(csv_output))
        }
        _ => Err(crate::safety::arg_err(
            "to-csv: input must be an array of records",
        )),
    }
}

fn csv_escape(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

/// from-yaml: Parse YAML into structured data.
///
/// Delegates to [`crate::yaml`], which implements a documented subset (nested
/// mappings, sequences, quoting, comments, JSON-style flow collections) and
/// returns an error naming any construct outside it. It never silently
/// mis-parses — see that module for why that matters here.
fn bi_from_yaml(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Accepts either a pipeline value or a positional argument, matching
    // `from-json`'s contract.
    let yaml_str = match input {
        Some(Value::Str(s)) => s,
        Some(_) => {
            return Err(crate::safety::arg_err(
                "from-yaml: input must be a YAML string",
            ))
        }
        None => match args.first() {
            Some(Value::Str(s)) => s.clone(),
            Some(_) => {
                return Err(crate::safety::arg_err(
                    "from-yaml: argument must be a YAML string",
                ))
            }
            None => return Err(crate::safety::arg_err("from-yaml: requires YAML input")),
        },
    };
    crate::yaml::parse(&yaml_str).map_err(|e| crate::safety::arg_err(format!("from-yaml: {e}")))
}

/// to-yaml: Convert structured data to YAML.
///
/// Output is quoted wherever quoting is required, so the result parses back to
/// the same value.
fn bi_to_yaml(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let value = match input {
        Some(v) => v,
        None => args
            .into_iter()
            .next()
            .ok_or_else(|| crate::safety::arg_err("to-yaml: requires pipeline input"))?,
    };
    Ok(Value::Str(crate::yaml::emit(&value)))
}

/// columns: Get column names from structured data
fn bi_columns(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let input = input.ok_or_else(|| crate::safety::arg_err("columns: requires pipeline input"))?;

    match input {
        Value::Array(arr) => {
            if let Some(Value::Record(first)) = arr.first() {
                let columns: Vec<Value> = first.keys().map(|k| Value::Str(k.clone())).collect();
                Ok(Value::Array(columns))
            } else {
                Ok(Value::Array(Vec::new()))
            }
        }
        Value::Record(record) => {
            let columns: Vec<Value> = record.keys().map(|k| Value::Str(k.clone())).collect();
            Ok(Value::Array(columns))
        }
        _ => Ok(Value::Array(Vec::new())),
    }
}

/// describe: Get type and structure information about data
fn bi_describe(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let input = input.ok_or_else(|| crate::safety::arg_err("describe: requires pipeline input"))?;

    let mut description = BTreeMap::new();

    match &input {
        Value::Str(s) => {
            description.insert("type".to_string(), Value::Str("string".to_string()));
            description.insert("length".to_string(), Value::Int(s.len() as i64));
        }
        Value::Int(_) => {
            description.insert("type".to_string(), Value::Str("integer".to_string()));
        }
        Value::Float(_) => {
            description.insert("type".to_string(), Value::Str("float".to_string()));
        }
        Value::Bool(_) => {
            description.insert("type".to_string(), Value::Str("boolean".to_string()));
        }
        Value::Array(arr) => {
            description.insert("type".to_string(), Value::Str("array".to_string()));
            description.insert("length".to_string(), Value::Int(arr.len() as i64));

            if !arr.is_empty() {
                let first_type = match &arr[0] {
                    Value::Str(_) => "string",
                    Value::Int(_) => "integer",
                    Value::Float(_) => "float",
                    Value::Bool(_) => "boolean",
                    Value::Array(_) => "array",
                    Value::Record(_) => "record",
                    _ => "unknown",
                };
                description.insert(
                    "element_type".to_string(),
                    Value::Str(first_type.to_string()),
                );
            }
        }
        Value::Record(record) => {
            description.insert("type".to_string(), Value::Str("record".to_string()));
            description.insert("fields".to_string(), Value::Int(record.len() as i64));

            let field_names: Vec<Value> = record.keys().map(|k| Value::Str(k.clone())).collect();
            description.insert("field_names".to_string(), Value::Array(field_names));
        }
        _ => {
            description.insert("type".to_string(), Value::Str("unknown".to_string()));
        }
    }

    Ok(Value::Record(description))
}

// =============== AI-Enhanced Commands ===============

/// ai: Direct AI query with optional multi-modal support
/// Usage:
///   ai("prompt")                              - Simple text query
///   ai("prompt", {images: ["path1", "path2"]}) - With images
///   ai("prompt", {audio: ["path"]})           - With audio
///   ai("prompt", {video: ["path"]})           - With video
///   ai("prompt", {model: "openai:gpt-4o"})    - Specify model
fn bi_ai(args: Vec<Value>, input: Option<Value>, _env: &mut Env) -> Result<Value> {
    // SECURITY: Rate limit AI calls
    check_rate_limit("bi_ai", 30, Duration::from_secs(60)).context("AI rate limit exceeded")?;

    // Get prompt from input or first argument
    let prompt = if let Some(input) = input {
        match input {
            Value::Str(s) => s,
            _ => return Err(crate::safety::arg_err("ai: input must be a prompt string")),
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            other => {
                return Err(crate::safety::bad_arg(
                    "ai",
                    "prompt: String",
                    other.type_name(),
                ))
            }
        }
    } else {
        return Err(crate::safety::arg_err("ai: requires a prompt string"));
    };

    // SECURITY: Validate AI prompt for injection
    let validated_prompt = validate_ai_prompt(&prompt).context("ai: prompt validation failed")?;

    // Check for optional config record (second argument)
    let config = args.get(1).and_then(|v| {
        if let Value::Record(r) = v {
            Some(r.clone())
        } else {
            None
        }
    });

    // Extract multi-modal content if present
    let images = config
        .as_ref()
        .and_then(|c| extract_string_array(c, "images"));
    let audio = config
        .as_ref()
        .and_then(|c| extract_string_array(c, "audio"));
    let video = config
        .as_ref()
        .and_then(|c| extract_string_array(c, "video"));
    let _model = config.as_ref().and_then(|c| {
        c.get("model").and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
    });

    // Determine if this is a multi-modal request
    let has_media = images.is_some() || audio.is_some() || video.is_some();

    if has_media {
        // Multi-modal request
        let mut content_parts = vec![crate::ai::MultiModalContent {
            text: Some(validated_prompt),
            image_url: None,
            audio_url: None,
            video_url: None,
            image_data: None,
            audio_data: None,
            video_data: None,
        }];

        // Load and encode images
        if let Some(img_paths) = images {
            for path in img_paths {
                // SECURITY: Validate path
                let validated_path = validate_read_path(&path)
                    .context(format!("ai: invalid image path: {}", path))?;

                // Read and base64 encode the image
                let data = read_bytes_capped("ai", &validated_path).context(format!(
                    "ai: failed to read image: {}",
                    validated_path.display()
                ))?;

                use base64::{engine::general_purpose::STANDARD, Engine as _};
                let encoded = STANDARD.encode(&data);

                content_parts.push(crate::ai::MultiModalContent {
                    text: None,
                    image_url: None,
                    audio_url: None,
                    video_url: None,
                    image_data: Some(encoded),
                    audio_data: None,
                    video_data: None,
                });
            }
        }

        // Load and encode audio
        if let Some(audio_paths) = audio {
            for path in audio_paths {
                let validated_path = validate_read_path(&path)
                    .context(format!("ai: invalid audio path: {}", path))?;

                let data = read_bytes_capped("ai", &validated_path).context(format!(
                    "ai: failed to read audio: {}",
                    validated_path.display()
                ))?;

                use base64::{engine::general_purpose::STANDARD, Engine as _};
                let encoded = STANDARD.encode(&data);

                content_parts.push(crate::ai::MultiModalContent {
                    text: None,
                    image_url: None,
                    audio_url: None,
                    video_url: None,
                    image_data: None,
                    audio_data: Some(encoded),
                    video_data: None,
                });
            }
        }

        // Load and encode video
        if let Some(video_paths) = video {
            for path in video_paths {
                let validated_path = validate_read_path(&path)
                    .context(format!("ai: invalid video path: {}", path))?;

                let data = read_bytes_capped("ai", &validated_path).context(format!(
                    "ai: failed to read video: {}",
                    validated_path.display()
                ))?;

                use base64::{engine::general_purpose::STANDARD, Engine as _};
                let encoded = STANDARD.encode(&data);

                content_parts.push(crate::ai::MultiModalContent {
                    text: None,
                    image_url: None,
                    audio_url: None,
                    video_url: None,
                    image_data: None,
                    audio_data: None,
                    video_data: Some(encoded),
                });
            }
        }

        let message = crate::ai::MultiModalMessage {
            role: "user".to_string(),
            content: content_parts,
        };

        let response = crate::ai::complete_multimodal_sync(&[message])?;

        Ok(Value::Str(response))
    } else {
        // Simple text-only request
        let response = crate::ai::complete_sync_router(&validated_prompt)?;

        Ok(Value::Str(response))
    }
}

/// Helper to extract a string array from a record field
fn extract_string_array(record: &BTreeMap<String, Value>, key: &str) -> Option<Vec<String>> {
    record.get(key).and_then(|v| {
        if let Value::Array(arr) = v {
            let strings: Vec<String> = arr
                .iter()
                .filter_map(|item| {
                    if let Value::Str(s) = item {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .collect();
            if strings.is_empty() {
                None
            } else {
                Some(strings)
            }
        } else {
            None
        }
    })
}

// suggest / explain / complete / fix
//
// These were documented as "AI-powered". No model was consulted: each matched
// keywords against canned paragraphs, and the paragraphs told the caller to run
// `Get-Files`, `Get-Content`, `Where-Object`, `Sort-Object`, `from-json`,
// `describe` and `ai-suggest "..."` -- none of which this shell can call (the
// last parses as a subtraction). An agent following the advice failed again.
//
// They now answer from the shell's own catalogue: the dispatcher's names and
// the declared signatures, which the test suite executes. Nothing here claims
// intelligence it does not have.

/// The single string subject of these builtins: piped input or the first
/// argument.
fn hint_subject(builtin: &str, args: &[Value], input: Option<Value>) -> Result<String> {
    match input.or_else(|| args.first().cloned()) {
        Some(Value::Str(s)) if !s.trim().is_empty() => Ok(s),
        other => Err(crate::safety::bad_arg(
            builtin,
            "a non-empty String (argument or piped input)",
            other.as_ref().map(|v| v.type_name()).unwrap_or("nothing"),
        )),
    }
}

fn hint_signature_record(sig: &crate::signature::Signature) -> Value {
    let mut r = BTreeMap::new();
    r.insert("name".to_string(), Value::Str(sig.name.to_string()));
    r.insert("signature".to_string(), Value::Str(sig.render()));
    r.insert("doc".to_string(), Value::Str(sig.doc.to_string()));
    Value::Record(r)
}

/// suggest(query): declared builtins whose name or description contains every
/// word of the query, best (most words in the name) first; at most 10.
fn bi_ai_suggest(args: Vec<Value>, input: Option<Value>, _env: &mut Env) -> Result<Value> {
    let query = hint_subject("suggest", &args, input)?.to_lowercase();
    let words: Vec<&str> = query.split_whitespace().collect();
    let mut hits: Vec<(usize, &crate::signature::Signature)> = crate::signature::SIGNATURES
        .iter()
        .filter_map(|sig| {
            let name = sig.name.to_lowercase();
            let text = format!("{} {}", name, sig.doc.to_lowercase());
            words
                .iter()
                .all(|w| text.contains(w))
                .then(|| (words.iter().filter(|w| name.contains(*w)).count(), sig))
        })
        .collect();
    hits.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.name.cmp(b.1.name)));
    Ok(Value::Array(
        hits.into_iter()
            .take(10)
            .map(|(_, sig)| hint_signature_record(sig))
            .collect(),
    ))
}

/// explain(subject): a builtin's declared signature and description, or what
/// an error code in the subject means.
fn bi_ai_explain(args: Vec<Value>, input: Option<Value>, _env: &mut Env) -> Result<Value> {
    let subject = hint_subject("explain", &args, input)?;
    if let Some(sig) = crate::signature::signature_of(subject.trim()) {
        return Ok(hint_signature_record(sig));
    }
    if is_dispatched(subject.trim()) {
        let mut r = BTreeMap::new();
        r.insert("name".to_string(), Value::Str(subject.trim().to_string()));
        r.insert(
            "doc".to_string(),
            Value::Str(
                "a builtin with no declared signature yet; its arguments are not described"
                    .to_string(),
            ),
        );
        return Ok(Value::Record(r));
    }
    if subject.contains("E_") {
        return bi_diagnose(vec![hint_error_value(&subject)], None);
    }
    Err(crate::safety::not_found(
        "explain",
        "builtin or error code",
        subject.trim(),
    ))
}

/// complete(partial): builtin names that start with `partial`, sorted,
/// at most 20.
fn bi_ai_complete(args: Vec<Value>, input: Option<Value>, _env: &mut Env) -> Result<Value> {
    let partial = hint_subject("complete", &args, input)?;
    let mut names: Vec<&str> = BUILTIN_LOOKUP
        .keys()
        .copied()
        .chain(FALLBACK_BUILTINS.iter().map(|(n, _)| *n))
        .filter(|n| n.starts_with(partial.trim()))
        .collect();
    names.sort_unstable();
    names.dedup();
    Ok(Value::Array(
        names
            .into_iter()
            .take(20)
            .map(|n| Value::Str(n.to_string()))
            .collect(),
    ))
}

/// An error given as text: the JSON a coded error prints, or plain words.
fn hint_error_value(text: &str) -> Value {
    let t = text.trim();
    let json = t
        .find('{')
        .and_then(|i| serde_json::from_str::<serde_json::Value>(&t[i..]).ok());
    match json.map(json_to_value) {
        Some(Value::Record(r)) => match r.get("error") {
            Some(inner @ Value::Record(_)) => inner.clone(),
            _ => Value::Record(r),
        },
        _ => match t.find("E_") {
            // "error[E_BAD_ARG]: ..." as the CLI prints it
            Some(i) => {
                let code: String = t[i..]
                    .chars()
                    .take_while(|c| c.is_ascii_uppercase() || *c == '_')
                    .collect();
                let mut r = BTreeMap::new();
                r.insert("code".to_string(), Value::Str(code));
                r.insert("message".to_string(), Value::Str(t.to_string()));
                Value::Record(r)
            }
            None => Value::Str(t.to_string()),
        },
    }
}

/// fix(error): the minimal repair context for an error, as diagnose gives
/// for a caught error record, from the error's text.
fn bi_ai_fix(args: Vec<Value>, input: Option<Value>, _env: &mut Env) -> Result<Value> {
    let error = match input.or_else(|| args.first().cloned()) {
        Some(v @ Value::Record(_)) => v,
        Some(Value::Str(s)) if !s.trim().is_empty() => hint_error_value(&s),
        other => {
            return Err(crate::safety::bad_arg(
                "fix",
                "an error: the record a catch bound, or its text",
                other.as_ref().map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    bi_diagnose(vec![error], None)
}

// ============ Option Type Constructors ============

/// Some(value) - Creates an Option variant containing a value
/// Returns: Record with _tag="Some" and _value=<arg>
fn bi_some(args: Vec<Value>) -> Result<Value> {
    if args.len() != 1 {
        return Err(crate::safety::arg_err(format!(
            "Some expects exactly 1 argument, got {}",
            args.len()
        )));
    }

    let mut record = BTreeMap::new();
    record.insert("_tag".to_string(), Value::Str("Some".to_string()));
    record.insert("_value".to_string(), args[0].clone());

    Ok(Value::Record(record))
}

/// None - Creates an Option variant representing no value
/// Returns: Record with _tag="None"
fn bi_none() -> Result<Value> {
    let mut record = BTreeMap::new();
    record.insert("_tag".to_string(), Value::Str("None".to_string()));

    Ok(Value::Record(record))
}

/// The one string argument a builtin takes; anything else is refused by name.
fn sole_str(builtin: &str, args: &[Value], expected: &str) -> Result<String> {
    match args {
        [Value::Str(s)] => Ok(s.clone()),
        [other] => Err(crate::safety::bad_arg(builtin, expected, other.type_name())),
        _ => Err(crate::safety::bad_arg(
            builtin,
            expected,
            &format!("{} argument(s)", args.len()),
        )),
    }
}

/// The single config record a builtin takes. A table, a string or any other
/// value is refused, because a config that is silently ignored is not a config.
fn cfg_record<'a>(
    builtin: &str,
    args: &'a [Value],
    expected: &str,
) -> Result<&'a std::collections::BTreeMap<String, Value>> {
    match args {
        [Value::Record(r)] => Ok(r),
        [other] => Err(crate::safety::bad_arg(builtin, expected, other.type_name())),
        _ => Err(crate::safety::bad_arg(
            builtin,
            expected,
            &format!("{} argument(s)", args.len()),
        )),
    }
}

/// Refuse a config key the builtin does not read. A misspelt option is an
/// error; read as its default it would be a silently different call.
fn cfg_known_keys(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    known: &[&str],
) -> Result<()> {
    if let Some(key) = rec.keys().find(|k| !known.contains(&k.as_str())) {
        return Err(crate::safety::bad_arg(
            builtin,
            &format!("only the keys {}", known.join(", ")),
            &format!("unknown key '{key}'"),
        ));
    }
    Ok(())
}

fn cfg_str(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    field: &str,
) -> Result<Option<String>> {
    match rec.get(field) {
        None => Ok(None),
        Some(Value::Str(s)) => Ok(Some(s.clone())),
        Some(other) => Err(crate::safety::bad_arg(
            builtin,
            &format!("{field}: a string"),
            other.type_name(),
        )),
    }
}

fn cfg_required_str(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    field: &str,
) -> Result<String> {
    cfg_str(builtin, rec, field)?
        .ok_or_else(|| crate::safety::bad_arg(builtin, &format!("{field}: a string"), "missing"))
}

fn cfg_bool(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    field: &str,
) -> Result<Option<bool>> {
    match rec.get(field) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(other) => Err(crate::safety::bad_arg(
            builtin,
            &format!("{field}: a boolean"),
            other.type_name(),
        )),
    }
}

/// An integer field in `lo..=hi`. A value outside the range is refused, not
/// wrapped by an `as` cast.
fn cfg_int(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    field: &str,
    lo: i64,
    hi: i64,
) -> Result<Option<i64>> {
    match rec.get(field) {
        None => Ok(None),
        Some(Value::Int(n)) if (lo..=hi).contains(n) => Ok(Some(*n)),
        Some(Value::Int(n)) => Err(crate::safety::bad_arg(
            builtin,
            &format!("{field}: an integer in {lo}..={hi}"),
            &n.to_string(),
        )),
        Some(other) => Err(crate::safety::bad_arg(
            builtin,
            &format!("{field}: an integer"),
            other.type_name(),
        )),
    }
}

/// A numeric field (Int or Float) in `lo..=hi`, finite. Int is widened, never
/// dropped: the earlier code read only Float and silently ignored Int.
fn cfg_float(
    builtin: &str,
    rec: &std::collections::BTreeMap<String, Value>,
    field: &str,
    lo: f64,
    hi: f64,
) -> Result<Option<f64>> {
    let v = match rec.get(field) {
        None => return Ok(None),
        Some(Value::Float(f)) => *f,
        Some(Value::Int(n)) => *n as f64,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                &format!("{field}: a number"),
                other.type_name(),
            ))
        }
    };
    if v.is_finite() && v >= lo && v <= hi {
        Ok(Some(v))
    } else {
        Err(crate::safety::bad_arg(
            builtin,
            &format!("{field}: a number in {lo}..={hi}"),
            &v.to_string(),
        ))
    }
}

// ============ AI Backend Detection ============

/// ai_backends() - Detect and list all available AI backends
/// Returns: Array of records with backend information
///
/// Example:
///   ai_backends() | select(["name", "available", "models"])
fn bi_ai_backends(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("ai_backends", &args, &input)?;
    // A probe the budget or policy refuses is the answer, not an empty list.
    let backends = crate::ai::try_detect_available_backends()?;

    let records: Vec<Value> = backends
        .into_iter()
        .map(|backend| {
            let mut record = BTreeMap::new();
            record.insert("name".to_string(), Value::Str(backend.name));
            record.insert(
                "provider".to_string(),
                Value::Str(format!("{:?}", backend.provider)),
            );
            record.insert("endpoint".to_string(), Value::Str(backend.endpoint));
            record.insert("available".to_string(), Value::Bool(backend.available));

            let models: Vec<Value> = backend.models.into_iter().map(Value::Str).collect();
            record.insert("models".to_string(), Value::Array(models));

            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(records))
}

/// ai_detect() - Automatically detect and return the best available backend
/// Returns: String with the model URI (e.g., "ollama:llama3" or "vllm:model")
/// Returns empty string if no backend is available.
///
/// Example:
///   let backend = ai_detect()
///   if backend != "" { ai(backend, "Hello!") }
fn bi_ai_detect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("ai_detect", &args, &input)?;
    // A probe the budget or policy refuses is an error. "No backend" is the
    // empty string, and only that.
    match crate::ai::try_auto_select_backend()? {
        Some(uri) => Ok(Value::Str(uri)),
        None => Ok(Value::Str(String::new())),
    }
}

/// ai_usage() - Get detailed AI usage statistics for the current session
/// Returns: Record with call_count, total_tokens, total_cost_usd, and per-call records
///
/// Example:
///   ai_usage()
///   ai_usage() | get("total_cost_usd")
fn bi_ai_usage() -> Result<Value> {
    let tracker = crate::ai::COST_TRACKER
        .lock()
        .map_err(|_| crate::safety::lock_poisoned("ai_usage", "the cost tracker"))?;
    let summary = tracker.summary();
    Ok(Value::from_json(&summary))
}

/// ai_cost() - Get total estimated cost for the current session in USD
/// Returns: Float (cost in USD)
///
/// Example:
///   ai_cost()  # => 0.0042
fn bi_ai_cost() -> Result<Value> {
    let tracker = crate::ai::COST_TRACKER
        .lock()
        .map_err(|_| crate::safety::lock_poisoned("ai_cost", "the cost tracker"))?;
    Ok(Value::Float(tracker.total_cost_usd))
}

/// ai_reset_usage() - Reset all usage tracking counters
/// Returns: String confirmation
///
/// Example:
///   ai_reset_usage()
fn bi_ai_reset_usage(input: Option<Value>) -> Result<Value> {
    refuse_piped("ai_reset_usage", &input)?;
    let mut tracker = crate::ai::COST_TRACKER
        .lock()
        .map_err(|_| crate::safety::lock_poisoned("ai_reset_usage", "the cost tracker"))?;
    tracker.reset();
    Ok(Value::Str("Usage tracking reset".to_string()))
}

/// ai_gpu_memory() - Query GPU memory status
/// Returns: Record with GPU memory info for all available GPUs
///
/// Example:
///   ai_gpu_memory()
///   ai_gpu_memory() | get("gpus") | map(fn(g) => g.free_mb)
fn bi_ai_gpu_memory(input: Option<Value>) -> Result<Value> {
    refuse_piped("ai_gpu_memory", &input)?;
    let summary = crate::ai::try_gpu_memory_summary(None, None, None)?;
    Ok(Value::from_json(&summary))
}

/// ai_model_fits(config) - Check if a model fits in GPU memory
/// Args: config record with params_b (float), file_size_mb (int), quantization (string)
/// Returns: Record with model_fits (bool), estimated VRAM, GPU info
///
/// Example:
///   ai_model_fits({params_b: 7.0, quantization: "q4_k_m"})
///   ai_model_fits({file_size_mb: 4096})
fn bi_ai_model_fits(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "ai_model_fits";
    refuse_piped(B, &input)?;
    let config = cfg_record(
        B,
        &args,
        "a config record: {params_b | file_size_mb, quantization?}",
    )?;
    cfg_known_keys(B, config, &["params_b", "file_size_mb", "quantization"])?;

    // The upper bound keeps the VRAM estimate far inside u64, so the estimate
    // cannot overflow; the lower bound refuses a size that rounds to zero MB
    // and so "fits" anything.
    let params_b = cfg_float(B, config, "params_b", f64::MIN_POSITIVE, 1_000_000.0)?;
    let file_size_mb = cfg_int(B, config, "file_size_mb", 1, i64::MAX)?;
    let quantization = cfg_str(B, config, "quantization")?;
    match (params_b.is_some(), file_size_mb.is_some()) {
        (true, false) | (false, true) => {}
        (false, false) => {
            return Err(crate::safety::bad_arg(
                B,
                "params_b (billions, above 0) or file_size_mb (1 or more)",
                "neither",
            ))
        }
        (true, true) => {
            return Err(crate::safety::bad_arg(
                B,
                "one of params_b or file_size_mb",
                "both",
            ))
        }
    }

    let summary = crate::ai::try_gpu_memory_summary(
        params_b,
        file_size_mb.map(|n| n as u64),
        quantization.as_deref(),
    )?;
    Ok(Value::from_json(&summary))
}

// =========================== AI Provider Registry Builtins ===========================

/// ai_providers() - List all registered providers and their status
/// Returns: Array of records with provider info
///
/// Example:
///   ai_providers()
///   ai_providers() | where(fn(p) => p.status == "ready")
fn bi_ai_providers() -> Result<Value> {
    use crate::providers::registry::PROVIDER_REGISTRY;

    let mut providers = PROVIDER_REGISTRY.list();
    providers.sort_by_key(|provider| provider.scheme());
    let available = PROVIDER_REGISTRY.available();

    let mut records = Vec::new();
    for p in &providers {
        let status = PROVIDER_REGISTRY
            .status(p)
            .map(|s| match s {
                crate::providers::registry::ProviderStatus::Ready => "ready".to_string(),
                crate::providers::registry::ProviderStatus::Unchecked => "unchecked".to_string(),
                crate::providers::registry::ProviderStatus::Unavailable { reason } => {
                    format!("unavailable: {}", reason)
                }
                crate::providers::registry::ProviderStatus::AuthFailed { reason } => {
                    format!("auth_failed: {}", reason)
                }
                crate::providers::registry::ProviderStatus::Disabled => "disabled".to_string(),
            })
            .unwrap_or_else(|| "unknown".to_string());

        let is_available = available.contains(p);
        let is_default = PROVIDER_REGISTRY.default_provider() == Some(*p);

        let mut rec = std::collections::BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(p.scheme().to_string()));
        rec.insert("status".to_string(), Value::Str(status));
        rec.insert("available".to_string(), Value::Bool(is_available));
        rec.insert("default".to_string(), Value::Bool(is_default));
        if let Some(env_key) = p.api_key_env_var() {
            rec.insert(
                "has_key".to_string(),
                Value::Bool(std::env::var(env_key).is_ok()),
            );
        } else {
            rec.insert("has_key".to_string(), Value::Bool(true));
        }
        records.push(Value::Record(rec));
    }

    Ok(Value::Array(records))
}

/// ai_routes() - List all configured routing rules
/// Returns: Array of records with rule info
///
/// Example:
///   ai_routes()
fn bi_ai_routes() -> Result<Value> {
    // The rules the registry checks, in the order it checks them, and the
    // registry's totals. Nothing here contacts a provider.
    use crate::providers::registry::PROVIDER_REGISTRY;

    let stats = PROVIDER_REGISTRY.stats();
    let providers = PROVIDER_REGISTRY.list();
    let rules = PROVIDER_REGISTRY.routing_rules();

    let rule_values: Vec<Value> = rules
        .iter()
        .map(|rule| {
            let mut r = std::collections::BTreeMap::new();
            r.insert("name".to_string(), Value::Str(rule.name.clone()));
            r.insert("priority".to_string(), Value::Int(i64::from(rule.priority)));
            r.insert(
                "condition".to_string(),
                Value::Str(rule.condition.describe()),
            );
            // A rule with no target matches but returns nothing, so route
            // skips it: Null says so instead of guessing a provider.
            r.insert(
                "target".to_string(),
                rule.target_provider
                    .map(|p| Value::Str(p.scheme().to_string()))
                    .unwrap_or(Value::Null),
            );
            r.insert(
                "allow_fallback".to_string(),
                Value::Bool(rule.allow_fallback),
            );
            Value::Record(r)
        })
        .collect();

    let mut rec = std::collections::BTreeMap::new();
    rec.insert("rule_count".to_string(), Value::Int(rules.len() as i64));
    if rules.is_empty() {
        rec.insert(
            "note".to_string(),
            Value::Str(
                "no routing rules are registered; a request goes to the provider its model names when that provider is registered, and to the default provider otherwise"
                    .to_string(),
            ),
        );
    }
    rec.insert("rules".to_string(), Value::Array(rule_values));
    rec.insert(
        "total_requests".to_string(),
        Value::Int(stats.total_requests as i64),
    );
    rec.insert(
        "total_tokens".to_string(),
        Value::Int(stats.total_tokens as i64),
    );
    rec.insert(
        "registered_providers".to_string(),
        Value::Int(providers.len() as i64),
    );
    rec.insert(
        "default_provider".to_string(),
        PROVIDER_REGISTRY
            .default_provider()
            .map(|p| Value::Str(p.scheme().to_string()))
            .unwrap_or(Value::Str("none".to_string())),
    );
    rec.insert(
        "router_enabled".to_string(),
        Value::Bool(std::env::var("AETHER_AI_ROUTER").ok().as_deref() == Some("registry")),
    );

    Ok(Value::Record(rec))
}

/// ai_add_route(config) - Add a routing rule
/// Args: config record with name, priority (int), condition (string), target (string), allow_fallback (bool)
/// Condition types: "always", "has_tools", "has_vision", "model:pattern", "tokens_over:N"
/// Returns: String confirmation
///
/// Example:
///   ai_add_route({name: "tools_to_openai", priority: 100, condition: "has_tools", target: "openai"})
///   ai_add_route({name: "large_to_groq", priority: 50, condition: "tokens_over:4000", target: "groq"})
fn bi_ai_add_route(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::providers::registry::{RoutingCondition, RoutingRule, PROVIDER_REGISTRY};
    use crate::providers::ProviderType;
    const B: &str = "ai_add_route";

    refuse_piped(B, &input)?;
    let config = cfg_record(
        B,
        &args,
        "a config record: {name, condition, priority?, target?, allow_fallback?}",
    )?;
    cfg_known_keys(
        B,
        config,
        &["name", "priority", "condition", "target", "allow_fallback"],
    )?;

    let name = cfg_required_str(B, config, "name")?;
    let condition_str = cfg_required_str(B, config, "condition")?;
    let priority = cfg_int(B, config, "priority", 0, u32::MAX as i64)?.map_or(50, |p| p as u32);
    let target_str = cfg_str(B, config, "target")?;
    let allow_fallback = cfg_bool(B, config, "allow_fallback")?.unwrap_or(true);

    let condition = if condition_str == "always" {
        RoutingCondition::Always
    } else if condition_str == "has_tools" {
        RoutingCondition::HasTools
    } else if condition_str == "has_vision" {
        RoutingCondition::HasVision
    } else if let Some(pattern) = condition_str.strip_prefix("model:") {
        RoutingCondition::ModelPattern {
            pattern: pattern.to_string(),
        }
    } else if let Some(n) = condition_str.strip_prefix("tokens_over:") {
        let threshold = n.parse::<u32>().map_err(|_| {
            crate::safety::bad_arg(
                B,
                "condition: tokens_over:<N> with N a whole number",
                &condition_str,
            )
        })?;
        RoutingCondition::TokenCountOver { threshold }
    } else {
        return Err(crate::safety::bad_arg(
            B,
            "condition: always, has_tools, has_vision, model:<pattern> or tokens_over:<N>",
            &condition_str,
        ));
    };

    let target_provider = match target_str.as_deref() {
        None => None,
        Some(target) => Some(ProviderType::from_scheme(target).map_err(|_| {
            crate::safety::bad_arg(B, "target: a provider name such as openai", target)
        })?),
    };

    let rule = RoutingRule {
        name: name.clone(),
        priority,
        condition,
        target_provider,
        allow_fallback,
    };

    PROVIDER_REGISTRY.add_routing_rule(rule);

    Ok(Value::Str(format!(
        "Route '{}' added (priority {})",
        name, priority
    )))
}

/// ai_set_default(provider) - Set the default AI provider for registry routing
/// Args: provider name string (e.g., "openai", "anthropic", "ollama")
/// Returns: String confirmation
///
/// Example:
///   ai_set_default("openai")
fn bi_ai_set_default(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::providers::registry::PROVIDER_REGISTRY;
    use crate::providers::ProviderType;
    const B: &str = "ai_set_default";

    refuse_piped(B, &input)?;
    let provider_str = sole_str(B, &args, "a provider name string")?;

    // Refused before the registry is touched: an unknown name changes nothing.
    let provider_type = ProviderType::from_scheme(&provider_str).map_err(|_| {
        crate::safety::bad_arg(B, "a provider name such as openai or ollama", &provider_str)
    })?;

    // Register if not already registered
    if PROVIDER_REGISTRY.get(&provider_type).is_none() {
        let config = crate::providers::ProviderConfig::from_env(provider_type).with_env_key();
        PROVIDER_REGISTRY.register(provider_type, config);
    }

    // Registered just above, so the only failure is a provider the registry
    // does not hold; say which name missed.
    PROVIDER_REGISTRY
        .set_default(provider_type)
        .map_err(|_| crate::safety::not_found(B, "provider", &provider_str))?;

    Ok(Value::Str(format!(
        "Default provider set to '{}'",
        provider_str
    )))
}

/// ai_registry_stats() - Get usage statistics from the provider registry
/// Returns: Record with per-provider request/token/success counts
///
/// Example:
///   ai_registry_stats()
fn bi_ai_registry_stats() -> Result<Value> {
    use crate::providers::registry::PROVIDER_REGISTRY;

    let stats = PROVIDER_REGISTRY.stats();
    let mut rec = std::collections::BTreeMap::new();
    rec.insert(
        "total_requests".to_string(),
        Value::Int(stats.total_requests as i64),
    );
    rec.insert(
        "total_tokens".to_string(),
        Value::Int(stats.total_tokens as i64),
    );

    let mut by_provider = std::collections::BTreeMap::new();
    for (pt, ps) in &stats.by_provider {
        let mut prec = std::collections::BTreeMap::new();
        prec.insert("requests".to_string(), Value::Int(ps.requests as i64));
        prec.insert("successes".to_string(), Value::Int(ps.successes as i64));
        prec.insert("failures".to_string(), Value::Int(ps.failures as i64));
        prec.insert("tokens".to_string(), Value::Int(ps.tokens as i64));
        prec.insert(
            "avg_latency_ms".to_string(),
            Value::Float(ps.avg_latency_ms),
        );
        prec.insert(
            "min_latency_ms".to_string(),
            Value::Float(ps.min_latency_ms),
        );
        prec.insert(
            "max_latency_ms".to_string(),
            Value::Float(ps.max_latency_ms),
        );
        prec.insert(
            "p95_latency_ms".to_string(),
            Value::Float(ps.p95_latency_ms),
        );
        prec.insert(
            "total_cost_usd".to_string(),
            Value::Float(ps.total_cost_usd),
        );
        by_provider.insert(pt.scheme().to_string(), Value::Record(prec));
    }
    rec.insert("by_provider".to_string(), Value::Record(by_provider));

    // Include load balancing strategy
    let strategy = PROVIDER_REGISTRY.load_balancing_strategy();
    rec.insert(
        "load_balancing".to_string(),
        Value::Str(format!("{:?}", strategy)),
    );

    Ok(Value::Record(rec))
}

/// ai_set_load_balancing(strategy) - Set the load balancing strategy for AI providers
/// Args: strategy string: "none", "round_robin", "least_latency", "least_requests", "adaptive"
///       OR a record with {type: "weighted", weights: {openai: 3, anthropic: 1}}
/// Returns: String confirmation
///
/// Example:
///   ai_set_load_balancing("round_robin")
///   ai_set_load_balancing("least_latency")
///   ai_set_load_balancing({type: "weighted", weights: {openai: 3, anthropic: 1}})
fn bi_ai_set_load_balancing(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::providers::registry::{LoadBalancingStrategy, PROVIDER_REGISTRY};
    const B: &str = "ai_set_load_balancing";

    refuse_piped(B, &input)?;
    let strategy = match args.as_slice() {
        [Value::Str(s)] => match s.as_str() {
            "none" => LoadBalancingStrategy::None,
            "round_robin" | "roundrobin" | "rr" => LoadBalancingStrategy::RoundRobin,
            "least_latency" | "latency" => LoadBalancingStrategy::LeastLatency,
            "least_requests" | "requests" => LoadBalancingStrategy::LeastRequests,
            "adaptive" | "auto" => LoadBalancingStrategy::Adaptive,
            other => {
                return Err(crate::safety::bad_arg(
                    B,
                    "a strategy: none, round_robin, least_latency, least_requests, adaptive, or a weighted config record",
                    other,
                ))
            }
        },
        [Value::Record(r)] => weighted_strategy(B, r)?,
        [other] => {
            return Err(crate::safety::bad_arg(
                B,
                "a strategy string or a weighted config record",
                other.type_name(),
            ))
        }
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                "one strategy argument",
                &format!("{} argument(s)", args.len()),
            ))
        }
    };

    let label = format!("{:?}", strategy);
    PROVIDER_REGISTRY.set_load_balancing(strategy);

    Ok(Value::Str(format!("Load balancing set to {}", label)))
}

/// The weighted strategy a config record names. Every key and weight is
/// checked: a misspelt key, a non-integer weight or an empty table is refused,
/// rather than read as weight 1 or as a strategy that does nothing.
fn weighted_strategy(
    builtin: &str,
    r: &std::collections::BTreeMap<String, Value>,
) -> Result<crate::providers::registry::LoadBalancingStrategy> {
    use crate::providers::registry::LoadBalancingStrategy;
    use crate::providers::ProviderType;

    cfg_known_keys(builtin, r, &["type", "weights"])?;
    let lb_type = cfg_str(builtin, r, "type")?.unwrap_or_else(|| "weighted".to_string());
    if lb_type != "weighted" {
        return Err(crate::safety::bad_arg(
            builtin,
            "type: \"weighted\"",
            &lb_type,
        ));
    }
    let weights_rec = match r.get("weights") {
        Some(Value::Record(w)) => w,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "weights: a record of provider name to weight",
                other.type_name(),
            ))
        }
        None => {
            return Err(crate::safety::bad_arg(
                builtin,
                "weights: a record of provider name to weight",
                "missing",
            ))
        }
    };
    if weights_rec.is_empty() {
        return Err(crate::safety::bad_arg(
            builtin,
            "weights: at least one provider",
            "an empty record",
        ));
    }

    let mut weights = std::collections::HashMap::new();
    for (key, value) in weights_rec {
        let provider = ProviderType::from_scheme(key).map_err(|_| {
            crate::safety::bad_arg(
                builtin,
                "weights: keys are provider names such as openai",
                key,
            )
        })?;
        let weight = match value {
            Value::Int(i) if (0..=u32::MAX as i64).contains(i) => *i as u32,
            Value::Float(f)
                if f.is_finite() && f.fract() == 0.0 && *f >= 0.0 && *f <= u32::MAX as f64 =>
            {
                *f as u32
            }
            other => {
                return Err(crate::safety::bad_arg(
                    builtin,
                    &format!("weight for {key}: a whole number from 0 to {}", u32::MAX),
                    &other.to_string(),
                ))
            }
        };
        weights.insert(provider, weight);
    }
    Ok(LoadBalancingStrategy::Weighted { weights })
}

/// ai_load_balancing() - Get the current load balancing strategy
/// Returns: String describing the active strategy
///
/// Example:
///   ai_load_balancing()
fn bi_ai_load_balancing() -> Result<Value> {
    use crate::providers::registry::PROVIDER_REGISTRY;

    let strategy = PROVIDER_REGISTRY.load_balancing_strategy();
    Ok(Value::Str(format!("{:?}", strategy)))
}

/// ai_convert_model(config) - Convert a model between formats.
///
/// **Delegates to IronVault.** This used to call an in-tree converter whose
/// every path was `fs::copy` — its own source said "simulate conversion by
/// copying file" — and which then reported `success: true` with a checksum of
/// the unchanged bytes. A conversion that silently does nothing is worse than
/// one that fails, so that path is gone. Format conversion is IronVault's job
/// in this stack, and IronVault addresses models by vault name rather than by
/// file path, so callers holding a loose file must add it to the vault first.
///
/// Args: config record with name and to_format (see `vault_convert`), or the
/// legacy source/target/source_format/target_format form, which is refused.
///
/// Example:
///   ai_convert_model({name: "my-llm", to_format: "gguf", quantization: "q4_k_m"})
fn bi_ai_convert_model(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "ai_convert_model";
    refuse_piped(B, &input)?;
    let config = cfg_record(
        B,
        &args,
        "a config record: {name, to_format, quantization?, output?, validate?}",
    )?;

    // The legacy path-based form cannot be honoured: IronVault converts models
    // it stores, and there is no correct way to guess which stored model a
    // loose path corresponds to. Say so precisely rather than half-working.
    if config.contains_key("source") || config.contains_key("target") {
        return Err(crate::safety::arg_err(
            "ai_convert_model: the source/target path form is no longer supported.\n\
             It was backed by an in-tree converter that copied the file and reported \
             success, so it never converted anything.\n\
             Conversion now goes through IronVault, which addresses models by vault name:\n  \
               iv add <path> --name <name>\n  \
               ai_convert_model({name: \"<name>\", to_format: \"gguf\"})",
        ));
    }

    bi_vault_convert(args, None)
}

/// ai_supported_conversions() - List the format conversions available.
///
/// Answered by IronVault, which is what actually performs them. The in-tree
/// table this used to read listed conversions that were implemented as file
/// copies, so it described capability the shell did not have.
///
/// Returns: the vault's supported conversion paths
fn bi_ai_supported_conversions(input: Option<Value>) -> Result<Value> {
    bi_vault_conversions(input)
}

/// ai_detect_format(path) - Detect the format of a model file
/// Args: path (string)
/// Returns: String with detected format name
fn bi_ai_detect_format(args: Vec<Value>) -> Result<Value> {
    let path = match args.first() {
        Some(Value::Str(s)) => s,
        _ => {
            return Err(crate::safety::arg_err(
                "ai_detect_format: requires a file path string",
            ))
        }
    };

    let ext = std::path::Path::new(path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("");

    let format = match ext.to_lowercase().as_str() {
        "gguf" => "GGUF",
        "safetensors" => "SafeTensors",
        "pt" | "pth" | "bin" => "PyTorch",
        "onnx" => "ONNX",
        "pb" | "savedmodel" => "TensorFlow",
        "trt" | "engine" => "TensorRT",
        _ => "Unknown",
    };

    Ok(Value::Str(format.to_string()))
}

// ========== Local Inference Builtins ==========

// ============================================================================
// THE NERVOSYS STACK — IronGate (routing), IronWorks (inference),
// IronVault (model store and conversion)
// ============================================================================

/// ai_gateway() - Report IronGate: whether it is up, what it will route, and
/// the state of each backend behind it.
///
/// This is the one place a caller can see the shape of the stack it is talking
/// to, including whether the local leg (IronWorks) is actually serving.
///
/// Returns: Record with url, reachable, providers, models, targets
///
/// Example:
///   ai_gateway()
///   ai_gateway().targets | where(fn(t) => t.circuit != "closed")
fn bi_ai_gateway(input: Option<Value>) -> Result<Value> {
    refuse_piped("ai_gateway", &input)?;
    let mut rec = std::collections::BTreeMap::new();
    rec.insert(
        "url".to_string(),
        Value::Str(crate::model_plane::gate_url()),
    );
    rec.insert(
        "default_model".to_string(),
        Value::Str(crate::model_plane::gate_model()),
    );

    let health = match crate::model_plane::gate_health() {
        Ok(h) => h,
        Err(e) => {
            // An unreachable gateway is an answer, not an error: the caller
            // asked about the gateway's state and "down" is a state. Returning
            // Err here would make the common check `ai_gateway().reachable`
            // impossible to write.
            rec.insert("reachable".to_string(), Value::Bool(false));
            rec.insert("error".to_string(), Value::Str(e.to_string()));
            rec.insert("providers".to_string(), Value::Int(0));
            rec.insert("models".to_string(), Value::Array(vec![]));
            rec.insert("targets".to_string(), Value::Array(vec![]));
            return Ok(Value::Record(rec));
        }
    };

    rec.insert("reachable".to_string(), Value::Bool(true));
    rec.insert("providers".to_string(), Value::Int(health.providers as i64));
    rec.insert(
        "models".to_string(),
        Value::Array(health.models.into_iter().map(Value::Str).collect()),
    );

    // Per-target circuit state. Best-effort: /status is a richer endpoint than
    // /health and a gateway can be serving with it unavailable. When it is
    // unavailable the targets are unknown, and the reason is reported as
    // targets_error rather than presented as an empty list.
    let targets = match crate::model_plane::gate_status() {
        Ok(status) => status
            .get("targets")
            .or_else(|| status.get("breakers"))
            .and_then(|t| t.as_array())
            .map(|arr| {
                arr.iter()
                    .cloned()
                    .map(json_to_value)
                    .collect::<Vec<Value>>()
            })
            .unwrap_or_default(),
        Err(e) => {
            rec.insert("targets_error".to_string(), Value::Str(e.to_string()));
            vec![]
        }
    };
    rec.insert("targets".to_string(), Value::Array(targets));

    Ok(Value::Record(rec))
}

/// vault_models() - List the models IronVault is storing.
///
/// Reads the encrypted inventory, so IRONVAULT_PASSPHRASE must be set; the
/// vault reports that failure itself rather than this builtin guessing at it.
///
/// Returns: Array of records, as the vault reports them
///
/// Example:
///   vault_models()
///   vault_models() | where(fn(m) => m.format == "gguf")
fn bi_vault_models(input: Option<Value>) -> Result<Value> {
    refuse_piped("vault_models", &input)?;
    let json = crate::model_plane::vault_list()?;
    Ok(json_to_value(json))
}

/// vault_conversions() - List the format conversions IronVault supports.
///
/// Returns: Array of supported conversion paths
fn bi_vault_conversions(input: Option<Value>) -> Result<Value> {
    refuse_piped("vault_conversions", &input)?;
    let json = crate::model_plane::vault_conversions()?;
    Ok(json_to_value(json))
}

/// vault_convert(config) - Convert a stored model between formats.
///
/// Args: config record with name, to_format, and optionally quantization,
/// output, validate.
///
/// Returns: Record with the vault's own report
///
/// Example:
///   vault_convert({name: "my-llm", to_format: "gguf", quantization: "q4_k_m", validate: true})
fn bi_vault_convert(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "vault_convert";
    refuse_piped(B, &input)?;
    let config = cfg_record(
        B,
        &args,
        "a config record: {name, to_format, quantization?, output?, validate?}",
    )?;
    cfg_known_keys(
        B,
        config,
        &[
            "name",
            "to_format",
            "target_format",
            "quantization",
            "output",
            "validate",
        ],
    )?;

    let name = cfg_required_str(B, config, "name")?;
    let to_format = match (
        cfg_str(B, config, "to_format")?,
        cfg_str(B, config, "target_format")?,
    ) {
        (Some(f), None) | (None, Some(f)) => f,
        (None, None) => {
            return Err(crate::safety::bad_arg(
                B,
                "to_format: a format such as \"gguf\" or \"safetensors\"",
                "missing",
            ))
        }
        (Some(_), Some(_)) => {
            return Err(crate::safety::bad_arg(
                B,
                "one of to_format or target_format",
                "both",
            ))
        }
    };
    let quantization = cfg_str(B, config, "quantization")?;
    let output = cfg_str(B, config, "output")?;
    let validate = cfg_bool(B, config, "validate")?.unwrap_or(false);

    // These reach iv as argv, where a value beginning with '-' is an option.
    let mut values = vec![name.clone(), to_format.clone()];
    values.extend(quantization.iter().cloned());
    values.extend(output.iter().cloned());
    crate::safety::reject_option_like(B, &values)?;

    let stdout = crate::model_plane::vault_convert(
        &name,
        &to_format,
        quantization.as_deref(),
        output.as_deref(),
        validate,
    )?;

    let mut rec = std::collections::BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("to_format".to_string(), Value::Str(to_format));
    if let Some(q) = quantization {
        rec.insert("quantization".to_string(), Value::Str(q));
    }
    if let Some(o) = output {
        rec.insert("output".to_string(), Value::Str(o));
    }
    rec.insert("validated".to_string(), Value::Bool(validate));
    rec.insert("report".to_string(), Value::Str(stdout.trim().to_string()));
    Ok(Value::Record(rec))
}

/// ai_local_backends() - List available local inference backends
/// Returns: Array of Records with backend name and supported formats
///
/// Example:
///   ai_local_backends()
fn bi_ai_local_backends() -> Result<Value> {
    use crate::local_inference;

    let backends = local_inference::available_backends();
    let names = local_inference::backend_names();

    if backends.is_empty() {
        return Ok(Value::Array(vec![Value::Record({
            let mut r = std::collections::BTreeMap::new();
            r.insert("status".to_string(), Value::Str("none".to_string()));
            r.insert(
                "message".to_string(),
                Value::Str(
                    "No local inference backends compiled. Rebuild with --features candle or --features onnx"
                        .to_string(),
                ),
            );
            r
        })]));
    }

    let mut result = Vec::new();
    for (backend, name) in backends.iter().zip(names.iter()) {
        let mut rec = std::collections::BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(name.to_string()));
        rec.insert(
            "loaded_models".to_string(),
            Value::Array(
                backend
                    .loaded_models()
                    .into_iter()
                    .map(Value::Str)
                    .collect(),
            ),
        );
        let formats: Vec<&str> = ["gguf", "safetensors", "onnx", "pt", "bin"]
            .iter()
            .copied()
            .filter(|ext| backend.supports_format(ext))
            .collect();
        rec.insert(
            "formats".to_string(),
            Value::Array(
                formats
                    .into_iter()
                    .map(|f| Value::Str(f.to_string()))
                    .collect(),
            ),
        );
        result.push(Value::Record(rec));
    }

    Ok(Value::Array(result))
}

/// ai_local_load(path) - Load a local model file into an inference backend
/// Returns: Record with handle, backend name, and estimated memory
///
/// Example:
///   ai_local_load("models/llama-3.2-1b-q4_k_m.gguf")
fn bi_ai_local_load(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::local_inference;
    const B: &str = "ai_local_load";
    refuse_piped(B, &input)?;
    let path = sole_str(B, &args, "a model file path string")?;

    let backend = local_inference::backend_for_model(&path).ok_or_else(|| {
        crate::safety::unimplemented(
            B,
            &format!(
                "no compiled-in backend supports this model format (available: {:?})",
                local_inference::backend_names()
            ),
            "rebuild with --features candle (for .gguf/.safetensors) or --features onnx (for .onnx)",
        )
    })?;

    let mut rec = std::collections::BTreeMap::new();
    // A memory estimate the backend cannot make is unknown, and the reason is
    // reported with it. It is not zero MB.
    match backend.estimate_memory_mb(&path) {
        Ok(mb) => {
            rec.insert("estimated_memory_mb".to_string(), Value::Int(mb as i64));
        }
        Err(e) => {
            rec.insert("estimated_memory_mb".to_string(), Value::Null);
            rec.insert("estimate_error".to_string(), Value::Str(e.to_string()));
        }
    }
    // A backend's coded refusal (an unsupported architecture, say) and a
    // file it cannot open keep their own codes; only what is left is read as
    // a file the backend cannot load.
    let handle = backend.load_model(&path).map_err(|e| {
        if e.downcast_ref::<crate::safety::SafetyError>().is_some() {
            return e;
        }
        if let Some(io) = e.downcast_ref::<std::io::Error>() {
            return crate::safety::fs_error(B, &path, io);
        }
        crate::safety::bad_arg(B, "a model file the backend can load", &e.to_string())
    })?;

    rec.insert("handle".to_string(), Value::Str(handle));
    rec.insert(
        "backend".to_string(),
        Value::Str(backend.name().to_string()),
    );
    rec.insert("path".to_string(), Value::Str(path));

    Ok(Value::Record(rec))
}

/// The prompt `ai_local_generate` was given: text for the backend's `generate`,
/// or chat messages for its `chat`.
enum GeneratePrompt {
    Text(String),
    Chat(Vec<crate::local_inference::ChatMessage>),
}

/// What `ai_local_generate` takes as its prompt, for a refusal to quote.
const GENERATE_PROMPT_EXPECTED: &str = "prompt: a String, or an Array of {role, content} messages";

/// The messages of a chat prompt: an Array of Records with exactly `role` and
/// `content`, both Strings, and a role of system, user, assistant or tool. Every
/// message is checked here, before a backend is looked up, so a malformed
/// conversation is refused the same way whichever model it names.
fn chat_messages_arg(
    builtin: &str,
    items: &[Value],
) -> Result<Vec<crate::local_inference::ChatMessage>> {
    if items.is_empty() {
        return Err(crate::safety::bad_arg(
            builtin,
            GENERATE_PROMPT_EXPECTED,
            "an empty Array",
        ));
    }
    let mut messages = Vec::with_capacity(items.len());
    for (i, item) in items.iter().enumerate() {
        let n = i + 1;
        let Value::Record(rec) = item else {
            return Err(crate::safety::bad_arg(
                builtin,
                GENERATE_PROMPT_EXPECTED,
                &format!("message {n} of type {}", item.type_name()),
            ));
        };
        if rec.len() != 2 || !rec.contains_key("role") || !rec.contains_key("content") {
            let fields: Vec<&str> = rec.keys().map(String::as_str).collect();
            return Err(crate::safety::bad_arg(
                builtin,
                GENERATE_PROMPT_EXPECTED,
                &format!("message {n} with fields {fields:?}"),
            ));
        }
        let (role, content) = match (rec.get("role"), rec.get("content")) {
            (Some(Value::Str(role)), Some(Value::Str(content))) => (role, content),
            _ => {
                return Err(crate::safety::bad_arg(
                    builtin,
                    GENERATE_PROMPT_EXPECTED,
                    &format!("message {n} whose role and content are not both Strings"),
                ))
            }
        };
        if !matches!(role.as_str(), "system" | "user" | "assistant" | "tool") {
            return Err(crate::safety::bad_arg(
                builtin,
                GENERATE_PROMPT_EXPECTED,
                &format!("message {n} with role {role:?}"),
            ));
        }
        messages.push(crate::local_inference::ChatMessage {
            role: role.clone(),
            content: content.clone(),
        });
    }
    Ok(messages)
}

/// ai_local_generate(handle, prompt, params?) - Generate text using a loaded local model
/// The prompt is a String, sent as is, or an Array of {role, content} messages
/// (role: system, user, assistant or tool). A messages Array is formatted by the
/// model's own chat template, and a model with no chat template refuses it.
/// Returns: Record with generated text, token counts, and performance metrics
///
/// Example:
///   ai_local_generate("candle:llama", "What is Rust?")
///   ai_local_generate("candle:llama", [{role: "user", content: "What is Rust?"}])
///   ai_local_generate("candle:llama", "Hello", {max_tokens: 100, temperature: 0.5})
fn bi_ai_local_generate(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::local_inference::{self, GenerationParams};
    const B: &str = "ai_local_generate";
    refuse_piped(B, &input)?;

    let handle = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ai_local_generate: requires handle string as first argument",
            ))
        }
    };

    let prompt = match args.get(1) {
        Some(Value::Str(s)) => GeneratePrompt::Text(s.clone()),
        Some(Value::Array(items)) => GeneratePrompt::Chat(chat_messages_arg(B, items)?),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                GENERATE_PROMPT_EXPECTED,
                other.type_name(),
            ))
        }
        None => {
            return Err(crate::safety::arg_err(
                "ai_local_generate: requires prompt as second argument",
            ))
        }
    };

    let mut params = GenerationParams::default();
    match args.get(2) {
        None => {}
        Some(Value::Record(r)) => {
            cfg_known_keys(
                B,
                r,
                &[
                    "max_tokens",
                    "temperature",
                    "top_p",
                    "repetition_penalty",
                    "seed",
                ],
            )?;
            if let Some(n) = cfg_int(B, r, "max_tokens", 1, u32::MAX as i64)? {
                params.max_tokens = n as u32;
            }
            if let Some(t) = cfg_float(B, r, "temperature", 0.0, f64::MAX)? {
                params.temperature = t;
            }
            if let Some(p) = cfg_float(B, r, "top_p", 0.0, 1.0)? {
                params.top_p = p;
            }
            if let Some(p) = cfg_float(B, r, "repetition_penalty", f64::MIN_POSITIVE, f64::MAX)? {
                params.repetition_penalty = p;
            }
            if let Some(s) = cfg_int(B, r, "seed", 0, i64::MAX)? {
                params.seed = Some(s as u64);
            }
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "params: a record {max_tokens?, temperature?, top_p?, repetition_penalty?, seed?}",
                other.type_name(),
            ))
        }
    }

    // Find the right backend from the handle prefix
    for backend in local_inference::available_backends() {
        if handle.starts_with(&format!("{}:", backend.name())) {
            let result = match &prompt {
                GeneratePrompt::Text(text) => backend.generate(&handle, text, &params)?,
                GeneratePrompt::Chat(messages) => backend.chat(&handle, messages, &params)?,
            };
            let mut rec = std::collections::BTreeMap::new();
            rec.insert("text".to_string(), Value::Str(result.text));
            rec.insert(
                "prompt_tokens".to_string(),
                Value::Int(result.prompt_tokens as i64),
            );
            rec.insert(
                "completion_tokens".to_string(),
                Value::Int(result.completion_tokens as i64),
            );
            rec.insert(
                "generation_ms".to_string(),
                Value::Float(result.generation_ms),
            );
            rec.insert(
                "tokens_per_second".to_string(),
                Value::Float(result.tokens_per_second),
            );
            rec.insert(
                "backend".to_string(),
                Value::Str(backend.name().to_string()),
            );
            return Ok(Value::Record(rec));
        }
    }

    // Nothing in-process can serve this handle. Before failing, try the
    // gateway: in this stack "local inference" means IronWorks behind IronGate,
    // and a build with neither `candle` nor `onnx` compiled in — which is the
    // default build — has no in-process backend at all. Treat the handle as the
    // model name and let the gateway route it.
    // The gateway takes a prompt string, so messages have no route through it.
    let prompt = match prompt {
        GeneratePrompt::Text(text) => text,
        GeneratePrompt::Chat(_) if crate::model_plane::gate_available() => {
            return Err(crate::safety::unimplemented(
                B,
                "chat messages through IronGate",
                "pass a prompt string",
            ))
        }
        GeneratePrompt::Chat(_) => {
            return Err(crate::safety::not_found(B, "local model handle", &handle))
        }
    };
    if crate::model_plane::gate_available() {
        let max_tokens = Some(params.max_tokens);
        let done = crate::model_plane::gate_complete(&handle, &prompt, max_tokens)?;
        let mut rec = std::collections::BTreeMap::new();
        rec.insert("text".to_string(), Value::Str(done.text));
        rec.insert(
            "prompt_tokens".to_string(),
            Value::Int(done.prompt_tokens as i64),
        );
        rec.insert(
            "completion_tokens".to_string(),
            Value::Int(done.completion_tokens as i64),
        );
        rec.insert("generation_ms".to_string(), Value::Float(done.elapsed_ms));
        rec.insert(
            "tokens_per_second".to_string(),
            Value::Float(if done.elapsed_ms > 0.0 {
                done.completion_tokens as f64 / (done.elapsed_ms / 1000.0)
            } else {
                0.0
            }),
        );
        // Which engine answered is part of the answer here: the same call can
        // be served in-process or by a machine across the network, and a caller
        // comparing timings needs to know which.
        rec.insert(
            "backend".to_string(),
            Value::Str(done.target.unwrap_or_else(|| "irongate".to_string())),
        );
        return Ok(Value::Record(rec));
    }

    Err(crate::safety::not_found(B, "local model handle", &handle))
}

/// ai_local_embed(handle, inputs) - Generate embeddings using a loaded local model
/// Returns: Record with embeddings array and token count
///
/// Example:
///   ai_local_embed("candle:embed-model", ["Hello world", "Rust is great"])
fn bi_ai_local_embed(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::local_inference;
    const B: &str = "ai_local_embed";
    refuse_piped(B, &input)?;

    let handle = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ai_local_embed: requires handle string as first argument",
            ))
        }
    };

    // Every element must be a string. The earlier code rendered a number or a
    // record with to_string and embedded that text, which is a different call.
    let inputs: Vec<String> = match args.get(1) {
        Some(Value::Array(arr)) if arr.is_empty() => {
            return Err(crate::safety::bad_arg(
                B,
                "inputs: at least one string",
                "an empty array",
            ))
        }
        Some(Value::Array(arr)) => arr
            .iter()
            .map(|v| match v {
                Value::Str(s) => Ok(s.clone()),
                other => Err(crate::safety::bad_arg(
                    B,
                    "inputs: an array of strings",
                    other.type_name(),
                )),
            })
            .collect::<Result<Vec<String>>>()?,
        Some(Value::Str(s)) => vec![s.clone()],
        _ => {
            return Err(crate::safety::arg_err(
                "ai_local_embed: requires input string or array of strings",
            ))
        }
    };

    for backend in local_inference::available_backends() {
        if handle.starts_with(&format!("{}:", backend.name())) {
            let result = backend.embed(&handle, &inputs)?;
            let mut rec = std::collections::BTreeMap::new();
            rec.insert(
                "embeddings".to_string(),
                Value::Array(
                    result
                        .embeddings
                        .into_iter()
                        .map(|emb| {
                            Value::Array(emb.into_iter().map(|f| Value::Float(f as f64)).collect())
                        })
                        .collect(),
                ),
            );
            rec.insert(
                "total_tokens".to_string(),
                Value::Int(result.total_tokens as i64),
            );
            return Ok(Value::Record(rec));
        }
    }

    Err(crate::safety::not_found(B, "local model handle", &handle))
}

/// ai_local_unload(handle) - Unload a previously loaded local model
/// Returns: String confirmation
///
/// Example:
///   ai_local_unload("candle:llama")
fn bi_ai_local_unload(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use crate::local_inference;
    const B: &str = "ai_local_unload";
    refuse_piped(B, &input)?;
    let handle = sole_str(B, &args, "a handle string")?;

    for backend in local_inference::available_backends() {
        if handle.starts_with(&format!("{}:", backend.name())) {
            backend.unload_model(&handle)?;
            return Ok(Value::Str(format!("Model '{}' unloaded", handle)));
        }
    }

    Err(crate::safety::not_found(B, "local model handle", &handle))
}

// ========== Runtime Type Introspection ==========

/// typeof(value) - Get the runtime type name of a value
/// Returns: String with the type name
///
/// Example:
///   typeof(42)              # => "Int"
///   typeof("hello")         # => "String"
///   typeof([1,2])           # => "Array"
///   typeof({a: 1})          # => "Record"
///   42 | typeof()           # => "Int"
fn bi_typeof(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input) = input {
        input
    } else if let Some(v) = args.first() {
        v.clone()
    } else {
        return Err(crate::safety::arg_err(
            "typeof: requires a value (argument or piped input)",
        ));
    };

    Ok(Value::Str(val.type_name().to_string()))
}

/// type_name(value) - Get detailed type description with inner types
/// Returns: String with detailed type info
///
/// Example:
///   type_name([1,2,3])       # => "Array<Int>"
///   type_name({a: 1, b: "x"})  # => "Record{a: Int, b: String}"
fn bi_type_name(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input) = input {
        input
    } else if let Some(v) = args.first() {
        v.clone()
    } else {
        return Err(crate::safety::arg_err("type_name: requires a value"));
    };

    let type_desc = detailed_type_name(&val);
    Ok(Value::Str(type_desc))
}

fn detailed_type_name(val: &Value) -> String {
    match val {
        Value::Int(_) => "Int".into(),
        Value::Float(_) => "Float".into(),
        Value::Str(_) => "String".into(),
        Value::Bool(_) => "Bool".into(),
        Value::Null => "Null".into(),
        Value::Uri(_) => "Uri".into(),
        Value::Error(e) => format!("Error({})", e),
        Value::Builtin(b) => format!("Builtin({})", b.name),
        Value::AsyncLambda(al) => format!("AsyncLambda({})", al.params.len()),
        Value::Future(_) => "Future".into(),
        Value::Array(items) => {
            if items.is_empty() {
                "Array<Any>".into()
            } else {
                let inner = detailed_type_name(&items[0]);
                format!("Array<{}>", inner)
            }
        }
        Value::Record(fields) => {
            let parts: Vec<String> = fields
                .iter()
                .take(6)
                .map(|(k, v)| format!("{}: {}", k, detailed_type_name(v)))
                .collect();
            let suffix = if fields.len() > 6 { ", …" } else { "" };
            format!("Record{{{}{}}}", parts.join(", "), suffix)
        }
        Value::Lambda(l) => format!("Lambda({})", l.params.len()),
        Value::Table(t) => {
            format!("Table({} cols, {} rows)", t.schema.len(), t.rows.len())
        }
    }
}

/// type_fields(record) - Get the field names and types of a record
/// Returns: Array of records with name, type, value_preview
///
/// Example:
///   type_fields({name: "ae", version: 3, active: true})
fn bi_type_fields(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input) = input {
        input
    } else if let Some(v) = args.first() {
        v.clone()
    } else {
        return Err(crate::safety::arg_err(
            "type_fields: requires a record value",
        ));
    };

    match val {
        Value::Record(fields) => {
            let result: Vec<Value> = fields
                .iter()
                .map(|(name, value)| {
                    let mut r = std::collections::BTreeMap::new();
                    r.insert("name".to_string(), Value::Str(name.clone()));
                    r.insert("type".to_string(), Value::Str(detailed_type_name(value)));
                    // Brief preview of value
                    let preview = match value {
                        Value::Str(s) if s.chars().nth(50).is_some() => {
                            format!("\"{}…\"", s.chars().take(50).collect::<String>())
                        }
                        Value::Array(a) => format!("[…] ({} items)", a.len()),
                        Value::Record(r) => format!("{{…}} ({} fields)", r.len()),
                        other => format!("{}", other),
                    };
                    r.insert("preview".to_string(), Value::Str(preview));
                    Value::Record(r)
                })
                .collect();
            Ok(Value::Array(result))
        }
        Value::Table(t) => {
            let result: Vec<Value> = t
                .schema
                .iter()
                .map(|h| {
                    let mut r = std::collections::BTreeMap::new();
                    r.insert("name".to_string(), Value::Str(h.clone()));
                    r.insert("type".to_string(), Value::Str("Any".to_string()));
                    r.insert("preview".to_string(), Value::Str("(column)".to_string()));
                    Value::Record(r)
                })
                .collect();
            Ok(Value::Array(result))
        }
        _ => Err(crate::safety::bad_arg(
            "type_fields",
            "a Record or Table",
            &detailed_type_name(&val),
        )),
    }
}

/// type_schema(value) - Generate a JSON Schema for a value's structure
/// Returns: Record representing a JSON Schema
///
/// Example:
///   type_schema({name: "ae", version: 3})
///   # => {type: "object", properties: {name: {type: "string"}, version: {type: "integer"}}}
fn bi_type_schema(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input) = input {
        input
    } else if let Some(v) = args.first() {
        v.clone()
    } else {
        return Err(crate::safety::arg_err("type_schema: requires a value"));
    };

    let schema = value_to_json_schema(&val);
    Ok(Value::from_json(&schema))
}

fn value_to_json_schema(val: &Value) -> serde_json::Value {
    use serde_json::json;
    match val {
        Value::Int(_) => json!({"type": "integer"}),
        Value::Float(_) => json!({"type": "number"}),
        Value::Str(_) => json!({"type": "string"}),
        Value::Bool(_) => json!({"type": "boolean"}),
        Value::Null => json!({"type": "null"}),
        Value::Uri(_) => json!({"type": "string", "format": "uri"}),
        Value::Error(_) => json!({"type": "string", "description": "error"}),
        Value::Builtin(_) => json!({"type": "string", "description": "builtin reference"}),
        Value::AsyncLambda(_) => json!({"type": "function", "async": true}),
        Value::Future(_) => json!({"type": "object", "description": "future"}),
        Value::Array(items) => {
            if items.is_empty() {
                json!({"type": "array", "items": {}})
            } else {
                let item_schema = value_to_json_schema(&items[0]);
                json!({"type": "array", "items": item_schema})
            }
        }
        Value::Record(fields) => {
            let mut properties = serde_json::Map::new();
            let required: Vec<String> = fields.keys().cloned().collect();
            for (k, v) in fields {
                properties.insert(k.clone(), value_to_json_schema(v));
            }
            json!({
                "type": "object",
                "properties": serde_json::Value::Object(properties),
                "required": required,
            })
        }
        Value::Lambda(l) => {
            json!({"type": "function", "parameters": l.params.len()})
        }
        Value::Table(t) => {
            let mut properties = serde_json::Map::new();
            for h in &t.schema {
                properties.insert(h.clone(), json!({}));
            }
            json!({
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": serde_json::Value::Object(properties),
                }
            })
        }
    }
}

/// is_type(value, type_name) - Check if a value matches a type name
/// Returns: Bool
///
/// Example:
///   is_type(42, "Int")       # => true
///   is_type("hi", "String")  # => true
///   is_type([], "Array")     # => true
fn bi_is_type(args: Vec<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "is_type: requires (value, type_name) arguments",
        ));
    }
    let type_name = match &args[1] {
        Value::Str(s) => s.to_lowercase(),
        other => {
            return Err(crate::safety::bad_arg(
                "is_type",
                "type_name: String",
                other.type_name(),
            ))
        }
    };

    let matches = match (&args[0], type_name.as_str()) {
        (Value::Int(_), "int" | "integer" | "number") => true,
        (Value::Float(_), "float" | "number" | "double") => true,
        (Value::Str(_), "string" | "str" | "text") => true,
        (Value::Bool(_), "bool" | "boolean") => true,
        (Value::Array(_), "array" | "list") => true,
        (Value::Record(_), "record" | "object" | "map") => true,
        (Value::Uri(_), "uri" | "url") => true,
        (Value::Lambda(_), "lambda" | "function" | "fn") => true,
        (Value::AsyncLambda(_), "asynclambda" | "async_lambda" | "function" | "fn") => true,
        (Value::Null, "null" | "nil" | "none") => true,
        (Value::Table(_), "table") => true,
        (Value::Error(_), "error") => true,
        (Value::Future(_), "future") => true,
        (Value::Builtin(_), "builtin") => true,
        (_, "any") => true,
        _ => false,
    };

    Ok(Value::Bool(matches))
}

