/// slice(start, end?) - Extract slice of array or string
/// Args:
///   - start: Int - Start index (inclusive)
///   - end: Int (optional) - End index (exclusive)
/// Returns: Array or String - Sliced input
///
/// Example:
///   [1,2,3,4,5] | slice(1, 3)     # Returns [2,3]
///   slice([1,2,3,4,5], 1, 3)      # Also works as function call
fn bi_slice(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Determine input and index arguments
    // If input is provided via pipe, args are (start, end?)
    // If input is first arg, args are (array, start, end?)
    let (input_val, start_idx, end_arg) = if let Some(inp) = input {
        // Piped input: args are start, end?
        if args.is_empty() {
            return Err(crate::safety::arg_err(
                "slice requires at least start index",
            ));
        }
        let start = expect_int("slice", &args[0])? as usize;
        let end = args.get(1);
        (inp, start, end)
    } else {
        // Function call: first arg is array, then start, end?
        if args.len() < 2 {
            return Err(crate::safety::arg_err(
                "slice(array, start, end?) requires at least array and start",
            ));
        }
        let arr = args[0].clone();
        let start = expect_int("slice", &args[1])? as usize;
        let end = args.get(2);
        (arr, start, end)
    };

    match input_val {
        Value::Array(arr) => {
            let end = if let Some(e) = end_arg {
                expect_int("slice", e)? as usize
            } else {
                arr.len()
            };

            let end = end.min(arr.len());
            let start = start_idx.min(end);

            Ok(Value::Array(arr[start..end].to_vec()))
        }
        Value::Str(s) => {
            let chars: Vec<char> = s.chars().collect();
            let end = if let Some(e) = end_arg {
                expect_int("slice", e)? as usize
            } else {
                chars.len()
            };

            let end = end.min(chars.len());
            let start = start_idx.min(end);

            Ok(Value::Str(chars[start..end].iter().collect()))
        }
        _ => Err(crate::safety::arg_err(
            "slice requires array or string input",
        )),
    }
}

/// Most elements `range` will build. A longer range is refused before any
/// element is allocated, as a coded `BudgetExceeded` error, so
/// `range(0, 1000000000000)` cannot exhaust memory.
const RANGE_MAX: i128 = 10_000_000;

/// range(start, end?, step?) - Generate array of integers
/// Args:
///   - start: Int - Start value (or end if only one arg)
///   - end: Int (optional) - End value (exclusive)
///   - step: Int (optional) - Step size (default 1)
/// Returns: Array - Array of integers
///
/// Example:
///   range(5)           # Returns [0,1,2,3,4]
///   range(2, 7)        # Returns [2,3,4,5,6]
///   range(0, 10, 2)    # Returns [0,2,4,6,8]
fn bi_range(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "range requires at least one argument",
        ));
    }

    let (start, end, step) = if args.len() == 1 {
        // range(n) -> 0..n
        (0, expect_int("range", &args[0])?, 1)
    } else if args.len() == 2 {
        // range(start, end) -> start..end
        (
            expect_int("range", &args[0])?,
            expect_int("range", &args[1])?,
            1,
        )
    } else {
        // range(start, end, step)
        (
            expect_int("range", &args[0])?,
            expect_int("range", &args[1])?,
            expect_int("range", &args[2])?,
        )
    };

    if step == 0 {
        return Err(crate::safety::arg_err("range step cannot be zero"));
    }

    // Count first, in i128, so no step or offset can overflow i64. The count
    // is refused before anything is allocated.
    let (s, e, st) = (start as i128, end as i128, step as i128);
    let count: i128 = if st > 0 {
        if s < e {
            (e - s + st - 1) / st
        } else {
            0
        }
    } else if s > e {
        (s - e - st - 1) / -st
    } else {
        0
    };
    if count > RANGE_MAX {
        return Err(crate::safety::budget_exceeded(
            "range",
            format!("{count} elements exceed the {RANGE_MAX} element limit"),
            "iterate in chunks, or use a smaller range",
        ));
    }

    let mut result = Vec::with_capacity(count as usize);
    for i in 0..count {
        // Each element lies between start and end, so it fits in i64.
        result.push(Value::Int((s + i * st) as i64));
    }

    Ok(Value::Array(result))
}

/// zip(array2) - Zip two arrays into array of pairs
/// Args:
///   - array2: Array - Second array to zip with
/// Returns: Array - Array of [item1, item2] pairs
///
/// Example:
///   [1,2,3] | zip(["a","b","c"])     # Returns [[1,"a"],[2,"b"],[3,"c"]]
fn bi_zip(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (arr1_val, arr2_val) = if let Some(inp) = input {
        // Piped: input is first array, args[0] is second array
        (
            inp,
            args.first()
                .ok_or_else(|| crate::safety::arg_err("zip requires second array argument"))?
                .clone(),
        )
    } else {
        // Not piped: args[0] is first array, args[1] is second array
        (
            args.first()
                .ok_or_else(|| crate::safety::arg_err("zip requires two array arguments"))?
                .clone(),
            args.get(1)
                .ok_or_else(|| crate::safety::arg_err("zip requires two array arguments"))?
                .clone(),
        )
    };

    let arr1 = expect_array("zip", &arr1_val)?;
    let arr2 = expect_array("zip", &arr2_val)?;
    let mut result = Vec::new();

    for (a, b) in arr1.iter().zip(arr2.iter()) {
        result.push(Value::Array(vec![a.clone(), b.clone()]));
    }

    Ok(Value::Array(result))
}

/// push(item) - Add item to end of array
/// Args:
///   - item: Any - Item to add
/// Returns: Array - Array with item added
///
/// Example:
///   [1,2,3] | push(4)     # Returns [1,2,3,4]
fn bi_push(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (arr_val, item) = if let Some(inp) = input {
        // Piped: input is array, args[0] is item
        (
            inp,
            args.first()
                .ok_or_else(|| crate::safety::arg_err("push requires item argument"))?,
        )
    } else {
        // Not piped: args[0] is array, args[1] is item
        (
            args.first()
                .ok_or_else(|| crate::safety::arg_err("push requires array input"))?
                .clone(),
            args.get(1)
                .ok_or_else(|| crate::safety::arg_err("push requires item argument"))?,
        )
    };

    let mut arr = expect_array("push", &arr_val)?.to_vec();
    arr.push(item.clone());
    Ok(Value::Array(arr))
}

/// concat(array2) - Concatenate two arrays
/// Args:
///   - array2: Array - Array to concatenate
/// Returns: Array - Combined array
///
/// Example:
///   [1,2,3] | concat([4,5,6])     # Returns [1,2,3,4,5,6]
fn bi_concat(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (arr1_val, arr2_val) = if let Some(inp) = input {
        // Piped: input is first array, args[0] is second array
        (
            inp,
            args.first()
                .ok_or_else(|| crate::safety::arg_err("concat requires second array argument"))?
                .clone(),
        )
    } else {
        // Not piped: args[0] is first array, args[1] is second array
        (
            args.first()
                .ok_or_else(|| crate::safety::arg_err("concat requires two array arguments"))?
                .clone(),
            args.get(1)
                .ok_or_else(|| crate::safety::arg_err("concat requires two array arguments"))?
                .clone(),
        )
    };

    let mut arr1 = expect_array("concat", &arr1_val)?.to_vec();
    let arr2 = expect_array("concat", &arr2_val)?;
    arr1.extend(arr2.iter().cloned());

    Ok(Value::Array(arr1))
}

// ==================== Math Functions ====================

/// abs(number?) - Get absolute value
/// Args:
///   - number: Number (optional if piped)
/// Returns: Number - Absolute value
///
/// Example:
///   abs(-5)     # Returns 5
fn bi_abs(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if args.is_empty() {
        input.ok_or_else(|| crate::safety::arg_err("abs requires number argument"))?
    } else {
        args[0].clone()
    };

    match val {
        Value::Int(n) => Ok(Value::Int(n.abs())),
        Value::Float(f) => Ok(Value::Float(f.abs())),
        _ => Err(crate::safety::arg_err("abs requires numeric input")),
    }
}

/// min(a, b) - Get minimum of two numbers
/// Args:
///   - a: Number
///   - b: Number
/// Returns: Number - Minimum value
///
/// Example:
///   min(3, 7)     # Returns 3
/// The array `min`/`max` should aggregate over, if this is the aggregate form.
///
/// Both builtins were binary-only: `min(a, b)`. The ontology advertised them
/// under `Aggregation` as "Get minimum value" / "Get maximum value" with an
/// empty parameter list, so an agent reading the ontology writes `max(xs)` or
/// `xs | max` and is told "max requires two arguments" -- a discovery surface
/// describing a function that does not exist. The aggregate form is accepted
/// here; the two-number form below is untouched.
fn aggregate_operand<'a>(args: &'a [Value], input: &'a Option<Value>) -> Option<&'a Vec<Value>> {
    match (args.first(), args.len()) {
        (Some(Value::Array(items)), 1) => Some(items),
        (None, _) => match input {
            Some(Value::Array(items)) => Some(items),
            _ => None,
        },
        _ => None,
    }
}

/// Largest (`want_max`) or smallest element of a numeric array.
fn fold_extremum(items: &[Value], want_max: bool) -> Result<Value> {
    if items.is_empty() {
        return Err(crate::safety::arg_err(if want_max {
            "max of an empty array is undefined"
        } else {
            "min of an empty array is undefined"
        }));
    }
    // Stay in Int while every element is one, so `[1, 5, 3] | max` is `5` and
    // not `5.0`: an agent comparing the answer to a literal should not have to
    // know whether the aggregate silently promoted.
    let all_int = items.iter().all(|v| matches!(v, Value::Int(_)));
    let mut best: Option<f64> = None;
    for v in items {
        let n = match v {
            Value::Int(i) => *i as f64,
            Value::Float(f) => *f,
            other => {
                return Err(crate::safety::arg_err(&format!(
                    "{} requires numeric elements, found {}",
                    if want_max { "max" } else { "min" },
                    other.type_name()
                )))
            }
        };
        best = Some(match best {
            None => n,
            Some(b) if want_max => b.max(n),
            Some(b) => b.min(n),
        });
    }
    let b = best.expect("non-empty array yields a value");
    Ok(if all_int {
        Value::Int(b as i64)
    } else {
        Value::Float(b)
    })
}

fn bi_min(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if let Some(items) = aggregate_operand(&args, &input) {
        return fold_extremum(items, false);
    }
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "min requires two numbers, one array, or a piped array",
        ));
    }

    match (&args[0], &args[1]) {
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(*a.min(b))),
        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a.min(*b))),
        (Value::Int(a), Value::Float(b)) => Ok(Value::Float((*a as f64).min(*b))),
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a.min(*b as f64))),
        _ => Err(crate::safety::arg_err("min requires numeric arguments")),
    }
}

/// max(a, b) - Get maximum of two numbers
/// Args:
///   - a: Number
///   - b: Number
/// Returns: Number - Maximum value
///
/// Example:
///   max(3, 7)     # Returns 7
fn bi_max(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if let Some(items) = aggregate_operand(&args, &input) {
        return fold_extremum(items, true);
    }
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "max requires two numbers, one array, or a piped array",
        ));
    }

    match (&args[0], &args[1]) {
        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(*a.max(b))),
        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a.max(*b))),
        (Value::Int(a), Value::Float(b)) => Ok(Value::Float((*a as f64).max(*b))),
        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a.max(*b as f64))),
        _ => Err(crate::safety::arg_err("max requires numeric arguments")),
    }
}

/// floor(number) - Round down to nearest integer
/// Args:
///   - number: Number
/// Returns: Int - Rounded down value
///
/// Example:
///   floor(3.7)     # Returns 3
fn bi_floor(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if args.is_empty() {
        input.ok_or_else(|| crate::safety::arg_err("floor requires number argument"))?
    } else {
        args[0].clone()
    };

    match val {
        Value::Int(n) => Ok(Value::Int(n)),
        Value::Float(f) => Ok(Value::Int(f.floor() as i64)),
        _ => Err(crate::safety::arg_err("floor requires numeric input")),
    }
}

/// ceil(number) - Round up to nearest integer
/// Args:
///   - number: Number
/// Returns: Int - Rounded up value
///
/// Example:
///   ceil(3.2)     # Returns 4
fn bi_ceil(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if args.is_empty() {
        input.ok_or_else(|| crate::safety::arg_err("ceil requires number argument"))?
    } else {
        args[0].clone()
    };

    match val {
        Value::Int(n) => Ok(Value::Int(n)),
        Value::Float(f) => Ok(Value::Int(f.ceil() as i64)),
        _ => Err(crate::safety::arg_err("ceil requires numeric input")),
    }
}

/// round(number) - Round to nearest integer
/// Args:
///   - number: Number
/// Returns: Int - Rounded value
///
/// Example:
///   round(3.5)     # Returns 4
fn bi_round(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // In a pipeline the piped value is the subject and the arguments are
    // parameters -- `xs | map(f)`, `xs | nth(2)`. `round` inherited the unary
    // convention "first argument if present, else the input", so
    // `mean | round(2)` took 2 as the number to round and answered 2. It is
    // the same defect as discarding `digits`, wearing a pipe.
    let piped_subject = input.is_some() && args.len() == 1;
    let (val, digit_arg) = if piped_subject {
        (input.clone().expect("checked"), args.first())
    } else if args.is_empty() {
        (
            input.ok_or_else(|| crate::safety::arg_err("round requires number argument"))?,
            None,
        )
    } else {
        (args[0].clone(), args.get(1))
    };

    // `round(x, digits)` used to parse, run, and silently discard `digits`:
    // `round(4.966, 2)` answered `5`. A wrong number returned without an error
    // is the worst shape a failure can take for an agent, because nothing in
    // the result says to look again. Absent or zero `digits` keeps the old
    // Int-returning behaviour exactly.
    let digits = match digit_arg {
        None => None,
        Some(Value::Int(d)) if (0..=17).contains(d) => Some(*d as u32),
        Some(other) => {
            return Err(crate::safety::arg_err(&format!(
                "round: digits must be an integer in 0..=17, got {}",
                other.type_name()
            )))
        }
    };

    match (val, digits) {
        (Value::Int(n), _) => Ok(Value::Int(n)),
        (Value::Float(f), None) | (Value::Float(f), Some(0)) => Ok(Value::Int(f.round() as i64)),
        (Value::Float(f), Some(d)) => {
            let scale = 10f64.powi(d as i32);
            Ok(Value::Float((f * scale).round() / scale))
        }
        _ => Err(crate::safety::arg_err("round requires numeric input")),
    }
}

/// sqrt(number) - Calculate square root
/// Args:
///   - number: Number
/// Returns: Float - Square root
///
/// Example:
///   sqrt(16)     # Returns 4.0
fn bi_sqrt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if args.is_empty() {
        input.ok_or_else(|| crate::safety::arg_err("sqrt requires number argument"))?
    } else {
        args[0].clone()
    };

    let num = match val {
        Value::Int(n) => n as f64,
        Value::Float(f) => f,
        _ => return Err(crate::safety::arg_err("sqrt requires numeric input")),
    };

    if num < 0.0 {
        return Err(crate::safety::arg_err("sqrt requires non-negative number"));
    }

    Ok(Value::Float(num.sqrt()))
}

/// pow(base, exponent) - Calculate power
/// Args:
///   - base: Number
///   - exponent: Number
/// Returns: Number - base ^ exponent
///
/// Example:
///   pow(2, 8)     # Returns 256
fn bi_pow(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "pow requires two arguments: base and exponent",
        ));
    }

    let base = match &args[0] {
        Value::Int(n) => *n as f64,
        Value::Float(f) => *f,
        _ => return Err(crate::safety::arg_err("pow requires numeric base")),
    };

    let exp = match &args[1] {
        Value::Int(n) => *n as f64,
        Value::Float(f) => *f,
        _ => return Err(crate::safety::arg_err("pow requires numeric exponent")),
    };

    let result = base.powf(exp);

    // Return Int if result is a whole number and both inputs were Int
    if matches!((&args[0], &args[1]), (Value::Int(_), Value::Int(_))) && result.fract() == 0.0 {
        Ok(Value::Int(result as i64))
    } else {
        Ok(Value::Float(result))
    }
}

// ==================== Utility Functions ====================

/// exit(code?) - Exit the shell process with a status.
/// Args:
///   - code: Int (optional) - 0..=255, default 0
/// Returns: never; the process ends
///
/// A code outside 0..=255 was truncated by the OS (256 exited 0, -1 exited
/// 255), and pipeline input and surplus arguments were dropped. All three are
/// refused before anything ends.
///
/// Example:
///   exit(0)     # Exit with success
fn bi_exit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("exit", &input)?;
    if args.len() > 1 {
        return Err(crate::safety::bad_arg(
            "exit",
            "at most one argument, the exit code",
            &format!("{} arguments", args.len()),
        ));
    }
    let code = match args.first() {
        None => 0,
        Some(Value::Int(n)) if (0..=255).contains(n) => *n as i32,
        Some(Value::Int(n)) => {
            return Err(crate::safety::bad_arg(
                "exit",
                "code: Int 0..=255",
                &n.to_string(),
            ))
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "exit",
                "code: Int 0..=255",
                other.type_name(),
            ))
        }
    };
    std::process::exit(code);
}

/// env(key) - Get environment variable
/// Args:
///   - key: String - Environment variable name
/// Returns: String or Null - Variable value or null if not set
///
/// Example:
///   env("HOME")     # Returns home directory path
fn bi_env(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "env requires variable name argument",
        ));
    }

    let key = expect_string("env", &args[0])?;
    match env_read("env", key, std::env::var(key))? {
        Some(val) => Ok(gate_env_secret(key, val)),
        // `env(name, default)` returns `default` when the variable is unset.
        //
        // The second argument used to be accepted and discarded, so an unset
        // variable was always `null` — the same defect shape as `round(x, n)`
        // ignoring `n`. It matters most in bash compatibility mode, where
        // `echo $NOPE` must print an empty line as bash does, not the word
        // "null".
        None => Ok(args.get(1).cloned().unwrap_or(Value::Null)),
    }
}

/// Gate an env-var read against the secret policy (§7.6): in agent mode, reading
/// a secret-named var (e.g. `*_KEY`, `*TOKEN*`) returns an opaque
/// `[REDACTED:NAME]` handle instead of the value, so the credential never enters
/// the program's value space — unless `AETHER_SECRETS=allow`. Human mode and
/// non-secret names return the value unchanged.
fn gate_env_secret(key: &str, val: String) -> Value {
    if crate::safety::env_secret_gated(key) {
        Value::Str(format!("[REDACTED:{}]", key))
    } else {
        Value::Str(val)
    }
}

/// set_env(key, value) - Set environment variable
/// Args:
///   - key: String - Environment variable name
///   - value: String - Value to set
/// Returns: Null
///
/// Example:
///   set_env("MY_VAR", "value")
fn bi_set_env(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "set_env";
    k8s_no_input(B, &input)?;
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "set_env requires key and value arguments",
        ));
    }
    let key = env_name(B, &args[0])?;
    refuse_gate_env(B, &key)?;
    let value = env_value(B, &args[1])?;
    std::env::set_var(key, value);
    Ok(Value::Null)
}

/// An environment variable name. `set_var` panics on an empty name, one with
/// '=' or NUL, and a value with NUL, so each is refused here as E_BAD_ARG.
fn env_name(builtin: &str, value: &Value) -> Result<String> {
    let name = expect_string(builtin, value)?;
    if name.is_empty() || name.len() > 1024 || name.contains(['=', '\0']) {
        return Err(crate::safety::bad_arg(
            builtin,
            "a name of 1 to 1024 bytes with no '=' and no NUL",
            &format!("{name:?}"),
        ));
    }
    Ok(name.to_string())
}

/// An environment variable value: a string with no NUL, at most 32767 bytes
/// (the Windows limit per variable).
fn env_value(builtin: &str, value: &Value) -> Result<String> {
    let text = expect_string(builtin, value)?;
    if text.contains('\0') || text.len() > 32_767 {
        return Err(crate::safety::bad_arg(
            builtin,
            "a value of at most 32767 bytes with no NUL",
            "a value that is too long or has NUL",
        ));
    }
    Ok(text.to_string())
}

/// Refuse, in agent mode, any change to an `AETHER_*` variable.
///
/// The approval gate and its mode switch are read from the process
/// environment on every call: `AETHER_MODE`/`AETHER_AGENT` decide whether
/// `approve()` is refused, `AETHER_APPROVE`/`AETHER_APPROVE_ALL` decide whether a
/// gated call (including `apply`) is approved, and `AETHER_POLICY`,
/// `AETHER_WORKSPACE` and the `AETHER_MAX_*` budgets decide the rest. An agent
/// that could set or unset those through `set_env`/`env_set`/`env_unset` (all
/// classified WriteLocal, so allowed in agent mode) could approve its own plan
/// or switch the gate off. Fail closed: the agent may not touch them. Human
/// mode is unchanged.
fn refuse_gate_env(builtin: &str, name: &str) -> Result<()> {
    if crate::safety::current_mode() == crate::safety::Mode::Agent
        && name.to_ascii_uppercase().starts_with("AETHER_")
    {
        return Err(crate::safety::policy_deny(
            builtin,
            format!("{builtin}: an agent may not change the approval gate's environment ({name})"),
            "AETHER_* variables are set by whoever launches the agent, not by the agent",
        ));
    }
    Ok(())
}

/// sleep(seconds) - Sleep for specified duration
/// Args:
///   - seconds: Number - Duration to sleep
/// Returns: Null
///
/// Example:
///   sleep(2)     # Sleep for 2 seconds
fn bi_sleep(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("sleep requires duration argument"));
    }

    let seconds = match &args[0] {
        Value::Int(n) => *n as f64,
        Value::Float(f) => *f,
        _ => return Err(crate::safety::arg_err("sleep requires numeric duration")),
    };

    let duration = Duration::try_from_secs_f64(seconds).map_err(|_| {
        crate::safety::arg_err("sleep: duration must be finite, non-negative and representable")
    })?;
    // A sleep may not outlast the evaluation deadline. Sleeping only what is
    // left and then failing tells the caller the time was cut short, rather
    // than returning Null for a wait that did not happen in full.
    if let Some(left) = crate::safety::remaining_deadline() {
        if left < duration {
            let message = if left.is_zero() {
                format!("sleep of {seconds} s refused: the evaluation deadline has already expired")
            } else {
                std::thread::sleep(left);
                format!("sleep of {seconds} s cut short by the evaluation deadline after {left:?}")
            };
            return Err(crate::safety::budget_exceeded(
                "sleep",
                message,
                "ask for a shorter sleep, or allow a longer evaluation time limit",
            ));
        }
    }
    std::thread::sleep(duration);
    Ok(Value::Null)
}

/// time() - Get current Unix timestamp
/// Returns: Int - Current Unix timestamp in seconds
///
/// Example:
///   time()     # Returns 1699401234
fn bi_time(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // `now` and `time` are one clock under two names, declared identically
    // in the ontology; one implementation keeps them from drifting apart.
    bi_now(args, input)
}

/// json_parse(json_string?) - Parse JSON string into value
/// Args:
///   - json_string: String (optional if piped)
/// Returns: Any - Parsed JSON value
///
/// Example:
///   json_parse("{\"a\":1}")     # Returns {a: 1}
fn bi_json_parse(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let json_str = if args.is_empty() {
        let input_val =
            input.ok_or_else(|| crate::safety::arg_err("json_parse requires JSON string"))?;
        expect_string("json_parse", &input_val)?.to_string()
    } else {
        expect_string("json_parse", &args[0])?.to_string()
    };

    let json_val: serde_json::Value = serde_json::from_str(&json_str)
        .map_err(|e| crate::safety::bad_arg("json_parse", "valid JSON", &e.to_string()))?;

    Ok(json_to_value(json_val))
}

/// json_stringify(value?) - Convert value to JSON string
/// Args:
///   - value: Any (optional if piped)
/// Returns: String - JSON representation
///
/// Example:
///   {a: 1} | json_stringify()     # Returns "{\"a\":1}"
fn bi_json_stringify(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if args.is_empty() {
        input.ok_or_else(|| crate::safety::arg_err("json_stringify requires value"))?
    } else {
        args[0].clone()
    };

    let json_val = value_to_json(val);
    let json_str = serde_json::to_string(&json_val).context("Failed to stringify to JSON")?;

    Ok(Value::Str(json_str))
}

// ==================== Syntax Knowledge Base Functions ====================

use crate::syntax_kb::{AgenticBinary, SyntaxCategory, SyntaxEntry, SyntaxKB};
use std::sync::{Mutex, OnceLock};

// Global syntax knowledge base
static SYNTAX_KB: OnceLock<Mutex<SyntaxKB>> = OnceLock::new();

fn get_syntax_kb() -> &'static Mutex<SyntaxKB> {
    SYNTAX_KB.get_or_init(|| {
        // Try to load from ~/.aethershell/syntax_kb.json
        let home = std::env::var("HOME")
            .or_else(|_| std::env::var("USERPROFILE"))
            .unwrap_or_else(|_| ".".to_string());
        let storage_path = std::path::PathBuf::from(home)
            .join(".aethershell")
            .join("syntax_kb.json");

        // Create directory if it doesn't exist
        if let Some(parent) = storage_path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }

        let kb = SyntaxKB::with_storage(storage_path).unwrap_or_else(|_| SyntaxKB::new());
        Mutex::new(kb)
    })
}

/// syntax_get(id) - Get syntax entry by ID
/// Args:
///   - id: String - Syntax ID
/// Returns: Record - Syntax entry details
///
/// Example:
///   syntax_get("ab")  # Returns AgenticBinary protocol details
fn bi_syntax_get(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let id_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("syntax_get requires syntax ID"))?;
    let id = expect_string("syntax_get", &id_val)?;

    let kb = get_syntax_kb().lock().unwrap();
    let entry = kb
        .get(id)
        .ok_or_else(|| crate::safety::not_found("syntax_get", "syntax", id))?;

    // Convert to Value::Record
    let mut fields = std::collections::BTreeMap::new();
    fields.insert("id".to_string(), Value::Str(entry.id.clone()));
    fields.insert("name".to_string(), Value::Str(entry.name.clone()));
    fields.insert(
        "category".to_string(),
        Value::Str(format!("{:?}", entry.category)),
    );
    fields.insert(
        "specification".to_string(),
        Value::Str(entry.specification.clone()),
    );
    fields.insert(
        "examples".to_string(),
        Value::Array(
            entry
                .examples
                .iter()
                .map(|s| Value::Str(s.clone()))
                .collect(),
        ),
    );

    if let Some(enc) = &entry.binary_encoding {
        let mut enc_fields = std::collections::BTreeMap::new();
        enc_fields.insert("name".to_string(), Value::Str(enc.name.clone()));
        enc_fields.insert("bit_layout".to_string(), Value::Str(enc.bit_layout.clone()));
        fields.insert("binary_encoding".to_string(), Value::Record(enc_fields));
    }

    Ok(Value::Record(fields))
}

/// syntax_list(category?) - List all syntax entries or by category
/// Args:
///   - category: String (optional) - Category to filter by
/// Returns: Array - List of syntax IDs
///
/// Example:
///   syntax_list()           # Returns all syntax IDs
///   syntax_list("protocol") # Returns protocol syntax IDs
fn bi_syntax_list(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let kb = get_syntax_kb().lock().unwrap();

    let ids = if let Some(cat_val) = input.or_else(|| args.first().cloned()) {
        let category_str = expect_string("syntax_list", &cat_val)?;
        let category = match category_str.to_lowercase().as_str() {
            "protocol" => SyntaxCategory::Protocol,
            "language" => SyntaxCategory::Language,
            "encoding" => SyntaxCategory::Encoding,
            "command" => SyntaxCategory::Command,
            "query" => SyntaxCategory::Query,
            other => SyntaxCategory::Custom(other.to_string()),
        };

        kb.list_by_category(&category)
            .iter()
            .map(|e| Value::Str(e.id.clone()))
            .collect()
    } else {
        kb.list_all_ids()
            .iter()
            .map(|id| Value::Str(id.clone()))
            .collect()
    };

    Ok(Value::Array(ids))
}

/// syntax_search(query) - Search syntax entries by keyword
/// Args:
///   - query: String - Search query
/// Returns: Array - Matching syntax IDs
///
/// Example:
///   syntax_search("binary")  # Finds entries with "binary" in name/spec
fn bi_syntax_search(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let query_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("syntax_search requires query string"))?;
    let query = expect_string("syntax_search", &query_val)?;

    let kb = get_syntax_kb().lock().unwrap();
    let results: Vec<Value> = kb
        .search(query)
        .iter()
        .map(|e| Value::Str(e.id.clone()))
        .collect();

    Ok(Value::Array(results))
}

/// syntax_add(entry_record) - Add a new syntax entry
/// Args:
///   - entry_record: Record - Syntax entry with id, name, category, specification
/// Returns: Bool - Success status
///
/// Example:
///   syntax_add({id: "mysyntax", name: "My Syntax", category: "custom", specification: "..."})
fn bi_syntax_add(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "syntax_add";
    // The entry comes either piped or as the argument, never both: the piped
    // form used to win and drop the argument without a word.
    let entry_val = match (input, args.as_slice()) {
        (Some(piped), []) => piped,
        (None, [direct]) => direct.clone(),
        (Some(_), [_, ..]) => {
            return Err(crate::safety::arg_err(
                "syntax_add takes its entry piped or as its argument, not both",
            ))
        }
        (None, []) => return Err(crate::safety::arg_err("syntax_add requires entry record")),
        (None, _) => return Err(crate::safety::arg_err("syntax_add takes one entry record")),
    };

    let record = match entry_val {
        Value::Record(r) => r,
        other => {
            return Err(crate::safety::bad_arg(
                B,
                "entry: Record",
                other.type_name(),
            ))
        }
    };
    // A misspelt field (`exmples`) used to be dropped, and the entry saved
    // without it.
    if let Some(unknown) = record.keys().find(|k| {
        !matches!(
            k.as_str(),
            "id" | "name" | "category" | "specification" | "examples"
        )
    }) {
        return Err(crate::safety::bad_arg(
            B,
            "a Record with only the fields id, name, category, specification, examples",
            &format!("the field {unknown:?}"),
        ));
    }

    // A present field of the wrong type is refused; an absent one falls to its
    // default or to the required-field message below.
    let text_field = |key: &str| -> Result<Option<String>> {
        match record.get(key) {
            None => Ok(None),
            Some(Value::Str(s)) => Ok(Some(s.clone())),
            Some(other) => Err(crate::safety::bad_arg(
                B,
                &format!("{key}: String"),
                other.type_name(),
            )),
        }
    };
    let id = text_field("id")?
        .ok_or_else(|| crate::safety::arg_err("syntax_add requires 'id' field"))?;
    let well_formed_id = !id.is_empty()
        && id.len() <= 128
        && id
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.'));
    if !well_formed_id {
        return Err(crate::safety::bad_arg(
            B,
            "id: 1 to 128 letters, digits, '_', '-' or '.'",
            &format!("{id:?}"),
        ));
    }
    let name = text_field("name")?
        .ok_or_else(|| crate::safety::arg_err("syntax_add requires 'name' field"))?;
    if name.trim().is_empty() {
        return Err(crate::safety::bad_arg(
            B,
            "name: a non-blank String",
            "a blank name",
        ));
    }
    let category_str = text_field("category")?.unwrap_or_else(|| "custom".to_string());
    let category = match category_str.to_lowercase().as_str() {
        "protocol" => SyntaxCategory::Protocol,
        "language" => SyntaxCategory::Language,
        "encoding" => SyntaxCategory::Encoding,
        "command" => SyntaxCategory::Command,
        "query" => SyntaxCategory::Query,
        "" => {
            return Err(crate::safety::bad_arg(
                B,
                "category: a nonblank String",
                "an empty category",
            ))
        }
        other => SyntaxCategory::Custom(other.to_string()),
    };
    let specification = text_field("specification")?
        .ok_or_else(|| crate::safety::arg_err("syntax_add requires 'specification' field"))?;

    let examples: Vec<String> = match record.get("examples") {
        None => Vec::new(),
        Some(Value::Array(arr)) => arr
            .iter()
            .map(|v| match v {
                Value::Str(s) => Ok(s.clone()),
                other => Err(crate::safety::bad_arg(
                    B,
                    "examples: Array of String",
                    other.type_name(),
                )),
            })
            .collect::<Result<_>>()?,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "examples: Array of String",
                other.type_name(),
            ))
        }
    };

    let entry = SyntaxEntry {
        id: id.clone(),
        name,
        category,
        specification,
        examples,
        binary_encoding: None,
        metadata: std::collections::HashMap::new(),
    };

    let mut kb = get_syntax_kb().lock().map_err(|_| {
        crate::safety::bad_state(
            B,
            "the syntax knowledge base is poisoned by an earlier failure",
            "syntax_list",
        )
    })?;
    // add_entry replaces an entry with the same id and lists the id twice in
    // its category, so an existing id is refused rather than overwritten.
    if kb.get(&id).is_some() {
        return Err(crate::safety::bad_arg(
            B,
            "an id not yet in the syntax knowledge base",
            &format!("the existing id {id:?}"),
        ));
    }
    kb.add_entry(entry).map_err(|e| {
        crate::safety::fs_error(B, "syntax_kb.json", &std::io::Error::other(e.to_string()))
    })?;

    Ok(Value::Bool(true))
}

/// syntax_categories() - List all available syntax categories
/// Returns: Array - List of category names
///
/// Example:
///   syntax_categories()  # Returns ["protocol", "language", ...]
fn bi_syntax_categories(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let kb = get_syntax_kb().lock().unwrap();
    let categories: Vec<Value> = kb
        .list_categories()
        .iter()
        .map(|c| Value::Str(c.clone()))
        .collect();

    Ok(Value::Array(categories))
}

/// ab_encode(msg_type, opcode, payload) - Encode message using AgenticBinary protocol
/// Args:
///   - msg_type: String or Int - Message type (Command/Query/Response/Event or 0-3)
///   - opcode: String or Int - Opcode name or number (0-15)
///   - payload: String - Payload data
/// Returns: Array - Encoded bytes
///
/// Example:
///   ab_encode("Query", "DATA", "hello")  # Encodes AgenticBinary message
///   ab_encode(1, 4, "hello")             # Same using numeric codes
fn bi_ab_encode(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 3 {
        return Err(crate::safety::arg_err(
            "ab_encode requires 3 arguments: msg_type, opcode, payload",
        ));
    }

    // Parse message type
    let msg_type = match &args[0] {
        Value::Int(i) if (0..=3).contains(i) => *i as u8,
        Value::Str(s) => match s.to_lowercase().as_str() {
            "command" | "cmd" => 0,
            "query" => 1,
            "response" | "resp" => 2,
            "event" => 3,
            _ => return Err(crate::safety::arg_err(format!("Invalid message type: {s}"))),
        },
        _ => return Err(crate::safety::arg_err("msg_type must be String or Int")),
    };

    // Parse opcode
    let opcode = match &args[1] {
        Value::Int(i) if (0..=15).contains(i) => *i as u8,
        Value::Str(s) => match s.to_uppercase().as_str() {
            "PING" => 0x0,
            "ACK" => 0x1,
            "QUERY" => 0x2,
            "EXEC" => 0x3,
            "DATA" => 0x4,
            "ERROR" => 0x5,
            "SYNC" => 0x6,
            "AUTH" => 0x7,
            "DELEGATE" => 0x8,
            "COLLABORATE" => 0x9,
            "LEARN" => 0xA,
            "REASON" => 0xB,
            "PLAN" => 0xC,
            "OBSERVE" => 0xD,
            "REFLECT" => 0xE,
            "EXTEND" => 0xF,
            _ => return Err(crate::safety::arg_err(format!("Invalid opcode: {s}"))),
        },
        _ => return Err(crate::safety::arg_err("opcode must be String or Int")),
    };

    // Get payload
    let payload = expect_string("ab_encode", &args[2])?;

    // Encode using AgenticBinary (version 0)
    let encoded = AgenticBinary::encode(0, msg_type, opcode, payload.as_bytes())?;

    // Convert to Value::Array of Int values
    let result: Vec<Value> = encoded.iter().map(|&b| Value::Int(b as i64)).collect();

    Ok(Value::Array(result))
}

/// ab_decode(bytes) - Decode AgenticBinary message
/// Args:
///   - bytes: Array - Byte array to decode
/// Returns: Record - Decoded message with version, msg_type, opcode, payload
///
/// Example:
///   ab_decode([20, 5, 104, 101, 108, 108, 111])  # Decodes to record
fn bi_ab_decode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let bytes_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("ab_decode requires byte array"))?;

    let bytes_arr = expect_array("ab_decode", &bytes_val)?;
    let bytes: Vec<u8> = bytes_arr
        .iter()
        .map(|v| match v {
            Value::Int(i) if (0..=255).contains(i) => Ok(*i as u8),
            _ => Err(crate::safety::arg_err(
                "Byte array must contain integers in 0..255",
            )),
        })
        .collect::<Result<Vec<u8>>>()?;

    let (version, msg_type, opcode, payload) = AgenticBinary::decode(&bytes)
        .map_err(|error| crate::safety::arg_err(format!("ab_decode: {error}")))?;

    let mut result = std::collections::BTreeMap::new();
    result.insert("version".to_string(), Value::Int(version as i64));
    result.insert(
        "msg_type".to_string(),
        Value::Str(AgenticBinary::msg_type_name(msg_type).to_string()),
    );
    result.insert("msg_type_code".to_string(), Value::Int(msg_type as i64));
    result.insert(
        "opcode".to_string(),
        Value::Str(AgenticBinary::opcode_name(opcode).to_string()),
    );
    result.insert("opcode_code".to_string(), Value::Int(opcode as i64));
    result.insert(
        "payload".to_string(),
        Value::Str(String::from_utf8_lossy(&payload).to_string()),
    );
    result.insert(
        "payload_bytes".to_string(),
        Value::Array(payload.iter().map(|&b| Value::Int(b as i64)).collect()),
    );

    Ok(Value::Record(result))
}

// --------------- Neural Network Builtins ---------------

/// nn_create(name, layer_sizes, [hidden_activation], [output_activation])
/// Creates a feedforward neural network
/// Args:
///   - name: String - Network name/identifier
///   - layer_sizes: Array[Int] - Sizes of each layer [input, hidden..., output]
///   - hidden_activation: String (optional) - "relu", "sigmoid", "tanh", "swish" (default: "relu")
///   - output_activation: String (optional) - activation for output layer (default: "tanh")
/// Returns: Record - Network representation
///
/// Example:
///   nn_create("policy", [8, 16, 8, 4])  # 8 inputs, 2 hidden layers, 4 outputs
fn bi_nn_create(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "nn_create requires at least name and layer_sizes",
        ));
    }

    let name = expect_string("nn_create", &args[0])?;
    let layer_sizes_val = args
        .get(1)
        .ok_or_else(|| crate::safety::arg_err("nn_create requires layer_sizes array"))?;
    let layer_sizes_arr = expect_array("nn_create", layer_sizes_val)?;

    let layer_sizes: Vec<usize> = layer_sizes_arr
        .iter()
        .map(|v| {
            let n = match v {
                Value::Int(n) => *n,
                other => {
                    return Err(crate::safety::bad_arg(
                        "nn_create",
                        "layer size: Int",
                        other.type_name(),
                    ))
                }
            };
            usize::try_from(n).ok().filter(|&n| n > 0).ok_or_else(|| {
                crate::safety::arg_err("nn_create: layer sizes must be positive integers")
            })
        })
        .collect::<Result<Vec<_>>>()?;

    if layer_sizes.len() < 2 {
        return Err(crate::safety::arg_err(
            "nn_create requires at least 2 layers (input and output)",
        ));
    }

    let mut count = 0usize;
    for sizes in layer_sizes.windows(2) {
        count = checked_nn_parameter_count(count, sizes[0], sizes[1])?;
    }
    let parse_activation = |value: &Value| {
        let name = expect_string("nn_create", value)?;
        Activation::from_str(name).ok_or_else(|| {
            crate::safety::bad_arg(
                "nn_create",
                "relu, sigmoid, tanh, softmax, linear, swish or leaky_relu",
                name,
            )
        })
    };
    let hidden_activation = args
        .get(2)
        .map(parse_activation)
        .transpose()?
        .unwrap_or(Activation::ReLU);
    let output_activation = args
        .get(3)
        .map(parse_activation)
        .transpose()?
        .unwrap_or(Activation::Tanh);

    let network =
        NeuralNetwork::feedforward(name, &layer_sizes, hidden_activation, output_activation);
    nn_to_value(&network)
}

/// nn_forward(network, input)
/// Forward pass through the network
/// Args:
///   - network: Record - Network from nn_create
///   - input: Array[Float] - Input values
/// Returns: Array[Float] - Output values
fn bi_nn_forward(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let has_input = input.is_some();
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_forward requires network"))?;

    let network = value_to_nn(&network_val)?;

    let input_val = args
        .get(if has_input { 0 } else { 1 })
        .ok_or_else(|| crate::safety::arg_err("nn_forward requires input array"))?;
    let input_arr = expect_array("nn_forward", input_val)?;

    let input_vec: Vec<f64> = input_arr
        .iter()
        .map(|v| finite_nn_number("nn_forward", v))
        .collect::<Result<Vec<_>>>()?;
    if input_vec.len() != network.layers[0].input_size {
        return Err(crate::safety::arg_err(
            "nn_forward: input length must equal the network input size",
        ));
    }
    let output = network.forward(&input_vec);
    if output.iter().any(|n| !n.is_finite()) {
        return Err(crate::safety::bad_state(
            "nn_forward",
            "non-finite output",
            "the computation exceeded the numeric range",
        ));
    }
    Ok(Value::Array(output.into_iter().map(Value::Float).collect()))
}

/// nn_mutate(network, rate, strength)
/// Mutate network parameters
/// Args:
///   - network: Record - Network to mutate
///   - rate: Float - Mutation probability (0.0-1.0)
///   - strength: Float - Mutation magnitude
/// Returns: Record - Mutated network
fn bi_nn_mutate(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let has_input = input.is_some();
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_mutate requires network"))?;

    let network = value_to_nn(&network_val)?;

    let idx = if has_input { 0 } else { 1 };
    let rate = args
        .get(idx)
        .map(|v| finite_nn_number("nn_mutate", v))
        .transpose()?
        .unwrap_or(0.1);
    let strength = args
        .get(idx + 1)
        .map(|v| finite_nn_number("nn_mutate", v))
        .transpose()?
        .unwrap_or(0.3);

    if !(0.0..=1.0).contains(&rate) || strength < 0.0 {
        return Err(crate::safety::arg_err(
            "nn_mutate: rate must be in 0..=1 and strength non-negative",
        ));
    }
    let mutated = network.mutate(rate, strength);
    validate_nn(&mutated)?;
    nn_to_value(&mutated)
}

/// nn_crossover(network1, network2)
/// Crossover two networks
/// Args:
///   - network1: Record - First parent network
///   - network2: Record - Second parent network
/// Returns: Record - Child network
fn bi_nn_crossover(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err("nn_crossover requires two networks"));
    }

    let net1 = value_to_nn(&args[0])?;
    let net2 = value_to_nn(&args[1])?;
    if net1.layers.len() != net2.layers.len()
        || net1
            .layers
            .iter()
            .zip(&net2.layers)
            .any(|(a, b)| a.input_size != b.input_size || a.output_size != b.output_size)
    {
        return Err(crate::safety::arg_err(
            "nn_crossover: parent layer dimensions must match",
        ));
    }
    let child = NeuralNetwork::crossover(&net1, &net2);
    nn_to_value(&child)
}

/// nn_params(network)
/// Get network parameters as flat array
/// Args:
///   - network: Record - Network
/// Returns: Array[Float] - All weights and biases
fn bi_nn_params(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_params requires network"))?;

    let network = value_to_nn(&network_val)?;
    let params = network.get_params();
    Ok(Value::Array(params.into_iter().map(Value::Float).collect()))
}

/// nn_set_params(network, params)
/// Set network parameters from flat array
/// Args:
///   - network: Record - Network
///   - params: Array[Float] - New parameters
/// Returns: Record - Updated network
fn bi_nn_set_params(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let has_input = input.is_some();
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_set_params requires network"))?;

    let mut network = value_to_nn(&network_val)?;

    let idx = if has_input { 0 } else { 1 };
    let params_val = args
        .get(idx)
        .ok_or_else(|| crate::safety::arg_err("nn_set_params requires params array"))?;
    let params_arr = expect_array("nn_set_params", params_val)?;

    let params: Vec<f64> = params_arr
        .iter()
        .map(|v| finite_nn_number("nn_set_params", v))
        .collect::<Result<Vec<_>>>()?;
    if params.len() != network.param_count() {
        return Err(crate::safety::arg_err(
            "nn_set_params: parameter length must equal the network parameter count",
        ));
    }
    network.set_params(&params);
    nn_to_value(&network)
}

/// nn_layers(network)
/// Get layer information
/// Args:
///   - network: Record - Network
/// Returns: Array[Record] - Layer specifications
fn bi_nn_layers(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_layers requires network"))?;

    let network = value_to_nn(&network_val)?;

    let layers: Vec<Value> = network
        .layers
        .iter()
        .map(|layer| {
            let mut rec = BTreeMap::new();
            rec.insert(
                "input_size".to_string(),
                Value::Int(layer.input_size as i64),
            );
            rec.insert(
                "output_size".to_string(),
                Value::Int(layer.output_size as i64),
            );
            rec.insert(
                "activation".to_string(),
                Value::Str(format!("{:?}", layer.activation)),
            );
            rec.insert(
                "param_count".to_string(),
                Value::Int(layer.param_count() as i64),
            );
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(layers))
}

/// nn_info(network)
/// Get network summary information
/// Args:
///   - network: Record - Network
/// Returns: Record - Network info including total params, layer count, etc.
fn bi_nn_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("nn_info requires network"))?;

    let network = value_to_nn(&network_val)?;

    let mut info = BTreeMap::new();
    info.insert("name".to_string(), Value::Str(network.name.clone()));
    info.insert(
        "layer_count".to_string(),
        Value::Int(network.layers.len() as i64),
    );
    info.insert(
        "param_count".to_string(),
        Value::Int(network.param_count() as i64),
    );

    if let Some(first) = network.layers.first() {
        info.insert(
            "input_size".to_string(),
            Value::Int(first.input_size as i64),
        );
    }
    if let Some(last) = network.layers.last() {
        info.insert(
            "output_size".to_string(),
            Value::Int(last.output_size as i64),
        );
    }

    Ok(Value::Record(info))
}

/// consensus_net(name, agent_count, input_size, hidden_size, output_size)
/// Create a consensus network for distributed decision making
/// Args:
///   - name: String - Network name
///   - agent_count: Int - Number of agents
///   - input_size: Int - Input dimension
///   - hidden_size: Int - Hidden layer size
///   - output_size: Int - Output dimension (decision size)
/// Returns: Record - Consensus network
fn bi_consensus_net(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 5 {
        return Err(crate::safety::arg_err(
            "consensus_net requires name, agent_count, input_size, hidden_size, output_size",
        ));
    }

    let name = expect_string("consensus_net", &args[0])?;
    let size = |value: &Value| -> Result<usize> {
        let n = expect_int("consensus_net", value)?;
        usize::try_from(n).ok().filter(|n| *n > 0).ok_or_else(|| {
            crate::safety::arg_err("consensus_net sizes must be positive representable integers")
        })
    };
    let agent_count = size(&args[1])?;
    let input_size = size(&args[2])?;
    let hidden_size = size(&args[3])?;
    let output_size = size(&args[4])?;
    if agent_count > 1024 {
        return Err(crate::safety::budget_exceeded(
            "consensus_net",
            "supports at most 1024 agents".into(),
            "use fewer agents",
        ));
    }
    let twice_input = input_size.checked_mul(2);
    let twice_hidden = hidden_size.checked_mul(2);
    let decision_input = hidden_size.checked_add(input_size);
    let decision_hidden = hidden_size.checked_add(output_size).map(|n| n / 2);
    let dimensions = twice_input
        .zip(twice_hidden)
        .zip(decision_input.zip(decision_hidden))
        .ok_or_else(|| crate::safety::arg_err("consensus_net dimension arithmetic overflow"))?;
    let ((twice_input, twice_hidden), (decision_input, decision_hidden)) = dimensions;
    let mut total = 0;
    for (input, output) in [
        (input_size, twice_input),
        (twice_input, hidden_size),
        (twice_hidden, twice_hidden),
        (twice_hidden, hidden_size),
        (decision_input, decision_hidden),
        (decision_hidden, output_size),
    ] {
        total = checked_nn_parameter_count(total, input, output)?;
    }
    for _ in 0..agent_count {
        total = checked_nn_parameter_count(total, input_size, input_size)?;
        total = checked_nn_parameter_count(total, input_size, hidden_size)?;
    }

    let consensus = ConsensusNetwork::new(name, agent_count, input_size, hidden_size, output_size);
    consensus_net_to_value(&consensus)
}

/// consensus_vote(network, agent_inputs)
/// Run consensus voting across all agents
/// Args:
///   - network: Record - Consensus network
///   - agent_inputs: Array[Array[Float]] - Each agent's input
/// Returns: Record - {decisions: Array[Array], consensus: Array[Float], confidence: Float}
fn bi_consensus_vote(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let has_input = input.is_some();
    let network_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("consensus_vote requires network"))?;

    let mut network = value_to_consensus_net(&network_val)?;

    let idx = if has_input { 0 } else { 1 };
    let inputs_val = args
        .get(idx)
        .ok_or_else(|| crate::safety::arg_err("consensus_vote requires agent_inputs"))?;
    let inputs_arr = expect_array("consensus_vote", inputs_val)?;

    let agent_inputs: Vec<Vec<f64>> = inputs_arr
        .iter()
        .map(|v| {
            let arr = expect_array("consensus_vote", v)?;
            arr.iter()
                .map(|v| finite_nn_number("consensus_vote", v))
                .collect()
        })
        .collect::<Result<Vec<_>>>()?;

    if agent_inputs.len() != network.agent_networks.len()
        || agent_inputs
            .iter()
            .any(|row| row.len() != network.state_dim)
    {
        return Err(crate::safety::arg_err(
            "consensus_vote requires exactly one state_dim input row per agent",
        ));
    }
    let (decisions, consensus) = network.consensus(&agent_inputs);

    if decisions
        .iter()
        .flatten()
        .chain(consensus.iter())
        .any(|n| !n.is_finite())
    {
        return Err(crate::safety::bad_state(
            "consensus_vote",
            "non-finite output",
            "the computation exceeded the numeric range",
        ));
    }
    // Confidence is the reciprocal of one plus the mean squared disagreement.
    let decision_dim = decisions.first().map(|d| d.len()).unwrap_or(0);
    let mean: Vec<f64> = (0..decision_dim)
        .map(|i| {
            decisions
                .iter()
                .map(|d| d.get(i).copied().unwrap_or(0.0))
                .sum::<f64>()
                / decisions.len().max(1) as f64
        })
        .collect();
    let variance: f64 = decisions
        .iter()
        .map(|d: &Vec<f64>| {
            d.iter()
                .zip(&mean)
                .map(|(a, b)| (a - b).powi(2))
                .sum::<f64>()
        })
        .sum::<f64>()
        / decisions.len().max(1) as f64;
    let confidence = 1.0 / (1.0 + variance);

    let mut result = BTreeMap::new();
    result.insert(
        "decisions".to_string(),
        Value::Array(
            decisions
                .into_iter()
                .map(|d: Vec<f64>| Value::Array(d.into_iter().map(Value::Float).collect()))
                .collect(),
        ),
    );
    result.insert(
        "consensus".to_string(),
        Value::Array(consensus.into_iter().map(Value::Float).collect()),
    );
    result.insert("confidence".to_string(), Value::Float(confidence));

    Ok(Value::Record(result))
}

/// activation(name)
/// Get activation function by name
/// Args:
///   - name: String - "relu", "sigmoid", "tanh", "softmax", "linear", "swish", "leaky_relu"
/// Returns: Record - Activation function info
fn bi_activation(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = args
        .first()
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.as_str())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("activation requires name string"))?;

    let activation = Activation::from_str(name).ok_or_else(|| {
        crate::safety::bad_arg(
            "activation",
            "one of: relu, sigmoid, tanh, softmax, linear, swish, leaky_relu",
            name,
        )
    })?;

    let mut info = BTreeMap::new();
    info.insert("name".to_string(), Value::Str(format!("{:?}", activation)));
    info.insert(
        "description".to_string(),
        Value::Str(
            match activation {
                Activation::ReLU => "Rectified Linear Unit: max(0, x)",
                Activation::Sigmoid => "Sigmoid: 1/(1+e^-x), outputs 0-1",
                Activation::Tanh => "Hyperbolic tangent: outputs -1 to 1",
                Activation::Softmax => "Softmax: probability distribution",
                Activation::Linear => "Linear: f(x) = x",
                Activation::LeakyReLU(_) => "Leaky ReLU: x if x>0, else 0.01*x",
                Activation::Swish => "Swish: x * sigmoid(x)",
            }
            .to_string(),
        ),
    );

    Ok(Value::Record(info))
}

// --------------- Evolution Builtins ---------------

/// population(size, genome_type, [config])
/// Create a population for evolution
/// Args:
///   - size: Int - Population size
///   - genome_type: String - "nn" for neural network, "vec" for float vector
///   - config: Record (optional) - Evolution configuration
/// Returns: Record - Population state
fn bi_population(args: Vec<Value>, _input: Option<Value>, _env: &mut Env) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "population requires size and genome_type",
        ));
    }

    let size_value = expect_int("population", &args[0])?;
    let size = usize::try_from(size_value)
        .ok()
        .filter(|n| *n > 0)
        .ok_or_else(|| {
            crate::safety::arg_err("population size must be a positive representable Int")
        })?;
    let genome_type = expect_string("population", &args[1])?;
    let config = parse_evolution_options("population", args.get(2), Some(size))?;

    // Create population based on genome type
    match genome_type {
        "nn" => {
            let pop: Population<NeuralNetwork> = Population::new(config.clone());
            population_to_value(&pop, "nn")
        }
        "vec" | "vector" => {
            let pop: Population<Vec<f64>> = Population::new(config.clone());
            population_to_value(&pop, "vec")
        }
        _ => Err(crate::safety::bad_arg(
            "population",
            "genome_type: nn, vec or vector",
            genome_type,
        )),
    }
}

/// evolve(population, fitness_fn, generations)
/// Run evolution for multiple generations
/// Args:
///   - population: Record - Population from population()
///   - fitness_fn: Lambda - fn(genome) => Float
///   - generations: Int - Number of generations
/// Returns: Record - Updated population with stats
fn bi_evolve(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    evolution_operation("evolve", args, input, env, true, false)
}

/// Run one generation, evaluating uncached parents before reproduction.
fn bi_evolve_step(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    evolution_operation("evolve_step", args, input, env, false, false)
}

/// Evaluate uncached individuals and retain their scores for subsequent calls.
fn bi_fitness(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    evolution_operation("fitness", args, input, env, false, true)
}

fn evolution_operation(
    name: &str,
    args: Vec<Value>,
    input: Option<Value>,
    env: &mut Env,
    multiple: bool,
    evaluate_only: bool,
) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err(format!("{name} requires population")))?;
    let idx = usize::from(!piped);
    let lambda = need_lambda(
        args.get(idx)
            .ok_or_else(|| crate::safety::arg_err(format!("{name} requires fitness function")))?,
        name,
    )?
    .clone();
    if lambda.params.len() != 1 {
        return Err(crate::safety::arg_err(format!(
            "{name}: fitness function must take exactly one genome parameter"
        )));
    }
    let generations = if evaluate_only {
        None
    } else if multiple {
        let count = match args.get(idx + 1) {
            None => 10,
            Some(Value::Int(n)) => usize::try_from(*n)
                .map_err(|_| crate::safety::arg_err("evolve: generations must be non-negative"))?,
            Some(other) => {
                return Err(crate::safety::bad_arg(
                    name,
                    "generations: Int",
                    other.type_name(),
                ))
            }
        };
        Some(count)
    } else {
        Some(1)
    };
    match get_population_genome_type(&value)?.as_str() {
        "nn" => {
            let mut population = value_to_population_nn(&value)?;
            run_population_operation(
                name,
                &mut population,
                &lambda,
                env,
                generations,
                nn_to_value,
                validate_nn,
            )?;
            population_to_value(&population, "nn")
        }
        "vec" => {
            let mut population = value_to_population_vec(&value)?;
            run_population_operation(
                name,
                &mut population,
                &lambda,
                env,
                generations,
                |genome| {
                    Ok(Value::Array(
                        genome.iter().copied().map(Value::Float).collect(),
                    ))
                },
                |genome| validate_vector_genome(genome),
            )?;
            population_to_value(&population, "vec")
        }
        other => Err(crate::safety::bad_arg(
            name,
            "population genome_type: nn or vec",
            other,
        )),
    }
}

fn check_population_work<G: crate::evolution::Evolvable>(
    name: &str,
    pop: &Population<G>,
    generations: Option<usize>,
) -> Result<()> {
    let count = generations.unwrap_or(1);
    let parameters: usize = pop
        .individuals
        .iter()
        .map(|individual| individual.genome.param_count())
        .sum();
    if count > MAX_EVOLUTION_GENERATIONS
        || pop
            .individuals
            .len()
            .checked_mul(count)
            .is_none_or(|n| n > 100_000)
        || parameters.checked_mul(count).is_none_or(|n| n > 10_000_000)
        || pop
            .stats
            .fitness_history
            .len()
            .checked_add(count)
            .is_none_or(|n| n > MAX_EVOLUTION_GENERATIONS)
    {
        return Err(crate::safety::budget_exceeded(
            name,
            "evolution work or history budget exceeded".into(),
            "use fewer generations or a smaller population",
        ));
    }
    let final_generation = pop.generation.checked_add(generations.unwrap_or(0));
    let final_id = pop
        .next_id
        .checked_add(pop.individuals.len() * generations.unwrap_or(0));
    if final_generation.is_none_or(|n| i64::try_from(n).is_err())
        || final_id.is_none_or(|n| i64::try_from(n).is_err())
    {
        return Err(crate::safety::arg_err(
            "evolution generation or individual ID overflow",
        ));
    }
    Ok(())
}

fn run_population_operation<G: crate::evolution::Evolvable>(
    name: &str,
    pop: &mut Population<G>,
    lambda: &Lambda,
    env: &mut Env,
    generations: Option<usize>,
    encode: impl Fn(&G) -> Result<Value>,
    validate: impl Fn(&G) -> Result<()>,
) -> Result<()> {
    check_population_work(name, pop, generations)?;
    let count = generations.unwrap_or(1);
    for _ in 0..count {
        // Populate the cache fallibly before entering the infallible engine.
        // A failed callback never becomes a zero score or triggers another call.
        for individual in &mut pop.individuals {
            if individual.fitness.is_none() {
                let result = call_lambda(lambda, &[encode(&individual.genome)?], env)?;
                individual.fitness = Some(FitnessResult::new(finite_nn_number(name, &result)?));
            }
        }
        if generations.is_some() {
            pop.evolve(|_| unreachable!("all parent fitness values were evaluated"));
        } else {
            pop.evaluate(|_| unreachable!("all fitness values were evaluated"));
            pop.stats.generation = pop.generation;
        }
        if [
            pop.stats.best_fitness,
            pop.stats.worst_fitness,
            pop.stats.avg_fitness,
            pop.stats.diversity,
        ]
        .iter()
        .any(|n| !n.is_finite())
        {
            return Err(crate::safety::bad_state(
                name,
                "non-finite statistics",
                "fitness arithmetic exceeded the numeric range",
            ));
        }
        for individual in &pop.individuals {
            validate(&individual.genome).map_err(|_| {
                crate::safety::bad_state(
                    name,
                    "invalid resulting genome",
                    "mutation exceeded the numeric range",
                )
            })?;
        }
    }
    Ok(())
}

/// best_individual(population)
/// Get the best individual from population
fn bi_best_individual(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let pop_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("best_individual requires population"))?;

    let genome_type = get_population_genome_type(&pop_val)?;

    match genome_type.as_str() {
        "nn" => {
            let pop = value_to_population_nn(&pop_val)?;
            if pop
                .individuals
                .iter()
                .any(|individual| individual.fitness.is_none())
            {
                return Err(crate::safety::bad_state(
                    "best_individual",
                    "population is not fully evaluated",
                    "call fitness before ranking individuals",
                ));
            }
            let best = pop
                .individuals
                .iter()
                .max_by(|a, b| {
                    a.score()
                        .partial_cmp(&b.score())
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .ok_or_else(|| crate::safety::arg_err("Empty population"))?;

            let mut result = BTreeMap::new();
            result.insert("genome".to_string(), nn_to_value(&best.genome)?);
            result.insert("fitness".to_string(), Value::Float(best.score()));
            result.insert("generation".to_string(), Value::Int(best.generation as i64));
            result.insert("id".to_string(), Value::Int(best.id as i64));
            Ok(Value::Record(result))
        }
        "vec" => {
            let pop = value_to_population_vec(&pop_val)?;
            if pop
                .individuals
                .iter()
                .any(|individual| individual.fitness.is_none())
            {
                return Err(crate::safety::bad_state(
                    "best_individual",
                    "population is not fully evaluated",
                    "call fitness before ranking individuals",
                ));
            }
            let best = pop
                .individuals
                .iter()
                .max_by(|a, b| {
                    a.score()
                        .partial_cmp(&b.score())
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .ok_or_else(|| crate::safety::arg_err("Empty population"))?;

            let mut result = BTreeMap::new();
            result.insert(
                "genome".to_string(),
                Value::Array(best.genome.iter().map(|&f| Value::Float(f)).collect()),
            );
            result.insert("fitness".to_string(), Value::Float(best.score()));
            result.insert("generation".to_string(), Value::Int(best.generation as i64));
            result.insert("id".to_string(), Value::Int(best.id as i64));
            Ok(Value::Record(result))
        }
        _ => Err(crate::safety::bad_arg(
            "best_individual",
            "population genome_type: nn or vec",
            &genome_type,
        )),
    }
}

/// evolution_stats(population)
/// Get evolution statistics
fn bi_evolution_stats(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let pop_val = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("evolution_stats requires population"))?;

    if let Value::Record(rec) = &pop_val {
        if let Some(Value::Record(stats)) = rec.get("stats") {
            return Ok(Value::Record(stats.clone()));
        }
    }

    Err(crate::safety::arg_err(
        "Could not extract stats from population",
    ))
}

/// selection_strategy(name, [param])
/// Create selection strategy
/// Args:
///   - name: String - "tournament", "roulette", "rank", "truncation", "elite"
///   - param: Int/Float (optional) - Strategy parameter
fn bi_selection_strategy(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = args
        .first()
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.as_str())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("selection_strategy requires name"))?;

    let strategy = match name.to_lowercase().as_str() {
        "tournament" => {
            let size = args
                .get(1)
                .map(|v| match v {
                    Value::Int(n) => Ok(*n),
                    other => Err(crate::safety::bad_arg(
                        "selection_strategy",
                        "parameter: Int",
                        other.type_name(),
                    )),
                })
                .transpose()?
                .unwrap_or(3);
            let size = usize::try_from(size)
                .ok()
                .filter(|&n| n > 0)
                .ok_or_else(|| {
                    crate::safety::arg_err("selection_strategy: tournament size must be positive")
                })?;
            SelectionStrategy::Tournament(size)
        }
        "roulette" | "rank" if args.len() > 1 => {
            return Err(crate::safety::arg_err(
                "selection_strategy: roulette and rank take no parameter",
            ))
        }
        "roulette" => SelectionStrategy::Roulette,
        "rank" => SelectionStrategy::Rank,
        "truncation" => {
            let ratio = args
                .get(1)
                .map(|v| finite_nn_number("selection_strategy", v))
                .transpose()?
                .unwrap_or(0.5);
            if !(0.0..=1.0).contains(&ratio) {
                return Err(crate::safety::arg_err(
                    "selection_strategy: truncation ratio must be in 0..=1",
                ));
            }
            SelectionStrategy::Truncation(ratio)
        }
        "elite" => {
            let n = args
                .get(1)
                .map(|v| match v {
                    Value::Int(n) => Ok(*n),
                    other => Err(crate::safety::bad_arg(
                        "selection_strategy",
                        "parameter: Int",
                        other.type_name(),
                    )),
                })
                .transpose()?
                .unwrap_or(5);
            let n = usize::try_from(n).ok().filter(|&n| n > 0).ok_or_else(|| {
                crate::safety::arg_err("selection_strategy: elite count must be positive")
            })?;
            SelectionStrategy::Elite(n)
        }
        _ => {
            return Err(crate::safety::bad_arg(
                "selection_strategy",
                "one of: tournament, roulette, rank, truncation, elite",
                name,
            ))
        }
    };

    let mut result = BTreeMap::new();
    result.insert(
        "type".to_string(),
        Value::Str("selection_strategy".to_string()),
    );
    result.insert("name".to_string(), Value::Str(format!("{:?}", strategy)));
    Ok(Value::Record(result))
}

/// crossover_strategy(name, [param])
/// Create crossover strategy
fn bi_crossover_strategy(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = args
        .first()
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.as_str())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("crossover_strategy requires name"))?;

    let strategy = match name.to_lowercase().as_str() {
        "single_point" | "singlepoint" | "two_point" | "twopoint" if args.len() > 1 => {
            return Err(crate::safety::arg_err(
                "crossover_strategy: point crossover takes no parameter",
            ))
        }
        "single_point" | "singlepoint" => CrossoverStrategy::SinglePoint,
        "two_point" | "twopoint" => CrossoverStrategy::TwoPoint,
        "uniform" => {
            let prob = args
                .get(1)
                .map(|v| finite_nn_number("crossover_strategy", v))
                .transpose()?
                .unwrap_or(0.5);
            if !(0.0..=1.0).contains(&prob) {
                return Err(crate::safety::arg_err(
                    "crossover_strategy: probability must be in 0..=1",
                ));
            }
            CrossoverStrategy::Uniform(prob)
        }
        "blend" => {
            let alpha = args
                .get(1)
                .map(|v| finite_nn_number("crossover_strategy", v))
                .transpose()?
                .unwrap_or(0.5);
            if alpha < 0.0 {
                return Err(crate::safety::arg_err(
                    "crossover_strategy: alpha must be non-negative",
                ));
            }
            CrossoverStrategy::Blend(alpha)
        }
        "sbx" => {
            let eta = args
                .get(1)
                .map(|v| finite_nn_number("crossover_strategy", v))
                .transpose()?
                .unwrap_or(20.0);
            if eta <= 0.0 {
                return Err(crate::safety::arg_err(
                    "crossover_strategy: eta must be positive",
                ));
            }
            CrossoverStrategy::SBX(eta)
        }
        _ => {
            return Err(crate::safety::bad_arg(
                "crossover_strategy",
                "one of: single_point, two_point, uniform, blend, sbx",
                name,
            ))
        }
    };

    let mut result = BTreeMap::new();
    result.insert(
        "type".to_string(),
        Value::Str("crossover_strategy".to_string()),
    );
    result.insert("name".to_string(), Value::Str(format!("{:?}", strategy)));
    Ok(Value::Record(result))
}

const MAX_EVOLUTION_POPULATION: usize = 10_000;
const MAX_EVOLUTION_GENERATIONS: usize = 10_000;

fn parse_evolution_options(
    builtin: &str,
    options: Option<&Value>,
    size: Option<usize>,
) -> Result<EvolutionConfig> {
    let opts = match options {
        None => None,
        Some(Value::Record(opts)) => Some(opts),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                builtin,
                "options: Record",
                other.type_name(),
            ))
        }
    };
    if let Some(opts) = opts {
        for (key, value) in opts {
            match key.as_str() {
                "population_size" | "generations" | "mutation_rate" | "mutation_strength"
                | "crossover_rate" | "elitism" => {}
                "type" if matches!(value, Value::Str(tag) if tag == "evolution_config") => {}
                _ => {
                    return Err(crate::safety::arg_err(format!(
                        "{builtin}: unknown option or invalid configuration marker {key}"
                    )))
                }
            }
        }
    }
    let get = |key: &str| opts.and_then(|opts| opts.get(key));
    let integer = |key: &str, default: usize, positive: bool| -> Result<usize> {
        let Some(value) = get(key) else {
            return Ok(default);
        };
        let n = match value {
            Value::Int(n) => *n,
            other => {
                return Err(crate::safety::bad_arg(
                    builtin,
                    &format!("{key}: Int"),
                    other.type_name(),
                ))
            }
        };
        usize::try_from(n)
            .ok()
            .filter(|n| !positive || *n > 0)
            .ok_or_else(|| {
                crate::safety::arg_err(format!(
                    "{builtin}: {key} must be a {}representable Int",
                    if positive {
                        "positive "
                    } else {
                        "non-negative "
                    }
                ))
            })
    };
    let mut config = EvolutionConfig::default();
    config.population_size = integer(
        "population_size",
        size.unwrap_or(config.population_size),
        true,
    )?;
    if size.is_some_and(|size| size != config.population_size) {
        return Err(crate::safety::arg_err(
            "population: configuration population_size must match the size argument",
        ));
    }
    config.generations = integer("generations", config.generations, false)?;
    if config.population_size > MAX_EVOLUTION_POPULATION
        || config.generations > MAX_EVOLUTION_GENERATIONS
    {
        return Err(crate::safety::budget_exceeded(
            builtin,
            "population_size and generations are limited to 10000".into(),
            "use a smaller population or fewer generations",
        ));
    }
    config.elitism = integer("elitism", config.elitism.min(config.population_size), false)?;
    if config.elitism > config.population_size {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: elitism cannot exceed population_size"
        )));
    }
    let number = |key: &str, default: f64| -> Result<f64> {
        get(key)
            .map(|value| finite_nn_number(builtin, value))
            .transpose()
            .map(|value| value.unwrap_or(default))
    };
    config.mutation_rate = number("mutation_rate", config.mutation_rate)?;
    config.mutation_strength = number("mutation_strength", config.mutation_strength)?;
    config.crossover_rate = number("crossover_rate", config.crossover_rate)?;
    if !(0.0..=1.0).contains(&config.mutation_rate)
        || !(0.0..=1.0).contains(&config.crossover_rate)
        || config.mutation_strength < 0.0
    {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: rates must be in 0..=1 and mutation_strength non-negative"
        )));
    }
    Ok(config)
}

/// evolution_config([options])
/// Create evolution configuration
fn bi_evolution_config(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let config = parse_evolution_options("evolution_config", args.first(), None)?;

    let mut result = BTreeMap::new();
    result.insert(
        "type".to_string(),
        Value::Str("evolution_config".to_string()),
    );
    result.insert(
        "population_size".to_string(),
        Value::Int(config.population_size as i64),
    );
    result.insert(
        "generations".to_string(),
        Value::Int(config.generations as i64),
    );
    result.insert(
        "mutation_rate".to_string(),
        Value::Float(config.mutation_rate),
    );
    result.insert(
        "mutation_strength".to_string(),
        Value::Float(config.mutation_strength),
    );
    result.insert(
        "crossover_rate".to_string(),
        Value::Float(config.crossover_rate),
    );
    result.insert("elitism".to_string(), Value::Int(config.elitism as i64));
    Ok(Value::Record(result))
}

/// Decoded population variants retained during batch preflight.
enum EvolutionPopulation {
    Neural(Population<NeuralNetwork>),
    Vector(Population<Vec<f64>>),
}

/// Evolve populations independently after validating the complete batch.
fn bi_coevolve(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("coevolve requires populations array"))?;
    let values = expect_array("coevolve", &value)?;
    let idx = usize::from(!piped);
    let lambda = need_lambda(
        args.get(idx)
            .ok_or_else(|| crate::safety::arg_err("coevolve requires fitness function"))?,
        "coevolve",
    )?
    .clone();
    if lambda.params.len() != 1 {
        return Err(crate::safety::arg_err(
            "coevolve: fitness function must take exactly one genome parameter",
        ));
    }
    let generations = match args.get(idx + 1) {
        None => 10,
        Some(Value::Int(n)) => usize::try_from(*n)
            .map_err(|_| crate::safety::arg_err("coevolve: generations must be non-negative"))?,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "coevolve",
                "generations: Int",
                other.type_name(),
            ))
        }
    };
    let budget = || {
        crate::safety::budget_exceeded(
            "coevolve",
            "combined population, encoding, history or work budget exceeded".into(),
            "use fewer or smaller populations and fewer generations",
        )
    };
    if values.len() > MAX_EVOLUTION_POPULATION || generations > MAX_EVOLUTION_GENERATIONS {
        return Err(budget());
    }
    let mut bytes = 0usize;
    for value in values {
        if let Value::Record(record) = value {
            for key in ["_individuals", "_config"] {
                if let Some(Value::Str(data)) = record.get(key) {
                    bytes = bytes
                        .checked_add(data.len())
                        .filter(|n| *n <= 64 * 1024 * 1024)
                        .ok_or_else(&budget)?;
                }
            }
        }
    }
    // Decode and preflight the complete batch before invoking any callback.
    let mut populations = Vec::with_capacity(values.len());
    let mut individuals = 0usize;
    let mut parameters = 0usize;
    let mut history = 0usize;
    for value in values {
        let (population, size, params, entries) = match get_population_genome_type(value)?.as_str()
        {
            "nn" => {
                let pop = value_to_population_nn(value)?;
                check_population_work("coevolve", &pop, Some(generations))?;
                let params = pop
                    .individuals
                    .iter()
                    .map(|individual| individual.genome.param_count())
                    .sum::<usize>();
                let size = pop.individuals.len();
                let entries = pop.stats.fitness_history.len();
                (EvolutionPopulation::Neural(pop), size, params, entries)
            }
            "vec" => {
                let pop = value_to_population_vec(value)?;
                check_population_work("coevolve", &pop, Some(generations))?;
                let params = pop
                    .individuals
                    .iter()
                    .map(|individual| individual.genome.len())
                    .sum::<usize>();
                let size = pop.individuals.len();
                let entries = pop.stats.fitness_history.len();
                (EvolutionPopulation::Vector(pop), size, params, entries)
            }
            other => {
                return Err(crate::safety::bad_arg(
                    "coevolve",
                    "population genome_type: nn or vec",
                    other,
                ))
            }
        };
        individuals = individuals
            .checked_add(size)
            .filter(|n| *n <= MAX_EVOLUTION_POPULATION)
            .ok_or_else(&budget)?;
        parameters = parameters
            .checked_add(params)
            .filter(|n| *n <= MAX_NN_PARAMETERS)
            .ok_or_else(&budget)?;
        history = history
            .checked_add(entries)
            .filter(|n| *n <= MAX_EVOLUTION_GENERATIONS)
            .ok_or_else(&budget)?;
        populations.push(population);
    }
    if individuals
        .checked_mul(generations)
        .is_none_or(|n| n > 100_000)
        || parameters
            .checked_mul(generations)
            .is_none_or(|n| n > 10_000_000)
        || populations
            .len()
            .checked_mul(generations)
            .and_then(|n| history.checked_add(n))
            .is_none_or(|n| n > MAX_EVOLUTION_GENERATIONS)
    {
        return Err(budget());
    }
    let mut results = Vec::with_capacity(populations.len());
    for population in populations {
        match population {
            EvolutionPopulation::Neural(mut pop) => {
                run_population_operation(
                    "coevolve",
                    &mut pop,
                    &lambda,
                    env,
                    Some(generations),
                    nn_to_value,
                    validate_nn,
                )?;
                results.push(population_to_value(&pop, "nn")?);
            }
            EvolutionPopulation::Vector(mut pop) => {
                run_population_operation(
                    "coevolve",
                    &mut pop,
                    &lambda,
                    env,
                    Some(generations),
                    |genome| {
                        Ok(Value::Array(
                            genome.iter().copied().map(Value::Float).collect(),
                        ))
                    },
                    |genome| validate_vector_genome(genome),
                )?;
                results.push(population_to_value(&pop, "vec")?);
            }
        }
    }
    Ok(Value::Array(results))
}

// --------------- Neural/Evolution Helpers ---------------

const MAX_NN_PARAMETERS: usize = 1_000_000;

fn finite_nn_number(builtin: &str, value: &Value) -> Result<f64> {
    let number = match value {
        Value::Int(n) => *n as f64,
        Value::Float(n) => *n,
        other => {
            return Err(crate::safety::bad_arg(
                builtin,
                "finite Number",
                other.type_name(),
            ))
        }
    };
    if !number.is_finite() {
        return Err(crate::safety::arg_err(&format!(
            "{builtin}: number must be finite"
        )));
    }
    Ok(number)
}

fn checked_nn_parameter_count(total: usize, input: usize, output: usize) -> Result<usize> {
    total
        .checked_add(
            input
                .checked_mul(output)
                .and_then(|n| n.checked_add(output))
                .ok_or_else(|| {
                    crate::safety::arg_err("neural network: parameter count overflow")
                })?,
        )
        .filter(|&n| n <= MAX_NN_PARAMETERS)
        .ok_or_else(|| {
            budget_unnamed(
                "neural network: exceeds 1000000 parameters",
                "reduce the number of layers or their sizes; the limit is 1000000 parameters",
            )
        })
}

fn validate_nn(network: &NeuralNetwork) -> Result<()> {
    if network.layers.is_empty() {
        return Err(crate::safety::arg_err(
            "neural network: at least one dense layer is required",
        ));
    }
    let mut total = 0;
    let mut previous_output = None;
    for layer in &network.layers {
        total = checked_nn_parameter_count(total, layer.input_size, layer.output_size)?;
        if layer.input_size == 0
            || layer.output_size == 0
            || previous_output.is_some_and(|n| n != layer.input_size)
            || layer.weights.len() != layer.output_size
            || layer.biases.len() != layer.output_size
            || layer
                .weights
                .iter()
                .any(|row| row.len() != layer.input_size || row.iter().any(|n| !n.is_finite()))
            || layer.biases.iter().any(|n| !n.is_finite())
            || matches!(layer.activation, Activation::LeakyReLU(alpha) if !alpha.is_finite())
        {
            return Err(crate::safety::arg_err(
                "neural network: inconsistent layer dimensions or non-finite parameters",
            ));
        }
        previous_output = Some(layer.output_size);
    }
    Ok(())
}

fn value_to_f64(v: &Value) -> Result<f64> {
    match v {
        Value::Float(f) => Ok(*f),
        Value::Int(i) => Ok(*i as f64),
        _ => Err(crate::safety::arg_err(format!(
            "Expected numeric value, got {:?}",
            v
        ))),
    }
}

fn nn_to_value(network: &NeuralNetwork) -> Result<Value> {
    let json = serde_json::to_string(network).context("Failed to serialize network")?;

    let mut rec = BTreeMap::new();
    rec.insert("type".to_string(), Value::Str("neural_network".to_string()));
    rec.insert("name".to_string(), Value::Str(network.name.clone()));
    rec.insert(
        "layer_count".to_string(),
        Value::Int(network.layers.len() as i64),
    );
    rec.insert(
        "param_count".to_string(),
        Value::Int(network.param_count() as i64),
    );
    rec.insert("_data".to_string(), Value::Str(json));
    Ok(Value::Record(rec))
}

fn value_to_nn(v: &Value) -> Result<NeuralNetwork> {
    if let Value::Record(rec) = v {
        if let Some(Value::Str(data)) = rec.get("_data") {
            if data.len() > 64 * 1024 * 1024 {
                return Err(budget_unnamed(
                    "neural network: encoded data exceeds 64 MiB",
                    "the encoded network is larger than 64 MiB and cannot be decoded",
                ));
            }
            let network = serde_json::from_str(data).map_err(|e| {
                crate::safety::arg_err(&format!("neural network: invalid encoded data: {e}"))
            })?;
            validate_nn(&network)?;
            return Ok(network);
        }
    }
    Err(crate::safety::arg_err("Invalid neural network value"))
}

fn consensus_net_to_value(network: &ConsensusNetwork) -> Result<Value> {
    let json = serde_json::to_string(network).context("Failed to serialize consensus network")?;

    let mut rec = BTreeMap::new();
    rec.insert(
        "type".to_string(),
        Value::Str("consensus_network".to_string()),
    );
    rec.insert("name".to_string(), Value::Str(network.name.clone()));
    rec.insert(
        "agent_count".to_string(),
        Value::Int(network.agent_networks.len() as i64),
    );
    rec.insert("_data".to_string(), Value::Str(json));
    Ok(Value::Record(rec))
}

fn value_to_consensus_net(v: &Value) -> Result<ConsensusNetwork> {
    if let Value::Record(rec) = v {
        if let Some(Value::Str(data)) = rec.get("_data") {
            if data.len() > 64 * 1024 * 1024 {
                return Err(crate::safety::budget_exceeded(
                    "consensus_vote",
                    "consensus network encoding exceeds 64 MiB".into(),
                    "use a smaller network",
                ));
            }
            let network: ConsensusNetwork = serde_json::from_str(data).map_err(|e| {
                crate::safety::bad_arg(
                    "consensus_vote",
                    "valid encoded consensus network",
                    &e.to_string(),
                )
            })?;
            validate_consensus_net(&network)?;
            return Ok(network);
        }
    }
    Err(crate::safety::arg_err("Invalid consensus network value"))
}

fn validate_consensus_net(network: &ConsensusNetwork) -> Result<()> {
    if network.state_dim == 0 || network.message_dim == 0 || network.agent_networks.is_empty() {
        return Err(crate::safety::arg_err(
            "consensus network dimensions and agent count must be positive",
        ));
    }
    if network.agent_networks.len() > 1024 || network.num_rounds > 16 {
        return Err(crate::safety::budget_exceeded(
            "consensus_vote",
            "consensus network exceeds 1024 agents or 16 rounds".into(),
            "use fewer agents or rounds",
        ));
    }
    let mut total = 0;
    for nn in [
        &network.local_encoder,
        &network.message_processor,
        &network.decision_network,
    ]
    .into_iter()
    .chain(network.agent_networks.iter())
    {
        validate_nn(nn)?;
        for layer in &nn.layers {
            total = checked_nn_parameter_count(total, layer.input_size, layer.output_size)?;
        }
    }
    let dimensions_match = |nn: &NeuralNetwork, input: Option<usize>, output: usize| {
        input == Some(nn.layers[0].input_size) && nn.layers.last().unwrap().output_size == output
    };
    if !dimensions_match(
        &network.local_encoder,
        Some(network.state_dim),
        network.message_dim,
    ) || !dimensions_match(
        &network.message_processor,
        network.message_dim.checked_mul(2),
        network.message_dim,
    ) || Some(network.decision_network.layers[0].input_size)
        != network.message_dim.checked_add(network.state_dim)
        || network
            .agent_networks
            .iter()
            .any(|nn| !dimensions_match(nn, Some(network.state_dim), network.message_dim))
    {
        return Err(crate::safety::arg_err(
            "consensus network component dimensions do not match",
        ));
    }
    Ok(())
}

fn get_population_genome_type(v: &Value) -> Result<String> {
    if let Value::Record(rec) = v {
        if let Some(Value::Str(gt)) = rec.get("genome_type") {
            return Ok(gt.clone());
        }
    }
    Err(crate::safety::arg_err(
        "Could not determine genome type from population",
    ))
}

fn population_to_value<G: crate::evolution::Evolvable + serde::Serialize>(
    pop: &Population<G>,
    genome_type: &str,
) -> Result<Value> {
    let json = serde_json::to_string(&pop.individuals).context("Failed to serialize population")?;
    let config_json = serde_json::to_string(&pop.config).context("Failed to serialize config")?;

    let mut stats = BTreeMap::new();
    stats.insert(
        "generation".to_string(),
        Value::Int(pop.stats.generation as i64),
    );
    stats.insert(
        "best_fitness".to_string(),
        Value::Float(pop.stats.best_fitness),
    );
    stats.insert(
        "avg_fitness".to_string(),
        Value::Float(pop.stats.avg_fitness),
    );
    stats.insert(
        "worst_fitness".to_string(),
        Value::Float(pop.stats.worst_fitness),
    );
    stats.insert("diversity".to_string(), Value::Float(pop.stats.diversity));
    stats.insert(
        "history".to_string(),
        Value::Array(
            pop.stats
                .fitness_history
                .iter()
                .map(|&f| Value::Float(f))
                .collect(),
        ),
    );

    let mut rec = BTreeMap::new();
    rec.insert("type".to_string(), Value::Str("population".to_string()));
    rec.insert(
        "genome_type".to_string(),
        Value::Str(genome_type.to_string()),
    );
    rec.insert("size".to_string(), Value::Int(pop.individuals.len() as i64));
    rec.insert("generation".to_string(), Value::Int(pop.generation as i64));
    rec.insert("next_id".to_string(), Value::Int(pop.next_id as i64));
    rec.insert("stats".to_string(), Value::Record(stats));
    rec.insert("_individuals".to_string(), Value::Str(json));
    rec.insert("_config".to_string(), Value::Str(config_json));
    Ok(Value::Record(rec))
}

fn validate_vector_genome(genome: &[f64]) -> Result<()> {
    if genome.is_empty() || genome.iter().any(|n| !n.is_finite()) {
        return Err(crate::safety::arg_err(
            "population vectors must be nonempty and finite",
        ));
    }
    Ok(())
}

fn value_to_population_nn(value: &Value) -> Result<Population<NeuralNetwork>> {
    let pop = decode_population(value, validate_nn)?;
    let dimensions: Vec<_> = pop.individuals[0]
        .genome
        .layers
        .iter()
        .map(|layer| (layer.input_size, layer.output_size))
        .collect();
    if pop.individuals.iter().any(|individual| {
        individual
            .genome
            .layers
            .iter()
            .map(|layer| (layer.input_size, layer.output_size))
            .collect::<Vec<_>>()
            != dimensions
    }) {
        return Err(crate::safety::arg_err(
            "population networks must have matching layer dimensions",
        ));
    }
    Ok(pop)
}

fn value_to_population_vec(value: &Value) -> Result<Population<Vec<f64>>> {
    let pop = decode_population(value, |genome: &Vec<f64>| validate_vector_genome(genome))?;
    let width = pop.individuals[0].genome.len();
    if pop
        .individuals
        .iter()
        .any(|individual| individual.genome.len() != width)
    {
        return Err(crate::safety::arg_err(
            "population vectors must have equal lengths",
        ));
    }
    Ok(pop)
}

fn decode_population<G: crate::evolution::Evolvable + serde::de::DeserializeOwned>(
    value: &Value,
    validate: impl Fn(&G) -> Result<()>,
) -> Result<Population<G>> {
    let Value::Record(record) = value else {
        return Err(crate::safety::arg_err("population must be a Record"));
    };
    let text = |key: &str| -> Result<&str> {
        match record.get(key) {
            Some(Value::Str(text)) => Ok(text),
            _ => Err(crate::safety::arg_err(format!(
                "population requires encoded {key}: String"
            ))),
        }
    };
    let data = text("_individuals")?;
    let config_data = text("_config")?;
    if data.len().saturating_add(config_data.len()) > 64 * 1024 * 1024 {
        return Err(crate::safety::budget_exceeded(
            "evo",
            "encoded population exceeds 64 MiB".into(),
            "use a smaller population",
        ));
    }
    let individuals: Vec<crate::evolution::Individual<G>> = serde_json::from_str(data)
        .map_err(|e| crate::safety::bad_arg("evo", "valid encoded individuals", &e.to_string()))?;
    let config: EvolutionConfig = serde_json::from_str(config_data).map_err(|e| {
        crate::safety::bad_arg("evo", "valid encoded configuration", &e.to_string())
    })?;
    if individuals.is_empty() || individuals.len() != config.population_size {
        return Err(crate::safety::arg_err(
            "population must be nonempty and match configured population_size",
        ));
    }
    let bounded_int = |n: usize| {
        i64::try_from(n)
            .map(Value::Int)
            .map_err(|_| crate::safety::arg_err("population count exceeds Int range"))
    };
    let options = Value::Record(BTreeMap::from([
        (
            "population_size".into(),
            bounded_int(config.population_size)?,
        ),
        ("generations".into(), bounded_int(config.generations)?),
        ("elitism".into(), bounded_int(config.elitism)?),
        ("mutation_rate".into(), Value::Float(config.mutation_rate)),
        (
            "mutation_strength".into(),
            Value::Float(config.mutation_strength),
        ),
        ("crossover_rate".into(), Value::Float(config.crossover_rate)),
    ]));
    parse_evolution_options("evo", Some(&options), None)?;
    if config.selection != SelectionStrategy::Tournament(3)
        || config.crossover != CrossoverStrategy::Uniform(0.5)
        || config.seed.is_some()
    {
        return Err(crate::safety::arg_err(
            "population uses unsupported selection, crossover or seed settings",
        ));
    }
    let nonnegative = |value: Option<&Value>| -> Result<usize> {
        match value {
            Some(Value::Int(n)) => usize::try_from(*n).map_err(|_| {
                crate::safety::arg_err("population counters must be non-negative Int values")
            }),
            _ => Err(crate::safety::arg_err(
                "population counters must be Int values",
            )),
        }
    };
    let generation = nonnegative(record.get("generation"))?;
    let mut ids = std::collections::HashSet::new();
    let mut parameters = 0usize;
    let mut next_id = 0usize;
    for individual in &individuals {
        validate(&individual.genome)?;
        parameters = parameters
            .checked_add(individual.genome.param_count())
            .filter(|n| *n <= MAX_NN_PARAMETERS)
            .ok_or_else(|| {
                crate::safety::budget_exceeded(
                    "evo",
                    "population exceeds one million genome parameters".into(),
                    "use a smaller population",
                )
            })?;
        if individual.generation > generation
            || i64::try_from(individual.id).is_err()
            || !ids.insert(individual.id)
        {
            return Err(crate::safety::arg_err(
                "population individual counters or IDs are invalid",
            ));
        }
        next_id = next_id.max(
            individual
                .id
                .checked_add(1)
                .ok_or_else(|| crate::safety::arg_err("population individual ID overflow"))?,
        );
        if individual.fitness.as_ref().is_some_and(|fitness| {
            !fitness.score.is_finite() || fitness.metrics.values().any(|n| !n.is_finite())
        }) {
            return Err(crate::safety::arg_err(
                "population fitness values must be finite",
            ));
        }
    }
    if let Some(value) = record.get("next_id") {
        let supplied = nonnegative(Some(value))?;
        if supplied < next_id {
            return Err(crate::safety::arg_err(
                "population next_id would reuse an individual ID",
            ));
        }
        next_id = supplied;
    }
    bounded_int(next_id)?;
    let Some(Value::Record(stats)) = record.get("stats") else {
        return Err(crate::safety::arg_err("population requires stats: Record"));
    };
    let stats_generation = nonnegative(stats.get("generation"))?;
    if stats_generation > generation {
        return Err(crate::safety::arg_err(
            "population stats generation exceeds population generation",
        ));
    }
    let Some(Value::Array(history)) = stats.get("history") else {
        return Err(crate::safety::arg_err(
            "population stats requires history: Array",
        ));
    };
    if history.len() > MAX_EVOLUTION_GENERATIONS {
        return Err(crate::safety::budget_exceeded(
            "evo",
            "population history exceeds 10000 entries".into(),
            "use a shorter history",
        ));
    }
    let history = history
        .iter()
        .map(|value| finite_nn_number("evo", value))
        .collect::<Result<Vec<_>>>()?;
    let number = |key: &str| -> Result<f64> {
        match stats.get(key) {
            Some(Value::Float(n)) => Ok(*n),
            Some(Value::Int(n)) => Ok(*n as f64),
            _ => Err(crate::safety::arg_err(format!(
                "population stats requires numeric {key}"
            ))),
        }
    };
    let best = number("best_fitness")?;
    let worst = number("worst_fitness")?;
    let avg = number("avg_fitness")?;
    let diversity = number("diversity")?;
    let initial = history.is_empty()
        && individuals
            .iter()
            .all(|individual| individual.fitness.is_none())
        && best == f64::NEG_INFINITY
        && worst == f64::INFINITY;
    if (!initial && (!best.is_finite() || !worst.is_finite()))
        || !avg.is_finite()
        || !diversity.is_finite()
        || diversity < 0.0
    {
        return Err(crate::safety::arg_err(
            "population statistics must be finite except unevaluated initial extrema",
        ));
    }
    Ok(Population {
        individuals,
        config,
        generation,
        next_id,
        stats: crate::evolution::EvolutionStats {
            generation: stats_generation,
            best_fitness: best,
            worst_fitness: worst,
            avg_fitness: avg,
            diversity,
            fitness_history: history,
        },
    })
}

// ==================== Reinforcement Learning Builtins ====================

/// Create a Q-learning agent
/// Usage: rl_agent(name, state_size, action_size, [config])
const MAX_RL_CELLS: usize = 1_000_000;

fn rl_positive_size(name: &str, value: &Value) -> Result<usize> {
    match value {
        Value::Int(n) => usize::try_from(*n).ok().filter(|n| *n > 0).ok_or_else(|| {
            crate::safety::arg_err(format!("{name}: size must be a positive representable Int"))
        }),
        other => Err(crate::safety::bad_arg(
            name,
            "positive Int",
            other.type_name(),
        )),
    }
}

fn validate_q_agent(agent: &QLearningAgent) -> Result<()> {
    if agent.state_size == 0 || agent.action_size == 0 {
        return Err(crate::safety::arg_err(
            "Q-learning dimensions must be positive",
        ));
    }
    if agent.action_size > 10000
        || agent
            .state_size
            .checked_mul(agent.action_size)
            .is_none_or(|n| n > MAX_RL_CELLS)
        || agent.q_table.len() > MAX_RL_CELLS
    {
        return Err(crate::safety::budget_exceeded(
            "rl",
            "Q-learning exceeds 10000 actions or one million state-action cells".into(),
            "use a smaller state/action space",
        ));
    }
    if [
        agent.learning_rate,
        agent.discount,
        agent.epsilon,
        agent.epsilon_decay,
        agent.epsilon_min,
    ]
    .iter()
    .any(|n| !n.is_finite() || !(0.0..=1.0).contains(n))
        || i64::try_from(agent.steps).is_err()
    {
        return Err(crate::safety::arg_err(
            "Q-learning rates must be finite probabilities and steps must fit Int",
        ));
    }
    if agent.q_table.iter().any(|(&(state, action), q)| {
        state >= agent.state_size || action >= agent.action_size || !q.is_finite()
    }) {
        return Err(crate::safety::arg_err(
            "Q-learning table indices must be in range and values finite",
        ));
    }
    Ok(())
}

fn validate_sarsa_agent(agent: &SarsaAgent) -> Result<()> {
    if agent.state_size == 0 || agent.action_size == 0 {
        return Err(crate::safety::arg_err("SARSA dimensions must be positive"));
    }
    if agent.action_size > 10000
        || agent
            .state_size
            .checked_mul(agent.action_size)
            .is_none_or(|n| n > MAX_RL_CELLS)
        || agent.q_table.len() > MAX_RL_CELLS
    {
        return Err(crate::safety::budget_exceeded(
            "rl",
            "SARSA exceeds 10000 actions or one million state-action cells".into(),
            "use a smaller state/action space",
        ));
    }
    if [agent.learning_rate, agent.discount, agent.epsilon]
        .iter()
        .any(|n| !n.is_finite() || !(0.0..=1.0).contains(n))
        || i64::try_from(agent.steps).is_err()
    {
        return Err(crate::safety::arg_err(
            "SARSA rates must be finite probabilities and steps must fit Int",
        ));
    }
    if agent.q_table.iter().any(|(&(state, action), q)| {
        state >= agent.state_size || action >= agent.action_size || !q.is_finite()
    }) {
        return Err(crate::safety::arg_err(
            "SARSA table indices must be in range and values finite",
        ));
    }
    Ok(())
}

fn rl_index(name: &str, value: &Value, limit: usize) -> Result<usize> {
    match value {
        Value::Int(n) => usize::try_from(*n)
            .ok()
            .filter(|n| *n < limit)
            .ok_or_else(|| crate::safety::arg_err(format!("{name}: index must be in 0..{limit}"))),
        other => Err(crate::safety::bad_arg(
            name,
            "index: Int",
            other.type_name(),
        )),
    }
}

fn bi_rl_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = expect_string(
        "rl_agent",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("rl_agent requires name"))?,
    )?;
    let states = rl_positive_size(
        "rl_agent",
        args.get(1)
            .ok_or_else(|| crate::safety::arg_err("rl_agent requires state_size"))?,
    )?;
    let actions = rl_positive_size(
        "rl_agent",
        args.get(2)
            .ok_or_else(|| crate::safety::arg_err("rl_agent requires action_size"))?,
    )?;
    let mut agent = QLearningAgent::new(name, states, actions, 0.1, 0.99, 0.1);
    if let Some(value) = args.get(3) {
        let Value::Record(options) = value else {
            return Err(crate::safety::bad_arg(
                "rl_agent",
                "config: Record",
                value.type_name(),
            ));
        };
        for (key, value) in options {
            let number = finite_nn_number("rl_agent", value)?;
            match key.as_str() {
                "learning_rate" => agent.learning_rate = number,
                "discount" => agent.discount = number,
                "epsilon" => agent.epsilon = number,
                _ => {
                    return Err(crate::safety::arg_err(format!(
                        "rl_agent: unknown option {key}"
                    )))
                }
            }
        }
    }
    validate_q_agent(&agent)?;
    q_agent_to_value(&agent)
}

fn bi_rl_action(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_action requires agent"))?;
    let agent = value_to_q_agent(&value)?;
    let idx = usize::from(!piped);
    let state = rl_index(
        "rl_action state",
        args.get(idx)
            .ok_or_else(|| crate::safety::arg_err("rl_action requires state"))?,
        agent.state_size,
    )?;
    Ok(Value::Int(agent.select_action(state) as i64))
}

fn bi_rl_update(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_update requires agent"))?;
    let mut agent = value_to_q_agent(&value)?;
    let idx = usize::from(!piped);
    let arg = |offset| {
        args.get(idx + offset).ok_or_else(|| {
            crate::safety::arg_err("rl_update requires state, action, reward, next_state, done")
        })
    };
    let state = rl_index("rl_update state", arg(0)?, agent.state_size)?;
    let action = rl_index("rl_update action", arg(1)?, agent.action_size)?;
    let reward = finite_nn_number("rl_update reward", arg(2)?)?;
    let next_state = rl_index("rl_update next_state", arg(3)?, agent.state_size)?;
    let Value::Bool(done) = arg(4)? else {
        return Err(crate::safety::arg_err("rl_update done must be Bool"));
    };
    if agent
        .steps
        .checked_add(1)
        .is_none_or(|n| i64::try_from(n).is_err())
    {
        return Err(crate::safety::arg_err("rl_update step counter overflow"));
    }
    agent.update(state, action, reward, next_state, *done);
    validate_q_agent(&agent).map_err(|_| {
        crate::safety::bad_state(
            "rl_update",
            "non-finite Q-learning result",
            "the update exceeded the numeric range",
        )
    })?;
    q_agent_to_value(&agent)
}

/// Create a SARSA agent with fixed default rates.
fn bi_rl_sarsa_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = expect_string(
        "rl_sarsa_agent",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("rl_sarsa_agent requires name"))?,
    )?;
    let states = rl_positive_size(
        "rl_sarsa_agent",
        args.get(1)
            .ok_or_else(|| crate::safety::arg_err("rl_sarsa_agent requires state_size"))?,
    )?;
    let actions = rl_positive_size(
        "rl_sarsa_agent",
        args.get(2)
            .ok_or_else(|| crate::safety::arg_err("rl_sarsa_agent requires action_size"))?,
    )?;
    sarsa_agent_to_value(&SarsaAgent::new(&name, states, actions, 0.1, 0.99, 0.1))
}

/// Update a validated SARSA agent copy using the supplied next action.
fn bi_rl_sarsa_update(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_sarsa_update requires agent"))?;
    let mut agent = value_to_sarsa_agent(&value)?;
    let idx = usize::from(!piped);
    let arg = |offset| {
        args.get(idx + offset).ok_or_else(|| {
            crate::safety::arg_err(
                "rl_sarsa_update requires state, action, reward, next_state, next_action, done",
            )
        })
    };
    let state = rl_index("rl_sarsa_update state", arg(0)?, agent.state_size)?;
    let action = rl_index("rl_sarsa_update action", arg(1)?, agent.action_size)?;
    let reward = finite_nn_number("rl_sarsa_update reward", arg(2)?)?;
    let next_state = rl_index("rl_sarsa_update next_state", arg(3)?, agent.state_size)?;
    let next_action = rl_index("rl_sarsa_update next_action", arg(4)?, agent.action_size)?;
    let Value::Bool(done) = arg(5)? else {
        return Err(crate::safety::arg_err("rl_sarsa_update done must be Bool"));
    };
    if agent
        .steps
        .checked_add(1)
        .is_none_or(|n| i64::try_from(n).is_err())
    {
        return Err(crate::safety::arg_err(
            "rl_sarsa_update step counter overflow",
        ));
    }
    agent.update(state, action, reward, next_state, next_action, *done);
    validate_sarsa_agent(&agent).map_err(|_| {
        crate::safety::bad_state(
            "rl_sarsa_update",
            "non-finite SARSA result",
            "the update exceeded the numeric range",
        )
    })?;
    sarsa_agent_to_value(&agent)
}

fn pg_dimensions(state_dim: usize, action_size: usize) -> Result<usize> {
    if state_dim == 0 || action_size == 0 {
        return Err(crate::safety::arg_err(
            "policy-gradient dimensions must be positive",
        ));
    }
    state_dim
        .checked_mul(action_size)
        .filter(|n| *n <= MAX_RL_CELLS && action_size <= 10000)
        .ok_or_else(|| {
            crate::safety::budget_exceeded(
                "rl_pg",
                "policy exceeds 10000 actions or one million weights".into(),
                "use a smaller policy",
            )
        })
}

fn pg_history_budget(state_dim: usize, steps: usize) -> Result<()> {
    if steps > 10000
        || state_dim
            .checked_mul(steps)
            .is_none_or(|n| n > MAX_RL_CELLS)
    {
        return Err(crate::safety::budget_exceeded(
            "rl_pg",
            "episode exceeds 10000 steps or one million stored state values".into(),
            "finish a shorter episode",
        ));
    }
    Ok(())
}

fn validate_pg_agent(agent: &PolicyGradientAgent) -> Result<()> {
    pg_dimensions(agent.state_dim, agent.action_size)?;
    pg_history_budget(agent.state_dim, agent.episode_states.len())?;
    if agent.weights.len() != agent.action_size
        || agent
            .weights
            .iter()
            .any(|row| row.len() != agent.state_dim || row.iter().any(|v| !v.is_finite()))
    {
        return Err(crate::safety::arg_err(
            "policy weights must match dimensions and be finite",
        ));
    }
    if [agent.learning_rate, agent.discount]
        .iter()
        .any(|v| !v.is_finite() || !(0.0..=1.0).contains(v))
        || i64::try_from(agent.episodes).is_err()
    {
        return Err(crate::safety::arg_err(
            "policy rates must be finite probabilities and episodes must fit Int",
        ));
    }
    if agent.episode_actions.len() != agent.episode_states.len()
        || agent.episode_rewards.len() != agent.episode_states.len()
        || agent
            .episode_states
            .iter()
            .any(|row| row.len() != agent.state_dim || row.iter().any(|v| !v.is_finite()))
        || agent
            .episode_actions
            .iter()
            .any(|a| *a >= agent.action_size)
        || agent.episode_rewards.iter().any(|v| !v.is_finite())
    {
        return Err(crate::safety::arg_err("episode states, actions and rewards must have equal lengths, valid shapes/indices and finite values"));
    }
    Ok(())
}

/// Create a linear softmax policy with fixed default rates.
fn bi_rl_pg_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = expect_string(
        "rl_pg_agent",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("rl_pg_agent requires name"))?,
    )?;
    let state_dim = rl_positive_size(
        "rl_pg_agent",
        args.get(1)
            .ok_or_else(|| crate::safety::arg_err("rl_pg_agent requires state_dim"))?,
    )?;
    let action_size = rl_positive_size(
        "rl_pg_agent",
        args.get(2)
            .ok_or_else(|| crate::safety::arg_err("rl_pg_agent requires action_size"))?,
    )?;
    pg_dimensions(state_dim, action_size)?;
    pg_agent_to_value(&PolicyGradientAgent::new(
        &name,
        state_dim,
        action_size,
        0.01,
        0.99,
    ))
}

/// Append a validated step without updating policy weights.
fn bi_rl_pg_step(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_pg_step requires agent"))?;
    let mut agent = value_to_pg_agent(&value)?;
    let idx = usize::from(!piped);
    let arg = |offset| {
        args.get(idx + offset)
            .ok_or_else(|| crate::safety::arg_err("rl_pg_step requires state, action, reward"))
    };
    let Value::Array(values) = arg(0)? else {
        return Err(crate::safety::arg_err("rl_pg_step state must be Array"));
    };
    if values.len() != agent.state_dim {
        return Err(crate::safety::arg_err(
            "rl_pg_step state must match state_dim",
        ));
    }
    pg_history_budget(agent.state_dim, agent.episode_states.len() + 1)?;
    let state = values
        .iter()
        .map(|v| finite_nn_number("rl_pg_step state", v))
        .collect::<Result<Vec<_>>>()?;
    let action = rl_index("rl_pg_step action", arg(1)?, agent.action_size)?;
    let reward = finite_nn_number("rl_pg_step reward", arg(2)?)?;
    agent.record_step(state, action, reward);
    pg_agent_to_value(&agent)
}

/// Finish a nonempty episode using REINFORCE, preserving empty episodes.
fn bi_rl_pg_episode_end(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_pg_episode_end requires agent"))?;
    let mut agent = value_to_pg_agent(&value)?;
    if !agent.episode_states.is_empty() {
        if agent
            .episodes
            .checked_add(1)
            .is_none_or(|n| i64::try_from(n).is_err())
        {
            return Err(crate::safety::arg_err(
                "rl_pg_episode_end episode counter overflow",
            ));
        }
        let weights = pg_dimensions(agent.state_dim, agent.action_size)?;
        if weights
            .checked_mul(agent.episode_states.len())
            .is_none_or(|n| n > 10_000_000)
        {
            return Err(crate::safety::budget_exceeded(
                "rl_pg_episode_end",
                "episode exceeds ten million weight-step pairs".into(),
                "use a smaller policy or shorter episode",
            ));
        }
        agent.end_episode();
        validate_pg_agent(&agent).map_err(|_| {
            crate::safety::bad_state(
                "rl_pg_episode_end",
                "non-finite policy-gradient result",
                "the update exceeded the numeric range",
            )
        })?;
    }
    pg_agent_to_value(&agent)
}

fn ac_dimensions(state_dim: usize, actions: usize) -> Result<()> {
    pg_dimensions(state_dim, actions)?;
    if actions
        .checked_add(1)
        .and_then(|n| n.checked_mul(state_dim))
        .is_none_or(|n| n > MAX_RL_CELLS)
    {
        return Err(crate::safety::budget_exceeded(
            "rl_ac",
            "actor and critic exceed one million weights".into(),
            "use a smaller agent",
        ));
    }
    Ok(())
}
fn validate_ac_agent(agent: &ActorCriticAgent) -> Result<()> {
    ac_dimensions(agent.state_dim, agent.action_size)?;
    if agent.actor_weights.len() != agent.action_size
        || agent
            .actor_weights
            .iter()
            .any(|row| row.len() != agent.state_dim || row.iter().any(|n| !n.is_finite()))
        || agent.critic_weights.len() != agent.state_dim
        || agent.critic_weights.iter().any(|n| !n.is_finite())
    {
        return Err(crate::safety::arg_err(
            "actor/critic weights must match dimensions and be finite",
        ));
    }
    if [agent.actor_lr, agent.critic_lr, agent.discount]
        .iter()
        .any(|n| !n.is_finite() || !(0.0..=1.0).contains(n))
        || i64::try_from(agent.steps).is_err()
    {
        return Err(crate::safety::arg_err(
            "actor/critic rates must be finite probabilities and steps must fit Int",
        ));
    }
    Ok(())
}
fn ac_state(value: &Value, width: usize) -> Result<Vec<f64>> {
    let Value::Array(values) = value else {
        return Err(crate::safety::arg_err("actor/critic state must be Array"));
    };
    if values.len() != width {
        return Err(crate::safety::arg_err(
            "actor/critic state must match state_dim",
        ));
    }
    values
        .iter()
        .map(|v| finite_nn_number("rl_ac_update state", v))
        .collect()
}
/// Create a bounded linear actor and critic with fixed rates.
fn bi_rl_ac_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = expect_string(
        "rl_ac_agent",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("rl_ac_agent requires name"))?,
    )?;
    let states = rl_positive_size(
        "rl_ac_agent",
        args.get(1)
            .ok_or_else(|| crate::safety::arg_err("rl_ac_agent requires state_dim"))?,
    )?;
    let actions = rl_positive_size(
        "rl_ac_agent",
        args.get(2)
            .ok_or_else(|| crate::safety::arg_err("rl_ac_agent requires action_size"))?,
    )?;
    ac_dimensions(states, actions)?;
    ac_agent_to_value(&ActorCriticAgent::new(
        &name, states, actions, 0.01, 0.01, 0.99,
    ))
}
/// Update a validated copy of an actor-critic agent.
fn bi_rl_ac_update(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_ac_update requires agent"))?;
    let mut agent = value_to_ac_agent(&value)?;
    let idx = usize::from(!piped);
    let arg = |offset| {
        args.get(idx + offset).ok_or_else(|| {
            crate::safety::arg_err("rl_ac_update requires state, action, reward, next_state, done")
        })
    };
    let state = ac_state(arg(0)?, agent.state_dim)?;
    let action = rl_index("rl_ac_update action", arg(1)?, agent.action_size)?;
    let reward = finite_nn_number("rl_ac_update reward", arg(2)?)?;
    let next = ac_state(arg(3)?, agent.state_dim)?;
    let Value::Bool(done) = arg(4)? else {
        return Err(crate::safety::arg_err("rl_ac_update done must be Bool"));
    };
    if agent
        .steps
        .checked_add(1)
        .is_none_or(|n| i64::try_from(n).is_err())
    {
        return Err(crate::safety::arg_err("rl_ac_update step counter overflow"));
    }
    agent.update(&state, action, reward, &next, *done);
    validate_ac_agent(&agent).map_err(|_| {
        crate::safety::bad_state(
            "rl_ac_update",
            "non-finite actor-critic result",
            "the update exceeded the numeric range",
        )
    })?;
    ac_agent_to_value(&agent)
}

fn validate_dqn_agent(agent: &DQNAgent) -> Result<()> {
    if agent.state_dim == 0 || agent.action_size == 0 {
        return Err(crate::safety::arg_err("DQN dimensions must be positive"));
    }
    if agent.action_size > 10000
        || agent.network.layers.len() > 127
        || agent.target_network.layers.len() > 127
    {
        return Err(crate::safety::budget_exceeded(
            "rl_dqn",
            "DQN exceeds 10000 actions or 127 dense layers".into(),
            "use a smaller network",
        ));
    }
    let mut total = 0;
    for net in [&agent.network, &agent.target_network] {
        validate_nn(net)?;
        if net
            .layers
            .first()
            .is_none_or(|l| l.input_size != agent.state_dim)
            || net
                .layers
                .last()
                .is_none_or(|l| l.output_size != agent.action_size)
        {
            return Err(crate::safety::arg_err(
                "DQN network endpoints must match state/action dimensions",
            ));
        }
        for layer in &net.layers {
            total = checked_nn_parameter_count(total, layer.input_size, layer.output_size)?;
        }
    }
    if agent.network.layers.len() != agent.target_network.layers.len()
        || agent
            .network
            .layers
            .iter()
            .zip(&agent.target_network.layers)
            .any(|(a, b)| (a.input_size, a.output_size) != (b.input_size, b.output_size))
    {
        return Err(crate::safety::arg_err(
            "DQN policy and target architectures must match",
        ));
    }
    if [
        agent.learning_rate,
        agent.discount,
        agent.epsilon,
        agent.epsilon_decay,
        agent.epsilon_min,
    ]
    .iter()
    .any(|n| !n.is_finite() || !(0.0..=1.0).contains(n))
        || i64::try_from(agent.steps).is_err()
        || agent.batch_size == 0
        || agent.batch_size > 10000
        || agent.target_update_freq == 0
    {
        return Err(crate::safety::arg_err("DQN requires finite probability rates, a representable step count, batch size in 1..=10000 and positive target frequency"));
    }
    let replay = &agent.replay_buffer;
    if replay.capacity == 0
        || replay.buffer.len() > replay.capacity
        || replay.position >= replay.capacity
        || (replay.buffer.len() < replay.capacity && replay.position != replay.buffer.len())
    {
        return Err(crate::safety::arg_err(
            "DQN replay capacity, length and circular position are inconsistent",
        ));
    }
    if replay.capacity > 10000
        || replay
            .buffer
            .len()
            .checked_mul(agent.state_dim)
            .and_then(|n| n.checked_mul(2))
            .is_none_or(|n| n > MAX_RL_CELLS)
    {
        return Err(crate::safety::budget_exceeded(
            "rl_dqn",
            "replay exceeds 10000 capacity or one million state values".into(),
            "use a smaller replay buffer",
        ));
    }
    if replay.buffer.iter().any(|exp| {
        exp.state.len() != agent.state_dim
            || exp.next_state.len() != agent.state_dim
            || exp
                .state
                .iter()
                .chain(&exp.next_state)
                .any(|n| !n.is_finite())
            || exp.action >= agent.action_size
            || !exp.reward.is_finite()
    }) {
        return Err(crate::safety::arg_err(
            "DQN experiences require exact finite state widths, valid actions and finite rewards",
        ));
    }
    Ok(())
}

/// Create bounded policy and target networks with fixed DQN defaults.
fn bi_rl_dqn_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = expect_string(
        "rl_dqn_agent",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("rl_dqn_agent requires name"))?,
    )?;
    let states = rl_positive_size(
        "rl_dqn_agent",
        args.get(1)
            .ok_or_else(|| crate::safety::arg_err("rl_dqn_agent requires state_dim"))?,
    )?;
    let actions = rl_positive_size(
        "rl_dqn_agent",
        args.get(2)
            .ok_or_else(|| crate::safety::arg_err("rl_dqn_agent requires action_size"))?,
    )?;
    if actions > 10000 {
        return Err(crate::safety::budget_exceeded(
            "rl_dqn_agent",
            "DQN exceeds 10000 actions".into(),
            "use fewer actions",
        ));
    }
    let hidden = match args.get(3) {
        None => vec![64, 64],
        Some(Value::Array(values)) if values.len() <= 126 => values
            .iter()
            .map(|v| rl_positive_size("rl_dqn_agent hidden size", v))
            .collect::<Result<Vec<_>>>()?,
        Some(Value::Array(_)) => {
            return Err(crate::safety::budget_exceeded(
                "rl_dqn_agent",
                "DQN exceeds 126 hidden layers".into(),
                "use fewer layers",
            ))
        }
        Some(_) => return Err(crate::safety::arg_err("DQN hidden_sizes must be Array")),
    };
    let sizes: Vec<_> = std::iter::once(states)
        .chain(hidden.iter().copied())
        .chain(std::iter::once(actions))
        .collect();
    let mut total = 0;
    for _ in 0..2 {
        for pair in sizes.windows(2) {
            total = checked_nn_parameter_count(total, pair[0], pair[1])?;
        }
    }
    dqn_agent_to_value(&DQNAgent::new(
        &name, states, actions, &hidden, 0.001, 0.99, 1.0, 10000,
    ))
}

/// Record experience; refuse the unimplemented training path before mutation.
fn bi_rl_dqn_step(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_dqn_step requires agent"))?;
    let mut agent = value_to_dqn_agent(&value)?;
    let idx = usize::from(!piped);
    let arg = |offset| {
        args.get(idx + offset).ok_or_else(|| {
            crate::safety::arg_err("rl_dqn_step requires state, action, reward, next_state, done")
        })
    };
    let state = ac_state(arg(0)?, agent.state_dim)?;
    let action = rl_index("rl_dqn_step action", arg(1)?, agent.action_size)?;
    let reward = finite_nn_number("rl_dqn_step reward", arg(2)?)?;
    let next = ac_state(arg(3)?, agent.state_dim)?;
    let Value::Bool(done) = arg(4)? else {
        return Err(crate::safety::arg_err("rl_dqn_step done must be Bool"));
    };
    if agent
        .steps
        .checked_add(1)
        .is_none_or(|n| i64::try_from(n).is_err())
    {
        return Err(crate::safety::arg_err("rl_dqn_step counter overflow"));
    }
    let next_len = (agent.replay_buffer.len() + 1).min(agent.replay_buffer.capacity);
    if next_len
        .checked_mul(agent.state_dim)
        .and_then(|n| n.checked_mul(2))
        .is_none_or(|n| n > MAX_RL_CELLS)
    {
        return Err(crate::safety::budget_exceeded(
            "rl_dqn_step",
            "replay exceeds one million state values".into(),
            "use a smaller buffer or state",
        ));
    }
    if next_len >= agent.batch_size
        && (agent.network.param_count() + agent.target_network.param_count())
            .checked_mul(agent.batch_size)
            .and_then(|work| work.checked_mul(4))
            .is_none_or(|work| work > 20_000_000)
    {
        return Err(crate::safety::budget_exceeded(
            "rl_dqn_step",
            "training exceeds twenty million estimated dense operations".into(),
            "use a smaller network or batch size",
        ));
    }
    agent
        .step(state, action, reward, next, *done)
        .map_err(|reason| {
            crate::safety::bad_state(
                "rl_dqn_step",
                reason,
                "finite training arithmetic; use smaller values or learning rate",
            )
        })?;
    dqn_agent_to_value(&agent)
}

/// Create an empty bounded replay buffer.
fn bi_rl_replay_buffer(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let capacity = match args.first() {
        None => 10000,
        Some(value) => rl_positive_size("rl_replay_buffer", value)?,
    };
    if capacity > 10000 {
        return Err(crate::safety::budget_exceeded(
            "rl_replay_buffer",
            "replay capacity exceeds 10000".into(),
            "use a smaller capacity",
        ));
    }
    replay_buffer_to_value(&ReplayBuffer::new(capacity))
}

fn grid_dimensions(width: usize, height: usize) -> Result<usize> {
    if width == 0 || height == 0 {
        return Err(crate::safety::arg_err(
            "gridworld dimensions must be positive",
        ));
    }
    width
        .checked_mul(height)
        .filter(|n| *n <= MAX_RL_CELLS)
        .ok_or_else(|| {
            crate::safety::budget_exceeded(
                "rl_gridworld",
                "gridworld exceeds one million cells".into(),
                "use smaller dimensions",
            )
        })
}

fn validate_gridworld(env: &GridWorld) -> Result<()> {
    grid_dimensions(env.width, env.height)?;
    if env.agent_pos.0 >= env.width
        || env.agent_pos.1 >= env.height
        || env.goal_pos.0 >= env.width
        || env.goal_pos.1 >= env.height
        || env
            .obstacles
            .iter()
            .any(|&(x, y)| x >= env.width || y >= env.height)
    {
        return Err(crate::safety::arg_err(
            "gridworld positions must be within dimensions",
        ));
    }
    if env.obstacles.len() > 10000 {
        return Err(crate::safety::budget_exceeded(
            "rl_gridworld",
            "gridworld exceeds 10000 obstacle entries".into(),
            "use fewer obstacles",
        ));
    }
    Ok(())
}

/// Create a positive bounded gridworld.
fn bi_rl_gridworld(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let width = match args.first() {
        None => 5,
        Some(value) => rl_positive_size("rl_gridworld width", value)?,
    };
    let height = match args.get(1) {
        None => width,
        Some(value) => rl_positive_size("rl_gridworld height", value)?,
    };
    grid_dimensions(width, height)?;
    gridworld_to_value(&GridWorld::new(width, height))
}

/// Move a validated gridworld copy by one clamped cardinal step.
fn bi_rl_env_step(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let piped = input.is_some();
    let value = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("rl_env_step requires environment"))?;
    let mut env = value_to_gridworld(&value)?;
    let action = rl_index(
        "rl_env_step action",
        args.get(usize::from(!piped))
            .ok_or_else(|| crate::safety::arg_err("rl_env_step requires action"))?,
        4,
    )?;
    let (state, reward, done) = env.step(action);
    Ok(Value::Record(BTreeMap::from([
        ("state".into(), Value::Int(state as i64)),
        ("reward".into(), Value::Float(reward)),
        ("done".into(), Value::Bool(done)),
        ("env".into(), gridworld_to_value(&env)?),
    ])))
}

// ==================== RL Helper Functions ====================

fn q_agent_to_value(agent: &QLearningAgent) -> Result<Value> {
    validate_q_agent(agent)?;
    let mut rows: Vec<_> = agent
        .q_table
        .iter()
        .map(|(&(state, action), &q)| (state, action, q))
        .collect();
    rows.sort_by_key(|&(state, action, _)| (state, action));
    let json = serde_json::json!({
        "name": agent.name, "state_size": agent.state_size, "action_size": agent.action_size,
        "learning_rate": agent.learning_rate, "discount": agent.discount, "epsilon": agent.epsilon,
        "epsilon_decay": agent.epsilon_decay, "epsilon_min": agent.epsilon_min, "steps": agent.steps,
        "q_table": rows,
    }).to_string();

    let mut rec = BTreeMap::new();
    rec.insert(
        "type".to_string(),
        Value::Str("q_learning_agent".to_string()),
    );
    rec.insert("name".to_string(), Value::Str(agent.name.clone()));
    rec.insert(
        "state_size".to_string(),
        Value::Int(agent.state_size as i64),
    );
    rec.insert(
        "action_size".to_string(),
        Value::Int(agent.action_size as i64),
    );
    rec.insert("epsilon".to_string(), Value::Float(agent.epsilon));
    rec.insert("steps".to_string(), Value::Int(agent.steps as i64));
    rec.insert("_data".to_string(), Value::Str(json));

    Ok(Value::Record(rec))
}

fn value_to_q_agent(value: &Value) -> Result<QLearningAgent> {
    let Value::Record(record) = value else {
        return Err(crate::safety::arg_err("Q-learning agent must be a Record"));
    };
    let Some(Value::Str(data)) = record.get("_data") else {
        return Err(crate::safety::arg_err(
            "Q-learning agent requires _data: String",
        ));
    };
    if data.len() > 64 * 1024 * 1024 {
        return Err(crate::safety::budget_exceeded(
            "rl",
            "Q-learning encoding exceeds 64 MiB".into(),
            "use a smaller agent",
        ));
    }
    let mut wire: serde_json::Value = serde_json::from_str(data).map_err(|e| {
        crate::safety::bad_arg("rl", "valid encoded Q-learning agent", &e.to_string())
    })?;
    let rows = match wire.get_mut("q_table") {
        Some(value @ serde_json::Value::Array(_)) => {
            std::mem::replace(value, serde_json::json!({}))
        }
        Some(serde_json::Value::Object(table)) if table.is_empty() => serde_json::json!([]),
        _ => {
            return Err(crate::safety::arg_err(
                "Q-learning q_table must contain row triples or a legacy empty object",
            ))
        }
    };
    let mut agent: QLearningAgent = serde_json::from_value(wire).map_err(|e| {
        crate::safety::bad_arg("rl", "valid encoded Q-learning agent", &e.to_string())
    })?;
    validate_q_agent(&agent)?;
    let rows = rows.as_array().expect("row representation was checked");
    if rows.len() > MAX_RL_CELLS {
        return Err(crate::safety::budget_exceeded(
            "rl",
            "Q-learning table exceeds one million entries".into(),
            "use a smaller agent",
        ));
    }
    for row in rows {
        let Some(row) = row.as_array().filter(|row| row.len() == 3) else {
            return Err(crate::safety::arg_err(
                "Q-learning rows must be [state, action, finite value]",
            ));
        };
        let index = |value: &serde_json::Value, limit| {
            value
                .as_u64()
                .and_then(|n| usize::try_from(n).ok())
                .filter(|n| *n < limit)
                .ok_or_else(|| {
                    crate::safety::arg_err("Q-learning row indices must be in-range integers")
                })
        };
        let state = index(&row[0], agent.state_size)?;
        let action = index(&row[1], agent.action_size)?;
        let q = row[2].as_f64().filter(|n| n.is_finite()).ok_or_else(|| {
            crate::safety::arg_err("Q-learning row values must be finite numbers")
        })?;
        if agent.q_table.insert((state, action), q).is_some() {
            return Err(crate::safety::arg_err(
                "Q-learning rows contain duplicate state-action pairs",
            ));
        }
    }
    Ok(agent)
}

