// Was `(Get-CimInstance Win32_Process -Filter ProcessId=N).CommandLine` run
// through PowerShell and split on whitespace here; now read in process.
// sysinfo's cmd() is the command line as CommandLineToArgvW splits it, so each
// element is one argument.
#[cfg(windows)]
fn proc_cmdline_of(pid: i64) -> Result<Vec<String>> {
    let spid = sysinfo::Pid::from_u32(pid as u32);
    let mut sys = System::new();
    sys.refresh_processes_specifics(
        sysinfo::ProcessesToUpdate::Some(&[spid]),
        true,
        sysinfo::ProcessRefreshKind::nothing().with_cmd(sysinfo::UpdateKind::Always),
    );
    let argv: Vec<String> = sys
        .process(spid)
        .map(|process| {
            process
                .cmd()
                .iter()
                .map(|arg| arg.to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    if argv.is_empty() {
        return Err(crate::safety::os_denied(
            "proc_cmdline",
            format!("proc_cmdline: the command line of process {pid} is not readable"),
            "the process is protected or belongs to another user; read the command line of a process this user owns",
        ));
    }
    Ok(argv)
}

#[cfg(target_os = "linux")]
fn proc_cmdline_of(pid: i64) -> Result<Vec<String>> {
    let data = std::fs::read(format!("/proc/{pid}/cmdline"))
        .map_err(|e| proc_read_failed("proc_cmdline", pid, "its command line", &e))?;
    // A zombie or kernel thread has no arguments at all.
    if data.is_empty() {
        return Ok(vec![]);
    }
    // Every argument ends in a NUL, so drop the one trailing terminator and
    // split on the rest. An empty argument is a real argument, not noise.
    let body: &[u8] = data.strip_suffix(&[0u8][..]).unwrap_or(&data[..]);
    Ok(body
        .split(|&b| b == 0)
        .map(|arg| String::from_utf8_lossy(arg).into_owned())
        .collect())
}

#[cfg(all(not(windows), not(target_os = "linux")))]
fn proc_cmdline_of(pid: i64) -> Result<Vec<String>> {
    let out = proc_tool(
        "proc_cmdline",
        "ps",
        {
            let mut c = Command::new("ps");
            c.args(["-p", &pid.to_string(), "-o", "args="]);
            c
        },
        PROBE_DEADLINE_SECS,
    )?;
    let line = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if line.is_empty() {
        return Err(crate::safety::tool_failed(
            "proc_cmdline",
            "ps",
            Some(0),
            "its output named no command line",
        ));
    }
    // ps does not quote its output, so an argument with a space is split.
    let argv: Vec<String> = line.split_whitespace().map(str::to_string).collect();
    Ok(argv)
}

fn bi_proc_cmdline(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    proc_check("proc_cmdline", &args, &input, 1)?;
    let pid = proc_pid("proc_cmdline", args.first())?;
    proc_require("proc_cmdline", pid)?;
    let argv = proc_cmdline_of(pid)?;
    Ok(Value::Array(argv.into_iter().map(Value::Str).collect()))
}

/// Seconds since the Unix epoch, as UTC ISO 8601 to the second. One form on
/// every OS: `ps lstart` and `ToString('o')` gave three different spellings,
/// and the Unix one changed with the locale.
fn proc_utc_iso(pid: i64, secs: u64) -> Result<String> {
    let at = i64::try_from(secs)
        .ok()
        .and_then(|s| chrono::DateTime::<chrono::Utc>::from_timestamp(s, 0))
        .ok_or_else(|| {
            crate::safety::tool_failed(
                "proc_start_time",
                "sysinfo",
                Some(0),
                &format!("the start time of process {pid} is out of range"),
            )
        })?;
    Ok(at.format("%Y-%m-%dT%H:%M:%SZ").to_string())
}

fn bi_proc_start_time(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    proc_check("proc_start_time", &args, &input, 1)?;
    let pid = proc_pid("proc_start_time", args.first())?;
    let sys = proc_sys(pid);
    let secs = sys
        .process(sysinfo::Pid::from_u32(pid as u32))
        .ok_or_else(|| crate::safety::not_found("proc_start_time", "process", &pid.to_string()))?
        .start_time();
    Ok(Value::Str(proc_utc_iso(pid, secs)?))
}

/// Sends a stop or continue signal. Unix sends it with kill(2), as proc_kill
/// does. Windows opens the process with PROCESS_SUSPEND_RESUME and calls
/// ntdll's NtSuspendProcess or NtResumeProcess: see the Windows definition.
#[cfg(unix)]
fn proc_signal(builtin: &str, pid: i64, name: &str) -> Result<Value> {
    let sig = if name == "STOP" {
        libc::SIGSTOP
    } else {
        libc::SIGCONT
    };
    let native = libc::pid_t::try_from(pid).map_err(|_| {
        crate::safety::bad_arg(
            builtin,
            "a process id that fits the operating system's pid type",
            &pid.to_string(),
        )
    })?;
    // SAFETY: kill(2) takes a pid and a signal number and touches no memory.
    if unsafe { libc::kill(native, sig) } == 0 {
        return Ok(Value::Bool(true));
    }
    let err = std::io::Error::last_os_error();
    Err(match err.raw_os_error() {
        Some(libc::ESRCH) => crate::safety::not_found(builtin, "process", &pid.to_string()),
        Some(libc::EPERM) => crate::safety::os_denied(
            builtin,
            format!("{builtin}: the operating system denied SIG{name} to process {pid} (EPERM)"),
            "the process belongs to another user or is protected; signal a process this user owns",
        ),
        _ => crate::safety::tool_failed(
            builtin,
            &format!("kill({pid}, SIG{name})"),
            None,
            &err.to_string(),
        ),
    })
}

/// The Windows half of [`proc_signal`]. A PowerShell script, built with
/// `ps_script!` so no caller text reaches it, opens the process with
/// PROCESS_SUSPEND_RESUME (0x0800), calls NtSuspendProcess or NtResumeProcess
/// through Add-Type P/Invoke, and closes the handle. It prints one coded line:
/// `ok`, `err:open:<GetLastError>` or `err:nt:<NTSTATUS in hex>`. That line is
/// the only thing read back; prose from PowerShell is never parsed.
#[cfg(windows)]
fn proc_signal(builtin: &str, pid: i64, name: &str) -> Result<Value> {
    const PRELUDE: &str = "$ErrorActionPreference = 'Stop'; Add-Type -Namespace AetherProc -Name Native -MemberDefinition '[DllImport(\"kernel32.dll\", SetLastError=true)] public static extern IntPtr OpenProcess(uint access, bool inherit, uint pid); [DllImport(\"kernel32.dll\", SetLastError=true)] public static extern bool CloseHandle(IntPtr handle); [DllImport(\"ntdll.dll\")] public static extern int NtSuspendProcess(IntPtr handle); [DllImport(\"ntdll.dll\")] public static extern int NtResumeProcess(IntPtr handle);'; ";
    let nt: &'static str = if name == "STOP" {
        "NtSuspendProcess"
    } else {
        "NtResumeProcess"
    };
    let cmd = crate::ps_script!(
        "{}$h = [AetherProc.Native]::OpenProcess(0x0800, $false, {}); if ($h -eq [IntPtr]::Zero) {{ 'err:open:' + [Runtime.InteropServices.Marshal]::GetLastWin32Error() }} else {{ $s = [AetherProc.Native]::{}($h); [void][AetherProc.Native]::CloseHandle($h); if ($s -eq 0) {{ 'ok' }} else {{ 'err:nt:' + $s.ToString('X8') }} }}",
        PRELUDE,
        pid,
        nt
    );
    let mut c = Command::new("powershell");
    c.args(["-NoProfile", "-NonInteractive", "-Command", &cmd]);
    let out = bounded_cmd_output(builtin, "powershell", c, TOOL_DEADLINE_SECS)?;
    let stdout = String::from_utf8_lossy(&out.stdout);
    let verdict = stdout
        .lines()
        .map(str::trim)
        .find(|l| *l == "ok" || l.starts_with("err:"));
    match verdict {
        Some("ok") => Ok(Value::Bool(true)),
        Some("err:open:5") => Err(crate::safety::os_denied(
            builtin,
            format!("{builtin}: the operating system denied PROCESS_SUSPEND_RESUME to process {pid} (ERROR_ACCESS_DENIED)"),
            "the process is protected or belongs to another user; act on a process this user owns",
        )),
        Some("err:open:87") => Err(crate::safety::not_found(
            builtin,
            "process",
            &pid.to_string(),
        )),
        Some(line) if line.starts_with("err:open:") => Err(crate::safety::tool_failed(
            builtin,
            "OpenProcess",
            None,
            &format!("OpenProcess on process {pid} failed: {line}"),
        )),
        Some(line) if line.starts_with("err:nt:") => Err(crate::safety::tool_failed(
            builtin,
            nt,
            None,
            &format!(
                "{nt} on process {pid} returned NTSTATUS 0x{}",
                &line["err:nt:".len()..]
            ),
        )),
        _ => Err(crate::safety::tool_failed(
            builtin,
            "powershell",
            out.status.code(),
            &String::from_utf8_lossy(&out.stderr),
        )),
    }
}

#[cfg(not(any(unix, windows)))]
fn proc_signal(builtin: &str, pid: i64, name: &str) -> Result<Value> {
    Err(crate::safety::unimplemented(
        builtin,
        &format!("sending the {name} signal to process {pid}: this platform has no suspend or resume call in this shell"),
        "use proc_kill to end the process",
    ))
}

