fn bi_group_members(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let group = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "group_members",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    crate::safety::reject_option_like("group_members", std::slice::from_ref(&group))?;
    #[cfg(target_os = "windows")]
    {
        let mut cmd = std::process::Command::new("powershell");
        cmd.args([
            "-Command",
            &crate::ps_script!(
                "Get-LocalGroupMember {} | Select-Object Name | ConvertTo-Json",
                crate::safety::ps_quote(&group)
            ),
        ]);
        let output = bounded_cmd_output("group_members", "powershell", cmd, PROBE_DEADLINE_SECS)?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                let items = match &json {
                    serde_json::Value::Array(arr) => arr.clone(),
                    obj @ serde_json::Value::Object(_) => vec![obj.clone()],
                    _ => vec![],
                };
                let members: Vec<Value> = items
                    .iter()
                    .filter_map(|obj| {
                        obj.as_object()?
                            .get("Name")?
                            .as_str()
                            .map(|s| Value::Str(s.to_string()))
                    })
                    .collect();
                return Ok(Value::Array(members));
            }
        }
        return Err(crate::safety::tool_failed(
            "group_members",
            "Get-LocalGroupMember",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    #[cfg(not(target_os = "windows"))]
    {
        let mut cmd = std::process::Command::new("getent");
        cmd.args(["group", &group]);
        let output = bounded_cmd_output("group_members", "getent", cmd, PROBE_DEADLINE_SECS)?;
        if output.status.success() {
            let line = String::from_utf8_lossy(&output.stdout);
            if let Some(members) = line.split(':').nth(3) {
                let member_list: Vec<Value> = members
                    .trim()
                    .split(',')
                    .filter(|s| !s.is_empty())
                    .map(|s| Value::Str(s.to_string()))
                    .collect();
                return Ok(Value::Array(member_list));
            }
        }
        // getent exits 2 for a name it does not know. An unknown group, a
        // failed query and a group with no members all answered [].
        if output.status.code() == Some(2) {
            return Err(crate::safety::not_found("group_members", "group", &group));
        }
        Err(crate::safety::tool_failed(
            "group_members",
            "getent",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ))
    }
}

fn bi_perm_get(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "perm_get",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    // A path that could not be read was null.
    let meta =
        std::fs::metadata(&path).map_err(|e| crate::safety::fs_error("perm_get", &path, &e))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = meta.permissions().mode();
        return Ok(Value::Str(format!("{:o}", mode & 0o777)));
    }
    #[cfg(not(unix))]
    {
        let readonly = meta.permissions().readonly();
        Ok(Value::Str(
            if readonly { "readonly" } else { "readwrite" }.to_string(),
        ))
    }
}

fn bi_perm_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    guard_and_set_permission_mode("perm_set", args, input)
}

fn bi_perm_check(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if !(1..=2).contains(&args.len()) || input.is_some() {
        return Err(crate::safety::arg_err(
            "perm_check requires path and optional mode, without pipeline input",
        ));
    }
    let mut args = args.into_iter();
    let Some(Value::Str(path)) = args.next() else {
        return Err(crate::safety::arg_err("perm_check path must be String"));
    };
    let mode = match args.next() {
        None => "r".to_string(),
        Some(Value::Str(mode))
            if matches!(
                mode.as_str(),
                "r" | "read" | "w" | "write" | "x" | "execute"
            ) =>
        {
            mode
        }
        _ => {
            return Err(crate::safety::arg_err(
                "perm_check mode must be r/read, w/write or x/execute",
            ))
        }
    };
    let path = crate::safety::resolve_path_str(&path);
    let metadata =
        fs::metadata(&path).map_err(|e| crate::safety::fs_error("perm_check", &path, &e))?;
    // This is a metadata query, not an access check for the caller's identity,
    // ACLs, privileges, mount flags or sharing restrictions.
    match mode.as_str() {
        "r" | "read" => Ok(Value::Bool(true)),
        "w" | "write" => Ok(Value::Bool(!metadata.permissions().readonly())),
        "x" | "execute" => {
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                Ok(Value::Bool(metadata.permissions().mode() & 0o111 != 0))
            }
            #[cfg(windows)]
            {
                Ok(Value::Bool(
                    metadata.is_file() && windows_pathext_executable(std::path::Path::new(&path)),
                ))
            }
            #[cfg(not(any(unix, windows)))]
            {
                Err(crate::safety::unimplemented(
                    "perm_check",
                    "execute permission bits are unavailable on this platform",
                    "inspect platform-specific executable formats and access controls",
                ))
            }
        }
        _ => unreachable!("validated permission mode"),
    }
}

/// Windows executability is a naming rule, not an ACL check: a regular file
/// whose extension appears in PATHEXT (default `.COM;.EXE;.BAT;.CMD`).
#[cfg(windows)]
fn windows_pathext_executable(path: &std::path::Path) -> bool {
    let Some(extension) = path.extension().and_then(|e| e.to_str()) else {
        return false;
    };
    let pathext = std::env::var("PATHEXT")
        .ok()
        .filter(|v| !v.trim().is_empty())
        .unwrap_or_else(|| ".COM;.EXE;.BAT;.CMD".to_string());
    pathext
        .split(';')
        .map(|entry| entry.trim().trim_start_matches('.'))
        .filter(|entry| !entry.is_empty())
        .any(|entry| entry.eq_ignore_ascii_case(extension))
}

