/// Capability numbers from `linux/capability.h`, in order. A bit beyond the
/// end of this table (a newer kernel) is reported as `cap_<n>`, not dropped.
#[cfg(target_os = "linux")]
const LINUX_CAPABILITIES: [&str; 41] = [
    "cap_chown",
    "cap_dac_override",
    "cap_dac_read_search",
    "cap_fowner",
    "cap_fsetid",
    "cap_kill",
    "cap_setgid",
    "cap_setuid",
    "cap_setpcap",
    "cap_linux_immutable",
    "cap_net_bind_service",
    "cap_net_broadcast",
    "cap_net_admin",
    "cap_net_raw",
    "cap_ipc_lock",
    "cap_ipc_owner",
    "cap_sys_module",
    "cap_sys_rawio",
    "cap_sys_chroot",
    "cap_sys_ptrace",
    "cap_sys_pacct",
    "cap_sys_admin",
    "cap_sys_boot",
    "cap_sys_nice",
    "cap_sys_resource",
    "cap_sys_time",
    "cap_sys_tty_config",
    "cap_mknod",
    "cap_lease",
    "cap_audit_write",
    "cap_audit_control",
    "cap_setfcap",
    "cap_mac_override",
    "cap_mac_admin",
    "cap_syslog",
    "cap_wake_alarm",
    "cap_block_suspend",
    "cap_audit_read",
    "cap_perfmon",
    "cap_bpf",
    "cap_checkpoint_restore",
];

#[cfg(target_os = "linux")]
fn decode_capability_mask(hex: &str) -> Option<Vec<Value>> {
    let mask = u64::from_str_radix(hex.trim(), 16).ok()?;
    Some(
        (0..64u32)
            .filter(|bit| mask & (1u64 << bit) != 0)
            .map(|bit| {
                Value::Str(match LINUX_CAPABILITIES.get(bit as usize) {
                    Some(name) => name.to_string(),
                    None => format!("cap_{bit}"),
                })
            })
            .collect(),
    )
}

fn bi_capabilities(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // This parsed `capsh --print`, and got it wrong: capsh writes the
    // effective set as `Current: =...`, with a colon, so the set an agent
    // most needs was never extracted (it surfaced as a key named
    // "current:"), `uid` came back as the string "1000(test) euid=1000(test)",
    // and hosts without libcap's tools failed outright. The kernel publishes
    // all five sets in /proc/self/status as bitmasks; decode those.
    #[cfg(target_os = "linux")]
    {
        let status = std::fs::read_to_string("/proc/self/status")
            .map_err(|e| crate::safety::fs_error("capabilities", "/proc/self/status", &e))?;
        let mut rec = std::collections::BTreeMap::new();
        for line in status.lines() {
            let Some((key, val)) = line.split_once(':') else {
                continue;
            };
            let field = match key {
                "CapInh" => "inheritable",
                "CapPrm" => "permitted",
                "CapEff" => "effective",
                "CapBnd" => "bounding",
                "CapAmb" => "ambient",
                "NoNewPrivs" => {
                    rec.insert("no_new_privs".to_string(), Value::Bool(val.trim() == "1"));
                    continue;
                }
                "Uid" | "Gid" => {
                    // real, effective, saved, filesystem
                    let ids: Vec<i64> = val
                        .split_whitespace()
                        .filter_map(|v| v.parse().ok())
                        .collect();
                    let (real, eff) = if key == "Uid" {
                        ("uid", "euid")
                    } else {
                        ("gid", "egid")
                    };
                    if let [r, e, ..] = ids[..] {
                        rec.insert(real.to_string(), Value::Int(r));
                        rec.insert(eff.to_string(), Value::Int(e));
                    }
                    continue;
                }
                _ => continue,
            };
            let caps = decode_capability_mask(val).ok_or_else(|| {
                crate::safety::bad_state(
                    "capabilities",
                    &format!(
                        "/proc/self/status has an unreadable {key} mask: {}",
                        val.trim()
                    ),
                    "this kernel reports capabilities in a format this shell does not know",
                )
            })?;
            rec.insert(field.to_string(), Value::Array(caps));
        }
        for field in [
            "inheritable",
            "permitted",
            "effective",
            "bounding",
            "ambient",
        ] {
            if !rec.contains_key(field) {
                return Err(crate::safety::bad_state(
                    "capabilities",
                    &format!("/proc/self/status does not report the {field} set"),
                    "this kernel predates the capability set, or /proc is not procfs",
                ));
            }
        }
        return Ok(Value::Record(rec));
    }
    // Windows has no capability bitmasks; its privileges are listed by
    // `whoami /priv`, a read-only system tool run without a shell.
    #[cfg(windows)]
    {
        return windows_privileges();
    }
    // Linux capability sets are a Linux concept. Everywhere else this fell
    // through to `Ok(Value::Null)`, which a caller reads as "this process
    // has no capabilities" -- a claim about privilege, made without looking.
    #[allow(unreachable_code)]
    Err(crate::safety::unimplemented(
        "capabilities",
        "Linux capability sets do not exist on this operating system; NOTHING WAS INSPECTED",
        "use `id` on this system",
    ))
}

/// The privileges of this Windows process, from `whoami /priv /fo csv`, as
/// `{privileges: [{name, description, state}]}`. The shape differs from the
/// Linux record because Windows has no capability masks.
#[cfg(windows)]
fn windows_privileges() -> Result<Value> {
    let run = tool_run(
        "capabilities",
        "whoami",
        None,
        &["/priv", "/fo", "csv"],
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_DEADLINE_SECS,
    )?;
    if !run.success {
        return Err(crate::safety::tool_failed(
            "capabilities",
            &run.command,
            run.code,
            &run.stderr,
        ));
    }
    let rows = parse_whoami_priv_csv("capabilities", &run.stdout)?;
    let mut rec = BTreeMap::new();
    rec.insert("privileges".to_string(), Value::Array(rows));
    Ok(Value::Record(rec))
}

/// Parses the CSV that `whoami /priv /fo csv` prints. Lines before the header
/// that have one field (a title) are skipped. The header must name the three
/// columns in English; any other layout is refused, not guessed at. Every line
/// after it must hold exactly three fields, or the whole answer is refused.
#[cfg(any(windows, test))]
fn parse_whoami_priv_csv(builtin: &str, text: &str) -> Result<Vec<Value>> {
    const HEADER: [&str; 3] = ["Privilege Name", "Description", "State"];
    let mut rows = Vec::new();
    let mut seen_header = false;
    for line in text.lines() {
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        let Some(fields) = csv_fields(line) else {
            return Err(crate::safety::bad_state(
                builtin,
                &format!("whoami /priv printed a malformed CSV line: {line:?}"),
                "this host's whoami output is not the CSV layout this shell reads",
            ));
        };
        if !seen_header {
            if fields.len() == 1 {
                continue;
            }
            if fields.iter().map(String::as_str).eq(HEADER) {
                seen_header = true;
                continue;
            }
            return Err(crate::safety::bad_state(
                builtin,
                &format!("whoami /priv printed an unexpected header: {line:?}"),
                "the privilege table is read only in its English layout",
            ));
        }
        if fields.len() != 3 {
            return Err(crate::safety::bad_state(
                builtin,
                &format!(
                    "whoami /priv printed a line with {} fields, not 3: {line:?}",
                    fields.len()
                ),
                "this host's whoami output is not the CSV layout this shell reads",
            ));
        }
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(fields[0].clone()));
        rec.insert("description".to_string(), Value::Str(fields[1].clone()));
        rec.insert("state".to_string(), Value::Str(fields[2].clone()));
        rows.push(Value::Record(rec));
    }
    if !seen_header {
        return Err(crate::safety::bad_state(
            builtin,
            "whoami /priv printed no privilege table",
            "this host's whoami output is not the CSV layout this shell reads",
        ));
    }
    Ok(rows)
}

/// Splits one CSV line into fields. A field may be quoted, and a quoted field
/// may hold commas and doubled quotes (""). None for an unterminated quote or
/// text between a closing quote and the next comma.
#[cfg(any(windows, test))]
fn csv_fields(line: &str) -> Option<Vec<String>> {
    let mut fields = Vec::new();
    let mut chars = line.chars().peekable();
    loop {
        let mut field = String::new();
        if chars.peek() == Some(&'"') {
            chars.next();
            loop {
                match chars.next() {
                    None => return None,
                    Some('"') => {
                        if chars.peek() == Some(&'"') {
                            chars.next();
                            field.push('"');
                        } else {
                            break;
                        }
                    }
                    Some(c) => field.push(c),
                }
            }
            match chars.next() {
                None => {
                    fields.push(field);
                    return Some(fields);
                }
                Some(',') => {}
                Some(_) => return None,
            }
        } else {
            loop {
                match chars.next() {
                    None => {
                        fields.push(field);
                        return Some(fields);
                    }
                    Some(',') => break,
                    Some(c) => field.push(c),
                }
            }
        }
        fields.push(field);
    }
}

#[cfg(test)]
mod whoami_csv_tests {
    use super::*;

    const SAMPLE: &str = "\"Privilege Name\",\"Description\",\"State\"\r\n\
\"SeShutdownPrivilege\",\"Shut down the system\",\"Disabled\"\r\n\
\"SeChangeNotifyPrivilege\",\"Bypass traverse checking, for any user\",\"Enabled\"\r\n\
\"SeUndockPrivilege\",\"Say \"\"undock\"\"\",\"Disabled\"\r\n";

    fn field(v: &Value, key: &str) -> String {
        match v {
            Value::Record(r) => match r.get(key) {
                Some(Value::Str(s)) => s.clone(),
                other => panic!("{key}: {other:?}"),
            },
            other => panic!("not a record: {other:?}"),
        }
    }

    #[test]
    fn parses_names_descriptions_and_states_including_quoted_commas() {
        let rows = parse_whoami_priv_csv("capabilities", SAMPLE).expect("sample parses");
        assert_eq!(rows.len(), 3);
        assert_eq!(field(&rows[0], "name"), "SeShutdownPrivilege");
        assert_eq!(field(&rows[0], "state"), "Disabled");
        assert_eq!(
            field(&rows[1], "description"),
            "Bypass traverse checking, for any user"
        );
        assert_eq!(field(&rows[2], "description"), "Say \"undock\"");
    }

    #[test]
    fn skips_a_title_line_before_the_header() {
        let text = format!("\"PRIVILEGES INFORMATION\"\n\n{SAMPLE}");
        assert_eq!(
            parse_whoami_priv_csv("capabilities", &text).unwrap().len(),
            3
        );
    }

    #[test]
    fn a_malformed_line_refuses_the_whole_answer() {
        let text = "\"Privilege Name\",\"Description\",\"State\"\n\
\"SeShutdownPrivilege\",\"Shut down the system\",\"Disabled\"\n\
\"SeBroken\",\"unterminated,\"Enabled\n";
        let err = parse_whoami_priv_csv("capabilities", text).expect_err("malformed");
        assert!(err.to_string().contains("E_BAD_STATE"), "{err}");
    }

    #[test]
    fn a_line_with_the_wrong_field_count_refuses() {
        let text = "\"Privilege Name\",\"Description\",\"State\"\n\"SeOnly\",\"Enabled\"\n";
        let err = parse_whoami_priv_csv("capabilities", text).expect_err("two fields");
        assert!(err.to_string().contains("E_BAD_STATE"), "{err}");
    }

    #[test]
    fn a_localised_header_refuses_rather_than_guessing() {
        let err = parse_whoami_priv_csv("capabilities", "\"Name\",\"Desc\",\"Status\"\n")
            .expect_err("header");
        assert!(err.to_string().contains("E_BAD_STATE"), "{err}");
    }

    #[test]
    fn csv_fields_rejects_text_after_a_closing_quote() {
        assert_eq!(csv_fields("\"a\"b,c"), None);
        assert_eq!(
            csv_fields("a,\"b,c\",d"),
            Some(vec!["a".to_string(), "b,c".to_string(), "d".to_string()])
        );
    }
}

// ============================================================================
// 370-389: Package Management
// ============================================================================

fn detect_package_manager() -> &'static str {
    #[cfg(target_os = "windows")]
    {
        "winget"
    }
    #[cfg(target_os = "macos")]
    {
        return "brew";
    }
    #[cfg(target_os = "linux")]
    {
        if std::path::Path::new("/usr/bin/apt").exists() {
            return "apt";
        }
        if std::path::Path::new("/usr/bin/dnf").exists() {
            return "dnf";
        }
        if std::path::Path::new("/usr/bin/yum").exists() {
            return "yum";
        }
        if std::path::Path::new("/usr/bin/pacman").exists() {
            return "pacman";
        }
        return "apt";
    }
}

fn bi_pkg_list(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if !args.is_empty() {
        return Err(crate::safety::arg_err(format!(
            "pkg_list takes no arguments, got {}",
            args.len()
        )));
    }
    linux_diagnostics::no_pipeline_input("pkg_list", &input)?;
    let packages = match detect_package_manager() {
        "apt" => pkg_query::list_dpkg("pkg_list")?,
        "pacman" => pkg_query::list_pacman("pkg_list")?,
        "dnf" | "yum" => pkg_query::list_rpm("pkg_list")?,
        "brew" => pkg_query::list_brew("pkg_list")?,
        #[cfg(windows)]
        "winget" => pkg_query::list_windows_arp("pkg_list")?,
        other => {
            return Err(crate::safety::unimplemented(
                "pkg_list",
                &format!(
                    "pkg_list is not implemented for the {other} package manager in 13.0.0; NOTHING WAS LISTED"
                ),
                "list the packages with that manager directly",
            ))
        }
    };
    Ok(Value::Array(
        packages
            .into_iter()
            .map(|(name, version)| {
                let mut rec = std::collections::BTreeMap::new();
                rec.insert("name".to_string(), Value::Str(name));
                // Only a Windows program can record no version.
                let version = if version.is_empty() {
                    Value::Null
                } else {
                    Value::Str(version)
                };
                rec.insert("version".to_string(), version);
                Value::Record(rec)
            })
            .collect(),
    ))
}

/// This package manager is not one the builtin knows how to query. These
/// answered [] ("no files", "no results"), null, or -- for pkg_verify --
/// `true`, "verified", without inspecting anything.
fn pkg_unsupported(builtin: &str, pm: &str) -> anyhow::Error {
    crate::safety::unimplemented(
        builtin,
        &format!(
            "{builtin} is not implemented for the {pm} package manager; NOTHING WAS INSPECTED"
        ),
        "query the package manager directly",
    )
}

/// Whether a nonzero exit from a package query is that tool's documented
/// "nothing matched" answer rather than a failure. Each rule is one tool's own
/// convention: `dpkg -S` and `dpkg-query -L` exit 1 when no package owns the
/// path or the package is not installed; `pacman -Ss` exits 1 with no output
/// when nothing matches; the pacman queries exit 1 with "was not found" or "No
/// package owns" on stderr; `apt-cache show|depends|rdepends` report "No
/// packages found". The text rules are English only: a localised message is
/// not recognised, so it is E_TOOL_FAILED, which still carries the stderr.
fn pkg_no_match(builtin: &str, pm: &str, status: Option<i32>, stderr: &str) -> bool {
    match pm {
        "apt" => {
            (matches!(builtin, "pkg_owner" | "pkg_files") && status == Some(1))
                || stderr.contains("No packages found")
        }
        "pacman" => {
            status == Some(1)
                && ((builtin == "pkg_search" && stderr.trim().is_empty())
                    || stderr.contains("was not found")
                    || stderr.contains("No package owns"))
        }
        "dnf" | "yum" => {
            stderr.contains("No matching Packages") || stderr.contains("No matches found")
        }
        "brew" => stderr.contains("No available formula") || stderr.contains("No available cask"),
        _ => false,
    }
}

/// The error for a package query that exited nonzero. The documented no-match
/// is E_NOT_FOUND naming what was asked for; any other exit is E_TOOL_FAILED
/// with the exit code and the tool's stderr.
fn pkg_query_failure(
    builtin: &str,
    kind: &str,
    name: &str,
    pm: &str,
    program: &str,
    status: Option<i32>,
    stderr: &str,
) -> anyhow::Error {
    if pkg_no_match(builtin, pm, status, stderr) {
        crate::safety::not_found(builtin, kind, name)
    } else {
        crate::safety::tool_failed(builtin, program, status, stderr)
    }
}

fn bi_pkg_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let query = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_search",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_search", std::slice::from_ref(&query))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("apt-cache");
            cmd.args(["search", &query]);
            bounded_cmd_output("pkg_search", "apt-cache", cmd, TOOL_DEADLINE_SECS)?
        }
        "dnf" | "yum" => {
            let mut cmd = std::process::Command::new(pm);
            cmd.args(["search", &query]);
            bounded_cmd_output("pkg_search", pm, cmd, TOOL_DEADLINE_SECS)?
        }
        "pacman" => {
            let mut cmd = std::process::Command::new("pacman");
            cmd.args(["-Ss", &query]);
            bounded_cmd_output("pkg_search", "pacman", cmd, TOOL_DEADLINE_SECS)?
        }
        "brew" => {
            let mut cmd = std::process::Command::new("brew");
            cmd.args(["search", &query]);
            bounded_cmd_output("pkg_search", "brew", cmd, TOOL_DEADLINE_SECS)?
        }
        "winget" => {
            let mut cmd = std::process::Command::new("winget");
            cmd.args(["search", &query]);
            bounded_cmd_output("pkg_search", "winget", cmd, TOOL_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_search", other)),
    };
    let program = match pm {
        "apt" => "apt-cache",
        "dnf" | "yum" => pm,
        "pacman" => "pacman",
        "brew" => "brew",
        "winget" => "winget",
        other => other,
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        // A query that matched nothing is an empty list, not a failure.
        if !pkg_no_match("pkg_search", pm, output.status.code(), &stderr) {
            return Err(crate::safety::tool_failed(
                "pkg_search",
                program,
                output.status.code(),
                &stderr,
            ));
        }
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let results: Vec<Value> = match pm {
        "apt" => {
            // apt-cache search: "name - description"
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .filter_map(|l| {
                    let parts: Vec<&str> = l.splitn(2, " - ").collect();
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(parts[0].trim().to_string()));
                    if parts.len() >= 2 {
                        rec.insert(
                            "description".to_string(),
                            Value::Str(parts[1].trim().to_string()),
                        );
                    }
                    Some(Value::Record(rec))
                })
                .collect()
        }
        "brew" => {
            // brew search: one name per line
            text.lines()
                .filter(|l| !l.trim().is_empty() && !l.starts_with("==>"))
                .map(|l| {
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(l.trim().to_string()));
                    Value::Record(rec)
                })
                .collect()
        }
        _ => {
            // Generic: parse as whitespace-separated
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .map(|l| {
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(l.trim().to_string()));
                    Value::Record(rec)
                })
                .collect()
        }
    };
    Ok(Value::Array(results))
}

fn bi_pkg_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let package = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_info",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_info", std::slice::from_ref(&package))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("apt-cache");
            cmd.args(["show", &package]);
            bounded_cmd_output("pkg_info", "apt-cache", cmd, TOOL_DEADLINE_SECS)?
        }
        "dnf" | "yum" => {
            let mut cmd = std::process::Command::new(pm);
            cmd.args(["info", &package]);
            bounded_cmd_output("pkg_info", pm, cmd, TOOL_DEADLINE_SECS)?
        }
        "pacman" => {
            let mut cmd = std::process::Command::new("pacman");
            cmd.args(["-Qi", &package]);
            bounded_cmd_output("pkg_info", "pacman", cmd, TOOL_DEADLINE_SECS)?
        }
        "brew" => {
            let mut cmd = std::process::Command::new("brew");
            cmd.args(["info", &package]);
            bounded_cmd_output("pkg_info", "brew", cmd, TOOL_DEADLINE_SECS)?
        }
        "winget" => {
            let mut cmd = std::process::Command::new("winget");
            cmd.args(["show", &package]);
            bounded_cmd_output("pkg_info", "winget", cmd, TOOL_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_info", other)),
    };
    let program = match pm {
        "apt" => "apt-cache",
        "dnf" | "yum" => pm,
        "pacman" => "pacman",
        "brew" => "brew",
        "winget" => "winget",
        other => other,
    };
    if !output.status.success() {
        return Err(pkg_query_failure(
            "pkg_info",
            "package",
            &package,
            pm,
            program,
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }

    // Parse key-value "Field: Value" lines into a Record (works for apt, dnf, pacman, brew, winget)
    let text = String::from_utf8_lossy(&output.stdout);
    let mut rec = std::collections::BTreeMap::new();
    for line in text.lines() {
        if let Some(colon_pos) = line.find(':') {
            let key = line[..colon_pos].trim();
            let value = line[colon_pos + 1..].trim();
            if !key.is_empty() && !key.contains(' ') || key.contains("Build Date") {
                rec.insert(
                    key.to_lowercase().replace(' ', "_"),
                    Value::Str(value.to_string()),
                );
            }
        }
    }
    if rec.is_empty() {
        Ok(Value::Str(text.to_string()))
    } else {
        Ok(Value::Record(rec))
    }
}

