fn bi_pkg_sources(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    #[cfg(target_os = "linux")]
    {
        // No sources.list is a system without apt ([] below). One that exists
        // but cannot be read used to be the same empty list; it is an error.
        let sources = match std::fs::read_to_string("/etc/apt/sources.list") {
            Ok(text) => Some(text),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
            Err(e) => {
                return Err(crate::safety::fs_error(
                    "pkg_sources",
                    "/etc/apt/sources.list",
                    &e,
                ))
            }
        };
        if let Some(sources) = sources {
            let entries: Vec<Value> = sources
                .lines()
                .filter(|l| {
                    let t = l.trim();
                    !t.is_empty() && !t.starts_with('#')
                })
                .map(|line| {
                    let mut rec = std::collections::BTreeMap::new();
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if let Some(typ) = parts.first() {
                        rec.insert("type".to_string(), Value::Str(typ.to_string()));
                    }
                    if let Some(uri) = parts.get(1) {
                        rec.insert("uri".to_string(), Value::Str(uri.to_string()));
                    }
                    if let Some(dist) = parts.get(2) {
                        rec.insert("distribution".to_string(), Value::Str(dist.to_string()));
                    }
                    if parts.len() > 3 {
                        let components: Vec<Value> = parts[3..]
                            .iter()
                            .map(|c| Value::Str(c.to_string()))
                            .collect();
                        rec.insert("components".to_string(), Value::Array(components));
                    }
                    rec.insert("raw".to_string(), Value::Str(line.to_string()));
                    Value::Record(rec)
                })
                .collect();
            return Ok(Value::Array(entries));
        }
    }
    Ok(Value::Array(vec![]))
}

