fn bi_pkg_files(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let package = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_files",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_files", std::slice::from_ref(&package))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("dpkg");
            cmd.args(["-L", &package]);
            bounded_cmd_output("pkg_files", "dpkg", cmd, TOOL_DEADLINE_SECS)?
        }
        "pacman" => {
            let mut cmd = std::process::Command::new("pacman");
            cmd.args(["-Ql", &package]);
            bounded_cmd_output("pkg_files", "pacman", cmd, TOOL_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_files", other)),
    };
    let program = match pm {
        "apt" => "dpkg",
        "pacman" => "pacman",
        other => other,
    };
    if !output.status.success() {
        return Err(pkg_query_failure(
            "pkg_files",
            "package",
            &package,
            pm,
            program,
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let files: Vec<Value> = text
        .lines()
        // dpkg -L lists the root as "/."; it is not a file of the package.
        .filter(|l| !l.trim().is_empty() && l.trim() != "/.")
        .map(|l| {
            // pacman -Ql prints "package /path"; dpkg -L prints the path alone,
            // and splitting that at a space cut "/usr/share/doc/a b" to "b".
            match l.split_once(' ') {
                Some((_pkg, path)) if pm == "pacman" => Value::Str(path.to_string()),
                _ => Value::Str(l.trim().to_string()),
            }
        })
        .collect();
    Ok(Value::Array(files))
}

fn bi_pkg_owner(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let file = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_owner",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_owner", std::slice::from_ref(&file))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("dpkg");
            cmd.args(["-S", &file]);
            bounded_cmd_output("pkg_owner", "dpkg", cmd, TOOL_DEADLINE_SECS)?
        }
        "pacman" => {
            let mut cmd = std::process::Command::new("pacman");
            cmd.args(["-Qo", &file]);
            bounded_cmd_output("pkg_owner", "pacman", cmd, TOOL_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_owner", other)),
    };
    let program = match pm {
        "apt" => "dpkg",
        "pacman" => "pacman",
        other => other,
    };
    if !output.status.success() {
        return Err(pkg_query_failure(
            "pkg_owner",
            "file",
            &file,
            pm,
            program,
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }

    let text = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let mut rec = std::collections::BTreeMap::new();
    // dpkg -S format: "package: /path/to/file"
    // pacman -Qo format: "/path/to/file is owned by package version"
    if pm == "apt" {
        if let Some((pkg, path)) = text.split_once(": ") {
            rec.insert("package".to_string(), Value::Str(pkg.to_string()));
            rec.insert("file".to_string(), Value::Str(path.to_string()));
        } else {
            rec.insert("package".to_string(), Value::Str(text));
            rec.insert("file".to_string(), Value::Str(file));
        }
    } else if pm == "pacman" {
        // "/path/to/file is owned by package version"
        if let Some(pos) = text.find(" is owned by ") {
            let owned_by = &text[pos + 13..];
            let parts: Vec<&str> = owned_by.split_whitespace().collect();
            rec.insert("file".to_string(), Value::Str(text[..pos].to_string()));
            rec.insert(
                "package".to_string(),
                Value::Str(parts.first().unwrap_or(&"").to_string()),
            );
            if let Some(ver) = parts.get(1) {
                rec.insert("version".to_string(), Value::Str(ver.to_string()));
            }
        } else {
            rec.insert("package".to_string(), Value::Str(text));
            rec.insert("file".to_string(), Value::Str(file));
        }
    } else {
        rec.insert("package".to_string(), Value::Str(text));
        rec.insert("file".to_string(), Value::Str(file));
    }
    Ok(Value::Record(rec))
}

fn bi_pkg_verify(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let package = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_verify",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_verify", std::slice::from_ref(&package))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("dpkg");
            cmd.args(["-V", &package]);
            // Verifying every installed file of a package can be slow.
            bounded_cmd_output("pkg_verify", "dpkg", cmd, TOOL_LONG_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_verify", other)),
    };

    // dpkg -V prints one line per file that fails verification.
    Ok(Value::Bool(
        output.status.success() && String::from_utf8_lossy(&output.stdout).trim().is_empty(),
    ))
}

/// `apt-cache depends` ("  Depends: libc6", "  |Depends: a" for an
/// alternative) or `pacman -Si` ("Depends On : a  b>=1") as records.
fn parse_pkg_deps(pm: &str, text: &str) -> Value {
    let mut out = Vec::new();
    let mut push = |kind: &str, package: &str, alternative: bool| {
        let mut r = BTreeMap::new();
        r.insert("kind".to_string(), Value::Str(kind.to_string()));
        r.insert("package".to_string(), Value::Str(package.to_string()));
        r.insert("alternative".to_string(), Value::Bool(alternative));
        out.push(Value::Record(r));
    };
    if pm == "pacman" {
        for line in text.lines() {
            let Some((key, val)) = line.split_once(':') else {
                continue;
            };
            let kind = match key.trim() {
                "Depends On" => "Depends",
                "Optional Deps" => "Optional",
                "Make Deps" => "MakeDepends",
                _ => continue,
            };
            if val.trim() == "None" {
                continue;
            }
            for dep in val.split_whitespace() {
                push(kind, dep, false);
            }
        }
    } else {
        for line in text.lines().filter(|l| l.starts_with(' ')) {
            let t = line.trim();
            let (alternative, t) = match t.strip_prefix('|') {
                Some(rest) => (true, rest),
                None => (false, t),
            };
            if let Some((kind, pkg)) = t.split_once(':') {
                push(kind.trim(), pkg.trim(), alternative);
            }
        }
    }
    Value::Array(out)
}

/// `apt-cache rdepends` (names under "Reverse Depends:", some repeated per
/// architecture as "name:arm64") or `pacman -Sii` ("Required By : a b") as a
/// de-duplicated list of package names.
fn parse_pkg_rdeps(pm: &str, package: &str, text: &str) -> Value {
    let mut names = std::collections::BTreeSet::new();
    if pm == "pacman" {
        for line in text.lines() {
            if let Some((key, val)) = line.split_once(':') {
                if key.trim() == "Required By" && val.trim() != "None" {
                    names.extend(val.split_whitespace().map(str::to_string));
                }
            }
        }
    } else {
        let mut listing = false;
        for line in text.lines() {
            if line.trim_end() == "Reverse Depends:" {
                listing = true;
            } else if listing && line.starts_with(' ') {
                let n = line.trim().trim_start_matches('|');
                let n = n.split(':').next().unwrap_or(n);
                if !n.is_empty() {
                    names.insert(n.to_string());
                }
            }
        }
    }
    // apt lists the package's other architectures ("coreutils:arm64") among
    // its reverse dependencies; with the suffix gone that is the package.
    names.remove(package);
    Value::Array(names.into_iter().map(Value::Str).collect())
}

fn bi_pkg_deps(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let package = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "pkg_deps",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    crate::safety::reject_option_like("pkg_deps", std::slice::from_ref(&package))?;
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => {
            let mut cmd = std::process::Command::new("apt-cache");
            cmd.args(["depends", &package]);
            bounded_cmd_output("pkg_deps", "apt-cache", cmd, TOOL_DEADLINE_SECS)?
        }
        "pacman" => {
            let mut cmd = std::process::Command::new("pacman");
            cmd.args(["-Si", &package]);
            bounded_cmd_output("pkg_deps", "pacman", cmd, TOOL_DEADLINE_SECS)?
        }
        other => return Err(pkg_unsupported("pkg_deps", other)),
    };
    let program = match pm {
        "apt" => "apt-cache",
        "pacman" => "pacman",
        other => other,
    };
    if !output.status.success() {
        return Err(pkg_query_failure(
            "pkg_deps",
            "package",
            &package,
            pm,
            program,
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }

    // This returned the tool's text verbatim, a different format per
    // package manager, which is what typed output exists to replace.
    Ok(parse_pkg_deps(pm, &String::from_utf8_lossy(&output.stdout)))
}

