fn bi_hw_usb(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    #[cfg(target_os = "windows")]
    {
        let mut cmd = std::process::Command::new("powershell");
        cmd.args([
            "-Command",
            "Get-PnpDevice -Class USB | Select-Object FriendlyName,Status | ConvertTo-Json",
        ]);
        let output = bounded_cmd_output("hw_usb", "powershell", cmd, PROBE_DEADLINE_SECS)?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                let items = match &json {
                    serde_json::Value::Array(arr) => arr.clone(),
                    obj @ serde_json::Value::Object(_) => vec![obj.clone()],
                    _ => vec![],
                };
                let devices: Vec<Value> = items
                    .iter()
                    .filter_map(|obj| {
                        let o = obj.as_object()?;
                        let mut rec = std::collections::BTreeMap::new();
                        if let Some(v) = o.get("FriendlyName") {
                            rec.insert("name".to_string(), json_to_value(v.clone()));
                        }
                        if let Some(v) = o.get("Status") {
                            rec.insert("status".to_string(), json_to_value(v.clone()));
                        }
                        Some(Value::Record(rec))
                    })
                    .collect();
                return Ok(Value::Array(devices));
            }
        }
    }
    #[cfg(target_os = "linux")]
    {
        let cmd = std::process::Command::new("lsusb");
        let output = bounded_cmd_output("hw_usb", "lsusb", cmd, PROBE_DEADLINE_SECS)?;
        if output.status.success() {
            let devices: Vec<Value> = String::from_utf8_lossy(&output.stdout)
                .lines()
                .map(|line| {
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(line.to_string()));
                    Value::Record(rec)
                })
                .collect();
            return Ok(Value::Array(devices));
        }
    }
    #[cfg(target_os = "macos")]
    {
        let mut cmd = std::process::Command::new("system_profiler");
        cmd.args(["SPUSBDataType", "-json"]);
        let output = bounded_cmd_output("hw_usb", "system_profiler", cmd, PROBE_DEADLINE_SECS)?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                if let Some(items) = json.get("SPUSBDataType").and_then(|v| v.as_array()) {
                    let devices: Vec<Value> = items
                        .iter()
                        .filter_map(|item| {
                            let o = item.as_object()?;
                            let mut rec = std::collections::BTreeMap::new();
                            if let Some(v) = o.get("_name") {
                                rec.insert("name".to_string(), json_to_value(v.clone()));
                            }
                            if let Some(v) = o.get("manufacturer") {
                                rec.insert("vendor".to_string(), json_to_value(v.clone()));
                            }
                            Some(Value::Record(rec))
                        })
                        .collect();
                    return Ok(Value::Array(devices));
                }
            }
        }
    }
    // A failed query answered null.
    Err(crate::safety::tool_failed(
        "lsusb",
        "the device query",
        None,
        "it failed or printed nothing usable",
    ))
}

