fn bi_web_websocket(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    web_no_input("web_websocket", &input)?;
    ws_plan(&args)?;
    Err(crate::safety::unimplemented(
        "web_websocket",
        "WebSocket support needs the `native` feature; NOTHING WAS OPENED",
        "build with the default `native` feature",
    ))
}

fn bi_web_graphql(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    web_no_input("web_graphql", &input)?;
    let url = web_http_url(
        "web_graphql",
        web_text_arg("web_graphql", &args, 0, WEB_URL_EXPECTED)?,
    )?;
    let query = web_text_arg("web_graphql", &args, 1, "query: String")?;
    let variables = args
        .get(2)
        .map(|v| value_to_json(v.clone()))
        .unwrap_or(serde_json::Value::Null);
    let body = serde_json::json!({ "query": query, "variables": variables }).to_string();
    guard_network("web_graphql", &url)?;
    let run = web_curl(
        "web_graphql",
        &[
            "-X",
            "POST",
            "-H",
            "Content-Type: application/json",
            "--data-raw",
            &body,
            &url,
        ],
    )?;
    web_json_value("web_graphql", &web_body("web_graphql", run)?)
}

fn bi_web_check_url(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    web_no_input("web_check_url", &input)?;
    let url = web_http_url(
        "web_check_url",
        web_text_arg("web_check_url", &args, 0, WEB_URL_EXPECTED)?,
    )?;
    guard_network("web_check_url", &url)?;
    // The body goes to the null device; stdout carries only the status code.
    let sink = if cfg!(windows) { "NUL" } else { "/dev/null" };
    let run = web_curl(
        "web_check_url",
        &["-L", "-o", sink, "-w", "%{http_code}", &url],
    )?;
    let text = String::from_utf8_lossy(&web_body("web_check_url", run)?).into_owned();
    let code: u16 = text.trim().parse().map_err(|_| {
        web_failure(
            "web_check_url",
            format!("curl printed no HTTP status code: {:?}", text.trim()),
            "retry the call",
        )
    })?;
    // A transport failure is an error above, so `false` means the server
    // answered with an error status.
    Ok(Value::Bool((200..400).contains(&code)))
}

/// The origin (`scheme://host[:port]`) of an absolute http or https URL. A bare
/// host name is refused: guessing a scheme for it would request a host the
/// caller did not name.
fn web_site_root(builtin: &str, args: &[Value]) -> Result<String> {
    let text = web_text_arg(builtin, args, 0, WEB_URL_EXPECTED)?;
    let normalised = web_http_url(builtin, text)?;
    let parsed = url::Url::parse(&normalised)
        .map_err(|e| crate::safety::bad_arg(builtin, WEB_URL_EXPECTED, &e.to_string()))?;
    Ok(parsed.origin().ascii_serialization())
}

fn bi_web_robots_txt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    web_no_input("web_robots_txt", &input)?;
    let url = format!("{}/robots.txt", web_site_root("web_robots_txt", &args)?);
    web_get_body("web_robots_txt", &url)
}

fn bi_web_sitemap(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    web_no_input("web_sitemap", &input)?;
    let url = format!("{}/sitemap.xml", web_site_root("web_sitemap", &args)?);
    web_get_body("web_sitemap", &url)
}

fn bi_web_extract_emails(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let text = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "web_extract_emails",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    let mut emails = Vec::new();
    let mut current = String::new();
    let mut in_email = false;

    for c in text.chars().chain(std::iter::once('\0')) {
        if c.is_alphanumeric() || c == '.' || c == '_' || c == '-' || c == '+' {
            current.push(c);
            if c == '@' {
                in_email = true;
            }
        } else if c == '@' {
            current.push(c);
            in_email = true;
        } else {
            if in_email && current.contains('@') && current.contains('.') {
                let email = current.trim_matches('.').to_string();
                if !emails.contains(&Value::Str(email.clone())) {
                    emails.push(Value::Str(email));
                }
            }
            current.clear();
            in_email = false;
        }
    }

    Ok(Value::Array(emails))
}

fn bi_web_extract_phones(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let text = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "web_extract_phones",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    let mut phones = Vec::new();
    let mut current = String::new();

    for c in text.chars().chain(std::iter::once('\0')) {
        if c.is_ascii_digit() || c == '+' || c == '-' || c == '(' || c == ')' || c == ' ' {
            current.push(c);
        } else {
            let digits: String = current.chars().filter(|c| c.is_ascii_digit()).collect();
            if digits.len() >= 7 && digits.len() <= 15 {
                phones.push(Value::Str(current.trim().to_string()));
            }
            current.clear();
        }
    }

    Ok(Value::Array(phones))
}

fn bi_web_html_to_text(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let html = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Str("".to_string())),
    };

    Ok(Value::Str(strip_html_tags(&html)))
}

fn bi_web_html_to_markdown(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let html = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Str("".to_string())),
    };

    // Simple HTML to Markdown conversion
    let mut md = html.clone();
    md = md.replace("<h1>", "# ").replace("</h1>", "\n");
    md = md.replace("<h2>", "## ").replace("</h2>", "\n");
    md = md.replace("<h3>", "### ").replace("</h3>", "\n");
    md = md.replace("<p>", "").replace("</p>", "\n\n");
    md = md
        .replace("<br>", "\n")
        .replace("<br/>", "\n")
        .replace("<br />", "\n");
    md = md.replace("<strong>", "**").replace("</strong>", "**");
    md = md.replace("<b>", "**").replace("</b>", "**");
    md = md.replace("<em>", "*").replace("</em>", "*");
    md = md.replace("<i>", "*").replace("</i>", "*");
    md = md.replace("<code>", "`").replace("</code>", "`");
    md = md.replace("<li>", "- ").replace("</li>", "\n");
    md = md.replace("<ul>", "").replace("</ul>", "\n");
    md = md.replace("<ol>", "").replace("</ol>", "\n");

    // Strip remaining tags
    md = strip_html_tags(&md);

    Ok(Value::Str(md))
}

fn bi_web_json_path(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let json_val = match args.first() {
        Some(v) => v.clone(),
        _ => return Ok(Value::Null),
    };
    let path = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(json_val),
    };

    let mut current = json_val;
    for part in path
        .trim_start_matches('$')
        .trim_start_matches('.')
        .split('.')
    {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }

        // Array index?
        if part.contains('[') {
            if let Some((name, idx_str)) = part.split_once('[') {
                if !name.is_empty() {
                    current = match &current {
                        Value::Record(r) => r.get(name).cloned().unwrap_or(Value::Null),
                        _ => Value::Null,
                    };
                }
                let idx: usize = idx_str
                    .strip_suffix(']')
                    .and_then(|index| index.parse().ok())
                    .ok_or_else(|| {
                        crate::safety::bad_arg(
                            "web_json_path",
                            "a nonnegative array index followed by ]",
                            idx_str,
                        )
                    })?;
                current = match &current {
                    Value::Array(arr) => arr.get(idx).cloned().unwrap_or(Value::Null),
                    _ => Value::Null,
                };
            }
        } else {
            current = match &current {
                Value::Record(r) => r.get(part).cloned().unwrap_or(Value::Null),
                _ => Value::Null,
            };
        }
    }

    Ok(current)
}

fn bi_web_xpath(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Refused before anything runs. XPath needs an XML parser, and none is
    // added for 13.0.0: the candidates are unmaintained and parse XML only,
    // while the pages web builtins fetch are HTML.
    web_no_input("web_xpath", &input)?;
    Err(crate::safety::unimplemented(
        "web_xpath",
        "querying with XPath is not implemented; NOTHING WAS DONE",
        "use web_scrape for simple extraction",
    ))
}

// Helper function
fn strip_html_tags(html: &str) -> String {
    let mut result = String::new();
    let mut in_tag = false;

    for c in html.chars() {
        if c == '<' {
            in_tag = true;
        } else if c == '>' {
            in_tag = false;
        } else if !in_tag {
            result.push(c);
        }
    }

    // Clean up whitespace
    result.split_whitespace().collect::<Vec<_>>().join(" ")
}

// ============================================================================
// 460-479: Clipboard & Input
// ============================================================================

/// Whether an environment variable names a display: set and not empty.
#[cfg(target_os = "linux")]
fn display_env_set(var: &str) -> bool {
    std::env::var_os(var).is_some_and(|v| !v.is_empty())
}

/// The text clipboard builtins run xclip or xsel, which need an X display.
/// With none it is E_NO_UI; under Wayland with no XWayland display they
/// cannot reach the clipboard at all. Checked before any tool runs: xclip
/// with no display failed as E_TOOL_FAILED.
#[cfg(target_os = "linux")]
fn linux_x11_clipboard_display(name: &str) -> Result<()> {
    if display_env_set("DISPLAY") {
        return Ok(());
    }
    if display_env_set("WAYLAND_DISPLAY") {
        return Err(crate::safety::unimplemented(
            name,
            "the text clipboard is reached through X11 (xclip or xsel), and this Wayland session has no X display; NOTHING WAS DONE",
            "run with XWayland so DISPLAY is set",
        ));
    }
    Err(crate::safety::no_ui(name))
}

/// One clipboard tool run for the Linux clipboard builtins. `Ok(None)` when the
/// tool is not installed, so the caller can try the next one. Same deadline and
/// error mapping as bounded_cmd_output, which cannot tell an absent tool
/// (NotFound) apart from the other failures.
#[cfg(target_os = "linux")]
fn linux_clipboard_tool(
    name: &str,
    tool: &str,
    args: &[&str],
) -> Result<Option<std::process::Output>> {
    let mut cmd = std::process::Command::new(tool);
    cmd.args(args);
    match crate::safety::output_with_timeout(cmd, TOOL_DEADLINE_SECS) {
        Ok(out) => Ok(Some(out)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(crate::safety::spawn_error(name, tool, &e)),
    }
}

/// The formats `clipboard_types` names, in the order it answers them.
#[cfg(target_os = "linux")]
const CLIPBOARD_FORMATS: [&str; 4] = ["text", "image", "files", "audio"];

/// Which of `CLIPBOARD_FORMATS` a clipboard target or MIME type stands for, if
/// any. Everything else (TARGETS, TIMESTAMP, MULTIPLE, SAVE_TARGETS, ...) is
/// ignored.
#[cfg(target_os = "linux")]
fn clipboard_format_index(target: &str) -> Option<usize> {
    let t = target.trim().to_ascii_lowercase();
    if matches!(t.as_str(), "utf8_string" | "string" | "text") || t.starts_with("text/plain") {
        Some(0)
    } else if t.starts_with("image/") {
        Some(1)
    } else if matches!(t.as_str(), "text/uri-list" | "x-special/gnome-copied-files") {
        Some(2)
    } else if t.starts_with("audio/") {
        Some(3)
    } else {
        None
    }
}

/// The answer for a listing of targets or MIME types, one per line: the formats
/// it names, in `CLIPBOARD_FORMATS` order, each once.
#[cfg(target_os = "linux")]
fn clipboard_formats_of(listing: &[u8]) -> Value {
    let mut seen = [false; 4];
    for line in String::from_utf8_lossy(listing).lines() {
        if let Some(i) = clipboard_format_index(line) {
            seen[i] = true;
        }
    }
    Value::Array(
        CLIPBOARD_FORMATS
            .iter()
            .zip(seen)
            .filter(|(_, present)| *present)
            .map(|(name, _)| Value::Str(name.to_string()))
            .collect(),
    )
}

#[allow(unused_variables)]
fn bi_clipboard_get(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "clipboard_get";
    no_args_or_input(NAME, &args, &input)?;
    crate::safety::clipboard_read_gate(NAME)?;
    #[cfg(target_os = "windows")]
    {
        let output = gui_powershell(NAME, "Get-Clipboard")?;
        if !output.status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                "Get-Clipboard",
                output.status.code(),
                &gui_stderr_tail(&output),
            ));
        }
        let text = String::from_utf8_lossy(&output.stdout)
            .trim_end()
            .to_string();
        clipboard_answer(NAME, text.as_bytes())
    }
    #[cfg(target_os = "macos")]
    {
        let mut cmd = std::process::Command::new("pbpaste");
        let output = bounded_cmd_output(NAME, "pbpaste", cmd, TOOL_DEADLINE_SECS)?;
        if !output.status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                "pbpaste",
                output.status.code(),
                &gui_stderr_tail(&output),
            ));
        }
        clipboard_answer(NAME, &output.stdout)
    }
    #[cfg(target_os = "linux")]
    {
        linux_x11_clipboard_display(NAME)?;
        // xclip reports an empty clipboard as "target not available": that is
        // the empty answer, not a failure.
        let read = |tool: &str, args: &[&str]| -> Result<Option<Vec<u8>>> {
            match linux_clipboard_tool(NAME, tool, args)? {
                None => Ok(None),
                Some(out) if out.status.success() => Ok(Some(out.stdout)),
                Some(out) => {
                    let stderr = String::from_utf8_lossy(&out.stderr);
                    if stderr.contains("not available") {
                        Ok(Some(Vec::new()))
                    } else {
                        Err(crate::safety::tool_failed(
                            NAME,
                            tool,
                            out.status.code(),
                            &gui_stderr_tail(&out),
                        ))
                    }
                }
            }
        };
        let bytes = match read("xclip", &["-selection", "clipboard", "-o"])? {
            Some(bytes) => bytes,
            None => read("xsel", &["--clipboard", "--output"])?.ok_or_else(|| {
                crate::safety::tool_missing(
                    NAME,
                    "xclip or xsel",
                    "install xclip or xsel to read the clipboard",
                )
            })?,
        };
        clipboard_answer(NAME, &bytes)
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos", target_os = "linux")))]
    {
        Err(crate::safety::unimplemented(
            NAME,
            "reading the clipboard is implemented on Windows, macOS and Linux; NOTHING WAS READ",
            "run this on Windows, macOS or Linux",
        ))
    }
}

fn bi_clipboard_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "clipboard_set";
    // The text comes either as the argument or from the pipe, never both. A
    // call with neither is refused: it used to answer false.
    let text = match args.first() {
        Some(v) => {
            if input.is_some() {
                return Err(crate::safety::bad_arg(
                    NAME,
                    "the text as the argument or as piped text, not both",
                    "both",
                ));
            }
            gui_text(NAME, "text", v, CLIPBOARD_MAX_BYTES, true)?
        }
        None => match input {
            Some(piped) => gui_text(NAME, "piped text", &piped, CLIPBOARD_MAX_BYTES, true)?,
            None => return Err(crate::safety::bad_arg(NAME, "the text to copy", "nothing")),
        },
    };

    #[cfg(target_os = "windows")]
    {
        let mut cmd = std::process::Command::new("powershell");
        cmd.args([
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            &crate::ps_script!("Set-Clipboard -Value {}", crate::safety::ps_quote(&text)),
        ]);
        let output = bounded_cmd_output(NAME, "powershell", cmd, TOOL_DEADLINE_SECS)?;
        if !output.status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                "Set-Clipboard",
                output.status.code(),
                &gui_stderr_tail(&output),
            ));
        }
        Ok(Value::Bool(true))
    }
    #[cfg(target_os = "macos")]
    {
        let child = std::process::Command::new("pbcopy")
            .stdin(std::process::Stdio::piped())
            .spawn()
            .map_err(|e| crate::safety::spawn_error(NAME, "pbcopy", &e))?;
        let status = feed_stdin_and_wait(
            NAME,
            "pbcopy",
            child,
            text.as_bytes().to_vec(),
            TOOL_DEADLINE_SECS,
        )?;
        if !status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                "pbcopy",
                status.code(),
                "it exited unsuccessfully",
            ));
        }
        Ok(Value::Bool(true))
    }
    #[cfg(target_os = "linux")]
    {
        linux_x11_clipboard_display(NAME)?;
        // xclip first, xsel when xclip is not installed. A tool that is
        // installed and fails is an error, whichever it is.
        let (tool, child) = match std::process::Command::new("xclip")
            .args(["-selection", "clipboard"])
            .stdin(std::process::Stdio::piped())
            .spawn()
        {
            Ok(child) => ("xclip", child),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => (
                "xsel",
                std::process::Command::new("xsel")
                    .args(["--clipboard", "--input"])
                    .stdin(std::process::Stdio::piped())
                    .spawn()
                    .map_err(|e| crate::safety::spawn_error(NAME, "xsel", &e))?,
            ),
            Err(e) => return Err(crate::safety::spawn_error(NAME, "xclip", &e)),
        };
        let status = feed_stdin_and_wait(
            NAME,
            tool,
            child,
            text.as_bytes().to_vec(),
            TOOL_DEADLINE_SECS,
        )?;
        if !status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                tool,
                status.code(),
                "it exited unsuccessfully",
            ));
        }
        Ok(Value::Bool(true))
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos", target_os = "linux")))]
    {
        Err(crate::safety::unimplemented(
            NAME,
            "writing the clipboard is implemented on Windows, macOS and Linux; NOTHING WAS COPIED",
            "run this on Windows, macOS or Linux",
        ))
    }
}

fn bi_clipboard_clear(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("clipboard_clear", &args, &input)?;
    bi_clipboard_set(vec![Value::Str(String::new())], None)
}

fn bi_clipboard_has_text(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("clipboard_has_text", &args, &input)?;
    match bi_clipboard_get(vec![], None)? {
        Value::Str(s) => Ok(Value::Bool(!s.is_empty())),
        other => Err(crate::safety::bad_arg(
            "clipboard_has_text",
            "text from the clipboard",
            other.type_name(),
        )),
    }
}

#[allow(unused_variables)]
fn bi_clipboard_types(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("clipboard_types", &args, &input)?;
    // This always listed "text" -- on Linux and macOS without looking at the
    // clipboard at all, on Windows even when the clipboard was empty or held
    // an image. It now asks the clipboard what it holds.
    #[cfg(target_os = "windows")]
    {
        let mut cmd = std::process::Command::new("powershell");
        cmd
            .args([
                "-NoProfile",
                "-NonInteractive",
                "-STA",
                "-Command",
                "Add-Type -AssemblyName System.Windows.Forms; $c = [Windows.Forms.Clipboard]; @(if ($c::ContainsText()) {'text'}; if ($c::ContainsImage()) {'image'}; if ($c::ContainsFileDropList()) {'files'}; if ($c::ContainsAudio()) {'audio'}) -join ','",
            ]);
        let output = bounded_cmd_output("clipboard_types", "powershell", cmd, TOOL_DEADLINE_SECS)?;
        if !output.status.success() {
            return Err(crate::safety::tool_failed(
                "clipboard_types",
                "powershell",
                output.status.code(),
                &gui_stderr_tail(&output),
            ));
        }
        let text = String::from_utf8_lossy(&output.stdout);
        Ok(Value::Array(
            text.trim()
                .split(',')
                .filter(|t| !t.is_empty())
                .map(|t| Value::Str(t.to_string()))
                .collect(),
        ))
    }
    #[cfg(target_os = "linux")]
    {
        const NAME: &str = "clipboard_types";
        // With no display there is no clipboard to ask, and no tool would answer.
        if !display_env_set("DISPLAY") && !display_env_set("WAYLAND_DISPLAY") {
            return Err(crate::safety::no_ui(NAME));
        }
        // Wayland first when it is the session: wl-paste reads the clipboard the
        // desktop shows, where xclip would see only XWayland's copy.
        if display_env_set("WAYLAND_DISPLAY") {
            let out =
                linux_clipboard_tool(NAME, "wl-paste", &["--list-types"])?.ok_or_else(|| {
                    crate::safety::tool_missing(
                        NAME,
                        "wl-paste",
                        "install wl-clipboard to list the clipboard's formats",
                    )
                })?;
            if out.status.success() {
                return Ok(clipboard_formats_of(&out.stdout));
            }
            // wl-paste exits 1 and says "Nothing is copied" when no client offers data.
            if out.status.code() == Some(1)
                && String::from_utf8_lossy(&out.stderr).contains("Nothing is copied")
            {
                return Ok(Value::Array(Vec::new()));
            }
            return Err(crate::safety::tool_failed(
                NAME,
                "wl-paste",
                out.status.code(),
                &gui_stderr_tail(&out),
            ));
        }
        // X11: xclip lists the targets. xsel cannot, so it only says whether the
        // clipboard holds text.
        if let Some(out) = linux_clipboard_tool(
            NAME,
            "xclip",
            &["-selection", "clipboard", "-o", "-t", "TARGETS"],
        )? {
            if out.status.success() {
                return Ok(clipboard_formats_of(&out.stdout));
            }
            // xclip reports an empty clipboard as "target TARGETS not available".
            if String::from_utf8_lossy(&out.stderr).contains("not available") {
                return Ok(Value::Array(Vec::new()));
            }
            return Err(crate::safety::tool_failed(
                NAME,
                "xclip",
                out.status.code(),
                &gui_stderr_tail(&out),
            ));
        }
        let Some(out) = linux_clipboard_tool(NAME, "xsel", &["--clipboard", "--output"])? else {
            return Err(crate::safety::tool_missing(
                NAME,
                "xclip or xsel",
                "install xclip or xsel to list the clipboard's formats",
            ));
        };
        if !out.status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                "xsel",
                out.status.code(),
                &gui_stderr_tail(&out),
            ));
        }
        Ok(if out.stdout.is_empty() {
            Value::Array(Vec::new())
        } else {
            Value::Array(vec![Value::Str("text".to_string())])
        })
    }
    #[cfg(not(any(target_os = "windows", target_os = "linux")))]
    {
        Err(crate::safety::unimplemented(
            "clipboard_types",
            "listing clipboard formats is implemented on Windows and Linux only; NOTHING WAS INSPECTED",
            "clipboard() reads the text on the clipboard",
        ))
    }
}

/// Most options one `input_select` or `input_multiselect` offers.
const INPUT_CHOICE_MAX_OPTIONS: usize = 1000;
/// Largest text `input_editor` starts with or answers.
const INPUT_EDITOR_MAX_BYTES: usize = 1024 * 1024;

/// One line from stdin, through the shared bounded reader. Closed stdin (EOF)
/// is `E_NO_UI`: it used to answer "", which read as a real answer.
fn read_answer(builtin: &str, prompt: &str) -> Result<String> {
    if !prompt.is_empty() {
        eprint!("{}", prompt);
    }
    stdin_lines::read_blocking(builtin)
}

/// Refuses piped input, and an argument count outside `min..=max`, before
/// anything is printed or read. `shape` is the signature the refusal names.
fn direct_args(
    name: &str,
    args: &[Value],
    piped: bool,
    min: usize,
    max: usize,
    shape: &str,
) -> Result<()> {
    if piped {
        return Err(crate::safety::bad_arg(
            name,
            "a direct call; the answer comes from the terminal, not piped input",
            "a piped value",
        ));
    }
    if !(min..=max).contains(&args.len()) {
        return Err(crate::safety::bad_arg(
            name,
            shape,
            &format!("{} argument(s)", args.len()),
        ));
    }
    Ok(())
}

/// A prompt: a String of at most `INPUT_TEXT_MAX_BYTES` bytes.
fn prompt_text(name: &str, value: &Value) -> Result<String> {
    match value {
        Value::Str(s) if s.len() <= INPUT_TEXT_MAX_BYTES => Ok(s.clone()),
        Value::Str(s) => Err(crate::safety::bad_arg(
            name,
            &format!("prompt of at most {INPUT_TEXT_MAX_BYTES} bytes"),
            &format!("{} bytes", s.len()),
        )),
        other => Err(crate::safety::bad_arg(
            name,
            "prompt: String",
            other.type_name(),
        )),
    }
}

/// The optional first argument as a prompt, or `default` when it is absent.
fn optional_prompt(name: &str, args: &[Value], default: &str) -> Result<String> {
    match args.first() {
        None => Ok(default.to_string()),
        Some(value) => prompt_text(name, value),
    }
}

/// An answer as a refusal shows it: its first 64 characters, quoted.
fn echo_answer(answer: &str) -> String {
    const SHOWN: usize = 64;
    if answer.chars().count() <= SHOWN {
        return format!("{answer:?}");
    }
    let head: String = answer.chars().take(SHOWN).collect();
    format!("{head:?}...")
}

/// Asks `question` until `accept` takes the answer. A rejected answer is
/// reported on stderr and asked again, at most `INPUT_MAX_ATTEMPTS` times. After
/// the last one the call refuses with E_BAD_ARG: no value is answered for an
/// answer that was not accepted.
fn ask_until<T>(
    name: &str,
    question: &str,
    expected: &str,
    mut accept: impl FnMut(&str) -> Option<T>,
) -> Result<T> {
    for _ in 0..INPUT_MAX_ATTEMPTS {
        let answer = read_answer(name, question)?;
        if let Some(value) = accept(&answer) {
            return Ok(value);
        }
        eprintln!("{name}: {} is not {expected}", echo_answer(&answer));
    }
    Err(crate::safety::bad_arg(
        name,
        expected,
        &format!("no valid answer in {INPUT_MAX_ATTEMPTS} attempts"),
    ))
}

/// The options a select offers: 1 through `INPUT_CHOICE_MAX_OPTIONS` values,
/// each a String of 1 through `INPUT_TEXT_MAX_BYTES` bytes, or an Int, Float
/// or Bool. Each comes back with the text its menu line shows; control
/// characters in that text are drawn as spaces.
fn choice_options(name: &str, value: &Value) -> Result<Vec<(Value, String)>> {
    let Value::Array(items) = value else {
        return Err(crate::safety::bad_arg(
            name,
            "options: Array of choices",
            value.type_name(),
        ));
    };
    if items.is_empty() || items.len() > INPUT_CHOICE_MAX_OPTIONS {
        return Err(crate::safety::bad_arg(
            name,
            &format!("1..={INPUT_CHOICE_MAX_OPTIONS} options"),
            &format!("{} option(s)", items.len()),
        ));
    }
    let mut out = Vec::with_capacity(items.len());
    for (i, item) in items.iter().enumerate() {
        let text = match item {
            Value::Str(s) if s.is_empty() || s.len() > INPUT_TEXT_MAX_BYTES => {
                return Err(crate::safety::bad_arg(
                    name,
                    &format!("option {}: 1 to {INPUT_TEXT_MAX_BYTES} bytes", i + 1),
                    &format!("{} bytes", s.len()),
                ));
            }
            Value::Str(s) => s.clone(),
            Value::Int(_) | Value::Float(_) | Value::Bool(_) => item.to_display_string(),
            other => {
                return Err(crate::safety::bad_arg(
                    name,
                    &format!("option {}: a String, Int, Float or Bool", i + 1),
                    other.type_name(),
                ));
            }
        };
        let shown: String = text
            .chars()
            .map(|c| if c.is_control() { ' ' } else { c })
            .collect();
        out.push((item.clone(), shown));
    }
    Ok(out)
}

/// A multi-select answer: 1-based numbers separated by commas, each in
/// `1..=count`, answered in the order given with repeats dropped. An empty
/// answer is the deliberate choice of nothing. Anything else is `None`.
fn parse_picks(answer: &str, count: usize) -> Option<Vec<usize>> {
    let text = answer.trim();
    let mut picks = Vec::new();
    if text.is_empty() {
        return Some(picks);
    }
    let mut seen = std::collections::BTreeSet::new();
    for token in text.split(',') {
        let n: usize = token.trim().parse().ok()?;
        if !(1..=count).contains(&n) {
            return None;
        }
        if seen.insert(n) {
            picks.push(n - 1);
        }
    }
    Some(picks)
}

/// A number answer: an Int when it parses as one, else a finite Float. NaN and
/// the infinities are not numbers an answer can give.
fn parse_number(text: &str) -> Option<Value> {
    if let Ok(n) = text.parse::<i64>() {
        return Some(Value::Int(n));
    }
    text.parse::<f64>()
        .ok()
        .filter(|f| f.is_finite())
        .map(Value::Float)
}

/// A date written `YYYY-MM-DD` that the calendar accepts, answered as its text.
fn parse_date(text: &str) -> Option<String> {
    let shaped = text.len() == 10
        && text.bytes().enumerate().all(|(i, b)| {
            if i == 4 || i == 7 {
                b == b'-'
            } else {
                b.is_ascii_digit()
            }
        });
    if !shaped {
        return None;
    }
    chrono::NaiveDate::parse_from_str(text, "%Y-%m-%d")
        .ok()
        .map(|_| text.to_string())
}

/// `input_read_line(prompt?)`: one line from stdin, without its terminator.
fn bi_input_read_line(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_read_line";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_read_line(prompt?: String)",
    )?;
    let prompt = optional_prompt(NAME, &args, "")?;
    Ok(Value::Str(read_answer(NAME, &prompt)?))
}

/// `input_read_password(prompt?)`. Piped or closed stdin is read as any other
/// line, so a closed stdin is `E_NO_UI` and nothing is echoed. Only a terminal
/// gets a hidden read, through `read_terminal_password`.
fn bi_input_read_password(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_read_password";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_read_password(prompt?: String)",
    )?;
    let prompt = optional_prompt(NAME, &args, "Password: ")?;
    use std::io::IsTerminal;
    if !std::io::stdin().is_terminal() {
        return Ok(Value::Str(read_answer(NAME, &prompt)?));
    }
    Ok(Value::Str(read_terminal_password(NAME, &prompt)?))
}

/// A hidden read from a terminal on Windows: PowerShell's `Read-Host
/// -AsSecureString`. Only the line terminator is removed from the answer.
#[cfg(target_os = "windows")]
fn read_terminal_password(name: &str, prompt: &str) -> Result<String> {
    let ps_script = crate::ps_script!(
        r#"
$password = Read-Host -Prompt {} -AsSecureString
$bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($password)
[System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
"#,
        crate::safety::ps_quote(prompt.trim_end_matches(": ").trim_end_matches(':'))
    );
    let output = std::process::Command::new("powershell")
        .args(["-Command", &ps_script])
        .output()
        .map_err(|e| crate::safety::spawn_error(name, "powershell", &e))?;
    if !output.status.success() {
        return Err(crate::safety::tool_failed(
            name,
            "powershell",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout)
        .trim_end_matches(['\r', '\n'])
        .to_string())
}

/// A hidden read from a terminal on Unix: echo is off for the one line.
#[cfg(unix)]
fn read_terminal_password(name: &str, prompt: &str) -> Result<String> {
    eprint!("{prompt}");
    let _ = std::process::Command::new("stty").arg("-echo").status();
    let answer = stdin_lines::read_blocking(name);
    let _ = std::process::Command::new("stty").arg("echo").status();
    eprintln!();
    answer
}

/// Other platforms have no hidden read, so the line is read as any other.
#[cfg(not(any(unix, target_os = "windows")))]
fn read_terminal_password(name: &str, prompt: &str) -> Result<String> {
    read_answer(name, prompt)
}

/// `input_confirm(prompt?)`: `y` or `yes` answers true; `n`, `no` or an empty
/// answer answers false. Anything else is asked again.
fn bi_input_confirm(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_confirm";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_confirm(prompt?: String)",
    )?;
    let prompt = optional_prompt(NAME, &args, "Confirm? [y/N]: ")?;
    ask_until(
        NAME,
        &prompt,
        "y, yes, n, no or an empty answer",
        |answer| match answer.trim().to_lowercase().as_str() {
            "y" | "yes" => Some(true),
            "" | "n" | "no" => Some(false),
            _ => None,
        },
    )
    .map(Value::Bool)
}

/// `input_select(prompt, options)`: lists the options numbered, then answers
/// the one picked, as it was given. An answer that is not a number in 1..=N is
/// asked again; after the last attempt the call refuses with E_BAD_ARG.
fn bi_input_select(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_select";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        2,
        2,
        "input_select(prompt: String, options: Array)",
    )?;
    let prompt = prompt_text(NAME, &args[0])?;
    let options = choice_options(NAME, &args[1])?;
    eprintln!("{prompt}");
    for (i, (_, text)) in options.iter().enumerate() {
        eprintln!("  {}. {text}", i + 1);
    }
    let count = options.len();
    let index = ask_until(
        NAME,
        "Choice: ",
        &format!("a number in 1..={count}"),
        |answer| {
            answer
                .trim()
                .parse::<usize>()
                .ok()
                .filter(|n| (1..=count).contains(n))
                .map(|n| n - 1)
        },
    )?;
    Ok(options[index].0.clone())
}

/// `input_multiselect(prompt, options)`: lists the options numbered, then
/// answers the picked ones, in the order given, as an Array. An empty answer
/// answers `[]`. An invalid answer is asked again; after the last attempt the
/// call refuses with E_BAD_ARG.
fn bi_input_multiselect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_multiselect";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        2,
        2,
        "input_multiselect(prompt: String, options: Array)",
    )?;
    let prompt = prompt_text(NAME, &args[0])?;
    let options = choice_options(NAME, &args[1])?;
    eprintln!("{prompt}");
    for (i, (_, text)) in options.iter().enumerate() {
        eprintln!("  {}. {text}", i + 1);
    }
    let count = options.len();
    let picks = ask_until(
        NAME,
        "Choices: ",
        &format!("numbers in 1..={count} separated by commas, or an empty answer"),
        |answer| parse_picks(answer, count),
    )?;
    Ok(Value::Array(
        picks.into_iter().map(|i| options[i].0.clone()).collect(),
    ))
}

/// `input_number(prompt?)`: an Int or a finite Float. Other text is asked again;
/// after the last attempt the call refuses with E_BAD_ARG.
fn bi_input_number(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_number";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_number(prompt?: String)",
    )?;
    let prompt = optional_prompt(NAME, &args, "Enter number: ")?;
    ask_until(NAME, &prompt, "a number", |answer| {
        parse_number(answer.trim())
    })
}

/// `input_editor(initial?)`: opens the editor named by `EDITOR` on a temporary
/// file that starts as `initial`, waits for it to exit, and answers the text
/// saved. It needs a terminal on stdin and stdout; without one it refuses with
/// E_NO_UI and runs nothing. An editor that exits unsuccessfully is a coded
/// E_TOOL_FAILED.
fn bi_input_editor(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_editor";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_editor(initial?: String)",
    )?;
    let initial = match args.first() {
        None => String::new(),
        Some(Value::Str(s)) if s.len() <= INPUT_EDITOR_MAX_BYTES => s.clone(),
        Some(Value::Str(s)) => {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("initial text of at most {INPUT_EDITOR_MAX_BYTES} bytes"),
                &format!("{} bytes", s.len()),
            ))
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                NAME,
                "initial: String",
                other.type_name(),
            ))
        }
    };
    use std::io::IsTerminal;
    if !(std::io::stdin().is_terminal() && std::io::stdout().is_terminal()) {
        return Err(crate::safety::no_ui(NAME));
    }
    let editor = editor_program(NAME)?;
    let path = create_edit_file(NAME, &initial)?;
    let answer = run_editor(NAME, &editor, &path).and_then(|()| read_edit_file(NAME, &path));
    let _ = std::fs::remove_file(&path);
    answer.map(Value::Str)
}

/// The editor program: the `EDITOR` variable, or notepad on Windows and vi
/// elsewhere. It names one program, run without a shell, so its text is not
/// split into arguments. A value that starts with `-` is refused, since the
/// editor would read it as an option.
fn editor_program(name: &str) -> Result<String> {
    let configured = match std::env::var("EDITOR") {
        Ok(value) => value,
        Err(std::env::VarError::NotPresent) => String::new(),
        Err(std::env::VarError::NotUnicode(_)) => {
            return Err(crate::safety::bad_arg(
                name,
                "EDITOR as Unicode text naming one program",
                "non-Unicode bytes",
            ))
        }
    };
    let editor = match configured.trim() {
        "" if cfg!(target_os = "windows") => "notepad".to_string(),
        "" => "vi".to_string(),
        value => value.to_string(),
    };
    if editor.starts_with('-') {
        return Err(crate::safety::bad_arg(
            name,
            "EDITOR naming a program, not an option",
            &echo_answer(&editor),
        ));
    }
    if editor.chars().any(char::is_control) {
        return Err(crate::safety::bad_arg(
            name,
            "EDITOR without control characters",
            "a control character",
        ));
    }
    Ok(editor)
}

/// Writes `text` to a new file in the temporary directory, under a name no
/// other file holds. The file is created exclusively and, on Unix, readable
/// only by its owner.
fn create_edit_file(name: &str, text: &str) -> Result<std::path::PathBuf> {
    use std::io::Write;
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    for attempt in 0..16u32 {
        let path = std::env::temp_dir().join(format!(
            "aether_edit_{}_{stamp}_{attempt}.txt",
            std::process::id()
        ));
        let mut options = std::fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }
        match options.open(&path) {
            Ok(mut file) => {
                if let Err(e) = file.write_all(text.as_bytes()) {
                    let _ = std::fs::remove_file(&path);
                    return Err(crate::safety::fs_error(name, &path, &e));
                }
                return Ok(path);
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(crate::safety::fs_error(name, &path, &e)),
        }
    }
    Err(crate::safety::fs_error(
        name,
        std::env::temp_dir(),
        &std::io::Error::other("no free temporary file name"),
    ))
}

/// Runs `editor` on `path` with the terminal inherited, without a shell.
fn run_editor(name: &str, editor: &str, path: &std::path::Path) -> Result<()> {
    let status = std::process::Command::new(editor)
        .arg(path)
        .status()
        .map_err(|e| crate::safety::spawn_error(name, editor, &e))?;
    if status.success() {
        return Ok(());
    }
    Err(crate::safety::tool_failed(
        name,
        editor,
        status.code(),
        "the editor exited without a successful status; nothing was answered",
    ))
}

/// The text saved in the temporary file, read through a bounded reader. A
/// file longer than `INPUT_EDITOR_MAX_BYTES` is refused, not truncated.
fn read_edit_file(name: &str, path: &std::path::Path) -> Result<String> {
    use std::io::Read;
    let file = std::fs::File::open(path).map_err(|e| crate::safety::fs_error(name, path, &e))?;
    let mut bytes = Vec::new();
    file.take(INPUT_EDITOR_MAX_BYTES as u64 + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| crate::safety::fs_error(name, path, &e))?;
    if bytes.len() > INPUT_EDITOR_MAX_BYTES {
        return Err(crate::safety::budget_exceeded(
            name,
            format!(
                "an edited text of at most {} KiB",
                INPUT_EDITOR_MAX_BYTES / 1024
            ),
            "the text was not answered; save a shorter text",
        ));
    }
    String::from_utf8(bytes).map_err(|_| {
        crate::safety::fs_error(
            name,
            path,
            &std::io::Error::new(std::io::ErrorKind::InvalidData, "the text is not UTF-8"),
        )
    })
}

/// `input_timeout(prompt, timeout_ms)`: one stdin line, or null when
/// `timeout_ms` passes first. The line typed after the timeout is not lost;
/// it answers the next prompt.
fn bi_input_timeout(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const BUILTIN: &str = "input_timeout";
    const MAX_MS: i64 = 3_600_000;
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "no pipeline input",
            "a piped value",
        ));
    }
    let [prompt, timeout] = args.as_slice() else {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "input_timeout(prompt: String, timeout_ms: Int)",
            &format!("{} arguments", args.len()),
        ));
    };
    let Value::Str(prompt) = prompt else {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "a String prompt",
            &format!("{prompt:?}"),
        ));
    };
    let ms = match timeout {
        Value::Int(ms) if (1..=MAX_MS).contains(ms) => *ms,
        other => {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                "an Int timeout_ms from 1 through 3600000",
                &format!("{other:?}"),
            ))
        }
    };
    eprint!("{prompt}");
    match stdin_lines::read_line(BUILTIN, Some(std::time::Duration::from_millis(ms as u64)))? {
        Some(line) => Ok(Value::Str(line)),
        None => Ok(Value::Null),
    }
}

/// Asks for one of `choices`. An exact match wins; otherwise a prefix that
/// matches exactly one choice, ignoring case, wins. Anything else lists the
/// candidates (or says there are none) and asks again.
fn bi_input_autocomplete(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_autocomplete";
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            NAME,
            "a direct call; the answer comes from the terminal, not piped input",
            "a piped value",
        ));
    }
    let [prompt, choices] = args.as_slice() else {
        return Err(crate::safety::bad_arg(
            NAME,
            "prompt: String, choices: Array of Strings",
            &format!("{} argument(s)", args.len()),
        ));
    };
    let Value::Str(prompt) = prompt else {
        return Err(crate::safety::bad_arg(
            NAME,
            "prompt: String",
            prompt.type_name(),
        ));
    };
    let Value::Array(choices) = choices else {
        return Err(crate::safety::bad_arg(
            NAME,
            "choices: Array of Strings",
            choices.type_name(),
        ));
    };
    if choices.is_empty() || choices.len() > INPUT_AUTOCOMPLETE_MAX_CHOICES {
        return Err(crate::safety::bad_arg(
            NAME,
            &format!("1..={INPUT_AUTOCOMPLETE_MAX_CHOICES} choices"),
            &format!("{} choice(s)", choices.len()),
        ));
    }
    let mut texts: Vec<&str> = Vec::with_capacity(choices.len());
    let mut seen = std::collections::BTreeSet::new();
    for (i, choice) in choices.iter().enumerate() {
        let Value::Str(text) = choice else {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("choice {}: a String", i + 1),
                choice.type_name(),
            ));
        };
        if text.is_empty() || text.len() > INPUT_TEXT_MAX_BYTES {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("choice {}: 1 to {INPUT_TEXT_MAX_BYTES} bytes", i + 1),
                &format!("{} bytes", text.len()),
            ));
        }
        if !seen.insert(text.as_str()) {
            return Err(crate::safety::bad_arg(
                NAME,
                "choices that are unique",
                &format!("duplicate {text:?}"),
            ));
        }
        texts.push(text.as_str());
    }

    for _ in 0..INPUT_AUTOCOMPLETE_MAX_ATTEMPTS {
        let answer = read_answer(NAME, prompt)?;
        if let Some(exact) = texts.iter().find(|c| **c == answer) {
            return Ok(Value::Str((*exact).to_string()));
        }
        let lower = answer.to_lowercase();
        let matches: Vec<&str> = texts
            .iter()
            .copied()
            .filter(|c| c.to_lowercase().starts_with(lower.as_str()))
            .collect();
        match matches.as_slice() {
            [only] => return Ok(Value::Str((*only).to_string())),
            [] => eprintln!("{NAME}: no match for {answer:?}"),
            many => {
                eprintln!("{NAME}: {} matches for {answer:?}:", many.len());
                for m in many.iter().take(INPUT_AUTOCOMPLETE_LIST) {
                    eprintln!("  {m}");
                }
                if many.len() > INPUT_AUTOCOMPLETE_LIST {
                    eprintln!("  ... and {} more", many.len() - INPUT_AUTOCOMPLETE_LIST);
                }
            }
        }
    }
    Err(crate::safety::bad_arg(
        NAME,
        "one of the choices, or a prefix that matches exactly one",
        &format!("no valid answer in {INPUT_AUTOCOMPLETE_MAX_ATTEMPTS} attempts"),
    ))
}

// ============================================================================
// 480-499: Security & Crypto
// ============================================================================

/// Hex digest of `bytes`, in-process.
///
/// These builtins shelled out -- `sha256sum`/`md5sum` on Unix, PowerShell on
/// Windows -- although `sha2`, `md5` and `sha1` are linked. Worse, a name the
/// match did not know fell through to SHA-256, so `crypto_hash(x, "blake3")`
/// returned a SHA-256 digest labelled as whatever was asked for.
fn digest_hex(builtin: &str, algo: &str, bytes: &[u8]) -> Result<String> {
    crate::safety::require_fips_hash(algo)?;
    let hex = |b: &[u8]| b.iter().map(|x| format!("{x:02x}")).collect::<String>();
    Ok(match algo.to_ascii_lowercase().as_str() {
        "md5" => format!("{:x}", md5::compute(bytes)),
        "sha1" | "sha-1" => hex(&sha1::Sha1::digest(bytes)),
        "sha256" | "sha-256" => hex(&Sha256::digest(bytes)),
        "sha384" | "sha-384" => hex(&sha2::Sha384::digest(bytes)),
        "sha512" | "sha-512" => hex(&sha2::Sha512::digest(bytes)),
        other => {
            return Err(crate::safety::bad_arg(
                builtin,
                "algorithm md5, sha1, sha256, sha384 or sha512",
                &format!("{other:?}"),
            ))
        }
    })
}

/// `(subject, the arguments after it)`: piped, the subject is the input and
/// every argument is a parameter; called directly, it is the first argument.
/// These builtins took `args[0]` as the data even when a value was piped, so
/// `"x" | crypto_hash("md5")` hashed the string "md5".
fn subject_and_params(
    builtin: &str,
    args: &[Value],
    input: Option<Value>,
) -> Result<(String, Vec<Value>)> {
    let (subject, params) = match input {
        Some(v) => (Some(v), args.to_vec()),
        None => (args.first().cloned(), args.get(1..).unwrap_or(&[]).to_vec()),
    };
    match subject {
        Some(Value::Str(s)) => Ok((s, params)),
        other => Err(crate::safety::bad_arg(
            builtin,
            "a String (argument or piped input)",
            other.as_ref().map(|v| v.type_name()).unwrap_or("nothing"),
        )),
    }
}

fn algo_param(builtin: &str, params: &[Value], default: &str) -> Result<String> {
    match params.first() {
        None => Ok(default.to_string()),
        Some(Value::Str(s)) => Ok(s.clone()),
        Some(other) => Err(crate::safety::bad_arg(
            builtin,
            "algorithm: String",
            other.type_name(),
        )),
    }
}

fn bi_crypto_hash(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (data, params) = subject_and_params("crypto_hash", &args, input)?;
    let algo = algo_param("crypto_hash", &params, "sha256")?;
    Ok(Value::Str(digest_hex(
        "crypto_hash",
        &algo,
        data.as_bytes(),
    )?))
}

/// `md5` and `sha256` shared `crypto_hash`'s dispatch row, and its default is
/// SHA-256, so `md5("hello")` returned the SHA-256 of "hello". Each now has
/// its own row with its algorithm fixed.
fn bi_named_hash(name: &str, args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (data, params) = subject_and_params(name, &args, input)?;
    if let Some(extra) = params.first() {
        return Err(crate::safety::bad_arg(
            name,
            &format!("only the data: {name} fixes its algorithm"),
            extra.type_name(),
        ));
    }
    Ok(Value::Str(digest_hex(name, name, data.as_bytes())?))
}

fn bi_crypto_hash_file(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_hash_file",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let algo = algo_param("crypto_hash_file", args.get(1..).unwrap_or(&[]), "sha256")?;
    let validated = crate::security::validate_read_path(&path)?;
    let bytes = read_bytes_capped("crypto_hash_file", &validated)?;
    Ok(Value::Str(digest_hex("crypto_hash_file", &algo, &bytes)?))
}

fn bi_crypto_hmac(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use hmac::{Hmac, Mac};
    let data = args
        .first()
        .ok_or_else(|| crate::safety::arg_err("crypto_hmac: data is required"))?;
    let data = expect_string("crypto_hmac", data)?;
    let key = args
        .get(1)
        .ok_or_else(|| crate::safety::arg_err("crypto_hmac: key is required"))?;
    let key = expect_string("crypto_hmac", key)?;
    let algo =
        algo_param("crypto_hmac", args.get(2..).unwrap_or(&[]), "sha256")?.to_ascii_lowercase();
    crate::safety::require_fips_hash(&algo)?;
    macro_rules! authenticate {
        ($digest:ty) => {{
            let mut mac = Hmac::<$digest>::new_from_slice(key.as_bytes())
                .map_err(|_| crate::safety::arg_err("crypto_hmac: invalid key"))?;
            mac.update(data.as_bytes());
            mac.finalize()
                .into_bytes()
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>()
        }};
    }
    let result = match algo.as_str() {
        "sha1" | "sha-1" => authenticate!(sha1::Sha1),
        "sha256" | "sha-256" => authenticate!(sha2::Sha256),
        "sha384" | "sha-384" => authenticate!(sha2::Sha384),
        "sha512" | "sha-512" => authenticate!(sha2::Sha512),
        "md5" => {
            // RFC 2104 compatibility: md5 0.7 predates the Digest trait.
            let shortened;
            let key = if key.len() > 64 {
                shortened = md5::compute(key.as_bytes()).0;
                &shortened[..]
            } else {
                key.as_bytes()
            };
            let mut inner_pad = [0x36; 64];
            let mut outer_pad = [0x5c; 64];
            for (i, byte) in key.iter().enumerate() {
                inner_pad[i] ^= byte;
                outer_pad[i] ^= byte;
            }
            let mut inner = md5::Context::new();
            inner.consume(inner_pad);
            inner.consume(data.as_bytes());
            let mut outer = md5::Context::new();
            outer.consume(outer_pad);
            outer.consume(inner.compute().0);
            format!("{:x}", outer.compute())
        }
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_hmac",
                "algorithm md5, sha1, sha256, sha384 or sha512",
                other,
            ))
        }
    };
    Ok(Value::Str(result))
}

fn bi_crypto_uuid(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    Ok(Value::Str(uuid::Uuid::new_v4().to_string()))
}

fn bi_crypto_random_bytes(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use rand::RngCore;
    let count = args
        .first()
        .map(|v| expect_int("crypto_random_bytes", v))
        .transpose()?
        .unwrap_or(32);
    if !(0..=1_048_576).contains(&count) {
        return Err(crate::safety::arg_err(
            "crypto_random_bytes: count must be in 0..1048576",
        ));
    }
    let mut bytes = vec![0u8; count as usize];
    rand::thread_rng().fill_bytes(&mut bytes);
    Ok(Value::Str(
        bytes.iter().map(|byte| format!("{byte:02x}")).collect(),
    ))
}

fn bi_crypto_random_string(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use rand::Rng;
    let length = args
        .first()
        .map(|v| expect_int("crypto_random_string", v))
        .transpose()?
        .unwrap_or(32);
    if !(0..=1_048_576).contains(&length) {
        return Err(crate::safety::arg_err(
            "crypto_random_string: length must be in 0..1048576",
        ));
    }
    let charset = args
        .get(1)
        .map(|v| expect_string("crypto_random_string", v))
        .transpose()?
        .unwrap_or("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
    let chars: Vec<char> = charset.chars().collect();
    if chars.is_empty() {
        return Err(crate::safety::arg_err(
            "crypto_random_string: charset must not be empty",
        ));
    }
    let mut rng = rand::thread_rng();
    let result = (0..length)
        .map(|_| chars[rng.gen_range(0..chars.len())])
        .collect();
    Ok(Value::Str(result))
}

fn bi_crypto_base64_encode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // In-process. This piped the data through `base64` on Unix and PowerShell
    // on Windows: GNU base64 wraps at 76 columns and PowerShell does not, so a
    // long input encoded differently by OS, and any failure answered "".
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    let data = hex_subject("crypto_base64_encode", &args, input)?;
    Ok(Value::Str(STANDARD.encode(data.as_bytes())))
}

fn bi_crypto_base64_decode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    let data = hex_subject("crypto_base64_decode", &args, input)?;
    // Wrapped input (as `base64` writes it) decodes: whitespace is not data.
    let compact: String = data.chars().filter(|c| !c.is_ascii_whitespace()).collect();
    let bytes = STANDARD.decode(compact.as_bytes()).map_err(|e| {
        crate::safety::bad_arg("crypto_base64_decode", "valid base64", &e.to_string())
    })?;
    // Bytes that are not text were replaced with U+FFFD, silently.
    String::from_utf8(bytes).map(Value::Str).map_err(|_| {
        crate::safety::bad_arg(
            "crypto_base64_decode",
            "base64 of UTF-8 text (these bytes are binary)",
            "non-UTF-8 bytes",
        )
    })
}

/// The string a hex builtin works on: the argument, else the piped value.
/// Both answered "" when there was none, which reads as "encoded nothing".
fn hex_subject(builtin: &str, args: &[Value], input: Option<Value>) -> Result<String> {
    match args.first().cloned().or(input) {
        Some(Value::Str(s)) => Ok(s),
        other => Err(crate::safety::bad_arg(
            builtin,
            "a String (argument or piped input)",
            other.as_ref().map(|v| v.type_name()).unwrap_or("nothing"),
        )),
    }
}

fn bi_crypto_hex_encode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let data = hex_subject("crypto_hex_encode", &args, input)?;
    let hex: String = data.bytes().map(|b| format!("{:02x}", b)).collect();
    Ok(Value::Str(hex))
}

fn bi_crypto_hex_decode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // This sliced `data[i..i + 2]` on byte offsets: an odd length read past
    // the end and a non-ASCII character split a code point, and both
    // panicked. Invalid pairs were skipped, so "zz41" decoded to "A".
    let data = hex_subject("crypto_hex_decode", &args, input)?;
    let digits = data.as_bytes();
    if digits.len() % 2 != 0 || !digits.iter().all(u8::is_ascii_hexdigit) {
        return Err(crate::safety::bad_arg(
            "crypto_hex_decode",
            "hex digits in pairs",
            &format!("{:?}", data.chars().take(40).collect::<String>()),
        ));
    }
    let bytes: Vec<u8> = digits
        .chunks(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap_or("00"), 16).unwrap_or(0))
        .collect();
    Ok(Value::Str(String::from_utf8_lossy(&bytes).to_string()))
}

/// Envelope version tag for authenticated ciphertext. A ciphertext that does
/// not begin with this is from before AS-2026-04 was fixed and carries no
/// integrity protection; `bi_crypto_decrypt` refuses it unless the caller opts
/// in, so an attacker cannot strip the envelope to downgrade a modern
/// ciphertext onto the unauthenticated path.
const CRYPTO_ENVELOPE_V1: &str = "AE1";

/// Additional authenticated data for the original `AE1` envelope.
///
/// Frozen: 10.0.0 shipped ciphertext authenticated under exactly these bytes,
/// and changing them would make every one of those ciphertexts undecryptable.
const CRYPTO_AAD: &[u8] = b"AetherShell-AE1";

/// AAD for the FIPS envelope, which carries its own version.
const CRYPTO_AAD_FIPS: &[u8] = b"AetherShell-AE1F";

/// Envelope version tag for ciphertext whose key was derived with PBKDF2
/// rather than Argon2id.
///
/// Argon2id is the better choice against offline cracking and stays the
/// default. It is also not FIPS-approved, which left `crypto.encrypt` with one
/// non-approved primitive in an otherwise approved chain (AS-2026-08). Under
/// `AETHER_FIPS` the key is derived with PBKDF2-HMAC-SHA256 (SP 800-132)
/// instead and the envelope says so, so a deployment that must be
/// all-approved can be, without changing what anyone else gets.
const CRYPTO_ENVELOPE_V1_FIPS: &str = "AE1F";

/// Iterations for the PBKDF2 path.
///
/// Deliberately a constant rather than a field in the envelope: the header is
/// not authenticated until after key derivation, so a count carried in the
/// ciphertext would let an attacker demand an arbitrarily expensive derivation
/// before the tag could reject it. Changing this value means minting a new
/// version tag.
const CRYPTO_PBKDF2_ROUNDS: u32 = 600_000;

/// Which key-derivation function an envelope tag selects.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum CryptoKdf {
    Argon2id,
    Pbkdf2HmacSha256,
}

impl CryptoKdf {
    /// The KDF to use for new ciphertext.
    fn for_new_ciphertext() -> Self {
        if crate::safety::fips_enabled() {
            Self::Pbkdf2HmacSha256
        } else {
            Self::Argon2id
        }
    }

    /// The AEAD's additional data, which differs per version so that the
    /// version tag is *authenticated* rather than merely load-bearing.
    ///
    /// Without this, swapping `AE1F` for `AE1` on a ciphertext is rejected only
    /// because the two tags select different KDFs and therefore different keys
    /// — true today, and an accident rather than a property. Binding the
    /// version into the AAD makes the rejection structural: it holds even if
    /// two versions ever derive the same key.
    fn aad(self) -> &'static [u8] {
        match self {
            Self::Argon2id => CRYPTO_AAD,
            Self::Pbkdf2HmacSha256 => CRYPTO_AAD_FIPS,
        }
    }

    fn tag(self) -> &'static str {
        match self {
            Self::Argon2id => CRYPTO_ENVELOPE_V1,
            Self::Pbkdf2HmacSha256 => CRYPTO_ENVELOPE_V1_FIPS,
        }
    }

    /// Decrypt reads the KDF from the envelope, never from the ambient mode:
    /// ciphertext written under `AETHER_FIPS` must stay readable without it,
    /// and vice versa.
    fn from_tag(tag: &str) -> Option<Self> {
        match tag {
            CRYPTO_ENVELOPE_V1 => Some(Self::Argon2id),
            CRYPTO_ENVELOPE_V1_FIPS => Some(Self::Pbkdf2HmacSha256),
            _ => None,
        }
    }
}

/// Derive a 32-byte AEAD key from a password.
///
/// Argon2id by default -- the same KDF `auth.rs` uses for password storage,
/// for the same reason: the threat is a precomputed table over a small
/// guessable space, and a fast hash invites one.
fn crypto_derive_key(password: &str, salt: &[u8], kdf: CryptoKdf) -> Result<[u8; 32]> {
    let mut key = [0u8; 32];
    match kdf {
        CryptoKdf::Argon2id => argon2::Argon2::default()
            .hash_password_into(password.as_bytes(), salt, &mut key)
            .map_err(|e| {
                crate::safety::crypto_failed(
                    "",
                    format!("key derivation failed: {e}"),
                    "no ciphertext was produced; the same input fails the same way, so check the host's Argon2 support",
                )
            })?,
        CryptoKdf::Pbkdf2HmacSha256 => {
            pbkdf2::pbkdf2_hmac::<sha2::Sha256>(
                password.as_bytes(),
                salt,
                CRYPTO_PBKDF2_ROUNDS,
                &mut key,
            );
        }
    }
    Ok(key)
}

fn bi_crypto_encrypt(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use aes_gcm::aead::{Aead, KeyInit, Payload};
    use base64::{engine::general_purpose::STANDARD, Engine as _};

    let data = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_encrypt",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let password = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_encrypt",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    if password.is_empty() {
        return Err(crate::safety::arg_err(
            "crypto.encrypt requires a non-empty password; nothing was encrypted",
        ));
    }

    // Fresh salt per message, so the derived key is unique per ciphertext and a
    // random nonce carries no birthday-bound risk across messages.
    let salt: [u8; 16] = rand::random();
    let nonce_bytes: [u8; 12] = rand::random();
    let kdf = CryptoKdf::for_new_ciphertext();
    let key = crypto_derive_key(&password, &salt, kdf)?;

    let cipher = aes_gcm::Aes256Gcm::new_from_slice(&key).map_err(|e| {
        crate::safety::crypto_failed(
            "",
            format!("bad key length: {e}"),
            "no ciphertext was produced; the derived key was rejected by the cipher",
        )
    })?;
    let ct = cipher
        .encrypt(
            aes_gcm::Nonce::from_slice(&nonce_bytes),
            Payload {
                msg: data.as_bytes(),
                aad: kdf.aad(),
            },
        )
        .map_err(|_| {
            crate::safety::crypto_failed(
                "",
                "encryption failed; nothing was encrypted",
                "retry once; if it fails again the in-process cipher is refusing this input",
            )
        })?;

    Ok(Value::Str(format!(
        "{}.{}.{}.{}",
        kdf.tag(),
        STANDARD.encode(salt),
        STANDARD.encode(nonce_bytes),
        STANDARD.encode(&ct)
    )))
}

/// Decrypt a pre-AS-2026-04 `openssl enc -aes-256-cbc` ciphertext. Kept so data
/// written by an older AetherShell stays recoverable, but off by default: see
/// the refusal in `bi_crypto_decrypt` for why.
/// Deadline for one legacy decrypt. OpenSSL on a few MiB finishes in well under
/// a second; this bounds a hung child, not a slow one.
const CRYPTO_LEGACY_DEADLINE_SECS: u64 = 30;
/// The most plaintext one legacy decrypt may return. Past it the call is
/// refused: a plaintext cut short would look whole.
const CRYPTO_LEGACY_MAX_BYTES: usize = 64 * 1024 * 1024;

/// Re-wrap legacy base64 the way `openssl enc -base64` writes it: 64-character
/// lines, each newline-terminated.
///
/// `openssl enc -d -base64` without `-A` reads line by line, and a final line
/// with no newline fails with "error reading input file". Callers trim their
/// input, so a short ciphertext always arrived that way. Whitespace is dropped
/// first, so one unbroken line and openssl's own wrapped form both reach
/// openssl in the shape it reads.
fn legacy_base64_lines(data: &str) -> String {
    const LINE: usize = 64;
    let compact: Vec<char> = data.chars().filter(|c| !c.is_whitespace()).collect();
    let mut out = String::with_capacity(compact.len() + compact.len() / LINE + 1);
    for chunk in compact.chunks(LINE) {
        out.extend(chunk.iter());
        out.push('\n');
    }
    out
}

fn crypto_decrypt_legacy_cbc(data: &str, password: &str) -> Result<Value> {
    let output = run_output(
        "crypto_decrypt",
        "openssl",
        "openssl",
        &[
            "enc",
            "-aes-256-cbc",
            "-pbkdf2",
            "-d",
            "-base64",
            // `pass:` puts the secret in argv, which is world-readable via
            // /proc/<pid>/cmdline on Linux. `env:` keeps it in the child
            // environment, which is owner-readable only (AS-2026-03).
            "-pass",
            "env:AE_OPENSSL_PASS",
        ],
        |cmd| {
            cmd.env("AE_OPENSSL_PASS", password);
        },
        Some(legacy_base64_lines(data).into_bytes()),
        CRYPTO_LEGACY_DEADLINE_SECS,
        CRYPTO_LEGACY_MAX_BYTES,
    )?;
    if output.status.success() {
        // The same refusal as the authenticated path: a lossy conversion would
        // silently change the plaintext, so non-UTF-8 output is not returned.
        return String::from_utf8(output.stdout)
            .map(Value::Str)
            .map_err(|_| {
                crate::safety::decrypt_failed(
                    "crypto_decrypt",
                    "crypto_decrypt: plaintext is not valid UTF-8; the legacy decrypt \
                     succeeded but its bytes are not text, so nothing was returned",
                    "the plaintext is binary; decrypt it with `openssl enc -d` and handle \
                     the bytes there",
                )
            });
    }
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    Err(crate::safety::decrypt_failed(
        "crypto_decrypt",
        format!(
            "crypto_decrypt: legacy (unauthenticated) decrypt failed -- the password may be \
             wrong, or the ciphertext may have been modified. AES-256-CBC is not authenticated, \
             so a *successful* legacy decrypt is not proof of integrity either. openssl: {}",
            if stderr.is_empty() {
                "(no detail)".to_string()
            } else {
                stderr
            }
        ),
        "check the password; if it is right, the ciphertext was altered and should not be \
         trusted. Nothing was decrypted",
    ))
}

fn bi_crypto_decrypt(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use aes_gcm::aead::{Aead, KeyInit, Payload};
    use base64::{engine::general_purpose::STANDARD, Engine as _};

    let data = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_decrypt",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let password = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_decrypt",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    let trimmed = data.trim();
    let parts: Vec<&str> = trimmed.split('.').collect();
    let kdf = parts.first().and_then(|t| CryptoKdf::from_tag(t));
    if parts.len() != 4 || kdf.is_none() {
        // Not an authenticated envelope. Accepting this silently would hand an
        // attacker a downgrade: strip the `AE1.` prefix and tag from a modern
        // ciphertext and the unauthenticated path would take it. So the legacy
        // format is opt-in, by whoever runs the shell rather than by whoever
        // supplies the ciphertext.
        if !crate::safety::truthy_env("AETHER_CRYPTO_LEGACY_DECRYPT") {
            return Err(crate::safety::decrypt_failed(
                "crypto_decrypt",
                format!(
                    "crypto_decrypt: this is not an authenticated `{}` ciphertext. It was \
                     most likely produced by AetherShell before 10.0.0, when crypto.encrypt \
                     used unauthenticated AES-256-CBC (AS-2026-04), so decrypting it cannot \
                     detect tampering. Nothing was decrypted",
                    CRYPTO_ENVELOPE_V1
                ),
                "set AETHER_CRYPTO_LEGACY_DECRYPT=1 to decrypt it anyway, then re-encrypt \
                 with crypto.encrypt to gain integrity protection",
            ));
        }
        return crypto_decrypt_legacy_cbc(trimmed, &password);
    }

    let malformed = |what: &str| {
        crate::safety::decrypt_failed(
            "crypto_decrypt",
            format!("crypto_decrypt: malformed ciphertext ({what}); nothing was decrypted"),
            "pass the unmodified output of crypto.encrypt",
        )
    };
    let decode = |what: &str, s: &str| -> Result<Vec<u8>> {
        STANDARD
            .decode(s)
            .map_err(|e| malformed(&format!("{what} is not valid base64: {e}")))
    };
    let salt = decode("salt", parts[1])?;
    let nonce_bytes = decode("nonce", parts[2])?;
    let ct = decode("body", parts[3])?;
    if nonce_bytes.len() != 12 {
        return Err(malformed(&format!(
            "nonce is {} bytes, expected 12",
            nonce_bytes.len()
        )));
    }

    // The KDF comes from the envelope, never from the ambient FIPS mode. The
    // salt is attacker-chosen text, so a salt the KDF refuses is a malformed
    // ciphertext, not a shell fault.
    let kdf = kdf.expect("checked above");
    let key = crypto_derive_key(&password, &salt, kdf).map_err(|e| {
        malformed(&format!(
            "the key could not be derived from its salt: {}",
            strip_code_prefix(&e.to_string())
        ))
    })?;
    let cipher = aes_gcm::Aes256Gcm::new_from_slice(&key)
        .map_err(|e| malformed(&format!("the key has the wrong length: {e}")))?;

    // AES-GCM verifies the tag before any plaintext is released, so a wrong
    // password and a modified ciphertext give the same answer here -- and
    // unlike the CBC path, "it decrypted" now genuinely means "it was not
    // modified".
    let plaintext = cipher
        .decrypt(
            aes_gcm::Nonce::from_slice(&nonce_bytes),
            Payload {
                msg: &ct,
                aad: kdf.aad(),
            },
        )
        .map_err(|_| {
            crate::safety::decrypt_failed(
                "crypto_decrypt",
                "crypto_decrypt: authentication failed -- the password is wrong or the \
                 ciphertext was modified. No plaintext was released",
                "check the password; if it is right, the ciphertext was altered and should \
                 not be trusted",
            )
        })?;

    String::from_utf8(plaintext).map(Value::Str).map_err(|_| {
        crate::safety::decrypt_failed(
            "crypto_decrypt",
            "crypto_decrypt: plaintext is not valid UTF-8; nothing was returned",
            "the plaintext is binary; crypto.decrypt returns text only",
        )
    })
}

/// Drop a leading `E_CODE: ` token from an error's text. Used where a shared
/// helper's own code would otherwise appear inside a message that already
/// carries the `E_DECRYPT_FAILED` code.
fn strip_code_prefix(text: &str) -> &str {
    match text.split_once(": ") {
        Some((head, rest)) if head.starts_with("E_") => rest,
        _ => text,
    }
}

#[path = "digital_signatures.rs"]
mod digital_signatures;
fn bi_crypto_sign(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    digital_signatures::sign(args, input)
}

fn bi_crypto_key_generate(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = "crypto_generate_key";
    if args.len() > 2 || input.is_some() {
        return Err(crate::safety::arg_err(
            "crypto_generate_key accepts zero to two arguments and no pipeline input",
        ));
    }
    let key_type = match args.first() {
        None => "rsa".to_string(),
        Some(Value::Str(s)) => s.to_ascii_lowercase(),
        Some(v) => {
            return Err(crate::safety::bad_arg(
                name,
                "key type String",
                v.type_name(),
            ))
        }
    };
    if !matches!(key_type.as_str(), "rsa" | "ec" | "ecdsa" | "ed25519") {
        return Err(crate::safety::bad_arg(
            name,
            "key type rsa, ec, ecdsa or ed25519",
            "unsupported key type",
        ));
    }
    let bits = match args.get(1) {
        None => 2048,
        Some(Value::Int(n)) if key_type == "rsa" && (2048..=16384).contains(n) => *n,
        Some(_) => {
            return Err(crate::safety::bad_arg(
                name,
                "RSA-only integer size from 2048 to 16384 bits",
                "invalid or inapplicable size",
            ))
        }
    };
    if key_type == "ed25519" {
        return digital_signatures::generate_key();
    }
    // The key is returned as PEM text and no file is written, so there is no
    // file mode to set here. A caller that saves the key owns that file's
    // protection: on Unix it should chmod 0600; on Windows the file inherits
    // the ACL of the directory it is written into.
    let mut command = std::process::Command::new("openssl");
    if key_type == "rsa" {
        command.args(["genrsa", &bits.to_string()]);
    } else {
        command.args(["ecparam", "-genkey", "-noout", "-name", "prime256v1"]);
    }
    command.stdin(std::process::Stdio::null());
    // Generating an RSA key can be slow; the long deadline covers it.
    let output = bounded_cmd_output(name, "openssl", command, TOOL_LONG_DEADLINE_SECS)?;
    crypto_key_output(output)
}

fn crypto_key_output(output: std::process::Output) -> Result<Value> {
    let name = "crypto_generate_key";
    if !output.status.success() {
        return Err(crate::safety::tool_failed(
            name,
            "openssl",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    let text = String::from_utf8(output.stdout).map_err(|_| {
        crate::safety::bad_state(name, "non-UTF-8 key output", "PEM private-key output")
    })?;
    use base64::Engine;
    let valid = text.len() <= 65536
        && ["PRIVATE KEY", "RSA PRIVATE KEY", "EC PRIVATE KEY"]
            .iter()
            .any(|label| {
                let begin = format!("-----BEGIN {label}-----");
                let end = format!("-----END {label}-----");
                let Some(body) = text
                    .trim()
                    .strip_prefix(&begin)
                    .and_then(|s| s.strip_suffix(&end))
                else {
                    return false;
                };
                let body: String = body.chars().filter(|c| !c.is_ascii_whitespace()).collect();
                base64::engine::general_purpose::STANDARD
                    .decode(body)
                    .is_ok_and(|bytes| !bytes.is_empty())
            });
    if !valid {
        return Err(crate::safety::bad_state(
            name,
            "unexpected successful tool output",
            "PEM private-key envelope",
        ));
    }
    Ok(Value::Str(text))
}

#[cfg(all(test, any(unix, windows)))]
mod crypto_key_output_tests {
    use super::*;
    fn output(success: bool, stdout: &[u8]) -> std::process::Output {
        #[cfg(unix)]
        let status = {
            use std::os::unix::process::ExitStatusExt;
            std::process::ExitStatus::from_raw(if success { 0 } else { 256 })
        };
        #[cfg(windows)]
        let status = {
            use std::os::windows::process::ExitStatusExt;
            std::process::ExitStatus::from_raw(if success { 0 } else { 1 })
        };
        std::process::Output {
            status,
            stdout: stdout.to_vec(),
            stderr: b"test tool failure".to_vec(),
        }
    }
    #[test]
    fn pem_envelopes_are_preserved_and_bad_success_is_coded() {
        for label in ["PRIVATE KEY", "RSA PRIVATE KEY", "EC PRIVATE KEY"] {
            let pem = format!("-----BEGIN {label}-----\nZml4dHVyZQ==\n-----END {label}-----\n");
            assert!(
                matches!(crypto_key_output(output(true, pem.as_bytes())).unwrap(), Value::Str(s) if s == pem)
            );
        }
        for invalid in [
            b"".as_slice(),
            b"Key generation requires OpenSSL",
            b"\xff",
            b"-----BEGIN PRIVATE KEY-----\ntruncated",
            b"-----BEGIN PRIVATE KEY-----\n-----END PRIVATE KEY-----",
            b"-----BEGIN PRIVATE KEY-----\nnot base64!\n-----END PRIVATE KEY-----",
        ] {
            let err = crypto_key_output(output(true, invalid)).unwrap_err();
            assert!(err.to_string().contains("E_BAD_STATE"), "{err}");
        }
    }
    #[test]
    fn failed_exit_trumps_success_shaped_or_non_utf8_stdout() {
        for stdout in [
            b"-----BEGIN PRIVATE KEY-----\nfixture\n-----END PRIVATE KEY-----".as_slice(),
            b"\xff",
        ] {
            let err = crypto_key_output(output(false, stdout))
                .unwrap_err()
                .to_string();
            assert!(
                err.contains("E_TOOL_FAILED") && err.contains("test tool failure"),
                "{err}"
            );
        }
    }
}

fn password_arguments<'a>(
    name: &str,
    args: &'a [Value],
    input: &Option<Value>,
    count: usize,
) -> Result<Vec<&'a str>> {
    if input.is_some() || args.len() != count {
        return Err(crate::safety::bad_arg(
            name,
            "exact positional String arguments; no pipeline input",
            "invalid call shape",
        ));
    }
    let values = args
        .iter()
        .map(|v| match v {
            Value::Str(s) => Ok(s.as_str()),
            _ => Err(crate::safety::bad_arg(name, "String", v.type_name())),
        })
        .collect::<Result<Vec<_>>>()?;
    if values[0].len() > 65536 || (count == 2 && values[1].len() > 1024) {
        return Err(crate::safety::budget_exceeded(
            name,
            "password or stored hash exceeds size limit".into(),
            "password limit 65536 bytes; stored hash limit 1024 bytes",
        ));
    }
    Ok(values)
}

fn bi_crypto_password_hash(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use argon2::password_hash::{PasswordHasher, SaltString};
    use rand::RngCore;
    let values = password_arguments("crypto_password_hash", &args, &input, 1)?;
    let mut salt = [0u8; 16];
    rand::rngs::OsRng.try_fill_bytes(&mut salt).map_err(|_| {
        crate::safety::bad_state(
            "crypto_password_hash",
            "randomness unavailable",
            "operating-system entropy",
        )
    })?;
    let salt = SaltString::encode_b64(&salt).map_err(|_| {
        crate::safety::bad_state("crypto_password_hash", "salt encoding failed", "valid salt")
    })?;
    let hash = if crate::safety::fips_enabled() {
        pbkdf2::Pbkdf2.hash_password(values[0].as_bytes(), &salt)
    } else {
        argon2::Argon2::default().hash_password(values[0].as_bytes(), &salt)
    }
    .map_err(|_| {
        crate::safety::bad_state(
            "crypto_password_hash",
            "password derivation failed",
            "supported parameters",
        )
    })?;
    Ok(Value::Str(hash.to_string()))
}

#[path = "sha_crypt.rs"]
mod sha_crypt;

fn bi_crypto_password_verify(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    use argon2::password_hash::{PasswordHash, PasswordVerifier};
    let name = "crypto_password_verify";
    let values = password_arguments(name, &args, &input, 2)?;
    let malformed = || {
        crate::safety::bad_arg(
            name,
            "supported password hash with valid parameters",
            "invalid stored hash",
        )
    };
    if values[1].len() == 64 && values[1].bytes().all(|b| b.is_ascii_hexdigit()) {
        if crate::safety::fips_enabled() {
            return Err(crate::safety::policy_deny(
                name,
                "legacy unsalted password hash",
                "rehash with crypto_password_hash",
            ));
        }
        use argon2::password_hash::Output;
        use sha2::{Digest, Sha256};
        let expected = hex::decode(values[1]).map_err(|_| malformed())?;
        let actual = Sha256::digest(values[0].as_bytes());
        return Ok(Value::Bool(
            Output::new(&expected).map_err(|_| malformed())?
                == Output::new(&actual).map_err(|_| malformed())?,
        ));
    }
    // SHA-crypt ($5$ / $6$) is verify-only. It is built from SHA-2, but it is not
    // an approved password-hashing construction; under AETHER_FIPS only PBKDF2 is,
    // as for the legacy hex and Argon2 branches.
    if values[1].starts_with("$5$") || values[1].starts_with("$6$") {
        if crate::safety::fips_enabled() {
            return Err(crate::safety::policy_deny(
                name,
                "SHA-crypt is outside the configured algorithm policy",
                "rehash with crypto_password_hash",
            ));
        }
        return Ok(Value::Bool(sha_crypt::verify(name, values[0], values[1])?));
    }
    let hash = PasswordHash::new(values[1]).map_err(|_| malformed())?;
    let salt = hash.salt.ok_or_else(malformed)?;
    let mut salt_bytes = [0u8; 64];
    let salt_len = salt
        .decode_b64(&mut salt_bytes)
        .map_err(|_| malformed())?
        .len();
    let digest_len = hash.hash.ok_or_else(malformed)?.len();
    if !(8..=64).contains(&salt_len) || !(16..=64).contains(&digest_len) {
        return Err(malformed());
    }
    let result = match hash.algorithm.as_str() {
        "argon2id" => {
            if crate::safety::fips_enabled() {
                return Err(crate::safety::policy_deny(
                    name,
                    "Argon2 is outside the configured algorithm policy",
                    "use a PBKDF2 password hash",
                ));
            }
            if hash.version != Some(19) || hash.params.iter().count() != 3 {
                return Err(malformed());
            }
            for key in ["m", "t", "p"] {
                if hash.params.get_decimal(key).is_none() {
                    return Err(malformed());
                }
            }
            let params = argon2::Params::try_from(&hash).map_err(|_| malformed())?;
            if params.m_cost() > 65536 || params.t_cost() > 10 || params.p_cost() > 4 {
                return Err(crate::safety::budget_exceeded(
                    name,
                    "stored Argon2 parameters exceed verification limits".into(),
                    "maximum m=65536 KiB, t=10, p=4",
                ));
            }
            argon2::Argon2::default().verify_password(values[0].as_bytes(), &hash)
        }
        "pbkdf2-sha256" => {
            let params = pbkdf2::Params::try_from(&hash).map_err(|_| malformed())?;
            if params.rounds == 0 || !(16..=64).contains(&params.output_length) {
                return Err(malformed());
            }
            if params.rounds > 1200000 {
                return Err(crate::safety::budget_exceeded(
                    name,
                    "stored PBKDF2 iterations exceed verification limit".into(),
                    "maximum 1200000 iterations",
                ));
            }
            pbkdf2::Pbkdf2.verify_password(values[0].as_bytes(), &hash)
        }
        _ => return Err(malformed()),
    };
    match result {
        Ok(()) => Ok(Value::Bool(true)),
        Err(argon2::password_hash::Error::Password) => Ok(Value::Bool(false)),
        Err(_) => Err(malformed()),
    }
}

fn bi_crypto_checksum(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    bi_crypto_hash_file(args, None)
}

fn bi_crypto_cert_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = "crypto_cert_info";
    if args.len() != 1 || input.is_some() {
        return Err(crate::safety::arg_err(
            "crypto_cert_info requires one path and no pipeline input",
        ));
    }
    let Value::Str(path) = &args[0] else {
        return Err(crate::safety::bad_arg(
            name,
            "path String",
            args[0].type_name(),
        ));
    };
    crate::safety::reject_option_like(name, std::slice::from_ref(path))?;
    let path = crate::safety::resolve_path_str(path);
    let metadata =
        std::fs::metadata(&path).map_err(|e| crate::safety::fs_error(name, &path, &e))?;
    if !metadata.is_file() {
        return Err(crate::safety::bad_arg(
            name,
            "regular certificate file",
            "non-file path",
        ));
    }
    if metadata.len() > 64 * 1024 * 1024 {
        return Err(crate::safety::budget_exceeded(
            name,
            "certificate input exceeds 64 MiB".into(),
            "inspect a smaller file",
        ));
    }
    // The same `openssl` on every OS: the Command resolves it through PATH
    // (openssl.exe on Windows), and an absent tool is E_TOOL_MISSING.
    let mut cmd = std::process::Command::new("openssl");
    cmd.args(["x509", "-in", &path, "-text", "-noout"])
        .stdin(std::process::Stdio::null());
    let output = bounded_cmd_output(name, "openssl", cmd, TOOL_DEADLINE_SECS)?;
    if !output.status.success() {
        return Err(crate::safety::tool_failed(
            name,
            "openssl",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    let text = String::from_utf8(output.stdout).map_err(|_| {
        crate::safety::bad_state(
            name,
            "non-UTF-8 certificate output",
            "textual certificate details",
        )
    })?;
    if text.trim().is_empty() {
        return Err(crate::safety::bad_state(
            name,
            "empty successful tool output",
            "textual certificate details",
        ));
    }
    Ok(Value::Str(text))
}

