fn bi_db_sqlite_backup(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_backup",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let backup_path = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        None => format!("{}.backup", db_path),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_backup",
                "destination: String",
                other.type_name(),
            ))
        }
    };

    crate::safety::reject_option_like("db_sqlite_backup", std::slice::from_ref(&db_path))?;
    // The path is interpolated into a `.backup '…'` dot-command. A quote in it
    // closes that argument and the rest becomes further arguments to `.backup`
    // — measured: `.backup 'x' --append 'other.db'` reaches the option parser.
    // That is not command execution (`.backup`'s options do not run programs,
    // and a newline does not start a second dot-command when the whole string
    // arrives as one argv entry — both checked against sqlite3 3.53.4), but it
    // does let a caller who asked to write one file pass options to a command
    // they were not given. Refused rather than escaped: a backup path with a
    // quote or a newline in it is not a request worth honouring.
    if backup_path.contains('\'') || backup_path.contains('\n') {
        return Err(crate::safety::bad_arg(
            "db_sqlite_backup",
            "a backup path without quotes or newlines",
            &backup_path,
        ));
    }
    let mut cmd = std::process::Command::new("sqlite3");
    cmd.args([&db_path, &format!(".backup '{}'", backup_path)]);
    let output = bounded_cmd_output("db_sqlite_backup", "sqlite3", cmd, TOOL_DEADLINE_SECS)?;

    if !output.status.success() {
        return Err(crate::safety::tool_failed(
            "db_sqlite_backup",
            "sqlite3",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    Ok(Value::Bool(true))
}

/// A coded budget refusal whose builtin name is left empty: the boundary
/// (`ensure_structured`) fills it in, so the message carries no builtin prefix.
fn budget_unnamed(message: &str, hint: &str) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::BudgetExceeded,
        message: message.to_string(),
        builtin: String::new(),
        hint: hint.to_string(),
        approval: None,
        did_you_mean: Vec::new(),
        expected: String::new(),
        got: String::new(),
    })
}

/// A coded I/O failure from a library whose error is not an `io::Error` (here
/// rusqlite), so `safety::fs_error` does not apply. `E_IO` is the code for a
/// failure that is neither absence nor refusal.
fn coded_io(builtin: &str, message: String, hint: &str) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::Io,
        message,
        builtin: builtin.to_string(),
        hint: hint.to_string(),
        approval: None,
        did_you_mean: Vec::new(),
        expected: String::new(),
        got: String::new(),
    })
}

fn bi_db_csv_to_sqlite(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const NAME: &str = "db_csv_to_sqlite";
    let db_path = args
        .first()
        .ok_or_else(|| crate::safety::arg_err("db_csv_to_sqlite: db is required"))?;
    let db_path = expect_string(NAME, db_path)?;
    let csv_path = args
        .get(1)
        .ok_or_else(|| crate::safety::arg_err("db_csv_to_sqlite: csv is required"))?;
    let csv_path = expect_string(NAME, csv_path)?;
    let table = args
        .get(2)
        .map(|v| expect_string(NAME, v))
        .transpose()?
        .unwrap_or("imported");
    let table = format!("\"{}\"", crate::safety::sql_identifier(NAME, table)?);
    let csv_path = crate::safety::resolve_path_str(csv_path);
    std::fs::metadata(&csv_path).map_err(|e| crate::safety::fs_error(NAME, &csv_path, &e))?;
    let source = crate::security::validate_read_path(&csv_path).map_err(|e| {
        crate::safety::policy_deny(
            NAME,
            format!("{NAME}: {e}"),
            "the shell's read policy refuses this file; choose a file it permits",
        )
    })?;
    let metadata =
        std::fs::metadata(&source).map_err(|e| crate::safety::fs_error(NAME, &csv_path, &e))?;
    crate::security::check_file_size_limit(metadata.len()).map_err(|e| {
        crate::safety::budget_exceeded(
            NAME,
            e.to_string(),
            "the CSV file is larger than the read limit; split it into smaller files",
        )
    })?;
    let content = std::fs::read_to_string(&source)
        .map_err(|e| crate::safety::fs_error(NAME, &csv_path, &e))?;
    let csv_error = |e: csv::Error| {
        crate::safety::bad_arg(
            NAME,
            "CSV with a header and equal-length rows",
            &e.to_string(),
        )
    };
    let mut reader = csv::ReaderBuilder::new()
        .trim(csv::Trim::Headers)
        .from_reader(content.as_bytes());
    let headers = reader.headers().map_err(csv_error)?.clone();
    if headers.is_empty() {
        return Err(crate::safety::arg_err(
            "db_csv_to_sqlite: CSV header must be nonempty",
        ));
    }
    let mut names = std::collections::HashSet::new();
    let columns: Vec<String> = headers
        .iter()
        .map(|name| {
            let name = crate::safety::sql_identifier(NAME, name)?;
            if !names.insert(name.to_ascii_lowercase()) {
                return Err(crate::safety::arg_err(
                    "db_csv_to_sqlite: duplicate CSV column name",
                ));
            }
            Ok(format!("\"{name}\""))
        })
        .collect::<Result<_>>()?;
    // Parse all rows before opening the destination; failed validation creates nothing.
    let rows = reader
        .records()
        .enumerate()
        .map(|(index, row)| {
            if index >= 1_000_000 {
                return Err(crate::safety::budget_exceeded(
                    NAME,
                    "CSV exceeds 1000000 rows".to_string(),
                    "split the CSV into files of at most 1000000 rows",
                ));
            }
            row.map_err(csv_error)
        })
        .collect::<Result<Vec<_>>>()?;
    let db_path = guard_local_write(NAME, db_path)?;
    crate::tx::snapshot(&db_path);
    let mut db = rusqlite::Connection::open(&db_path).map_err(|e| {
        coded_io(
            NAME,
            format!("{NAME}: cannot open the database: {e}"),
            "check that the database path is writable and not locked by another process",
        )
    })?;
    let transaction = db.transaction().map_err(|e| {
        coded_io(
            NAME,
            format!("{NAME}: cannot begin the import transaction: {e}"),
            "no rows were written; check that the database is not locked or corrupt",
        )
    })?;
    let sql_error = |e: rusqlite::Error| {
        crate::safety::arg_err(&format!(
            "{NAME}: SQLite rejected import: {e}; no rows committed"
        ))
    };
    let definitions = columns
        .iter()
        .map(|name| format!("{name} TEXT"))
        .collect::<Vec<_>>()
        .join(", ");
    transaction
        .execute_batch(&format!(
            "CREATE TABLE IF NOT EXISTS {table} ({definitions})"
        ))
        .map_err(sql_error)?;
    let placeholders = vec!["?"; columns.len()].join(", ");
    {
        let mut statement = transaction
            .prepare(&format!(
                "INSERT INTO {table} ({}) VALUES ({placeholders})",
                columns.join(", ")
            ))
            .map_err(sql_error)?;
        for row in rows {
            statement
                .execute(rusqlite::params_from_iter(row.iter()))
                .map_err(sql_error)?;
        }
    }
    transaction
        .commit()
        .map_err(|e| {
            coded_io(
                NAME,
                format!("{NAME}: committing import: {e}"),
                "the import was rolled back and no rows were committed; check that the database is writable and has space",
            )
        })?;
    Ok(Value::Bool(true))
}

fn bi_db_sqlite_export_csv(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_export_csv",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table_or_query = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_export_csv",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let output_path = args
        .get(2)
        .map(|v| expect_string("db_sqlite_to_csv", v))
        .transpose()?;

    // A leading SELECT means the caller passed a query and owns it, the same
    // contract as the WHERE clause in `db_sqlite_delete`. Anything else is a
    // table *name*, so it is an identifier and is validated — without this it
    // was interpolated raw, and the sqlite3 CLI runs every `;`-separated
    // statement it is handed.
    let query = if table_or_query.to_uppercase().starts_with("SELECT") {
        table_or_query
    } else {
        format!(
            "SELECT * FROM {}",
            crate::safety::sql_identifier("db_sqlite_export_csv", &table_or_query)?
        )
    };

    crate::safety::reject_sqlite_dot_command("db_sqlite_export_csv", &query)?;
    crate::safety::reject_option_like("db_sqlite_export_csv", std::slice::from_ref(&db_path))?;
    let mut cmd = std::process::Command::new("sqlite3");
    cmd.args(["-header", "-csv", &db_path, &query]);
    let output = bounded_cmd_output("db_sqlite_export_csv", "sqlite3", cmd, TOOL_DEADLINE_SECS)?;

    if output.status.success() {
        let csv = String::from_utf8_lossy(&output.stdout).to_string();
        if let Some(path) = output_path {
            std::fs::write(path, &csv)
                .map_err(|e| crate::safety::fs_error("db_sqlite_to_csv", path, &e))?;
            return Ok(Value::Str(path.to_string()));
        }
        return Ok(Value::Str(csv));
    }
    Err(crate::safety::tool_failed(
        "db_sqlite_to_csv",
        "sqlite3",
        output.status.code(),
        &String::from_utf8_lossy(&output.stderr),
    ))
}

fn bi_db_kv_get(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let store_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => ".aether_kv.db".to_string(),
    };
    let key = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_get",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    // A store that does not exist yet holds no value; asking must not
    // create one.
    if !sqlite_db_exists(&store_path) {
        return Ok(Value::Null);
    }
    bi_db_sqlite_query(
        vec![
            Value::Str(store_path),
            Value::Str(format!(
                "SELECT value FROM kv WHERE key = {}",
                crate::safety::sql_literal("db_kv_get", &key)?
            )),
        ],
        None,
    )
    .map(|v| match v {
        Value::Array(arr) if !arr.is_empty() => {
            if let Value::Record(rec) = &arr[0] {
                rec.get("value").cloned().unwrap_or(Value::Null)
            } else {
                Value::Null
            }
        }
        _ => Value::Null,
    })
}

fn bi_db_kv_set(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let store_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_set",
                "store: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let key = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_set",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let value = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        Some(v) => format!("{:?}", v),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_set",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    // Validate literals before any file can be created or changed.
    let query = format!(
        "INSERT OR REPLACE INTO kv (key, value) VALUES ({}, {})",
        crate::safety::sql_literal("db_kv_set", &key)?,
        crate::safety::sql_literal("db_kv_set", &value)?
    );
    // Ensure table exists, propagating its failure.
    bi_db_sqlite_exec(
        vec![
            Value::Str(store_path.clone()),
            Value::Str(
                "CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT)".to_string(),
            ),
        ],
        None,
    )?;

    bi_db_sqlite_exec(vec![Value::Str(store_path), Value::Str(query)], None)
}

fn bi_db_kv_delete(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let store_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_delete",
                "store: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let key = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_kv_delete",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "db_kv_delete",
        effect: crate::safety::Effect::Destructive,
        what: "db_delete",
        targets: vec![format!("{}:{}", store_path, key)],
        blast_radius: serde_json::json!({ "store": store_path.clone(), "key": key.clone() }),
        reversible: false,
        fs_paths: false,
    })?;

    bi_db_sqlite_exec(
        vec![
            Value::Str(store_path),
            Value::Str(format!(
                "DELETE FROM kv WHERE key = {}",
                crate::safety::sql_literal("db_kv_delete", &key)?
            )),
        ],
        None,
    )
}

fn bi_db_kv_keys(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let store_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => ".aether_kv.db".to_string(),
    };

    if !sqlite_db_exists(&store_path) {
        return Ok(Value::Array(vec![]));
    }
    bi_db_sqlite_query(
        vec![
            Value::Str(store_path),
            Value::Str("SELECT key FROM kv".to_string()),
        ],
        None,
    )
    .map(|v| match v {
        Value::Array(arr) => Value::Array(
            arr.iter()
                .filter_map(|r| match r {
                    Value::Record(rec) => rec.get("key").cloned(),
                    _ => None,
                })
                .collect(),
        ),
        _ => Value::Array(vec![]),
    })
}

/// Deadline for one `db_json_query` run of jq over a file.
const DB_JQ_DEADLINE_SECS: u64 = 30;
/// The most output one `db_json_query` may produce. More is E_BUDGET_EXCEEDED.
const DB_JQ_MAX_OUTPUT: usize = 16 * 1024 * 1024;

fn bi_db_json_query(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let json_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_json_query",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let jq_filter = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => ".".to_string(),
    };
    // Both go to jq positionally, so a leading `-` would be read as an option.
    crate::safety::reject_option_like("db_json_query", &[json_path.clone(), jq_filter.clone()])?;

    // jq reads the file itself and gets no stdin, so nothing is written to it
    // here. The run has a deadline and an output cap like every other tool run.
    let output = run_output(
        "db_json_query",
        "jq",
        "jq",
        &[jq_filter.as_str(), json_path.as_str()],
        |_| {},
        None,
        DB_JQ_DEADLINE_SECS,
        DB_JQ_MAX_OUTPUT,
    )?;

    if output.status.success() {
        let json_str = String::from_utf8_lossy(&output.stdout);
        if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
            return Ok(json_to_value(json));
        }
        return Ok(Value::Str(json_str.trim().to_string()));
    }

    // This "fell back" to reading the file and returning all of it, so a
    // filter jq rejected answered with the whole document, filter ignored.
    Err(crate::safety::tool_failed(
        "db_json_query",
        "jq",
        output.status.code(),
        &String::from_utf8_lossy(&output.stderr),
    ))
}

fn bi_db_csv_query(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let csv_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_csv_query",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    let content = read_text_capped("db_csv_query", &csv_path)?;
    let mut reader = csv::ReaderBuilder::new()
        .trim(csv::Trim::All)
        .from_reader(content.as_bytes());
    let csv_error = |e: csv::Error| {
        crate::safety::bad_arg("db_csv_query", "CSV with equal-length rows", &e.to_string())
    };
    let headers = reader.headers().map_err(csv_error)?.clone();
    let rows = reader
        .records()
        .map(|record| {
            let record = record.map_err(csv_error)?;
            Ok(Value::Record(
                headers
                    .iter()
                    .zip(record.iter())
                    .map(|(header, value)| (header.to_string(), Value::Str(value.to_string())))
                    .collect(),
            ))
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(Value::Array(rows))
}

fn bi_db_json_to_csv(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // Every failure here answered "": invalid JSON, a non-array, a first row
    // that was not a record. Worse, cells that were not strings were written
    // with Rust's Debug format, so 5 became `Int(5)`; columns came from the
    // first record only, so a field first seen later was dropped; and a row
    // that was not a record was skipped.
    const B: &str = "db_json_to_csv";
    let rows = match args.first() {
        Some(Value::Array(arr)) => arr.clone(),
        Some(Value::Str(s)) => {
            let json = serde_json::from_str::<serde_json::Value>(s)
                .map_err(|e| crate::safety::bad_arg(B, "valid JSON", &e.to_string()))?;
            match json_to_value(json) {
                Value::Array(arr) => arr,
                other => {
                    return Err(crate::safety::bad_arg(
                        B,
                        "a JSON array of objects",
                        other.type_name(),
                    ))
                }
            }
        }
        other => {
            return Err(crate::safety::bad_arg(
                B,
                "an array of records, or its JSON text",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    if rows.is_empty() {
        return Ok(Value::Str(String::new()));
    }

    let mut headers = std::collections::BTreeSet::new();
    for row in &rows {
        match row {
            Value::Record(rec) => headers.extend(rec.keys().cloned()),
            other => {
                return Err(crate::safety::bad_arg(
                    B,
                    "every row a record",
                    other.type_name(),
                ))
            }
        }
    }
    let headers: Vec<String> = headers.into_iter().collect();

    fn cell(v: Option<&Value>) -> String {
        let raw = match v {
            None | Some(Value::Null) => return String::new(),
            Some(Value::Str(s)) => s.clone(),
            Some(v @ (Value::Int(_) | Value::Float(_) | Value::Bool(_))) => v.to_display_string(),
            Some(other) => value_to_json(other.clone()).to_string(),
        };
        if raw.contains([',', '"', '\n', '\r']) {
            format!("\"{}\"", raw.replace('"', "\"\""))
        } else {
            raw
        }
    }

    let mut csv = headers
        .iter()
        .map(|h| cell(Some(&Value::Str(h.clone()))))
        .collect::<Vec<_>>()
        .join(",");
    csv.push('\n');
    for row in &rows {
        let Value::Record(rec) = row else {
            unreachable!("checked above")
        };
        let line: Vec<String> = headers.iter().map(|h| cell(rec.get(h))).collect();
        csv.push_str(&line.join(","));
        csv.push('\n');
    }
    Ok(Value::Str(csv))
}

fn bi_db_csv_to_json(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    bi_db_csv_query(args, None)
}

// ============================================================================
// Missing Clipboard & Input implementations
// ============================================================================

/// Most image data `clipboard_get_image` returns or `clipboard_set_image` copies.
const CLIPBOARD_IMAGE_MAX: usize = 32 * 1024 * 1024;
/// The image types the clipboard image builtins carry, in the order
/// `clipboard_get_image` prefers them.
#[cfg(target_os = "linux")]
const CLIPBOARD_IMAGE_TYPES: [&str; 5] = [
    "image/png",
    "image/jpeg",
    "image/gif",
    "image/bmp",
    "image/webp",
];

/// The MIME type of an image, from its first bytes, if it is one the
/// clipboard image builtins carry.
fn image_mime_of(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        Some("image/png")
    } else if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
        Some("image/jpeg")
    } else if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        Some("image/gif")
    } else if bytes.starts_with(b"BM") && bytes.len() > 14 {
        Some("image/bmp")
    } else if bytes.len() > 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some("image/webp")
    } else {
        None
    }
}

/// The targets (X11) or MIME types (Wayland) the Linux clipboard offers, one
/// per entry; empty when nothing owns the clipboard. With no display it is
/// E_NO_UI. xsel cannot list targets or carry images, so only xclip serves
/// X11 here.
#[cfg(target_os = "linux")]
fn linux_clipboard_offers(name: &str) -> Result<Vec<String>> {
    if !display_env_set("DISPLAY") && !display_env_set("WAYLAND_DISPLAY") {
        return Err(crate::safety::no_ui(name));
    }
    let lines = |out: &std::process::Output| {
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect::<Vec<_>>()
    };
    if display_env_set("WAYLAND_DISPLAY") {
        let out = linux_clipboard_tool(name, "wl-paste", &["--list-types"])?.ok_or_else(|| {
            crate::safety::tool_missing(
                name,
                "wl-paste",
                "install wl-clipboard to use clipboard images",
            )
        })?;
        if out.status.success() {
            return Ok(lines(&out));
        }
        if out.status.code() == Some(1)
            && String::from_utf8_lossy(&out.stderr).contains("Nothing is copied")
        {
            return Ok(Vec::new());
        }
        return Err(crate::safety::tool_failed(
            name,
            "wl-paste",
            out.status.code(),
            &gui_stderr_tail(&out),
        ));
    }
    let out = linux_clipboard_tool(
        name,
        "xclip",
        &["-selection", "clipboard", "-o", "-t", "TARGETS"],
    )?
    .ok_or_else(|| {
        crate::safety::tool_missing(
            name,
            "xclip",
            "install xclip to use clipboard images; xsel cannot carry them",
        )
    })?;
    if out.status.success() {
        return Ok(lines(&out));
    }
    if String::from_utf8_lossy(&out.stderr).contains("not available") {
        return Ok(Vec::new());
    }
    Err(crate::safety::tool_failed(
        name,
        "xclip",
        out.status.code(),
        &gui_stderr_tail(&out),
    ))
}

fn bi_clipboard_get_image(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "clipboard_get_image";
    no_args_or_input(NAME, &args, &input)?;
    crate::safety::clipboard_read_gate(NAME)?;
    #[cfg(target_os = "linux")]
    {
        let offers = linux_clipboard_offers(NAME)?;
        let Some(mime) = CLIPBOARD_IMAGE_TYPES
            .iter()
            .find(|t| offers.iter().any(|o| o.eq_ignore_ascii_case(t)))
        else {
            return Err(crate::safety::not_found(
                NAME,
                "image on the clipboard",
                "the clipboard holds no PNG, JPEG, GIF, BMP or WEBP image",
            ));
        };
        let (tool, read_args): (&str, Vec<&str>) = if display_env_set("WAYLAND_DISPLAY") {
            ("wl-paste", vec!["--no-newline", "--type", mime])
        } else {
            ("xclip", vec!["-selection", "clipboard", "-o", "-t", mime])
        };
        let out = linux_clipboard_tool(NAME, tool, &read_args)?.ok_or_else(|| {
            crate::safety::tool_missing(NAME, tool, "install it to read clipboard images")
        })?;
        if !out.status.success() {
            return Err(crate::safety::tool_failed(
                NAME,
                tool,
                out.status.code(),
                &gui_stderr_tail(&out),
            ));
        }
        if out.stdout.len() > CLIPBOARD_IMAGE_MAX {
            return Err(crate::safety::budget_exceeded(
                NAME,
                format!(
                    "the clipboard image is {} bytes, over the {CLIPBOARD_IMAGE_MAX}-byte limit",
                    out.stdout.len()
                ),
                "copy a smaller image; this shell returns no truncated image",
            ));
        }
        if out.stdout.is_empty() {
            return Err(crate::safety::not_found(
                NAME,
                "image on the clipboard",
                "the clipboard offered an image but gave no data; copy it again",
            ));
        }
        use base64::Engine;
        let mut rec = BTreeMap::new();
        rec.insert("mime".to_string(), Value::Str(mime.to_string()));
        rec.insert("bytes".to_string(), Value::Int(out.stdout.len() as i64));
        rec.insert(
            "base64".to_string(),
            Value::Str(base64::engine::general_purpose::STANDARD.encode(&out.stdout)),
        );
        Ok(Value::Record(rec))
    }
    #[cfg(not(target_os = "linux"))]
    {
        Err(crate::safety::unimplemented(
            NAME,
            "reading an image from the clipboard is implemented on Linux only; NOTHING WAS READ",
            "use a platform clipboard tool",
        ))
    }
}

/// Copy an image file to the clipboard. The argument, the file and its type
/// are checked before the display, so every refusal but E_NO_UI is the same
/// on every OS.
fn bi_clipboard_set_image(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "clipboard_set_image";
    refuse_piped_input(NAME, &input)?;
    let path = gui_text(
        NAME,
        "image path",
        gui_required(NAME, &args, 0, "an image path")?,
        GUI_FIELD_MAX_BYTES,
        false,
    )?;
    if args.len() > 1 {
        return Err(crate::safety::bad_arg(
            NAME,
            "one argument: the image path",
            &format!("{} arguments", args.len()),
        ));
    }
    if !std::path::Path::new(&path).exists() {
        return Err(crate::safety::not_found(NAME, "image file", &path));
    }
    let validated = validate_read_path(&path)?;
    let size = fs::metadata(&validated)
        .map_err(|e| crate::safety::fs_error(NAME, &path, &e))?
        .len();
    if size > CLIPBOARD_IMAGE_MAX as u64 {
        return Err(crate::safety::budget_exceeded(
            NAME,
            format!("{path} is {size} bytes, over the {CLIPBOARD_IMAGE_MAX}-byte limit"),
            "copy a smaller image",
        ));
    }
    let bytes = read_bytes_capped(NAME, &validated)?;
    let Some(mime) = image_mime_of(&bytes) else {
        return Err(crate::safety::bad_arg(
            NAME,
            "a PNG, JPEG, GIF, BMP or WEBP image",
            &format!("{path}, which is none of those"),
        ));
    };
    #[cfg(target_os = "linux")]
    {
        linux_clipboard_set_image(NAME, mime, bytes)?;
        Ok(Value::Bool(true))
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = (mime, bytes);
        Err(crate::safety::unimplemented(
            NAME,
            "writing an image to the clipboard is implemented on Linux only; NOTHING WAS COPIED",
            "use a platform clipboard tool",
        ))
    }
}

/// Hand `input` to a clipboard helper on its stdin and wait for it, with a
/// deadline. `child` must have been spawned with a piped stdin. Its stdout and
/// stderr are left however the caller set them and are never read here: a
/// clipboard holder forked by xclip keeps the inherited handles open, so
/// waiting on them would wait for the holder as well.
///
/// The write runs on its own thread and the pipe is closed when it finishes,
/// so a helper that stops reading cannot block the caller. Past `deadline_secs`
/// the child is killed and reaped, and the call is a coded budget error. A
/// BrokenPipe means the helper exited before reading everything. That is not an
/// error here: the exit status decides, and the caller judges it as before.
/// Any other write failure is a coded tool error.
#[cfg(any(target_os = "macos", target_os = "linux", test))]
fn feed_stdin_and_wait(
    builtin: &str,
    tool: &str,
    mut child: std::process::Child,
    input: Vec<u8>,
    deadline_secs: u64,
) -> Result<std::process::ExitStatus> {
    use std::io::Write;
    use std::sync::mpsc;
    use std::time::{Duration, Instant};
    let Some(mut stdin) = child.stdin.take() else {
        let _ = child.kill();
        let _ = child.wait();
        return Err(crate::safety::tool_failed(
            builtin,
            tool,
            None,
            "its stdin was not piped",
        ));
    };
    let (tx, rx) = mpsc::channel::<std::io::Result<()>>();
    std::thread::spawn(move || {
        let written = stdin.write_all(&input);
        // Dropping the pipe here is what lets the helper see end of input.
        drop(stdin);
        let _ = tx.send(written);
    });
    let deadline = Instant::now() + Duration::from_secs(deadline_secs);
    let mut write: Option<std::io::Result<()>> = None;
    let status = loop {
        if write.is_none() {
            write = rx.try_recv().ok();
        }
        if let Some(Err(e)) = &write {
            if e.kind() != std::io::ErrorKind::BrokenPipe {
                let message = format!("writing its input failed: {e}");
                let _ = child.kill();
                let _ = child.wait();
                return Err(crate::safety::tool_failed(builtin, tool, None, &message));
            }
        }
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(20));
            }
            Ok(None) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(crate::safety::budget_exceeded(
                    builtin,
                    format!("`{tool}` did not finish within {deadline_secs} s and was stopped"),
                    "the clipboard may be unchanged; check it, then retry",
                ));
            }
            Err(e) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(crate::safety::tool_failed(
                    builtin,
                    tool,
                    None,
                    &e.to_string(),
                ));
            }
        }
    };
    if write.is_none() {
        // The helper has exited; the write has at most a moment left to report.
        write = rx.recv_timeout(Duration::from_millis(200)).ok();
    }
    match write {
        Some(Err(e)) if e.kind() != std::io::ErrorKind::BrokenPipe => {
            Err(crate::safety::tool_failed(
                builtin,
                tool,
                None,
                &format!("writing its input failed: {e}"),
            ))
        }
        _ => Ok(status),
    }
}

/// Hand `bytes` to xclip or wl-copy as `mime`.
///
/// Not through bounded_cmd_output or run_tree, on purpose. Both tools fork a
/// holder that owns the selection after the command returns, and run_tree puts
/// its child in a new process group and kills that group when a pipe outlives
/// the child: it would kill the holder and empty the clipboard again. So the
/// tool keeps this shell's process group, gets null stdout and stderr (the
/// holder keeps no pipe of ours), and only the direct child is waited on, with
/// a deadline, through feed_stdin_and_wait.
#[cfg(target_os = "linux")]
fn linux_clipboard_set_image(name: &str, mime: &str, bytes: Vec<u8>) -> Result<()> {
    use std::process::Stdio;
    if !display_env_set("DISPLAY") && !display_env_set("WAYLAND_DISPLAY") {
        return Err(crate::safety::no_ui(name));
    }
    let (tool, tool_args): (&str, Vec<&str>) = if display_env_set("WAYLAND_DISPLAY") {
        ("wl-copy", vec!["--type", mime])
    } else {
        ("xclip", vec!["-selection", "clipboard", "-t", mime, "-i"])
    };
    let child = std::process::Command::new(tool)
        .args(&tool_args)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|e| crate::safety::spawn_error(name, tool, &e))?;
    let status = feed_stdin_and_wait(name, tool, child, bytes, TOOL_DEADLINE_SECS)?;
    if status.success() {
        return Ok(());
    }
    Err(crate::safety::tool_failed(
        name,
        tool,
        status.code(),
        "it did not take the image",
    ))
}

fn bi_clipboard_history(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "clipboard_history";
    no_args_or_input(NAME, &args, &input)?;
    crate::safety::clipboard_read_gate(NAME)?;
    #[cfg(target_os = "windows")]
    {
        let mut cmd = std::process::Command::new("powershell");
        cmd.args([
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            "Get-ClipboardHistory | Select-Object -First 10 | ForEach-Object { $_.Text }",
        ]);
        let output = bounded_cmd_output(NAME, "powershell", cmd, TOOL_DEADLINE_SECS)?;
        if !output.status.success() {
            // Previously answered a String explaining the requirement, which
            // read as a list of one entry. The requirement is an error.
            return Err(crate::safety::tool_failed(
                NAME,
                "Get-ClipboardHistory",
                output.status.code(),
                &gui_stderr_tail(&output),
            ));
        }
        let text = String::from_utf8_lossy(&output.stdout).into_owned();
        Ok(Value::Array(
            text.lines().map(|l| Value::Str(l.to_string())).collect(),
        ))
    }
    #[cfg(not(target_os = "windows"))]
    {
        Err(crate::safety::unimplemented(
            NAME,
            "clipboard history is implemented on Windows 10 and later only; NOTHING WAS READ",
            "clipboard() reads the current clipboard text",
        ))
    }
}

/// `input_read_char(timeout_ms?)`: one keypress from the terminal, answered as
/// a String. Needs stdin and stderr to be terminals; otherwise it refuses with
/// E_NO_UI without reading anything, so piped stdin is left for the next read.
/// Ctrl+C is refused (E_POLICY_DENY), not answered: raw mode delivers it as a
/// key, and answering it as a character would hide that the user cancelled.
fn bi_input_read_char(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const BUILTIN: &str = "input_read_char";
    const MAX_MS: i64 = 3_600_000;
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "no pipeline input",
            "a piped value",
        ));
    }
    let timeout = match args.as_slice() {
        [] => None,
        [Value::Int(ms)] if (1..=MAX_MS).contains(ms) => {
            Some(std::time::Duration::from_millis(*ms as u64))
        }
        [other] => {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                "an Int timeout_ms from 1 through 3600000",
                &format!("{other:?}"),
            ))
        }
        more => {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                "input_read_char(timeout_ms?: Int)",
                &format!("{} arguments", more.len()),
            ))
        }
    };
    use std::io::IsTerminal;
    if !(std::io::stdin().is_terminal() && std::io::stderr().is_terminal()) {
        return Err(crate::safety::no_ui(BUILTIN));
    }
    read_key_native(BUILTIN, timeout)
}

#[cfg(feature = "native")]
fn read_key_native(builtin: &str, timeout: Option<std::time::Duration>) -> Result<Value> {
    use crossterm::event::{self, Event, KeyCode, KeyEventKind, KeyModifiers};
    use crossterm::terminal;

    let io = |e: std::io::Error| crate::safety::fs_error(builtin, "the terminal", &e);

    // Same discipline as line_editor::terminal::read_line: raw mode is
    // restored on every path, including a failed read, before the result
    // is returned.
    terminal::enable_raw_mode().map_err(io)?;
    let outcome = (|| -> Result<Option<String>> {
        let deadline = timeout.map(|t| std::time::Instant::now() + t);
        loop {
            if let Some(deadline) = deadline {
                let remaining = deadline.saturating_duration_since(std::time::Instant::now());
                if remaining.is_zero() || !event::poll(remaining).map_err(io)? {
                    return Ok(None);
                }
            }
            let Event::Key(key) = event::read().map_err(io)? else {
                continue;
            };
            if key.kind != KeyEventKind::Press {
                continue;
            }
            if let KeyCode::Char('c' | 'C') = key.code {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    return Err(crate::safety::policy_deny(
                        builtin,
                        format!(
                            "{builtin}: Ctrl+C was pressed; the key was cancelled, not answered"
                        ),
                        "the user cancelled this read; ask again only if they want to answer",
                    ));
                }
            }
            // Keys with no name here (modifier-only presses, media keys) are
            // skipped, so the answer is always a key an agent can match.
            if let Some(name) = key_name(key.code) {
                return Ok(Some(name));
            }
        }
    })();
    let restored = terminal::disable_raw_mode();
    let answer = outcome?;
    restored.map_err(io)?;
    Ok(answer.map_or(Value::Null, Value::Str))
}

#[cfg(feature = "native")]
fn key_name(code: crossterm::event::KeyCode) -> Option<String> {
    use crossterm::event::KeyCode;
    Some(match code {
        KeyCode::Char(c) => c.to_string(),
        KeyCode::Enter => "Enter".to_string(),
        KeyCode::Esc => "Esc".to_string(),
        KeyCode::Tab => "Tab".to_string(),
        KeyCode::BackTab => "BackTab".to_string(),
        KeyCode::Backspace => "Backspace".to_string(),
        KeyCode::Delete => "Delete".to_string(),
        KeyCode::Insert => "Insert".to_string(),
        KeyCode::Home => "Home".to_string(),
        KeyCode::End => "End".to_string(),
        KeyCode::PageUp => "PageUp".to_string(),
        KeyCode::PageDown => "PageDown".to_string(),
        KeyCode::Up => "Up".to_string(),
        KeyCode::Down => "Down".to_string(),
        KeyCode::Left => "Left".to_string(),
        KeyCode::Right => "Right".to_string(),
        KeyCode::F(n) => format!("F{n}"),
        _ => return None,
    })
}

#[cfg(not(feature = "native"))]
fn read_key_native(builtin: &str, timeout: Option<std::time::Duration>) -> Result<Value> {
    let _ = timeout;
    Err(crate::safety::unimplemented(
        builtin,
        "reading a keypress needs the `native` feature (crossterm); NOTHING WAS READ",
        "build with default features, or use `ae --tui`",
    ))
}

/// `input_spinner(label, duration_ms)`: animates `| / - \` on stderr for
/// `duration_ms`, then clears its line and answers `{label, duration_ms}`.
/// When stderr is not a terminal nothing is drawn (no CR or escape bytes reach
/// a log), but the call still waits the full duration. Control characters in
/// the label are drawn as `?`; the answer carries the label unchanged.
fn bi_input_spinner(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const BUILTIN: &str = "input_spinner";
    const MAX_MS: i64 = 600_000;
    const MAX_LABEL_BYTES: usize = 1024;
    const FRAME_MS: u64 = 100;
    const FRAMES: [char; 4] = ['|', '/', '-', '\\'];
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "no pipeline input",
            "a piped value",
        ));
    }
    let [label, duration] = args.as_slice() else {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "input_spinner(label: String, duration_ms: Int)",
            &format!("{} arguments", args.len()),
        ));
    };
    let Value::Str(label) = label else {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "a String label",
            &format!("{label:?}"),
        ));
    };
    if label.len() > MAX_LABEL_BYTES {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "a label of at most 1024 bytes",
            &format!("{} bytes", label.len()),
        ));
    }
    let ms = match duration {
        Value::Int(ms) if (1..=MAX_MS).contains(ms) => *ms as u64,
        other => {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                "an Int duration_ms from 1 through 600000",
                &format!("{other:?}"),
            ))
        }
    };
    use std::io::IsTerminal;
    let draw = std::io::stderr().is_terminal();
    let shown: String = label
        .chars()
        .map(|c| if c.is_control() { '?' } else { c })
        .collect();
    let total = std::time::Duration::from_millis(ms);
    let start = std::time::Instant::now();
    let mut frame = 0usize;
    loop {
        let elapsed = start.elapsed();
        if elapsed >= total {
            break;
        }
        if draw {
            eprint!("\r{} {}", FRAMES[frame % FRAMES.len()], shown);
        }
        frame += 1;
        std::thread::sleep((total - elapsed).min(std::time::Duration::from_millis(FRAME_MS)));
    }
    if draw {
        eprint!("\r{}\r", " ".repeat(shown.chars().count() + 2));
    }
    let mut rec = std::collections::BTreeMap::new();
    rec.insert("label".to_string(), Value::Str(label.clone()));
    rec.insert("duration_ms".to_string(), Value::Int(ms as i64));
    Ok(Value::Record(rec))
}

/// `input_progress(current, total, label?)`: draws one progress line on stderr
/// and answers `{current, total, percent}`. Nothing is kept between calls.
fn bi_input_progress(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const BUILTIN: &str = "input_progress";
    const WIDTH: usize = 30;
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "no pipeline input",
            "a piped value",
        ));
    }
    if !(2..=3).contains(&args.len()) {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "input_progress(current: Number, total: Number, label?: String)",
            &format!("{} arguments", args.len()),
        ));
    }
    let number = |v: &Value, what: &str| -> Result<f64> {
        let n = match v {
            Value::Int(i) => *i as f64,
            Value::Float(f) => *f,
            other => {
                return Err(crate::safety::bad_arg(
                    BUILTIN,
                    &format!("a Number {what}"),
                    &format!("{other:?}"),
                ))
            }
        };
        if !n.is_finite() {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                &format!("a finite Number {what}"),
                &format!("{n}"),
            ));
        }
        Ok(n)
    };
    let current_value = &args[0];
    let total_value = &args[1];
    let current = number(current_value, "current")?;
    let total = number(total_value, "total")?;
    if total <= 0.0 {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "a total greater than 0",
            &format!("{total}"),
        ));
    }
    if current < 0.0 || current > total {
        return Err(crate::safety::bad_arg(
            BUILTIN,
            "0 <= current <= total",
            &format!("current {current} of total {total}"),
        ));
    }
    let label = match args.get(2) {
        None => None,
        Some(Value::Str(s)) => Some(s.as_str()),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                BUILTIN,
                "a String label",
                &format!("{other:?}"),
            ))
        }
    };
    let fraction = (current / total).clamp(0.0, 1.0);
    let percent = (fraction * 100.0).floor() as i64;
    let filled = ((fraction * WIDTH as f64).floor() as usize).min(WIDTH);
    let bar = format!("{}{}", "#".repeat(filled), "-".repeat(WIDTH - filled));
    let prefix = match label {
        Some(text) => format!("{text} "),
        None => String::new(),
    };
    let finished = current == total;
    eprint!("\r{prefix}[{bar}] {percent}%");
    if finished {
        eprintln!();
    }
    let mut record = std::collections::BTreeMap::new();
    record.insert("current".to_string(), current_value.clone());
    record.insert("total".to_string(), total_value.clone());
    record.insert("percent".to_string(), Value::Int(percent));
    Ok(Value::Record(record))
}

/// Most fields one `input_form` asks about.
const INPUT_FORM_MAX_FIELDS: usize = 50;
/// Longest label, default or choice text a line prompt accepts.
const INPUT_TEXT_MAX_BYTES: usize = 1024;
/// Invalid answers a line prompt tolerates before it refuses.
const INPUT_MAX_ATTEMPTS: usize = 3;
/// Most rows one `input_table` lists.
const INPUT_TABLE_MAX_ROWS: usize = 1000;
/// Columns one `input_table` shows; the chosen row still carries every key.
const INPUT_TABLE_MAX_COLUMNS: usize = 16;
/// Characters of one table cell shown before it is cut with `...`.
const INPUT_TABLE_CELL_CHARS: usize = 40;
/// Most choices one `input_autocomplete` accepts.
const INPUT_AUTOCOMPLETE_MAX_CHOICES: usize = 10000;
/// Matches one `input_autocomplete` lists when a prefix is ambiguous.
const INPUT_AUTOCOMPLETE_LIST: usize = 20;
/// Answers one `input_autocomplete` accepts before it refuses.
const INPUT_AUTOCOMPLETE_MAX_ATTEMPTS: usize = 5;

/// A form field name: `^[A-Za-z_][A-Za-z0-9_]{0,63}$`.
fn is_form_field_name(name: &str) -> bool {
    let bytes = name.as_bytes();
    matches!(bytes.first(), Some(b) if b.is_ascii_alphabetic() || *b == b'_')
        && bytes.len() <= 64
        && bytes
            .iter()
            .all(|b| b.is_ascii_alphanumeric() || *b == b'_')
}

/// One table cell or column title: control characters become spaces, and text
/// over the cell width is cut with `...`.
fn input_table_cell(text: &str) -> String {
    let flat: String = text
        .chars()
        .map(|c| if c.is_control() { ' ' } else { c })
        .collect();
    if flat.chars().count() <= INPUT_TABLE_CELL_CHARS {
        return flat;
    }
    let mut cut: String = flat.chars().take(INPUT_TABLE_CELL_CHARS - 3).collect();
    cut.push_str("...");
    cut
}

/// A form of named fields, asked one line each. Every field is validated
/// before the first prompt, so a malformed form asks nothing.
fn bi_input_form(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_form";
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            NAME,
            "a direct call; the answers come from the terminal, not piped input",
            "a piped value",
        ));
    }
    let [fields] = args.as_slice() else {
        return Err(crate::safety::bad_arg(
            NAME,
            "fields: Array of field Records",
            &format!("{} argument(s)", args.len()),
        ));
    };
    let Value::Array(specs) = fields else {
        return Err(crate::safety::bad_arg(
            NAME,
            "fields: Array of field Records",
            fields.type_name(),
        ));
    };
    if specs.is_empty() || specs.len() > INPUT_FORM_MAX_FIELDS {
        return Err(crate::safety::bad_arg(
            NAME,
            &format!("1..={INPUT_FORM_MAX_FIELDS} fields"),
            &format!("{} field(s)", specs.len()),
        ));
    }

    // (name, label, default, required), validated in full before any prompt.
    let mut checked: Vec<(String, String, Option<String>, bool)> = Vec::with_capacity(specs.len());
    let mut seen = std::collections::BTreeSet::new();
    for (i, spec) in specs.iter().enumerate() {
        let position = i + 1;
        let Value::Record(rec) = spec else {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("field {position}: a Record"),
                spec.type_name(),
            ));
        };
        if let Some(key) = rec
            .keys()
            .find(|k| !matches!(k.as_str(), "name" | "label" | "default" | "required"))
        {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("field {position}: keys name, label, default, required"),
                &format!("unknown key {key:?}"),
            ));
        }
        let name = match rec.get("name") {
            Some(Value::Str(s)) if is_form_field_name(s) => s.clone(),
            Some(Value::Str(s)) => {
                return Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: name matching ^[A-Za-z_][A-Za-z0-9_]{{0,63}}$"),
                    &format!("{s:?}"),
                ))
            }
            Some(other) => {
                return Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: name as a String"),
                    other.type_name(),
                ))
            }
            None => {
                return Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: a name"),
                    "no name",
                ))
            }
        };
        if !seen.insert(name.clone()) {
            return Err(crate::safety::bad_arg(
                NAME,
                "field names that are unique",
                &format!("duplicate {name:?}"),
            ));
        }
        let text = |key: &str| -> Result<Option<String>> {
            match rec.get(key) {
                None => Ok(None),
                Some(Value::Str(s)) if s.len() <= INPUT_TEXT_MAX_BYTES => Ok(Some(s.clone())),
                Some(Value::Str(s)) => Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: {key} of at most {INPUT_TEXT_MAX_BYTES} bytes"),
                    &format!("{} bytes", s.len()),
                )),
                Some(other) => Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: {key} as a String"),
                    other.type_name(),
                )),
            }
        };
        let label = text("label")?
            .filter(|l| !l.is_empty())
            .unwrap_or_else(|| name.clone());
        let default = text("default")?;
        let required = match rec.get("required") {
            None => false,
            Some(Value::Bool(b)) => *b,
            Some(other) => {
                return Err(crate::safety::bad_arg(
                    NAME,
                    &format!("field {position}: required as a Bool"),
                    other.type_name(),
                ))
            }
        };
        checked.push((name, label, default, required));
    }

    let mut answers = BTreeMap::new();
    for (name, label, default, required) in &checked {
        let prompt = match default {
            Some(d) => format!("{label} ({d}): "),
            None => format!("{label}: "),
        };
        let mut empty_answers = 0usize;
        let answer = loop {
            let raw = read_answer(NAME, &prompt)?;
            if !raw.is_empty() {
                break raw;
            }
            if let Some(d) = default {
                break d.clone();
            }
            if !required {
                break String::new();
            }
            empty_answers += 1;
            if empty_answers == INPUT_MAX_ATTEMPTS {
                return Err(crate::safety::bad_arg(
                    NAME,
                    &format!("a non-empty answer for required field `{name}`"),
                    &format!("{empty_answers} empty answers"),
                ));
            }
            eprintln!("{NAME}: `{name}` is required");
        };
        answers.insert(name.clone(), Value::Str(answer));
    }
    Ok(Value::Record(answers))
}

/// Lists rows as a numbered table on stderr, then answers the row the user
/// picks, as it was given.
fn bi_input_table(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_table";
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            NAME,
            "a direct call; the choice comes from the terminal, not piped input",
            "a piped value",
        ));
    }
    if args.is_empty() || args.len() > 2 {
        return Err(crate::safety::bad_arg(
            NAME,
            "rows: Array of Records, prompt?: String",
            &format!("{} argument(s)", args.len()),
        ));
    }
    let Value::Array(rows) = &args[0] else {
        return Err(crate::safety::bad_arg(
            NAME,
            "rows: Array of Records",
            args[0].type_name(),
        ));
    };
    let prompt = match args.get(1) {
        None => None,
        Some(Value::Str(p)) => Some(p.clone()),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                NAME,
                "prompt: String",
                other.type_name(),
            ))
        }
    };
    if rows.is_empty() || rows.len() > INPUT_TABLE_MAX_ROWS {
        return Err(crate::safety::bad_arg(
            NAME,
            &format!("1..={INPUT_TABLE_MAX_ROWS} rows"),
            &format!("{} row(s)", rows.len()),
        ));
    }
    let mut columns = std::collections::BTreeSet::new();
    for (i, row) in rows.iter().enumerate() {
        let Value::Record(rec) = row else {
            return Err(crate::safety::bad_arg(
                NAME,
                &format!("row {}: a Record", i + 1),
                row.type_name(),
            ));
        };
        columns.extend(rec.keys().map(String::as_str));
    }

    let shown: Vec<&str> = columns
        .iter()
        .copied()
        .take(INPUT_TABLE_MAX_COLUMNS)
        .collect();
    let hidden = columns.len() - shown.len();
    let mut table = String::from("   #");
    for column in &shown {
        table.push_str(" | ");
        table.push_str(&input_table_cell(column));
    }
    if hidden > 0 {
        table.push_str(&format!(" | (+{hidden} more columns)"));
    }
    table.push('\n');
    for (i, row) in rows.iter().enumerate() {
        table.push_str(&format!("{:>4}", i + 1));
        if let Value::Record(rec) = row {
            for column in &shown {
                let cell = rec
                    .get(*column)
                    .map(|v| v.to_display_string())
                    .unwrap_or_default();
                table.push_str(" | ");
                table.push_str(&input_table_cell(&cell));
            }
        }
        table.push('\n');
    }
    eprint!("{table}");

    let question = prompt.unwrap_or_else(|| format!("Select a row (1-{}): ", rows.len()));
    for _ in 0..INPUT_MAX_ATTEMPTS {
        let answer = read_answer(NAME, &question)?;
        match answer.trim().parse::<usize>() {
            Ok(n) if (1..=rows.len()).contains(&n) => return Ok(rows[n - 1].clone()),
            _ => eprintln!(
                "{NAME}: {answer:?} is not a row number in 1..={}",
                rows.len()
            ),
        }
    }
    Err(crate::safety::bad_arg(
        NAME,
        &format!("a row number in 1..={}", rows.len()),
        &format!("no valid answer in {INPUT_MAX_ATTEMPTS} attempts"),
    ))
}

/// `input_date(prompt?)`: a `YYYY-MM-DD` date the calendar accepts, answered as
/// its text. Anything else is asked again; after the last attempt the call
/// refuses with E_BAD_ARG.
fn bi_input_date(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "input_date";
    direct_args(
        NAME,
        &args,
        input.is_some(),
        0,
        1,
        "input_date(prompt?: String)",
    )?;
    let prompt = optional_prompt(NAME, &args, "Enter date (YYYY-MM-DD): ")?;
    ask_until(NAME, &prompt, "a date as YYYY-MM-DD", |answer| {
        parse_date(answer.trim())
    })
    .map(Value::Str)
}

// ============================================================================
// Missing Crypto implementations
// ============================================================================

fn bi_crypto_cert_verify(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let cert_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_cert_verify",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    crate::safety::reject_option_like("crypto_cert_verify", std::slice::from_ref(&cert_path))?;
    // A certificate file that did not exist answered false, "invalid".
    if !std::path::Path::new(&cert_path).is_file() {
        return Err(crate::safety::not_found(
            "crypto_cert_verify",
            "certificate file",
            &cert_path,
        ));
    }
    // A file that exists but cannot be opened makes openssl exit non-zero,
    // which answered false: an unreadable certificate read as an invalid one.
    if let Err(e) = std::fs::File::open(&cert_path) {
        return Err(crate::safety::fs_error(
            "crypto_cert_verify",
            &cert_path,
            &e,
        ));
    }
    // `openssl verify` against its default trust store on every OS. A missing
    // or empty trust store makes openssl exit non-zero, which reads as false;
    // that is the documented limitation and it is deliberately unchanged.
    let mut cmd = std::process::Command::new("openssl");
    cmd.args(["verify", &cert_path]);
    let output = bounded_cmd_output("crypto_cert_verify", "openssl", cmd, TOOL_DEADLINE_SECS)?;
    Ok(Value::Bool(output.status.success()))
}

fn bi_crypto_generate_key(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    bi_crypto_key_generate(args, input)
}

/// Signature verification returns a Bool only after structural input validation.
fn bi_crypto_verify_signature(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    digital_signatures::verify(args, input)
}

fn bi_crypto_jwt_decode(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let token = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "crypto_jwt_decode",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    // The payload, decoded without verifying the signature. This shelled
    // out to `base64` (Unix) or PowerShell (Windows) and answered null for a
    // malformed token, a bad segment or a payload that was not JSON.
    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
    let bad = |why: &str| {
        crate::safety::bad_arg("crypto_jwt_decode", "a JWT (header.payload.signature)", why)
    };
    let parts: Vec<&str> = token.trim().split('.').collect();
    if parts.len() != 3 {
        return Err(bad(&format!("{} dot-separated segment(s)", parts.len())));
    }
    let bytes = URL_SAFE_NO_PAD
        .decode(parts[1].trim_end_matches('='))
        .map_err(|e| bad(&format!("a payload that is not base64url: {e}")))?;
    let json: serde_json::Value = serde_json::from_slice(&bytes)
        .map_err(|e| bad(&format!("a payload that is not JSON: {e}")))?;
    Ok(json_to_value(json))
}

// ============================================================================
// Missing Database implementations
// ============================================================================

fn bi_db_sqlite_open(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // Just verify the database can be opened
    bi_db_sqlite_create(args, None)
}

/// Render one `Value` as a SQL literal.
///
/// Strings go through [`crate::safety::sql_literal`] rather than a local
/// `replace('\'', "''")`. The two agree on doubling quotes, but the helper also
/// refuses an interior NUL — the sqlite3 CLI reads its SQL as a C string, so a
/// NUL silently truncates the statement, and storing a shortened value is its own
/// bug. Two call sites had hand-rolled the escaping and inherited neither that
/// check nor any later fix to it.
fn sql_value(builtin: &str, v: &Value) -> Result<String> {
    Ok(match v {
        Value::Str(s) => crate::safety::sql_literal(builtin, s)?,
        Value::Int(n) => n.to_string(),
        Value::Float(f) if f.is_finite() => f.to_string(),
        Value::Bool(b) => if *b { "1" } else { "0" }.to_string(),
        Value::Null => "NULL".to_string(),
        other => {
            return Err(crate::safety::bad_arg(
                builtin,
                "String, Int, finite Float, Bool or Null SQL cell",
                other.type_name(),
            ))
        }
    })
}

fn bi_db_sqlite_insert(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_insert",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_insert",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let values = match args.get(2) {
        Some(Value::Record(r)) => r.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_insert",
                "Record",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    if values.is_empty() {
        return Err(crate::safety::arg_err(
            "db_sqlite_insert: values must be a nonempty Record",
        ));
    }

    // Column names are identifiers, and they come from a caller-supplied record,
    // so they are exactly as controlled as the values are. Escaping the values
    // and not the keys made the gap easier to miss, not smaller: a key of
    // `id) VALUES (1); DROP TABLE victim; --` closed the statement and the
    // sqlite3 CLI ran what followed.
    let columns: Vec<String> = values
        .keys()
        .map(|k| crate::safety::sql_identifier("db_sqlite_insert", k))
        .collect::<Result<_>>()?;
    let vals: Vec<String> = values
        .values()
        .map(|v| sql_value("db_sqlite_insert", v))
        .collect::<Result<_>>()?;

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({})",
        crate::safety::sql_identifier("db_sqlite_insert", &table)?,
        columns.join(", "),
        vals.join(", ")
    );
    bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None)
}

fn bi_db_sqlite_update(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_update",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_update",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let values = match args.get(2) {
        Some(Value::Record(r)) => r.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_update",
                "Record",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let where_clause = match args.get(3) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_update",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    if values.is_empty() || where_clause.trim().is_empty() {
        return Err(crate::safety::arg_err(
            "db_sqlite_update: values and WHERE clause must be nonempty",
        ));
    }

    // Same as `db_sqlite_insert`: the record's keys are identifiers and are
    // caller-controlled. The WHERE clause is SQL by contract -- this builtin
    // exists to take one -- so it stays the caller's, matching the note in
    // `db_sqlite_delete`.
    let sets: Vec<String> = values
        .iter()
        .map(|(k, v)| {
            Ok(format!(
                "{} = {}",
                crate::safety::sql_identifier("db_sqlite_update", k)?,
                sql_value("db_sqlite_update", v)?
            ))
        })
        .collect::<Result<_>>()?;

    let sql = format!(
        "UPDATE {} SET {} WHERE {}",
        crate::safety::sql_identifier("db_sqlite_update", &table)?,
        sets.join(", "),
        where_clause
    );
    bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None)
}

fn bi_db_sqlite_delete(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_delete",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_delete",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let where_clause = match args.get(2) {
        Some(Value::Str(s)) if !s.trim().is_empty() => s.clone(),
        None => "1=0".to_string(), // Safety: don't delete all by default
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_delete",
                "where: String",
                other.type_name(),
            ))
        }
    };

    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "db_sqlite_delete",
        effect: crate::safety::Effect::Destructive,
        what: "db_delete",
        targets: vec![format!("{}:{}", db_path, table)],
        blast_radius: serde_json::json!({
            "db": db_path.clone(), "table": table.clone(), "where": where_clause.clone()
        }),
        reversible: false,
        fs_paths: false,
    })?;

    // The table is an identifier and is validated; the WHERE clause is SQL by
    // contract -- this builtin exists to take one -- so it is the caller's.
    let sql = format!(
        "DELETE FROM {} WHERE {}",
        crate::safety::sql_identifier("db_sqlite_delete", &table)?,
        where_clause
    );
    bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None)
}

fn bi_db_sqlite_count(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_count",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_count",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let where_clause = args.get(2).and_then(|v| match v {
        Value::Str(s) => Some(s.clone()),
        _ => None,
    });

    let sql = if let Some(w) = where_clause {
        format!(
            "SELECT COUNT(*) as count FROM {} WHERE {}",
            crate::safety::sql_identifier("db_sqlite_count", &table)?,
            w
        )
    } else {
        format!(
            "SELECT COUNT(*) as count FROM {}",
            crate::safety::sql_identifier("db_sqlite_count", &table)?
        )
    };

    // This matched only a String count. db_sqlite_query returns it as an Int,
    // so every table counted 0 -- a 3-row table included.
    let rows = bi_db_sqlite_query(vec![Value::Str(db_path), Value::Str(sql)], None)?;
    let count = match &rows {
        Value::Array(arr) => match arr.first() {
            Some(Value::Record(rec)) => match rec.get("count") {
                Some(Value::Int(n)) => Some(*n),
                Some(Value::Str(s)) => s.trim().parse().ok(),
                _ => None,
            },
            _ => None,
        },
        _ => None,
    };
    count.map(Value::Int).ok_or_else(|| {
        crate::safety::tool_failed(
            "db_sqlite_count",
            "sqlite3 SELECT COUNT(*)",
            None,
            &format!("no count in the result: {}", rows.to_display_string()),
        )
    })
}

fn bi_db_sqlite_create_table(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_create_table",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_create_table",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let columns = match args.get(2) {
        Some(Value::Record(r)) => r.clone(),
        Some(Value::Str(s)) => {
            // Allow raw column definition
            if s.trim().is_empty() {
                return Err(crate::safety::arg_err(
                    "db_sqlite_create_table: column definition must be nonempty",
                ));
            }
            let sql = format!(
                "CREATE TABLE IF NOT EXISTS {} ({})",
                crate::safety::sql_identifier("db_sqlite_create_table", &table)?,
                s
            );
            return bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None);
        }
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_create_table",
                "Record or String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    if columns.is_empty() {
        return Err(crate::safety::arg_err(
            "db_sqlite_create_table: columns must be a nonempty Record",
        ));
    }

    // Record-form column names and type strings are validated before execution.
    // The explicit raw-SQL string form above retains the caller's SQL grammar.
    let col_defs: Vec<String> = columns
        .iter()
        .map(|(name, typ)| {
            let name = crate::safety::sql_identifier("db_sqlite_create_table", name)?;
            let type_str = match typ {
                Value::Str(s) => crate::safety::sql_column_type("db_sqlite_create_table", s)?,
                other => {
                    return Err(crate::safety::bad_arg(
                        "db_sqlite_create_table",
                        "column type: String",
                        other.type_name(),
                    ))
                }
            };
            Ok(format!("{} {}", name, type_str))
        })
        .collect::<Result<_>>()?;

    let sql = format!(
        "CREATE TABLE IF NOT EXISTS {} ({})",
        crate::safety::sql_identifier("db_sqlite_create_table", &table)?,
        col_defs.join(", ")
    );
    bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None)
}

fn bi_db_sqlite_drop_table(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_drop_table",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_drop_table",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "db_sqlite_drop_table",
        effect: crate::safety::Effect::Destructive,
        what: "db_sqlite_drop_table",
        targets: vec![format!("{}:{}", db_path, table)],
        blast_radius: serde_json::json!({ "db": db_path, "table": table }),
        // Reversible only inside a transaction — db_sqlite_exec snapshots the
        // file, so a rollback restores it byte-for-byte.
        reversible: crate::tx::is_active(),
        fs_paths: false,
    })?;
    // Validated after the guard, so an approval prompt still describes the table
    // the caller named rather than a sanitised version of it.
    let sql = format!(
        "DROP TABLE IF EXISTS {}",
        crate::safety::sql_identifier("db_sqlite_drop_table", &table)?
    );
    bi_db_sqlite_exec(vec![Value::Str(db_path), Value::Str(sql)], None)
}

