fn bi_db_sqlite_dump(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_dump",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    crate::safety::reject_option_like("db_sqlite_dump", std::slice::from_ref(&db_path))?;
    if !sqlite_db_exists(&db_path) {
        return Err(crate::safety::not_found(
            "db_sqlite_dump",
            "database",
            &db_path,
        ));
    }
    let mut cmd = std::process::Command::new("sqlite3");
    cmd.args([&db_path, ".dump"]);
    let output = bounded_cmd_output("db_sqlite_dump", "sqlite3", cmd, TOOL_DEADLINE_SECS)?;

    if output.status.success() {
        return Ok(Value::Str(
            String::from_utf8_lossy(&output.stdout).to_string(),
        ));
    }
    // A failure answered null.
    Err(crate::safety::tool_failed(
        "db_sqlite_dump",
        "sqlite3 .dump",
        output.status.code(),
        &String::from_utf8_lossy(&output.stderr),
    ))
}

