fn bi_db_json_to_sqlite(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // A malformed call used to return `Ok(Value::Bool(false))`: no error, exit
    // 0, and a value the caller may well read as "the import found nothing".
    // Same shape as `round(x, digits)` discarding `digits` and `env(name,
    // default)` discarding `default` -- a wrong answer with nothing in it that
    // says to look again. The argument order is (db, json, table), which is the
    // opposite of what the name reads like, so getting it wrong is the likely
    // mistake and it must say so.
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_json_to_sqlite",
                "a database path as the first argument: db_json_to_sqlite(db, json, table)",
                other.map_or("nothing", |v| v.type_name()),
            ))
        }
    };
    let json_path = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_json_to_sqlite",
                "a JSON path as the second argument: db_json_to_sqlite(db, json, table)",
                other.map_or("nothing", |v| v.type_name()),
            ))
        }
    };
    let table_name = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        _ => "imported".to_string(),
    };

    // Read JSON
    let content = read_text_capped("db_json_to_sqlite", &json_path)?;
    if let Ok(json) = serde_json::from_str::<serde_json::Value>(&content) {
        if let serde_json::Value::Array(arr) = json {
            if let Some(first) = arr.first() {
                if let serde_json::Value::Object(obj) = first {
                    // Column names come from the *file*, so the injection payload
                    // does not even have to be an argument: a JSON object key of
                    // `x TEXT); DROP TABLE victim; --` closed the statement and
                    // the sqlite3 CLI ran what followed. Identifiers are validated
                    // for that reason, which also means a key that is not a legal
                    // column name is now refused rather than producing broken SQL.
                    let columns: Vec<String> = obj
                        .keys()
                        .map(|k| {
                            Ok(format!(
                                "{} TEXT",
                                crate::safety::sql_identifier("db_json_to_sqlite", k)?
                            ))
                        })
                        .collect::<Result<_>>()?;
                    let create_sql = format!(
                        "CREATE TABLE IF NOT EXISTS {} ({})",
                        crate::safety::sql_identifier("db_json_to_sqlite", &table_name)?,
                        columns.join(", ")
                    );
                    bi_db_sqlite_exec(
                        vec![Value::Str(db_path.clone()), Value::Str(create_sql)],
                        None,
                    )?;

                    // Insert rows
                    for row in arr {
                        if let serde_json::Value::Object(obj) = row {
                            let cols: Vec<String> = obj
                                .keys()
                                .map(|k| crate::safety::sql_identifier("db_json_to_sqlite", k))
                                .collect::<Result<_>>()?;
                            let vals: Vec<String> = obj
                                .values()
                                .map(|v| {
                                    Ok(match v {
                                        serde_json::Value::String(s) => {
                                            crate::safety::sql_literal("db_json_to_sqlite", s)?
                                        }
                                        serde_json::Value::Number(n) => n.to_string(),
                                        serde_json::Value::Bool(b) => {
                                            if *b { "1" } else { "0" }.to_string()
                                        }
                                        _ => "NULL".to_string(),
                                    })
                                })
                                .collect::<Result<_>>()?;
                            let insert_sql = format!(
                                "INSERT INTO {} ({}) VALUES ({})",
                                crate::safety::sql_identifier("db_json_to_sqlite", &table_name)?,
                                cols.join(", "),
                                vals.join(", ")
                            );
                            bi_db_sqlite_exec(
                                vec![Value::Str(db_path.clone()), Value::Str(insert_sql)],
                                None,
                            )?;
                        }
                    }
                    return Ok(Value::Bool(true));
                }
            }
        }
    }
    Ok(Value::Bool(false))
}

fn bi_db_sqlite_to_json(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_to_json",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let table = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "db_sqlite_to_json",
                "String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    bi_db_sqlite_query(
        vec![
            Value::Str(db_path),
            Value::Str(format!(
                "SELECT * FROM {}",
                crate::safety::sql_identifier("db_sqlite_to_json", &table)?
            )),
        ],
        None,
    )
}

fn bi_db_kv_store(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // Initialize KV store
    let store_path = args
        .first()
        .and_then(|v| match v {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        })
        .unwrap_or_else(|| ".aether_kv.db".to_string());

    // The result was discarded, so a store that could not be created was
    // reported as created.
    bi_db_sqlite_exec(
        vec![
            Value::Str(store_path.clone()),
            Value::Str(
                "CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT)".to_string(),
            ),
        ],
        None,
    )?;
    Ok(Value::Str(store_path))
}

// =====================================================================
// ROBUST FILE EDITING BUILTINS (for AI agents)
// =====================================================================
// These functions provide structured, atomic file editing that avoids
// shell quoting/escaping issues that plague BASH and PowerShell.
// AI agents can safely manipulate multi-line text without worrying about
// special characters, newlines, or encoding problems.
// =====================================================================

/// file_write(path, content) - Write content to a file (creates or overwrites)
/// This is the foundation for safe file writing without shell escaping issues.
/// Usage: file_write("config.txt", "line1\nline2\nline3")
///        content | file_write("output.txt")
fn write_file_atomically(builtin: &str, path: &str, content: &[u8]) -> Result<()> {
    use std::io::Write;
    let requested = std::path::Path::new(path);
    // A rename over a symlink would replace the link with a regular file. So a
    // symlink is resolved first, and the write goes next to the file it names;
    // the link keeps pointing at the updated file. The jail check already
    // resolves links, so the resolved file is the one that was checked.
    let resolved;
    let target: &std::path::Path = match fs::symlink_metadata(requested) {
        Ok(meta) if meta.file_type().is_symlink() => {
            resolved = fs::canonicalize(requested)
                .map_err(|error| crate::safety::fs_error(builtin, path, &error))?;
            &resolved
        }
        _ => requested,
    };
    let parent = target
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| std::path::Path::new("."));
    let temporary = parent.join(format!(".aether_tmp_{}", uuid::Uuid::new_v4()));
    // Never reuse another writer's temporary file or follow a preexisting link.
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|error| crate::safety::fs_error(builtin, path, &error))?;
    let original_permissions = file.metadata().ok().map(|m| m.permissions());
    // The data must reach the disk before the rename publishes it, or a crash
    // can leave an empty or partial file under the target name.
    let written = file.write_all(content).and_then(|_| file.sync_all());
    drop(file);
    let result = written
        .map_err(|error| crate::safety::fs_error(builtin, path, &error))
        .and_then(|_| match fs::metadata(target) {
            // An existing target keeps its mode (Unix) and read-only attribute (Windows).
            Ok(existing) => fs::set_permissions(&temporary, existing.permissions())
                .map_err(|error| crate::safety::fs_error(builtin, path, &error)),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(crate::safety::fs_error(builtin, path, &error)),
        })
        .and_then(|_| {
            fs::rename(&temporary, target)
                .map_err(|error| crate::safety::fs_error(builtin, path, &error))
        });
    match result {
        Ok(()) => {
            sync_parent_directory(parent);
            Ok(())
        }
        Err(error) => {
            // Restore our own file's permissions before removing it: a read-only copy cannot be deleted on Windows.
            if let Some(permissions) = original_permissions {
                let _ = fs::set_permissions(&temporary, permissions);
            }
            let _ = fs::remove_file(&temporary);
            Err(error)
        }
    }
}

/// Best-effort fsync of the directory that holds a just-renamed file, so the
/// rename itself survives a crash on Unix. Errors are ignored: the file is
/// already published, and some filesystems refuse to sync a directory.
#[cfg(unix)]
fn sync_parent_directory(parent: &std::path::Path) {
    if let Ok(dir) = fs::File::open(parent) {
        let _ = dir.sync_all();
    }
}

/// Windows has no directory fsync in std, and the rename is already durable there.
#[cfg(not(unix))]
fn sync_parent_directory(_parent: &std::path::Path) {}

fn bi_file_write(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("file_write requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_write",
                "path: String",
                other.type_name(),
            ))
        }
    };
    // In a jailed context, a relative path is workspace-relative (not CWD-relative)
    // so the write lands inside the jail and matches the transaction journal.
    let path = crate::safety::resolve_path_str(&path);

    // Get content from args or pipeline input
    let content = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => {
                return Err(crate::safety::arg_err(
                    "file_write requires content to write",
                ))
            }
        }
    };

    // Agent mode / explicit workspace: a write is allowed but jailed to the
    // workspace (WriteLocal is allow-by-policy; fs_paths enforces containment, so
    // an absolute path outside the workspace is rejected).
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_write",
        effect: crate::safety::Effect::WriteLocal,
        what: "write",
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({ "bytes": content.len() }),
        reversible: true,
        fs_paths: true,
    })?;

    crate::tx::snapshot(&path); // record pre-write state if a transaction is active

    write_file_atomically("file_write", &path, content.as_bytes())?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("bytes".to_string(), Value::Int(content.len() as i64));
    result.insert(
        "lines".to_string(),
        Value::Int(content.lines().count() as i64),
    );
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_append(path, content) - Append content to a file
/// Usage: file_append("log.txt", "New log entry\n")
///        new_lines | file_append("data.txt")
fn bi_file_append(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("file_append requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_append",
                "path: String",
                other.type_name(),
            ))
        }
    };
    // Jailed: relative paths are workspace-relative (see file_write).
    let path = crate::safety::resolve_path_str(&path);

    // Get content from args or pipeline input
    let content = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => {
                return Err(crate::safety::arg_err(
                    "file_append requires content to append",
                ))
            }
        }
    };

    // Jailed to the workspace in agent mode (see file_write).
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_append",
        effect: crate::safety::Effect::WriteLocal,
        what: "append",
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({ "bytes": content.len() }),
        reversible: true,
        fs_paths: true,
    })?;

    crate::tx::snapshot(&path); // record pre-append state if a transaction is active

    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .map_err(|error| crate::safety::fs_error("file_append", &path, &error))?;

    file.write_all(content.as_bytes())
        .map_err(|error| crate::safety::fs_error("file_append", &path, &error))?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert(
        "bytes_appended".to_string(),
        Value::Int(content.len() as i64),
    );
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_patch(path, patches) - Apply multiple search/replace operations atomically
/// Patches is an array of records: [{find: "old", replace: "new"}, ...]
/// Usage: file_patch("config.txt", [{find: "DEBUG=0", replace: "DEBUG=1"}])
fn bi_file_patch(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("file_patch requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_patch",
                "path: String",
                other.type_name(),
            ))
        }
    };
    // Classified `ReadLocal` while the body wrote the file back in place.
    // `WriteLocal` is what the jail keys on, so this path went uncontained.
    let path = guard_local_write("file_patch", &path)?;

    let patches = if args.len() > 1 {
        match &args[1] {
            Value::Array(arr) => arr.clone(),
            Value::Record(r) => vec![Value::Record(r.clone())],
            _ => {
                return Err(crate::safety::arg_err(
                    "file_patch: patches must be an array of records",
                ))
            }
        }
    } else {
        match input {
            Some(Value::Array(arr)) => arr,
            Some(Value::Record(r)) => vec![Value::Record(r)],
            _ => {
                return Err(crate::safety::arg_err(
                    "file_patch: patches must be provided",
                ))
            }
        }
    };

    // Each patch is a full pass over the file, so the batch is capped the way
    // file_edit caps its own.
    if patches.len() > 10_000 {
        return Err(crate::safety::budget_exceeded(
            "file_patch",
            "batch exceeds 10000 patches".into(),
            "use a smaller batch",
        ));
    }

    // Refuse malformed instructions before reading or writing the file.
    for (index, patch) in patches.iter().enumerate() {
        let Value::Record(record) = patch else {
            return Err(crate::safety::arg_err(format!(
                "file_patch: patch {index} must be a record"
            )));
        };
        for names in [["find", "old", "search"], ["replace", "new", "with"]] {
            if !matches!(
                record
                    .get(names[0])
                    .or(record.get(names[1]))
                    .or(record.get(names[2])),
                Some(Value::Str(_))
            ) {
                return Err(crate::safety::arg_err(format!(
                    "file_patch: patch {index} requires a {} string",
                    names[0]
                )));
            }
        }
    }

    // Read current content
    let mut content = read_text_capped("file_patch", &path)?;

    let mut applied = Vec::new();
    let mut failed = Vec::new();

    for (i, patch) in patches.iter().enumerate() {
        let record = match patch {
            Value::Record(r) => r,
            _ => {
                failed.push(Value::Str(format!("patch {}: not a record", i)));
                continue;
            }
        };

        let find_str = match record
            .get("find")
            .or(record.get("old"))
            .or(record.get("search"))
        {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                failed.push(Value::Str(format!("patch {}: missing 'find' string", i)));
                continue;
            }
        };

        let replace_str = match record
            .get("replace")
            .or(record.get("new"))
            .or(record.get("with"))
        {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                failed.push(Value::Str(format!("patch {}: missing 'replace' string", i)));
                continue;
            }
        };

        if content.contains(&find_str) {
            let count = content.matches(&find_str).count();
            content = content.replace(&find_str, &replace_str);

            let mut patch_result = BTreeMap::new();
            patch_result.insert("find".to_string(), Value::Str(find_str));
            patch_result.insert("replace".to_string(), Value::Str(replace_str));
            patch_result.insert("count".to_string(), Value::Int(count as i64));
            applied.push(Value::Record(patch_result));
        } else {
            failed.push(Value::Str(format!(
                "patch {}: '{}' not found",
                i,
                if find_str.chars().nth(40).is_some() {
                    format!("{}...", find_str.chars().take(40).collect::<String>())
                } else {
                    find_str
                }
            )));
        }
    }

    // Write back atomically
    crate::tx::snapshot(&path); // record pre-patch state if a transaction is active
    write_file_atomically("file_patch", &path, content.as_bytes())?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("applied".to_string(), Value::Array(applied.clone()));
    result.insert("failed".to_string(), Value::Array(failed.clone()));
    result.insert("success".to_string(), Value::Bool(failed.is_empty()));
    result.insert(
        "patches_applied".to_string(),
        Value::Int(applied.len() as i64),
    );
    result.insert(
        "patches_failed".to_string(),
        Value::Int(failed.len() as i64),
    );

    Ok(Value::Record(result))
}

/// file_replace(path, old_text, new_text) - Simple string replacement in a file
/// Usage: file_replace("config.txt", "old_value", "new_value")
fn bi_file_replace(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 3 {
        return Err(crate::safety::arg_err(
            "file_replace requires path, old_text, and new_text",
        ));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_replace",
                "path: String",
                other.type_name(),
            ))
        }
    };

    let old_text = match &args[1] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_replace",
                "old_text: String",
                other.type_name(),
            ))
        }
    };

    let new_text = match &args[2] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_replace",
                "new_text: String",
                other.type_name(),
            ))
        }
    };

    let mut patch = BTreeMap::new();
    patch.insert("find".to_string(), Value::Str(old_text));
    patch.insert("replace".to_string(), Value::Str(new_text));

    bi_file_patch(
        vec![Value::Str(path), Value::Array(vec![Value::Record(patch)])],
        None,
    )
}

/// file_insert(path, position, content) - Insert content at a specific position
fn bi_file_insert(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "file_insert requires path and position",
        ));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_insert",
                "path: String",
                other.type_name(),
            ))
        }
    };
    // Classified `ReadLocal` while the body wrote the file back in place.
    // `WriteLocal` is what the jail keys on, so this path went uncontained.
    let path = guard_local_write("file_insert", &path)?;

    let content = if args.len() > 2 {
        match &args[2] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => {
                return Err(crate::safety::arg_err(
                    "file_insert requires content to insert",
                ))
            }
        }
    };

    let mut file_content = read_text_capped("file_insert", &path)?;

    let mut lines: Vec<String> = file_content.lines().map(|s| s.to_string()).collect();
    let insert_lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
    let insert_pos: usize;
    let mut pattern_found = true;

    match &args[1] {
        Value::Int(line_num) => {
            let line = (*line_num).max(1) as usize;
            insert_pos = (line - 1).min(lines.len());
        }
        Value::Str(pos) => match pos.as_str() {
            "start" | "beginning" | "top" => insert_pos = 0,
            "end" | "bottom" | "append" => insert_pos = lines.len(),
            _ => {
                if let Some(idx) = lines.iter().position(|l| l.contains(pos)) {
                    insert_pos = idx + 1;
                } else {
                    pattern_found = false;
                    insert_pos = lines.len();
                }
            }
        },
        Value::Record(r) => {
            if let Some(Value::Str(after_pattern)) = r.get("after") {
                if let Some(idx) = lines.iter().position(|l| l.contains(after_pattern)) {
                    insert_pos = idx + 1;
                } else {
                    pattern_found = false;
                    insert_pos = lines.len();
                }
            } else if let Some(Value::Str(before_pattern)) = r.get("before") {
                if let Some(idx) = lines.iter().position(|l| l.contains(before_pattern)) {
                    insert_pos = idx;
                } else {
                    pattern_found = false;
                    insert_pos = 0;
                }
            } else if let Some(Value::Int(line)) = r.get("line") {
                insert_pos = ((*line).max(1) as usize - 1).min(lines.len());
            } else {
                return Err(crate::safety::arg_err(
                    "file_insert: position record must have 'after', 'before', or 'line' key",
                ));
            }
        }
        _ => {
            return Err(crate::safety::arg_err(
                "file_insert: position must be a line number, string, or record",
            ))
        }
    }

    for (i, line) in insert_lines.iter().enumerate() {
        lines.insert(insert_pos + i, line.clone());
    }

    file_content = lines.join("\n");
    if !file_content.ends_with('\n') {
        file_content.push('\n');
    }

    crate::tx::snapshot(&path); // record pre-insert state if a transaction is active
    write_file_atomically("file_insert", &path, file_content.as_bytes())?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert(
        "lines_inserted".to_string(),
        Value::Int(insert_lines.len() as i64),
    );
    result.insert("at_line".to_string(), Value::Int((insert_pos + 1) as i64));
    result.insert("pattern_found".to_string(), Value::Bool(pattern_found));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// Delete an inclusive one-based range or lines selected by a literal pattern.
fn bi_file_delete_lines(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if !(2..=3).contains(&args.len()) || input.is_some() {
        return Err(crate::safety::arg_err("file_delete_lines requires path, line specification and optional range end, without pipeline input"));
    }
    enum Selection {
        Range(usize, usize),
        Pattern(String, bool),
    }
    fn line_index(value: Value) -> Result<usize> {
        match value {
            Value::Int(n) if n > 0 => usize::try_from(n - 1)
                .map_err(|_| crate::safety::arg_err("file_delete_lines line number is too large")),
            _ => Err(crate::safety::arg_err(
                "file_delete_lines line numbers must be positive Int",
            )),
        }
    }
    let mut args = args.into_iter();
    let Some(Value::Str(path)) = args.next() else {
        return Err(crate::safety::arg_err(
            "file_delete_lines path must be String",
        ));
    };
    let selection = match args.next() {
        Some(value @ Value::Int(_)) => {
            let start = line_index(value)?;
            let end = args.next().map(line_index).transpose()?.unwrap_or(start);
            if end < start {
                return Err(crate::safety::arg_err(
                    "file_delete_lines range end must not precede start",
                ));
            }
            Selection::Range(start, end)
        }
        Some(Value::Record(record)) => {
            if args.next().is_some() || record.len() != 1 {
                return Err(crate::safety::arg_err("file_delete_lines pattern record requires exactly one selector and no range end"));
            }
            let (key, value) = record.into_iter().next().expect("one selector checked");
            if !matches!(key.as_str(), "matching" | "contains" | "pattern" | "exact") {
                return Err(crate::safety::arg_err(
                    "file_delete_lines selector must be matching, contains, pattern or exact",
                ));
            }
            let Value::Str(pattern) = value else {
                return Err(crate::safety::arg_err(
                    "file_delete_lines pattern must be String",
                ));
            };
            Selection::Pattern(pattern, key == "exact")
        }
        _ => {
            return Err(crate::safety::arg_err(
                "file_delete_lines selection must be positive Int or pattern Record",
            ))
        }
    };
    let path = crate::safety::resolve_path_str(&path);
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_delete_lines",
        effect: crate::safety::Effect::Destructive,
        what: "delete lines",
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({"path":path}),
        reversible: true,
        fs_paths: true,
    })?;
    let content = line_read("file_delete_lines", &path)?;
    let mut new_content = String::with_capacity(content.len());
    let mut deleted = 0;
    let mut remaining = 0;
    for (index, line) in content.lines().enumerate() {
        let remove = match &selection {
            Selection::Range(start, end) => (*start..=*end).contains(&index),
            Selection::Pattern(pattern, exact) => {
                if *exact {
                    line == pattern
                } else {
                    line.contains(pattern)
                }
            }
        };
        if remove {
            deleted += 1;
        } else {
            new_content.push_str(line);
            new_content.push('\n');
            remaining += 1;
        }
    }
    crate::tx::snapshot(&path);
    write_file_atomically("file_delete_lines", &path, new_content.as_bytes())?;
    Ok(Value::Record(BTreeMap::from([
        ("path".into(), Value::Str(path)),
        ("lines_deleted".into(), Value::Int(deleted)),
        ("lines_remaining".into(), Value::Int(remaining)),
        ("success".into(), Value::Bool(true)),
    ])))
}

/// Apply a validated batch in descending line order, then publish once.
fn bi_file_edit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const MAX_BYTES: usize = 64 * 1024 * 1024;
    const MAX_LINES: usize = 1_000_000;
    if (input.is_some() && args.len() != 1) || (input.is_none() && args.len() != 2) {
        return Err(crate::safety::arg_err(
            "file_edit requires path and direct or piped edits, without conflicting input",
        ));
    }
    let mut args = args.into_iter();
    let Some(Value::Str(path)) = args.next() else {
        return Err(crate::safety::arg_err("file_edit path must be String"));
    };
    let edits = match input.or_else(|| args.next()) {
        Some(Value::Array(edits)) => edits,
        Some(edit @ Value::Record(_)) => vec![edit],
        _ => {
            return Err(crate::safety::arg_err(
                "file_edit edits must be a Record or Array of Records",
            ))
        }
    };
    if edits.len() > 10_000 {
        return Err(crate::safety::budget_exceeded(
            "file_edit",
            "batch exceeds 10000 edits".into(),
            "use a smaller batch",
        ));
    }
    fn field(
        record: &mut BTreeMap<String, Value>,
        name: &str,
        alias: &str,
    ) -> Result<Option<Value>> {
        let first = record.remove(name);
        let second = record.remove(alias);
        if first.is_some() && second.is_some() {
            return Err(crate::safety::arg_err(format!(
                "file_edit cannot combine {name} and {alias}"
            )));
        }
        Ok(first.or(second))
    }
    fn position(value: Option<Value>) -> Result<usize> {
        match value {
            Some(Value::Int(n)) if n > 0 => usize::try_from(n - 1)
                .map_err(|_| crate::safety::arg_err("file_edit line number is too large")),
            _ => Err(crate::safety::arg_err(
                "file_edit line numbers must be positive Int",
            )),
        }
    }
    struct Edit {
        index: usize,
        op: &'static str,
        start: usize,
        end: usize,
        lines: Vec<String>,
    }
    let mut prepared = Vec::with_capacity(edits.len());
    let mut payload_bytes = 0usize;
    let mut payload_lines = 0usize;
    for (index, edit) in edits.into_iter().enumerate() {
        let Value::Record(mut record) = edit else {
            return Err(crate::safety::arg_err(
                "file_edit every edit must be a Record",
            ));
        };
        let op = match field(&mut record, "op", "operation")? {
            Some(Value::Str(op)) => match op.as_str() {
                "replace" | "replace_range" => "replace_range",
                "insert" | "insert_at" => "insert_at",
                "delete" | "delete_range" => "delete_range",
                _ => return Err(crate::safety::arg_err("file_edit unknown operation")),
            },
            _ => {
                return Err(crate::safety::arg_err(
                    "file_edit requires an operation String",
                ))
            }
        };
        let start = if op == "insert_at" {
            position(record.remove("line"))?
        } else {
            position(field(&mut record, "start_line", "line")?)?
        };
        let end = if op == "insert_at" {
            start
        } else {
            record
                .remove("end_line")
                .map(|v| position(Some(v)))
                .transpose()?
                .unwrap_or(start)
        };
        if end < start {
            return Err(crate::safety::arg_err(
                "file_edit range end must not precede start",
            ));
        }
        let lines = if op == "delete_range" {
            Vec::new()
        } else {
            let Some(Value::Str(text)) = field(&mut record, "content", "text")? else {
                return Err(crate::safety::arg_err(
                    "file_edit insert and replace require content String",
                ));
            };
            payload_bytes = payload_bytes.saturating_add(text.len());
            payload_lines = payload_lines.saturating_add(text.lines().count());
            if payload_bytes > MAX_BYTES || payload_lines > MAX_LINES {
                return Err(crate::safety::budget_exceeded(
                    "file_edit",
                    "edit payload exceeds 64 MiB or one million lines".into(),
                    "use a smaller batch",
                ));
            }
            text.lines().map(str::to_owned).collect()
        };
        if !record.is_empty() {
            return Err(crate::safety::arg_err(
                "file_edit unknown or conflicting operation fields",
            ));
        }
        prepared.push(Edit {
            index,
            op,
            start,
            end,
            lines,
        });
    }
    let path = guard_local_write("file_edit", &path)?;
    let content = line_read("file_edit", &path)?;
    let count = content.lines().count();
    let max_lines = count.saturating_add(payload_lines);
    if max_lines > MAX_LINES || max_lines.saturating_mul(prepared.len()) > 10_000_000 {
        return Err(crate::safety::budget_exceeded(
            "file_edit",
            "batch exceeds one million potential lines or ten million line-edit work units".into(),
            "use a smaller file or batch",
        ));
    }
    let mut lines: Vec<String> = content.lines().map(str::to_owned).collect();
    drop(content);
    prepared.sort_by(|a, b| b.start.cmp(&a.start));
    let mut applied = Vec::with_capacity(prepared.len());
    for edit in prepared {
        let mut result = BTreeMap::from([("op".into(), Value::Str(edit.op.into()))]);
        if edit.op == "insert_at" {
            let at = edit.start.min(lines.len());
            let inserted = edit.lines.len();
            lines.splice(at..at, edit.lines);
            result.insert("line".into(), Value::Int((at + 1) as i64));
            result.insert("lines_inserted".into(), Value::Int(inserted as i64));
        } else {
            if edit.start >= lines.len() {
                return Err(crate::safety::arg_err(format!(
                    "file_edit edit {}: start line out of range",
                    edit.index
                )));
            }
            let end = edit.end.min(lines.len() - 1);
            result.insert("start_line".into(), Value::Int((edit.start + 1) as i64));
            if edit.op == "replace_range" {
                lines.splice(edit.start..=end, edit.lines);
                result.insert("end_line".into(), Value::Int((end + 1) as i64));
            } else {
                lines.drain(edit.start..=end);
                result.insert(
                    "lines_deleted".into(),
                    Value::Int((end - edit.start + 1) as i64),
                );
            }
        }
        applied.push(Value::Record(result));
    }
    let bytes = lines.iter().fold(0usize, |n, line| {
        n.saturating_add(line.len()).saturating_add(1)
    });
    if bytes > MAX_BYTES {
        return Err(crate::safety::budget_exceeded(
            "file_edit",
            "normalized output exceeds 64 MiB".into(),
            "produce a smaller file",
        ));
    }
    let mut output = String::with_capacity(bytes);
    for line in &lines {
        output.push_str(line);
        output.push('\n');
    }
    crate::tx::snapshot(&path);
    write_file_atomically("file_edit", &path, output.as_bytes())?;
    let applied_count = applied.len();
    Ok(Value::Record(BTreeMap::from([
        ("path".into(), Value::Str(path)),
        ("applied".into(), Value::Array(applied)),
        ("failed".into(), Value::Array(Vec::new())),
        ("success".into(), Value::Bool(true)),
        ("edits_applied".into(), Value::Int(applied_count as i64)),
        ("edits_failed".into(), Value::Int(0)),
        ("final_lines".into(), Value::Int(lines.len() as i64)),
    ])))
}

/// file_diff(path1, path2) - Compare two files and return differences
fn bi_file_diff(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if input.is_some() || args.len() != 2 {
        return Err(crate::safety::arg_err(
            "file_diff requires two direct file paths and no pipeline input",
        ));
    }
    let mut args = args.into_iter();
    let Some(Value::Str(path1)) = args.next() else {
        return Err(crate::safety::arg_err(
            "file_diff first path must be String",
        ));
    };
    let Some(Value::Str(path2)) = args.next() else {
        return Err(crate::safety::arg_err(
            "file_diff second path must be String",
        ));
    };
    let resolved1 = crate::safety::resolve_path_str(&path1);
    let resolved2 = crate::safety::resolve_path_str(&path2);
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_diff",
        effect: crate::safety::Effect::ReadLocal,
        what: "compare files",
        targets: vec![resolved1.clone(), resolved2.clone()],
        blast_radius: serde_json::json!({"files":2}),
        reversible: true,
        fs_paths: true,
    })?;
    let content1 = line_read("file_diff", &resolved1)?;
    let content2 = line_read("file_diff", &resolved2)?;
    let mut lines1 = content1.lines();
    let mut lines2 = content2.lines();
    let (mut count1, mut count2, mut line) = (0, 0, 0);
    let mut diffs = Vec::new();
    loop {
        let old = lines1.next();
        let new = lines2.next();
        if old.is_none() && new.is_none() {
            break;
        }
        line += 1;
        count1 += usize::from(old.is_some());
        count2 += usize::from(new.is_some());
        if old == new {
            continue;
        }
        if diffs.len() >= 10000 {
            return Err(crate::safety::budget_exceeded(
                "file_diff",
                "comparison exceeds 10000 differences".into(),
                "compare smaller files",
            ));
        }
        let kind = match (old, new) {
            (Some(_), Some(_)) => "changed",
            (Some(_), None) => "deleted",
            (None, Some(_)) => "added",
            _ => unreachable!(),
        };
        let mut diff = BTreeMap::from([
            ("line".into(), Value::Int(line)),
            ("type".into(), Value::Str(kind.into())),
        ]);
        if let Some(old) = old {
            diff.insert("old".into(), Value::Str(old.to_string()));
        }
        if let Some(new) = new {
            diff.insert("new".into(), Value::Str(new.to_string()));
        }
        diffs.push(Value::Record(diff));
    }
    let diff_count = diffs.len();
    Ok(Value::Record(BTreeMap::from([
        ("file1".into(), Value::Str(path1)),
        ("file2".into(), Value::Str(path2)),
        ("lines1".into(), Value::Int(count1 as i64)),
        ("lines2".into(), Value::Int(count2 as i64)),
        ("differences".into(), Value::Array(diffs)),
        ("diff_count".into(), Value::Int(diff_count as i64)),
        ("identical".into(), Value::Bool(diff_count == 0)),
    ])))
}
/// file_backup(path, [suffix]) - Create a backup copy of a file before editing
/// Usage: file_backup("config.txt")  -> creates config.txt.bak
/// Usage: file_backup("config.txt", ".backup")  -> creates config.txt.backup
fn bi_file_backup(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let mut args = args.into_iter();
    let path = match input {
        Some(Value::Str(path)) => path,
        Some(_) => {
            return Err(crate::safety::arg_err(
                "file_backup piped path must be String",
            ))
        }
        None => match args.next() {
            Some(Value::Str(path)) => path,
            _ => return Err(crate::safety::arg_err("file_backup requires path String")),
        },
    };
    let suffix = match args.next() {
        None => ".bak".to_string(),
        Some(Value::Str(suffix)) => suffix,
        Some(_) => return Err(crate::safety::arg_err("file_backup suffix must be String")),
    };
    if args.next().is_some() {
        return Err(crate::safety::arg_err(
            "file_backup accepts path and optional suffix only",
        ));
    }
    if suffix.is_empty()
        || suffix.ends_with(['.', ' '])
        || suffix
            .chars()
            .any(|c| c.is_control() || matches!(c, '/' | '\\' | ':'))
    {
        return Err(crate::safety::arg_err("file_backup suffix must be nonempty, without separators, colon, controls or trailing dot/space"));
    }
    let backup = crate::safety::resolve_path_str(&format!("{path}{suffix}"));
    let path = crate::safety::resolve_path_str(&path);
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_backup",
        effect: crate::safety::Effect::WriteLocal,
        what: "back up file",
        targets: vec![path.clone(), backup.clone()],
        blast_radius: serde_json::json!({"files":2}),
        reversible: true,
        fs_paths: true,
    })?;
    let bytes = backup_file_atomically(&path, &backup)?;
    Ok(Value::Record(BTreeMap::from([
        ("path".into(), Value::Str(path)),
        ("backup".into(), Value::Str(backup)),
        ("bytes".into(), Value::Int(bytes as i64)),
        ("success".into(), Value::Bool(true)),
    ])))
}

/// Copy binary bytes through an exclusively created sibling, then publish it.
fn backup_file_atomically(source: &str, destination: &str) -> Result<u64> {
    copy_file_atomically("file_backup", source, destination, 64 * 1024 * 1024)
}

fn copy_file_atomically(
    builtin: &str,
    source: &str,
    destination: &str,
    max_bytes: u64,
) -> Result<u64> {
    use std::io::Read;
    let metadata =
        fs::metadata(source).map_err(|e| crate::safety::fs_error(builtin, source, &e))?;
    if !metadata.is_file() {
        return Err(crate::safety::arg_err(format!(
            "{builtin} source must be a regular file"
        )));
    }
    if metadata.len() > max_bytes {
        return Err(crate::safety::budget_exceeded(
            builtin,
            "source exceeds remaining copy byte budget".into(),
            "copy a smaller file",
        ));
    }
    match fs::metadata(destination) {
        Ok(metadata) if !metadata.is_file() => {
            return Err(crate::safety::arg_err(format!(
                "{builtin} destination must be a regular file when it exists"
            )))
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(crate::safety::fs_error(builtin, destination, &error)),
    }
    if let Ok(source_path) = fs::canonicalize(source) {
        if fs::canonicalize(destination)
            .is_ok_and(|destination_path| destination_path == source_path)
        {
            return Err(crate::safety::arg_err(format!(
                "{builtin} destination must differ from source"
            )));
        }
    }
    let file = fs::File::open(source).map_err(|e| crate::safety::fs_error(builtin, source, &e))?;
    let target = std::path::Path::new(destination);
    let parent = target
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| std::path::Path::new("."));
    let temporary = parent.join(format!(".aether_tmp_{}", uuid::Uuid::new_v4()));
    let mut output = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|e| crate::safety::fs_error(builtin, destination, &e))?;
    let original_permissions = output.metadata().ok().map(|m| m.permissions());
    let result = (|| -> Result<u64> {
        let bytes = std::io::copy(&mut file.take(max_bytes + 1), &mut output)
            .map_err(|e| crate::safety::fs_error(builtin, destination, &e))?;
        if bytes > max_bytes {
            return Err(crate::safety::budget_exceeded(
                builtin,
                "source grew beyond remaining copy byte budget".into(),
                "copy a smaller file",
            ));
        }
        output
            .set_permissions(metadata.permissions())
            .map_err(|e| crate::safety::fs_error(builtin, destination, &e))?;
        drop(output);
        crate::tx::snapshot(destination);
        fs::rename(&temporary, target)
            .map_err(|e| crate::safety::fs_error(builtin, destination, &e))?;
        Ok(bytes)
    })();
    if result.is_err() {
        // Restore the original sibling-file permissions before cleaning our own file.
        // This also removes Windows read-only attributes copied from the source.
        if let Some(permissions) = original_permissions {
            let _ = fs::set_permissions(&temporary, permissions);
        }
        let _ = fs::remove_file(&temporary);
    }
    result
}

/// Copy a bounded, preflighted file or directory tree.
fn bi_file_copy(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const MAX_BYTES: u64 = 64 * 1024 * 1024;
    const MAX_ENTRIES: usize = 10_000;
    if args.len() != 2 || input.is_some() {
        return Err(crate::safety::arg_err(
            "file_copy requires exactly source and destination paths, without pipeline input",
        ));
    }
    let mut args = args.into_iter();
    let Some(Value::Str(source)) = args.next() else {
        return Err(crate::safety::arg_err("file_copy source must be String"));
    };
    let Some(Value::Str(dest)) = args.next() else {
        return Err(crate::safety::arg_err(
            "file_copy destination must be String",
        ));
    };
    let source = crate::safety::resolve_path_str(&source);
    let dest = crate::safety::resolve_path_str(&dest);
    let source_path = std::path::Path::new(&source);
    let dest_path = std::path::Path::new(&dest);
    let metadata = fs::symlink_metadata(source_path)
        .map_err(|e| crate::safety::fs_error("file_copy", source_path, &e))?;
    if !metadata.is_file() && !metadata.is_dir() {
        return Err(crate::safety::arg_err(
            "file_copy supports regular files and directories only, without symlink entries",
        ));
    }
    // Canonicalize the existing parent before joining the leaf: this also makes
    // non-existent destinations comparable with the canonical source tree.
    let parent = dest_path
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| std::path::Path::new("."));
    let parent =
        fs::canonicalize(parent).map_err(|e| crate::safety::fs_error("file_copy", parent, &e))?;
    let leaf = dest_path.file_name().ok_or_else(|| {
        crate::safety::arg_err("file_copy destination must name a file or directory")
    })?;
    if !parent.is_dir() {
        return Err(crate::safety::arg_err(
            "file_copy destination parent must be an existing directory",
        ));
    }
    let canonical_dest = match fs::canonicalize(dest_path) {
        Ok(path) => path,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => parent.join(leaf),
        Err(e) => return Err(crate::safety::fs_error("file_copy", dest_path, &e)),
    };
    let canonical_source = fs::canonicalize(source_path)
        .map_err(|e| crate::safety::fs_error("file_copy", source_path, &e))?;
    if canonical_source == canonical_dest
        || (metadata.is_dir()
            && (canonical_dest.starts_with(&canonical_source)
                || canonical_source.starts_with(&canonical_dest)))
    {
        return Err(crate::safety::arg_err(
            "file_copy source and destination must not overlap",
        ));
    }
    // Source reads are intentionally unjailed. Only destination paths are guarded.
    let mut plan = vec![(
        source_path.to_path_buf(),
        dest_path.to_path_buf(),
        metadata.is_dir(),
    )];
    let mut bytes = if metadata.is_file() {
        metadata.len()
    } else {
        0
    };
    if metadata.is_dir() {
        for entry in WalkDir::new(source_path).min_depth(1) {
            if plan.len() >= MAX_ENTRIES {
                return Err(crate::safety::budget_exceeded(
                    "file_copy",
                    "copy exceeds 10000 entries".into(),
                    "copy a smaller tree",
                ));
            }
            let entry = entry.map_err(|e| {
                crate::safety::fs_error(
                    "file_copy",
                    e.path().unwrap_or(source_path),
                    &std::io::Error::other(e.to_string()),
                )
            })?;
            let kind = entry.file_type();
            if entry.path().to_str().is_none() {
                return Err(crate::safety::arg_err(
                    "file_copy tree paths must be valid UTF-8",
                ));
            }
            if !kind.is_file() && !kind.is_dir() {
                return Err(crate::safety::arg_err("file_copy tree must contain regular files and directories only, without symlink entries"));
            }
            let relative = entry
                .path()
                .strip_prefix(source_path)
                .map_err(|_| crate::safety::arg_err("file_copy traversal escaped source"))?;
            if kind.is_file() {
                let size = fs::metadata(entry.path())
                    .map_err(|e| crate::safety::fs_error("file_copy", entry.path(), &e))?
                    .len();
                bytes = bytes.saturating_add(size);
            }
            plan.push((
                entry.path().to_path_buf(),
                dest_path.join(relative),
                kind.is_dir(),
            ));
            if bytes > MAX_BYTES {
                break;
            }
        }
    }
    if bytes > MAX_BYTES {
        return Err(crate::safety::budget_exceeded(
            "file_copy",
            "copy exceeds 64 MiB total".into(),
            "copy smaller files",
        ));
    }
    // Refuse conflicts and symlink destinations for the entire plan before any
    // mkdir, transaction snapshot or copy. Existing directories are merged.
    for (_, target, directory) in &plan {
        match fs::symlink_metadata(target) {
            Ok(m) if (*directory && !m.is_dir()) || (!*directory && !m.is_file()) => {
                return Err(crate::safety::arg_err(
                    "file_copy destination type conflicts with source or is a symlink",
                ));
            }
            Ok(_) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(crate::safety::fs_error("file_copy", target, &e)),
        }
    }
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "file_copy",
        effect: crate::safety::Effect::WriteLocal,
        what: "copy files",
        targets: plan
            .iter()
            .map(|(_, p, _)| p.to_string_lossy().into_owned())
            .collect(),
        blast_radius: serde_json::json!({"entries":plan.len(),"bytes":bytes}),
        reversible: true,
        fs_paths: true,
    })?;
    let mut copied = 0;
    for (from, to, directory) in plan {
        let to_str = to.to_string_lossy();
        if directory {
            // Snapshot only new directories; snapshotting an existing merge
            // root would also journal unrelated files in that directory.
            if !to.exists() {
                crate::tx::snapshot(&to_str);
                fs::create_dir(&to).map_err(|e| crate::safety::fs_error("file_copy", &to, &e))?;
            }
        } else {
            copied += copy_file_atomically(
                "file_copy",
                &from.to_string_lossy(),
                &to_str,
                MAX_BYTES - copied,
            )?;
        }
    }
    Ok(Value::Record(BTreeMap::from([
        ("source".into(), Value::Str(source)),
        ("dest".into(), Value::Str(dest)),
        ("bytes".into(), Value::Int(copied as i64)),
        ("success".into(), Value::Bool(true)),
    ])))
}

/// file_move(source, dest) - Move/rename a file or directory
fn bi_file_move(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "file_move requires source and destination paths",
        ));
    }

    let source = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_move",
                "source: String",
                other.type_name(),
            ))
        }
    };

    let dest = match &args[1] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "file_move",
                "destination: String",
                other.type_name(),
            ))
        }
    };

    if !std::path::Path::new(&source).exists() {
        return Err(crate::safety::not_found("file_move", "source", &source));
    }

    // Classified `ReadLocal` while the body renamed one path over another —
    // which removes the source and can overwrite the destination. Both ends
    // are caller-supplied, and neither was jailed.
    let source = guard_local_move("file_move", &source)?;
    let dest = guard_local_move("file_move", &dest)?;

    let metadata =
        fs::metadata(&source).map_err(|e| crate::safety::fs_error("file_move", &source, &e))?;
    let bytes = metadata.len();

    // Both ends change: the source disappears and the destination is replaced
    // (or created). Rollback restores the source and removes or restores the
    // destination.
    crate::tx::snapshot(&source);
    crate::tx::snapshot(&dest);
    fs::rename(&source, &dest)
        .map_err(|error| crate::safety::fs_error("file_move", &dest, &error))?;

    let mut result = BTreeMap::new();
    result.insert("source".to_string(), Value::Str(source));
    result.insert("dest".to_string(), Value::Str(dest));
    result.insert("bytes".to_string(), Value::Int(bytes as i64));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_exists(path) - Check if a file or directory exists
fn bi_file_exists(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = match args.first().or(input.as_ref()) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("file_exists requires a path")),
    };

    // Path::exists/is_file/is_dir answer false for any stat error, so a path
    // that could not be checked read as absent. Only NotFound is absent now.
    let p = std::path::Path::new(&path);
    let meta = match std::fs::metadata(p) {
        Ok(meta) => Some(meta),
        Err(e) if path_is_absent(&e) => None,
        Err(e) => return Err(crate::safety::fs_error("file_exists", p, &e)),
    };
    let exists = meta.is_some();
    let is_file = meta.as_ref().is_some_and(|m| m.is_file());
    let is_dir = meta.as_ref().is_some_and(|m| m.is_dir());

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("exists".to_string(), Value::Bool(exists));
    result.insert("is_file".to_string(), Value::Bool(is_file));
    result.insert("is_dir".to_string(), Value::Bool(is_dir));

    Ok(Value::Record(result))
}

/// file_mkdir(path) - Create a directory (and parents if needed)
fn bi_file_mkdir(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = match args.first().or(input.as_ref()) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("file_mkdir requires a path")),
    };

    // Creates a directory at a caller-named path, with no guard until now:
    // `WriteLocal` is not centrally enforced, so nothing jailed it.
    let path = guard_local_write("file_mkdir", &path)?;

    let already_exists = std::path::Path::new(&path).exists();

    fs::create_dir_all(&path)
        .map_err(|error| crate::safety::fs_error("file_mkdir", &path, &error))?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("created".to_string(), Value::Bool(!already_exists));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

// ===================== A2A (Agent-to-Agent) Protocol =====================

lazy_static::lazy_static! {
    /// A2A agent registry - maps agent names to their connection info
    static ref A2A_REGISTRY: std::sync::RwLock<BTreeMap<String, BTreeMap<String, Value>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };

    /// A2A message queue - pending messages for each agent
    static ref A2A_MESSAGES: std::sync::RwLock<BTreeMap<String, Vec<Value>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };
}

/// Most undelivered messages one agent's queue holds.
const A2A_QUEUE_MAX: usize = 1024;
/// Largest message a2a_send accepts, measured as its display text.
const A2A_MESSAGE_MAX: usize = 64 * 1024;
/// Most agents one process registers (the registry was unbounded).
const A2A_AGENTS_MAX: usize = 256;
/// Most agents one a2a_broadcast reaches in a single call.
const A2A_BROADCAST_RECIPIENTS_MAX: usize = 64;
/// Largest info Record a2a_register stores, measured as its display text.
const A2A_INFO_MAX: usize = 64 * 1024;

/// a2a.send(target, message) - Queue a message for a registered agent. The
/// queue is in-process: nothing leaves the process, so it needs no network guard.
fn bi_a2a_send(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("a2a_send", &input)?;
    let target = collab_text_arg("a2a_send", "target", args.first(), 128)?;
    let message = args
        .get(1)
        .cloned()
        .ok_or_else(|| crate::safety::bad_arg("a2a_send", "message: any value", "nothing"))?;
    let size = message.to_display_string().len();
    if size > A2A_MESSAGE_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_send",
            format!("a2a_send: the message is {size} bytes; at most {A2A_MESSAGE_MAX} are sent"),
            "send a reference to the data instead of the data",
        ));
    }
    let registry = A2A_REGISTRY
        .read()
        .map_err(|_| crate::safety::lock_poisoned("a2a_send", "the A2A agent registry"))?;
    if !registry.contains_key(&target) {
        return Err(crate::safety::not_found("a2a_send", "agent", &target));
    }
    drop(registry);

    let mut messages = A2A_MESSAGES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("a2a_send", "the A2A message queue"))?;
    let queue = messages.entry(target.clone()).or_default();
    if queue.len() >= A2A_QUEUE_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_send",
            format!("a2a_send: {target} has {A2A_QUEUE_MAX} undelivered messages"),
            "a2a_receive drains an agent's queue",
        ));
    }
    queue.push(message);

    let mut result = BTreeMap::new();
    result.insert("sent".to_string(), Value::Bool(true));
    result.insert("target".to_string(), Value::Str(target));
    Ok(Value::Record(result))
}

/// a2a.receive(agent_name?) - Receive pending messages
fn bi_a2a_receive(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let agent_name = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .unwrap_or_else(|| "default".to_string());
    let mut messages = A2A_MESSAGES.write().unwrap();
    let pending = messages.remove(&agent_name).unwrap_or_default();
    Ok(Value::Array(pending))
}

/// a2a.broadcast(message) - Broadcast to all agents. All or nothing: a refusal
/// (too large, too many recipients, a full queue) leaves every queue as it was.
fn bi_a2a_broadcast(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("a2a_broadcast", &input)?;
    if args.is_empty() {
        return Err(crate::safety::arg_err("a2a.broadcast: requires a message"));
    }
    if args.len() > 1 {
        return Err(crate::safety::bad_arg(
            "a2a_broadcast",
            "one message",
            &format!("{} arguments", args.len()),
        ));
    }
    let message = args[0].clone();
    let size = message.to_display_string().len();
    if size > A2A_MESSAGE_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_broadcast",
            format!("the message is {size} bytes; at most {A2A_MESSAGE_MAX} are sent"),
            "send a reference to the data instead of the data",
        ));
    }
    let registry = A2A_REGISTRY
        .read()
        .map_err(|_| crate::safety::lock_poisoned("a2a_broadcast", "the A2A agent registry"))?;
    let agents: Vec<String> = registry.keys().cloned().collect();
    drop(registry);
    if agents.len() > A2A_BROADCAST_RECIPIENTS_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_broadcast",
            format!(
                "{} agents are registered; a broadcast reaches at most {A2A_BROADCAST_RECIPIENTS_MAX}",
                agents.len()
            ),
            "send to the agents by name with a2a_send",
        ));
    }
    let mut messages = A2A_MESSAGES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("a2a_broadcast", "the A2A message queue"))?;
    // Check every recipient's queue before pushing to any of them.
    for agent in &agents {
        if messages.get(agent).map_or(0, Vec::len) >= A2A_QUEUE_MAX {
            return Err(crate::safety::budget_exceeded(
                "a2a_broadcast",
                format!("{agent} has {A2A_QUEUE_MAX} undelivered messages"),
                "a2a_receive drains an agent's queue",
            ));
        }
    }
    for agent in &agents {
        messages
            .entry(agent.clone())
            .or_default()
            .push(message.clone());
    }
    let mut result = BTreeMap::new();
    result.insert("broadcast".to_string(), Value::Bool(true));
    result.insert("recipients".to_string(), Value::Int(agents.len() as i64));
    Ok(Value::Record(result))
}

/// a2a.discover() - Discover available agents
fn bi_a2a_discover(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let agents: Vec<Value> = registry
        .iter()
        .map(|(name, info)| {
            let mut agent = info.clone();
            agent.insert("name".to_string(), Value::Str(name.clone()));
            Value::Record(agent)
        })
        .collect();
    Ok(Value::Array(agents))
}

/// a2a.register(name, info?) - Register an agent
fn bi_a2a_register(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("a2a_register", &input)?;
    if args.is_empty() {
        return Err(crate::safety::arg_err("a2a.register: requires agent name"));
    }
    if args.len() > 2 {
        return Err(crate::safety::bad_arg(
            "a2a_register",
            "a name and an optional info Record",
            &format!("{} arguments", args.len()),
        ));
    }
    let name = collab_text_arg("a2a_register", "name", args.first(), 128)?;
    // An info that is not a Record used to be replaced by an empty one without
    // a word. Refuse it instead.
    let info = match args.get(1) {
        None | Some(Value::Null) => BTreeMap::new(),
        Some(Value::Record(rec)) => rec.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "a2a_register",
                "info: a Record",
                other.type_name(),
            ))
        }
    };
    let info_size = Value::Record(info.clone()).to_display_string().len();
    if info_size > A2A_INFO_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_register",
            format!("info is {info_size} bytes; at most {A2A_INFO_MAX} are kept"),
            "register a name and a reference to the details",
        ));
    }
    let mut registry = A2A_REGISTRY
        .write()
        .map_err(|_| crate::safety::lock_poisoned("a2a_register", "the A2A agent registry"))?;
    // Re-registering a name replaces its info and does not grow the registry.
    if !registry.contains_key(&name) && registry.len() >= A2A_AGENTS_MAX {
        return Err(crate::safety::budget_exceeded(
            "a2a_register",
            format!("{A2A_AGENTS_MAX} agents are already registered"),
            "a2a_unregister an agent that is no longer running",
        ));
    }
    registry.insert(name.clone(), info);
    let mut result = BTreeMap::new();
    result.insert("registered".to_string(), Value::Bool(true));
    result.insert("name".to_string(), Value::Str(name.to_string()));
    Ok(Value::Record(result))
}

/// a2a.unregister(name) - Unregister an agent
fn bi_a2a_unregister(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "a2a.unregister: requires agent name",
        ));
    }
    let name = args[0]
        .as_str()
        .map_err(|_| crate::safety::arg_err("a2a.unregister: name must be a string"))?;
    let mut registry = A2A_REGISTRY.write().unwrap();
    let removed = registry.remove(name).is_some();
    let mut messages = A2A_MESSAGES.write().unwrap();
    messages.remove(name);
    let mut result = BTreeMap::new();
    result.insert("unregistered".to_string(), Value::Bool(removed));
    result.insert("name".to_string(), Value::Str(name.to_string()));
    Ok(Value::Record(result))
}

/// a2a.status() - Get A2A subsystem status
fn bi_a2a_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let messages = A2A_MESSAGES.read().unwrap();
    let pending_count: usize = messages.values().map(|v| v.len()).sum();
    let mut result = BTreeMap::new();
    result.insert("active".to_string(), Value::Bool(true));
    result.insert("agents".to_string(), Value::Int(registry.len() as i64));
    result.insert(
        "pending_messages".to_string(),
        Value::Int(pending_count as i64),
    );
    Ok(Value::Record(result))
}

/// a2a.agents() - List all registered agents
fn bi_a2a_agents(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let agents: Vec<Value> = registry
        .keys()
        .map(|name| Value::Str(name.clone()))
        .collect();
    Ok(Value::Array(agents))
}

// ===================== NANDA (Consensus) Protocol =====================

// A local tally, not a distributed consensus. A proposal names its electorate
// (`electorate`, an Int 1..=1024, default 1) and each vote is one ballot cast
// against it. Nothing identifies the voter, so the electorate is the caller's
// assertion and one caller can cast every ballot. Quorum is half the
// electorate: a proposal commits only when that many ballots are in and the
// approval ratio is at least its threshold. A decided proposal takes no
// further ballots. The store holds at most NANDA_MAX_PROPOSALS and evicts the
// oldest decided proposal when a new one needs the room.

const NANDA_MAX_PROPOSALS: usize = 256;
const NANDA_MAX_ELECTORATE: i64 = 1024;
const NANDA_MAX_DATA_FIELDS: usize = 64;
/// Keys the proposal record owns. A caller's `data` cannot overwrite them.
const NANDA_RESERVED: &[&str] = &[
    "id",
    "name",
    "threshold",
    "electorate",
    "status",
    "votes_cast",
    "approvals",
];

struct NandaProposal {
    seq: u64,
    name: String,
    threshold: f64,
    electorate: usize,
    ballots: Vec<bool>,
    status: &'static str,
    data: BTreeMap<String, Value>,
}

static NANDA_SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

lazy_static::lazy_static! {
    static ref NANDA_PROPOSALS: std::sync::RwLock<BTreeMap<String, NandaProposal>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };
}

fn nanda_uuid() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let bytes: [u8; 16] = rng.gen();
    format!(
        "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
        u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]),
        u16::from_be_bytes([bytes[4], bytes[5]]),
        u16::from_be_bytes([bytes[6], bytes[7]]) & 0x0fff,
        (u16::from_be_bytes([bytes[8], bytes[9]]) & 0x3fff) | 0x8000,
        u64::from_be_bytes([
            0, 0, bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]
        ])
    )
}

/// `(cast, approvals)` for a proposal.
fn nanda_tally(p: &NandaProposal) -> (usize, usize) {
    let cast = p.ballots.len();
    let approvals = p.ballots.iter().filter(|b| **b).count();
    (cast, approvals)
}

/// Half the electorate has balloted. An electorate of at least one means a
/// quorum always has at least one ballot behind it, so no ratio divides by zero.
fn nanda_has_quorum(p: &NandaProposal) -> bool {
    2 * p.ballots.len() >= p.electorate
}

fn nanda_record(id: &str, p: &NandaProposal) -> BTreeMap<String, Value> {
    let (cast, approvals) = nanda_tally(p);
    let mut rec = p.data.clone();
    rec.insert("id".to_string(), Value::Str(id.to_string()));
    rec.insert("name".to_string(), Value::Str(p.name.clone()));
    rec.insert("threshold".to_string(), Value::Float(p.threshold));
    rec.insert("electorate".to_string(), Value::Int(p.electorate as i64));
    rec.insert("status".to_string(), Value::Str(p.status.to_string()));
    rec.insert("votes_cast".to_string(), Value::Int(cast as i64));
    rec.insert("approvals".to_string(), Value::Int(approvals as i64));
    rec
}

/// Refuse pipeline input for a builtin that documents no subject. What was
/// piped in would otherwise be dropped without a word.
fn refuse_piped_subject(builtin: &str, input: &Option<Value>) -> Result<()> {
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            builtin,
            "no pipeline input",
            "piped input",
        ));
    }
    Ok(())
}

/// A required, non-empty String of at most `max` bytes.
fn collab_text_arg(builtin: &str, what: &str, v: Option<&Value>, max: usize) -> Result<String> {
    match v {
        Some(Value::Str(s)) if !s.trim().is_empty() && s.len() <= max => Ok(s.clone()),
        Some(Value::Str(s)) if s.len() > max => Err(crate::safety::bad_arg(
            builtin,
            &format!("{what}: a String of at most {max} bytes"),
            &format!("a String of {} bytes", s.len()),
        )),
        Some(Value::Str(_)) => Err(crate::safety::bad_arg(
            builtin,
            &format!("{what}: a non-empty String"),
            "an empty String",
        )),
        other => Err(crate::safety::bad_arg(
            builtin,
            &format!("{what}: a non-empty String"),
            other.map(|v| v.type_name()).unwrap_or("nothing"),
        )),
    }
}

/// The value of a scalar as it should appear in a refusal: `0.7`, not `Float`.
fn collab_got(v: &Value) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Float(x) => x.to_string(),
        other => other.type_name().to_string(),
    }
}

/// nanda_propose(name, data) - Open a proposal in the local tally.
/// `data.threshold` is a Float in (0, 1] (default 0.5); `data.electorate` an
/// Int in 1..=1024 (default 1). Other fields are kept on the record.
fn bi_nanda_propose(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_propose", &input)?;
    let name = collab_text_arg("nanda_propose", "name", args.first(), 256)?;
    let data = match args.get(1) {
        Some(Value::Record(r)) => r,
        other => {
            return Err(crate::safety::bad_arg(
                "nanda_propose",
                "data: Record",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let threshold = match data.get("threshold") {
        None => 0.5,
        Some(Value::Float(t)) if *t > 0.0 && *t <= 1.0 => *t,
        Some(Value::Int(1)) => 1.0,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "nanda_propose",
                "threshold: a Float in (0, 1]",
                &collab_got(other),
            ))
        }
    };
    let electorate = match data.get("electorate") {
        None => 1,
        Some(Value::Int(n)) if (1..=NANDA_MAX_ELECTORATE).contains(n) => *n as usize,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "nanda_propose",
                "electorate: an Int in 1..=1024",
                &collab_got(other),
            ))
        }
    };
    if data.len() > NANDA_MAX_DATA_FIELDS {
        return Err(crate::safety::budget_exceeded(
            "nanda_propose",
            format!(
                "nanda_propose: data has {} fields; a proposal holds at most {NANDA_MAX_DATA_FIELDS}",
                data.len()
            ),
            "send the proposal's detail in fewer fields",
        ));
    }
    let mut extra = data.clone();
    for key in NANDA_RESERVED {
        extra.remove(*key);
    }

    let id = format!("prop_{}", nanda_uuid());
    let mut proposals = NANDA_PROPOSALS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("nanda_propose", "the NANDA proposal table"))?;
    if proposals.len() >= NANDA_MAX_PROPOSALS {
        let oldest_decided = proposals
            .iter()
            .filter(|(_, p)| p.status != "pending")
            .min_by_key(|(_, p)| p.seq)
            .map(|(k, _)| k.clone());
        match oldest_decided {
            Some(k) => {
                proposals.remove(&k);
            }
            None => {
                return Err(crate::safety::budget_exceeded(
                    "nanda_propose",
                    format!(
                        "nanda_propose: {NANDA_MAX_PROPOSALS} proposals are pending and none is decided"
                    ),
                    "commit or abort a pending proposal, then propose again",
                ))
            }
        }
    }
    let proposal = NandaProposal {
        seq: NANDA_SEQ.fetch_add(1, std::sync::atomic::Ordering::SeqCst),
        name,
        threshold,
        electorate,
        ballots: Vec::new(),
        status: "pending",
        data: extra,
    };
    let rec = nanda_record(&id, &proposal);
    proposals.insert(id, proposal);
    Ok(Value::Record(rec))
}

/// nanda_vote(proposal_id, approve) - Cast one ballot on a pending proposal.
fn bi_nanda_vote(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_vote", &input)?;
    let proposal_id = collab_text_arg("nanda_vote", "proposal_id", args.first(), 128)?;
    let approve = match args.get(1) {
        Some(Value::Bool(b)) => *b,
        other => {
            return Err(crate::safety::bad_arg(
                "nanda_vote",
                "approve: Bool",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let mut proposals = NANDA_PROPOSALS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("nanda_vote", "the NANDA proposal table"))?;
    let p = proposals
        .get_mut(&proposal_id)
        .ok_or_else(|| crate::safety::not_found("nanda_vote", "proposal", &proposal_id))?;
    if p.status != "pending" {
        return Err(crate::safety::bad_state(
            "nanda_vote",
            &format!(
                "proposal {proposal_id} is {}; a decided proposal takes no votes",
                p.status
            ),
            "nanda_status",
        ));
    }
    if p.ballots.len() >= p.electorate {
        return Err(crate::safety::budget_exceeded(
            "nanda_vote",
            format!(
                "nanda_vote: all {} ballots of {proposal_id} are cast",
                p.electorate
            ),
            "a proposal takes exactly its electorate's ballots; commit it or propose another",
        ));
    }
    p.ballots.push(approve);
    let mut rec = BTreeMap::new();
    rec.insert("voted".to_string(), Value::Bool(true));
    rec.insert("proposal_id".to_string(), Value::Str(proposal_id));
    rec.insert("approve".to_string(), Value::Bool(approve));
    rec.insert("ballot".to_string(), Value::Int(p.ballots.len() as i64));
    rec.insert("votes_cast".to_string(), Value::Int(p.ballots.len() as i64));
    rec.insert("electorate".to_string(), Value::Int(p.electorate as i64));
    Ok(Value::Record(rec))
}

/// nanda_commit(proposal_id) - Commit a pending proposal with quorum and an
/// approval ratio at or above its threshold. Below the threshold it is rejected.
fn bi_nanda_commit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_commit", &input)?;
    let proposal_id = collab_text_arg("nanda_commit", "proposal_id", args.first(), 128)?;
    let mut proposals = NANDA_PROPOSALS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("nanda_commit", "the NANDA proposal table"))?;
    let p = proposals
        .get_mut(&proposal_id)
        .ok_or_else(|| crate::safety::not_found("nanda_commit", "proposal", &proposal_id))?;
    if p.status != "pending" {
        return Err(crate::safety::bad_state(
            "nanda_commit",
            &format!(
                "proposal {proposal_id} is {}; only a pending proposal commits",
                p.status
            ),
            "nanda_status",
        ));
    }
    if !nanda_has_quorum(p) {
        let (cast, _) = nanda_tally(p);
        return Err(crate::safety::bad_state(
            "nanda_commit",
            &format!(
                "no quorum: {cast} of {} ballots are cast and at least half are needed",
                p.electorate
            ),
            "nanda_vote",
        ));
    }
    let (cast, approvals) = nanda_tally(p);
    let ratio = approvals as f64 / cast as f64;
    if ratio < p.threshold {
        p.status = "rejected";
        return Err(crate::safety::policy_deny(
            "nanda_commit",
            format!(
                "consensus not reached: approval {:.0}% is below the threshold {:.0}%; {proposal_id} is now rejected",
                ratio * 100.0,
                p.threshold * 100.0
            ),
            "a rejected proposal takes no further ballots; propose again",
        ));
    }
    p.status = "committed";
    let mut rec = BTreeMap::new();
    rec.insert("committed".to_string(), Value::Bool(true));
    rec.insert("proposal_id".to_string(), Value::Str(proposal_id));
    rec.insert("approval_ratio".to_string(), Value::Float(ratio));
    rec.insert("threshold".to_string(), Value::Float(p.threshold));
    rec.insert("votes_cast".to_string(), Value::Int(cast as i64));
    rec.insert("electorate".to_string(), Value::Int(p.electorate as i64));
    Ok(Value::Record(rec))
}

/// nanda_abort(proposal_id) - Abort a pending proposal.
fn bi_nanda_abort(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_abort", &input)?;
    let proposal_id = collab_text_arg("nanda_abort", "proposal_id", args.first(), 128)?;
    let mut proposals = NANDA_PROPOSALS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("nanda_abort", "the NANDA proposal table"))?;
    let p = proposals
        .get_mut(&proposal_id)
        .ok_or_else(|| crate::safety::not_found("nanda_abort", "proposal", &proposal_id))?;
    if p.status != "pending" {
        return Err(crate::safety::bad_state(
            "nanda_abort",
            &format!(
                "proposal {proposal_id} is {}; only a pending proposal aborts",
                p.status
            ),
            "nanda_status",
        ));
    }
    p.status = "aborted";
    let mut rec = BTreeMap::new();
    rec.insert("aborted".to_string(), Value::Bool(true));
    rec.insert("proposal_id".to_string(), Value::Str(proposal_id));
    rec.insert("status".to_string(), Value::Str("aborted".to_string()));
    Ok(Value::Record(rec))
}

/// nanda_status(proposal_id?) - One proposal's record, or every proposal's.
fn bi_nanda_status(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_status", &input)?;
    let proposals = NANDA_PROPOSALS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("nanda_status", "the NANDA proposal table"))?;
    match args.first() {
        None => Ok(Value::Array(
            proposals
                .iter()
                .map(|(id, p)| Value::Record(nanda_record(id, p)))
                .collect(),
        )),
        Some(Value::Str(id)) => {
            let p = proposals
                .get(id)
                .ok_or_else(|| crate::safety::not_found("nanda_status", "proposal", id))?;
            Ok(Value::Record(nanda_record(id, p)))
        }
        Some(other) => Err(crate::safety::bad_arg(
            "nanda_status",
            "proposal_id: String",
            other.type_name(),
        )),
    }
}

/// nanda_consensus(proposal_id) - Whether the tally reaches consensus now: a
/// quorum of ballots, and an approval ratio at or above the threshold.
fn bi_nanda_consensus(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_consensus", &input)?;
    let proposal_id = collab_text_arg("nanda_consensus", "proposal_id", args.first(), 128)?;
    let proposals = NANDA_PROPOSALS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("nanda_consensus", "the NANDA proposal table"))?;
    let p = proposals
        .get(&proposal_id)
        .ok_or_else(|| crate::safety::not_found("nanda_consensus", "proposal", &proposal_id))?;
    let (cast, approvals) = nanda_tally(p);
    let ratio = if cast > 0 {
        approvals as f64 / cast as f64
    } else {
        0.0
    };
    let quorum = nanda_has_quorum(p);
    let mut rec = BTreeMap::new();
    rec.insert(
        "reached".to_string(),
        Value::Bool(quorum && cast > 0 && ratio >= p.threshold),
    );
    rec.insert("quorum_reached".to_string(), Value::Bool(quorum));
    rec.insert("approval_ratio".to_string(), Value::Float(ratio));
    rec.insert("threshold".to_string(), Value::Float(p.threshold));
    rec.insert("total_votes".to_string(), Value::Int(cast as i64));
    rec.insert("approvals".to_string(), Value::Int(approvals as i64));
    rec.insert("electorate".to_string(), Value::Int(p.electorate as i64));
    rec.insert("status".to_string(), Value::Str(p.status.to_string()));
    Ok(Value::Record(rec))
}

/// nanda_quorum(proposal_id) - How much of the electorate has balloted.
fn bi_nanda_quorum(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("nanda_quorum", &input)?;
    let proposal_id = collab_text_arg("nanda_quorum", "proposal_id", args.first(), 128)?;
    let proposals = NANDA_PROPOSALS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("nanda_quorum", "the NANDA proposal table"))?;
    let p = proposals
        .get(&proposal_id)
        .ok_or_else(|| crate::safety::not_found("nanda_quorum", "proposal", &proposal_id))?;
    let (cast, _) = nanda_tally(p);
    let mut rec = BTreeMap::new();
    rec.insert(
        "quorum_reached".to_string(),
        Value::Bool(nanda_has_quorum(p)),
    );
    rec.insert(
        "participation".to_string(),
        Value::Float(cast as f64 / p.electorate as f64),
    );
    rec.insert("votes_cast".to_string(), Value::Int(cast as i64));
    rec.insert("electorate".to_string(), Value::Int(p.electorate as i64));
    Ok(Value::Record(rec))
}

// ============== AI CODING ASSISTANT BUILTINS ==============

// Git module implementations
//
// Every git builtin refuses pipeline input and surplus arguments (the
// declarations in src/signature.rs enforce the arity and types), runs git
// with an argv vector and no shell, and turns a failed git into a coded
// error: E_BAD_STATE outside a repository, E_TOOL_FAILED with the tail of
// what git printed otherwise. None answers a failure with false, "" or [].

/// Refuse pipeline input: a git builtin acts on the repository, and what was
/// piped in would otherwise be dropped without a word.
fn git_refuse_input(builtin: &str, input: &Option<Value>) -> Result<()> {
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            builtin,
            "no pipeline input",
            "piped input",
        ));
    }
    Ok(())
}

/// The last 4 KiB of what git printed when it failed: stderr, or stdout when
/// stderr is empty (`git commit` says "nothing to commit" on stdout alone).
fn git_failure_tail(output: &std::process::Output) -> String {
    const TAIL: usize = 4096;
    let raw = if output.stderr.iter().all(|b| b.is_ascii_whitespace()) {
        &output.stdout
    } else {
        &output.stderr
    };
    let text = String::from_utf8_lossy(raw);
    if text.len() <= TAIL {
        return text.into_owned();
    }
    let mut start = text.len() - TAIL;
    while !text.is_char_boundary(start) {
        start += 1;
    }
    format!("...{}", &text[start..])
}

/// `git` exited non-zero. Every git builtin read stdout and ignored the
/// status, so outside a repository -- where git prints only to stderr --
/// `git_status()` was `[]`, `git_branch()` was `""` and `git_log()` was `[]`,
/// all at exit 0: "clean", "detached" and "no history", none of them true.
fn git_succeeded(builtin: &str, output: &std::process::Output, dir: &str) -> Result<()> {
    if output.status.success() {
        return Ok(());
    }
    // Ask git rather than read its stderr: outside a repository `git status`
    // says "not a git repository", `git diff` says "Not a git repository" and
    // prints usage, `git diff --staged` says only "unknown option", and all
    // of it is translated under a non-English locale.
    let mut cmd = std::process::Command::new("git");
    cmd.args(["rev-parse", "--is-inside-work-tree"]);
    cmd.current_dir(dir);
    let in_repo = bounded_cmd_output("git_succeeded", "git", cmd, TOOL_DEADLINE_SECS)
        .is_ok_and(|o| o.status.success());
    if !in_repo {
        return Err(crate::safety::bad_state(
            builtin,
            "the working directory is not inside a git repository",
            "cd into a repository (or pass its path where the builtin takes one)",
        ));
    }
    Err(crate::safety::tool_failed(
        builtin,
        "git",
        output.status.code(),
        &git_failure_tail(output),
    ))
}

/// The directory a read-only git builtin runs in. It is the child's working
/// directory rather than an argument, and spawning into a missing directory
/// fails the same way a missing git does, so it is named here first.
fn git_dir_arg(builtin: &str, path: &str) -> Result<String> {
    if std::path::Path::new(path).is_dir() {
        Ok(path.to_string())
    } else {
        Err(crate::safety::not_found(builtin, "directory", path))
    }
}

/// The first argument as a ref, branch or commit name. Empty and NUL-bearing
/// values are refused before they reach argv. The caller refuses a leading
/// '-' at its own spawn site, where `reject_option_like` must be visible.
fn git_ref_arg(builtin: &str, args: &[Value], what: &str) -> Result<String> {
    let value = match args.first() {
        Some(v) => expect_string(builtin, v)?.to_string(),
        None => return Err(crate::safety::arg_err(format!("{builtin} requires {what}"))),
    };
    if value.trim().is_empty() || value.contains('\0') {
        return Err(crate::safety::bad_arg(builtin, what, &format!("{value:?}")));
    }
    Ok(value)
}

fn bi_git_status(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    git_refuse_input("git_status", &input)?;
    let path = match args.first() {
        Some(v) => expect_string("git_status", v)?.to_string(),
        None => ".".to_string(),
    };
    let path = git_dir_arg("git_status", &path)?;
    let mut cmd = std::process::Command::new("git");
    cmd.args(["status", "--porcelain", "-b"]);
    cmd.current_dir(&path);
    let output = bounded_cmd_output("git_status", "git", cmd, TOOL_DEADLINE_SECS)?;
    git_succeeded("git_status", &output, &path)?;
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let lines: Vec<Value> = stdout.lines().map(|l| Value::Str(l.to_string())).collect();
    Ok(Value::Array(lines))
}

