// Project module implementations
fn bi_project_type(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if std::path::Path::new("Cargo.toml").exists() {
        return Ok(Value::Str("rust".to_string()));
    }
    if std::path::Path::new("package.json").exists() {
        return Ok(Value::Str("node".to_string()));
    }
    if std::path::Path::new("pyproject.toml").exists() || std::path::Path::new("setup.py").exists()
    {
        return Ok(Value::Str("python".to_string()));
    }
    if std::path::Path::new("go.mod").exists() {
        return Ok(Value::Str("go".to_string()));
    }
    if std::path::Path::new("pom.xml").exists() {
        return Ok(Value::Str("java".to_string()));
    }
    Ok(Value::Str("unknown".to_string()))
}

fn bi_project_root(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut cmd = std::process::Command::new("git");
    cmd.args(["rev-parse", "--show-toplevel"]);
    // The doc promises no fallback, so a directory that is not a repository
    // (or no git at all) is not reported as the root. It used to answer the
    // current directory for every failure, which named a subdirectory as the
    // project root.
    let output = bounded_cmd_output("project_root", "git", cmd, TOOL_DEADLINE_SECS);
    let cwd = std::env::current_dir()?.to_string_lossy().to_string();
    match output {
        Ok(o) if o.status.success() => Ok(Value::Str(
            String::from_utf8_lossy(&o.stdout).trim().to_string(),
        )),
        Ok(o) if String::from_utf8_lossy(&o.stderr).contains("not a git repository") => Err(
            crate::safety::not_found("project_root", "project root", &cwd),
        ),
        Ok(o) => Err(crate::safety::tool_failed(
            "project_root",
            "git rev-parse --show-toplevel",
            o.status.code(),
            &String::from_utf8_lossy(&o.stderr),
        )),
        // No git is E_TOOL_MISSING from the spawn, not "no project root".
        Err(e) => Err(e),
    }
}

/// Read a manifest that may be absent. `None` means the file does not exist.
/// Other read errors are coded errors, not an empty answer.
fn project_manifest_optional(builtin: &str, path: &str) -> Result<Option<String>> {
    match std::fs::read_to_string(path) {
        Ok(text) => Ok(Some(text)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(crate::safety::fs_error(builtin, path, &e)),
    }
}

/// Read a Cargo.toml that must exist. A missing file is a coded not_found.
fn project_cargo_text(builtin: &str) -> Result<String> {
    match project_manifest_optional(builtin, "Cargo.toml")? {
        Some(text) => Ok(text),
        None => Err(crate::safety::not_found(
            builtin,
            "Cargo.toml",
            "Cargo.toml",
        )),
    }
}

/// The `name = "..."` value in Cargo.toml text. Old code returned "unknown"
/// when the value was absent or malformed.
fn cargo_name_from_text(builtin: &str, text: &str) -> Result<String> {
    for line in text.lines() {
        if line.starts_with("name = ") {
            if let Some(name) = line.split('"').nth(1) {
                return Ok(name.to_string());
            }
        }
    }
    Err(crate::safety::bad_state(
        builtin,
        "Cargo.toml has no name = line",
        "project_type",
    ))
}

/// The `version = "..."` value in Cargo.toml text. Old code returned "0.0.0"
/// when the value was absent or malformed.
fn cargo_version_from_text(builtin: &str, text: &str) -> Result<String> {
    for line in text.lines() {
        if line.starts_with("version = ") {
            if let Some(version) = line.split('"').nth(1) {
                return Ok(version.to_string());
            }
        }
    }
    Err(crate::safety::bad_state(
        builtin,
        "Cargo.toml has no version = line",
        "project_type",
    ))
}

/// A top-level string field of package.json text, such as `"name"`.
fn package_json_field(content: &str, field: &str) -> Option<String> {
    match serde_json::from_str::<serde_json::Value>(content)
        .ok()?
        .get(field)?
    {
        serde_json::Value::String(v) => Some(v.clone()),
        _ => None,
    }
}

/// The keys listed under one Cargo.toml table header (for example
/// `[dependencies]`). A table with no entries gives an empty list, which is a
/// real answer; a missing Cargo.toml is handled by the caller.
fn cargo_section_keys(text: &str, header: &str) -> Vec<Value> {
    let mut keys = Vec::new();
    let mut in_section = false;
    for line in text.lines() {
        if line.starts_with(header) {
            in_section = true;
            continue;
        }
        if line.starts_with("[") {
            in_section = false;
        }
        if in_section && line.contains("=") {
            keys.push(Value::Str(
                line.split('=').next().unwrap_or("").trim().to_string(),
            ));
        }
    }
    keys
}

fn bi_project_name(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const B: &str = "project_name";
    let cargo = project_manifest_optional(B, "Cargo.toml")?;
    if let Some(text) = &cargo {
        if let Ok(name) = cargo_name_from_text(B, text) {
            return Ok(Value::Str(name));
        }
    }
    let pkg = project_manifest_optional(B, "package.json")?;
    if let Some(name) = pkg.as_deref().and_then(|t| package_json_field(t, "name")) {
        return Ok(Value::Str(name));
    }
    if cargo.is_none() && pkg.is_none() {
        return Err(crate::safety::not_found(B, "Cargo.toml", "Cargo.toml"));
    }
    Err(crate::safety::bad_state(
        B,
        "no name in Cargo.toml or package.json",
        "project_type",
    ))
}

fn bi_project_version(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const B: &str = "project_version";
    // A Node project has no Cargo.toml; read its package.json as
    // project_name does, rather than answer "0.0.0" or refuse it.
    if let Some(text) = project_manifest_optional(B, "Cargo.toml")? {
        return Ok(Value::Str(cargo_version_from_text(B, &text)?));
    }
    match project_manifest_optional(B, "package.json")? {
        Some(text) => package_json_field(&text, "version")
            .map(Value::Str)
            .ok_or_else(|| {
                crate::safety::bad_state(B, "package.json has no \"version\"", "project_type")
            }),
        None => Err(crate::safety::not_found(
            B,
            "Cargo.toml or package.json",
            ".",
        )),
    }
}

fn bi_project_dependencies(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let text = project_cargo_text("project_dependencies")?;
    Ok(Value::Array(cargo_section_keys(&text, "[dependencies]")))
}

fn bi_project_dev_dependencies(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let text = project_cargo_text("project_dev_dependencies")?;
    Ok(Value::Array(cargo_section_keys(
        &text,
        "[dev-dependencies]",
    )))
}

#[cfg(test)]
mod quiet_misc_tests {
    use super::*;

    #[test]
    fn cargo_version_is_read_from_package_section() {
        let text = "[package]\nname = \"ae\"\nversion = \"1.2.3\"\n";
        assert_eq!(
            cargo_version_from_text("project_version", text).unwrap(),
            "1.2.3"
        );
    }

    #[test]
    fn cargo_version_missing_is_an_error_not_0_0_0() {
        let text = "[package]\nname = \"ae\"\n";
        assert!(cargo_version_from_text("project_version", text).is_err());
    }

    #[test]
    fn cargo_name_is_read_from_package_section() {
        let text = "[package]\nname = \"ae\"\nversion = \"1.2.3\"\n";
        assert_eq!(cargo_name_from_text("project_name", text).unwrap(), "ae");
    }

    #[test]
    fn cargo_name_missing_is_an_error_not_unknown() {
        let text = "[package]\nversion = \"1.2.3\"\n";
        assert!(cargo_name_from_text("project_name", text).is_err());
    }

    #[test]
    fn cargo_section_keys_empty_table_is_a_real_empty_list() {
        let text = "[package]\nname = \"ae\"\n\n[dependencies]\n\n[dev-dependencies]\nx = \"1\"\n";
        assert!(cargo_section_keys(text, "[dependencies]").is_empty());
        assert_eq!(cargo_section_keys(text, "[dev-dependencies]").len(), 1);
    }
}

#[path = "project_manifest.rs"]
mod project_manifest;
fn bi_project_scripts(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    project_manifest::guard_and_discover(args, input)
}

fn bi_project_structure(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut files = Vec::new();
    // An unreadable directory used to be skipped, so its entries silently
    // vanished from a listing that looked complete. It is an error now.
    fn walk(dir: &std::path::Path, files: &mut Vec<Value>, depth: usize) -> Result<()> {
        if depth > 3 {
            return Ok(());
        }
        let entries = match std::fs::read_dir(dir) {
            Ok(entries) => entries,
            // Removed since its parent listed it: nothing left to report.
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(crate::safety::fs_error("project_structure", dir, &e)),
        };
        for entry in entries {
            let entry = entry.map_err(|e| crate::safety::fs_error("project_structure", dir, &e))?;
            let path = entry.path();
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default();
            if name.starts_with(".") || name == "target" || name == "node_modules" {
                continue;
            }
            files.push(Value::Str(path.to_string_lossy().to_string()));
            if entry_is_dir("project_structure", &path)? {
                walk(&path, files, depth + 1)?;
            }
        }
        Ok(())
    }
    walk(std::path::Path::new("."), &mut files, 0)?;
    Ok(Value::Array(files))
}

fn bi_project_entry_points(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut entries = Vec::new();
    if std::path::Path::new("src/main.rs").exists() {
        entries.push(Value::Str("src/main.rs".to_string()));
    }
    if std::path::Path::new("src/lib.rs").exists() {
        entries.push(Value::Str("src/lib.rs".to_string()));
    }
    if std::path::Path::new("index.js").exists() {
        entries.push(Value::Str("index.js".to_string()));
    }
    if std::path::Path::new("main.py").exists() {
        entries.push(Value::Str("main.py".to_string()));
    }
    Ok(Value::Array(entries))
}

fn bi_project_test_files(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut tests = Vec::new();
    // A tests/ directory that cannot be listed used to read as no tests.
    let dir = std::path::Path::new("tests");
    if entry_is_dir("project_test_files", dir)? {
        let entries = std::fs::read_dir(dir)
            .map_err(|e| crate::safety::fs_error("project_test_files", dir, &e))?;
        for entry in entries {
            let entry =
                entry.map_err(|e| crate::safety::fs_error("project_test_files", dir, &e))?;
            tests.push(Value::Str(entry.path().to_string_lossy().to_string()));
        }
    }
    Ok(Value::Array(tests))
}

fn bi_project_config_files(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let configs = [
        "Cargo.toml",
        "package.json",
        "pyproject.toml",
        "tsconfig.json",
        ".eslintrc.json",
        "rustfmt.toml",
    ];
    let found: Vec<Value> = configs
        .iter()
        .filter(|c| std::path::Path::new(c).exists())
        .map(|c| Value::Str(c.to_string()))
        .collect();
    Ok(Value::Array(found))
}

// Each reader used to turn any read error (permission, not UTF-8, I/O) into
// Null, the same answer as "no such file". Only a missing file is Null now.
fn bi_project_readme(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    first_project_text(
        "project_readme",
        &["README.md", "README.txt", "README", "readme.md"],
    )
}

fn bi_project_license(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    first_project_text("project_license", &["LICENSE", "LICENSE.md", "LICENSE.txt"])
}

fn bi_project_gitignore(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    first_project_text("project_gitignore", &[".gitignore"])
}

fn bi_project_languages(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut langs = std::collections::HashSet::new();
    fn check_ext(path: &std::path::Path, langs: &mut std::collections::HashSet<String>) {
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            let lang = match ext {
                "rs" => "Rust",
                "py" => "Python",
                "js" => "JavaScript",
                "ts" => "TypeScript",
                "go" => "Go",
                "java" => "Java",
                "rb" => "Ruby",
                "c" | "h" => "C",
                "cpp" | "hpp" => "C++",
                "sh" => "Shell",
                _ => return,
            };
            langs.insert(lang.to_string());
        }
    }
    // An unreadable directory used to be skipped, so its languages silently
    // dropped out of the answer. It is an error now.
    fn walk(
        dir: &std::path::Path,
        langs: &mut std::collections::HashSet<String>,
        depth: usize,
    ) -> Result<()> {
        if depth > 3 {
            return Ok(());
        }
        let entries = match std::fs::read_dir(dir) {
            Ok(entries) => entries,
            // Removed since its parent listed it: nothing left to report.
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(crate::safety::fs_error("project_languages", dir, &e)),
        };
        for entry in entries {
            let entry = entry.map_err(|e| crate::safety::fs_error("project_languages", dir, &e))?;
            let path = entry.path();
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default();
            if name.starts_with(".") || name == "target" || name == "node_modules" {
                continue;
            }
            if entry_is_dir("project_languages", &path)? {
                walk(&path, langs, depth + 1)?;
            } else if entry_is_file("project_languages", &path)? {
                check_ext(&path, langs);
            }
        }
        Ok(())
    }
    walk(std::path::Path::new("."), &mut langs, 0)?;
    Ok(Value::Array(langs.into_iter().map(Value::Str).collect()))
}

/// Source lines under the working directory.
///
/// This ran `wc -l src/*.rs`. There is no shell between `Command::new` and
/// `wc`, so nothing expanded the glob: `wc` was handed a file literally named
/// `src/*.rs`, failed, and the function fell through to `Ok(Value::Int(0))`.
/// It reported 0 lines for every project on every platform, and reported it as
/// a fact rather than a failure. Counting in Rust removes both the glob and
/// the subprocess.
fn bi_project_loc(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    Ok(Value::Int(project_loc_in(std::path::Path::new("."))?))
}

/// The count behind `project_loc`, over `root`. Split out so that the tests
/// can point it at a temporary tree; the builtin itself always counts `.`.
fn project_loc_in(root: &std::path::Path) -> Result<i64> {
    const SOURCE_EXT: &[&str] = &[
        "rs", "py", "js", "ts", "tsx", "jsx", "go", "java", "c", "h", "cc", "cpp", "hpp", "cs",
        "rb", "sh", "ae", "lua", "kt", "swift", "php", "scala",
    ];
    // Directories that are build output or vendored code: counting them
    // measures someone else's project, and on a Rust tree `target/` alone
    // dwarfs the source.
    const SKIP: &[&str] = &[
        "target",
        "node_modules",
        ".git",
        "dist",
        "build",
        "vendor",
        ".venv",
        "__pycache__",
    ];

    /// Lines as `str::lines` counts them: one per newline, plus a final line
    /// that has no newline after it.
    fn count_lines(bytes: &[u8]) -> i64 {
        let newlines = bytes.iter().filter(|b| **b == b'\n').count();
        let unterminated = !bytes.is_empty() && bytes.last() != Some(&b'\n');
        (newlines + usize::from(unterminated)) as i64
    }

    fn count(dir: &std::path::Path, total: &mut i64, budget: &mut u32) -> Result<()> {
        // A budget rather than unbounded recursion: this is called from an
        // agent loop, and a symlinked or pathological tree must not cost the
        // whole turn. Exhausting it is reported as E_BUDGET_EXCEEDED, never as
        // a number -- a partial count returned as an Int is indistinguishable
        // from a small project, which is the defect this replaced.
        if *budget == 0 {
            return Ok(());
        }
        // An unreadable directory used to be skipped, so its sources were
        // missing from the total and the total was returned as the count.
        let entries =
            std::fs::read_dir(dir).map_err(|e| crate::safety::fs_error("project_loc", dir, &e))?;
        for entry in entries {
            let entry = entry.map_err(|e| crate::safety::fs_error("project_loc", dir, &e))?;
            *budget = budget.saturating_sub(1);
            if *budget == 0 {
                return Ok(());
            }
            let path = entry.path();
            let name = entry.file_name();
            let name = name.to_string_lossy();
            if entry_is_dir("project_loc", &path)? {
                if !SKIP.contains(&name.as_ref()) && !name.starts_with('.') {
                    count(&path, total, budget)?;
                }
            } else if path
                .extension()
                .and_then(|e| e.to_str())
                .is_some_and(|e| SOURCE_EXT.contains(&e))
            {
                // Bytes, not `read_to_string`: that refused any non-UTF-8 file
                // (Latin-1 source, say), and the file counted as 0 lines.
                let bytes = match read_bytes_capped("project_loc", &path) {
                    Ok(bytes) => bytes,
                    // Removed since it was listed, or a dangling symlink.
                    Err(e) if capped_read_not_found(&e) => continue,
                    Err(e) => return Err(e),
                };
                *total += count_lines(&bytes);
            }
        }
        Ok(())
    }

    let mut total = 0i64;
    const BUDGET: u32 = 200_000;
    let mut budget = BUDGET;
    count(root, &mut total, &mut budget)?;
    if budget == 0 {
        return Err(crate::safety::budget_exceeded(
            "project_loc",
            format!("stopped after {BUDGET} directory entries; the count is partial"),
            "run it against a subdirectory, or exclude generated trees",
        ));
    }
    Ok(total)
}

fn bi_project_size(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut total: u64 = 0;
    // An unreadable directory or entry used to be skipped, and a failed stat
    // counted as 0 bytes: the size was the sum of what happened to be readable.
    fn walk(dir: &std::path::Path, total: &mut u64, depth: usize) -> Result<()> {
        if depth > 5 {
            return Ok(());
        }
        let entries =
            std::fs::read_dir(dir).map_err(|e| crate::safety::fs_error("project_size", dir, &e))?;
        for entry in entries {
            let path = entry
                .map_err(|e| crate::safety::fs_error("project_size", dir, &e))?
                .path();
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default();
            if name.starts_with(".") || name == "target" || name == "node_modules" {
                continue;
            }
            if entry_is_dir("project_size", &path)? {
                walk(&path, total, depth + 1)?;
            } else {
                match std::fs::metadata(&path) {
                    Ok(meta) if meta.is_file() => *total += meta.len(),
                    Ok(_) => {}
                    // Removed since it was listed, or a dangling symlink.
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                    Err(e) => return Err(crate::safety::fs_error("project_size", &path, &e)),
                }
            }
        }
        Ok(())
    }
    walk(std::path::Path::new("."), &mut total, 0)?;
    Ok(Value::Int(total as i64))
}
// ---------------------------------------------------------------------------
// Recursive search helpers for the `search_*` family
// ---------------------------------------------------------------------------

/// Directories a code search must never descend into.
///
/// `search_fixmes` ran `grep -rn FIXME .` with no exclusions. From a project
/// root that walks `node_modules`, `.git` and build output: slow, and full of
/// third-party noise -- `search_todos` returned a TODO from
/// `.git/hooks/sendemail-validate.sample`. Under WSL2, two such walks running
/// at once over `/mnt/c` stalled in 9P (`wchan = p9_client_rpc`, state D)
/// inside `node_modules/lucide-react/dist/esm/icons`, and because
/// `Command::output()` waits forever, the builtin never returned.
const SEARCH_SKIP_DIRS: &[&str] = &[
    "node_modules",
    ".git",
    "target",
    "dist",
    "build",
    "vendor",
    ".venv",
    "__pycache__",
];

/// A search that has not finished in this long is not going to be useful to
/// an agent, and a bounded refusal is worth more than an unbounded wait.
const SEARCH_TIMEOUT_SECS: u64 = 30;

/// Everything a search needs to know about one directory entry.
struct SearchEntry {
    /// `./relative/path`, the form `find .` and `grep -r .` printed.
    shown: String,
    path: std::path::PathBuf,
    is_file: bool,
    meta: std::fs::Metadata,
}

/// Walk `.` in sorted order, skipping [`SEARCH_SKIP_DIRS`] and symlinks, and
/// hand each entry to `visit`.
///
/// This replaces shelling out to `find` and `grep`. The subprocesses were the
/// problem three times over: on Windows `find` is System32\find.exe, `grep` is
/// only present when Git's tools happen to be on PATH, and on WSL two
/// concurrent walks over /mnt/c stalled in 9P until the builtin never returned.
/// A walk in-process is the same everywhere, and it is sorted, where `find`
/// and `grep` printed in whatever order the directory happened to list --
/// which made two identical searches differ.
///
/// Symlinks are skipped, matching what the subprocesses did: `find -type f`
/// excludes them and `grep -r` follows only those named on the command line.
fn search_walk(builtin: &str, visit: &mut dyn FnMut(&SearchEntry) -> Result<()>) -> Result<()> {
    const BUDGET: u32 = 200_000;
    let started = std::time::Instant::now();
    let mut budget = BUDGET;
    let mut stack = vec![(std::path::PathBuf::from("."), String::from("."))];
    while let Some((dir, shown_dir)) = stack.pop() {
        // A directory that cannot be listed used to be skipped with `continue`,
        // and an entry that could not be read was dropped by `flatten`. The
        // search then reported the matches it had found as if they were all.
        let rd = std::fs::read_dir(&dir).map_err(|e| crate::safety::fs_error(builtin, &dir, &e))?;
        let mut entries = Vec::new();
        for entry in rd {
            entries.push(entry.map_err(|e| crate::safety::fs_error(builtin, &dir, &e))?);
        }
        entries.sort_by_key(|e| e.file_name());
        let mut subdirs = Vec::new();
        for entry in entries {
            // A search that has not finished in this long is not going to be
            // useful to an agent. Refusing is worth more than an unbounded wait,
            // and a partial list returned as the whole answer would be the
            // silent wrong answer this family used to give.
            if budget == 0 || started.elapsed().as_secs() >= SEARCH_TIMEOUT_SECS {
                return Err(crate::safety::budget_exceeded(
                    builtin,
                    format!(
                        "stopped after {} entries and {}s; the result would be partial, \
                         so nothing was returned",
                        BUDGET - budget,
                        started.elapsed().as_secs()
                    ),
                    "search a narrower directory",
                ));
            }
            budget -= 1;
            let meta = match std::fs::symlink_metadata(entry.path()) {
                Ok(meta) => meta,
                // Removed since it was listed: nothing left to report.
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => continue,
                Err(e) => return Err(crate::safety::fs_error(builtin, entry.path(), &e)),
            };
            if meta.file_type().is_symlink() {
                continue;
            }
            let name = entry.file_name().to_string_lossy().to_string();
            let shown = format!("{shown_dir}/{name}");
            if meta.is_dir() && SEARCH_SKIP_DIRS.contains(&name.as_str()) {
                continue;
            }
            let item = SearchEntry {
                shown: shown.clone(),
                path: entry.path(),
                is_file: meta.is_file(),
                meta,
            };
            visit(&item)?;
            if item.meta.is_dir() {
                subdirs.push((item.path, shown));
            }
        }
        // Reverse so that popping visits subdirectories in sorted order.
        stack.extend(subdirs.into_iter().rev());
    }
    Ok(())
}

/// Shell-style glob on a file name: `*`, `?` and `[...]` (with `!` or `^`
/// negation and `a-z` ranges) -- what `find -name` accepted.
fn shell_glob(pat: &[char], name: &[char]) -> bool {
    match pat.first() {
        None => name.is_empty(),
        Some('*') => (0..=name.len()).any(|i| shell_glob(&pat[1..], &name[i..])),
        Some('?') => !name.is_empty() && shell_glob(&pat[1..], &name[1..]),
        Some('[') => {
            let Some(close) = pat.iter().skip(2).position(|&c| c == ']').map(|p| p + 2) else {
                // No closing bracket: `[` is a literal, as in the shell.
                return name.first() == Some(&'[') && shell_glob(&pat[1..], &name[1..]);
            };
            let Some(&c) = name.first() else {
                return false;
            };
            let class = &pat[1..close];
            let (negate, class) = match class.first() {
                Some('!') | Some('^') => (true, &class[1..]),
                _ => (false, class),
            };
            let mut hit = false;
            let mut i = 0;
            while i < class.len() {
                if i + 2 < class.len() && class[i + 1] == '-' {
                    hit |= class[i] <= c && c <= class[i + 2];
                    i += 3;
                } else {
                    hit |= class[i] == c;
                    i += 1;
                }
            }
            hit != negate && shell_glob(&pat[close + 1..], &name[1..])
        }
        Some(&p) => name.first() == Some(&p) && shell_glob(&pat[1..], &name[1..]),
    }
}

/// `find .`'s `-size` test: `[+|-]N[c|k|M|G|b]`, where a size is rounded UP
/// to whole units before comparing, and a bare number means 512-byte blocks.
/// `+1M` is "more than one MiB", `-10k` "under ten KiB".
fn find_size_matches(builtin: &str, spec: &str, bytes: u64) -> Result<bool> {
    let (cmp, rest) = match spec.chars().next() {
        Some('+') => ('+', &spec[1..]),
        Some('-') => ('-', &spec[1..]),
        _ => ('=', spec),
    };
    let (digits, unit) = match rest.chars().last() {
        Some(u) if u.is_ascii_alphabetic() => (&rest[..rest.len() - 1], u),
        _ => (rest, 'b'),
    };
    let unit_bytes: u64 = match unit {
        'c' => 1,
        'k' => 1024,
        'M' => 1024 * 1024,
        'G' => 1024 * 1024 * 1024,
        'b' => 512,
        _ => {
            return Err(crate::safety::bad_arg(
                builtin,
                "a find-style size such as +1M, -10k or 100c",
                spec,
            ))
        }
    };
    let n: u64 = digits.parse().map_err(|_| {
        crate::safety::bad_arg(builtin, "a find-style size such as +1M, -10k or 100c", spec)
    })?;
    let units = bytes.div_ceil(unit_bytes);
    Ok(match cmp {
        '+' => units > n,
        '-' => units < n,
        _ => units == n,
    })
}

/// Search file contents for `pattern` under `.`, as `grep -rnI` did: lines
/// printed as `./path:line:text`, binary files skipped.
///
/// The pattern is a Rust regular expression. `grep` read a POSIX basic
/// regular expression, and the two agree on the literals every caller in this
/// file passes (`TODO`, `FIXME`). They differ on grouping -- `foo(` is a
/// literal `(` to grep and an unclosed group here -- so a pattern that does not
/// compile is refused with the reason, never searched for as something else.
fn search_grep(builtin: &str, pattern: &str) -> Result<Vec<String>> {
    let re = regex::Regex::new(pattern).map_err(|e| {
        crate::safety::bad_arg(
            builtin,
            "a regular expression (Rust regex syntax)",
            &e.to_string(),
        )
    })?;
    let mut out = Vec::new();
    search_walk(builtin, &mut |e| {
        if !e.is_file {
            return Ok(());
        }
        let Some(text) = search_read_text(builtin, &e.path, &e.shown)? else {
            return Ok(());
        };
        for (i, line) in text.lines().enumerate() {
            if re.is_match(line) {
                if out.len() >= SEARCH_MAX_RESULTS {
                    return Err(search_budget(builtin));
                }
                out.push(format!("{}:{}:{}", e.shown, i + 1, line));
            }
        }
        Ok(())
    })?;
    Ok(out)
}

/// Find files under `.` by the subset of `find` predicates the `search_*`
/// builtins use: `-type f`, `-name GLOB`, `-mtime -N` and `-size SPEC`.
///
/// Without `-type f` a matching directory is listed too, as `find` did.
fn search_find(builtin: &str, predicates: &[&str]) -> Result<Vec<String>> {
    let mut files_only = false;
    let mut name: Option<Vec<char>> = None;
    let mut newer_than_days: Option<u64> = None;
    let mut size: Option<String> = None;
    let mut it = predicates.iter();
    while let Some(&p) = it.next() {
        match (p, it.next()) {
            ("-type", Some(&"f")) => files_only = true,
            ("-name", Some(&g)) => name = Some(g.chars().collect()),
            ("-mtime", Some(&d)) if d.starts_with('-') => {
                newer_than_days =
                    Some(d[1..].parse().map_err(|_| {
                        crate::safety::bad_arg(builtin, "a whole number of days", d)
                    })?)
            }
            ("-size", Some(&spec)) => size = Some(spec.to_string()),
            (other, _) => {
                // Only reachable by a change to this file, never by a caller:
                // every predicate list is a literal above.
                return Err(crate::safety::arg_err(format!(
                    "{builtin}: unsupported search predicate {other}"
                )));
            }
        }
    }
    let now = std::time::SystemTime::now();
    let mut out = Vec::new();
    search_walk(builtin, &mut |e| {
        if files_only && !e.is_file {
            return Ok(());
        }
        if let Some(g) = &name {
            let base: Vec<char> = e
                .path
                .file_name()
                .map(|n| n.to_string_lossy().chars().collect())
                .unwrap_or_default();
            if !shell_glob(g, &base) {
                return Ok(());
            }
        }
        if let Some(days) = newer_than_days {
            let age = e
                .meta
                .modified()
                .ok()
                .and_then(|m| now.duration_since(m).ok())
                .map(|d| d.as_secs())
                .unwrap_or(u64::MAX);
            if age >= days.saturating_mul(86_400) {
                return Ok(());
            }
        }
        if let Some(spec) = &size {
            if !find_size_matches(builtin, spec, e.meta.len())? {
                return Ok(());
            }
        }
        out.push(e.shown.clone());
        Ok(())
    })?;
    Ok(out)
}

// Search module implementations
fn bi_search_code(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    search_pattern_builtin("search_code", args, input)
}

fn bi_search_grep(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    search_pattern_builtin("search_grep", args, input)
}

fn bi_search_regex(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    search_pattern_builtin("search_regex", args, input)
}

/// The content search behind `search_code`, `search_grep` and `search_regex`:
/// one regular expression, under the workspace, capped at [`SEARCH_MAX_RESULTS`].

fn bi_search_symbols(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let pattern = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("pattern required"))?;
    // This ran `grep -rn "fn X|struct X|class X|def X" .`. Without `-E`, grep
    // reads a BASIC regular expression, in which `|` is a literal pipe -- so it
    // searched for that whole string, matched nothing, and returned [] for
    // every symbol in every project. `search_grep` takes a Rust regex, where
    // `|` alternates as intended; the symbol itself is escaped so that `a.b`
    // means `a.b`.
    let found = search_grep(
        "search_symbols",
        &format!(r"(?:fn|struct|class|def)\s+{}\b", regex::escape(&pattern)),
    )?;
    let matches: Vec<Value> = found
        .iter()
        .take(50)
        .map(|l| Value::Str(l.to_string()))
        .collect();
    Ok(Value::Array(matches))
}

fn bi_search_files(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let pattern = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("pattern required"))?;
    let found = search_find("search_files", &["-name", &pattern])?;
    let files: Vec<Value> = found.iter().map(|l| Value::Str(l.to_string())).collect();
    Ok(Value::Array(files))
}

fn bi_search_recent(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let found = search_find("search_recent", &["-type", "f", "-mtime", "-1"])?;
    let files: Vec<Value> = found
        .iter()
        .take(50)
        .map(|l| Value::Str(l.to_string()))
        .collect();
    Ok(Value::Array(files))
}

fn bi_search_modified(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let days = args.first().and_then(|v| v.as_int().ok()).unwrap_or(7);
    let found = search_find(
        "search_modified",
        &["-type", "f", "-mtime", &format!("-{}", days)],
    )?;
    let files: Vec<Value> = found
        .iter()
        .take(100)
        .map(|l| Value::Str(l.to_string()))
        .collect();
    Ok(Value::Array(files))
}

fn bi_search_by_type(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ext = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("extension required"))?;
    let found = search_find("search_by_type", &["-name", &format!("*.{}", ext)])?;
    let files: Vec<Value> = found.iter().map(|l| Value::Str(l.to_string())).collect();
    Ok(Value::Array(files))
}

fn bi_search_by_size(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "search_by_size";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 1)?;
    let size = match args.first() {
        None => "+1M".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "a find-style size such as +1M, -10k or 100c",
                other.type_name(),
            ))
        }
    };
    // Checked before the walk: an empty tree would otherwise answer [] for a
    // size that was never understood.
    find_size_matches(B, &size, 0)?;
    let found = search_find(B, &["-type", "f", "-size", size.as_str()])?;
    search_list(B, found)
}

