/// diag_fix(dir) - cargo fix, which applies the compiler's machine-applicable
/// suggestions to the project's files. It refuses a version-controlled tree
/// with uncommitted changes, as cargo does by default; --allow-dirty is not
/// passed, so the rewrite never lands on uncommitted work silently.
fn bi_diag_fix(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "diag_fix";
    k8s_no_input(B, &input)?;
    let dir = project_dir(B, args.first())?;
    cargo_done(B, &dir, &["fix"])?;
    Ok(Value::Bool(true))
}

fn bi_diag_explain(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let code = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("error code required"))?;
    crate::safety::reject_option_like("diag_explain", std::slice::from_ref(&code))?;
    let mut cmd = std::process::Command::new("rustc");
    cmd.args(["--explain", &code]);
    let output = bounded_cmd_output("diag_explain", "rustc", cmd, TOOL_DEADLINE_SECS)?;
    // A code rustc does not know ("E9999") answered "".
    if !output.status.success() {
        return Err(crate::safety::tool_failed(
            "diag_explain",
            "rustc --explain",
            output.status.code(),
            &String::from_utf8_lossy(&output.stderr),
        ));
    }
    Ok(Value::Str(
        String::from_utf8_lossy(&output.stdout).to_string(),
    ))
}

