// Session module implementations
use std::sync::atomic::{AtomicU64, Ordering};
static SESSION_COUNTER: AtomicU64 = AtomicU64::new(0);

fn bi_session_start(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = SESSION_COUNTER.fetch_add(1, Ordering::SeqCst);
    Ok(Value::Int(id as i64))
}

/// Refuse arguments and pipeline input for a builtin that takes neither.
fn no_args_or_input(name: &str, args: &[Value], input: &Option<Value>) -> Result<()> {
    if !args.is_empty() {
        return Err(crate::safety::bad_arg(
            name,
            "no arguments",
            &format!("{} argument(s)", args.len()),
        ));
    }
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            name,
            "no pipeline input",
            "piped input",
        ));
    }
    Ok(())
}

/// The optional step count of `session_undo` and `session_redo`: none means 1,
/// otherwise one Int from 1 to 10000. Anything else is refused, not clamped.
fn step_count_arg(name: &str, args: &[Value], input: &Option<Value>) -> Result<usize> {
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            name,
            "no pipeline input",
            "piped input",
        ));
    }
    match args {
        [] => Ok(1),
        [Value::Int(n)] if (1..=10_000).contains(n) => Ok(*n as usize),
        [Value::Int(n)] => Err(crate::safety::bad_arg(
            name,
            "a step count from 1 to 10000",
            &n.to_string(),
        )),
        [other] => Err(crate::safety::bad_arg(
            name,
            "an Int step count",
            other.type_name(),
        )),
        more => Err(crate::safety::bad_arg(
            name,
            "at most one step count",
            &format!("{} arguments", more.len()),
        )),
    }
}

/// `session_end()` — keep every change and forget the journal. No files are
/// touched; after this, nothing recorded can be undone or redone.
fn bi_session_end(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("session_end", &args, &input)?;
    let entries = crate::journal::entries();
    let kept = entries.len();
    let irreversible = entries.iter().filter(|e| !e.reversible()).count();
    let discarded_redo = crate::journal::redo_count();
    crate::journal::clear();
    let mut m = std::collections::BTreeMap::new();
    m.insert("kept".to_string(), Value::Int(kept as i64));
    m.insert("irreversible".to_string(), Value::Int(irreversible as i64));
    m.insert(
        "discarded_redo".to_string(),
        Value::Int(discarded_redo as i64),
    );
    m.insert(
        "note".to_string(),
        Value::Str("no files changed; these steps can no longer be undone or redone".to_string()),
    );
    Ok(Value::Record(m))
}

fn bi_session_id(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    Ok(Value::Int(SESSION_COUNTER.load(Ordering::SeqCst) as i64))
}

/// `session_history()` — the steps that can be undone (`done`) and the steps
/// that can be re-applied (`undone`, most recent last).
fn bi_session_history(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    no_args_or_input("session_history", &args, &input)?;
    let done = crate::journal::entries();
    let undone: Vec<Value> = crate::journal::undone()
        .iter()
        .map(|r| {
            let mut m = std::collections::BTreeMap::new();
            m.insert("seq".to_string(), Value::Int(r.seq as i64));
            m.insert("builtin".to_string(), Value::Str(r.builtin.clone()));
            m.insert("effect".to_string(), Value::Str(r.effect.clone()));
            if !r.path.is_empty() {
                m.insert("path".to_string(), Value::Str(r.path.clone()));
            }
            Value::Record(m)
        })
        .collect();
    let mut out = std::collections::BTreeMap::new();
    out.insert(
        "enabled".to_string(),
        Value::Bool(crate::journal::enabled()),
    );
    out.insert("done".to_string(), Value::Array(journal_rows(&done)));
    out.insert("undone".to_string(), Value::Array(undone));
    Ok(Value::Record(out))
}

/// `session_undo(n = 1)` — the same record `undo(n)` returns.
fn bi_session_undo(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let n = step_count_arg("session_undo", &args, &input)?;
    Ok(Value::Record(rewind_record(
        &crate::journal::undo(n),
        "restored",
    )))
}

/// `session_redo(n = 1)` — re-apply the last `n` undone steps.
fn bi_session_redo(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let n = step_count_arg("session_redo", &args, &input)?;
    Ok(Value::Record(rewind_record(
        &crate::journal::redo(n),
        "reapplied",
    )))
}

fn bi_session_checkpoint(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    git_refuse_input("session_checkpoint", &input)?;
    // A non-string label used to fall back silently to "checkpoint".
    let name = match args.first() {
        Some(v) => expect_string("session_checkpoint", v)?.to_string(),
        None => "checkpoint".to_string(),
    };
    // This ran `git stash push`, which saves the changes and then REMOVES
    // them from the working tree: a "checkpoint" that erased the work it was
    // meant to protect. With nothing to save git exits 0, so it also answered
    // true having saved nothing. `stash create` records the changes without
    // touching the tree; `stash store` keeps that record in the stash list.
    // Both git calls are checked the same way: outside a repository these
    // are E_BAD_STATE, a failed git is E_TOOL_FAILED with its stderr tail.
    let mut cmd = std::process::Command::new("git");
    cmd.args(["stash", "create"]);
    let output = bounded_cmd_output("session_checkpoint", "git", cmd, TOOL_DEADLINE_SECS)?;
    git_succeeded("session_checkpoint", &output, ".")?;
    let sha = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if sha.is_empty() {
        // Not an error: the tree has no changes, so there is nothing to keep.
        return Ok(Value::Bool(false));
    }
    let mut cmd = std::process::Command::new("git");
    cmd.args(["stash", "store", "-m", &name, &sha]);
    let output = bounded_cmd_output("session_checkpoint", "git", cmd, TOOL_DEADLINE_SECS)?;
    git_succeeded("session_checkpoint", &output, ".")?;
    Ok(Value::Bool(true))
}

fn bi_session_restore(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    git_refuse_input("session_restore", &input)?;
    let index = args
        .first()
        .map(|v| expect_int("session_restore", v))
        .transpose()?
        .unwrap_or(0);
    let mut cmd = std::process::Command::new("git");
    cmd.args([
        "rev-parse",
        "--verify",
        "--quiet",
        &format!("stash@{{{}}}", index),
    ]);
    let check = bounded_cmd_output("session_restore", "git", cmd, TOOL_DEADLINE_SECS)?;
    if !check.status.success() {
        // A missing checkpoint is not a git failure: git's own answer for it
        // is exit 1 with no text, which the generic path reported as E_TOOL_FAILED.
        let mut cmd = std::process::Command::new("git");
        cmd.args(["rev-parse", "--is-inside-work-tree"]);
        let in_repo = bounded_cmd_output("session_restore", "git", cmd, TOOL_DEADLINE_SECS)
            .is_ok_and(|o| o.status.success());
        if in_repo {
            return Err(crate::safety::not_found(
                "session_restore",
                "checkpoint",
                &index.to_string(),
            ));
        }
        git_succeeded("session_restore", &check, ".")?;
    }
    let mut cmd = std::process::Command::new("git");
    cmd.args(["stash", "apply", &format!("stash@{{{}}}", index)]);
    let output = bounded_cmd_output("session_restore", "git", cmd, TOOL_DEADLINE_SECS)?;
    // `false` said "not restored" and dropped why: no repository, no such
    // checkpoint, or a conflict. Those need different next steps.
    git_succeeded("session_restore", &output, ".")?;
    Ok(Value::Bool(true))
}

