fn bi_docs_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // In-process, as "file:line: text" like the grep it replaces. That grep
    // took the query as a pattern (a leading `-` was an option), does not
    // exist on Windows, and exited 2 with [] when there were no docs, which
    // read as "no matches".
    let query = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("query required"))?;
    let root = std::path::Path::new("target/doc");
    if !entry_is_dir("docs_search", root)? {
        return Err(crate::safety::not_found(
            "docs_search",
            "documentation directory",
            "target/doc (run `cargo doc` first)",
        ));
    }
    const LIMIT: usize = 20;
    let mut matches = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    // An unreadable directory or entry used to be skipped, so the match list
    // looked complete when it was not. Those are errors now. A file that is
    // not UTF-8 is searched as lossy text, not skipped.
    while let Some(dir) = stack.pop() {
        let mut entries = Vec::new();
        for entry in
            std::fs::read_dir(&dir).map_err(|e| crate::safety::fs_error("docs_search", &dir, &e))?
        {
            let entry = entry.map_err(|e| crate::safety::fs_error("docs_search", &dir, &e))?;
            entries.push(entry.path());
        }
        entries.sort();
        for p in entries {
            if entry_is_dir("docs_search", &p)? {
                stack.push(p);
                continue;
            }
            // Capped like every whole-file read: a doc over the limit is an
            // error, not a search of part of it.
            let bytes = match read_bytes_capped("docs_search", &p) {
                Ok(bytes) => bytes,
                // A dangling link has no text to search.
                Err(e) if capped_read_not_found(&e) => continue,
                Err(e) => return Err(e),
            };
            let text = String::from_utf8_lossy(&bytes);
            for (i, line) in text.lines().enumerate() {
                if line.contains(&query) {
                    matches.push(Value::Str(format!(
                        "{}:{}: {}",
                        p.display(),
                        i + 1,
                        line.trim()
                    )));
                    if matches.len() == LIMIT {
                        return Ok(Value::Array(matches));
                    }
                }
            }
        }
    }
    Ok(Value::Array(matches))
}

