fn bi_env_shell(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // Neither variable set was "", which names no shell. It is not an answer.
    match std::env::var("SHELL").or_else(|_| std::env::var("COMSPEC")) {
        Ok(shell) => Ok(Value::Str(shell)),
        Err(_) => Err(crate::safety::not_found(
            "env_shell",
            "shell",
            "SHELL or COMSPEC",
        )),
    }
}

/// Read one environment variable for a builtin. `Ok(None)` is an unset
/// variable. A variable that is set but not valid UTF-8 is refused: it used
/// to read as unset, which is a different fact from absence.
fn env_read(
    builtin: &str,
    name: &str,
    read: Result<String, std::env::VarError>,
) -> Result<Option<String>> {
    match read {
        Ok(v) => Ok(Some(v)),
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(std::env::VarError::NotUnicode(_)) => Err(crate::safety::bad_state(
            builtin,
            &format!("environment variable `{name}` is set, but its value is not valid UTF-8"),
            "env_set",
        )),
    }
}

fn bi_env_path(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path = std::env::var("PATH").unwrap_or_default();
    let parts: Vec<Value> = path
        .split(if cfg!(windows) { ";" } else { ":" })
        // An empty entry ("a::b", or PATH unset) is no directory.
        .filter(|p| !p.is_empty())
        .map(|p| Value::Str(p.to_string()))
        .collect();
    Ok(Value::Array(parts))
}

fn bi_env_var(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("variable name required"))?;
    // Unset was "", where env() and sys.env() answer null.
    Ok(match env_read("env_var", &name, std::env::var(&name))? {
        Some(v) => gate_env_secret(&name, v),
        None => Value::Null,
    })
}

/// env_vars() - every variable as a Record. In agent mode a value whose name
/// looks like a secret is replaced with a redaction marker, as env_var does.
/// Non-UTF-8 names and values are shown lossily: `std::env::vars` panics on
/// them, so this reads the OS strings.
fn bi_env_vars(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "env_vars";
    k8s_no_input(B, &input)?;
    if !args.is_empty() {
        return Err(crate::safety::bad_arg(
            B,
            "no arguments",
            &format!("{} argument(s)", args.len()),
        ));
    }
    let vars: BTreeMap<String, Value> = std::env::vars_os()
        .map(|(k, v)| {
            let k = k.to_string_lossy().into_owned();
            let gated = gate_env_secret(&k, v.to_string_lossy().into_owned());
            (k, gated)
        })
        .collect();
    Ok(Value::Record(vars))
}

/// env_set(name, value) - set an environment variable of this process.
fn bi_env_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "env_set";
    k8s_no_input(B, &input)?;
    if args.len() < 2 {
        return Err(crate::safety::arg_err("name and value required"));
    }
    let name = env_name(B, &args[0])?;
    refuse_gate_env(B, &name)?;
    let value = env_value(B, &args[1])?;
    std::env::set_var(&name, &value);
    Ok(Value::Bool(true))
}

fn bi_env_unset(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const B: &str = "env_unset";
    let raw = args
        .first()
        .ok_or_else(|| crate::safety::arg_err("variable name required"))?;
    let name = env_name(B, raw)?;
    refuse_gate_env(B, &name)?;
    std::env::remove_var(&name);
    Ok(Value::Bool(true))
}

