fn bi_platform_has_tool(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // With no tool named this asked whether "" is installed, and said no.
    let tool = match args.first() {
        Some(v) => expect_string("platform_has_tool", v)?,
        None => {
            return Err(crate::safety::bad_arg(
                "platform_has_tool",
                "a tool name",
                "nothing",
            ))
        }
    };
    Ok(Value::Bool(on_path(tool)))
}

/// Whether this Windows process is elevated, read from its own token.
///
/// This was `net session` here and PowerShell's
/// `IsInRole(Administrator)` in sudo_check. Both answer the same question as
/// the token's elevation flag (under UAC an administrator's unelevated
/// process is not elevated for any of them), but each started a process, and
/// `net session` also failed, reading as "not admin", when the Server service
/// was stopped.
#[cfg(target_os = "windows")]
fn windows_is_admin(builtin: &str) -> Result<bool> {
    use std::ffi::c_void;
    #[link(name = "kernel32")]
    extern "system" {
        fn GetCurrentProcess() -> *mut c_void;
        fn CloseHandle(handle: *mut c_void) -> i32;
    }
    #[link(name = "advapi32")]
    extern "system" {
        fn OpenProcessToken(process: *mut c_void, access: u32, token: *mut *mut c_void) -> i32;
        fn GetTokenInformation(
            token: *mut c_void,
            class: u32,
            info: *mut c_void,
            len: u32,
            returned: *mut u32,
        ) -> i32;
    }
    const TOKEN_QUERY: u32 = 0x0008;
    const TOKEN_ELEVATION: u32 = 20;
    let failed = |call: &str| {
        crate::safety::bad_state(
            builtin,
            &format!("{call} failed: {}", std::io::Error::last_os_error()),
            "a process token this process can query",
        )
    };
    let mut token: *mut c_void = std::ptr::null_mut();
    // SAFETY: GetCurrentProcess returns a pseudo-handle that needs no close;
    // `token` is a valid out-pointer.
    if unsafe { OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token) } == 0 {
        return Err(failed("OpenProcessToken"));
    }
    let mut elevated: u32 = 0;
    let mut returned: u32 = 0;
    // SAFETY: TOKEN_ELEVATION is a single DWORD, and `elevated` is one.
    let ok = unsafe {
        GetTokenInformation(
            token,
            TOKEN_ELEVATION,
            (&mut elevated as *mut u32).cast(),
            std::mem::size_of::<u32>() as u32,
            &mut returned,
        )
    };
    let result = if ok == 0 {
        Err(failed("GetTokenInformation"))
    } else {
        Ok(elevated != 0)
    };
    // SAFETY: `token` was opened above and is closed once.
    unsafe { CloseHandle(token) };
    result
}

/// The drive types Get-PSDrive -PSProvider FileSystem listed in
/// `bi_fs_df` and `bi_fs_mounts`: fixed, removable, network and RAM-disk
/// roots. CD-ROM drives are not in that set.
#[cfg(target_os = "windows")]
fn windows_listed_by_powershell(drive_type: u32) -> bool {
    matches!(
        drive_type,
        DRIVE_FIXED | DRIVE_REMOVABLE | DRIVE_REMOTE | DRIVE_RAMDISK
    )
}

#[cfg(target_os = "windows")]
const DRIVE_UNKNOWN: u32 = 0;
#[cfg(target_os = "windows")]
const DRIVE_NO_ROOT_DIR: u32 = 1;
#[cfg(target_os = "windows")]
const DRIVE_REMOVABLE: u32 = 2;
#[cfg(target_os = "windows")]
const DRIVE_FIXED: u32 = 3;
#[cfg(target_os = "windows")]
const DRIVE_REMOTE: u32 = 4;
#[cfg(target_os = "windows")]
const DRIVE_RAMDISK: u32 = 6;

/// One drive letter with a root, as kernel32 described it. A field is `None`
/// where the call that answers it failed: an empty card reader or a
/// disconnected network drive has no size and no file system.
#[cfg(target_os = "windows")]
struct WinVolume {
    /// The drive letter, such as 'C'.
    letter: char,
    /// GetDriveTypeW's answer, one of the DRIVE_* constants.
    drive_type: u32,
    /// Total bytes on the volume, from GetDiskFreeSpaceExW.
    total: Option<u64>,
    /// Free bytes, from GetDiskFreeSpaceExW's TotalNumberOfFreeBytes. This is
    /// the figure WMI's FreeSpace and Get-PSDrive's Free reported, not the
    /// caller-available figure.
    free: Option<u64>,
    /// The file system name from GetVolumeInformationW, such as "NTFS".
    fs_name: Option<String>,
    /// The volume label. `Some("")` is an unlabeled volume that answered.
    label: Option<String>,
}

/// [`windows_volumes_now`] on a worker thread, bounded by the probe deadline.
///
/// PowerShell's Get-PSDrive was bounded by it, and these calls need it too:
/// asking a disconnected network drive for its size waits on SMB, which can
/// take longer than that. The worker also turns off the "There is no disk in
/// the drive" dialog an empty removable drive could raise on the desktop.
#[cfg(target_os = "windows")]
fn windows_volumes(builtin: &str) -> Result<Vec<WinVolume>> {
    #[link(name = "kernel32")]
    extern "system" {
        fn SetThreadErrorMode(mode: u32, old: *mut u32) -> i32;
    }
    const SEM_FAILCRITICALERRORS: u32 = 0x0001;
    const SEM_NOOPENFILEERRORBOX: u32 = 0x8000;
    let (tx, rx) = std::sync::mpsc::channel();
    let name = builtin.to_string();
    std::thread::spawn(move || {
        // SAFETY: affects only this worker thread; the old mode is not needed
        // because the thread ends after the walk.
        unsafe {
            SetThreadErrorMode(
                SEM_FAILCRITICALERRORS | SEM_NOOPENFILEERRORBOX,
                std::ptr::null_mut(),
            )
        };
        let _ = tx.send(windows_volumes_now(&name));
    });
    match rx.recv_timeout(std::time::Duration::from_secs(PROBE_DEADLINE_SECS)) {
        Ok(result) => result,
        Err(_) => Err(crate::safety::budget_exceeded(
            builtin,
            format!("the drive table did not answer in {PROBE_DEADLINE_SECS}s"),
            "a network drive may be unreachable; disconnect it or retry",
        )),
    }
}

/// Every drive letter with a root (GetLogicalDrives, GetDriveTypeW). A zero
/// bitmask is a failed call, since no machine has no drive letters.
#[cfg(target_os = "windows")]
fn windows_volumes_now(builtin: &str) -> Result<Vec<WinVolume>> {
    #[link(name = "kernel32")]
    extern "system" {
        fn GetLogicalDrives() -> u32;
        fn GetDriveTypeW(root: *const u16) -> u32;
        fn GetDiskFreeSpaceExW(
            root: *const u16,
            free_to_caller: *mut u64,
            total: *mut u64,
            total_free: *mut u64,
        ) -> i32;
        fn GetVolumeInformationW(
            root: *const u16,
            name: *mut u16,
            name_len: u32,
            serial: *mut u32,
            max_component: *mut u32,
            flags: *mut u32,
            fs_name: *mut u16,
            fs_name_len: u32,
        ) -> i32;
    }
    // MAX_PATH + 1, the buffer size GetVolumeInformationW is documented with.
    const NAME_UNITS: usize = 261;
    let text = |buf: &[u16]| {
        let end = buf.iter().position(|&u| u == 0).unwrap_or(buf.len());
        String::from_utf16_lossy(&buf[..end])
    };
    // SAFETY: GetLogicalDrives takes no arguments and only reads the drive
    // table.
    let mask = unsafe { GetLogicalDrives() };
    if mask == 0 {
        return Err(crate::safety::bad_state(
            builtin,
            &format!(
                "GetLogicalDrives failed: {}",
                std::io::Error::last_os_error()
            ),
            "a readable drive table",
        ));
    }
    let mut volumes = Vec::new();
    for bit in 0..26u32 {
        if mask & (1 << bit) == 0 {
            continue;
        }
        let letter = char::from(b'A' + bit as u8);
        let root: Vec<u16> = format!("{letter}:\\")
            .encode_utf16()
            .chain(std::iter::once(0))
            .collect();
        // SAFETY: `root` is NUL-terminated and lives across the call.
        let drive_type = unsafe { GetDriveTypeW(root.as_ptr()) };
        if drive_type == DRIVE_UNKNOWN || drive_type == DRIVE_NO_ROOT_DIR {
            continue;
        }
        let (mut free_to_caller, mut total, mut total_free) = (0u64, 0u64, 0u64);
        // SAFETY: `root` is NUL-terminated, and each out-pointer is a valid
        // u64 for the call to write.
        let sized = unsafe {
            GetDiskFreeSpaceExW(
                root.as_ptr(),
                &mut free_to_caller,
                &mut total,
                &mut total_free,
            )
        } != 0;
        // An empty or disconnected drive fails here, and its size stays unknown.
        let (size, free) = if sized {
            (Some(total), Some(total_free))
        } else {
            (None, None)
        };
        let mut label_buf = [0u16; NAME_UNITS];
        let mut fs_buf = [0u16; NAME_UNITS];
        // SAFETY: both buffers hold NAME_UNITS units, and the lengths passed
        // say so. The serial, max-component and flags out-pointers are null,
        // which the call accepts.
        let described = unsafe {
            GetVolumeInformationW(
                root.as_ptr(),
                label_buf.as_mut_ptr(),
                NAME_UNITS as u32,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                fs_buf.as_mut_ptr(),
                NAME_UNITS as u32,
            )
        } != 0;
        let (label, fs_name) = if described {
            (Some(text(&label_buf)), Some(text(&fs_buf)))
        } else {
            (None, None)
        };
        volumes.push(WinVolume {
            letter,
            drive_type,
            total: size,
            free,
            fs_name,
            label,
        });
    }
    Ok(volumes)
}

/// A REG_DWORD under HKEY_LOCAL_MACHINE: `Ok(None)` when the key or value is
/// absent, `Err` with the Win32 status for anything else.
#[cfg(target_os = "windows")]
fn windows_hklm_dword(subkey: &str, value: &str) -> std::result::Result<Option<u32>, i32> {
    use std::ffi::c_void;
    #[link(name = "advapi32")]
    extern "system" {
        fn RegGetValueW(
            key: isize,
            subkey: *const u16,
            value: *const u16,
            flags: u32,
            kind: *mut u32,
            data: *mut c_void,
            len: *mut u32,
        ) -> i32;
    }
    const HKEY_LOCAL_MACHINE: isize = 0x8000_0002u32 as i32 as isize;
    const RRF_RT_REG_DWORD: u32 = 0x0000_0010;
    const ERROR_FILE_NOT_FOUND: i32 = 2;
    let wide = |s: &str| {
        s.encode_utf16()
            .chain(std::iter::once(0))
            .collect::<Vec<u16>>()
    };
    let (subkey, value) = (wide(subkey), wide(value));
    let mut data: u32 = 0;
    let mut len = std::mem::size_of::<u32>() as u32;
    // SAFETY: both names are NUL-terminated, and RRF_RT_REG_DWORD writes at
    // most `len` (4) bytes into `data`.
    let status = unsafe {
        RegGetValueW(
            HKEY_LOCAL_MACHINE,
            subkey.as_ptr(),
            value.as_ptr(),
            RRF_RT_REG_DWORD,
            std::ptr::null_mut(),
            (&mut data as *mut u32).cast(),
            &mut len,
        )
    };
    match status {
        0 => Ok(Some(data)),
        ERROR_FILE_NOT_FOUND => Ok(None),
        other => Err(other),
    }
}

/// A REG_SZ under HKEY_LOCAL_MACHINE, as [`windows_hklm_dword`] reads a
/// DWORD.
#[cfg(target_os = "windows")]
fn windows_hklm_string(subkey: &str, value: &str) -> std::result::Result<Option<String>, i32> {
    windows_hklm_string_from(subkey, value, 128)
}

/// [`windows_hklm_string`] starting from a buffer of `units` UTF-16 units,
/// so a test can make it grow.
#[cfg(target_os = "windows")]
fn windows_hklm_string_from(
    subkey: &str,
    value: &str,
    units: usize,
) -> std::result::Result<Option<String>, i32> {
    use std::ffi::c_void;
    #[link(name = "advapi32")]
    extern "system" {
        fn RegGetValueW(
            key: isize,
            subkey: *const u16,
            value: *const u16,
            flags: u32,
            kind: *mut u32,
            data: *mut c_void,
            len: *mut u32,
        ) -> i32;
    }
    const HKEY_LOCAL_MACHINE: isize = 0x8000_0002u32 as i32 as isize;
    const RRF_RT_REG_SZ: u32 = 0x0000_0002;
    const ERROR_FILE_NOT_FOUND: i32 = 2;
    let wide = |s: &str| {
        s.encode_utf16()
            .chain(std::iter::once(0))
            .collect::<Vec<u16>>()
    };
    let (subkey, value) = (wide(subkey), wide(value));
    let mut buf = vec![0u16; units.max(1)];
    loop {
        let mut len = (buf.len() * 2) as u32;
        // SAFETY: both names are NUL-terminated, and RegGetValueW writes at
        // most `len` bytes into `buf`, NUL included.
        let status = unsafe {
            RegGetValueW(
                HKEY_LOCAL_MACHINE,
                subkey.as_ptr(),
                value.as_ptr(),
                RRF_RT_REG_SZ,
                std::ptr::null_mut(),
                buf.as_mut_ptr().cast(),
                &mut len,
            )
        };
        match status {
            0 => {
                let units = (len as usize / 2).min(buf.len());
                let text = &buf[..units];
                let end = text.iter().position(|&u| u == 0).unwrap_or(text.len());
                return Ok(Some(String::from_utf16_lossy(&text[..end])));
            }
            ERROR_FILE_NOT_FOUND => return Ok(None),
            // ERROR_MORE_DATA: `len` is the size needed.
            234 if (len as usize) / 2 > buf.len() => buf = vec![0u16; len as usize / 2 + 1],
            other => return Err(other),
        }
    }
}

/// Processor 0's clock in MHz as the kernel measured it at boot, from the
/// registry, without starting PowerShell to ask WMI. It is not quite WMI's
/// MaxClockSpeed, the rated figure: on one host 4392 where WMI said 4400.
#[cfg(target_os = "windows")]
fn windows_cpu_mhz(builtin: &str) -> Result<Option<u32>> {
    windows_hklm_dword(r"HARDWARE\DESCRIPTION\System\CentralProcessor\0", "~MHz").map_err(
        |status| {
            crate::safety::bad_state(
                builtin,
                &format!(
                    "the processor's ~MHz registry value could not be read: {}",
                    std::io::Error::from_raw_os_error(status)
                ),
                "a readable HKLM\\HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",
            )
        },
    )
}

fn bi_platform_capabilities(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut caps = std::collections::BTreeMap::new();

    // Admin/sudo
    #[cfg(target_os = "windows")]
    {
        // Check if running as admin
        let is_admin = windows_is_admin("platform_capabilities")?;
        caps.insert("has_admin".to_string(), Value::Bool(is_admin));
        caps.insert("has_sudo".to_string(), Value::Bool(false));
    }
    #[cfg(not(target_os = "windows"))]
    {
        caps.insert(
            "has_admin".to_string(),
            Value::Bool(unsafe { libc::geteuid() } == 0),
        );
        caps.insert("has_sudo".to_string(), Value::Bool(on_path("sudo")));
    }

    // GUI
    #[cfg(target_os = "windows")]
    {
        caps.insert("has_gui".to_string(), Value::Bool(true));
    }
    #[cfg(target_os = "macos")]
    {
        caps.insert("has_gui".to_string(), Value::Bool(true));
    }
    #[cfg(target_os = "linux")]
    {
        let has_display =
            std::env::var("DISPLAY").is_ok() || std::env::var("WAYLAND_DISPLAY").is_ok();
        caps.insert("has_gui".to_string(), Value::Bool(has_display));
    }

    // Network: a routable interface address. This was a hard-coded true.
    caps.insert("has_network".to_string(), Value::Bool(host_has_network()));

    // Container runtimes
    caps.insert("has_docker".to_string(), Value::Bool(on_path("docker")));
    caps.insert("has_podman".to_string(), Value::Bool(on_path("podman")));
    caps.insert(
        "has_container".to_string(),
        Value::Bool(on_path("docker") || on_path("podman")),
    );

    // Package managers
    let mut pkg_mgrs = Vec::new();
    if on_path("apt") {
        pkg_mgrs.push("apt");
    }
    if on_path("dnf") {
        pkg_mgrs.push("dnf");
    }
    if on_path("yum") {
        pkg_mgrs.push("yum");
    }
    if on_path("pacman") {
        pkg_mgrs.push("pacman");
    }
    if on_path("brew") {
        pkg_mgrs.push("brew");
    }
    if on_path("choco") {
        pkg_mgrs.push("choco");
    }
    if on_path("winget") {
        pkg_mgrs.push("winget");
    }
    if on_path("scoop") {
        pkg_mgrs.push("scoop");
    }
    if on_path("snap") {
        pkg_mgrs.push("snap");
    }
    if on_path("flatpak") {
        pkg_mgrs.push("flatpak");
    }
    caps.insert(
        "pkg_managers".to_string(),
        Value::Array(
            pkg_mgrs
                .into_iter()
                .map(|s| Value::Str(s.to_string()))
                .collect(),
        ),
    );

    Ok(Value::Record(caps))
}

