// ============================================================================
// Kubernetes & Helm Builtins (850-879)
// kubectl, helm operations with structured output
// ============================================================================

// ---------------------------------------------------------------------------
// kubectl runner shared by every k8s_* builtin.
//
// argv only, never a shell. A hard deadline ends a call that hangs (a rollout
// that never finishes, an API server that does not answer). Output is bounded:
// stdout is held up to `max_bytes` and refused beyond that, and stderr keeps
// only its tail. A nonzero exit is a coded E_TOOL_FAILED carrying that tail; a
// kubectl that is not installed is E_TOOL_MISSING.
// ---------------------------------------------------------------------------

/// How long one kubectl call may run before it is killed.
const K8S_DEADLINE_SECS: u64 = 30;
/// Largest text output: describe, logs, apply, exec, cluster-info, top.
const K8S_MAX_TEXT: usize = 4 * 1024 * 1024;
/// Largest JSON output: get and the list builtins.
const K8S_MAX_JSON: usize = 16 * 1024 * 1024;
/// The last bytes of stderr kept for a failure message.
const K8S_STDERR_TAIL: usize = 2048;
/// Log lines k8s_logs returns when no tail is given, and the most it will return.
const K8S_LOG_DEFAULT_TAIL: i64 = 200;
const K8S_LOG_MAX_TAIL: i64 = 10_000;
/// Largest replica count k8s_scale will request.
const K8S_MAX_REPLICAS: i64 = 1_000;
/// Most argv elements k8s_exec will pass to a container.
const K8S_MAX_EXEC_ARGV: usize = 256;

/// A check that turns one caller string into a value kubectl may be given.
type K8sCheck = fn(&str, &str, &str) -> Result<String>;

/// Run `kubectl` with `args` and return its stdout.
fn kubectl_run(builtin: &str, args: &[&str], max_bytes: usize) -> Result<String> {
    kubectl_run_program(builtin, "kubectl", args, max_bytes, K8S_DEADLINE_SECS)
}

/// [`kubectl_run`] with the program and the deadline given, so a test can aim
/// it at a stand-in. Through the shared bounded runner: past `deadline_secs`
/// the whole process tree is killed and the call is a coded budget error, and
/// a grandchild that keeps the pipes open cannot hold the call.
fn kubectl_run_program(
    builtin: &str,
    program: &str,
    args: &[&str],
    max_bytes: usize,
    deadline_secs: u64,
) -> Result<String> {
    let command = format!("{program} {}", args.join(" "));
    let run = run_tree(
        program,
        args,
        |_| {},
        None,
        std::time::Duration::from_secs(deadline_secs),
        Keep::Head(max_bytes),
        Keep::Tail(K8S_STDERR_TAIL),
    )
    .map_err(|e| match e {
        TreeError::Spawn(e) => crate::safety::spawn_error(builtin, program, &e),
        TreeError::Wait(e) => crate::safety::tool_failed(builtin, &command, None, &e.to_string()),
    })?;
    if run.timed_out {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{command}` did not finish within {deadline_secs} s"),
            "check that the cluster answers, or narrow the call",
        ));
    }
    if !run.success {
        return Err(crate::safety::tool_failed(
            builtin,
            &command,
            run.code,
            &String::from_utf8_lossy(&run.stderr),
        ));
    }
    if run.stdout_truncated {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{command}` printed more than {max_bytes} bytes"),
            "narrow the call: give a namespace or a name, or ask for fewer lines",
        ));
    }
    Ok(String::from_utf8_lossy(&run.stdout).into_owned())
}

/// Test hook: [`kubectl_run`] against `program` with a chosen deadline. Not
/// part of the public API.
#[doc(hidden)]
pub fn __test_kubectl_run(
    program: &str,
    args: &[&str],
    max_bytes: usize,
    deadline_secs: u64,
) -> Result<String> {
    kubectl_run_program("test", program, args, max_bytes, deadline_secs)
}

/// Run `kubectl` with JSON output and parse it.
fn kubectl_json(builtin: &str, args: &[&str], max_bytes: usize) -> Result<Value> {
    let text = kubectl_run(builtin, args, max_bytes)?;
    match serde_json::from_str::<serde_json::Value>(&text) {
        Ok(json) => Ok(json_to_value(json)),
        Err(e) => Err(crate::safety::tool_failed(
            builtin,
            &format!("kubectl {}", args.join(" ")),
            Some(0),
            &format!("printed output that is not JSON ({e})"),
        )),
    }
}

/// A resource type, object name, context or namespace as kubectl will read it:
/// 1-253 letters, digits or `-._/:@,`, and never a leading `-`, which kubectl
/// would take for a flag. The leading-`-` refusal is the option-injection
/// guard; the character set keeps everything else inside what names can be.
fn k8s_token(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.len() <= 253
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "-._/:@,".contains(c));
    if !well_formed {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be 1-253 characters of letters, digits or -._/:@, (got {value:?})"
        )));
    }
    Ok(value.to_string())
}

/// A Kubernetes object name or namespace: the token rule, narrowed to letters,
/// digits, `-` and `.`, so no resource path or list separator can be smuggled
/// into a `type/name` argument.
fn k8s_object_name(builtin: &str, what: &str, value: &str) -> Result<String> {
    let name = k8s_token(builtin, what, value)?;
    if name
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.')
    {
        Ok(name)
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is a Kubernetes object name (letters, digits, '-' and '.'), got {value:?}"
        )))
    }
}

/// The string argument at `index`, checked, when it is present.
fn k8s_arg(
    builtin: &str,
    what: &str,
    args: &[Value],
    index: usize,
    check: K8sCheck,
) -> Result<Option<String>> {
    match args.get(index) {
        None => Ok(None),
        Some(Value::Str(s)) => check(builtin, what, s).map(Some),
        Some(other) => Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be a String, got {}",
            other.type_name()
        ))),
    }
}

/// The string argument at `index`, checked, and required.
fn k8s_need(
    builtin: &str,
    what: &str,
    args: &[Value],
    index: usize,
    check: K8sCheck,
) -> Result<String> {
    k8s_arg(builtin, what, args, index, check)?
        .ok_or_else(|| crate::safety::arg_err(format!("{builtin} requires {what}")))
}

/// Refuse a pipeline subject. None of the k8s_* builtins takes one, and an
/// ignored subject would look like a filtered result.
fn k8s_no_input(builtin: &str, input: &Option<Value>) -> Result<()> {
    if input.is_some() {
        return Err(crate::safety::arg_err(format!(
            "{builtin} takes no pipeline input"
        )));
    }
    Ok(())
}

/// Refuse more arguments than the builtin takes; none is silently dropped.
fn k8s_max_args(builtin: &str, args: &[Value], max: usize) -> Result<()> {
    if args.len() > max {
        return Err(crate::safety::arg_err(format!(
            "{builtin} takes at most {max} argument(s), got {}",
            args.len()
        )));
    }
    Ok(())
}

/// Append `-n <namespace>` when a namespace was given.
fn k8s_push_ns<'a>(cmd: &mut Vec<&'a str>, ns: Option<&'a str>) {
    if let Some(ns) = ns {
        cmd.extend(["-n", ns]);
    }
}

/// `kubectl get <resource> -o json`, for the list builtins. A namespaced list
/// takes an optional namespace; a cluster-scoped one takes no arguments.
fn k8s_list(
    builtin: &str,
    resource: &str,
    namespaced: bool,
    args: &[Value],
    input: Option<Value>,
) -> Result<Value> {
    k8s_no_input(builtin, &input)?;
    k8s_max_args(builtin, args, usize::from(namespaced))?;
    let ns = if namespaced {
        k8s_arg(builtin, "namespace", args, 0, k8s_object_name)?
    } else {
        None
    };
    let mut cmd: Vec<&str> = vec!["get", "-o", "json"];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.extend(["--", resource]);
    kubectl_json(builtin, &cmd, K8S_MAX_JSON)
}

// ---------------------------------------------------------------------------
// Helm and Terraform: one bounded runner, and the argument checks both share
// ---------------------------------------------------------------------------

/// Deadline for the quick calls: reads of local or cluster state.
const TOOL_DEADLINE_SECS: u64 = 120;
/// Deadline for calls that can run for minutes: provider downloads, plans that
/// refresh, applies, destroys, and helm installs and upgrades.
const TOOL_LONG_DEADLINE_SECS: u64 = 900;
/// The most output a call that prints JSON may produce.
const TOOL_MAX_JSON: usize = 16 * 1024 * 1024;
/// The most output a read-only text call may produce.
const TOOL_MAX_TEXT: usize = 4 * 1024 * 1024;
/// Output kept from a call that changes state. Its work is finished by the time
/// its report is read, so an oversized report keeps its end and says so.
const TOOL_KEEP_TAIL: usize = 256 * 1024;
/// Stderr kept for a failure message.
const TOOL_STDERR_TAIL: usize = 2048;
/// The most `--set` overrides one helm call passes.
const HELM_MAX_SET: usize = 256;
/// The longest Terraform workspace name.
const TF_MAX_WORKSPACE: usize = 90;

/// How much of a call's output is kept.
#[derive(Clone, Copy)]
pub(crate) enum Keep {
    /// The first `n` bytes. More is an error: a read cut short would look whole.
    Head(usize),
    /// The last `n` bytes, with a note when earlier output was dropped.
    Tail(usize),
}

/// One finished call: how it ended and what it printed.
pub(crate) struct ToolRun {
    pub(crate) command: String,
    pub(crate) keep: Keep,
    pub(crate) success: bool,
    pub(crate) code: Option<i32>,
    pub(crate) stdout: String,
    pub(crate) stdout_truncated: bool,
    pub(crate) stderr: String,
    /// Whether earlier stderr was dropped to fit `stderr_keep` (the tail is kept).
    pub(crate) stderr_truncated: bool,
}

/// Read a pipe to its end, keeping its last `keep` bytes, and report whether
/// more than that was printed.
fn tool_read_tail(mut pipe: impl std::io::Read, keep: usize) -> (Vec<u8>, bool) {
    let mut buf: Vec<u8> = Vec::new();
    let mut total: usize = 0;
    let mut chunk = [0u8; 8192];
    loop {
        match pipe.read(&mut chunk) {
            Ok(0) | Err(_) => break,
            Ok(n) => {
                total = total.saturating_add(n);
                buf.extend_from_slice(&chunk[..n]);
                if buf.len() > 2 * keep {
                    let cut = buf.len() - keep;
                    buf.drain(..cut);
                }
            }
        }
    }
    let truncated = total > keep;
    if buf.len() > keep {
        let cut = buf.len() - keep;
        buf.drain(..cut);
    }
    (buf, truncated)
}

/// Run `program` with `args` in `dir` (the process's directory when `None`),
/// directly and never through a shell, with stdin closed. Past `deadline_secs`
/// the child is killed and the call is refused. Nothing is judged here: the
/// caller decides what a finished call means.
fn tool_run(
    builtin: &str,
    program: &str,
    dir: Option<&std::path::Path>,
    args: &[&str],
    keep: Keep,
    deadline_secs: u64,
) -> Result<ToolRun> {
    tool_run_stderr(
        builtin,
        program,
        dir,
        args,
        keep,
        TOOL_STDERR_TAIL,
        deadline_secs,
    )
}

/// [`tool_run`] that keeps `stderr_keep` bytes of stderr instead of the usual
/// failure-message tail. A tool whose report is written to stderr (valgrind)
/// needs more than the tail; its failure message is cut again by the caller.
fn tool_run_stderr(
    builtin: &str,
    program: &str,
    dir: Option<&std::path::Path>,
    args: &[&str],
    keep: Keep,
    stderr_keep: usize,
    deadline_secs: u64,
) -> Result<ToolRun> {
    let mut run = run_bounded(
        builtin,
        program,
        dir,
        args,
        keep,
        stderr_keep,
        deadline_secs,
    )?;
    run.stderr = strip_ansi(&run.stderr).trim().to_string();
    Ok(run)
}

/// The bounded runner behind [`tool_run_stderr`], with stderr left as the
/// program wrote it. Stdout keeps `keep` and stderr its last `stderr_keep`
/// bytes. Past `deadline_secs` the whole process tree is killed and the call is
/// refused. Never through a shell, with stdin closed.
pub(crate) fn run_bounded(
    builtin: &str,
    program: &str,
    dir: Option<&std::path::Path>,
    args: &[&str],
    keep: Keep,
    stderr_keep: usize,
    deadline_secs: u64,
) -> Result<ToolRun> {
    let command = format!("{program} {}", args.join(" "));
    let run = run_tree(
        program,
        args,
        |cmd| {
            if let Some(dir) = dir {
                cmd.current_dir(dir);
            }
            if program == "terraform" {
                // Automation mode drops the interactive "run terraform apply" hints.
                cmd.env("TF_IN_AUTOMATION", "1");
            }
        },
        None,
        std::time::Duration::from_secs(deadline_secs),
        keep,
        Keep::Tail(stderr_keep),
    )
    .map_err(|e| match e {
        TreeError::Spawn(e) => crate::safety::spawn_error(builtin, program, &e),
        TreeError::Wait(e) => crate::safety::tool_failed(builtin, &command, None, &e.to_string()),
    })?;
    if run.timed_out {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{command}` did not finish within {deadline_secs} s"),
            "a killed call can leave work half done; check the state with the matching read builtin before retrying",
        ));
    }
    Ok(ToolRun {
        command,
        keep,
        success: run.success,
        code: run.code,
        stdout: String::from_utf8_lossy(&run.stdout).into_owned(),
        stdout_truncated: run.stdout_truncated,
        stderr: String::from_utf8_lossy(&run.stderr).into_owned(),
        stderr_truncated: run.stderr_truncated,
    })
}

/// How one bounded run ended. A pipe that a descendant of the child kept open
/// past the grace is abandoned: what it had produced is kept, and
/// `pipes_abandoned` says so. The `_truncated` flags mean only that output went
/// past its bound, so a child that finished while a helper it started still
/// held the pipe is not reported as having printed too much.
pub(crate) struct TreeRun {
    /// The child exited on its own with status 0.
    pub(crate) success: bool,
    /// The exit code; `None` when killed by a signal or at the deadline.
    pub(crate) code: Option<i32>,
    /// The deadline passed and the child's tree was killed.
    pub(crate) timed_out: bool,
    pub(crate) stdout: Vec<u8>,
    pub(crate) stdout_truncated: bool,
    pub(crate) stderr: Vec<u8>,
    pub(crate) stderr_truncated: bool,
    /// A descendant still held stdout or stderr after the grace, so whatever
    /// it would have printed after that was not read.
    pub(crate) pipes_abandoned: bool,
    /// The child's exit status; `None` only when the deadline killed it.
    pub(crate) status: Option<std::process::ExitStatus>,
}

/// Why a bounded run could not be completed.
pub(crate) enum TreeError {
    /// The program did not start.
    Spawn(std::io::Error),
    /// Waiting on the child failed; the child's tree was killed.
    Wait(std::io::Error),
}

/// How long a run's pipes may stay open after its child has exited or been
/// killed. Only a descendant that outlived the child can keep them open.
const PIPE_GRACE: std::time::Duration = std::time::Duration::from_secs(2);
/// How long the pipes may take to close once a leftover group was killed.
const AFTER_KILL_GRACE: std::time::Duration = std::time::Duration::from_millis(500);
/// Bound on one `taskkill` at a deadline, so the kill itself cannot hang a call.
#[cfg(windows)]
const TASKKILL_LIMIT: std::time::Duration = std::time::Duration::from_secs(10);

/// The one bounded runner that the builtins, the diagnostics runner and the
/// tool-run runner share. `program` runs with `args` directly (never through a
/// shell); `configure` may set the directory and environment; `stdin` is a
/// fixed payload, or the child gets a null stdin when `None`.
///
/// The child leads its own process group (unix), and on Windows it is put in a
/// job object at once (see [`TreeJob`]). At `limit` the child's tree is killed
/// (the group on unix; the job, then `taskkill /T`, on Windows) and the child is
/// reaped. After a normal exit, a pipe still open after [`PIPE_GRACE`] means a
/// leftover descendant holds it, so the group is killed (the job on Windows). A
/// pipe still open after the grace that follows a kill is abandoned, not joined.
/// The call therefore takes at most `limit` plus a few seconds, whatever the
/// descendants do.
///
/// On Windows the job reaches descendants whose parent has already exited, which
/// `taskkill /T` cannot walk. A descendant started before the child joined the
/// job escapes every kill here; that window is short but not zero.
pub(crate) fn run_tree(
    program: &str,
    args: &[&str],
    configure: impl FnOnce(&mut std::process::Command),
    stdin: Option<Vec<u8>>,
    limit: std::time::Duration,
    stdout_keep: Keep,
    stderr_keep: Keep,
) -> std::result::Result<TreeRun, TreeError> {
    let mut command = std::process::Command::new(program);
    command.args(args);
    configure(&mut command);
    run_tree_cmd(command, stdin, limit, stdout_keep, stderr_keep)
}

/// [`run_tree`] for a `Command` the caller has already built (its program,
/// arguments, environment and directory are kept). Its stdio is set here, so
/// the caller's stdin, stdout and stderr settings are replaced.
pub(crate) fn run_tree_cmd(
    command: std::process::Command,
    stdin: Option<Vec<u8>>,
    limit: std::time::Duration,
    stdout_keep: Keep,
    stderr_keep: Keep,
) -> std::result::Result<TreeRun, TreeError> {
    run_tree_cmd_observed(command, stdin, limit, stdout_keep, stderr_keep, |_, _| {})
}

/// [`run_tree_cmd`] that also hands `observe` the child once the runner is done
/// with it (it exited, or was killed at the limit and reaped), before the
/// child's handle is closed. The second argument is the time from the start of
/// the wait to that point. Only a caller that reads the child's handle needs
/// this: perf stat reads process times and memory from it on Windows.
pub(crate) fn run_tree_cmd_observed(
    mut command: std::process::Command,
    stdin: Option<Vec<u8>>,
    limit: std::time::Duration,
    stdout_keep: Keep,
    stderr_keep: Keep,
    observe: impl FnOnce(&std::process::Child, std::time::Duration),
) -> std::result::Result<TreeRun, TreeError> {
    use std::process::Stdio;
    command
        .stdin(if stdin.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    let mut child = command.spawn().map_err(TreeError::Spawn)?;
    #[cfg(windows)]
    let job = TreeJob::for_child(&child);
    if let (Some(payload), Some(mut pipe)) = (stdin, child.stdin.take()) {
        // Detached: a child that never reads its stdin blocks this write until
        // the kill closes the pipe, which then fails the write.
        std::thread::spawn(move || {
            use std::io::Write;
            let _ = pipe.write_all(&payload);
        });
    }
    let out = PipeReader::start(child.stdout.take(), stdout_keep);
    let err = PipeReader::start(child.stderr.take(), stderr_keep);

    let started = std::time::Instant::now();
    let exited = loop {
        match child.try_wait() {
            Ok(Some(status)) => break Some(status),
            Ok(None) => {}
            Err(e) => {
                #[cfg(windows)]
                kill_job(job.as_ref());
                kill_tree(&mut child);
                return Err(TreeError::Wait(e));
            }
        }
        if started.elapsed() >= limit {
            break None;
        }
        std::thread::sleep(std::time::Duration::from_millis(5));
    };
    let waited = started.elapsed();
    let (success, code, status, timed_out, out_closed, err_closed) = match exited {
        Some(status) => {
            let (mut out_closed, mut err_closed) = wait_pipes(&out, &err, PIPE_GRACE);
            if !(out_closed && err_closed) {
                // A descendant that outlived the child holds a pipe: kill its
                // group rather than wait for it.
                #[cfg(windows)]
                kill_job(job.as_ref());
                kill_group(child.id());
                (out_closed, err_closed) = wait_pipes(&out, &err, AFTER_KILL_GRACE);
            }
            (
                status.success(),
                status.code(),
                Some(status),
                false,
                out_closed,
                err_closed,
            )
        }
        None => {
            #[cfg(windows)]
            kill_job(job.as_ref());
            kill_tree(&mut child);
            let (out_closed, err_closed) = wait_pipes(&out, &err, PIPE_GRACE);
            (false, None, None, true, out_closed, err_closed)
        }
    };
    observe(&child, waited);
    let (stdout, stdout_truncated) = out.finish();
    let (stderr, stderr_truncated) = err.finish();
    Ok(TreeRun {
        success,
        code,
        timed_out,
        stdout,
        stdout_truncated,
        stderr,
        stderr_truncated,
        pipes_abandoned: !out_closed || !err_closed,
        status,
    })
}

/// Deadline for a probe that only asks a tool about itself or the host
/// (`--version`, `uname`, `which`, a status read). It bounds a hung probe, not
/// a slow one: 10 s was measured too short, because a cold `powershell` start
/// under a parallel test run took longer than that on Windows.
pub(crate) const PROBE_DEADLINE_SECS: u64 = 30;

/// `cmd.output()` with a deadline: the whole process tree is killed past
/// `deadline_secs`, and output over 64 MiB is refused (see
/// [`crate::safety::output_with_timeout`]). A tool that is absent is
/// E_TOOL_MISSING, a deadline is E_BUDGET_EXCEEDED, and a nonzero exit is left
/// in the returned status for the caller to judge, as `output()` left it.
pub(crate) fn bounded_cmd_output(
    builtin: &str,
    tool: &str,
    cmd: std::process::Command,
    deadline_secs: u64,
) -> Result<std::process::Output> {
    crate::safety::output_with_timeout(cmd, deadline_secs)
        .map_err(|e| crate::safety::spawn_error(builtin, tool, &e))
}

/// Run `tool` (executed as `program`) through [`run_tree`] and return the
/// `Output` its callers read. Stdin is written on run_tree's own thread, so a
/// payload larger than the pipe buffer cannot deadlock against a child that is
/// still writing. Past `deadline_secs` the child's tree is killed and the call
/// is a coded budget error. Output over `max_output` in either stream is also a
/// budget error: a report cut short would look whole. Nothing is judged here.
pub(crate) fn run_output(
    builtin: &str,
    tool: &str,
    program: &str,
    args: &[&str],
    configure: impl FnOnce(&mut std::process::Command),
    stdin: Option<Vec<u8>>,
    deadline_secs: u64,
    max_output: usize,
) -> Result<std::process::Output> {
    let run = run_tree(
        program,
        args,
        configure,
        stdin,
        std::time::Duration::from_secs(deadline_secs),
        Keep::Head(max_output),
        Keep::Head(max_output),
    )
    .map_err(|e| match e {
        TreeError::Spawn(e) | TreeError::Wait(e) => crate::safety::spawn_error(builtin, tool, &e),
    })?;
    match run.status {
        Some(status) if !run.timed_out => {
            if run.stdout_truncated || run.stderr_truncated {
                return Err(crate::safety::budget_exceeded(
                    builtin,
                    format!("`{tool}` printed more than {max_output} bytes"),
                    "the output was not used; the call was refused rather than cut short",
                ));
            }
            Ok(std::process::Output {
                status,
                stdout: run.stdout,
                stderr: run.stderr,
            })
        }
        _ => Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{tool}` did not finish within {deadline_secs} s"),
            "the call was killed and its result discarded; check the state with the matching read builtin before retrying",
        )),
    }
}

