/// What one pipe has produced, kept to its `Keep` bound while it is read.
struct PipeBuf {
    keep: Keep,
    kept: Vec<u8>,
    total: usize,
}

impl PipeBuf {
    fn limit(&self) -> usize {
        match self.keep {
            Keep::Head(n) | Keep::Tail(n) => n,
        }
    }

    fn push(&mut self, bytes: &[u8]) {
        self.total = self.total.saturating_add(bytes.len());
        match self.keep {
            Keep::Head(max) => {
                let room = max.saturating_sub(self.kept.len());
                self.kept.extend_from_slice(&bytes[..bytes.len().min(room)]);
            }
            Keep::Tail(max) => {
                self.kept.extend_from_slice(bytes);
                if self.kept.len() > max.saturating_mul(2) {
                    let cut = self.kept.len() - max;
                    self.kept.drain(..cut);
                }
            }
        }
    }
}

/// A pipe read to its end on its own thread. The thread signals `done` when
/// the pipe reaches end-of-file; the waiter never joins the thread.
struct PipeReader {
    buf: std::sync::Arc<std::sync::Mutex<PipeBuf>>,
    done: std::sync::mpsc::Receiver<()>,
}

impl PipeReader {
    fn start<R: std::io::Read + Send + 'static>(pipe: Option<R>, keep: Keep) -> Self {
        let buf = std::sync::Arc::new(std::sync::Mutex::new(PipeBuf {
            keep,
            kept: Vec::new(),
            total: 0,
        }));
        let (tx, done) = std::sync::mpsc::channel();
        match pipe {
            Some(mut pipe) => {
                let shared = std::sync::Arc::clone(&buf);
                std::thread::spawn(move || {
                    let mut chunk = [0u8; 8192];
                    loop {
                        match pipe.read(&mut chunk) {
                            Ok(0) => break,
                            Ok(n) => shared
                                .lock()
                                .unwrap_or_else(std::sync::PoisonError::into_inner)
                                .push(&chunk[..n]),
                            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {}
                            Err(_) => break,
                        }
                    }
                    let _ = tx.send(());
                });
            }
            None => {
                let _ = tx.send(());
            }
        }
        PipeReader { buf, done }
    }

    /// Whether the pipe reached end-of-file by `until`. A reader that has
    /// finished (its sender is gone) counts as closed on every later call.
    fn wait_until(&self, until: std::time::Instant) -> bool {
        let wait = until.saturating_duration_since(std::time::Instant::now());
        !matches!(
            self.done.recv_timeout(wait),
            Err(std::sync::mpsc::RecvTimeoutError::Timeout)
        )
    }

    /// The kept bytes and whether output went past the bound and was dropped.
    fn finish(self) -> (Vec<u8>, bool) {
        let mut buf = self
            .buf
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let max = buf.limit();
        let truncated = buf.total > max;
        if let Keep::Tail(_) = buf.keep {
            if buf.kept.len() > max {
                let cut = buf.kept.len() - max;
                buf.kept.drain(..cut);
            }
        }
        (std::mem::take(&mut buf.kept), truncated)
    }
}

/// Wait for both pipes to close within one shared grace.
fn wait_pipes(out: &PipeReader, err: &PipeReader, grace: std::time::Duration) -> (bool, bool) {
    let until = std::time::Instant::now() + grace;
    (out.wait_until(until), err.wait_until(until))
}

/// Kill the child's tree, then reap the child. Unix: the child leads its own
/// process group, so the whole group is signalled. Windows: `taskkill /T` walks
/// the tree, which only works while the child is alive, so it runs first. Callers
/// on Windows terminate the run's job ([`kill_job`]) before this.
fn kill_tree(child: &mut std::process::Child) {
    kill_group(child.id());
    #[cfg(windows)]
    {
        taskkill_tree(child.id());
    }
    let _ = child.kill();
    let _ = child.wait();
}

/// Windows: a job object that holds one bounded run's child and what it starts.
/// A process started by a job member joins the job (Windows 8 and later), so the
/// job reaches descendants whose parent has already exited, which `taskkill /T`
/// cannot walk. The job does not kill on close: a descendant that closed its
/// pipes and was left running survives, as on unix. A descendant the child starts
/// before it is assigned to the job escapes the job.
#[cfg(windows)]
struct TreeJob(*mut std::ffi::c_void);

#[cfg(windows)]
#[link(name = "kernel32")]
extern "system" {
    fn CreateJobObjectW(attrs: *mut std::ffi::c_void, name: *const u16) -> *mut std::ffi::c_void;
    fn AssignProcessToJobObject(job: *mut std::ffi::c_void, process: *mut std::ffi::c_void) -> i32;
    fn TerminateJobObject(job: *mut std::ffi::c_void, exit_code: u32) -> i32;
    fn CloseHandle(handle: *mut std::ffi::c_void) -> i32;
}

#[cfg(windows)]
impl TreeJob {
    /// A job holding `child`, or `None` when no job can be made or the child
    /// cannot join one (for example a process already in a job that forbids
    /// nesting). Without a job the run falls back to `taskkill /T`.
    fn for_child(child: &std::process::Child) -> Option<TreeJob> {
        use std::os::windows::io::AsRawHandle;
        // SAFETY: null attributes and a null name ask for an unnamed job with the
        // default security descriptor; the call has no other effects.
        let job = TreeJob(unsafe { CreateJobObjectW(std::ptr::null_mut(), std::ptr::null()) });
        if job.0.is_null() {
            return None;
        }
        // SAFETY: `job.0` is the live job handle made above, and the child's
        // process handle stays valid while `child` is borrowed. On failure `job`
        // is dropped, which closes the job.
        let assigned = unsafe { AssignProcessToJobObject(job.0, child.as_raw_handle()) };
        (assigned != 0).then_some(job)
    }

    /// Kill every process in the job, the child's descendants included, whether
    /// or not their parent is still alive.
    fn terminate(&self) {
        // SAFETY: `self.0` is a live job handle owned by `self`.
        unsafe {
            TerminateJobObject(self.0, 1);
        }
    }
}

#[cfg(windows)]
impl Drop for TreeJob {
    fn drop(&mut self) {
        // SAFETY: the handle came from CreateJobObjectW and is closed only here.
        // Closing it ends nothing: kill-on-close is not set.
        unsafe {
            CloseHandle(self.0);
        }
    }
}

/// Windows: terminate a run's job, if it has one. Called before `taskkill /T` at
/// a deadline, and after a normal exit when a pipe is held open.
#[cfg(windows)]
fn kill_job(job: Option<&TreeJob>) {
    if let Some(job) = job {
        job.terminate();
    }
}

/// Signal the process group whose id is `pid` (the child's own group on unix).
fn kill_group(pid: u32) {
    #[cfg(unix)]
    {
        // SAFETY: a negative pid addresses the process group that
        // `process_group(0)` made the child's own; kill has no memory effects.
        unsafe {
            libc::kill(-(pid as i32), libc::SIGKILL);
        }
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
    }
}

/// `taskkill /T /F` on the tree rooted at `pid`, given at most
/// [`TASKKILL_LIMIT`]. It runs with argv (no shell) and its output is discarded.
#[cfg(windows)]
pub(crate) fn taskkill_tree(pid: u32) {
    use std::process::{Command, Stdio};
    let pid_text = pid.to_string();
    let Ok(mut killer) = Command::new("taskkill")
        .args(["/T", "/F", "/PID", pid_text.as_str()])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
    else {
        return;
    };
    let until = std::time::Instant::now() + TASKKILL_LIMIT;
    loop {
        match killer.try_wait() {
            Ok(Some(_)) => return,
            Ok(None) if std::time::Instant::now() < until => {
                std::thread::sleep(std::time::Duration::from_millis(20));
            }
            _ => {
                let _ = killer.kill();
                let _ = killer.wait();
                return;
            }
        }
    }
}

/// Text with terminal colour sequences removed. Terraform colours some errors on
/// stderr even under -no-color, and a failure message should not carry them.
fn strip_ansi(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            if chars.peek() == Some(&'[') {
                chars.next();
                for d in chars.by_ref() {
                    if d.is_ascii_alphabetic() {
                        break;
                    }
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// The text of a finished call, or the coded failure it reports.
fn tool_text(builtin: &str, run: ToolRun) -> Result<String> {
    if !run.success {
        return Err(crate::safety::tool_failed(
            builtin,
            &run.command,
            run.code,
            &run.stderr,
        ));
    }
    match run.keep {
        Keep::Head(max) if run.stdout_truncated => Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{}` printed more than {max} bytes", run.command),
            "narrow the call so that it prints less",
        )),
        Keep::Tail(max) if run.stdout_truncated => Ok(format!(
            "[earlier output dropped; the last {max} bytes follow]\n{}",
            run.stdout
        )),
        _ => Ok(run.stdout),
    }
}

/// The JSON a finished call printed. Output that is not JSON is a coded
/// failure, never a string handed back in place of the answer.
fn tool_json(builtin: &str, run: ToolRun) -> Result<Value> {
    let command = run.command.clone();
    let text = tool_text(builtin, run)?;
    match serde_json::from_str::<serde_json::Value>(&text) {
        Ok(json) => Ok(json_to_value(json)),
        Err(e) => Err(crate::safety::tool_failed(
            builtin,
            &command,
            Some(0),
            &format!("printed output that is not JSON ({e})"),
        )),
    }
}

/// A helm call, run in the process's directory.
fn helm_call(builtin: &str, args: &[String], keep: Keep, deadline_secs: u64) -> Result<ToolRun> {
    let refs: Vec<&str> = args.iter().map(String::as_str).collect();
    tool_run(builtin, "helm", None, &refs, keep, deadline_secs)
}

/// A terraform call, run in `dir`.
fn tf_call(
    builtin: &str,
    dir: &std::path::Path,
    args: &[&str],
    keep: Keep,
    deadline_secs: u64,
) -> Result<ToolRun> {
    tool_run(builtin, "terraform", Some(dir), args, keep, deadline_secs)
}

/// The workspace root as an absolute path. `AETHER_WORKSPACE`, or the process's
/// directory when it is unset.
fn workspace_root_abs() -> std::path::PathBuf {
    let root = crate::safety::workspace_root();
    if root.is_absolute() {
        root
    } else {
        std::env::current_dir()
            .map(|cwd| cwd.join(&root))
            .unwrap_or(root)
    }
}

/// `value` resolved against `base` and required to lie inside the workspace.
/// Every path a helm or terraform call is given passes here first.
fn workspace_path(
    builtin: &str,
    value: &str,
    base: &std::path::Path,
) -> Result<std::path::PathBuf> {
    let given = std::path::Path::new(value);
    let path = if given.is_absolute() {
        given.to_path_buf()
    } else {
        base.join(given)
    };
    if !crate::safety::within_workspace(&path.to_string_lossy()) {
        return Err(crate::safety::outside_workspace(builtin, value));
    }
    Ok(path)
}

/// A plain text argument: not empty and never option-like. Used where the
/// value goes to a tool as an argument, so a leading `-` would be a flag.
fn tf_plain(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    if value.trim().is_empty() || value.contains('\0') {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must not be empty"
        )));
    }
    Ok(value.to_string())
}

/// A Terraform directory: the workspace root, or `value` inside it. Refused
/// when it is outside the workspace, or when it is not a directory. Without
/// that second check a missing directory would surface as E_TOOL_MISSING.
fn tf_dir(builtin: &str, value: Option<&str>) -> Result<std::path::PathBuf> {
    let root = workspace_root_abs();
    let dir = match value {
        None => root,
        Some(v) => workspace_path(builtin, v, &root)?,
    };
    if !dir.is_dir() {
        return Err(crate::safety::not_found(
            builtin,
            "directory",
            &dir.display().to_string(),
        ));
    }
    Ok(dir)
}

/// `-var-file=<path>` for a variable file inside the workspace, when one is given.
fn tf_var_file(builtin: &str, args: &[Value], index: usize) -> Result<Option<String>> {
    let Some(name) = k8s_arg(builtin, "variable file", args, index, tf_plain)? else {
        return Ok(None);
    };
    let path = workspace_path(builtin, &name, &workspace_root_abs())?;
    if !path.is_file() {
        return Err(crate::safety::not_found(builtin, "variable file", &name));
    }
    Ok(Some(format!("-var-file={}", path.display())))
}

/// A Terraform workspace name: letters, digits, `-` and `_`.
fn tf_workspace_name(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.chars().count() <= TF_MAX_WORKSPACE
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_');
    if !well_formed {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is 1-{TF_MAX_WORKSPACE} letters, digits, '-' or '_' (got {value:?})"
        )));
    }
    Ok(value.to_string())
}

/// A helm chart: a repository chart name, an OCI or URL reference, or a local
/// path. A local path that exists must lie inside the workspace.
fn helm_chart(builtin: &str, what: &str, value: &str) -> Result<String> {
    let chart = k8s_token(builtin, what, value)?;
    if std::path::Path::new(&chart).exists() {
        let cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
        workspace_path(builtin, &chart, &cwd)?;
    }
    Ok(chart)
}

/// A helm values key: letters, digits, and `._-[]`, not starting with `-`.
fn helm_set_key(builtin: &str, key: &str) -> Result<String> {
    let well_formed = !key.is_empty()
        && key.len() <= 253
        && !key.starts_with('-')
        && key
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "._-[]".contains(c));
    if !well_formed {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: a values key is letters, digits and ._-[] and does not start with '-' (got {key:?})"
        )));
    }
    Ok(key.to_string())
}

/// `--set=key=value` for each override in a values Record. Each override is one
/// argv element, so a value cannot become a flag. A comma in a string value is
/// escaped, because helm splits `--set` on commas.
fn helm_set_flags(builtin: &str, values: Option<&Value>) -> Result<Vec<String>> {
    let overrides = match values {
        None => return Ok(Vec::new()),
        Some(Value::Record(map)) => map,
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "{builtin}: values must be a Record, got {}",
                other.type_name()
            )))
        }
    };
    if overrides.len() > HELM_MAX_SET {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: at most {HELM_MAX_SET} values, got {}",
            overrides.len()
        )));
    }
    let mut flags = Vec::with_capacity(overrides.len());
    for (key, value) in overrides {
        let key = helm_set_key(builtin, key)?;
        let text = match value {
            Value::Str(s) if s.chars().any(char::is_control) => {
                return Err(crate::safety::arg_err(format!(
                    "{builtin}: the value for {key} contains a control character"
                )))
            }
            Value::Str(s) => s.replace(',', "\\,"),
            Value::Int(n) => n.to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Float(f) if f.is_finite() => f.to_string(),
            other => {
                return Err(crate::safety::arg_err(format!(
                    "{builtin}: the value for {key} must be a String, Int, Float or Bool, got {}",
                    other.type_name()
                )))
            }
        };
        flags.push(format!("--set={key}={text}"));
    }
    Ok(flags)
}

/// `--namespace=<ns>` when a namespace was given.
fn helm_ns_flag(ns: Option<String>) -> Option<String> {
    ns.map(|n| format!("--namespace={n}"))
}

// Helper: parse tabular kubectl output (e.g. `kubectl top`) into Records
fn parse_kubectl_table(text: &str) -> Vec<Value> {
    let mut lines = text.lines();
    let header_line = match lines.next() {
        Some(h) => h,
        None => return Vec::new(),
    };
    let headers: Vec<String> = header_line
        .split_whitespace()
        .map(|h| {
            h.to_lowercase()
                .replace('(', "_")
                .replace(')', "")
                .replace('%', "pct")
        })
        .collect();
    let mut rows = Vec::new();
    for line in lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let cols: Vec<&str> = trimmed.split_whitespace().collect();
        let mut record = std::collections::BTreeMap::new();
        for (i, hdr) in headers.iter().enumerate() {
            let val = cols.get(i).unwrap_or(&"").to_string();
            record.insert(hdr.clone(), Value::Str(val));
        }
        rows.push(Value::Record(record));
    }
    rows
}

// ---------------------------------------------------------------------------
// 850: bi_k8s_get - kubectl get <resource> [-n namespace] -o json
// ---------------------------------------------------------------------------
fn bi_k8s_get(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("k8s_get", &input)?;
    k8s_max_args("k8s_get", &args, 2)?;
    let resource = k8s_need("k8s_get", "a resource type", &args, 0, k8s_token)?;
    let ns = k8s_arg("k8s_get", "namespace", &args, 1, k8s_object_name)?;
    let mut cmd: Vec<&str> = vec!["get", "-o", "json"];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.extend(["--", resource.as_str()]);
    kubectl_json("k8s_get", &cmd, K8S_MAX_JSON)
}

// ---------------------------------------------------------------------------
// 851: bi_k8s_apply - kubectl apply -f <local manifest> [-n namespace]
//
// The manifest is a local file inside the workspace, read through the same
// guard as the file builtins before kubectl is given its resolved path. A URL
// is refused: kubectl would fetch it outside that guard.
// ---------------------------------------------------------------------------
fn bi_k8s_apply(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "k8s_apply";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 2)?;
    let Some(Value::Str(file)) = args.first() else {
        return Err(crate::safety::arg_err(
            "k8s_apply requires a manifest file path as first argument",
        ));
    };
    crate::safety::reject_option_like(B, std::slice::from_ref(file))?;
    if file.contains("://") {
        return Err(crate::safety::arg_err(
            "k8s_apply reads a local manifest; a URL is not fetched, because kubectl would read it outside the workspace guard",
        ));
    }
    let ns = k8s_arg(B, "namespace", &args, 1, k8s_object_name)?;
    let resolved = crate::safety::resolve_path_str(file);
    // No guard call here: listing k8s_apply as self-guarded would skip the
    // dispatcher's Network guard (metering, allowlist, audit) for the cluster
    // call. The manifest read is checked by validate_read_path.
    let path = crate::security::validate_read_path(&resolved)?;
    let meta = std::fs::metadata(&path).map_err(|e| crate::safety::fs_error(B, &path, &e))?;
    if !meta.is_file() {
        return Err(crate::safety::arg_err(format!(
            "{B} requires a regular file, got {resolved:?}"
        )));
    }
    let path_text = path.display().to_string();
    let mut cmd: Vec<&str> = vec!["apply", "-f", path_text.as_str()];
    k8s_push_ns(&mut cmd, ns.as_deref());
    let text = kubectl_run(B, &cmd, K8S_MAX_TEXT)?;
    Ok(Value::Str(text.trim().to_string()))
}

// ---------------------------------------------------------------------------
// 852: bi_k8s_delete - kubectl delete <resource> <name> [-n namespace]
// ---------------------------------------------------------------------------
fn bi_k8s_delete(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "k8s_delete";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let resource = k8s_need(B, "a resource type", &args, 0, k8s_token)?;
    let name = k8s_need(B, "a resource name", &args, 1, k8s_object_name)?;
    let ns = k8s_arg(B, "namespace", &args, 2, k8s_object_name)?;
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: B,
        effect: crate::safety::Effect::Destructive,
        what: "k8s_delete",
        targets: vec![format!("{}/{}", resource, name)],
        blast_radius: serde_json::json!({ "resource": resource, "name": name, "namespace": ns }),
        reversible: false,
        fs_paths: false,
    })?;
    let mut cmd: Vec<&str> = vec!["delete"];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.extend(["--", resource.as_str(), name.as_str()]);
    let text = kubectl_run(B, &cmd, K8S_MAX_TEXT)?;
    Ok(Value::Str(text.trim().to_string()))
}

// ---------------------------------------------------------------------------
// 853: bi_k8s_describe - kubectl describe <resource> <name> [-n namespace]
// ---------------------------------------------------------------------------
fn bi_k8s_describe(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "k8s_describe";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let resource = k8s_need(B, "a resource type", &args, 0, k8s_token)?;
    let name = k8s_need(B, "a resource name", &args, 1, k8s_object_name)?;
    let ns = k8s_arg(B, "namespace", &args, 2, k8s_object_name)?;
    let mut cmd: Vec<&str> = vec!["describe"];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.extend(["--", resource.as_str(), name.as_str()]);
    let text = kubectl_run(B, &cmd, K8S_MAX_TEXT)?;
    Ok(Value::Str(text.trim().to_string()))
}

// ---------------------------------------------------------------------------
// 854: bi_k8s_logs - kubectl logs <pod> [-n namespace] --tail=N
//
// Always bounded: the tail defaults to K8S_LOG_DEFAULT_TAIL lines and cannot
// exceed K8S_LOG_MAX_TAIL.
// ---------------------------------------------------------------------------
fn bi_k8s_logs(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "k8s_logs";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let pod = k8s_need(B, "a pod name", &args, 0, k8s_object_name)?;
    let ns = k8s_arg(B, "namespace", &args, 1, k8s_object_name)?;
    let tail = match args.get(2) {
        None => K8S_LOG_DEFAULT_TAIL,
        Some(Value::Int(n)) if (1..=K8S_LOG_MAX_TAIL).contains(n) => *n,
        Some(Value::Int(n)) => {
            return Err(crate::safety::arg_err(format!(
                "k8s_logs tail must be in 1..={K8S_LOG_MAX_TAIL} lines, got {n}"
            )))
        }
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "k8s_logs tail must be an Int, got {}",
                other.type_name()
            )))
        }
    };
    let tail_flag = format!("--tail={tail}");
    let mut cmd: Vec<&str> = vec!["logs", tail_flag.as_str()];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.extend(["--", pod.as_str()]);
    Ok(Value::Str(kubectl_run(B, &cmd, K8S_MAX_TEXT)?))
}

// ---------------------------------------------------------------------------
// 855: bi_k8s_exec - kubectl exec <pod> [-n namespace] -- <argv...>
//
// The command is an Array of Strings, the argv the container runs. A string is
// refused rather than split on spaces, and nothing is run through a shell.
// ---------------------------------------------------------------------------
fn bi_k8s_exec(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "k8s_exec";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let pod = k8s_need(B, "a pod name", &args, 0, k8s_object_name)?;
    let Some(Value::Array(items)) = args.get(1) else {
        return Err(crate::safety::arg_err(
            "k8s_exec command must be an Array of Strings (the argv); a shell string is not run",
        ));
    };
    if items.is_empty() || items.len() > K8S_MAX_EXEC_ARGV {
        return Err(crate::safety::arg_err(format!(
            "k8s_exec command must have 1..={K8S_MAX_EXEC_ARGV} elements, got {}",
            items.len()
        )));
    }
    let mut argv: Vec<String> = Vec::with_capacity(items.len());
    for item in items {
        match item {
            Value::Str(s) if !s.contains('\0') => argv.push(s.clone()),
            _ => {
                return Err(crate::safety::arg_err(
                    "k8s_exec command elements must be Strings without NUL bytes",
                ))
            }
        }
    }
    let ns = k8s_arg(B, "namespace", &args, 2, k8s_object_name)?;
    crate::safety::guard_exec(B, format!("kubectl exec {pod} -- {}", argv.join(" ")))?;
    let mut cmd: Vec<&str> = vec!["exec", pod.as_str()];
    k8s_push_ns(&mut cmd, ns.as_deref());
    cmd.push("--");
    cmd.extend(argv.iter().map(String::as_str));
    Ok(Value::Str(kubectl_run(B, &cmd, K8S_MAX_TEXT)?))
}

