/// Windows: the drive a `C:`, `C:\` or `c:/` argument names, as its upper-case
/// letter. Anything else is refused: blkid on Windows takes a drive, not a path.
#[cfg(windows)]
fn blkid_drive(device: &str) -> Result<char> {
    let b = device.as_bytes();
    let plain = (b.len() == 2 || b.len() == 3)
        && b[0].is_ascii_alphabetic()
        && b[1] == b':'
        && (b.len() == 2 || b[2] == b'\\' || b[2] == b'/');
    if plain {
        Ok(char::from(b[0].to_ascii_uppercase()))
    } else if device.starts_with("/dev/") {
        // A well-formed Unix device names nothing here, as a missing device
        // does on Linux, so a script written for both gets the same code. It
        // is checked as on Linux first: `/dev/../x` is still a bad argument.
        linux_diagnostics::device_path("blkid", device)?;
        Err(crate::safety::not_found(
            "blkid",
            "block device",
            &format!("{device} (Windows names drives, such as C:)"),
        ))
    } else {
        Err(crate::safety::bad_arg(
            "blkid",
            "a drive such as C: or C:\\",
            device,
        ))
    }
}

/// Windows: one drive's volume and partition, from Get-Volume and Get-Partition.
/// The volume's UniqueId is uuid and the partition's Guid is partuuid, the way
/// blkid reports them on Linux; type is the file system lower-cased. A field the
/// drive does not report is left out, not made up.
#[cfg(windows)]
fn blkid_windows(device: &str) -> Result<Value> {
    const NAME: &str = "blkid";
    let letter = blkid_drive(device)?.to_string();
    // A drive with no volume prints nothing, which the parse below reads as
    // absent. Get-Volume exits 1 for it even under SilentlyContinue, so only
    // ObjectNotFound is taken as absence; any other error still fails.
    let script = crate::ps_script!(
        "try {{ $v = Get-Volume -DriveLetter {} -ErrorAction Stop }} catch {{ if ($_.CategoryInfo.Category -eq 'ObjectNotFound') {{ exit 0 }} else {{ throw }} }}; $p = Get-Partition -DriveLetter {} -ErrorAction SilentlyContinue | Select-Object -First 1; [pscustomobject]@{{ UniqueId=$v.UniqueId; FileSystemType=$v.FileSystemType; FileSystemLabel=$v.FileSystemLabel; PartitionGuid=$p.Guid }} | ConvertTo-Json",
        crate::safety::ps_quote(&letter),
        crate::safety::ps_quote(&letter)
    );
    let out = net_run(
        NAME,
        "powershell",
        &["-NoProfile", "-NonInteractive", "-Command", script.as_str()],
        NET_TOOL_SECS,
    )?;
    net_checked(NAME, "powershell", &out)?;
    let Some(item) = net_ps_items(NAME, &out.stdout)?.into_iter().next() else {
        return Err(crate::safety::not_found(
            NAME,
            "identifiable device",
            device,
        ));
    };
    let Some(o) = item.as_object() else {
        return Err(net_unparsed(NAME, "powershell"));
    };
    let text = |key: &str| {
        o.get(key)
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    let mut rec = BTreeMap::new();
    rec.insert("devname".to_string(), Value::Str(format!("{letter}:")));
    if let Some(s) = text("UniqueId") {
        rec.insert("uuid".to_string(), Value::Str(s));
    }
    if let Some(s) = text("PartitionGuid") {
        rec.insert("partuuid".to_string(), Value::Str(s));
    }
    if let Some(s) = text("FileSystemType") {
        rec.insert("type".to_string(), Value::Str(s.to_lowercase()));
    }
    if let Some(s) = text("FileSystemLabel") {
        rec.insert("label".to_string(), Value::Str(s));
    }
    // Only the drive name is left: nothing identifies a volume, as on Linux.
    if rec.len() == 1 {
        return Err(crate::safety::not_found(
            NAME,
            "identifiable device",
            device,
        ));
    }
    Ok(Value::Record(rec))
}

/// 958: bi_blkid - Block device attributes (Linux; Windows reads a drive).
fn bi_blkid(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    linux_diagnostics::no_pipeline_input("blkid", &input)?;
    let device = match args.as_slice() {
        [Value::Str(s)] => s.clone(),
        [other] => {
            return Err(crate::safety::bad_arg(
                "blkid",
                "a device path String such as /dev/sda1",
                other.type_name(),
            ))
        }
        _ => {
            return Err(crate::safety::arg_err(
                "blkid: expected exactly one device path",
            ))
        }
    };
    #[cfg(not(windows))]
    linux_diagnostics::device_path("blkid", &device)?;
    #[cfg(target_os = "linux")]
    {
        let limit = std::time::Duration::from_secs(20);
        let run = linux_diagnostics::run_bounded(
            "blkid",
            "blkid",
            "blkid",
            &["-o".to_string(), "export".to_string(), device.clone()],
            limit,
        )?;
        // blkid exits 2 for a device it cannot identify.
        if !run.timed_out && !run.truncated && run.code == Some(2) {
            return Err(crate::safety::not_found(
                "blkid",
                "identifiable device",
                &device,
            ));
        }
        linux_diagnostics::require_success("blkid", "blkid", &run, limit)?;
        let mut rec = BTreeMap::new();
        for line in run.stdout.lines() {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim().to_lowercase();
                if !k.is_empty() {
                    rec.insert(k, Value::Str(v.to_string()));
                }
            }
        }
        if rec.is_empty() {
            return Err(crate::safety::not_found(
                "blkid",
                "identifiable device",
                &device,
            ));
        }
        Ok(Value::Record(rec))
    }
    #[cfg(windows)]
    {
        blkid_windows(&device)
    }
    #[cfg(not(any(windows, target_os = "linux")))]
    {
        Err(crate::safety::unimplemented(
            "blkid",
            "blkid is Linux and Windows only; NOTHING WAS DONE on this operating system",
            "lsblk() lists block devices on every OS",
        ))
    }
}

/// Longest host name a network tool accepts.
const NET_HOST_MAX: usize = 253;
/// Most words a command line may hold once split into argv.
const NET_ARGV_MAX: usize = 256;
/// Stderr kept from a network or debug tool, for a failure message or a report.
const NET_ERR_MAX: usize = 4096;
/// Most items one xargs_exec call may run.
const XARGS_MAX_ITEMS: usize = 256;
/// Output kept from one run of xargs_exec, on each stream.
const XARGS_ITEM_OUT: usize = 16 * 1024;
/// Wall-clock limit on one xargs_exec call, all of its items together.
const XARGS_TOTAL_SECS: u64 = 600;
/// Redirects http_get follows, each one checked before it is taken.
const HTTP_MAX_REDIRECTS: usize = 5;
/// Largest response body http_get reads.
const HTTP_BODY_MAX: u64 = 16 * 1024 * 1024;
/// Largest file wget_download writes.
const WGET_FILE_MAX: u64 = 1024 * 1024 * 1024;
/// Largest logrotate configuration that is read.
const LOGROTATE_CONFIG_MAX: u64 = 1024 * 1024;
/// Most log files multitail_open opens at once.
const MULTITAIL_MAX_FILES: usize = 16;
/// The port iperf3 listens on when none is given.
const IPERF3_PORT: i64 = 5201;
/// The nmap flags nmap_scan passes through. Every other nmap option is refused:
/// --script runs scripts, -oN/-oG/--log-file write files, and the rest change
/// what nmap reads or runs.
const NMAP_FLAGS: &[&str] = &[
    "-sT", "-sS", "-sU", "-sV", "-Pn", "-n", "-T0", "-T1", "-T2", "-T3", "-T4", "-T5",
];
/// logrotate directives that run a program or send mail. A configuration that
/// names one is refused, because the command it would run is out of sight here.
const LOGROTATE_REFUSED: &[&str] = &[
    "prerotate",
    "postrotate",
    "firstaction",
    "lastaction",
    "preremove",
    "mail",
    "mailfirst",
    "maillast",
];

/// A host name or IP literal given to a network tool as an argument: letters,
/// digits, '.', '-' and ':', at most NET_HOST_MAX bytes. A leading '-' is
/// refused as an option, and every other character is refused by the rule.
fn net_target_host(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.len() <= NET_HOST_MAX
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b':'));
    if well_formed {
        Ok(value.to_string())
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be a host name or IP literal of letters, digits, '.', '-' and ':' (at most {NET_HOST_MAX} bytes), got {value:?}"
        )))
    }
}

/// A TCP or UDP port: an Int in 1..=65535.
fn net_port(builtin: &str, n: i64) -> Result<i64> {
    if (1..=65535).contains(&n) {
        Ok(n)
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: port must be 1..=65535, got {n}"
        )))
    }
}

/// A systemd unit name for journalctl: letters, digits, and '-', '_', '.', '@'.
fn journal_unit(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.len() <= 256
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'@'));
    if well_formed {
        Ok(value.to_string())
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be a systemd unit name (letters, digits and - _ . @), got {value:?}"
        )))
    }
}

/// A command line split into argv on whitespace. There is no quoting and no
/// shell: each word is one argument, and shell metacharacters are inert. The
/// program word may not begin with '-'.
fn argv_words(builtin: &str, command: &str) -> Result<Vec<String>> {
    let words: Vec<String> = command.split_whitespace().map(str::to_string).collect();
    let Some(program) = words.first() else {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: the command is empty"
        )));
    };
    crate::safety::reject_option_like(builtin, std::slice::from_ref(program))?;
    if words.len() > NET_ARGV_MAX {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!(
                "the command has {} words; the limit is {NET_ARGV_MAX}",
                words.len()
            ),
            "pass a shorter command line",
        ));
    }
    Ok(words)
}

/// The exit code of a finished run; a run ended by a signal has none, and is -1.
fn exit_code_of(run: &ToolRun) -> i64 {
    run.code.map_or(-1, i64::from)
}

/// A network request that failed before any answer came back: a coded E_IO
/// that says what was attempted.
fn net_io_error(builtin: &str, what: &str, detail: impl std::fmt::Display) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::Io,
        message: format!("{builtin}: {what}: {detail}"),
        builtin: builtin.to_string(),
        hint: "no answer came back; check the address and the network, then retry".to_string(),
        approval: None,
        did_you_mean: Vec::new(),
        expected: format!("{what} to complete"),
        got: "no answer".to_string(),
    })
}

/// The client http_get uses. Its timeouts are those of the secure client, and
/// every redirect target passes the same SSRF and scheme rules as the first URL
/// before it is followed. A refused hop ends the request with the refusal.
fn http_redirect_client() -> Result<reqwest::blocking::Client> {
    reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(30))
        .connect_timeout(std::time::Duration::from_secs(10))
        .redirect(reqwest::redirect::Policy::custom(|attempt| {
            if attempt.previous().len() >= HTTP_MAX_REDIRECTS {
                return attempt.error(format!("more than {HTTP_MAX_REDIRECTS} redirects"));
            }
            let next = attempt.url().to_string();
            match validate_http_url("http_get", &next) {
                Ok(_) => attempt.follow(),
                Err(e) => attempt.error(format!("redirect to {next} refused: {e}")),
            }
        }))
        .build()
        .context("Failed to create HTTP client")
}

/// Whether netcat's failure text says the port was closed or did not answer: a
/// determined "not open", as opposed to netcat itself failing.
fn nc_refusal(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    lower.contains("refused") || lower.contains("timed out") || lower.contains("timeout")
}

/// One socat address for socat_relay. Only an outbound TCP or UDP connection to
/// a host name or IPv4 literal and a port is allowed, with no options. EXEC,
/// SYSTEM and SHELL run programs, OPEN and CREATE write files, and every LISTEN
/// form opens a listener, so each of those is refused by policy.
fn socat_address(builtin: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let Some((kind, rest)) = value.split_once(':') else {
        return Err(crate::safety::bad_arg(
            builtin,
            "an address such as TCP:host:port",
            value,
        ));
    };
    let kind_up = kind.to_ascii_uppercase();
    if !matches!(kind_up.as_str(), "TCP" | "TCP4" | "UDP" | "UDP4") {
        return Err(crate::safety::policy_deny(
            builtin,
            format!("{builtin}: socat address type `{kind}` is refused"),
            "only outbound TCP, TCP4, UDP and UDP4 connections to a host and port are allowed; EXEC, SYSTEM and SHELL run programs, OPEN and CREATE write files, and LISTEN forms open listeners",
        ));
    }
    let Some((host, port)) = rest.rsplit_once(':') else {
        return Err(crate::safety::bad_arg(
            builtin,
            "TCP:host:port or UDP:host:port",
            value,
        ));
    };
    let host = net_target_host(builtin, "the socat address host", host)?;
    if host.contains(':') {
        return Err(crate::safety::bad_arg(
            builtin,
            "a host name or IPv4 literal without ':' in the address",
            value,
        ));
    }
    let port = if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) {
        port.parse::<i64>().ok()
    } else {
        None
    };
    let Some(port) = port else {
        return Err(crate::safety::bad_arg(
            builtin,
            "a port number with no options after it",
            value,
        ));
    };
    let port = net_port(builtin, port)?;
    Ok(format!("{kind_up}:{host}:{port}"))
}

/// The ports nmap_scan may scan: digits, ',' and '-', with every number in
/// 1..=65535 and every range low <= high.
fn nmap_ports(builtin: &str, what: &str, value: &str) -> Result<String> {
    let ok = !value.is_empty()
        && value.len() <= 1024
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || matches!(b, b',' | b'-'))
        && value.split(',').all(|item| {
            let mut bounds = item.splitn(2, '-');
            let lo = bounds.next().and_then(|s| s.parse::<u32>().ok());
            let hi = match bounds.next() {
                Some(s) => s.parse::<u32>().ok(),
                None => lo,
            };
            matches!((lo, hi), (Some(l), Some(h)) if (1..=65535).contains(&l) && (1..=65535).contains(&h) && l <= h)
        });
    if ok {
        Ok(value.to_string())
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be ports or ranges such as \"22,80,1000-1100\", each 1..=65535 (got {value:?})"
        )))
    }
}

/// The nmap flags nmap_scan accepts, whitespace-separated. Anything not in
/// NMAP_FLAGS is refused by policy.
fn nmap_flags(builtin: &str, what: &str, value: &str) -> Result<String> {
    for word in value.split_whitespace() {
        if !NMAP_FLAGS.contains(&word) {
            return Err(crate::safety::policy_deny(
                builtin,
                format!("{builtin}: {what} `{word}` is not an allowed nmap flag"),
                format!(
                    "allowed flags: {}; scripts (--script) and output files (-oN, -oG, --log-file) are refused",
                    NMAP_FLAGS.join(" ")
                ),
            ));
        }
    }
    Ok(value.to_string())
}

/// The items xargs_exec runs: an Array of scalars, or a String read as lines
/// with empty lines skipped. Each item is one argument, so an item that begins
/// with '-' is refused as an option.
fn xargs_items(builtin: &str, value: &Value) -> Result<Vec<String>> {
    let items: Vec<String> = match value {
        Value::Array(arr) => arr
            .iter()
            .map(|v| match v {
                Value::Str(s) => Ok(s.clone()),
                Value::Int(n) => Ok(n.to_string()),
                Value::Float(f) => Ok(f.to_string()),
                Value::Bool(b) => Ok(b.to_string()),
                other => Err(crate::safety::bad_arg(
                    builtin,
                    "scalar items (String, Int, Float or Bool)",
                    other.type_name(),
                )),
            })
            .collect::<Result<Vec<String>>>()?,
        Value::Str(s) => s
            .lines()
            .filter(|l| !l.is_empty())
            .map(str::to_string)
            .collect(),
        other => {
            return Err(crate::safety::bad_arg(
                builtin,
                "an Array or a String of items",
                other.type_name(),
            ))
        }
    };
    if items.len() > XARGS_MAX_ITEMS {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("{} items; the limit is {XARGS_MAX_ITEMS}", items.len()),
            "run the items in more than one call",
        ));
    }
    for item in &items {
        if item.len() > 4096 || item.contains('\0') {
            return Err(crate::safety::arg_err(format!(
                "{builtin}: each item is at most 4096 bytes and has no NUL"
            )));
        }
        crate::safety::reject_option_like(builtin, std::slice::from_ref(item))?;
    }
    Ok(items)
}

/// One `strace -c` summary row, read from its default columns: percent,
/// seconds, usecs/call, calls, errors, syscall. A row with any other shape is
/// counted and returned as the second value, never dropped.
fn strace_summary(text: &str) -> (Vec<Value>, usize) {
    let mut rows = Vec::new();
    let mut unparsed = 0usize;
    let mut in_table = false;
    let mut after_rule = false;
    for line in text.lines() {
        let t = line.trim();
        if t.starts_with("% time") {
            in_table = true;
            continue;
        }
        if !in_table {
            continue;
        }
        if t.starts_with("------") {
            if after_rule {
                break;
            }
            after_rule = true;
            continue;
        }
        if t.is_empty() {
            continue;
        }
        let cols: Vec<&str> = t.split_whitespace().collect();
        if cols.last() == Some(&"total") {
            continue;
        }
        let parsed = match cols.as_slice() {
            [pct, secs, _usecs, calls, errors, name] => {
                match (
                    pct.parse::<f64>(),
                    secs.parse::<f64>(),
                    calls.parse::<i64>(),
                    errors.parse::<i64>(),
                ) {
                    (Ok(pct), Ok(secs), Ok(calls), Ok(errors)) => {
                        Some((pct, secs, calls, errors, *name))
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        match parsed {
            Some((pct, secs, calls, errors, name)) => {
                let mut rec = BTreeMap::new();
                rec.insert("percent".to_string(), Value::Float(pct));
                rec.insert("seconds".to_string(), Value::Float(secs));
                rec.insert("calls".to_string(), Value::Int(calls));
                rec.insert("errors".to_string(), Value::Int(errors));
                rec.insert("name".to_string(), Value::Str(name.to_string()));
                rows.push(Value::Record(rec));
            }
            None => unparsed += 1,
        }
    }
    (rows, unparsed)
}

/// One line of `nm --demangle` output: `address type name`, or `type name` for
/// an undefined symbol, whose address is null. A demangled name may contain
/// spaces, so only the first fields are split off.
fn nm_record(line: &str) -> Value {
    let mut rec = BTreeMap::new();
    let t = line.trim();
    let (address, rest) = match t.split_once(' ') {
        Some((first, rest)) if first.len() >= 8 && first.bytes().all(|b| b.is_ascii_hexdigit()) => {
            (Value::Str(first.to_string()), rest.trim_start())
        }
        _ => (Value::Null, t),
    };
    match rest.split_once(' ') {
        Some((ty, name)) if ty.len() == 1 && !name.trim().is_empty() => {
            rec.insert("address".to_string(), address);
            rec.insert("type".to_string(), Value::Str(ty.to_string()));
            rec.insert("name".to_string(), Value::Str(name.trim().to_string()));
        }
        _ => {
            rec.insert("line".to_string(), Value::Str(line.to_string()));
        }
    }
    Value::Record(rec)
}

/// Directives in a logrotate configuration are checked before the tool runs.
/// A path that is absolute, starts with '~', or contains '..' could reach
/// outside the workspace, and a directive in LOGROTATE_REFUSED runs a program.
fn logrotate_config_check(builtin: &str, text: &str) -> Result<()> {
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        for token in line.split_whitespace() {
            let word = token.trim_matches(|c| c == '"' || c == '\'');
            if LOGROTATE_REFUSED.contains(&word) {
                return Err(crate::safety::policy_deny(
                    builtin,
                    format!("{builtin}: the configuration uses `{word}`, which runs a program or sends mail"),
                    "remove that directive; this call runs logrotate without a shell and cannot see the commands it would run",
                ));
            }
            let absolute = word.starts_with('/')
                || word.starts_with('\\')
                || word.starts_with('~')
                || word.as_bytes().get(1) == Some(&b':');
            if absolute || word.contains("..") {
                return Err(crate::safety::policy_deny(
                    builtin,
                    format!("{builtin}: the configuration names `{word}`, which may lie outside the workspace"),
                    "use paths relative to the configuration file, with no '..', so every file it touches is inside the workspace",
                ));
            }
        }
    }
    Ok(())
}

/// journalctl — the most recent entries of the systemd journal, optionally of one unit.
/// Usage: journalctl(), journalctl(count) or journalctl(count, unit). count is
/// 1..=1000 and defaults to 50. Returns an Array of entries, each a Record of
/// the journal's JSON fields. Linux only; elsewhere the call is E_UNIMPLEMENTED
/// after its arguments are checked. A line that is not JSON is E_TOOL_FAILED,
/// never skipped, and output past 16 MiB is E_BUDGET_EXCEEDED.
///
/// On Windows the entries are the newest `count` events of the System log, as
/// Records {time, provider, level, id, message}. `unit` is then an event
/// provider's name, such as "Service Control Manager". Nothing else maps: the
/// Linux call takes no priority, so none is accepted here.
fn bi_journalctl(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("journalctl", &input)?;
    k8s_max_args("journalctl", &args, 2)?;
    let count = match args.first() {
        None => 50,
        Some(Value::Int(n)) if (1..=1000).contains(n) => *n,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "journalctl",
                "count: Int 1..=1000",
                other.type_name(),
            ))
        }
    };
    #[cfg(windows)]
    let unit = k8s_arg("journalctl", "unit", &args, 1, journal_provider)?;
    #[cfg(not(windows))]
    let unit = k8s_arg("journalctl", "unit", &args, 1, journal_unit)?;
    #[cfg(windows)]
    {
        journal_windows(count, unit)
    }
    #[cfg(target_os = "linux")]
    {
        let count_s = count.to_string();
        let mut argv: Vec<&str> = vec!["-n", count_s.as_str(), "-o", "json", "--no-pager"];
        if let Some(u) = unit.as_deref() {
            argv.extend(["-u", u]);
        }
        let run = tool_run(
            "journalctl",
            "journalctl",
            None,
            &argv,
            Keep::Head(TOOL_MAX_JSON),
            TOOL_DEADLINE_SECS,
        )?;
        let text = tool_text("journalctl", run)?;
        let mut entries = Vec::new();
        for line in text.lines().filter(|l| !l.trim().is_empty()) {
            let json = serde_json::from_str::<serde_json::Value>(line).map_err(|e| {
                crate::safety::tool_failed(
                    "journalctl",
                    "journalctl -o json",
                    Some(0),
                    &format!("printed a line that is not JSON ({e})"),
                )
            })?;
            entries.push(json_to_value(json));
        }
        Ok(Value::Array(entries))
    }
    #[cfg(not(any(windows, target_os = "linux")))]
    {
        let _ = (count, unit);
        Err(crate::safety::unimplemented(
            "journalctl",
            "journalctl reads the systemd journal on Linux and the event log on Windows; NOTHING WAS READ on this operating system",
            "cat(path) reads a log file on every OS",
        ))
    }
}

/// An event provider name for journalctl on Windows: letters, digits, space,
/// and - _ . only. The name goes inside a single-quoted PowerShell string, so
/// nothing PowerShell would read as syntax is allowed.
#[cfg(windows)]
fn journal_provider(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.trim().is_empty()
        && value.len() <= 256
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b' ' | b'-' | b'_' | b'.'));
    if well_formed {
        Ok(value.to_string())
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be an event provider name (letters, digits, space and - _ .), got {value:?}"
        )))
    }
}

/// journalctl on Windows: the newest `count` events of the System log, or of
/// one provider. A provider with no events is an empty Array.
#[cfg(windows)]
fn journal_windows(count: i64, provider: Option<String>) -> Result<Value> {
    let filter = match provider.as_deref() {
        Some(p) => format!("@{{LogName='System'; ProviderName='{p}'}}"),
        None => "@{LogName='System'}".to_string(),
    };
    let script = WIN_JOURNAL_SCRIPT
        .replace("__FILTER__", &filter)
        .replace("__COUNT__", &count.to_string());
    Ok(Value::Array(win_event_rows("journalctl", &script)?))
}

/// Get-WinEvent streams the newest event first. A filter that matches nothing
/// raises a NoMatching error, caught here and printed as []. Any other error
/// stops the script under ErrorActionPreference Stop and exits non-zero.
#[cfg(windows)]
const WIN_JOURNAL_SCRIPT: &str = r#"$ErrorActionPreference='Stop'; $OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=$OutputEncoding; $rows=@(); try { $rows=@(Get-WinEvent -FilterHashtable __FILTER__ -MaxEvents __COUNT__ | ForEach-Object { [pscustomobject]@{ time=$_.TimeCreated.ToString('o'); provider=$_.ProviderName; level=$_.LevelDisplayName; id=$_.Id; message=$_.Message } }) } catch { if ($_.FullyQualifiedErrorId -like 'NoMatching*') { $rows=@() } else { throw } }; ConvertTo-Json -InputObject $rows -Depth 3 -Compress"#;

/// pkg_history on Windows: the MsiInstaller events 1033 (installed) and 1034
/// (removed) in the Application log. They carry the product name and version as
/// properties, and status 0 is success; other statuses are failed transactions
/// and are left out. Select-Object -First stops the read at the limit.
#[cfg(windows)]
const WIN_PKG_HISTORY_SCRIPT: &str = r#"$ErrorActionPreference='Stop'; $OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=$OutputEncoding; $rows=@(); try { $rows=@(Get-WinEvent -FilterHashtable @{LogName='Application'; ProviderName='MsiInstaller'; Id=1033,1034} | Where-Object { $_.Properties.Count -ge 4 -and [string]$_.Properties[3].Value -eq '0' } | Select-Object -First __LIMIT__ | ForEach-Object { [pscustomobject]@{ time=$_.TimeCreated.ToString('o'); action=$(if ($_.Id -eq 1033) { 'install' } else { 'remove' }); package=[string]$_.Properties[0].Value; version=[string]$_.Properties[1].Value } }) } catch { if ($_.FullyQualifiedErrorId -like 'NoMatching*') { $rows=@() } else { throw } }; ConvertTo-Json -InputObject $rows -Depth 3 -Compress"#;

/// Run one event-log script under the tool deadline and return its records.
/// The script prints a JSON array. Anything else is an unreadable answer, never
/// an empty one.
#[cfg(windows)]
fn win_event_rows(builtin: &str, script: &str) -> Result<Vec<Value>> {
    let mut cmd = std::process::Command::new("powershell");
    cmd.args([
        "-NoLogo",
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        script,
    ])
    .stdin(std::process::Stdio::null());
    let output = bounded_cmd_output(builtin, "powershell", cmd, TOOL_DEADLINE_SECS)?;
    let text = probe_stdout(builtin, "powershell", output)?;
    let items = match serde_json::from_str::<serde_json::Value>(&text) {
        Ok(serde_json::Value::Array(items)) => items,
        _ => return Err(net_unparsed(builtin, "powershell")),
    };
    items
        .into_iter()
        .map(|item| match item {
            obj @ serde_json::Value::Object(_) => Ok(json_to_value(obj)),
            _ => Err(net_unparsed(builtin, "powershell")),
        })
        .collect()
}

/// 961: bi_lsof - List open files.
fn bi_lsof(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    linux_diagnostics::no_pipeline_input("lsof", &input)?;
    let path = match args.as_slice() {
        [] => None,
        [Value::Str(p)] => {
            linux_diagnostics::file_path("lsof", p)?;
            Some(p.clone())
        }
        [other] => {
            return Err(crate::safety::bad_arg(
                "lsof",
                "a file path String, or no argument",
                other.type_name(),
            ))
        }
        _ => {
            return Err(crate::safety::arg_err(
                "lsof: expected no argument, or one file path",
            ))
        }
    };
    #[cfg(unix)]
    {
        let limit = std::time::Duration::from_secs(30);
        let mut argv = vec!["-P".to_string(), "-n".to_string()];
        match &path {
            Some(p) => {
                if !std::path::Path::new(p).exists() {
                    return Err(crate::safety::not_found("lsof", "file", p));
                }
                argv.push(p.clone());
            }
            None => argv.push("-i".to_string()),
        }
        let run = linux_diagnostics::run_bounded("lsof", "lsof", "lsof", &argv, limit)?;
        // lsof exits 1 when nothing matched; with nothing on stderr that is an
        // empty answer, not a failure.
        if run.code == Some(1)
            && !run.timed_out
            && !run.truncated
            && run.stdout.trim().is_empty()
            && run.stderr.trim().is_empty()
        {
            return Ok(Value::Array(vec![]));
        }
        linux_diagnostics::require_success("lsof", "lsof", &run, limit)?;
        let mut lines = run.stdout.lines();
        let headers: Vec<String> = match lines.next() {
            Some(h) => h.split_whitespace().map(|h| h.to_lowercase()).collect(),
            None => return Ok(Value::Array(vec![])),
        };
        let entries: Vec<Value> = lines
            .filter(|line| !line.trim().is_empty())
            .map(|line| {
                let cols = linux_diagnostics::columns(line, headers.len());
                let mut rec = BTreeMap::new();
                for (header, col) in headers.iter().zip(cols) {
                    rec.insert(header.clone(), Value::Str(col.to_string()));
                }
                Value::Record(rec)
            })
            .collect();
        Ok(Value::Array(entries))
    }
    #[cfg(windows)]
    {
        match path {
            None => lsof_windows_sockets(),
            Some(_) => Err(crate::safety::unimplemented(
                "lsof",
                "the processes holding a file open are not read on Windows: no shipped source lists open files (handle.exe is Sysinternals, not shipped); NOTHING WAS LISTED",
                "net_connections() lists sockets",
            )),
        }
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = path;
        Err(crate::safety::unimplemented(
            "lsof",
            "lsof runs on Linux and macOS only; NOTHING WAS LISTED on this operating system",
            "netstat_info() lists this machine's network connections on every OS",
        ))
    }
}

/// strace_cmd — trace the system calls of one program and summarise them.
/// Usage: strace_cmd(command). The command is split on whitespace into a program
/// and its arguments and run directly, with no shell; the program may not begin
/// with '-'. Returns {command, exit_code, stdout, raw, syscalls, unparsed_rows}.
/// The exit code is the traced program's, which is the answer here, so it is
/// data and not a failure of the trace. macOS uses dtruss; elsewhere strace, and
/// where it is not installed the call is E_TOOL_MISSING.
fn bi_strace_cmd(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("strace_cmd", &input)?;
    k8s_max_args("strace_cmd", &args, 1)?;
    let command = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "strace_cmd: expected command string",
            ))
        }
    };
    let words = argv_words("strace_cmd", &command)?;
    crate::safety::guard_exec("strace", &command)?;
    let macos = cfg!(target_os = "macos");
    let tracer = if macos { "dtruss" } else { "strace" };
    let mut argv: Vec<&str> = if macos {
        Vec::new()
    } else {
        vec!["-c", "-e", "trace=all", "--"]
    };
    argv.extend(words.iter().map(String::as_str));
    let run = tool_run_stderr(
        "strace_cmd",
        tracer,
        None,
        &argv,
        Keep::Tail(TOOL_MAX_TEXT),
        TOOL_MAX_TEXT,
        TOOL_DEADLINE_SECS,
    )?;
    let (syscalls, unparsed) = if macos {
        (Vec::new(), 0)
    } else {
        strace_summary(&run.stderr)
    };
    let mut rec = BTreeMap::new();
    rec.insert("command".to_string(), Value::Str(command));
    rec.insert("exit_code".to_string(), Value::Int(exit_code_of(&run)));
    rec.insert("stdout".to_string(), Value::Str(run.stdout.clone()));
    rec.insert("raw".to_string(), Value::Str(run.stderr.clone()));
    rec.insert("syscalls".to_string(), Value::Array(syscalls));
    rec.insert("unparsed_rows".to_string(), Value::Int(unparsed as i64));
    Ok(Value::Record(rec))
}

/// top — Process snapshot, largest resident memory first (cross-platform via sysinfo).
/// Usage: top_snapshot() or top_snapshot(count), count 1..=10000, default 30.
/// Each entry is {pid, name, cpu_percent, memory_bytes, memory_mb}. CPU use is a
/// difference between two samples, so the call takes one sampling interval.
fn bi_top_snapshot(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("top_snapshot", &input)?;
    k8s_max_args("top_snapshot", &args, 1)?;
    let count = match args.first() {
        None => 30,
        Some(Value::Int(n)) if (1..=10_000).contains(n) => *n as usize,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "top_snapshot",
                "count: Int 1..=10000",
                other.type_name(),
            ))
        }
    };
    let mut sys = System::new_all();
    sys.refresh_all();
    // CPU use is measured between two samples; one sample reads 0 for every process.
    std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL);
    sys.refresh_all();
    let mut procs: Vec<_> = sys.processes().iter().collect();
    procs.sort_by(|a, b| b.1.memory().cmp(&a.1.memory()));
    let entries: Vec<Value> = procs
        .iter()
        .take(count)
        .map(|(pid, p)| {
            let mut rec = BTreeMap::new();
            rec.insert("pid".to_string(), Value::Int(pid.as_u32() as i64));
            rec.insert(
                "name".to_string(),
                Value::Str(p.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "cpu_percent".to_string(),
                Value::Float(p.cpu_usage() as f64),
            );
            rec.insert("memory_bytes".to_string(), Value::Int(p.memory() as i64));
            rec.insert(
                "memory_mb".to_string(),
                Value::Float(p.memory() as f64 / 1_048_576.0),
            );
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// 970: bi_dd_copy - Copy with `dd if=<source> of=<destination>` (Unix; Windows
/// copies in-process, see dd_copy_in_process).
///
/// Each operand is one argv element, so a path cannot add a second operand. It
/// used to drop an options value that was not a Record, any key but `bs` and
/// `count`, and a `count` that was not an Int; a failed copy came back as a
/// record with `success: false`; and `dd` ran with no deadline.
fn bi_dd_copy(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("dd_copy", &input)?;
    let text = |i: usize, what: &str| -> Result<String> {
        match args.get(i) {
            Some(Value::Str(s)) if !s.is_empty() => Ok(s.clone()),
            other => Err(crate::safety::bad_arg(
                "dd_copy",
                &format!("{what}: a non-empty String"),
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            )),
        }
    };
    let src = text(0, "source")?;
    let dst = text(1, "destination")?;
    let mut operands = vec![format!("if={src}"), format!("of={dst}")];
    match args.get(2) {
        None => {}
        Some(Value::Record(opts)) => {
            for (key, value) in opts {
                match (key.as_str(), value) {
                    ("bs", Value::Str(bs)) if dd_block_size(bs) => {
                        operands.push(format!("bs={bs}"))
                    }
                    ("bs", Value::Int(n)) if *n >= 1 => operands.push(format!("bs={n}")),
                    ("count", Value::Int(n)) if *n >= 1 => operands.push(format!("count={n}")),
                    ("bs", v) | ("count", v) => {
                        return Err(crate::safety::bad_arg(
                            "dd_copy",
                            "bs: a positive Int or a size such as 4M; count: a positive Int",
                            &format!("{key} = {}", v.type_name()),
                        ))
                    }
                    _ => {
                        return Err(crate::safety::bad_arg(
                            "dd_copy",
                            "options with only bs and count",
                            key,
                        ))
                    }
                }
            }
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "dd_copy",
                "options: a Record {bs?, count?}",
                other.type_name(),
            ))
        }
    }
    #[cfg(windows)]
    {
        dd_copy_in_process(&src, &dst, &operands)
    }
    #[cfg(not(windows))]
    {
        let argv: Vec<&str> = operands.iter().map(String::as_str).collect();
        let run = tool_run(
            "dd_copy",
            "dd",
            None,
            &argv,
            Keep::Tail(TOOL_STDERR_TAIL),
            TOOL_LONG_DEADLINE_SECS,
        )?;
        if !run.success {
            return Err(crate::safety::tool_failed(
                "dd_copy",
                &run.command,
                run.code,
                &run.stderr,
            ));
        }
        let mut rec = BTreeMap::new();
        rec.insert("success".to_string(), Value::Bool(true));
        // dd reports what it copied on stderr.
        rec.insert("output".to_string(), Value::Str(run.stderr));
        Ok(Value::Record(rec))
    }
}

/// Largest block dd_copy's in-process copy reads at once.
#[cfg(windows)]
const DD_BLOCK_MAX: u64 = 64 * 1024 * 1024;

/// The byte count of a `dd` block size already checked by [`dd_block_size`].
#[cfg(windows)]
fn dd_block_bytes(bs: &str) -> Option<u64> {
    let (digits, unit) = match bs.char_indices().last() {
        Some((i, c)) if c.is_ascii_alphabetic() => {
            let unit: u64 = match c {
                'c' => 1,
                'w' => 2,
                'b' => 512,
                'k' | 'K' => 1 << 10,
                'M' => 1 << 20,
                'G' => 1 << 30,
                'T' => 1 << 40,
                _ => return None,
            };
            (&bs[..i], unit)
        }
        _ => (bs, 1),
    };
    digits.parse::<u64>().ok()?.checked_mul(unit)
}

/// Windows: dd's copy done in-process with the operands dd_copy built. The block
/// size and count are the ones the options gave (512 and no count when absent).
/// The Unix run has a 900 s deadline; this one is checked between blocks. The
/// output is the three report lines dd prints on stderr.
#[cfg(windows)]
fn dd_copy_in_process(src: &str, dst: &str, operands: &[String]) -> Result<Value> {
    use std::io::{Read as _, Write as _};
    const NAME: &str = "dd_copy";
    let bs_text = operands
        .iter()
        .find_map(|o| o.strip_prefix("bs="))
        .unwrap_or("512");
    let block = dd_block_bytes(bs_text)
        .filter(|n| (1..=DD_BLOCK_MAX).contains(n))
        .ok_or_else(|| crate::safety::bad_arg(NAME, "a block size of at most 64M", bs_text))?;
    let count: Option<u64> = operands
        .iter()
        .find_map(|o| o.strip_prefix("count="))
        .map(|text| {
            text.parse::<u64>()
                .map_err(|_| crate::safety::bad_arg(NAME, "a positive Int", text))
        })
        .transpose()?;
    linux_diagnostics::file_path(NAME, src)?;
    linux_diagnostics::output_path(NAME, dst)?;
    // dd truncates its output before it reads, so a copy onto its own source
    // would destroy the source. Refuse it.
    let same = match (std::fs::canonicalize(src), std::fs::canonicalize(dst)) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    };
    if same {
        return Err(crate::safety::bad_arg(
            NAME,
            "a destination other than the source",
            dst,
        ));
    }
    let mut input = std::fs::File::open(src).map_err(|e| dd_io(NAME, src, &e))?;
    // Record dst's pre-image (or its absence) before File::create truncates it.
    crate::tx::snapshot(dst);
    let mut output = std::fs::File::create(dst).map_err(|e| dd_io(NAME, dst, &e))?;
    let started = std::time::Instant::now();
    let limit = std::time::Duration::from_secs(TOOL_LONG_DEADLINE_SECS);
    let mut buf = vec![0u8; block as usize];
    let (mut full_in, mut part_in, mut full_out, mut part_out, mut bytes) =
        (0u64, 0u64, 0u64, 0u64, 0u64);
    let mut blocks = 0u64;
    loop {
        if let Some(n) = count {
            if blocks >= n {
                break;
            }
        }
        if started.elapsed() > limit {
            return Err(crate::safety::budget_exceeded(
                NAME,
                format!("the copy ran past {TOOL_LONG_DEADLINE_SECS} s and was stopped"),
                "copy less with count, or in smaller parts",
            ));
        }
        let n = match input.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(dd_io(NAME, src, &e)),
        };
        output
            .write_all(&buf[..n])
            .map_err(|e| dd_io(NAME, dst, &e))?;
        if n as u64 == block {
            full_in += 1;
            full_out += 1;
        } else {
            part_in += 1;
            part_out += 1;
        }
        bytes += n as u64;
        blocks += 1;
    }
    output.flush().map_err(|e| dd_io(NAME, dst, &e))?;
    let mut rec = BTreeMap::new();
    rec.insert("success".to_string(), Value::Bool(true));
    rec.insert(
        "output".to_string(),
        Value::Str(format!(
            "{full_in}+{part_in} records in\n{full_out}+{part_out} records out\n{bytes} bytes copied"
        )),
    );
    Ok(Value::Record(rec))
}

/// The coded error for a file dd_copy could not open, read or write.
#[cfg(windows)]
fn dd_io(builtin: &str, path: &str, e: &std::io::Error) -> anyhow::Error {
    match e.kind() {
        std::io::ErrorKind::NotFound => crate::safety::not_found(builtin, "file", path),
        std::io::ErrorKind::PermissionDenied => crate::safety::os_denied(
            builtin,
            format!("`{path}` is not accessible: {e}"),
            "check the path and its permissions",
        ),
        // A device that stops answering, a full disk: still a coded refusal.
        _ => crate::safety::bad_state(
            builtin,
            &format!("`{path}` failed: {e}"),
            "a readable source and a writable destination",
        ),
    }
}

/// A `dd` block size: digits with at most one unit suffix (`512`, `4M`, `1k`).
fn dd_block_size(bs: &str) -> bool {
    let digits = bs.trim_end_matches(|c: char| "cwbkKMGT".contains(c));
    !digits.is_empty()
        && digits.len() <= 12
        && bs.len() - digits.len() <= 1
        && digits.bytes().all(|b| b.is_ascii_digit())
        && digits.bytes().any(|b| b != b'0')
}

/// 975: bi_mount_info - Detailed mount info (cross-platform via sysinfo::Disks).
fn bi_mount_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let disks = Disks::new_with_refreshed_list();
    let entries: Vec<Value> = disks
        .iter()
        .map(|d| {
            let mut rec = BTreeMap::new();
            rec.insert(
                "device".to_string(),
                Value::Str(d.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "mount_point".to_string(),
                Value::Str(d.mount_point().to_string_lossy().to_string()),
            );
            rec.insert(
                "file_system".to_string(),
                Value::Str(String::from_utf8_lossy(d.file_system().as_encoded_bytes()).to_string()),
            );
            rec.insert(
                "total_space".to_string(),
                Value::Int(d.total_space() as i64),
            );
            rec.insert(
                "available_space".to_string(),
                Value::Int(d.available_space() as i64),
            );
            rec.insert("is_removable".to_string(), Value::Bool(d.is_removable()));
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ============================================================================
// Remote Access Builtins (980-994)
// SSH, SCP, Rsync, SFTP, RDP, VNC, Telnet, Curl
// ============================================================================

// [removed duplicate] use std::collections::BTreeMap;
// [removed duplicate] use std::process::Command;
// [removed duplicate] use anyhow::{anyhow, Result};
// [removed duplicate] use crate::value::Value;

// ---------------------------------------------------------------------------
// Shared runner for the remote, crypto and archive tools below.
//
// A tool starts from an argv (never a shell), with a null or fixed stdin, under
// a deadline. Its output is bounded, and a run that exceeds a bound is stopped
// and refused (E_BUDGET_EXCEEDED): a cut-off answer reads like a complete one.
// ---------------------------------------------------------------------------

/// Most bytes a tool run may write to captured stdout, or to stderr.
const TOOL_OUTPUT_CAP: u64 = 16 * 1024 * 1024;
/// Most bytes a tool run may write to a file. For xz and zstd this is the
/// decompressed size, which is the bomb a small archive can hide.
const FILE_OUTPUT_CAP: u64 = 1024 * 1024 * 1024;
/// Deadline for a command or transfer that contacts a host, or that may stop
/// for a prompt that nobody will answer.
const NETWORK_DEADLINE_SECS: u64 = 120;
/// Deadline for a local crypto, archive or transfer run.
const LOCAL_DEADLINE_SECS: u64 = 600;
/// Most bytes of JSON text the jq builtins accept.
const JQ_INPUT_CAP: usize = 64 * 1024 * 1024;
/// Options every ssh run gets: no terminal, and no prompt that waits for a
/// person to type. A host that needs a password fails instead of hanging.
const SSH_OPTS: &[&str] = &["-T", "-o", "BatchMode=yes", "-o", "ConnectTimeout=20"];
/// The scp equivalent of [`SSH_OPTS`].
const SCP_OPTS: &[&str] = &["-o", "BatchMode=yes", "-o", "ConnectTimeout=20"];

const HALT_NONE: u8 = 0;
const HALT_OVER_CAP: u8 = 1;
const HALT_IO: u8 = 2;

/// Copies one pipe into `sink` until the pipe closes. When the stream passes
/// `cap`, or a read or write fails, it records why in `halt` and stops.
fn pump<R, W>(
    mut pipe: R,
    sink: std::sync::Arc<std::sync::Mutex<W>>,
    cap: u64,
    halt: std::sync::Arc<std::sync::atomic::AtomicU8>,
    done: std::sync::mpsc::Sender<()>,
) where
    R: std::io::Read + Send + 'static,
    W: std::io::Write + Send + 'static,
{
    use std::io::ErrorKind;
    use std::sync::atomic::Ordering;
    std::thread::spawn(move || {
        let mut total: u64 = 0;
        let mut chunk = [0u8; 8192];
        loop {
            match pipe.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    total = total.saturating_add(n as u64);
                    if total > cap {
                        halt.store(HALT_OVER_CAP, Ordering::SeqCst);
                        break;
                    }
                    let mut w = sink
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    if w.write_all(&chunk[..n]).is_err() {
                        halt.store(HALT_IO, Ordering::SeqCst);
                        break;
                    }
                }
                Err(e) if e.kind() == ErrorKind::Interrupted => {}
                Err(_) => {
                    halt.store(HALT_IO, Ordering::SeqCst);
                    break;
                }
            }
        }
        let _ = done.send(());
    });
}

/// The refusal for a run that was stopped: over a cap, a failed pipe, or the deadline.
fn halt_error(builtin: &str, tool: &str, flag: u8, secs: u64, cap: u64) -> anyhow::Error {
    match flag {
        HALT_OVER_CAP => crate::safety::budget_exceeded(
            builtin,
            format!("{tool} wrote more than {cap} bytes and was stopped"),
            "the output would be cut short, so it is refused; narrow the request",
        ),
        HALT_IO => crate::safety::tool_failed(
            builtin,
            tool,
            None,
            "its output could not be read or written",
        ),
        _ => crate::safety::budget_exceeded(
            builtin,
            format!("{tool} did not finish within {secs} s and was stopped"),
            "the call is refused rather than answered in part; check the host, file or network and try again",
        ),
    }
}

/// Runs `cmd` for at most `secs`. Stdout goes to `stdout`; stderr is captured.
/// Returns the exit status and the stderr text. A run that exceeds `cap`, or
/// its deadline, is killed and refused. A nonzero exit is not an error here;
/// see [`tool_ok`].
fn run_tool<W>(
    builtin: &str,
    tool: &str,
    mut cmd: std::process::Command,
    stdin: Option<Vec<u8>>,
    stdout: std::sync::Arc<std::sync::Mutex<W>>,
    secs: u64,
    cap: u64,
) -> Result<(std::process::ExitStatus, String)>
where
    W: std::io::Write + Send + 'static,
{
    use std::io::Write as _;
    use std::process::Stdio;
    use std::sync::atomic::{AtomicU8, Ordering};
    use std::sync::{mpsc, Arc, Mutex, PoisonError};
    use std::time::{Duration, Instant};

    let halt = Arc::new(AtomicU8::new(HALT_NONE));
    cmd.stdin(if stdin.is_some() {
        Stdio::piped()
    } else {
        Stdio::null()
    })
    .stdout(Stdio::piped())
    .stderr(Stdio::piped());
    #[cfg(unix)]
    {
        // The child leads its own group, so a deadline or cap kills its whole tree.
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut child = cmd
        .spawn()
        .map_err(|e| crate::safety::spawn_error(builtin, tool, &e))?;
    #[cfg(windows)]
    let job = TreeJob::for_child(&child);
    let (Some(out_pipe), Some(err_pipe)) = (child.stdout.take(), child.stderr.take()) else {
        #[cfg(windows)]
        kill_job(job.as_ref());
        kill_tree(&mut child);
        return Err(crate::safety::tool_failed(
            builtin,
            tool,
            None,
            "its output pipes were not opened",
        ));
    };
    if let (Some(payload), Some(mut pipe)) = (stdin, child.stdin.take()) {
        // Detached: a child that never reads its stdin must not hold this call.
        // A failed write just ends early, and the exit status reports why.
        std::thread::spawn(move || {
            let _ = pipe.write_all(&payload);
        });
    }
    let stderr = Arc::new(Mutex::new(Vec::<u8>::new()));
    let (out_done, out_closed) = mpsc::channel();
    let (err_done, err_closed) = mpsc::channel();
    pump(out_pipe, stdout, cap, Arc::clone(&halt), out_done);
    pump(
        err_pipe,
        Arc::clone(&stderr),
        cap,
        Arc::clone(&halt),
        err_done,
    );

    let limit = Duration::from_secs(secs);
    let started = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => {}
            Err(e) => {
                #[cfg(windows)]
                kill_job(job.as_ref());
                kill_tree(&mut child);
                return Err(crate::safety::tool_failed(
                    builtin,
                    tool,
                    None,
                    &e.to_string(),
                ));
            }
        }
        if halt.load(Ordering::SeqCst) != HALT_NONE || started.elapsed() >= limit {
            #[cfg(windows)]
            kill_job(job.as_ref());
            kill_tree(&mut child);
            return Err(halt_error(
                builtin,
                tool,
                halt.load(Ordering::SeqCst),
                secs,
                cap,
            ));
        }
        std::thread::sleep(Duration::from_millis(10));
    };
    // The pipes close with the child. A grandchild that keeps one open must not
    // hold the call, and output that has not closed is not returned.
    let wait = Duration::from_secs(2);
    let closed = out_closed.recv_timeout(wait).is_ok() && err_closed.recv_timeout(wait).is_ok();
    let flag = halt.load(Ordering::SeqCst);
    if !closed || flag != HALT_NONE {
        // A descendant still holds a pipe, or the run was halted: kill its group
        // so nothing it started keeps running after the call returns.
        #[cfg(windows)]
        kill_job(job.as_ref());
        kill_group(child.id());
    }
    if flag != HALT_NONE {
        return Err(halt_error(builtin, tool, flag, secs, cap));
    }
    if !closed {
        return Err(crate::safety::tool_failed(
            builtin,
            tool,
            status.code(),
            "its output stayed open after it exited",
        ));
    }
    let bytes = stderr.lock().unwrap_or_else(PoisonError::into_inner);
    Ok((status, String::from_utf8_lossy(&bytes).into_owned()))
}

/// A nonzero exit is a coded tool failure, with the exit status and the tail of stderr.
fn tool_ok(
    builtin: &str,
    tool: &str,
    status: std::process::ExitStatus,
    stderr: &str,
) -> Result<()> {
    if status.success() {
        return Ok(());
    }
    Err(crate::safety::tool_failed(
        builtin,
        tool,
        status.code(),
        stderr_tail(stderr),
    ))
}

/// The last 4 KiB of a tool's stderr, for an error message.
fn stderr_tail(text: &str) -> &str {
    const KEEP: usize = 4096;
    let text = text.trim();
    if text.len() <= KEEP {
        return text;
    }
    let mut start = text.len() - KEEP;
    while !text.is_char_boundary(start) {
        start += 1;
    }
    text[start..].trim()
}

/// Runs a tool that answers on stdout. Returns that text and the stderr text
/// once the tool exits 0; any other exit is a coded tool failure.
fn run_checked(
    builtin: &str,
    tool: &str,
    cmd: std::process::Command,
    secs: u64,
) -> Result<(String, String)> {
    let out = std::sync::Arc::new(std::sync::Mutex::new(Vec::<u8>::new()));
    let (status, stderr) = run_tool(
        builtin,
        tool,
        cmd,
        None,
        std::sync::Arc::clone(&out),
        secs,
        TOOL_OUTPUT_CAP,
    )?;
    tool_ok(builtin, tool, status, &stderr)?;
    let bytes = std::mem::take(
        &mut *out
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner),
    );
    Ok((String::from_utf8_lossy(&bytes).into_owned(), stderr))
}

/// Runs a tool whose stdout is the new file `out_path`. The file is created
/// exclusively, so an existing file is refused, and it is removed when the run fails.
fn tool_to_new_file(builtin: &str, tool: &str, argv: &[&str], out_path: &str) -> Result<()> {
    let file = create_new_output(builtin, out_path)?;
    let sink = std::sync::Arc::new(std::sync::Mutex::new(file));
    let mut cmd = std::process::Command::new(tool);
    cmd.args(argv);
    let result = run_tool(
        builtin,
        tool,
        cmd,
        None,
        sink,
        LOCAL_DEADLINE_SECS,
        FILE_OUTPUT_CAP,
    )
    .and_then(|(status, stderr)| tool_ok(builtin, tool, status, &stderr));
    if result.is_err() {
        remove_partial(out_path);
    }
    result
}

/// Creates a new file for a tool's output. Existing files are refused, and the
/// check and the create are one open, so a file that appears meanwhile is refused too.
fn create_new_output(builtin: &str, path: &str) -> Result<std::fs::File> {
    std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|e| {
            if e.kind() == std::io::ErrorKind::AlreadyExists {
                crate::safety::bad_state(
                    builtin,
                    &format!("{path} already exists"),
                    "remove it first; the existing file is not overwritten",
                )
            } else {
                crate::safety::fs_error(builtin, path, &e)
            }
        })
}

/// Refuses an output path that already exists, for a tool that writes its own file.
fn refuse_existing(builtin: &str, path: &str) -> Result<()> {
    if std::path::Path::new(path).exists() {
        return Err(crate::safety::bad_state(
            builtin,
            &format!("{path} already exists"),
            "remove it first; the existing file is not overwritten",
        ));
    }
    Ok(())
}

/// Removes a file a failed run may have left. Only ever called on a path that
/// was checked absent before the run, so the file is the run's own.
fn remove_partial(path: &str) {
    let _ = std::fs::remove_file(path);
}

/// A caller value in a positional slot, refused when it could be read as an option.
fn refuse_option(builtin: &str, value: &str) -> Result<()> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])
}

/// The path must name an existing regular file.
fn regular_file_arg(builtin: &str, path: &str) -> Result<()> {
    let meta = std::fs::metadata(path).map_err(|e| crate::safety::fs_error(builtin, path, &e))?;
    if !meta.is_file() {
        return Err(crate::safety::bad_arg(builtin, "a regular file", path));
    }
    Ok(())
}

/// A `[user@]host` for ssh, scp and ssh-copy-id. It is refused when it could be
/// read as an option (`-oProxyCommand=…`), when it is empty, or when it holds a
/// character a host name, address or user name does not use.
fn ssh_target_arg(builtin: &str, what: &str, target: &str) -> Result<()> {
    refuse_option(builtin, target)?;
    let (user, host) = match target.rsplit_once('@') {
        Some((user, host)) => (Some(user), host),
        None => (None, target),
    };
    let chars_ok = target.chars().all(|c| {
        c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_' | ':' | '[' | ']' | '%' | '@')
    });
    let user_ok = match user {
        Some(user) => !user.is_empty() && !user.starts_with('-'),
        None => true,
    };
    if !target.is_empty()
        && target.len() <= 255
        && chars_ok
        && user_ok
        && !host.is_empty()
        && !host.starts_with('-')
    {
        return Ok(());
    }
    Err(crate::safety::bad_arg(
        builtin,
        &format!("{what} as [user@]host of letters, digits and . _ - : [ ] % @"),
        target,
    ))
}

/// A tunnel's destination: a host name, an IPv4 address, or a bracketed IPv6 address.
fn tunnel_host_arg(builtin: &str, host: &str) -> Result<()> {
    refuse_option(builtin, host)?;
    let ok = match host.strip_prefix('[').and_then(|h| h.strip_suffix(']')) {
        Some(addr) => {
            !addr.is_empty()
                && addr
                    .chars()
                    .all(|c| c.is_ascii_hexdigit() || matches!(c, ':' | '.'))
        }
        None => {
            !host.is_empty()
                && host.len() <= 253
                && host
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
        }
    };
    if ok {
        return Ok(());
    }
    Err(crate::safety::bad_arg(
        builtin,
        "remote_host as a host name, an IPv4 address or a bracketed IPv6 address",
        host,
    ))
}

/// An scp remote, `[user@]host:path`. The host is checked as [`ssh_target_arg`]
/// checks it. The path must be one file: it may not hold a shell
/// metacharacter, a glob, or a control character, because the remote side may
/// read it through a shell.
fn scp_remote_arg(builtin: &str, remote: &str) -> Result<()> {
    let bad = || crate::safety::bad_arg(builtin, "a remote of the form [user@]host:path", remote);
    // A user name ends at the first '@' that comes before any ':' or '/'. A
    // later '@' belongs to the path.
    let user_len = match remote.find('@') {
        Some(i) if !remote[..i].contains([':', '/']) => i + 1,
        _ => 0,
    };
    let rest = &remote[user_len..];
    let colon = if rest.starts_with('[') {
        rest.find("]:").map(|i| i + 1)
    } else {
        rest.find(':')
    };
    let Some(colon) = colon else {
        return Err(bad());
    };
    ssh_target_arg(builtin, "remote host", &remote[..user_len + colon])?;
    let path = &remote[user_len + colon + 1..];
    if path.is_empty() {
        return Err(bad());
    }
    if path
        .chars()
        .any(|c| c.is_control() || "`$;&|<>()'\"\\{}*?[]".contains(c))
    {
        return Err(crate::safety::bad_arg(
            builtin,
            "a remote path with no shell or glob characters (one file)",
            path,
        ));
    }
    Ok(())
}

/// A local scp operand. scp reads a path with a ':' in it as a host, so a local
/// path must not have one, apart from a Windows drive letter.
fn scp_local_arg(builtin: &str, path: &str) -> Result<()> {
    refuse_option(builtin, path)?;
    let bytes = path.as_bytes();
    let rest = if bytes.len() >= 2 && bytes[0].is_ascii_alphabetic() && bytes[1] == b':' {
        &path[2..]
    } else {
        path
    };
    if rest.contains(':') {
        return Err(crate::safety::bad_arg(
            builtin,
            "a local path without ':' (scp would read it as a host)",
            path,
        ));
    }
    Ok(())
}

/// The text, when it is one OpenSSH public key line: a key type, a base64 blob
/// and an optional comment, and nothing else. Anything else is refused by the
/// caller, and its content is not echoed.
fn public_key_line(text: &str) -> Option<&str> {
    let line = text.trim();
    if line.is_empty() || line.len() > 16 * 1024 || line.contains(['\n', '\r']) {
        return None;
    }
    let mut parts = line.splitn(3, ' ');
    let kind = parts.next()?;
    let blob = parts.next()?;
    let kind_ok =
        (kind.starts_with("ssh-") || kind.starts_with("ecdsa-sha2-") || kind.starts_with("sk-"))
            && kind
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '@' | '.'));
    let blob_ok = !blob.is_empty()
        && blob
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '/' | '='));
    let comment_ok = match parts.next() {
        None => true,
        Some(comment) => comment
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '@' | '.' | '_' | '-' | '+' | ' ')),
    };
    if kind_ok && blob_ok && comment_ok {
        Some(line)
    } else {
        None
    }
}

// 980: bi_ssh_exec - Run one command on a remote host over ssh.
//
// The command is one string and the remote account's login shell reads it, so
// the remote side expands it as that shell does. The host never reaches a
// local shell. Exit 0 returns the output. Any other exit is E_TOOL_FAILED with
// the exit status and the tail of stderr. Output past the cap, or a run past
// its deadline, is refused.
fn bi_ssh_exec(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("ssh_exec", &input)?;
    let host = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_exec: first argument must be host string (user@host)",
            ))
        }
    };
    let command = match args.get(1) {
        Some(Value::Str(s)) if !s.trim().is_empty() && !s.contains('\0') => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_exec: second argument must be a non-empty command string",
            ))
        }
    };
    let port = match args.get(2) {
        Some(Value::Int(p)) => Some(*p),
        _ => None,
    };
    ssh_target_arg("ssh_exec", "host", &host)?;
    // Runs an arbitrary command on another host: the widest blast radius in the
    // builtin table. Checked after the arguments, so a refused call is not audited
    // as a run.
    crate::safety::guard_exec("ssh_exec", format!("ssh {} {}", host, command))?;
    let mut cmd = std::process::Command::new("ssh");
    cmd.args(SSH_OPTS);
    if let Some(p) = port {
        cmd.arg("-p").arg(p.to_string());
    }
    cmd.arg(&host).arg(&command);
    let (stdout, stderr) = run_checked("ssh_exec", "ssh", cmd, NETWORK_DEADLINE_SECS)?;
    Ok(rec(vec![
        ("stdout", s(&stdout)),
        ("stderr", s(&stderr)),
        ("exit_code", Value::Int(0)),
        ("success", Value::Bool(true)),
    ]))
}

// 981: bi_ssh_tunnel - Open a local port forward through an ssh host.
//
// ssh runs in the foreground (`-N`, not `-f`), so this process holds the ssh
// pid and the call answers it: proc_kill(pid) stops the tunnel. The call returns
// once the forward is listening, or fails when ssh exits or the deadline passes.
// The local port must be free before ssh starts: a connect to a port something
// else holds would report a tunnel that ssh never opened. ExitOnForwardFailure
// makes a port that cannot be bound an error rather than a silent tunnel that
// does nothing.
fn bi_ssh_tunnel(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("ssh_tunnel", &input)?;
    let local_port = match args.first() {
        Some(Value::Int(p)) => *p,
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_tunnel: first argument must be local_port (Int)",
            ))
        }
    };
    let remote_host = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_tunnel: second argument must be remote_host string",
            ))
        }
    };
    let remote_port = match args.get(2) {
        Some(Value::Int(p)) => *p,
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_tunnel: third argument must be remote_port (Int)",
            ))
        }
    };
    let ssh_host = match args.get(3) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_tunnel: fourth argument must be ssh_host string",
            ))
        }
    };
    for (what, port) in [("local_port", local_port), ("remote_port", remote_port)] {
        if !(1..=65535).contains(&port) {
            return Err(crate::safety::bad_arg(
                "ssh_tunnel",
                &format!("{what} in 1..=65535"),
                &port.to_string(),
            ));
        }
    }
    tunnel_host_arg("ssh_tunnel", &remote_host)?;
    ssh_target_arg("ssh_tunnel", "ssh_host", &ssh_host)?;
    // Checked above to be in 1..=65535.
    let port = local_port as u16;
    // Refused when something already holds the port. The probe listener is
    // dropped here, before ssh is started. A bind error other than "in use"
    // (for example a privileged port) is refused the same way, with the OS text.
    match std::net::TcpListener::bind(("127.0.0.1", port)) {
        Ok(listener) => drop(listener),
        Err(e) => {
            return Err(crate::safety::bad_arg(
                "ssh_tunnel",
                &format!("a local_port that is free on 127.0.0.1 (bind said: {e})"),
                &local_port.to_string(),
            ))
        }
    }
    let spec = format!("{local_port}:{remote_host}:{remote_port}");
    // ssh's stderr goes to a new file, not a pipe: nothing reads a pipe after
    // this call returns, and a full pipe would block ssh. The file name carries
    // the port and this process's pid, plus a uuid so a stale file cannot collide.
    let stderr_path = std::env::temp_dir().join(format!(
        "ae-ssh-tunnel-{local_port}-{}-{}.err",
        std::process::id(),
        uuid::Uuid::new_v4().simple()
    ));
    let stderr_path = stderr_path.to_string_lossy().into_owned();
    let stderr_file = create_new_output("ssh_tunnel", &stderr_path)?;
    let mut cmd = std::process::Command::new("ssh");
    cmd.args(["-N", "-o", "ExitOnForwardFailure=yes"])
        .args(SSH_OPTS)
        .arg("-L")
        .arg(&spec)
        .arg(&ssh_host)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(stderr_file);
    let mut child = match cmd.spawn() {
        Ok(child) => child,
        Err(e) => {
            remove_partial(&stderr_path);
            return Err(crate::safety::spawn_error("ssh_tunnel", "ssh", &e));
        }
    };
    drop(cmd);
    // Wait until the forward listens, ssh exits, or the deadline passes. The
    // deadline is the network one, or the evaluation's own if that is sooner.
    let mut limit = std::time::Duration::from_secs(NETWORK_DEADLINE_SECS);
    if let Some(left) = crate::safety::remaining_deadline() {
        limit = limit.min(left);
    }
    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    let started = std::time::Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                let stderr = std::fs::read_to_string(&stderr_path).unwrap_or_default();
                remove_partial(&stderr_path);
                return Err(crate::safety::tool_failed(
                    "ssh_tunnel",
                    "ssh",
                    status.code(),
                    &tail_text(stderr.trim(), 300),
                ));
            }
            Ok(None) => {}
            Err(e) => {
                let _ = child.kill();
                let _ = child.wait();
                remove_partial(&stderr_path);
                return Err(crate::safety::tool_failed(
                    "ssh_tunnel",
                    "ssh",
                    None,
                    &e.to_string(),
                ));
            }
        }
        if std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_millis(200))
            .is_ok()
        {
            break;
        }
        if started.elapsed() >= limit {
            let _ = child.kill();
            let _ = child.wait();
            remove_partial(&stderr_path);
            return Err(crate::safety::budget_exceeded(
                "ssh_tunnel",
                format!(
                    "ssh did not open the forward on 127.0.0.1:{port} within {:.1} s and was stopped",
                    limit.as_secs_f64()
                ),
                "the call is refused rather than answered in part; check the host, its key authentication and the network, and try again",
            ));
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
    // The forward is up. The child is not waited for: dropping it does not kill
    // it, and it is the tunnel. Its pid is the answer, and proc_wait may reap it.
    remove_partial(&stderr_path);
    let pid = i64::from(child.id());
    spawned_note(pid);
    Ok(rec(vec![
        ("success", Value::Bool(true)),
        ("pid", Value::Int(pid)),
        ("local_port", Value::Int(local_port)),
        ("remote_host", Value::Str(remote_host)),
        ("remote_port", Value::Int(remote_port)),
        ("ssh_host", Value::Str(ssh_host)),
    ]))
}

// 982: bi_ssh_keygen - Generate an SSH key pair.
//
// The private key is written with no passphrase (`-N ""`), so anyone who can
// read the file can use the key. A key or public-key file that already exists
// is refused, not replaced. The jail applies to the private key's path, so a
// default under ~/.ssh is refused unless that path is inside the workspace.
fn bi_ssh_keygen(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("ssh_keygen", &input)?;
    let key_type = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => "ed25519".to_string(),
    };
    if !matches!(key_type.as_str(), "ed25519" | "rsa" | "ecdsa") {
        return Err(crate::safety::bad_arg(
            "ssh_keygen",
            "type: ed25519, rsa or ecdsa",
            &key_type,
        ));
    }
    let filename = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            let home = std::env::var("HOME")
                .or_else(|_| std::env::var("USERPROFILE"))
                .unwrap_or_else(|_| ".".to_string());
            format!("{}/.ssh/id_{}", home, key_type)
        }
    };
    refuse_option("ssh_keygen", &filename)?;
    // The jail is checked first, so the existence test looks at the path the
    // key would really be written to.
    let filename = guard_local_write("ssh_keygen", &filename)?;
    let public = format!("{filename}.pub");
    refuse_existing("ssh_keygen", &filename)?;
    refuse_existing("ssh_keygen", &public)?;
    let mut cmd = std::process::Command::new("ssh-keygen");
    cmd.args(["-t", key_type.as_str(), "-f", filename.as_str(), "-N", ""]);
    match run_checked("ssh_keygen", "ssh-keygen", cmd, LOCAL_DEADLINE_SECS) {
        Ok((output, _)) => Ok(rec(vec![
            ("passphrase", Value::Bool(false)),
            ("type", Value::Str(key_type)),
            ("private_key", Value::Str(filename)),
            ("public_key", Value::Str(public)),
            ("output", Value::Str(output)),
        ])),
        Err(e) => {
            // Both paths were checked absent above, so anything there now is ours.
            remove_partial(&filename);
            remove_partial(&public);
            Err(e)
        }
    }
}

// 983: bi_ssh_copy_id - Install a public key in a remote account's authorized_keys.
//
// This writes to the remote host. The key must be one OpenSSH public-key line,
// so a private key or a stray file is refused without its content being shown.
// On Windows the line is appended by a remote shell command. Its quoting relies
// on the key holding no quote character, which public_key_line guarantees, and
// a grep keeps a second copy from being appended.
fn bi_ssh_copy_id(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("ssh_copy_id", &input)?;
    let host = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "ssh_copy_id: first argument must be host string (user@host)",
            ))
        }
    };
    let key_file = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            let home = std::env::var("HOME")
                .or_else(|_| std::env::var("USERPROFILE"))
                .unwrap_or_else(|_| ".".to_string());
            format!("{}/.ssh/id_ed25519.pub", home)
        }
    };
    ssh_target_arg("ssh_copy_id", "host", &host)?;
    refuse_option("ssh_copy_id", &key_file)?;
    let key_file = crate::safety::resolve_path_str(&key_file);
    regular_file_arg("ssh_copy_id", &key_file)?;
    let size = std::fs::metadata(&key_file).map(|m| m.len()).unwrap_or(0);
    if size > 16 * 1024 {
        return Err(crate::safety::bad_arg(
            "ssh_copy_id",
            "key_file: an OpenSSH public key",
            &key_file,
        ));
    }
    let text = read_text_capped("ssh_copy_id", &key_file)?;
    let Some(key) = public_key_line(&text) else {
        return Err(crate::safety::bad_arg(
            "ssh_copy_id",
            "key_file: an OpenSSH public key (type, base64, optional comment)",
            &key_file,
        ));
    };
    if cfg!(target_os = "windows") {
        // ssh-copy-id may not be installed here, so the key is appended by hand.
        let remote = format!(
            "mkdir -p ~/.ssh && (grep -qxF '{key}' ~/.ssh/authorized_keys 2>/dev/null || echo '{key}' >> ~/.ssh/authorized_keys) && chmod 700 ~/.ssh && chmod 600 ~/.ssh/authorized_keys"
        );
        let mut cmd = std::process::Command::new("ssh");
        cmd.args(["-T", "-o", "ConnectTimeout=20"])
            .arg(&host)
            .arg(&remote);
        run_checked("ssh_copy_id", "ssh", cmd, NETWORK_DEADLINE_SECS)?;
        Ok(rec(vec![
            ("success", Value::Bool(true)),
            ("method", s("manual")),
            ("host", Value::Str(host)),
        ]))
    } else {
        let mut cmd = std::process::Command::new("ssh-copy-id");
        cmd.args(["-i", key_file.as_str()]).arg(&host);
        run_checked("ssh_copy_id", "ssh-copy-id", cmd, NETWORK_DEADLINE_SECS)?;
        Ok(rec(vec![
            ("success", Value::Bool(true)),
            ("method", s("ssh-copy-id")),
            ("host", Value::Str(host)),
        ]))
    }
}

/// The value of an ssh config `Port` line: a decimal number from 1 to 65535.
/// Anything else is `None`.
fn ssh_port_value(val: &str) -> Option<i64> {
    val.trim()
        .parse::<u16>()
        .ok()
        .filter(|p| *p != 0)
        .map(i64::from)
}

// 984: bi_ssh_config - Read and parse SSH config file
fn bi_ssh_config(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let config_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            let home = std::env::var("HOME")
                .or_else(|_| std::env::var("USERPROFILE"))
                .unwrap_or_else(|_| ".".to_string());
            format!("{}/.ssh/config", home)
        }
    };
    // A missing file is E_NOT_FOUND from the read; a denied or oversized one
    // keeps its own code. Every failure used to read as "not found".
    let content = read_text_capped("ssh_config", &config_path)?;
    let mut hosts: Vec<Value> = Vec::new();
    let mut current: Option<BTreeMap<String, Value>> = None;
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = trimmed.splitn(2, char::is_whitespace).collect();
        if parts.len() < 2 {
            continue;
        }
        let key = parts[0].to_lowercase();
        let val = parts[1].trim().to_string();
        if key == "host" {
            if let Some(entry) = current.take() {
                hosts.push(Value::Record(entry));
            }
            let mut entry = BTreeMap::new();
            entry.insert("Host".to_string(), Value::Str(val));
            current = Some(entry);
        } else if let Some(ref mut entry) = current {
            match key.as_str() {
                "hostname" => {
                    entry.insert("HostName".to_string(), Value::Str(val));
                }
                "user" => {
                    entry.insert("User".to_string(), Value::Str(val));
                }
                "port" => {
                    // A malformed Port used to become 22, a connection to a
                    // port the host may not serve. It is refused instead.
                    let port = ssh_port_value(&val).ok_or_else(|| {
                        let host = match entry.get("Host") {
                            Some(Value::Str(h)) => h.as_str(),
                            _ => "?",
                        };
                        crate::safety::bad_arg(
                            "ssh_config",
                            "a Port number from 1 to 65535",
                            &format!("Port `{val}` for host `{host}`"),
                        )
                    })?;
                    entry.insert("Port".to_string(), Value::Int(port));
                }
                "identityfile" => {
                    entry.insert("IdentityFile".to_string(), Value::Str(val));
                }
                other => {
                    entry.insert(other.to_string(), Value::Str(val));
                }
            }
        }
    }
    if let Some(entry) = current {
        hosts.push(Value::Record(entry));
    }
    Ok(Value::Array(hosts))
}

// 985: bi_scp_upload - Copy one local file to a remote host with scp.
//
// The remote side is validated before the local file is looked at, so a bad
// remote is refused without touching the disk.
fn bi_scp_upload(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("scp_upload", &input)?;
    let local_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "scp_upload: first argument must be local_path string",
            ))
        }
    };
    let remote = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "scp_upload: second argument must be remote string (user@host:path)",
            ))
        }
    };
    let port = match args.get(2) {
        Some(Value::Int(p)) => Some(*p),
        _ => None,
    };
    scp_remote_arg("scp_upload", &remote)?;
    let local_path = crate::safety::resolve_path_str(&local_path);
    scp_local_arg("scp_upload", &local_path)?;
    regular_file_arg("scp_upload", &local_path)?;
    let mut cmd = std::process::Command::new("scp");
    cmd.args(SCP_OPTS);
    if let Some(p) = port {
        cmd.arg("-P").arg(p.to_string());
    }
    cmd.arg(&local_path).arg(&remote);
    run_checked("scp_upload", "scp", cmd, LOCAL_DEADLINE_SECS)?;
    Ok(rec(vec![
        ("success", Value::Bool(true)),
        ("local_path", Value::Str(local_path)),
        ("remote", Value::Str(remote)),
    ]))
}

// 986: bi_scp_download - Copy one remote file to a new local file with scp.
//
// The local destination is jailed like any write and must not exist: scp
// would otherwise replace it without a word. A failed transfer leaves no file.
fn bi_scp_download(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("scp_download", &input)?;
    let remote = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "scp_download: first argument must be remote string (user@host:path)",
            ))
        }
    };
    let local_path = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "scp_download: second argument must be local_path string",
            ))
        }
    };
    let port = match args.get(2) {
        Some(Value::Int(p)) => Some(*p),
        _ => None,
    };
    scp_remote_arg("scp_download", &remote)?;
    refuse_option("scp_download", &local_path)?;
    // Self-guarded for the local write, so the fetch is guarded here too, as
    // `web_download` does: otherwise the central Network gate is skipped.
    guard_network("scp_download", &remote)?;
    let local_path = guard_local_write("scp_download", &local_path)?;
    scp_local_arg("scp_download", &local_path)?;
    refuse_existing("scp_download", &local_path)?;
    let mut cmd = std::process::Command::new("scp");
    cmd.args(SCP_OPTS);
    if let Some(p) = port {
        cmd.arg("-P").arg(p.to_string());
    }
    cmd.arg(&remote).arg(&local_path);
    if let Err(e) = run_checked("scp_download", "scp", cmd, LOCAL_DEADLINE_SECS) {
        remove_partial(&local_path);
        return Err(e);
    }
    Ok(rec(vec![
        ("success", Value::Bool(true)),
        ("remote", Value::Str(remote)),
        ("local_path", Value::Str(local_path)),
    ]))
}

// 987: bi_rsync_sync - Rsync synchronization

/// 987 – rsync_sync(source, destination, [options]): rsync with a local path
/// inside the workspace or a `[user@]host:path` remote spec on either side. The
/// options Record names archive, compress, delete, verbose, progress and exclude;
/// with no Record the default is `-az`. A nonzero exit is E_TOOL_FAILED. Runs
/// with a 15 minute deadline. `delete` removes files on the destination.
fn bi_rsync_sync(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "rsync_sync";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let source = k8s_need(B, "a source path or remote spec", &args, 0, ops_sync_path)?;
    let destination = k8s_need(
        B,
        "a destination path or remote spec",
        &args,
        1,
        ops_sync_path,
    )?;
    let mut argv = rsync_flags(B, args.get(2))?;
    argv.push(source.clone());
    argv.push(destination.clone());
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = tool_run(
        B,
        "rsync",
        None,
        &refs,
        Keep::Tail(TOOL_KEEP_TAIL),
        TOOL_LONG_DEADLINE_SECS,
    )?;
    pkg_done(
        B,
        run,
        vec![
            ("source", Value::Str(source)),
            ("destination", Value::Str(destination)),
        ],
    )
}

// ============================================================================
// Security & Firewall Builtins (995-1014)
// Firewall, SELinux, AppArmor, auditd, fail2ban, OpenSSL, GPG
// ============================================================================

// [removed duplicate] use std::collections::BTreeMap;
// [removed duplicate] use std::process::Command;
// [removed duplicate] use anyhow::{anyhow, Result};

// Assuming Value is defined in the crate root or a value module
// [removed duplicate] use crate::value::Value;

// ---------------------------------------------------------------------------
// Helper: run a command, return stdout or error
// ---------------------------------------------------------------------------
/// Deadline for one security-tool query, such as gpg listing its keyring.
const SEC_RUN_DEADLINE_SECS: u64 = 60;
/// The most output one security-tool query may print. More is E_BUDGET_EXCEEDED.
const SEC_RUN_MAX_OUTPUT: usize = 16 * 1024 * 1024;

fn sec_run_cmd(program: &str, args: &[&str]) -> Result<String> {
    sec_run_cmd_within(program, args, SEC_RUN_DEADLINE_SECS)
}

/// [`sec_run_cmd`] with its deadline given. Past it the tree is killed and the
/// call is a coded budget error. Output over the cap is refused the same way.
fn sec_run_cmd_within(program: &str, args: &[&str], deadline_secs: u64) -> Result<String> {
    let output = run_output(
        program,
        program,
        program,
        args,
        |_| {},
        None,
        deadline_secs,
        SEC_RUN_MAX_OUTPUT,
    )?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(crate::safety::tool_failed(
            program,
            &format!("{} {}", program, args.join(" ")),
            output.status.code(),
            &stderr,
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

fn sec_run_cmd_ok(program: &str, args: &[&str]) -> Option<String> {
    sec_run_cmd(program, args).ok()
}

/// Test hook: [`sec_run_cmd`] with a deadline the test chooses, so a silent
/// child can be shown to be killed at it. Not part of the public API.
#[doc(hidden)]
pub fn __test_sec_run_cmd(program: &str, args: &[&str], deadline_secs: u64) -> Result<String> {
    sec_run_cmd_within(program, args, deadline_secs)
}

fn cmd_exists(program: &str) -> bool {
    // This used to find out whether a program existed by RUNNING it with
    // `--version`, with no time limit, and then running `which` as well.
    on_path(program)
}

fn rec(pairs: Vec<(&str, Value)>) -> Value {
    let mut m = BTreeMap::new();
    for (k, v) in pairs {
        m.insert(k.to_string(), v);
    }
    Value::Record(m)
}

fn s(v: &str) -> Value {
    Value::Str(v.to_string())
}

// ============================================================================
// 1010: bi_openssl_cert_info
// ============================================================================
// Reads a certificate's fields with `openssl x509 -text -noout`. A private key
// given here fails in openssl, and its content is not echoed.
fn bi_openssl_cert_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("openssl_cert_info", &input)?;
    let file_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "openssl_cert_info",
                "file: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    refuse_option("openssl_cert_info", &file_path)?;
    let file_path = crate::safety::resolve_path_str(&file_path);
    let mut cmd = std::process::Command::new("openssl");
    cmd.args(["x509", "-in", file_path.as_str(), "-text", "-noout"]);
    let (out, _) = run_checked("openssl_cert_info", "openssl", cmd, LOCAL_DEADLINE_SECS)?;
    let mut m = BTreeMap::new();
    m.insert("file".to_string(), s(&file_path));

    for line in out.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("Issuer:") {
            m.insert(
                "issuer".to_string(),
                s(trimmed.strip_prefix("Issuer:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Subject:") {
            m.insert(
                "subject".to_string(),
                s(trimmed.strip_prefix("Subject:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Not Before:") {
            m.insert(
                "not_before".to_string(),
                s(trimmed.strip_prefix("Not Before:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Not After :") || trimmed.starts_with("Not After:") {
            let val = trimmed
                .strip_prefix("Not After :")
                .or_else(|| trimmed.strip_prefix("Not After:"))
                .unwrap_or("")
                .trim();
            m.insert("not_after".to_string(), s(val));
        } else if trimmed.starts_with("Serial Number:") {
            m.insert(
                "serial_number".to_string(),
                s(trimmed.strip_prefix("Serial Number:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Signature Algorithm:") {
            m.insert(
                "signature_algorithm".to_string(),
                s(trimmed
                    .strip_prefix("Signature Algorithm:")
                    .unwrap_or("")
                    .trim()),
            );
        } else if trimmed.starts_with("Public Key Algorithm:") {
            m.insert(
                "public_key_algorithm".to_string(),
                s(trimmed
                    .strip_prefix("Public Key Algorithm:")
                    .unwrap_or("")
                    .trim()),
            );
        }
    }
    m.insert("raw".to_string(), s(out.trim()));
    Ok(Value::Record(m))
}

// ============================================================================
// 1011: bi_openssl_genrsa
// ============================================================================
// Generates an RSA private key into a new, unencrypted file (no passphrase).
// `bits` is 2048 to 16384, default 4096. An existing file is refused. A failed
// run removes the file it started. The key is never returned in the result.
fn bi_openssl_genrsa(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("openssl_genrsa", &input)?;
    let file_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "openssl_genrsa",
                "file: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let bits = match args.get(1) {
        Some(Value::Int(n)) => *n,
        None => 4096,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "openssl_genrsa",
                "bits: Int",
                other.type_name(),
            ))
        }
    };
    if !(2048..=16384).contains(&bits) {
        return Err(crate::safety::bad_arg(
            "openssl_genrsa",
            "bits in 2048..=16384",
            &bits.to_string(),
        ));
    }
    refuse_option("openssl_genrsa", &file_path)?;
    let file_path = guard_local_write("openssl_genrsa", &file_path)?;
    refuse_existing("openssl_genrsa", &file_path)?;
    let bits_text = bits.to_string();
    let mut cmd = std::process::Command::new("openssl");
    cmd.args(["genrsa", "-out", file_path.as_str(), bits_text.as_str()]);
    let (raw, _) = match run_checked("openssl_genrsa", "openssl", cmd, LOCAL_DEADLINE_SECS) {
        Ok(done) => done,
        Err(e) => {
            remove_partial(&file_path);
            return Err(e);
        }
    };
    Ok(rec(vec![
        ("action", s("genrsa")),
        ("file", s(&file_path)),
        ("bits", Value::Int(bits)),
        ("raw", s(raw.trim())),
    ]))
}

// ============================================================================
// 1012: bi_gpg_list_keys
// ============================================================================
fn bi_gpg_list_keys(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Takes no arguments and no piped input; both used to be silently dropped.
    no_args_or_input("gpg_list_keys", &args, &input)?;

    let out = sec_run_cmd("gpg", &["--list-keys", "--with-colons"])?;
    let mut keys = Vec::new();
    let mut current: Option<BTreeMap<String, Value>> = None;

    for line in out.lines() {
        let fields: Vec<&str> = line.split(':').collect();
        if fields.is_empty() {
            continue;
        }
        match fields[0] {
            "pub" => {
                // Save previous key if any
                if let Some(k) = current.take() {
                    keys.push(Value::Record(k));
                }
                let mut m = BTreeMap::new();
                m.insert("type".to_string(), s("pub"));
                if fields.len() > 1 {
                    m.insert("validity".to_string(), s(fields[1]));
                }
                if fields.len() > 2 {
                    m.insert("key_length".to_string(), s(fields[2]));
                }
                if fields.len() > 3 {
                    m.insert("algorithm".to_string(), s(fields[3]));
                }
                if fields.len() > 4 {
                    m.insert("key_id".to_string(), s(fields[4]));
                }
                if fields.len() > 5 {
                    m.insert("creation_date".to_string(), s(fields[5]));
                }
                if fields.len() > 6 {
                    m.insert("expiration_date".to_string(), s(fields[6]));
                }
                current = Some(m);
            }
            "uid" => {
                if let Some(ref mut m) = current {
                    if fields.len() > 9 {
                        m.insert("uid".to_string(), s(fields[9]));
                    }
                }
            }
            "sub" => {
                if let Some(ref mut m) = current {
                    let mut sub_info = String::new();
                    if fields.len() > 2 {
                        sub_info.push_str(fields[2]);
                        sub_info.push('/');
                    }
                    if fields.len() > 4 {
                        sub_info.push_str(fields[4]);
                    }
                    // Append to existing subkeys or create
                    let existing = m
                        .entry("subkeys".to_string())
                        .or_insert_with(|| Value::Array(Vec::new()));
                    if let Value::Array(ref mut arr) = existing {
                        arr.push(s(&sub_info));
                    }
                }
            }
            "fpr" => {
                if let Some(ref mut m) = current {
                    if fields.len() > 9 {
                        m.insert("fingerprint".to_string(), s(fields[9]));
                    }
                }
            }
            _ => {}
        }
    }
    // Push last key
    if let Some(k) = current {
        keys.push(Value::Record(k));
    }

    Ok(Value::Array(keys))
}

// ============================================================================
// 1013: bi_gpg_encrypt
// ============================================================================
// Encrypts a file to one recipient, into file.gpg. The output is refused if it
// exists. gpg runs with --batch and --no-tty, so it never waits at a prompt, and
// it writes the output file itself. The recipient is a key id, fingerprint or
// user id. No passphrase is ever taken on the command line.
fn bi_gpg_encrypt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("gpg_encrypt", &input)?;
    let file_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "gpg_encrypt",
                "file: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let recipient = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "gpg_encrypt",
                "recipient: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    refuse_option("gpg_encrypt", &file_path)?;
    refuse_option("gpg_encrypt", &recipient)?;
    if recipient.trim().is_empty() || recipient.chars().any(char::is_control) {
        return Err(crate::safety::bad_arg(
            "gpg_encrypt",
            "recipient: a key id, fingerprint or user id",
            &recipient,
        ));
    }
    let input = crate::safety::resolve_path_str(&file_path);
    regular_file_arg("gpg_encrypt", &input)?;
    let output_file = guard_local_write("gpg_encrypt", &format!("{input}.gpg"))?;
    refuse_existing("gpg_encrypt", &output_file)?;
    let mut cmd = std::process::Command::new("gpg");
    cmd.args([
        "--batch",
        "--no-tty",
        "--output",
        output_file.as_str(),
        "--encrypt",
        "--recipient",
        recipient.as_str(),
        input.as_str(),
    ]);
    let (raw, _) = match run_checked("gpg_encrypt", "gpg", cmd, LOCAL_DEADLINE_SECS) {
        Ok(done) => done,
        Err(e) => {
            remove_partial(&output_file);
            return Err(e);
        }
    };
    Ok(rec(vec![
        ("action", s("encrypt")),
        ("input_file", s(&input)),
        ("output_file", s(&output_file)),
        ("recipient", s(&recipient)),
        ("raw", s(raw.trim())),
    ]))
}

// Decrypts a .gpg or .asc file to the same name without that suffix, or to
// `<name>.decrypted` otherwise. The plaintext is written to the file and never
// returned. An existing output is refused. A passphrase, if the key needs one,
// comes from the agent's prompt, and the deadline stops the run if no one answers it.
fn bi_gpg_decrypt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("gpg_decrypt", &input)?;
    let file_path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "gpg_decrypt",
                "file: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    refuse_option("gpg_decrypt", &file_path)?;
    let input = crate::safety::resolve_path_str(&file_path);
    regular_file_arg("gpg_decrypt", &input)?;
    let stem = input
        .strip_suffix(".gpg")
        .or_else(|| input.strip_suffix(".asc"))
        .map(str::to_string)
        .unwrap_or_else(|| format!("{input}.decrypted"));
    let output_file = guard_local_write("gpg_decrypt", &stem)?;
    refuse_existing("gpg_decrypt", &output_file)?;
    let mut cmd = std::process::Command::new("gpg");
    cmd.args([
        "--batch",
        "--no-tty",
        "--output",
        output_file.as_str(),
        "--decrypt",
        input.as_str(),
    ]);
    if let Err(e) = run_checked("gpg_decrypt", "gpg", cmd, LOCAL_DEADLINE_SECS) {
        remove_partial(&output_file);
        return Err(e);
    }
    Ok(rec(vec![
        ("action", s("decrypt")),
        ("input_file", s(&input)),
        ("output_file", s(&output_file)),
    ]))
}

// ---------------------------------------------------------------------------
// Monitor builtins: shared argument checks, sampling and the alert store.
// ---------------------------------------------------------------------------

/// The most rules the alert store keeps. A create past this is refused.
const MONITOR_MAX_RULES: usize = 1000;
/// The most history events the alert store keeps; the oldest are dropped.
const MONITOR_MAX_HISTORY: usize = 1000;
/// Gap between the CPU samples of `monitor_watch_cpu`.
const MONITOR_WATCH_INTERVAL_MS: u64 = 500;
const MONITOR_METRICS: &[&str] = &["cpu", "memory", "disk"];
const MONITOR_CONDITIONS: &[&str] = &[">", ">=", "<", "<="];
const MONITOR_SEVERITIES: &[&str] = &["info", "warning", "critical"];

/// Refuse pipeline input and more than `max` arguments: these builtins read the
/// machine, so input piped in would otherwise be dropped without a word.
fn monitor_direct_call(
    builtin: &str,
    args: &[Value],
    input: &Option<Value>,
    max: usize,
) -> Result<()> {
    if input.is_some() {
        return Err(crate::safety::bad_arg(
            builtin,
            "a direct call; pipeline input is not accepted",
            "pipeline input",
        ));
    }
    if args.len() > max {
        return Err(crate::safety::bad_arg(
            builtin,
            &format!("at most {max} argument(s)"),
            &format!("{} arguments", args.len()),
        ));
    }
    Ok(())
}

/// How a rejected argument is described to the caller.
fn monitor_got(v: Option<&Value>) -> String {
    match v {
        None => "nothing".to_string(),
        Some(Value::Str(s)) => format!("\"{}\"", s.chars().take(40).collect::<String>()),
        Some(other) => other.type_name().to_string(),
    }
}

/// An optional Int argument from `lo` to `hi`, or `default` when absent.
fn monitor_int_arg(
    builtin: &str,
    args: &[Value],
    idx: usize,
    default: i64,
    lo: i64,
    hi: i64,
    what: &str,
) -> Result<i64> {
    let expected = format!("{what} from {lo} to {hi}");
    match args.get(idx) {
        None => Ok(default),
        Some(Value::Int(n)) if (lo..=hi).contains(n) => Ok(*n),
        Some(Value::Int(n)) => Err(crate::safety::bad_arg(builtin, &expected, &n.to_string())),
        Some(_) => Err(crate::safety::bad_arg(
            builtin,
            &expected,
            &monitor_got(args.get(idx)),
        )),
    }
}

/// An optional percentage (Int or Float) from 0 to 100, or `default` when absent.
fn monitor_percent_arg(builtin: &str, args: &[Value], idx: usize, default: f64) -> Result<f64> {
    let expected = "a finite percentage from 0 to 100";
    match args.get(idx) {
        None => Ok(default),
        Some(Value::Int(n)) if (0..=100).contains(n) => Ok(*n as f64),
        Some(Value::Float(f)) if f.is_finite() && (0.0..=100.0).contains(f) => Ok(*f),
        Some(Value::Int(n)) => Err(crate::safety::bad_arg(builtin, expected, &n.to_string())),
        Some(Value::Float(f)) => Err(crate::safety::bad_arg(builtin, expected, &f.to_string())),
        Some(_) => Err(crate::safety::bad_arg(
            builtin,
            expected,
            &monitor_got(args.get(idx)),
        )),
    }
}

/// An optional string argument that must be one of `choices`.
fn monitor_choice_arg(
    builtin: &str,
    args: &[Value],
    idx: usize,
    choices: &[&str],
    default: &str,
) -> Result<String> {
    match args.get(idx) {
        None => Ok(default.to_string()),
        Some(Value::Str(s)) if choices.contains(&s.as_str()) => Ok(s.clone()),
        Some(_) => {
            let listed = choices
                .iter()
                .map(|c| format!("\"{c}\""))
                .collect::<Vec<_>>()
                .join(", ");
            Err(crate::safety::bad_arg(
                builtin,
                &format!("one of {listed}"),
                &monitor_got(args.get(idx)),
            ))
        }
    }
}

/// An optional interface name. Absent is None; a given name must be a String
/// that is not option-like and is at most 256 bytes. On Unix it must also pass
/// the interface rule, because ip and ifconfig take it as a positional argument.
/// On Windows it is matched in Rust and never reaches a PowerShell script.
fn monitor_iface_arg(builtin: &str, args: &[Value], idx: usize) -> Result<Option<String>> {
    match args.get(idx) {
        None => Ok(None),
        Some(Value::Str(name)) => {
            crate::safety::reject_option_like(builtin, std::slice::from_ref(name))?;
            if name.is_empty() || name.len() > 256 || name.chars().any(char::is_control) {
                return Err(crate::safety::bad_arg(
                    builtin,
                    "an interface name of 1 to 256 characters",
                    &monitor_got(args.get(idx)),
                ));
            }
            #[cfg(not(target_os = "windows"))]
            {
                linux_diagnostics::interface_name(builtin, name)?;
            }
            Ok(Some(name.clone()))
        }
        Some(_) => Err(crate::safety::bad_arg(
            builtin,
            "an interface name String",
            &monitor_got(args.get(idx)),
        )),
    }
}

/// A search keyword: 1 to 256 characters, no control character, and not
/// option-like, since journalctl and grep would read a leading `-` as a flag.
fn monitor_keyword(builtin: &str, keyword: &str) -> Result<()> {
    crate::safety::reject_option_like(builtin, &[keyword.to_string()])?;
    if keyword.is_empty() || keyword.len() > 256 || keyword.chars().any(char::is_control) {
        return Err(crate::safety::bad_arg(
            builtin,
            "a keyword of 1 to 256 characters with no control character",
            &format!("{:?}", keyword.chars().take(40).collect::<String>()),
        ));
    }
    Ok(())
}

/// The stdout of one bounded, read-only query. A nonzero exit is E_TOOL_FAILED
/// with the stderr tail; output past `cap` is E_BUDGET_EXCEEDED; a missing
/// program is E_TOOL_MISSING.
fn monitor_text(builtin: &str, program: &str, args: &[&str], cap: usize) -> Result<String> {
    let run = tool_run(
        builtin,
        program,
        None,
        args,
        Keep::Head(cap),
        TOOL_DEADLINE_SECS,
    )?;
    tool_text(builtin, run)
}

/// The records of one bounded query that prints JSON.
fn monitor_json_records(builtin: &str, program: &str, args: &[&str]) -> Result<Value> {
    let text = monitor_text(builtin, program, args, TOOL_MAX_JSON)?;
    monitor_parse::json_array(builtin, program, &text)
}

/// The records of one bounded PowerShell query that prints JSON. A failure names
/// `label` rather than the script, which can be long.
fn monitor_ps_json(builtin: &str, label: &str, script: &str) -> Result<Value> {
    let mut run = tool_run(
        builtin,
        "powershell",
        None,
        &["-NoProfile", "-Command", script],
        Keep::Head(TOOL_MAX_JSON),
        TOOL_DEADLINE_SECS,
    )?;
    run.command = label.to_string();
    let text = tool_text(builtin, run)?;
    monitor_parse::json_array(builtin, label, &text)
}

/// Keeps the records whose `field` contains `name`, ignoring case. An empty
/// result for a name the caller gave is E_NOT_FOUND, as `ip` answers.
#[cfg(target_os = "windows")]
fn monitor_named(builtin: &str, records: Value, name: Option<&str>, field: &str) -> Result<Value> {
    let Some(name) = name else {
        return Ok(records);
    };
    let want = name.to_lowercase();
    let items = match records {
        Value::Array(items) => items,
        other => return Ok(other),
    };
    let kept: Vec<Value> = items
        .into_iter()
        .filter(|r| match r {
            Value::Record(m) => {
                matches!(m.get(field), Some(Value::Str(s)) if s.to_lowercase().contains(&want))
            }
            _ => false,
        })
        .collect();
    if kept.is_empty() {
        return Err(crate::safety::not_found(builtin, "interface", name));
    }
    Ok(Value::Array(kept))
}

/// Whether a failure is a program that is not installed (E_TOOL_MISSING).
#[cfg(target_os = "linux")]
fn monitor_tool_missing(err: &anyhow::Error) -> bool {
    err.downcast_ref::<crate::safety::SafetyError>()
        .is_some_and(|se| matches!(se.code, crate::safety::ErrorCode::ToolMissing))
}

/// The last `count` items of an array. Used where the tool cannot limit its own
/// output and answers oldest first.
#[cfg(target_os = "macos")]
fn monitor_newest(records: Value, count: i64) -> Value {
    match records {
        Value::Array(items) => {
            let keep = count.max(0) as usize;
            let start = items.len().saturating_sub(keep);
            Value::Array(items.into_iter().skip(start).collect())
        }
        other => other,
    }
}

/// A System with CPU usage. sysinfo reports 0% from a single refresh, because a
/// usage figure is the change between two refreshes.
fn monitor_sample_system() -> System {
    let mut sys = System::new_all();
    sys.refresh_all();
    std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL);
    sys.refresh_all();
    sys
}

/// Percent of the summed disk space in use across all mounts. With no disks,
/// or zero total space, the old code returned 0.0% used, so a disk alert could
/// never fire. That is now a coded error.
fn monitor_disk_used_percent() -> Result<f64> {
    let disks = Disks::new_with_refreshed_list();
    let count = disks.iter().count();
    let total: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail: u64 = disks.iter().map(|d| d.available_space()).sum();
    if count == 0 || total == 0 {
        return Err(crate::safety::bad_state(
            "monitor_alert_list",
            &format!(
                "disk usage unavailable ({} disks, {} bytes total)",
                count, total
            ),
            "platform_disk_usage",
        ));
    }
    Ok(total.saturating_sub(avail) as f64 / total as f64 * 100.0)
}

fn monitor_memory_used_percent(sys: &System) -> f64 {
    let total = sys.total_memory();
    if total > 0 {
        sys.used_memory() as f64 / total as f64 * 100.0
    } else {
        0.0
    }
}

/// The live reading for an alert metric; None for a metric it does not know.
fn monitor_metric_value(metric: &str, sys: &System, disk_pct: Option<f64>) -> Option<f64> {
    match metric {
        "cpu" => Some(sys.global_cpu_usage() as f64),
        "memory" => Some(monitor_memory_used_percent(sys)),
        "disk" => disk_pct,
        _ => None,
    }
}

fn monitor_breached(value: f64, condition: &str, threshold: f64) -> bool {
    match condition {
        ">" => value > threshold,
        ">=" => value >= threshold,
        "<" => value < threshold,
        "<=" => value <= threshold,
        _ => false,
    }
}

/// The alert store: `alerts.json` in the monitor directory of the data
/// directory. `AETHER_DATA_HOME` moves it, which is how tests keep it out of
/// the real data directory.
fn monitor_store_path() -> std::path::PathBuf {
    crate::config::ShellConfig::data_dir()
        .join("monitor")
        .join("alerts.json")
}

#[derive(Default)]
struct MonitorStore {
    rules: Vec<serde_json::Value>,
    history: Vec<serde_json::Value>,
}

/// A store file that exists but does not parse. It is reported and left
/// alone: starting an empty store over it would destroy the user's rules.
fn monitor_store_error(builtin: &str, path: &std::path::Path, why: &str) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::Io,
        message: format!(
            "{builtin}: the alert store {} cannot be read: {why}",
            path.display()
        ),
        builtin: builtin.to_string(),
        hint: "move the file aside to start with an empty store; nothing was changed".to_string(),
        approval: None,
        did_you_mean: Vec::new(),
        expected: "an alert store written by monitor_alert_create".to_string(),
        got: "a file that does not parse".to_string(),
    })
}

fn monitor_store_load(builtin: &str) -> Result<MonitorStore> {
    let path = monitor_store_path();
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(MonitorStore::default()),
        Err(e) => return Err(crate::safety::fs_error(builtin, &path, &e)),
    };
    let doc: serde_json::Value = serde_json::from_str(&text)
        .map_err(|e| monitor_store_error(builtin, &path, &e.to_string()))?;
    let list = |key: &str| -> Result<Vec<serde_json::Value>> {
        doc.get(key)
            .and_then(|v| v.as_array())
            .cloned()
            .ok_or_else(|| monitor_store_error(builtin, &path, &format!("no \"{key}\" array")))
    };
    Ok(MonitorStore {
        rules: list("rules")?,
        history: list("history")?,
    })
}

/// Write the store through a temporary file, so a crash leaves either the old
/// store or the new one.
fn monitor_store_save(builtin: &str, store: &MonitorStore) -> Result<()> {
    let path = monitor_store_path();
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| crate::safety::fs_error(builtin, dir, &e))?;
    }
    let doc = serde_json::json!({ "rules": store.rules, "history": store.history });
    let bytes = serde_json::to_vec_pretty(&doc)?;
    let path_text = path.to_str().ok_or_else(|| {
        crate::safety::bad_arg(builtin, "a UTF-8 store path", &path.display().to_string())
    })?;
    // A unique temporary name (not a shared "json.tmp") and cleanup on failure
    // are both done by write_file_atomically.
    write_file_atomically(builtin, path_text, &bytes)
}

fn monitor_history_push(store: &mut MonitorStore, event: &str, rule: &serde_json::Value) {
    store.history.push(serde_json::json!({
        "event": event,
        "rule_id": rule.get("id").cloned().unwrap_or(serde_json::Value::Null),
        "name": rule.get("name").cloned().unwrap_or(serde_json::Value::Null),
        "at": chrono::Local::now().to_rfc3339(),
    }));
    let overflow = store.history.len().saturating_sub(MONITOR_MAX_HISTORY);
    store.history.drain(..overflow);
}

fn monitor_rule_str<'a>(builtin: &str, rule: &'a serde_json::Value, key: &str) -> Result<&'a str> {
    rule.get(key).and_then(|v| v.as_str()).ok_or_else(|| {
        monitor_store_error(
            builtin,
            &monitor_store_path(),
            &format!("a rule has no \"{key}\" text"),
        )
    })
}

fn monitor_rule_f64(builtin: &str, rule: &serde_json::Value, key: &str) -> Result<f64> {
    rule.get(key).and_then(|v| v.as_f64()).ok_or_else(|| {
        monitor_store_error(
            builtin,
            &monitor_store_path(),
            &format!("a rule has no \"{key}\" number"),
        )
    })
}

// ============================================================================
// Monitoring & Diagnostics Builtins (1015-1034)
// System monitoring, network diagnostics, performance counters
// ============================================================================

// [removed duplicate] use std::collections::BTreeMap;
// [removed duplicate] use std::process::Command;
// [removed duplicate] use anyhow::anyhow;

// [removed duplicate] use crate::value::Value;
// [removed duplicate] use crate::builtins::json_to_value;

// ---------------------------------------------------------------------------
// 1015: bi_htop_snapshot — Process monitor snapshot (top 20 by memory)
// ---------------------------------------------------------------------------
// 1015: bi_htop_snapshot - Interactive-style process monitor (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_htop_snapshot(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_htop";
    monitor_direct_call(B, &args, &input, 1)?;
    let count = monitor_int_arg(B, &args, 0, 20, 1, 500, "a process count")? as usize;
    let sys = monitor_sample_system();
    let mut procs: Vec<_> = sys.processes().iter().collect();
    procs.sort_by(|a, b| b.1.memory().cmp(&a.1.memory()));
    let entries: Vec<Value> = procs
        .iter()
        .take(count)
        .map(|(pid, p)| {
            let mut rec = BTreeMap::new();
            rec.insert("pid".to_string(), Value::Int(pid.as_u32() as i64));
            rec.insert(
                "name".to_string(),
                Value::Str(p.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "cpu_percent".to_string(),
                Value::Float(p.cpu_usage() as f64),
            );
            rec.insert("memory_bytes".to_string(), Value::Int(p.memory() as i64));
            rec.insert(
                "memory_mb".to_string(),
                Value::Float(p.memory() as f64 / 1_048_576.0),
            );
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ---------------------------------------------------------------------------
// 1016: bi_iotop_snapshot — I/O monitor snapshot
// ---------------------------------------------------------------------------
// 1016: bi_iotop_snapshot - I/O monitor snapshot (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_iotop_snapshot(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_iotop";
    monitor_direct_call(B, &args, &input, 1)?;
    let count = monitor_int_arg(B, &args, 0, 20, 1, 500, "a process count")? as usize;
    let sys = monitor_sample_system();
    let mut procs: Vec<_> = sys.processes().iter().collect();
    procs.sort_by(|a, b| {
        let a_io = a.1.disk_usage().total_read_bytes + a.1.disk_usage().total_written_bytes;
        let b_io = b.1.disk_usage().total_read_bytes + b.1.disk_usage().total_written_bytes;
        b_io.cmp(&a_io)
    });
    let entries: Vec<Value> = procs
        .iter()
        .take(count)
        .map(|(pid, p)| {
            let du = p.disk_usage();
            let mut rec = BTreeMap::new();
            rec.insert("pid".to_string(), Value::Int(pid.as_u32() as i64));
            rec.insert(
                "name".to_string(),
                Value::Str(p.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "total_read_bytes".to_string(),
                Value::Int(du.total_read_bytes as i64),
            );
            rec.insert(
                "total_written_bytes".to_string(),
                Value::Int(du.total_written_bytes as i64),
            );
            rec.insert("read_bytes".to_string(), Value::Int(du.read_bytes as i64));
            rec.insert(
                "written_bytes".to_string(),
                Value::Int(du.written_bytes as i64),
            );
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ---------------------------------------------------------------------------
// 1017: bi_nethogs_info — Network traffic per process
// ---------------------------------------------------------------------------
fn bi_nethogs_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_nethogs";
    monitor_direct_call(B, &args, &input, 0)?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetTCPConnection | Where-Object { $_.State -eq 'Established' } | Select-Object OwningProcess, LocalAddress, LocalPort, RemoteAddress, RemotePort, State | ForEach-Object { $proc = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue; $_ | Add-Member -NotePropertyName ProcessName -NotePropertyValue $(if($proc){$proc.ProcessName}else{'unknown'}) -PassThru } | Select-Object -First 30 | ConvertTo-Json -Depth 3";
        monitor_ps_json(B, "Get-NetTCPConnection", ps_cmd)
    }

    // nethogs is the only source on Unix (it needs root). The ss fallback this
    // used to take answered records of another shape under the same name, so a
    // missing or failing nethogs is now the coded error and nothing else.
    #[cfg(not(target_os = "windows"))]
    {
        let text = monitor_text(B, "nethogs", &["-t", "-c", "1"], TOOL_MAX_TEXT)?;
        Ok(Value::Array(monitor_parse::nethogs_trace(&text)?))
    }
}

// ---------------------------------------------------------------------------
// 1018: bi_iftop_info — Network bandwidth info
// ---------------------------------------------------------------------------
fn bi_iftop_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_iftop";
    monitor_direct_call(B, &args, &input, 0)?;

    #[cfg(target_os = "windows")]
    {
        let text = monitor_text(B, "netstat", &["-s"], TOOL_MAX_TEXT)?;
        let mut rec = BTreeMap::new();
        rec.insert("source".to_string(), Value::Str("netstat -s".to_string()));
        for (key, value) in monitor_parse::netstat_counters(&text)? {
            rec.insert(key.to_string(), value);
        }
        rec.insert("raw_output".to_string(), Value::Str(text));
        Ok(Value::Record(rec))
    }

    #[cfg(not(target_os = "windows"))]
    {
        // ss -s on Linux; netstat -s on macOS, which has no ss.
        let tool = if cfg!(target_os = "macos") {
            "netstat"
        } else {
            "ss"
        };
        let text = monitor_text(B, tool, &["-s"], TOOL_MAX_TEXT)?;
        let mut rec = BTreeMap::new();
        rec.insert("source".to_string(), Value::Str(format!("{tool} -s")));
        for line in text.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("TCP:") {
                rec.insert("tcp_summary".to_string(), Value::Str(trimmed.to_string()));
            } else if trimmed.starts_with("UDP:") {
                rec.insert("udp_summary".to_string(), Value::Str(trimmed.to_string()));
            } else if trimmed.starts_with("Total:") || trimmed.starts_with("Transport") {
                rec.insert("total_summary".to_string(), Value::Str(trimmed.to_string()));
            }
        }
        rec.insert("raw_output".to_string(), Value::Str(text));
        Ok(Value::Record(rec))
    }
}
// ---------------------------------------------------------------------------
// 1017: bi_nmon_snapshot - System performance snapshot (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_nmon_snapshot(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    monitor_direct_call("monitor_nmon", &args, &input, 0)?;
    let sys = monitor_sample_system();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let disks = Disks::new_with_refreshed_list();
    let total_disk: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail_disk: u64 = disks.iter().map(|d| d.available_space()).sum();
    let mut rec = BTreeMap::new();
    rec.insert("cpu_count".to_string(), Value::Int(sys.cpus().len() as i64));
    rec.insert(
        "cpu_percent".to_string(),
        Value::Float(sys.global_cpu_usage() as f64),
    );
    load_fields(&mut rec);
    rec.insert("memory_total".to_string(), Value::Int(total_mem as i64));
    rec.insert("memory_used".to_string(), Value::Int(used_mem as i64));
    rec.insert(
        "memory_free".to_string(),
        Value::Int(total_mem.saturating_sub(used_mem) as i64),
    );
    rec.insert("disk_total".to_string(), Value::Int(total_disk as i64));
    rec.insert("disk_available".to_string(), Value::Int(avail_disk as i64));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}
// ---------------------------------------------------------------------------
// 1018: bi_glances_info - Comprehensive system info (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_glances_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    monitor_direct_call("monitor_glances", &args, &input, 0)?;
    let sys = monitor_sample_system();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();
    let cpus: Vec<Value> = sys
        .cpus()
        .iter()
        .map(|c| {
            let mut m = BTreeMap::new();
            m.insert("name".to_string(), Value::Str(c.name().to_string()));
            m.insert(
                "usage_percent".to_string(),
                Value::Float(c.cpu_usage() as f64),
            );
            m.insert(
                "frequency_mhz".to_string(),
                Value::Int(c.frequency() as i64),
            );
            Value::Record(m)
        })
        .collect();
    let disks_list = Disks::new_with_refreshed_list();
    let disk_entries: Vec<Value> = disks_list
        .iter()
        .map(|d| {
            let mut m = BTreeMap::new();
            m.insert(
                "name".to_string(),
                Value::Str(d.name().to_string_lossy().to_string()),
            );
            m.insert(
                "mount".to_string(),
                Value::Str(d.mount_point().to_string_lossy().to_string()),
            );
            m.insert(
                "fs_type".to_string(),
                Value::Str(d.file_system().to_string_lossy().to_string()),
            );
            m.insert(
                "total_bytes".to_string(),
                Value::Int(d.total_space() as i64),
            );
            m.insert(
                "available_bytes".to_string(),
                Value::Int(d.available_space() as i64),
            );
            let used = d.total_space().saturating_sub(d.available_space());
            let pct = if d.total_space() > 0 {
                used as f64 / d.total_space() as f64 * 100.0
            } else {
                0.0
            };
            m.insert("use_percent".to_string(), Value::Float(pct));
            Value::Record(m)
        })
        .collect();
    let nets = Networks::new_with_refreshed_list();
    let net_entries: Vec<Value> = nets
        .iter()
        .map(|(name, data)| {
            let mut m = BTreeMap::new();
            m.insert("interface".to_string(), Value::Str(name.clone()));
            m.insert(
                "rx_bytes".to_string(),
                Value::Int(data.total_received() as i64),
            );
            m.insert(
                "tx_bytes".to_string(),
                Value::Int(data.total_transmitted() as i64),
            );
            m.insert(
                "rx_packets".to_string(),
                Value::Int(data.total_packets_received() as i64),
            );
            m.insert(
                "tx_packets".to_string(),
                Value::Int(data.total_packets_transmitted() as i64),
            );
            Value::Record(m)
        })
        .collect();
    let mut rec = BTreeMap::new();
    // A missing host name was "", which read as a name. platform_snapshot
    // gets it from sys_hostname, which refuses when it cannot be read.
    rec.insert("hostname".to_string(), bi_sys_hostname(Vec::new(), None)?);
    rec.insert(
        "uptime_seconds".to_string(),
        Value::Int(System::uptime() as i64),
    );
    rec.insert("cpu_count".to_string(), Value::Int(sys.cpus().len() as i64));
    rec.insert("cpus".to_string(), Value::Array(cpus));
    rec.insert("memory_total".to_string(), Value::Int(total_mem as i64));
    rec.insert("memory_used".to_string(), Value::Int(used_mem as i64));
    rec.insert(
        "memory_percent".to_string(),
        Value::Float(if total_mem > 0 {
            used_mem as f64 / total_mem as f64 * 100.0
        } else {
            0.0
        }),
    );
    rec.insert("swap_total".to_string(), Value::Int(total_swap as i64));
    rec.insert("swap_used".to_string(), Value::Int(used_swap as i64));
    rec.insert("disks".to_string(), Value::Array(disk_entries));
    rec.insert("networks".to_string(), Value::Array(net_entries));
    load_fields(&mut rec);
    Ok(Value::Record(rec))
}
// chrono_timestamp helper - returns RFC3339 timestamp
fn chrono_timestamp() -> String {
    chrono::Local::now().to_rfc3339()
}

// ---------------------------------------------------------------------------
// 1021: bi_tcpdump_capture — Packet capture
// ---------------------------------------------------------------------------
fn bi_tcpdump_capture(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_tcpdump";
    linux_diagnostics::no_pipeline_input(B, &input)?;
    if args.len() > 3 {
        return Err(crate::safety::arg_err(
            "monitor_tcpdump: expected at most (interface, count, seconds)",
        ));
    }
    let iface = match args.first() {
        None => "any".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "an interface name String",
                other.type_name(),
            ))
        }
    };
    let count = match args.get(1) {
        None => 10,
        Some(Value::Int(n)) if (1..=1000).contains(n) => *n,
        Some(Value::Int(n)) => {
            return Err(crate::safety::bad_arg(
                B,
                "a packet count from 1 to 1000",
                &n.to_string(),
            ))
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "a packet count Int",
                other.type_name(),
            ))
        }
    };
    let seconds = match args.get(2) {
        None => 10,
        Some(Value::Int(n)) if (1..=60).contains(n) => *n,
        Some(Value::Int(n)) => {
            return Err(crate::safety::bad_arg(
                B,
                "a duration in seconds from 1 to 60",
                &n.to_string(),
            ))
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                B,
                "a duration Int in seconds",
                other.type_name(),
            ))
        }
    };
    linux_diagnostics::interface_name(B, &iface)?;
    #[cfg(unix)]
    {
        // The deadline is the capture's duration: tcpdump stops at `count`
        // packets or is killed (with its group) at `seconds`.
        let limit = std::time::Duration::from_secs(seconds as u64);
        let argv = vec![
            "-l".to_string(),
            "-nn".to_string(),
            "-q".to_string(),
            "-i".to_string(),
            iface.clone(),
            "-c".to_string(),
            count.to_string(),
        ];
        let run = linux_diagnostics::run_bounded(B, "tcpdump", "tcpdump", &argv, limit)?;
        if run.truncated {
            return Err(crate::safety::budget_exceeded(
                B,
                format!(
                    "tcpdump wrote more than {} bytes",
                    linux_diagnostics::MAX_OUTPUT
                ),
                "use a smaller packet count",
            ));
        }
        if !run.timed_out && run.code != Some(0) {
            return Err(crate::safety::tool_failed(
                B,
                "tcpdump",
                run.code,
                &run.stderr,
            ));
        }
        let packets: Vec<Value> = run
            .stdout
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(|line| {
                let mut rec = BTreeMap::new();
                rec.insert("line".to_string(), Value::Str(line.to_string()));
                Value::Record(rec)
            })
            .collect();
        let mut result = BTreeMap::new();
        result.insert("interface".to_string(), Value::Str(iface));
        result.insert("count".to_string(), Value::Int(count));
        result.insert("captured".to_string(), Value::Int(packets.len() as i64));
        result.insert("timed_out".to_string(), Value::Bool(run.timed_out));
        result.insert("packets".to_string(), Value::Array(packets));
        Ok(Value::Record(result))
    }
    #[cfg(not(unix))]
    {
        let _ = (iface, count, seconds);
        Err(crate::safety::unimplemented(
            B,
            "tcpdump_capture runs on Linux and macOS only; NOTHING WAS CAPTURED on this operating system",
            "run it on Linux",
        ))
    }
}

// ---------------------------------------------------------------------------
// 1022: bi_ss_info — Socket statistics
// ---------------------------------------------------------------------------
fn bi_ss_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_sockets";
    monitor_direct_call(B, &args, &input, 1)?;
    let filter = monitor_choice_arg(B, &args, 0, &["all", "tcp", "udp", "listening"], "all")?;

    #[cfg(target_os = "windows")]
    {
        let text = monitor_text(B, "netstat", &["-an"], TOOL_MAX_TEXT)?;
        Ok(Value::Array(monitor_parse::socket_records_windows(
            &text, &filter,
        )?))
    }

    #[cfg(not(target_os = "windows"))]
    {
        if cfg!(target_os = "macos") {
            let text = monitor_text(B, "netstat", &["-an"], TOOL_MAX_TEXT)?;
            Ok(Value::Array(monitor_parse::socket_records_bsd(
                &text, &filter,
            )?))
        } else {
            // One query for every TCP and UDP socket, with the filter applied to
            // what it printed: "tcp" and "udp" include established sockets.
            let text = monitor_text(B, "ss", &["-tuanH"], TOOL_MAX_TEXT)?;
            Ok(Value::Array(monitor_parse::socket_records_ss(
                &text, &filter,
            )?))
        }
    }
}

// ---------------------------------------------------------------------------
// 1023: bi_ip_addr — IP address management
// ---------------------------------------------------------------------------
fn bi_ip_addr(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_ip_addr";
    monitor_direct_call(B, &args, &input, 1)?;
    let iface = monitor_iface_arg(B, &args, 0)?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetIPAddress | Select-Object InterfaceAlias, IPAddress, PrefixLength, AddressFamily, Type | ConvertTo-Json -Depth 3";
        let records = monitor_ps_json(B, "Get-NetIPAddress", ps_cmd)?;
        monitor_named(B, records, iface.as_deref(), "InterfaceAlias")
    }

    #[cfg(target_os = "linux")]
    {
        let mut argv = vec!["-j", "addr", "show"];
        argv.extend(iface.as_deref());
        monitor_json_records(B, "ip", &argv)
    }

    #[cfg(target_os = "macos")]
    {
        let mut argv: Vec<&str> = Vec::new();
        argv.extend(iface.as_deref());
        let text = monitor_text(B, "ifconfig", &argv, TOOL_MAX_TEXT)?;
        let mut records = Vec::new();
        let mut current_iface = String::new();
        for line in text.lines() {
            if !line.starts_with('\t') && !line.starts_with(' ') && line.contains(':') {
                current_iface = line.split(':').next().unwrap_or("").to_string();
            } else if line.trim().starts_with("inet ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    let mut rec = BTreeMap::new();
                    rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    rec.insert("address".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("family".to_string(), Value::Str("inet".to_string()));
                    if let Some(pos) = parts.iter().position(|&x| x == "netmask") {
                        if parts.len() > pos + 1 {
                            rec.insert(
                                "netmask".to_string(),
                                Value::Str(parts[pos + 1].to_string()),
                            );
                        }
                    }
                    records.push(Value::Record(rec));
                }
            } else if line.trim().starts_with("inet6 ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    let mut rec = BTreeMap::new();
                    rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    rec.insert("address".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("family".to_string(), Value::Str("inet6".to_string()));
                    records.push(Value::Record(rec));
                }
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1024: bi_ip_route — IP route table
// ---------------------------------------------------------------------------
fn bi_ip_route(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_ip_route";
    monitor_direct_call(B, &args, &input, 0)?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetRoute | Select-Object DestinationPrefix, NextHop, InterfaceAlias, RouteMetric, InterfaceMetric | ConvertTo-Json -Depth 3";
        monitor_ps_json(B, "Get-NetRoute", ps_cmd)
    }

    #[cfg(target_os = "linux")]
    {
        monitor_json_records(B, "ip", &["-j", "route", "show"])
    }

    #[cfg(target_os = "macos")]
    {
        let text = monitor_text(B, "netstat", &["-rn"], TOOL_MAX_TEXT)?;
        let mut records = Vec::new();
        let mut header_seen = false;
        for line in text.lines() {
            if line.starts_with("Destination") {
                header_seen = true;
                continue;
            }
            if header_seen {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 4 {
                    let mut rec = BTreeMap::new();
                    rec.insert("destination".to_string(), Value::Str(parts[0].to_string()));
                    rec.insert("gateway".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("flags".to_string(), Value::Str(parts[2].to_string()));
                    rec.insert(
                        "interface".to_string(),
                        Value::Str(parts.last().unwrap_or(&"").to_string()),
                    );
                    records.push(Value::Record(rec));
                }
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1025: bi_ip_link — Network link info
// ---------------------------------------------------------------------------
fn bi_ip_link(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_ip_link";
    monitor_direct_call(B, &args, &input, 1)?;
    let iface = monitor_iface_arg(B, &args, 0)?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetAdapter | Select-Object Name, InterfaceDescription, Status, MacAddress, LinkSpeed, MediaType | ConvertTo-Json -Depth 3";
        let records = monitor_ps_json(B, "Get-NetAdapter", ps_cmd)?;
        monitor_named(B, records, iface.as_deref(), "Name")
    }

    #[cfg(target_os = "linux")]
    {
        let mut argv = vec!["-j", "link", "show"];
        argv.extend(iface.as_deref());
        monitor_json_records(B, "ip", &argv)
    }

    #[cfg(target_os = "macos")]
    {
        let mut argv: Vec<&str> = Vec::new();
        argv.extend(iface.as_deref());
        let text = monitor_text(B, "ifconfig", &argv, TOOL_MAX_TEXT)?;
        let mut records = Vec::new();
        let mut current_iface = String::new();
        let mut current_rec = BTreeMap::new();
        for line in text.lines() {
            if !line.starts_with('\t') && !line.starts_with(' ') && line.contains(':') {
                if !current_iface.is_empty() {
                    current_rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    records.push(Value::Record(current_rec.clone()));
                }
                current_iface = line.split(':').next().unwrap_or("").to_string();
                current_rec = BTreeMap::new();
                let flags_part = line.split('<').nth(1).and_then(|s| s.split('>').next());
                if let Some(flags) = flags_part {
                    current_rec.insert("flags".to_string(), Value::Str(flags.to_string()));
                }
            } else if line.trim().starts_with("ether ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    current_rec.insert("mac_address".to_string(), Value::Str(parts[1].to_string()));
                }
            } else if line.trim().starts_with("status:") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    current_rec.insert("status".to_string(), Value::Str(parts[1].to_string()));
                }
            }
        }
        if !current_iface.is_empty() {
            current_rec.insert("interface".to_string(), Value::Str(current_iface));
            records.push(Value::Record(current_rec));
        }
        Ok(Value::Array(records))
    }
}

/// Windows: an adapter name, matched exactly (not as a -Name wildcard), so
/// `Local Area Connection* 1` names that adapter and no other. Letters,
/// digits, spaces and `- _ . ( ) # *` cover the names Windows gives adapters
/// ("Wi-Fi 4", "vEthernet (Default Switch)"); a `;` or `/` is refused, as
/// interface names are on Linux.
#[cfg(windows)]
fn ethtool_adapter(device: &str) -> Result<()> {
    let plain = !device.trim().is_empty()
        && device.len() <= 256
        && !device.starts_with('-')
        && device
            .chars()
            .all(|c| c.is_alphanumeric() || " -_.()#*".contains(c));
    if plain {
        Ok(())
    } else {
        Err(crate::safety::bad_arg(
            "monitor_ethtool",
            "an adapter name such as \"Ethernet\" or \"Wi-Fi 4\"",
            device,
        ))
    }
}

/// Windows: one adapter's settings from Get-NetAdapter. The keys match the
/// ethtool record where the fact is the same: speed, duplex, link_detected. A
/// field the adapter does not report is left out.
#[cfg(windows)]
fn ethtool_windows(device: &str) -> Result<Value> {
    const NAME: &str = "monitor_ethtool";
    ethtool_adapter(device)?;
    let script = crate::ps_script!(
        "$n = {}; $a = Get-NetAdapter -ErrorAction Stop | Where-Object {{ $_.Name -eq $n }}; $a | Select-Object Name,LinkSpeed,FullDuplex,MediaConnectionState,DriverDescription,DriverVersion,MacAddress | ConvertTo-Json",
        crate::safety::ps_quote(device)
    );
    let out = net_run(
        NAME,
        "powershell",
        &["-NoProfile", "-NonInteractive", "-Command", script.as_str()],
        NET_TOOL_SECS,
    )?;
    net_checked(NAME, "powershell", &out)?;
    // An adapter that does not exist matches nothing and prints nothing.
    let Some(item) = net_ps_items(NAME, &out.stdout)?.into_iter().next() else {
        return Err(crate::safety::not_found(NAME, "network interface", device));
    };
    let Some(o) = item.as_object() else {
        return Err(net_unparsed(NAME, "powershell"));
    };
    let text = |key: &str| {
        o.get(key)
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| Value::Str(s.to_string()))
    };
    let mut rec = BTreeMap::new();
    rec.insert("device".to_string(), Value::Str(device.to_string()));
    for (out_key, json_key) in [
        ("speed", "LinkSpeed"),
        ("driver_description", "DriverDescription"),
        ("driver_version", "DriverVersion"),
        ("mac_address", "MacAddress"),
    ] {
        if let Some(v) = text(json_key) {
            rec.insert(out_key.to_string(), v);
        }
    }
    match o.get("FullDuplex").and_then(|v| v.as_bool()) {
        Some(true) => {
            rec.insert("duplex".to_string(), Value::Str("Full".to_string()));
        }
        Some(false) => {
            rec.insert("duplex".to_string(), Value::Str("Half".to_string()));
        }
        None => {}
    }
    // ConvertTo-Json writes the MediaConnectionState enum as a number: 1 is
    // Connected, 2 is Disconnected, and 0 (Unknown) is left out.
    match o.get("MediaConnectionState").and_then(|v| v.as_i64()) {
        Some(1) => {
            rec.insert("link_detected".to_string(), Value::Str("yes".to_string()));
        }
        Some(2) => {
            rec.insert("link_detected".to_string(), Value::Str("no".to_string()));
        }
        _ => {}
    }
    Ok(Value::Record(rec))
}

// ---------------------------------------------------------------------------
// 1026: bi_ethtool_info — Ethernet device info (Linux; Windows reads Get-NetAdapter)
// ---------------------------------------------------------------------------
fn bi_ethtool_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    linux_diagnostics::no_pipeline_input("monitor_ethtool", &input)?;
    let device = match args.as_slice() {
        [Value::Str(s)] => s.clone(),
        [other] => {
            return Err(crate::safety::bad_arg(
                "monitor_ethtool",
                "a device name String such as \"eth0\"",
                other.type_name(),
            ))
        }
        _ => {
            return Err(crate::safety::arg_err(
                "monitor_ethtool: expected one device name, e.g. \"eth0\"",
            ))
        }
    };
    #[cfg(not(windows))]
    linux_diagnostics::interface_name("monitor_ethtool", &device)?;
    #[cfg(target_os = "linux")]
    {
        let text = monitor_text(
            "monitor_ethtool",
            "ethtool",
            &[device.as_str()],
            TOOL_MAX_TEXT,
        )?;
        let mut rec = BTreeMap::new();
        rec.insert("device".to_string(), Value::Str(device.clone()));
        for line in text.lines() {
            if let Some((key, val)) = line.trim().split_once(':') {
                let k = key.trim().to_lowercase().replace([' ', '-'], "_");
                let v = val.trim();
                if !k.is_empty() && !v.is_empty() {
                    rec.insert(k, Value::Str(v.to_string()));
                }
            }
        }
        Ok(Value::Record(rec))
    }
    #[cfg(windows)]
    {
        ethtool_windows(&device)
    }
    #[cfg(not(any(windows, target_os = "linux")))]
    {
        let _ = device;
        Err(crate::safety::unimplemented(
            "monitor_ethtool",
            "ethtool is Linux and Windows only; NOTHING WAS INSPECTED on this operating system",
            "monitor_ip_link() lists interfaces on every OS",
        ))
    }
}

// ---------------------------------------------------------------------------
// perf stat on Windows: the figures a finished child reports through its handle
// ---------------------------------------------------------------------------

/// What a finished child reports about itself: CPU times in 100 ns ticks, its
/// peak working set in bytes, and its page-fault count.
#[cfg(windows)]
struct WinProcStats {
    user_ticks: u64,
    kernel_ticks: u64,
    peak_rss: u64,
    page_faults: u32,
}

/// The Win32 PROCESS_MEMORY_COUNTERS record, laid out as K32GetProcessMemoryInfo
/// fills it. Only `peak_working_set_size` and `page_fault_count` are read.
#[cfg(windows)]
#[repr(C)]
#[derive(Default)]
#[allow(dead_code)]
struct WinProcessMemoryCounters {
    cb: u32,
    page_fault_count: u32,
    peak_working_set_size: usize,
    working_set_size: usize,
    quota_peak_paged_pool_usage: usize,
    quota_paged_pool_usage: usize,
    quota_peak_non_paged_pool_usage: usize,
    quota_non_paged_pool_usage: usize,
    pagefile_usage: usize,
    peak_pagefile_usage: usize,
}

/// Reads a child's CPU times, peak working set and page faults through its
/// process handle. The child must have exited or been killed, and its `Child`
/// must not be dropped yet: the handle is what keeps these figures readable.
#[cfg(windows)]
fn win_process_stats(child: &std::process::Child) -> std::io::Result<WinProcStats> {
    use std::ffi::c_void;
    use std::os::windows::io::AsRawHandle;
    #[link(name = "kernel32")]
    extern "system" {
        fn GetProcessTimes(
            process: *mut c_void,
            creation: *mut WinFileTime,
            exit: *mut WinFileTime,
            kernel: *mut WinFileTime,
            user: *mut WinFileTime,
        ) -> i32;
        fn K32GetProcessMemoryInfo(
            process: *mut c_void,
            counters: *mut WinProcessMemoryCounters,
            cb: u32,
        ) -> i32;
    }
    let handle = child.as_raw_handle();
    let mut creation = WinFileTime::default();
    let mut exit = WinFileTime::default();
    let mut kernel = WinFileTime::default();
    let mut user = WinFileTime::default();
    // SAFETY: `handle` is the child's process handle, borrowed from `child`,
    // which is alive for this call; each out-pointer is a local of the type the
    // API writes.
    if unsafe { GetProcessTimes(handle, &mut creation, &mut exit, &mut kernel, &mut user) } == 0 {
        return Err(std::io::Error::last_os_error());
    }
    let cb = std::mem::size_of::<WinProcessMemoryCounters>() as u32;
    let mut mem = WinProcessMemoryCounters {
        cb,
        ..Default::default()
    };
    // SAFETY: as above; `mem` is a repr(C) record whose `cb` is its own size,
    // which is what the API checks against.
    if unsafe { K32GetProcessMemoryInfo(handle, &mut mem, cb) } == 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok(WinProcStats {
        user_ticks: user.ticks(),
        kernel_ticks: kernel.ticks(),
        peak_rss: mem.peak_working_set_size as u64,
        page_faults: mem.page_fault_count,
    })
}

// ---------------------------------------------------------------------------
// 1027: bi_perf_stat — Performance counters (Linux and Windows)
// ---------------------------------------------------------------------------
fn bi_perf_stat(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    linux_diagnostics::no_pipeline_input("perf_stat", &input)?;
    if args.is_empty() || args.len() > 2 {
        return Err(crate::safety::arg_err(
            "perf_stat: expected an argv array and optionally an event list, e.g. perf_stat([\"/usr/bin/true\"], \"cycles\")",
        ));
    }
    let argv = linux_diagnostics::argv_arg("perf_stat", &args[0])?;
    let events = match args.get(1) {
        None => "cycles,instructions,cache-misses".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "perf_stat",
                "an event list String such as \"cycles,instructions\"",
                other.type_name(),
            ))
        }
    };
    linux_diagnostics::event_list("perf_stat", &events)?;
    let command = argv.join(" ");
    crate::safety::guard_exec("perf_stat", command.clone())?;
    #[cfg(target_os = "linux")]
    {
        let limit = std::time::Duration::from_secs(120);
        let mut pargs = vec![
            "stat".to_string(),
            "-e".to_string(),
            events.clone(),
            "--".to_string(),
        ];
        pargs.extend(argv.iter().cloned());
        let run = linux_diagnostics::run_bounded("perf_stat", "perf", "perf", &pargs, limit)?;
        linux_diagnostics::require_success("perf_stat", "perf stat", &run, limit)?;
        // perf stat writes its report to stderr.
        let mut counters = Vec::new();
        for line in run.stderr.lines() {
            let line = line.trim();
            if line.is_empty()
                || line.starts_with('#')
                || line.starts_with("Performance counter stats")
            {
                continue;
            }
            // "value  event  # comment", or "<not supported> event".
            let body = line.split('#').next().unwrap_or("").trim();
            let (value, name) = if let Some(rest) = body.strip_prefix("<not") {
                let (what, name) = rest.split_once('>').unwrap_or(("", rest));
                (format!("<not{what}>"), name.trim().to_string())
            } else {
                match body.split_once(char::is_whitespace) {
                    Some((v, n)) => (v.to_string(), n.trim().to_string()),
                    None => continue,
                }
            };
            if name.is_empty() {
                continue;
            }
            let mut counter = BTreeMap::new();
            counter.insert("value".to_string(), Value::Str(value));
            counter.insert("name".to_string(), Value::Str(name));
            counters.push(Value::Record(counter));
        }
        if counters.is_empty() {
            return Err(crate::safety::tool_failed(
                "perf_stat",
                "perf stat",
                run.code,
                &format!("no counters were reported; stderr was: {}", run.stderr),
            ));
        }
        let mut rec = BTreeMap::new();
        rec.insert("command".to_string(), Value::Str(command));
        rec.insert("events".to_string(), Value::Str(events));
        rec.insert("counters".to_string(), Value::Array(counters));
        rec.insert("raw_output".to_string(), Value::Str(run.stderr));
        Ok(Value::Record(rec))
    }
    #[cfg(windows)]
    {
        // The event list is Linux only. It was checked above; a call that passes
        // one is refused here rather than read and ignored.
        if args.len() == 2 {
            return Err(crate::safety::unimplemented(
                "perf_stat",
                "the event list is Linux only: Windows reads a fixed set of counters; NOTHING WAS RUN",
                "call monitor_perf_stat(argv) with the argv alone",
            ));
        }
        let _ = events;
        // The argv runs as given: argv[0] is the program, found on PATH, with no
        // shell and no perf in between.
        let limit = std::time::Duration::from_secs(120);
        let mut cmd = std::process::Command::new(&argv[0]);
        cmd.args(&argv[1..]);
        let mut sampled = None;
        let tree = run_tree_cmd_observed(
            cmd,
            None,
            limit,
            Keep::Head(linux_diagnostics::MAX_OUTPUT),
            Keep::Head(linux_diagnostics::MAX_OUTPUT),
            |child, waited| sampled = Some((win_process_stats(child), waited)),
        )
        .map_err(|e| match e {
            TreeError::Spawn(e) => crate::safety::spawn_error("perf_stat", &argv[0], &e),
            TreeError::Wait(e) => e.into(),
        })?;
        let run = linux_diagnostics::Run {
            code: tree.code,
            timed_out: tree.timed_out,
            truncated: tree.stdout_truncated || tree.stderr_truncated || tree.pipes_abandoned,
            stdout: String::from_utf8_lossy(&tree.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&tree.stderr).into_owned(),
        };
        linux_diagnostics::require_success("perf_stat", &command, &run, limit)?;
        let (stats, waited) = match sampled {
            Some((Ok(stats), waited)) => (stats, waited),
            Some((Err(e), _)) => {
                return Err(crate::safety::bad_state(
                    "perf_stat",
                    &format!(
                        "GetProcessTimes or K32GetProcessMemoryInfo failed on `{}`: {e}",
                        argv[0]
                    ),
                    "a child this process started, read before its handle is closed",
                ))
            }
            None => {
                return Err(crate::safety::bad_state(
                    "perf_stat",
                    "the child was not sampled before it was reaped",
                    "a child this process started and waited for",
                ))
            }
        };
        let ms = |ticks: u64| Value::Int((ticks / 10_000) as i64);
        let counter = |name: &str, value: Value| {
            let mut c = BTreeMap::new();
            c.insert("name".to_string(), Value::Str(name.to_string()));
            c.insert("value".to_string(), value);
            Value::Record(c)
        };
        let counters = vec![
            counter("task_clock_ms", ms(stats.user_ticks + stats.kernel_ticks)),
            counter("user_ms", ms(stats.user_ticks)),
            counter("system_ms", ms(stats.kernel_ticks)),
            counter("elapsed_ms", Value::Int(waited.as_millis() as i64)),
            counter("peak_rss_bytes", Value::Int(stats.peak_rss as i64)),
            counter("page_faults", Value::Int(i64::from(stats.page_faults))),
        ];
        let mut rec = BTreeMap::new();
        rec.insert("command".to_string(), Value::Str(command));
        rec.insert("counters".to_string(), Value::Array(counters));
        rec.insert("raw_output".to_string(), Value::Str(run.stderr));
        Ok(Value::Record(rec))
    }
    #[cfg(not(any(target_os = "linux", windows)))]
    {
        let _ = (command, events);
        Err(crate::safety::unimplemented(
            "perf_stat",
            "perf stat is Linux only; NOTHING WAS RUN on this operating system",
            "run it on Linux",
        ))
    }
}

// ---------------------------------------------------------------------------
// 1028: bi_perf_record — Performance recording info (Linux only)
// ---------------------------------------------------------------------------
fn bi_perf_record(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    linux_diagnostics::no_pipeline_input("perf_record", &input)?;
    if args.is_empty() || args.len() > 2 {
        return Err(crate::safety::arg_err(
            "perf_record: expected an argv array and optionally an output path, e.g. perf_record([\"/usr/bin/true\"], \"/tmp/x.data\")",
        ));
    }
    let argv = linux_diagnostics::argv_arg("perf_record", &args[0])?;
    let output_file = match args.get(1) {
        None => "perf.data".to_string(),
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "perf_record",
                "an output path String",
                other.type_name(),
            ))
        }
    };
    linux_diagnostics::output_path("perf_record", &output_file)?;
    let command = argv.join(" ");
    crate::safety::guard_exec("perf_record", command.clone())?;
    #[cfg(target_os = "linux")]
    {
        let limit = std::time::Duration::from_secs(120);
        let mut pargs = vec![
            "record".to_string(),
            "-o".to_string(),
            output_file.clone(),
            "--".to_string(),
        ];
        pargs.extend(argv.iter().cloned());
        let run = linux_diagnostics::run_bounded("perf_record", "perf", "perf", &pargs, limit)?;
        linux_diagnostics::require_success("perf_record", "perf record", &run, limit)?;
        let bytes = match std::fs::metadata(&output_file) {
            Ok(meta) => meta.len(),
            Err(_) => {
                return Err(crate::safety::tool_failed(
                    "perf_record",
                    "perf record",
                    Some(0),
                    &format!("perf exited 0 but wrote no file at {output_file}"),
                ))
            }
        };
        let mut rec = BTreeMap::new();
        rec.insert("command".to_string(), Value::Str(command));
        rec.insert("output_file".to_string(), Value::Str(output_file.clone()));
        rec.insert("bytes".to_string(), Value::Int(bytes as i64));
        rec.insert("success".to_string(), Value::Bool(true));
        rec.insert(
            "details".to_string(),
            Value::Str(run.stderr.trim().to_string()),
        );
        rec.insert(
            "hint".to_string(),
            Value::Str(format!(
                "Use 'perf report -i {output_file}' to analyze the recorded data"
            )),
        );
        Ok(Value::Record(rec))
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = (command, output_file);
        Err(crate::safety::unimplemented(
            "perf_record",
            "perf record is Linux only; NOTHING WAS RUN on this operating system",
            "run it on Linux",
        ))
    }
}
// ---------------------------------------------------------------------------
// 1019: bi_free_mem - Memory usage (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_free_mem(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    monitor_direct_call("monitor_memory", &args, &input, 0)?;
    let mut sys = System::new();
    sys.refresh_memory();
    let total = sys.total_memory();
    let used = sys.used_memory();
    let free = sys.free_memory();
    let available = sys.available_memory();
    let swap_total = sys.total_swap();
    let swap_used = sys.used_swap();
    let swap_free = swap_total.saturating_sub(swap_used);
    let mut rec = BTreeMap::new();
    rec.insert("total".to_string(), Value::Int(total as i64));
    rec.insert("used".to_string(), Value::Int(used as i64));
    rec.insert("free".to_string(), Value::Int(free as i64));
    rec.insert("available".to_string(), Value::Int(available as i64));
    rec.insert(
        "use_percent".to_string(),
        Value::Float(if total > 0 {
            used as f64 / total as f64 * 100.0
        } else {
            0.0
        }),
    );
    rec.insert("swap_total".to_string(), Value::Int(swap_total as i64));
    rec.insert("swap_used".to_string(), Value::Int(swap_used as i64));
    rec.insert("swap_free".to_string(), Value::Int(swap_free as i64));
    Ok(Value::Record(rec))
}
// ---------------------------------------------------------------------------
// 1020: bi_uptime_extended - Extended uptime info (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_uptime_extended(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let secs = System::uptime();
    let days = secs / 86400;
    let hours = (secs % 86400) / 3600;
    let minutes = (secs % 3600) / 60;
    let seconds = secs % 60;
    let human = format!("{}d {}h {}m {}s", days, hours, minutes, seconds);
    let mut rec = BTreeMap::new();
    rec.insert("uptime_seconds".to_string(), Value::Int(secs as i64));
    rec.insert("uptime_human".to_string(), Value::Str(human));
    rec.insert("days".to_string(), Value::Int(days as i64));
    rec.insert("hours".to_string(), Value::Int(hours as i64));
    rec.insert("minutes".to_string(), Value::Int(minutes as i64));
    rec.insert("seconds".to_string(), Value::Int(seconds as i64));
    load_fields(&mut rec);
    // A missing host name was "" (see bi_glances_info).
    rec.insert("hostname".to_string(), bi_sys_hostname(Vec::new(), None)?);
    Ok(Value::Record(rec))
}

// ---------------------------------------------------------------------------
// 1031: bi_who_users — Currently logged in users
// ---------------------------------------------------------------------------
fn bi_who_users(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_users";
    monitor_direct_call(B, &args, &input, 0)?;

    #[cfg(target_os = "windows")]
    {
        // query.exe exits 1 and says "No User exists" when nobody is logged on.
        // That is an empty answer, not a failure.
        let run = tool_run(
            B,
            "query",
            None,
            &["user"],
            Keep::Head(TOOL_MAX_TEXT),
            TOOL_DEADLINE_SECS,
        )?;
        if !run.success && format!("{}{}", run.stdout, run.stderr).contains("No User exists") {
            return Ok(Value::Array(Vec::new()));
        }
        let text = tool_text(B, run)?;
        Ok(Value::Array(monitor_parse::query_user_records(&text)?))
    }

    #[cfg(not(target_os = "windows"))]
    {
        let text = monitor_text(B, "who", &[], TOOL_MAX_TEXT)?;
        Ok(Value::Array(monitor_parse::who_records(&text)?))
    }
}

// ---------------------------------------------------------------------------
// 1032: bi_last_logins — Recent login history
// ---------------------------------------------------------------------------
fn bi_last_logins(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_logins";
    monitor_direct_call(B, &args, &input, 1)?;
    let count = monitor_int_arg(B, &args, 0, 20, 1, 1000, "a login count")?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = crate::ps_script!(
            // Always an array (one event serialised as a bare object); no
            // events is []; anything else -- access denied above all -- is an
            // error, where all of it used to be {available: false, reason}.
            r#"try {{
    $r = @(Get-WinEvent -FilterHashtable @{{LogName='Security'; Id=4624}} -MaxEvents {} -ErrorAction Stop |
        Select-Object TimeCreated, Id, @{{Name='User';Expression={{$_.Properties[5].Value}}}}, @{{Name='LogonType';Expression={{$_.Properties[8].Value}}}}, @{{Name='SourceIP';Expression={{$_.Properties[18].Value}}}})
    ConvertTo-Json -InputObject $r -Depth 3
}} catch {{
    if ($_.FullyQualifiedErrorId -like 'NoMatchingEventsFound*') {{ '[]' }}
    else {{ [Console]::Error.WriteLine($_.Exception.Message); exit 1 }}
}}"#,
            count
        );
        monitor_ps_json(
            B,
            "Get-WinEvent (the Security log needs an elevated shell)",
            &ps_cmd,
        )
    }

    #[cfg(not(target_os = "windows"))]
    {
        let n = count.to_string();
        let text = monitor_text(B, "last", &["-n", n.as_str()], TOOL_MAX_TEXT)?;
        Ok(Value::Array(monitor_parse::last_records(&text)?))
    }
}

// ---------------------------------------------------------------------------
// 1033: bi_syslog_search — System log search
// ---------------------------------------------------------------------------
fn bi_syslog_search(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_syslog";
    monitor_direct_call(B, &args, &input, 2)?;
    let keyword = match args.first() {
        Some(Value::Str(k)) => k.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                "a keyword String",
                &monitor_got(args.first()),
            ))
        }
    };
    monitor_keyword(B, &keyword)?;
    let count = monitor_int_arg(B, &args, 1, 50, 1, 1000, "a match count")?;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = crate::ps_script!(
            // Always an array; no events is []; any other failure is an error,
            // where it used to be {available: false, reason} at exit 0. Only the
            // newest 500 System events are searched.
            r#"try {{
    $r = @(Get-WinEvent -FilterHashtable @{{LogName='System'}} -MaxEvents 500 -ErrorAction Stop |
        Where-Object {{ $_.Message -match [regex]::Escape({}) }} |
        Select-Object -First {} |
        Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message)
    ConvertTo-Json -InputObject $r -Depth 3
}} catch {{
    if ($_.FullyQualifiedErrorId -like 'NoMatchingEventsFound*') {{ '[]' }}
    else {{ [Console]::Error.WriteLine($_.Exception.Message); exit 1 }}
}}"#,
            crate::safety::ps_quote(&keyword),
            count
        );
        monitor_ps_json(B, "Get-WinEvent", &ps_cmd)
    }

    #[cfg(target_os = "linux")]
    {
        // journalctl first. The syslog file is read only when journalctl is not
        // installed; a journalctl that runs and fails is an error, not a cue to
        // answer from a different source.
        let n = count.to_string();
        let journal = tool_run(
            B,
            "journalctl",
            None,
            &[
                "-g",
                keyword.as_str(),
                "-n",
                n.as_str(),
                "--no-pager",
                "-o",
                "json",
            ],
            Keep::Head(TOOL_MAX_JSON),
            TOOL_DEADLINE_SECS,
        );
        match journal {
            Ok(run) => {
                let text = tool_text(B, run)?;
                Ok(Value::Array(monitor_parse::journal_records(&text)?))
            }
            Err(e) if monitor_tool_missing(&e) => {
                let log = ["/var/log/syslog", "/var/log/messages"]
                    .into_iter()
                    .find(|p| std::path::Path::new(p).exists())
                    .ok_or_else(|| {
                        crate::safety::tool_missing(
                            B,
                            "journalctl",
                            "and there is no /var/log/syslog or /var/log/messages to read instead",
                        )
                    })?;
                // grep: exit 1 is "no line matched"; `-e` keeps a keyword from
                // being read as an option.
                let run = tool_run(
                    B,
                    "grep",
                    None,
                    &["-i", "-e", keyword.as_str(), log],
                    Keep::Tail(TOOL_MAX_TEXT),
                    TOOL_DEADLINE_SECS,
                )?;
                if run.code == Some(1) {
                    return Ok(Value::Array(Vec::new()));
                }
                if !run.success {
                    return Err(crate::safety::tool_failed(B, "grep", run.code, &run.stderr));
                }
                // A tail cut short starts mid-line, so that fragment is dropped.
                let text = if run.stdout_truncated {
                    run.stdout.split_once('\n').map_or("", |(_, rest)| rest)
                } else {
                    run.stdout.as_str()
                };
                Ok(Value::Array(monitor_parse::grep_records(
                    text,
                    count as usize,
                    log,
                )))
            }
            Err(e) => Err(e),
        }
    }

    #[cfg(target_os = "macos")]
    {
        // Backslashes first: escaping only the quote let a trailing backslash
        // re-open the string.
        let predicate = format!(
            "eventMessage contains \"{}\"",
            keyword.replace('\\', "\\\\").replace('"', "\\\"")
        );
        let records = monitor_json_records(
            B,
            "log",
            &[
                "show",
                "--predicate",
                predicate.as_str(),
                "--last",
                "1h",
                "--style",
                "json",
            ],
        )?;
        Ok(monitor_newest(records, count))
    }
}

// ---------------------------------------------------------------------------
// 1034: bi_dstat_info — System resource stats (aggregate)
// ---------------------------------------------------------------------------
// 1034: bi_dstat_info - System resource stats (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_dstat_info(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    monitor_direct_call("monitor_dstat", &args, &input, 0)?;
    let sys = monitor_sample_system();
    let mut stats = BTreeMap::new();
    // Per-CPU usage
    let cpus: Vec<Value> = sys
        .cpus()
        .iter()
        .map(|c| {
            let mut m = BTreeMap::new();
            m.insert("name".to_string(), Value::Str(c.name().to_string()));
            m.insert(
                "usage_percent".to_string(),
                Value::Float(c.cpu_usage() as f64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("cpus".to_string(), Value::Array(cpus));
    stats.insert(
        "cpu_percent".to_string(),
        Value::Float(sys.global_cpu_usage() as f64),
    );
    // Memory
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mut mem = BTreeMap::new();
    mem.insert("total".to_string(), Value::Int(total_mem as i64));
    mem.insert("used".to_string(), Value::Int(used_mem as i64));
    mem.insert(
        "free".to_string(),
        Value::Int(total_mem.saturating_sub(used_mem) as i64),
    );
    stats.insert("memory".to_string(), Value::Record(mem));
    // Disks
    let disks = Disks::new_with_refreshed_list();
    let disk_entries: Vec<Value> = disks
        .iter()
        .map(|d| {
            let mut m = BTreeMap::new();
            m.insert(
                "name".to_string(),
                Value::Str(d.name().to_string_lossy().to_string()),
            );
            m.insert(
                "total_bytes".to_string(),
                Value::Int(d.total_space() as i64),
            );
            m.insert(
                "available_bytes".to_string(),
                Value::Int(d.available_space() as i64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("disk".to_string(), Value::Array(disk_entries));
    // Networks
    let nets = Networks::new_with_refreshed_list();
    let net_entries: Vec<Value> = nets
        .iter()
        .map(|(name, data)| {
            let mut m = BTreeMap::new();
            m.insert("interface".to_string(), Value::Str(name.clone()));
            m.insert(
                "rx_bytes".to_string(),
                Value::Int(data.total_received() as i64),
            );
            m.insert(
                "tx_bytes".to_string(),
                Value::Int(data.total_transmitted() as i64),
            );
            m.insert(
                "rx_packets".to_string(),
                Value::Int(data.total_packets_received() as i64),
            );
            m.insert(
                "tx_packets".to_string(),
                Value::Int(data.total_packets_transmitted() as i64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("network".to_string(), Value::Array(net_entries));
    stats.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(stats))
}

// ===========================================================================
// Proactive Monitoring & Alerting Builtins (836-843)
// ===========================================================================

// 836: bi_health_check - Comprehensive system health check
pub fn bi_health_check(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    monitor_direct_call("monitor_health_check", &args, &input, 0)?;
    let sys = monitor_sample_system();

    let cpu = sys.global_cpu_usage() as f64;
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_pct = if total_mem > 0 {
        used_mem as f64 / total_mem as f64 * 100.0
    } else {
        0.0
    };

    let disks = Disks::new_with_refreshed_list();
    let total_disk: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail_disk: u64 = disks.iter().map(|d| d.available_space()).sum();
    let disk_pct = if total_disk > 0 {
        total_disk.saturating_sub(avail_disk) as f64 / total_disk as f64 * 100.0
    } else {
        0.0
    };

    // Determine overall health status
    let status = if cpu > 95.0 || mem_pct > 95.0 || disk_pct > 95.0 {
        "critical"
    } else if cpu > 80.0 || mem_pct > 80.0 || disk_pct > 85.0 {
        "warning"
    } else {
        "healthy"
    };

    let mut alerts = Vec::new();
    if cpu > 80.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("cpu".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(if cpu > 95.0 { "critical" } else { "warning" }.to_string()),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("CPU usage at {:.1}%", cpu)),
        );
        a.insert("value".to_string(), Value::Float(cpu));
        a.insert("threshold".to_string(), Value::Float(80.0));
        alerts.push(Value::Record(a));
    }
    if mem_pct > 80.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("memory".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(
                if mem_pct > 95.0 {
                    "critical"
                } else {
                    "warning"
                }
                .to_string(),
            ),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("Memory usage at {:.1}%", mem_pct)),
        );
        a.insert("value".to_string(), Value::Float(mem_pct));
        a.insert("threshold".to_string(), Value::Float(80.0));
        alerts.push(Value::Record(a));
    }
    if disk_pct > 85.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("disk".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(
                if disk_pct > 95.0 {
                    "critical"
                } else {
                    "warning"
                }
                .to_string(),
            ),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("Disk usage at {:.1}%", disk_pct)),
        );
        a.insert("value".to_string(), Value::Float(disk_pct));
        a.insert("threshold".to_string(), Value::Float(85.0));
        alerts.push(Value::Record(a));
    }

    let mut rec = BTreeMap::new();
    rec.insert("status".to_string(), Value::Str(status.to_string()));
    rec.insert("cpu_percent".to_string(), Value::Float(cpu));
    rec.insert("memory_percent".to_string(), Value::Float(mem_pct));
    rec.insert("disk_percent".to_string(), Value::Float(disk_pct));
    load_fields(&mut rec);
    rec.insert(
        "process_count".to_string(),
        Value::Int(sys.processes().len() as i64),
    );
    rec.insert("alerts".to_string(), Value::Array(alerts));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 837: bi_alert_create - Create an alert rule for a metric
pub fn bi_alert_create(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_alert_create";
    monitor_direct_call(B, &args, &input, 5)?;
    let name = match args.first() {
        Some(Value::Str(s)) if !s.trim().is_empty() && s.chars().count() <= 100 => {
            s.trim().to_string()
        }
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                "a rule name: a non-empty String of at most 100 characters",
                &monitor_got(args.first()),
            ))
        }
    };
    let metric = match args.get(1) {
        Some(Value::Str(s)) if MONITOR_METRICS.contains(&s.as_str()) => s.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                "a metric: \"cpu\", \"memory\" or \"disk\"",
                &monitor_got(args.get(1)),
            ))
        }
    };
    let condition = monitor_choice_arg(B, &args, 2, MONITOR_CONDITIONS, ">")?;
    let threshold = monitor_percent_arg(B, &args, 3, 80.0)?;
    let severity = monitor_choice_arg(B, &args, 4, MONITOR_SEVERITIES, "warning")?;

    let mut store = monitor_store_load(B)?;
    if store.rules.len() >= MONITOR_MAX_RULES {
        return Err(crate::safety::budget_exceeded(
            B,
            format!("the alert store already holds {MONITOR_MAX_RULES} rules"),
            "remove a rule with monitor_alert_remove before creating another",
        ));
    }
    let base = format!(
        "alert_{}_{}",
        metric,
        chrono::Local::now().timestamp_millis()
    );
    let mut id = base.clone();
    let mut n = 1usize;
    while store
        .rules
        .iter()
        .any(|r| r.get("id").and_then(|v| v.as_str()) == Some(id.as_str()))
    {
        id = format!("{base}_{n}");
        n += 1;
    }
    let rule = serde_json::json!({
        "id": id,
        "name": name,
        "metric": metric,
        "condition": condition,
        "threshold": threshold,
        "severity": severity,
        "status": "active",
        "created_at": chrono::Local::now().to_rfc3339(),
    });
    store.rules.push(rule.clone());
    monitor_history_push(&mut store, "created", &rule);
    monitor_store_save(B, &store)?;
    Ok(json_to_value(rule))
}

// 838: bi_alert_list - List active alert rules
pub fn bi_alert_list(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_alert_list";
    monitor_direct_call(B, &args, &input, 0)?;
    let store = monitor_store_load(B)?;
    if store.rules.is_empty() {
        return Ok(Value::Array(Vec::new()));
    }
    let sys = monitor_sample_system();
    // Read the disks only when a rule needs them, so a host whose disks
    // cannot be measured still evaluates its cpu and memory rules.
    let wants_disk = store
        .rules
        .iter()
        .any(|r| r.get("metric").and_then(|m| m.as_str()) == Some("disk"));
    let disk_pct = if wants_disk {
        Some(monitor_disk_used_percent()?)
    } else {
        None
    };
    let mut out = Vec::with_capacity(store.rules.len());
    for rule in &store.rules {
        let metric = monitor_rule_str(B, rule, "metric")?;
        let condition = monitor_rule_str(B, rule, "condition")?;
        let threshold = monitor_rule_f64(B, rule, "threshold")?;
        let current = monitor_metric_value(metric, &sys, disk_pct).ok_or_else(|| {
            monitor_store_error(
                B,
                &monitor_store_path(),
                &format!("a rule has the unknown metric \"{metric}\""),
            )
        })?;
        let mut rec = rule.clone();
        rec["current_value"] = serde_json::json!(current);
        rec["triggered"] = serde_json::json!(monitor_breached(current, condition, threshold));
        out.push(json_to_value(rec));
    }
    Ok(Value::Array(out))
}

// 839: bi_alert_history - Get alert history
pub fn bi_alert_history(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_alert_history";
    monitor_direct_call(B, &args, &input, 1)?;
    let limit = monitor_int_arg(B, &args, 0, 50, 1, 1000, "an event count")? as usize;
    let store = monitor_store_load(B)?;
    let out: Vec<Value> = store
        .history
        .iter()
        .rev()
        .take(limit)
        .cloned()
        .map(json_to_value)
        .collect();
    Ok(Value::Array(out))
}

// 840: bi_alert_remove - Remove an alert rule by ID
pub fn bi_alert_remove(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_alert_remove";
    monitor_direct_call(B, &args, &input, 1)?;
    let id = match args.first() {
        Some(Value::Str(s)) if !s.is_empty() && s.len() <= 100 => s.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                B,
                "an alert id: a non-empty String of at most 100 bytes",
                &monitor_got(args.first()),
            ))
        }
    };
    let mut store = monitor_store_load(B)?;
    let Some(pos) = store
        .rules
        .iter()
        .position(|r| r.get("id").and_then(|v| v.as_str()) == Some(id.as_str()))
    else {
        return Err(crate::safety::not_found(B, "alert", &id));
    };
    let rule = store.rules.remove(pos);
    monitor_history_push(&mut store, "removed", &rule);
    monitor_store_save(B, &store)?;
    Ok(json_to_value(serde_json::json!({
        "id": id,
        "removed": true,
        "timestamp": chrono::Local::now().to_rfc3339(),
    })))
}

// 841: bi_watch_cpu - Monitor CPU usage with threshold alerting
pub fn bi_watch_cpu(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_watch_cpu";
    monitor_direct_call(B, &args, &input, 2)?;
    let threshold = monitor_percent_arg(B, &args, 0, 80.0)?;
    // At most 10 samples, 500 ms apart: a watch lasts at most about 5 seconds.
    let samples = monitor_int_arg(B, &args, 1, 5, 1, 10, "a sample count")? as usize;

    let mut sys = System::new();
    sys.refresh_cpu_all();
    let mut readings = Vec::with_capacity(samples);
    let mut total = 0.0_f64;
    let mut breaches = 0_usize;
    for i in 0..samples {
        std::thread::sleep(std::time::Duration::from_millis(MONITOR_WATCH_INTERVAL_MS));
        sys.refresh_cpu_all();
        let cpu = sys.global_cpu_usage() as f64;
        let above = cpu > threshold;
        total += cpu;
        if above {
            breaches += 1;
        }
        let mut sample = BTreeMap::new();
        sample.insert("sample".to_string(), Value::Int(i as i64 + 1));
        sample.insert("cpu_percent".to_string(), Value::Float(cpu));
        sample.insert("above_threshold".to_string(), Value::Bool(above));
        sample.insert(
            "timestamp".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        readings.push(Value::Record(sample));
    }

    let avg = total / samples as f64;
    let mut rec = BTreeMap::new();
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("samples".to_string(), Value::Int(samples as i64));
    rec.insert("average_cpu".to_string(), Value::Float(avg));
    rec.insert("breaches".to_string(), Value::Int(breaches as i64));
    rec.insert("alert".to_string(), Value::Bool(breaches > samples / 2));
    rec.insert("readings".to_string(), Value::Array(readings));
    Ok(Value::Record(rec))
}

// 842: bi_watch_memory - Monitor memory usage with threshold alerting
pub fn bi_watch_memory(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_watch_memory";
    monitor_direct_call(B, &args, &input, 1)?;
    let threshold = monitor_percent_arg(B, &args, 0, 80.0)?;
    let mut sys = System::new();
    sys.refresh_memory();

    let total = sys.total_memory();
    let used = sys.used_memory();
    let free = sys.free_memory();
    let available = sys.available_memory();
    let pct = if total > 0 {
        used as f64 / total as f64 * 100.0
    } else {
        0.0
    };

    let swap_total = sys.total_swap();
    let swap_used = sys.used_swap();
    let swap_pct = if swap_total > 0 {
        swap_used as f64 / swap_total as f64 * 100.0
    } else {
        0.0
    };

    let status = if pct > 95.0 {
        "critical"
    } else if pct > threshold {
        "warning"
    } else {
        "healthy"
    };

    let mut rec = BTreeMap::new();
    rec.insert("status".to_string(), Value::Str(status.to_string()));
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("total_bytes".to_string(), Value::Int(total as i64));
    rec.insert("used_bytes".to_string(), Value::Int(used as i64));
    rec.insert("free_bytes".to_string(), Value::Int(free as i64));
    rec.insert("available_bytes".to_string(), Value::Int(available as i64));
    rec.insert("use_percent".to_string(), Value::Float(pct));
    rec.insert("above_threshold".to_string(), Value::Bool(pct > threshold));
    rec.insert("swap_total".to_string(), Value::Int(swap_total as i64));
    rec.insert("swap_used".to_string(), Value::Int(swap_used as i64));
    rec.insert("swap_percent".to_string(), Value::Float(swap_pct));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 843: bi_watch_disk - Monitor disk usage with threshold alerting
pub fn bi_watch_disk(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "monitor_watch_disk";
    monitor_direct_call(B, &args, &input, 1)?;
    let threshold = monitor_percent_arg(B, &args, 0, 85.0)?;
    let disks = Disks::new_with_refreshed_list();
    let mut disk_entries = Vec::new();
    let mut any_alert = false;

    for disk in disks.iter() {
        let total = disk.total_space();
        let avail = disk.available_space();
        let used = total.saturating_sub(avail);
        let pct = if total > 0 {
            used as f64 / total as f64 * 100.0
        } else {
            0.0
        };
        let above = pct > threshold;
        if above {
            any_alert = true;
        }

        let mut rec = BTreeMap::new();
        rec.insert(
            "mount".to_string(),
            Value::Str(disk.mount_point().to_string_lossy().to_string()),
        );
        rec.insert(
            "filesystem".to_string(),
            Value::Str(disk.file_system().to_string_lossy().to_string()),
        );
        rec.insert("total_bytes".to_string(), Value::Int(total as i64));
        rec.insert("used_bytes".to_string(), Value::Int(used as i64));
        rec.insert("available_bytes".to_string(), Value::Int(avail as i64));
        rec.insert("use_percent".to_string(), Value::Float(pct));
        rec.insert("above_threshold".to_string(), Value::Bool(above));
        let status = if pct > 95.0 {
            "critical"
        } else if above {
            "warning"
        } else {
            "healthy"
        };
        rec.insert("status".to_string(), Value::Str(status.to_string()));
        disk_entries.push(Value::Record(rec));
    }

    let mut rec = BTreeMap::new();
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("alert".to_string(), Value::Bool(any_alert));
    rec.insert(
        "disk_count".to_string(),
        Value::Int(disk_entries.len() as i64),
    );
    rec.insert("disks".to_string(), Value::Array(disk_entries));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// ===================== Cloud Platform Builtins =====================

/// The current OS username (cross-platform). Neither variable set used to be
/// "unknown", which passed as a real user: workspace membership and package
/// authorship would record that name. It is refused instead.
///
/// Asked through `whoami`, which reads the user database by effective uid on
/// Unix: $USER is unset under cron, systemd units and many containers.
fn get_current_username(builtin: &str) -> Result<String> {
    match bi_whoami(Vec::new(), None)? {
        Value::Str(name) => Ok(name),
        other => Err(crate::safety::bad_state(
            builtin,
            &format!("whoami answered {}", other.type_name()),
            "whoami",
        )),
    }
}

