/// Get or set cloud platform configuration.
/// Usage: cloud.config() or cloud.config({provider?, region?, endpoint?, instance_type?})
fn bi_cloud_config(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if let Some(Value::Record(opts)) = args.first() {
        // Set config
        let provider = opts
            .get("provider")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "aether".to_string());
        let region = opts
            .get("region")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "us-east-1".to_string());
        let endpoint = opts.get("endpoint").and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        });
        let instance_type = opts
            .get("instance_type")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "ae.small".to_string());

        let config = CloudConfig {
            provider: provider.clone(),
            region: region.clone(),
            api_endpoint: endpoint.clone(),
            default_instance_type: instance_type.clone(),
        };

        let mut guard = CLOUD_CONFIG
            .write()
            .map_err(|_| crate::safety::lock_poisoned("cloud_config", "the cloud configuration"))?;
        *guard = Some(config);

        let mut rec = BTreeMap::new();
        rec.insert("provider".to_string(), Value::Str(provider));
        rec.insert("region".to_string(), Value::Str(region));
        if let Some(ep) = endpoint {
            rec.insert("endpoint".to_string(), Value::Str(ep));
        }
        rec.insert("instance_type".to_string(), Value::Str(instance_type));
        rec.insert("status".to_string(), Value::Str("configured".to_string()));
        Ok(Value::Record(rec))
    } else {
        // Get config
        let guard = CLOUD_CONFIG
            .read()
            .map_err(|_| crate::safety::lock_poisoned("cloud_config", "the cloud configuration"))?;
        if let Some(ref config) = *guard {
            let mut rec = BTreeMap::new();
            rec.insert("provider".to_string(), Value::Str(config.provider.clone()));
            rec.insert("region".to_string(), Value::Str(config.region.clone()));
            if let Some(ref ep) = config.api_endpoint {
                rec.insert("endpoint".to_string(), Value::Str(ep.clone()));
            }
            rec.insert(
                "instance_type".to_string(),
                Value::Str(config.default_instance_type.clone()),
            );
            Ok(Value::Record(rec))
        } else {
            Ok(Value::Null)
        }
    }
}

// ===================== Remote REPL Builtins =====================
//
// repl_serve starts a loopback TCP listener that evaluates code sent by a peer
// holding the token it returns, and only in agent mode. repl_connect is one
// request per connection: it sends {token, code} and returns the value. Remote
// code reaches the same builtin dispatcher as local code, so `guard_dispatch`
// judges every call it makes; nothing on this path skips it.
//
// Wire format: one newline-terminated JSON object each way.
//   request:  {"token": "<token>", "code": "<source>"}
//   response: {"ok": true, "value": <json>, "type": "<type name>"}
//             {"ok": false, "error": "<message>"}
// A wrong token gets {"ok": false, "error": "unauthorized"} and the connection
// closes. repl_broadcast stays refused: no session is held open, so no peer set
// exists.

/// Longest request or response line, in bytes.
const REPL_MAX_LINE: usize = 1024 * 1024;
/// Connections served at once; one beyond this is refused with one error line.
const REPL_MAX_CONNECTIONS: usize = 8;
/// Wall-clock limit on one remote evaluation.
const REPL_EVAL_LIMIT: Duration = Duration::from_secs(30);
/// Read and write timeout on each socket operation.
const REPL_IO_TIMEOUT: Duration = Duration::from_secs(10);

/// The running listener, if any. One per process.
struct ReplServer {
    addr: std::net::SocketAddr,
    token: String,
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

/// A request line that passed the shape check.
#[derive(Debug, PartialEq, Eq)]
struct ReplRequest {
    token: String,
    code: String,
}

/// Parse one request line. The error text is what the peer is told.
fn repl_parse_request(line: &[u8]) -> std::result::Result<ReplRequest, String> {
    let text = std::str::from_utf8(line).map_err(|_| "request is not UTF-8".to_string())?;
    let value: serde_json::Value =
        serde_json::from_str(text.trim_end()).map_err(|e| format!("request is not JSON: {e}"))?;
    let object = value
        .as_object()
        .ok_or_else(|| "request must be a JSON object".to_string())?;
    let token = object
        .get("token")
        .and_then(|v| v.as_str())
        .ok_or_else(|| "request needs a string token".to_string())?;
    let code = object
        .get("code")
        .and_then(|v| v.as_str())
        .ok_or_else(|| "request needs a string code".to_string())?;
    Ok(ReplRequest {
        token: token.to_string(),
        code: code.to_string(),
    })
}

/// Whether `given` is `expected`. Every byte of an equal-length pair is compared,
/// so a mismatch does not reveal how much of the token matched.
fn repl_token_matches(expected: &str, given: &str) -> bool {
    let (a, b) = (expected.as_bytes(), given.as_bytes());
    a.len() == b.len() && a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// Read one newline-terminated line of at most `max` bytes, newline excluded.
/// `Ok(None)` is EOF before any byte. A longer line is an error. The reader is
/// never asked for more than one buffer past the cap, so a peer cannot grow the
/// line without bound.
fn repl_read_line<R: std::io::BufRead>(
    reader: &mut R,
    max: usize,
) -> std::result::Result<Option<Vec<u8>>, String> {
    let mut line: Vec<u8> = Vec::new();
    loop {
        let (complete, used) = {
            let buf = reader.fill_buf().map_err(|e| format!("read failed: {e}"))?;
            if buf.is_empty() {
                return if line.is_empty() {
                    Ok(None)
                } else {
                    Err("connection closed mid-line".to_string())
                };
            }
            match buf.iter().position(|&b| b == b'\n') {
                Some(i) => {
                    line.extend_from_slice(&buf[..i]);
                    (true, i + 1)
                }
                None => {
                    line.extend_from_slice(buf);
                    (false, buf.len())
                }
            }
        };
        reader.consume(used);
        if line.len() > max {
            return Err(format!("line is longer than {max} bytes"));
        }
        if complete {
            return Ok(Some(line));
        }
    }
}

/// Evaluate remote source as `ae -c` evaluates local source: parse, then
/// `eval_program` in the module environment. Each builtin the source calls is
/// dispatched, and so guarded, exactly as it is locally.
fn repl_eval(code: &str) -> std::result::Result<Value, String> {
    let stmts = crate::parser::parse_program(code).map_err(|e| format!("parse error: {e}"))?;
    let mut env = crate::modules::env_with_modules();
    crate::eval::eval_program(&stmts, &mut env).map_err(|e| format!("{e}"))
}

fn repl_error_reply(reason: &str) -> serde_json::Value {
    serde_json::json!({"ok": false, "error": reason})
}

/// Write one reply line. A peer that has gone away is not something the server
/// can act on, so the write result is dropped.
fn repl_send(stream: &mut std::net::TcpStream, reply: &serde_json::Value) {
    use std::io::Write as _;
    let mut line = reply.to_string();
    line.push('\n');
    let _ = stream.write_all(line.as_bytes());
}

/// Serve one connection: one request, one reply, then close.
fn repl_handle_connection(mut stream: std::net::TcpStream, token: &str) {
    let _ = stream.set_read_timeout(Some(REPL_IO_TIMEOUT));
    let _ = stream.set_write_timeout(Some(REPL_IO_TIMEOUT));
    let read_side = match stream.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut reader = std::io::BufReader::new(read_side);
    let line = match repl_read_line(&mut reader, REPL_MAX_LINE) {
        Ok(Some(line)) => line,
        Ok(None) => return,
        Err(reason) => {
            repl_send(&mut stream, &repl_error_reply(&reason));
            return;
        }
    };
    let request = match repl_parse_request(&line) {
        Ok(request) => request,
        Err(reason) => {
            repl_send(&mut stream, &repl_error_reply(&reason));
            return;
        }
    };
    if crate::safety::current_mode() != crate::safety::Mode::Agent {
        repl_send(
            &mut stream,
            &repl_error_reply("remote evaluation needs agent mode"),
        );
        return;
    }
    if !repl_token_matches(token, &request.token) {
        repl_send(&mut stream, &repl_error_reply("unauthorized"));
        return;
    }
    let _deadline = crate::safety::enter_deadline(REPL_EVAL_LIMIT);
    let reply = match repl_eval(&request.code) {
        Ok(value) => {
            let type_name = value.type_name().to_string();
            serde_json::json!({
                "ok": true,
                "value": value_to_json(value),
                "type": type_name,
            })
        }
        Err(reason) => repl_error_reply(&reason),
    };
    repl_send(&mut stream, &reply);
}

/// Decrements the live-connection count however a connection thread ends.
struct ReplSlot(std::sync::Arc<std::sync::atomic::AtomicUsize>);

impl Drop for ReplSlot {
    fn drop(&mut self) {
        self.0.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
    }
}

/// Accept connections until `stop` is set. The listener is non-blocking, so the
/// flag is seen within one poll interval.
fn repl_accept_loop(
    listener: std::net::TcpListener,
    token: String,
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
) {
    use std::sync::atomic::{AtomicUsize, Ordering};
    let live = std::sync::Arc::new(AtomicUsize::new(0));
    while !stop.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((mut stream, _peer)) => {
                let _ = stream.set_nonblocking(false);
                if live.fetch_add(1, Ordering::SeqCst) >= REPL_MAX_CONNECTIONS {
                    live.fetch_sub(1, Ordering::SeqCst);
                    repl_send(&mut stream, &repl_error_reply("too many connections"));
                    continue;
                }
                let slot = ReplSlot(live.clone());
                let token = token.clone();
                let _ = std::thread::Builder::new()
                    .name("repl-conn".to_string())
                    .spawn(move || {
                        let _slot = slot;
                        repl_handle_connection(stream, &token);
                    });
            }
            Err(_) => std::thread::sleep(Duration::from_millis(25)),
        }
    }
}

/// A transport failure on a REPL connection (`E_IO`).
fn repl_io_error(builtin: &str, message: &str) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::Io,
        builtin: builtin.into(),
        message: format!("{builtin}: {message}"),
        hint: "the connection was closed or stalled; no remote result was received".into(),
        approval: None,
        did_you_mean: vec![],
        expected: "a complete reply line from the REPL listener".into(),
        got: message.into(),
    })
}

/// repl_serve(options?) - Serve this process's evaluation on a loopback port.
///
/// Options: `host` (a literal loopback address, default 127.0.0.1), `port`
/// (0..65535; 0 picks a free one), and `stop: true` to stop the running
/// listener. Returns {address, port, token, status}; every request must present
/// the token. Serving needs agent mode, so a peer gets the agent-mode policy.
fn bi_repl_serve(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "repl_serve";
    refuse_piped_subject(NAME, &input)?;
    if args.len() > 1 {
        return Err(crate::safety::bad_arg(
            NAME,
            "at most one options Record",
            "more arguments",
        ));
    }
    let fields = match args.into_iter().next() {
        None | Some(Value::Null) => BTreeMap::new(),
        Some(Value::Record(fields)) => fields,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                NAME,
                "options: Record",
                other.type_name(),
            ))
        }
    };
    let mut host: std::net::IpAddr = std::net::Ipv4Addr::LOCALHOST.into();
    let mut port: i64 = 0;
    let mut stop = false;
    for (key, value) in fields {
        match (key.as_str(), value) {
            ("host", Value::Str(text)) => {
                host = text.parse::<std::net::IpAddr>().map_err(|_| {
                    crate::safety::bad_arg(NAME, "host: a literal IP address", &text)
                })?;
            }
            ("port", Value::Int(n)) if (0..=65535i64).contains(&n) => port = n,
            ("stop", Value::Bool(flag)) => stop = flag,
            (other, _) => {
                return Err(crate::safety::bad_arg(
                    NAME,
                    "options: host String, port Int 0..65535, stop Bool",
                    other,
                ))
            }
        }
    }

    let mut slot = REPL_SERVER
        .lock()
        .map_err(|_| crate::safety::lock_poisoned(NAME, "the REPL listener"))?;
    if stop {
        let server = slot.take().ok_or_else(|| {
            crate::safety::bad_state(NAME, "no REPL listener is running", "repl_serve")
        })?;
        server.stop.store(true, std::sync::atomic::Ordering::SeqCst);
        let mut rec = BTreeMap::new();
        rec.insert("address".to_string(), Value::Str(server.addr.to_string()));
        rec.insert("status".to_string(), Value::Str("stopped".to_string()));
        return Ok(Value::Record(rec));
    }

    if crate::tx::is_active() {
        return Err(crate::safety::unimplemented(
            NAME,
            "listeners and network effects cannot be rolled back",
            "finish the transaction first",
        ));
    }
    if !host.is_loopback() {
        return Err(crate::safety::bad_arg(
            NAME,
            "host: a loopback address (127.0.0.1 or ::1)",
            &host.to_string(),
        ));
    }
    if crate::safety::current_mode() != crate::safety::Mode::Agent {
        return Err(crate::safety::policy_deny(
            NAME,
            "remote evaluation needs agent mode, so a peer cannot run code with human-mode permissions",
            "set AETHER_MODE=agent, then serve again",
        ));
    }
    let addr = std::net::SocketAddr::new(host, port as u16);
    guard_network(NAME, &format!("tcp://{addr}"))?;
    if let Some(running) = slot.as_ref() {
        return Err(crate::safety::bad_state(
            NAME,
            &format!("already serving on {}", running.addr),
            "repl_serve({stop: true})",
        ));
    }

    let listener = std::net::TcpListener::bind(addr).map_err(|e| nc_io_error(NAME, e))?;
    let bound = listener.local_addr().map_err(|e| nc_io_error(NAME, e))?;
    listener
        .set_nonblocking(true)
        .map_err(|e| nc_io_error(NAME, e))?;
    // Two v4 UUIDs: 244 random bits, hex-encoded.
    let token = format!(
        "{}{}",
        uuid::Uuid::new_v4().simple(),
        uuid::Uuid::new_v4().simple()
    );
    let stop_flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let (thread_token, thread_stop) = (token.clone(), stop_flag.clone());
    std::thread::Builder::new()
        .name("repl-serve".to_string())
        .spawn(move || repl_accept_loop(listener, thread_token, thread_stop))
        .map_err(|e| nc_io_error(NAME, e))?;

    let mut rec = BTreeMap::new();
    rec.insert("address".to_string(), Value::Str(bound.to_string()));
    rec.insert("port".to_string(), Value::Int(i64::from(bound.port())));
    rec.insert("token".to_string(), Value::Str(token.clone()));
    rec.insert("status".to_string(), Value::Str("listening".to_string()));
    *slot = Some(ReplServer {
        addr: bound,
        token,
        stop: stop_flag,
    });
    Ok(Value::Record(rec))
}

/// repl_connect(target, options) - Send one request to a repl_serve listener and
/// return its value. `target` is a `tcp://ip:port` String or a `{host, port}`
/// Record with a literal IP. `options` is `{token, code}`. A refused token raises
/// E_POLICY_DENY; any other failure from the remote side is returned as
/// {ok: false, error}.
fn bi_repl_connect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "repl_connect";
    refuse_piped_subject(NAME, &input)?;
    let (target, options) = match <[Value; 2]>::try_from(args) {
        Ok([target, options]) => (target, options),
        Err(_) => {
            return Err(crate::safety::bad_arg(
                NAME,
                "a target and an options Record {token, code}",
                "a different number of arguments",
            ))
        }
    };
    let target_hint = "target: a tcp://ip:port String or {host, port} Record";
    let addr: std::net::SocketAddr = match &target {
        Value::Str(text) => text
            .strip_prefix("tcp://")
            .unwrap_or(text.as_str())
            .parse::<std::net::SocketAddr>()
            .map_err(|_| crate::safety::bad_arg(NAME, target_hint, text))?,
        Value::Record(fields) => {
            let host = match fields.get("host") {
                Some(Value::Str(h)) => h
                    .parse::<std::net::IpAddr>()
                    .map_err(|_| crate::safety::bad_arg(NAME, "host: a literal IP address", h))?,
                _ => {
                    return Err(crate::safety::bad_arg(
                        NAME,
                        target_hint,
                        "a Record without a String host",
                    ))
                }
            };
            let port = match fields.get("port") {
                Some(Value::Int(n)) if (1..=65535i64).contains(n) => *n as u16,
                _ => {
                    return Err(crate::safety::bad_arg(
                        NAME,
                        "port: Int 1..65535",
                        "a missing or out-of-range port",
                    ))
                }
            };
            std::net::SocketAddr::new(host, port)
        }
        other => return Err(crate::safety::bad_arg(NAME, target_hint, other.type_name())),
    };
    let fields = match &options {
        Value::Record(fields) => fields,
        other => {
            return Err(crate::safety::bad_arg(
                NAME,
                "options: Record {token, code}",
                other.type_name(),
            ))
        }
    };
    let token = match fields.get("token") {
        Some(Value::Str(t)) if !t.is_empty() => t.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                NAME,
                "options.token: a non-empty String",
                "a missing or non-String token",
            ))
        }
    };
    let code = match fields.get("code") {
        Some(Value::Str(c)) => c.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                NAME,
                "options.code: a String",
                "a missing or non-String code",
            ))
        }
    };
    let line = format!("{}\n", serde_json::json!({"token": token, "code": code}));
    if line.len() > REPL_MAX_LINE {
        return Err(crate::safety::bad_arg(
            NAME,
            "code that fits one 1 MiB request line",
            "a longer String",
        ));
    }
    if crate::tx::is_active() {
        return Err(crate::safety::unimplemented(
            NAME,
            "network effects cannot be rolled back",
            "finish the transaction first",
        ));
    }
    guard_network(NAME, &format!("tcp://{addr}"))?;

    let mut stream = std::net::TcpStream::connect_timeout(&addr, REPL_IO_TIMEOUT)
        .map_err(|e| nc_io_error(NAME, e))?;
    stream
        .set_read_timeout(Some(REPL_EVAL_LIMIT + REPL_IO_TIMEOUT))
        .map_err(|e| nc_io_error(NAME, e))?;
    stream
        .set_write_timeout(Some(REPL_IO_TIMEOUT))
        .map_err(|e| nc_io_error(NAME, e))?;
    std::io::Write::write_all(&mut stream, line.as_bytes()).map_err(|e| nc_io_error(NAME, e))?;
    let read_side = stream.try_clone().map_err(|e| nc_io_error(NAME, e))?;
    let mut reader = std::io::BufReader::new(read_side);
    let reply_line = repl_read_line(&mut reader, REPL_MAX_LINE)
        .map_err(|reason| repl_io_error(NAME, &reason))?
        .ok_or_else(|| repl_io_error(NAME, "the listener closed without a reply"))?;
    let reply: serde_json::Value = serde_json::from_slice(&reply_line)
        .map_err(|e| repl_io_error(NAME, &format!("reply is not JSON: {e}")))?;

    let mut rec = BTreeMap::new();
    rec.insert("address".to_string(), Value::Str(addr.to_string()));
    if reply.get("ok").and_then(|v| v.as_bool()) == Some(true) {
        let value = json_to_value(
            reply
                .get("value")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
        );
        let type_name = reply
            .get("type")
            .and_then(|v| v.as_str())
            .unwrap_or("Unknown")
            .to_string();
        rec.insert("ok".to_string(), Value::Bool(true));
        rec.insert("value".to_string(), value);
        rec.insert("type".to_string(), Value::Str(type_name));
        return Ok(Value::Record(rec));
    }
    let reason = reply
        .get("error")
        .and_then(|v| v.as_str())
        .unwrap_or("request refused")
        .to_string();
    if reason == "unauthorized" {
        return Err(crate::safety::policy_deny(
            NAME,
            "the listener refused the token",
            "present the token that repl_serve returned",
        ));
    }
    rec.insert("ok".to_string(), Value::Bool(false));
    rec.insert("error".to_string(), Value::Str(reason));
    Ok(Value::Record(rec))
}

/// repl_disconnect(session_id) - Remove a session from the session table.
fn bi_repl_disconnect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("repl_disconnect", &input)?;
    let id = collab_text_arg("repl_disconnect", "session_id", args.first(), 128)?;
    let mut sessions = REPL_SESSIONS
        .write()
        .map_err(|_| crate::safety::lock_poisoned("repl_disconnect", "the REPL session table"))?;
    let session = sessions
        .remove(&id)
        .ok_or_else(|| crate::safety::not_found("repl_disconnect", "repl session", &id))?;
    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(session.id));
    rec.insert("status".to_string(), Value::Str("disconnected".to_string()));
    rec.insert(
        "disconnected_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// repl_broadcast(expression) - Refused: there is no peer set to send to.
fn bi_repl_broadcast(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("repl_broadcast", &input)?;
    collab_text_arg("repl_broadcast", "expression", args.first(), 4096)?;
    Err(crate::safety::unimplemented(
        "repl_broadcast",
        "nothing is sent: repl_connect holds no session open, so there is no peer set to broadcast to",
        "call repl_connect once per peer",
    ))
}

#[cfg(test)]
mod repl_protocol_tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn request_line_yields_token_and_code() {
        let parsed = repl_parse_request(br#"{"token":"t1","code":"1 + 1"}"#).expect("parses");
        assert_eq!(
            parsed,
            ReplRequest {
                token: "t1".into(),
                code: "1 + 1".into(),
            }
        );
        // A CRLF peer is tolerated.
        let crlf = repl_parse_request(b"{\"token\":\"t\",\"code\":\"2\"}\r").expect("parses");
        assert_eq!(crlf.code, "2");
    }

    #[test]
    fn malformed_request_lines_are_refused_with_a_reason() {
        let cases: [(&[u8], &str); 6] = [
            (b"not json", "not JSON"),
            (b"[1,2]", "JSON object"),
            (br#"{"code":"1"}"#, "token"),
            (br#"{"token":"t"}"#, "code"),
            (br#"{"token":5,"code":"1"}"#, "token"),
            (&[0xffu8, 0xfeu8], "UTF-8"),
        ];
        for (line, why) in cases {
            let reason = repl_parse_request(line).expect_err("refused");
            assert!(reason.contains(why), "{reason} should mention {why}");
        }
    }

    #[test]
    fn token_check_requires_an_exact_match() {
        assert!(repl_token_matches("abcd", "abcd"));
        assert!(!repl_token_matches("abcd", "abce"));
        assert!(!repl_token_matches("abcd", "abc"));
        assert!(!repl_token_matches("abcd", "abcde"));
        assert!(!repl_token_matches("abcd", ""));
    }

    #[test]
    fn lines_are_split_on_newline_then_eof() {
        let mut reader = Cursor::new(b"one\ntwo\n".to_vec());
        assert_eq!(repl_read_line(&mut reader, 16), Ok(Some(b"one".to_vec())));
        assert_eq!(repl_read_line(&mut reader, 16), Ok(Some(b"two".to_vec())));
        assert_eq!(repl_read_line(&mut reader, 16), Ok(None));
    }

    #[test]
    fn a_line_over_the_cap_is_refused_and_one_at_the_cap_is_kept() {
        let mut over = vec![b'x'; 5000];
        over.push(b'\n');
        let mut reader = Cursor::new(over);
        assert!(repl_read_line(&mut reader, 1000).is_err());

        let mut exact = vec![b'x'; 1000];
        exact.push(b'\n');
        let mut reader = Cursor::new(exact);
        assert_eq!(
            repl_read_line(&mut reader, 1000).map(|l| l.map(|v| v.len())),
            Ok(Some(1000))
        );
    }

    #[test]
    fn eof_mid_line_is_an_error_not_a_request() {
        let mut reader = Cursor::new(b"partial".to_vec());
        assert!(repl_read_line(&mut reader, 100).is_err());
    }
}

// ===================== Team Workspace Builtins =====================
//
// A workspace is a membership list and a list of shared agent names, held in
// process memory. Membership is keyed by the USER or USERNAME environment
// variable, which the caller sets, so it names whoever set it and is not an
// access control. Nothing leaves the process: workspace_sync refuses.

/// Most workspaces one process holds.
const WORKSPACE_MAX: usize = 256;
/// Most members one workspace holds.
const WORKSPACE_MAX_MEMBERS: usize = 64;
/// Most agent names one workspace shares.
const WORKSPACE_MAX_AGENTS: usize = 64;

/// workspace_create(name, options?) - Create a workspace owned by the caller.
/// The only option is `description` (a String of at most 1024 bytes).
fn bi_workspace_create(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_create", &input)?;
    let name = collab_text_arg("workspace_create", "name", args.first(), 128)?;
    let mut description = String::new();
    match args.get(1) {
        None => {}
        Some(Value::Record(opts)) => {
            if let Some(key) = opts.keys().find(|k| k.as_str() != "description") {
                return Err(crate::safety::bad_arg(
                    "workspace_create",
                    "options: {description?: String}",
                    &format!("unknown option `{key}`"),
                ));
            }
            match opts.get("description") {
                None => {}
                Some(Value::Str(s)) if s.len() <= 1024 => description = s.clone(),
                Some(other) => {
                    return Err(crate::safety::bad_arg(
                        "workspace_create",
                        "description: a String of at most 1024 bytes",
                        &collab_got(other),
                    ))
                }
            }
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "workspace_create",
                "options: Record",
                other.type_name(),
            ))
        }
    }

    let id = uuid::Uuid::new_v4().to_string();
    let owner = get_current_username("workspace_create")?;
    let created_at = chrono::Local::now().to_rfc3339();
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("workspace_create", "the workspace registry"))?;
    if workspaces.len() >= WORKSPACE_MAX {
        return Err(crate::safety::budget_exceeded(
            "workspace_create",
            format!("workspace_create: {WORKSPACE_MAX} workspaces already exist in this process"),
            "a process holds a bounded number of workspaces; start another process for more",
        ));
    }
    workspaces.insert(
        id.clone(),
        TeamWorkspace {
            id: id.clone(),
            name: name.clone(),
            owner: owner.clone(),
            members: vec![WorkspaceMember {
                user: owner.clone(),
                role: "owner".to_string(),
                joined_at: created_at.clone(),
            }],
            shared_agents: Vec::new(),
            created_at: created_at.clone(),
            description: description.clone(),
        },
    );

    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(id));
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("owner".to_string(), Value::Str(owner));
    rec.insert("description".to_string(), Value::Str(description));
    rec.insert("member_count".to_string(), Value::Int(1));
    rec.insert("created_at".to_string(), Value::Str(created_at));
    Ok(Value::Record(rec))
}

/// workspace_join(workspace_id) - Add the caller to a workspace.
fn bi_workspace_join(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_join", &input)?;
    let ws_id = collab_text_arg("workspace_join", "workspace_id", args.first(), 64)?;
    let user = get_current_username("workspace_join")?;
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("workspace_join", "the workspace registry"))?;
    let ws = workspaces
        .get_mut(&ws_id)
        .ok_or_else(|| crate::safety::not_found("workspace_join", "workspace", &ws_id))?;
    if ws.members.iter().any(|m| m.user == user) {
        return Err(crate::safety::bad_state(
            "workspace_join",
            &format!("already a member of '{}'", ws.name),
            "workspace_members",
        ));
    }
    if ws.members.len() >= WORKSPACE_MAX_MEMBERS {
        return Err(crate::safety::budget_exceeded(
            "workspace_join",
            format!(
                "workspace_join: '{}' already has {WORKSPACE_MAX_MEMBERS} members",
                ws.name
            ),
            "a workspace holds a bounded number of members",
        ));
    }
    ws.members.push(WorkspaceMember {
        user: user.clone(),
        role: "member".to_string(),
        joined_at: chrono::Local::now().to_rfc3339(),
    });
    let mut rec = BTreeMap::new();
    rec.insert("workspace_id".to_string(), Value::Str(ws_id));
    rec.insert("workspace_name".to_string(), Value::Str(ws.name.clone()));
    rec.insert("user".to_string(), Value::Str(user));
    rec.insert("role".to_string(), Value::Str("member".to_string()));
    rec.insert("status".to_string(), Value::Str("joined".to_string()));
    Ok(Value::Record(rec))
}

/// workspace_leave(workspace_id) - Remove the caller from a workspace. The
/// owner cannot leave: ownership cannot be transferred yet.
fn bi_workspace_leave(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_leave", &input)?;
    let ws_id = collab_text_arg("workspace_leave", "workspace_id", args.first(), 64)?;
    let user = get_current_username("workspace_leave")?;
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|_| crate::safety::lock_poisoned("workspace_leave", "the workspace registry"))?;
    let ws = workspaces
        .get_mut(&ws_id)
        .ok_or_else(|| crate::safety::not_found("workspace_leave", "workspace", &ws_id))?;
    if ws.owner == user {
        return Err(crate::safety::policy_deny(
            "workspace_leave",
            format!("the owner of '{}' cannot leave it", ws.name),
            "ownership cannot be transferred yet, so the owner stays",
        ));
    }
    let before = ws.members.len();
    ws.members.retain(|m| m.user != user);
    if ws.members.len() == before {
        return Err(crate::safety::bad_state(
            "workspace_leave",
            &format!("not a member of '{}'", ws.name),
            "workspace_members",
        ));
    }
    let mut rec = BTreeMap::new();
    rec.insert("workspace_id".to_string(), Value::Str(ws_id));
    rec.insert("workspace_name".to_string(), Value::Str(ws.name.clone()));
    rec.insert("user".to_string(), Value::Str(user));
    rec.insert("status".to_string(), Value::Str("left".to_string()));
    Ok(Value::Record(rec))
}

/// workspace_members(workspace_id) - The members of a workspace.
fn bi_workspace_members(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_members", &input)?;
    let ws_id = collab_text_arg("workspace_members", "workspace_id", args.first(), 64)?;
    let workspaces = WORKSPACES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("workspace_members", "the workspace registry"))?;
    let ws = workspaces
        .get(&ws_id)
        .ok_or_else(|| crate::safety::not_found("workspace_members", "workspace", &ws_id))?;
    let members: Vec<Value> = ws
        .members
        .iter()
        .map(|m| {
            let mut rec = BTreeMap::new();
            rec.insert("user".to_string(), Value::Str(m.user.clone()));
            rec.insert("role".to_string(), Value::Str(m.role.clone()));
            rec.insert("joined_at".to_string(), Value::Str(m.joined_at.clone()));
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(members))
}

/// workspace_share_agent(workspace_id, agent) - Share a registered agent (see
/// a2a_register) into a workspace the caller belongs to.
fn bi_workspace_share_agent(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_share_agent", &input)?;
    let ws_id = collab_text_arg("workspace_share_agent", "workspace_id", args.first(), 64)?;
    let agent = collab_text_arg("workspace_share_agent", "agent", args.get(1), 128)?;
    let user = get_current_username("workspace_share_agent")?;
    let mut workspaces = WORKSPACES.write().map_err(|_| {
        crate::safety::lock_poisoned("workspace_share_agent", "the workspace registry")
    })?;
    let ws = workspaces
        .get_mut(&ws_id)
        .ok_or_else(|| crate::safety::not_found("workspace_share_agent", "workspace", &ws_id))?;
    if !ws.members.iter().any(|m| m.user == user) {
        return Err(crate::safety::policy_deny(
            "workspace_share_agent",
            format!("{user} is not a member of '{}'", ws.name),
            "join the workspace before sharing an agent into it",
        ));
    }
    let registered = A2A_REGISTRY
        .read()
        .map_err(|_| {
            crate::safety::lock_poisoned("workspace_share_agent", "the A2A agent registry")
        })?
        .contains_key(&agent);
    if !registered {
        return Err(crate::safety::not_found(
            "workspace_share_agent",
            "agent",
            &agent,
        ));
    }
    if ws.shared_agents.contains(&agent) {
        return Err(crate::safety::bad_state(
            "workspace_share_agent",
            &format!("'{agent}' is already shared in '{}'", ws.name),
            "workspace_agents",
        ));
    }
    if ws.shared_agents.len() >= WORKSPACE_MAX_AGENTS {
        return Err(crate::safety::budget_exceeded(
            "workspace_share_agent",
            format!(
                "workspace_share_agent: '{}' already shares {WORKSPACE_MAX_AGENTS} agents",
                ws.name
            ),
            "a workspace shares a bounded number of agents",
        ));
    }
    ws.shared_agents.push(agent.clone());
    let mut rec = BTreeMap::new();
    rec.insert("workspace_id".to_string(), Value::Str(ws_id));
    rec.insert("agent".to_string(), Value::Str(agent));
    rec.insert("status".to_string(), Value::Str("shared".to_string()));
    rec.insert(
        "total_agents".to_string(),
        Value::Int(ws.shared_agents.len() as i64),
    );
    Ok(Value::Record(rec))
}

/// workspace_agents(workspace_id) - The agent names shared in a workspace.
fn bi_workspace_agents(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_agents", &input)?;
    let ws_id = collab_text_arg("workspace_agents", "workspace_id", args.first(), 64)?;
    let workspaces = WORKSPACES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("workspace_agents", "the workspace registry"))?;
    let ws = workspaces
        .get(&ws_id)
        .ok_or_else(|| crate::safety::not_found("workspace_agents", "workspace", &ws_id))?;
    Ok(Value::Array(
        ws.shared_agents
            .iter()
            .map(|a| Value::Str(a.clone()))
            .collect(),
    ))
}

/// workspace_sync(workspace_id) - Refused: there are no peers to sync with.
fn bi_workspace_sync(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped_subject("workspace_sync", &input)?;
    let ws_id = collab_text_arg("workspace_sync", "workspace_id", args.first(), 64)?;
    let workspaces = WORKSPACES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("workspace_sync", "the workspace registry"))?;
    if !workspaces.contains_key(&ws_id) {
        return Err(crate::safety::not_found(
            "workspace_sync",
            "workspace",
            &ws_id,
        ));
    }
    Err(crate::safety::unimplemented(
        "workspace_sync",
        "there are no remote peers, so nothing is synced; this workspace is local to this process",
        "workspace_members and workspace_agents report its local state",
    ))
}

/// List active REPL sessions.
/// Usage: repl.sessions()
fn bi_repl_sessions(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let sessions = REPL_SESSIONS
        .read()
        .map_err(|_| crate::safety::lock_poisoned("repl_sessions", "the REPL session table"))?;
    let entries: Vec<Value> = sessions
        .values()
        .map(|s| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(s.id.clone()));
            rec.insert("host".to_string(), Value::Str(s.host.clone()));
            rec.insert("port".to_string(), Value::Int(s.port as i64));
            rec.insert("user".to_string(), Value::Str(s.user.clone()));
            rec.insert("status".to_string(), Value::Str(s.status.clone()));
            rec.insert(
                "connected_at".to_string(),
                Value::Str(s.connected_at.clone()),
            );
            if let Some(ref ws) = s.workspace_id {
                rec.insert("workspace_id".to_string(), Value::Str(ws.clone()));
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// List all workspaces the current user belongs to.
/// Usage: workspace.list()
fn bi_workspace_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let workspaces = WORKSPACES
        .read()
        .map_err(|_| crate::safety::lock_poisoned("workspace_list", "the workspace registry"))?;
    let user = get_current_username("workspace_list")?;
    let entries: Vec<Value> = workspaces
        .values()
        .filter(|ws| ws.members.iter().any(|m| m.user == user))
        .map(|ws| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(ws.id.clone()));
            rec.insert("name".to_string(), Value::Str(ws.name.clone()));
            rec.insert("owner".to_string(), Value::Str(ws.owner.clone()));
            rec.insert(
                "description".to_string(),
                Value::Str(ws.description.clone()),
            );
            rec.insert(
                "member_count".to_string(),
                Value::Int(ws.members.len() as i64),
            );
            rec.insert(
                "agent_count".to_string(),
                Value::Int(ws.shared_agents.len() as i64),
            );
            rec.insert("created_at".to_string(), Value::Str(ws.created_at.clone()));
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ===================== Marketplace Builtins =====================

const MARKETPLACE_REGISTRY: &str = "https://packages.nervosys.ai";

/// A package name or version. Both are written into cache paths and registry
/// URLs, so anything that could leave the cache directory or read as an option
/// (a `/`, a `..`, a leading `-`) is refused here, before any request.
fn package_token(builtin: &str, what: &str, s: &str) -> Result<String> {
    let ok = !s.is_empty()
        && s.len() <= 128
        && !s.starts_with(['-', '.'])
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-' | '+'));
    if ok {
        Ok(s.to_string())
    } else {
        Err(crate::safety::bad_arg(
            builtin,
            &format!(
                "{what}: 1 to 128 letters, digits, '.', '_', '-' or '+', not starting with '-' or '.'"
            ),
            &format!("{s:?}"),
        ))
    }
}

/// A string argument, refused with the expected shape when it is not one.
fn str_arg<'a>(builtin: &str, v: Option<&'a Value>, what: &str) -> Result<&'a str> {
    match v {
        Some(Value::Str(s)) => Ok(s.as_str()),
        other => Err(crate::safety::bad_arg(
            builtin,
            what,
            other.map_or("nothing", Value::type_name),
        )),
    }
}

/// A registry request that did not complete. Nothing local has changed when
/// this is returned, so the call can be repeated as it stands.
fn registry_failure(builtin: &str, e: &anyhow::Error) -> anyhow::Error {
    crate::safety::policy_deny(
        builtin,
        format!("{builtin}: the package registry did not complete the request: {e:#}"),
        "the registry refused the request or could not be reached; check the network and AETHER_REGISTRY_TOKEN, then retry",
    )
}

/// Whether a registry error says the package does not exist, as opposed to
/// the registry being unreachable or refusing the request.
fn registry_says_absent(e: &anyhow::Error) -> bool {
    e.to_string().contains("not found in registry")
}

/// Mark a record with where it came from, so a caller never mistakes a local
/// catalogue entry for the registry's answer.
fn with_source(mut v: Value, source: &str) -> Value {
    if let Value::Record(r) = &mut v {
        r.insert("source".to_string(), Value::Str(source.to_string()));
    }
    v
}

/// Publish a plugin or agent to the marketplace.
/// With `path`, uploads that file to packages.nervosys.ai (network-guarded,
/// inside the workspace, and needs AETHER_REGISTRY_TOKEN); the status is then
/// `published`. Without `path` the package is recorded in the local catalogue
/// only, and the status says so: `recorded_locally`.
/// Usage: marketplace.publish({name, version, description?, category?, keywords?, path?})
fn bi_marketplace_publish(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const FIELDS: &[&str] = &[
        "name",
        "version",
        "description",
        "category",
        "keywords",
        "path",
    ];
    const MAX_KEYWORDS: usize = 32;
    let opts = match args.first() {
        Some(Value::Record(r)) => r.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.publish requires a Record with name, version, description",
            ))
        }
    };
    if let Some(bad) = opts.keys().find(|k| !FIELDS.contains(&k.as_str())) {
        return Err(crate::safety::bad_arg(
            "marketplace_publish",
            "a record with only the fields name, version, description, category, keywords and path",
            &format!("field {bad:?}"),
        ));
    }
    // A field of the wrong type used to fall back to its default, so a number
    // given as a description was published with an empty one.
    let text = |key: &str| -> Result<Option<String>> {
        match opts.get(key) {
            None => Ok(None),
            Some(Value::Str(s)) => Ok(Some(s.clone())),
            Some(other) => Err(crate::safety::bad_arg(
                "marketplace_publish",
                &format!("{key}: a string"),
                other.type_name(),
            )),
        }
    };
    let name = package_token(
        "marketplace_publish",
        "name",
        &text("name")?
            .ok_or_else(|| crate::safety::arg_err("marketplace.publish requires 'name'"))?,
    )?;
    let version = package_token(
        "marketplace_publish",
        "version",
        &text("version")?
            .ok_or_else(|| crate::safety::arg_err("marketplace.publish requires 'version'"))?,
    )?;
    let description = text("description")?.unwrap_or_default();
    if description.len() > 4096 || description.chars().any(char::is_control) {
        return Err(crate::safety::bad_arg(
            "marketplace_publish",
            "description: at most 4096 bytes with no control characters",
            "a description that does not fit",
        ));
    }
    let category = text("category")?.unwrap_or_else(|| "general".to_string());
    let keywords: Vec<String> = match opts.get("keywords") {
        None => Vec::new(),
        Some(Value::Array(arr)) if arr.len() <= MAX_KEYWORDS => arr
            .iter()
            .map(|v| match v {
                Value::Str(s) => Ok(s.clone()),
                other => Err(crate::safety::bad_arg(
                    "marketplace_publish",
                    "keywords: an array of strings",
                    other.type_name(),
                )),
            })
            .collect::<Result<Vec<_>>>()?,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "marketplace_publish",
                &format!("keywords: an array of at most {MAX_KEYWORDS} strings"),
                other.type_name(),
            ))
        }
    };
    let path = match text("path")? {
        None => None,
        Some(p) => {
            // The file is read and sent to a server, so only a file the
            // workspace already holds may be published.
            if !crate::safety::within_workspace(&p) {
                return Err(crate::safety::outside_workspace("marketplace_publish", &p));
            }
            let meta = std::fs::metadata(&p)
                .map_err(|e| crate::safety::fs_error("marketplace_publish", &p, &e))?;
            if !meta.is_file() {
                return Err(crate::safety::bad_arg(
                    "marketplace_publish",
                    "path: a file to upload",
                    &format!("{p:?}"),
                ));
            }
            Some(std::path::PathBuf::from(p))
        }
    };

    // Egress is decided at dispatch: `Network` is centrally enforced, so the
    // upload is metered and gated before this body runs.
    // Resolved before the upload, so a missing user cannot leave a published
    // package without an author.
    let user = get_current_username("marketplace_publish")?;
    let target = match &path {
        Some(tarball) => {
            let manifest = crate::packages::PackageManifest {
                package: crate::packages::PackageInfo {
                    name: name.clone(),
                    version: version.clone(),
                    description: description.clone(),
                    authors: vec![user.clone()],
                    license: None,
                    repository: None,
                    main: "main.ae".to_string(),
                },
                dependencies: std::collections::HashMap::new(),
            };
            crate::packages::RegistryClient::default()
                .publish(tarball, &manifest)
                .map_err(|e| registry_failure("marketplace_publish", &e))?;
            "registry"
        }
        None => "local",
    };

    let published_at = chrono::Local::now().to_rfc3339();
    let package = MarketplacePackage {
        name: name.clone(),
        version: version.clone(),
        author: user,
        description: description.clone(),
        category: category.clone(),
        downloads: 0,
        rating: 0.0,
        rating_count: 0,
        published_at: published_at.clone(),
        installed: false,
        keywords,
    };
    MARKETPLACE_PACKAGES
        .write()
        .map_err(|_| {
            crate::safety::lock_poisoned("marketplace_publish", "the marketplace package cache")
        })?
        .insert(name.clone(), package);

    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("version".to_string(), Value::Str(version));
    rec.insert("description".to_string(), Value::Str(description));
    rec.insert("category".to_string(), Value::Str(category));
    rec.insert(
        "status".to_string(),
        Value::Str(
            if target == "registry" {
                "published"
            } else {
                "recorded_locally"
            }
            .to_string(),
        ),
    );
    rec.insert("target".to_string(), Value::Str(target.to_string()));
    rec.insert("published_at".to_string(), Value::Str(published_at));
    Ok(Value::Record(rec))
}

/// Search the marketplace for packages.
/// Searches the remote registry at packages.nervosys.ai, falls back to local cache.
/// Each record says whether it came from the `registry` or the `local_cache`. If
/// the registry could not be reached and the local cache has nothing to offer,
/// that is an error, not an empty list.
/// Usage: marketplace.search(query) or marketplace.search({q?, category?})
fn bi_marketplace_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    fn query_text(builtin: &str, s: &str) -> Result<String> {
        if s.len() > 256 || s.chars().any(char::is_control) {
            return Err(crate::safety::bad_arg(
                builtin,
                "a query of at most 256 bytes with no control characters",
                &format!("{:?}", s.chars().take(40).collect::<String>()),
            ));
        }
        Ok(s.to_lowercase())
    }
    let (query, category) = match args.first() {
        None => (String::new(), None),
        Some(Value::Str(s)) => (query_text("marketplace_search", s)?, None),
        Some(Value::Record(r)) => {
            if let Some(bad) = r
                .keys()
                .find(|k| !matches!(k.as_str(), "q" | "query" | "category"))
            {
                return Err(crate::safety::bad_arg(
                    "marketplace_search",
                    "a record with only the fields q, query and category",
                    &format!("field {bad:?}"),
                ));
            }
            let q = match r.get("q").or_else(|| r.get("query")) {
                None => String::new(),
                Some(Value::Str(s)) => query_text("marketplace_search", s)?,
                Some(other) => {
                    return Err(crate::safety::bad_arg(
                        "marketplace_search",
                        "q: a string",
                        other.type_name(),
                    ))
                }
            };
            let cat = match r.get("category") {
                None => None,
                Some(Value::Str(s)) => Some(s.clone()),
                Some(other) => {
                    return Err(crate::safety::bad_arg(
                        "marketplace_search",
                        "category: a string",
                        other.type_name(),
                    ))
                }
            };
            (q, cat)
        }
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "marketplace_search",
                "a query string or a Record {q?, category?}",
                other.type_name(),
            ))
        }
    };

    guard_network("marketplace_search", MARKETPLACE_REGISTRY)?;

    let client = crate::packages::RegistryClient::default();
    let registry_error = match client.search(&query, category.as_deref()) {
        Ok(remote_pkgs) if !remote_pkgs.is_empty() => {
            let results: Vec<Value> = remote_pkgs
                .iter()
                .map(|p| {
                    with_source(
                        crate::packages::RegistryClient::package_to_value(p),
                        "registry",
                    )
                })
                .collect();
            return Ok(Value::Array(results));
        }
        Ok(_) => None,
        Err(e) => Some(e),
    };

    // Fall back to local cache
    let packages = MARKETPLACE_PACKAGES.read().map_err(|_| {
        crate::safety::lock_poisoned("marketplace_search", "the marketplace package cache")
    })?;
    let results: Vec<Value> = packages
        .values()
        .filter(|pkg| {
            let matches_query = query.is_empty()
                || pkg.name.to_lowercase().contains(&query)
                || pkg.description.to_lowercase().contains(&query)
                || pkg
                    .keywords
                    .iter()
                    .any(|k| k.to_lowercase().contains(&query));
            let matches_category = category
                .as_ref()
                .map(|c| pkg.category.to_lowercase() == c.to_lowercase())
                .unwrap_or(true);
            matches_query && matches_category
        })
        .map(marketplace_package_to_value)
        .collect();

    if let (true, Some(e)) = (results.is_empty(), registry_error.as_ref()) {
        return Err(registry_failure("marketplace_search", e));
    }
    Ok(Value::Array(results))
}

fn marketplace_package_to_value(pkg: &MarketplacePackage) -> Value {
    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
    rec.insert("version".to_string(), Value::Str(pkg.version.clone()));
    rec.insert("author".to_string(), Value::Str(pkg.author.clone()));
    rec.insert(
        "description".to_string(),
        Value::Str(pkg.description.clone()),
    );
    rec.insert("category".to_string(), Value::Str(pkg.category.clone()));
    rec.insert("downloads".to_string(), Value::Int(pkg.downloads));
    rec.insert("rating".to_string(), Value::Float(pkg.rating));
    rec.insert("rating_count".to_string(), Value::Int(pkg.rating_count));
    rec.insert(
        "published_at".to_string(),
        Value::Str(pkg.published_at.clone()),
    );
    rec.insert("installed".to_string(), Value::Bool(pkg.installed));
    rec.insert("source".to_string(), Value::Str("local_cache".to_string()));
    if !pkg.keywords.is_empty() {
        rec.insert(
            "keywords".to_string(),
            Value::Array(pkg.keywords.iter().map(|k| Value::Str(k.clone())).collect()),
        );
    }
    Value::Record(rec)
}

/// Install a package from the marketplace: download the registry's archive
/// into the package cache and unpack it. Nothing is run; extraction is the
/// whole of it. A package the registry does not hold is an error. There is no
/// local fallback, because the local catalogue holds records, not archives.
/// Usage: marketplace.install(name) or marketplace.install(name, version)
fn bi_marketplace_install(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = package_token(
        "marketplace_install",
        "name",
        str_arg("marketplace_install", args.first(), "a package name string")?,
    )?;
    let version = match args.get(1) {
        None => None,
        Some(v) => Some(package_token(
            "marketplace_install",
            "version",
            str_arg("marketplace_install", Some(v), "a version string")?,
        )?),
    };

    // Not metered against AETHER_MAX_NET: this builtin is gated as `Exec` at
    // dispatch, and calling `guard_network` here would need it listed as
    // self-guarding, which skips that approval. See the report.
    let client = crate::packages::RegistryClient::default();
    let pkg_info = match client.get_package(&name) {
        Ok(p) => p,
        Err(e) if registry_says_absent(&e) => {
            return Err(crate::safety::not_found(
                "marketplace_install",
                "package",
                &name,
            ))
        }
        Err(e) => return Err(registry_failure("marketplace_install", &e)),
    };
    // The registry's own version string names a directory, so it is checked
    // like any other name before it is used.
    let ver = match version {
        Some(v) => v,
        None => package_token("marketplace_install", "version", &pkg_info.version)?,
    };
    let install_path = client
        .download_package(&name, &ver)
        .map_err(|e| registry_failure("marketplace_install", &e))?;

    // Update the local catalogue. A poisoned lock used to skip this and still
    // report "installed"; the download is on disk, so the error names it.
    {
        let mut packages = MARKETPLACE_PACKAGES.write().map_err(|_| {
            anyhow!(
                "marketplace_install: `{}` was downloaded, but the package catalogue lock is poisoned, so it was not recorded",
                install_path.display()
            )
        })?;
        let existing = packages
            .entry(name.clone())
            .or_insert_with(|| MarketplacePackage {
                name: name.clone(),
                version: ver.clone(),
                author: pkg_info.author.clone(),
                description: pkg_info.description.clone(),
                category: pkg_info
                    .category
                    .clone()
                    .unwrap_or_else(|| "general".to_string()),
                downloads: pkg_info.downloads,
                rating: 0.0,
                rating_count: 0,
                published_at: pkg_info.created_at.clone(),
                installed: false,
                keywords: pkg_info.keywords.clone(),
            });
        existing.installed = true;
        existing.downloads += 1;
    }
    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("version".to_string(), Value::Str(ver));
    rec.insert("status".to_string(), Value::Str("installed".to_string()));
    rec.insert("source".to_string(), Value::Str("registry".to_string()));
    rec.insert(
        "path".to_string(),
        Value::Str(install_path.display().to_string()),
    );
    rec.insert(
        "installed_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// Uninstall a marketplace package: remove its cached archive and unpacked
/// files, and clear the installed flag. Reports whether any files were there.
/// Usage: marketplace.uninstall(name)
fn bi_marketplace_uninstall(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = package_token(
        "marketplace_uninstall",
        "name",
        str_arg(
            "marketplace_uninstall",
            args.first(),
            "a package name string",
        )?,
    )?;
    let mut packages = MARKETPLACE_PACKAGES.write().map_err(|_| {
        crate::safety::lock_poisoned("marketplace_uninstall", "the marketplace package cache")
    })?;
    let Some(pkg) = packages.get_mut(&name) else {
        return Err(crate::safety::not_found(
            "marketplace_uninstall",
            "package",
            &name,
        ));
    };
    if !pkg.installed {
        return Err(crate::safety::bad_state(
            "marketplace_uninstall",
            &format!("package '{name}' is not installed, so there is nothing to remove"),
            "marketplace_install",
        ));
    }
    // The install wrote into the package's own cache directory. The name has
    // been checked to be a single path segment, so this cannot reach beyond it.
    let dir = crate::packages::RegistryClient::default()
        .cache_dir
        .join(&name);
    let files_removed = if dir.exists() {
        std::fs::remove_dir_all(&dir)
            .map_err(|e| crate::safety::fs_error("marketplace_uninstall", &dir, &e))?;
        true
    } else {
        false
    };
    pkg.installed = false;

    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
    rec.insert("status".to_string(), Value::Str("uninstalled".to_string()));
    rec.insert("files_removed".to_string(), Value::Bool(files_removed));
    rec.insert(
        "uninstalled_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// List installed marketplace packages.
/// Usage: marketplace.list()
fn bi_marketplace_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let packages = MARKETPLACE_PACKAGES.read().map_err(|_| {
        crate::safety::lock_poisoned("marketplace_list", "the marketplace package cache")
    })?;
    let installed: Vec<Value> = packages
        .values()
        .filter(|pkg| pkg.installed)
        .map(marketplace_package_to_value)
        .collect();
    Ok(Value::Array(installed))
}

/// Get detailed info about a marketplace package.
/// Checks remote registry first, falls back to local cache; the `source` field
/// says which answered. A registry that could not be reached, with nothing in
/// the local cache, is an error.
/// Usage: marketplace.info(name)
fn bi_marketplace_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = package_token(
        "marketplace_info",
        "name",
        str_arg("marketplace_info", args.first(), "a package name string")?,
    )?;

    guard_network("marketplace_info", MARKETPLACE_REGISTRY)?;
    let client = crate::packages::RegistryClient::default();
    let registry_error = match client.get_package(&name) {
        Ok(pkg) => {
            return Ok(with_source(
                crate::packages::RegistryClient::package_to_value(&pkg),
                "registry",
            ))
        }
        Err(e) if registry_says_absent(&e) => None,
        Err(e) => Some(e),
    };

    let packages = MARKETPLACE_PACKAGES.read().map_err(|_| {
        crate::safety::lock_poisoned("marketplace_info", "the marketplace package cache")
    })?;
    if let Some(pkg) = packages.get(&name) {
        return Ok(marketplace_package_to_value(pkg));
    }
    Err(match registry_error {
        Some(e) => registry_failure("marketplace_info", &e),
        None => crate::safety::not_found("marketplace_info", "package", &name),
    })
}

/// Rate a marketplace package. The rating is kept in the local catalogue
/// (`scope: local_cache`); it is not sent to the registry.
/// Usage: marketplace.rate(name, score) — score 1-5
fn bi_marketplace_rate(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = package_token(
        "marketplace_rate",
        "name",
        str_arg("marketplace_rate", args.first(), "a package name string")?,
    )?;
    let score = match args.get(1) {
        Some(Value::Int(n)) => *n as f64,
        Some(Value::Float(f)) => *f,
        other => {
            return Err(crate::safety::bad_arg(
                "marketplace_rate",
                "a score from 1 to 5",
                other.map_or("nothing", Value::type_name),
            ))
        }
    };
    if !(1.0..=5.0).contains(&score) {
        return Err(crate::safety::bad_arg(
            "marketplace_rate",
            "a score from 1 to 5",
            &format!("{score}"),
        ));
    }
    let mut packages = MARKETPLACE_PACKAGES.write().map_err(|_| {
        crate::safety::lock_poisoned("marketplace_rate", "the marketplace package cache")
    })?;
    let Some(pkg) = packages.get_mut(&name) else {
        return Err(crate::safety::not_found(
            "marketplace_rate",
            "package",
            &name,
        ));
    };
    // Compute new weighted average
    let total = pkg.rating * pkg.rating_count as f64 + score;
    pkg.rating_count += 1;
    pkg.rating = total / pkg.rating_count as f64;
    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
    rec.insert("rating".to_string(), Value::Float(pkg.rating));
    rec.insert("rating_count".to_string(), Value::Int(pkg.rating_count));
    rec.insert("your_rating".to_string(), Value::Float(score));
    rec.insert("scope".to_string(), Value::Str("local_cache".to_string()));
    Ok(Value::Record(rec))
}

/// Check installed marketplace packages against the registry for a newer
/// version. This reports `update_available` with the `latest` version; it does
/// not install anything. With a name, one package, and a registry failure is an
/// error. Without one, every installed package, and a package that could not be
/// checked says `unreachable` with the reason.
/// Usage: marketplace.update(name) or marketplace.update() for all
fn bi_marketplace_update(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let single = match args.first() {
        None => None,
        Some(v) => Some(package_token(
            "marketplace_update",
            "name",
            str_arg("marketplace_update", Some(v), "a package name string")?,
        )?),
    };

    // What to check, decided from the local catalogue before any request, so a
    // name that is absent or not installed costs no network round trip.
    let targets: Vec<(String, String)> = {
        let packages = MARKETPLACE_PACKAGES.read().map_err(|_| {
            crate::safety::lock_poisoned("marketplace_update", "the marketplace package cache")
        })?;
        match &single {
            Some(name) => match packages.get(name) {
                None => {
                    return Err(crate::safety::not_found(
                        "marketplace_update",
                        "package",
                        name,
                    ))
                }
                Some(p) if !p.installed => {
                    return Err(crate::safety::bad_state(
                        "marketplace_update",
                        &format!("package '{name}' is not installed"),
                        "marketplace_install",
                    ))
                }
                Some(p) => vec![(p.name.clone(), p.version.clone())],
            },
            None => packages
                .values()
                .filter(|p| p.installed)
                .map(|p| (p.name.clone(), p.version.clone()))
                .collect(),
        }
    };

    let client = crate::packages::RegistryClient::default();
    let mut out: Vec<Value> = Vec::with_capacity(targets.len());
    for (name, local_version) in &targets {
        guard_network("marketplace_update", MARKETPLACE_REGISTRY)?;
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(name.clone()));
        rec.insert("version".to_string(), Value::Str(local_version.clone()));
        match client.get_package(name) {
            Ok(remote) if remote.version == *local_version => {
                rec.insert("status".to_string(), Value::Str("up_to_date".to_string()));
            }
            Ok(remote) => {
                rec.insert("latest".to_string(), Value::Str(remote.version));
                rec.insert(
                    "status".to_string(),
                    Value::Str("update_available".to_string()),
                );
            }
            Err(e) if registry_says_absent(&e) => {
                rec.insert(
                    "status".to_string(),
                    Value::Str("not_in_registry".to_string()),
                );
            }
            Err(e) => {
                if single.is_some() {
                    return Err(registry_failure("marketplace_update", &e));
                }
                rec.insert("status".to_string(), Value::Str("unreachable".to_string()));
                rec.insert("reason".to_string(), Value::Str(format!("{e:#}")));
            }
        }
        rec.insert(
            "checked_at".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        out.push(Value::Record(rec));
    }

    match single {
        Some(_) => Ok(out.pop().unwrap_or(Value::Null)),
        None => Ok(Value::Array(out)),
    }
}

// ===================== Telemetry & Analytics Builtins =====================

/// Enable opt-in telemetry.
/// Usage: telemetry.enable()
fn bi_telemetry_enable(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut enabled = TELEMETRY_ENABLED
        .write()
        .map_err(|_| crate::safety::lock_poisoned("telemetry_enable", "the telemetry switch"))?;
    *enabled = true;

    // Record the opt-in event
    let event = TelemetryEvent {
        id: uuid::Uuid::new_v4().to_string(),
        event_type: "telemetry_enabled".to_string(),
        category: "system".to_string(),
        data: HashMap::new(),
        timestamp: chrono::Local::now().to_rfc3339(),
        session_id: uuid::Uuid::new_v4().to_string(),
    };
    if let Ok(mut events) = TELEMETRY_EVENTS.write() {
        events.push(event);
    }

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(true));
    rec.insert(
        "status".to_string(),
        Value::Str("telemetry enabled (opt-in)".to_string()),
    );
    rec.insert(
        "note".to_string(),
        Value::Str("Data is stored locally. Use telemetry.report() to view.".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Disable telemetry.
/// Usage: telemetry.disable()
fn bi_telemetry_disable(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut enabled = TELEMETRY_ENABLED
        .write()
        .map_err(|_| crate::safety::lock_poisoned("telemetry_disable", "the telemetry switch"))?;
    *enabled = false;

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(false));
    rec.insert(
        "status".to_string(),
        Value::Str("telemetry disabled".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Get current telemetry status.
/// Usage: telemetry.status()
fn bi_telemetry_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let enabled = TELEMETRY_ENABLED
        .read()
        .map_err(|_| crate::safety::lock_poisoned("telemetry_status", "the telemetry switch"))?;
    let events = TELEMETRY_EVENTS.read().map_err(|_| {
        crate::safety::lock_poisoned("telemetry_status", "the telemetry event buffer")
    })?;

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(*enabled));
    rec.insert("event_count".to_string(), Value::Int(events.len() as i64));
    rec.insert("storage".to_string(), Value::Str("local".to_string()));
    rec.insert(
        "privacy".to_string(),
        Value::Str("All data stored locally. No external transmission.".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Generate a telemetry usage report.
/// Usage: telemetry.report() or telemetry.report({category?})
fn bi_telemetry_report(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let opts = match args.first() {
        Some(Value::Record(r)) => r.clone(),
        None => BTreeMap::new(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "telemetry_report",
                "options: Record",
                other.type_name(),
            ))
        }
    };
    for (key, value) in &opts {
        if key != "category" {
            return Err(crate::safety::arg_err(format!(
                "telemetry_report: unknown option {key}"
            )));
        }
        expect_string("telemetry_report category", value)?;
    }
    let category_filter = opts.get("category").and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });

    let events = TELEMETRY_EVENTS.read().map_err(|_| {
        crate::safety::lock_poisoned("telemetry_report", "the telemetry event buffer")
    })?;

    // Group by category
    let mut by_category: BTreeMap<String, i64> = BTreeMap::new();
    let mut by_type: BTreeMap<String, i64> = BTreeMap::new();
    let mut filtered_count = 0i64;

    for event in events.iter() {
        let include = category_filter
            .as_ref()
            .map(|c| event.category == *c)
            .unwrap_or(true);
        if include {
            filtered_count += 1;
            *by_category.entry(event.category.clone()).or_insert(0) += 1;
            *by_type.entry(event.event_type.clone()).or_insert(0) += 1;
        }
    }

    let categories: Vec<Value> = by_category
        .iter()
        .map(|(k, v)| {
            let mut rec = BTreeMap::new();
            rec.insert("category".to_string(), Value::Str(k.clone()));
            rec.insert("count".to_string(), Value::Int(*v));
            Value::Record(rec)
        })
        .collect();

    let types: Vec<Value> = by_type
        .iter()
        .map(|(k, v)| {
            let mut rec = BTreeMap::new();
            rec.insert("event_type".to_string(), Value::Str(k.clone()));
            rec.insert("count".to_string(), Value::Int(*v));
            Value::Record(rec)
        })
        .collect();

    let mut rec = BTreeMap::new();
    rec.insert("total_events".to_string(), Value::Int(filtered_count));
    rec.insert("by_category".to_string(), Value::Array(categories));
    rec.insert("by_type".to_string(), Value::Array(types));
    rec.insert(
        "generated_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// Get raw telemetry events.
/// Usage: telemetry.events() or telemetry.events(limit)
fn bi_telemetry_events(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let limit = match args.first() {
        Some(Value::Int(n)) => *n as usize,
        _ => 100,
    };
    let events = TELEMETRY_EVENTS.read().map_err(|_| {
        crate::safety::lock_poisoned("telemetry_events", "the telemetry event buffer")
    })?;
    let entries: Vec<Value> = events
        .iter()
        .rev()
        .take(limit)
        .map(|e| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(e.id.clone()));
            rec.insert("event_type".to_string(), Value::Str(e.event_type.clone()));
            rec.insert("category".to_string(), Value::Str(e.category.clone()));
            rec.insert("timestamp".to_string(), Value::Str(e.timestamp.clone()));
            rec.insert("session_id".to_string(), Value::Str(e.session_id.clone()));
            if !e.data.is_empty() {
                let data_rec: BTreeMap<String, Value> = e
                    .data
                    .iter()
                    .map(|(k, v)| (k.clone(), Value::Str(v.clone())))
                    .collect();
                rec.insert("data".to_string(), Value::Record(data_rec));
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Reset (clear) all telemetry data.
/// Usage: telemetry.reset()
fn bi_telemetry_reset(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if !args.is_empty() {
        return Err(crate::safety::bad_arg(
            "telemetry_reset",
            "no arguments",
            &format!("{} argument(s)", args.len()),
        ));
    }
    // Clears the in-process event buffer only. Nothing on disk is read or
    // removed, so the status says exactly that.
    let mut events = TELEMETRY_EVENTS.write().map_err(|_| {
        crate::safety::lock_poisoned("telemetry_reset", "the telemetry event buffer")
    })?;
    let count = events.len();
    events.clear();

    let mut rec = BTreeMap::new();
    rec.insert("cleared".to_string(), Value::Int(count as i64));
    rec.insert(
        "status".to_string(),
        Value::Str("in-process telemetry events cleared".to_string()),
    );
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// ═══════════════════════════════════════════════════════════════════════════
// CLI Tool Wrappers — New cross-platform implementations (965-987)
// ═══════════════════════════════════════════════════════════════════════════

/// wget_download — download one http(s) URL to a file in the workspace.
/// Usage: wget_download(url) or wget_download(url, output). Without an output,
/// the file is the last path segment of the URL. The transfer is curl, limited
/// to http and https for the first request and for every redirect, with at most
/// 5 redirects, a 1 GiB size limit and a 15 s connect limit; wget cannot limit
/// the schemes it follows, so it is not used. An existing output is refused, and
/// a failed transfer removes its partial file. Returns {url, output, size, status, tool}.
fn bi_wget_download(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("wget_download")?;
    k8s_no_input("wget_download", &input)?;
    if args.len() > 2 {
        return Err(crate::safety::arg_err(
            "wget_download takes a URL and an optional output path",
        ));
    }
    let url = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("wget requires a URL string")),
    };
    let parsed = url::Url::parse(&url).map_err(|e| {
        crate::safety::bad_arg("wget_download", "an absolute http(s) URL", &e.to_string())
    })?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err(crate::safety::bad_arg(
            "wget_download",
            "an http or https URL",
            &format!("the scheme {}", parsed.scheme()),
        ));
    }
    guard_network("wget_download", &url)?;
    let output = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "wget_download",
                "an output path String",
                other.type_name(),
            ))
        }
        None => parsed
            .path_segments()
            .and_then(|segs| {
                segs.rev()
                    .find(|s| !s.is_empty() && *s != "." && *s != "..")
            })
            .map(str::to_string)
            .ok_or_else(|| {
                crate::safety::arg_err("wget_download: the URL names no file; pass an output path")
            })?,
    };
    crate::safety::reject_option_like("wget_download", std::slice::from_ref(&output))?;
    if output.trim().is_empty() || output.len() > 4096 || output.contains('\0') {
        return Err(crate::safety::arg_err(
            "wget_download: the output path must be 1 to 4096 bytes without NUL",
        ));
    }
    let output = guard_local_write("wget_download", &output)?;
    if std::path::Path::new(&output).exists() {
        return Err(crate::safety::arg_err(format!(
            "wget_download: `{output}` already exists; remove it or choose another output path"
        )));
    }
    let max = WGET_FILE_MAX.to_string();
    let argv = [
        "-sS",
        "-f",
        "-L",
        "--max-redirs",
        "5",
        "--proto",
        "=http,https",
        "--proto-redir",
        "=http,https",
        "--connect-timeout",
        "15",
        "--max-filesize",
        max.as_str(),
        "-o",
        output.as_str(),
        url.as_str(),
    ];
    if let Err(e) = tool_run(
        "wget_download",
        "curl",
        None,
        &argv,
        Keep::Tail(TOOL_STDERR_TAIL),
        TOOL_LONG_DEADLINE_SECS,
    )
    .and_then(|run| finished("wget_download", run))
    {
        remove_partial(&output);
        return Err(e);
    }
    let size = std::fs::metadata(&output)
        .map_err(|e| crate::safety::fs_error("wget_download", &output, &e))?
        .len();
    let mut rec = BTreeMap::new();
    rec.insert("url".to_string(), Value::Str(url));
    rec.insert("output".to_string(), Value::Str(output));
    rec.insert("size".to_string(), Value::Int(size as i64));
    rec.insert("status".to_string(), Value::Str("downloaded".to_string()));
    rec.insert("tool".to_string(), Value::Str("curl".to_string()));
    Ok(Value::Record(rec))
}

/// An age recipient: an age1… key or an ssh- public key, and no other text.
fn age_recipient_ok(recipient: &str) -> bool {
    (recipient.starts_with("age1") || recipient.starts_with("ssh-"))
        && recipient.len() <= 1024
        && recipient.chars().all(|c| {
            c.is_ascii_alphanumeric() || matches!(c, ' ' | '-' | '_' | '+' | '/' | '=' | '.' | '@')
        })
}

/// age — Encrypt a file to one recipient (an age1… or ssh- public key).
/// Usage: age_encrypt(input_file, output_file, recipient). The output is
/// required, and is the second argument because the recipient is the third. An
/// existing output is refused, and a failed run removes its partial file.
fn bi_age_encrypt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("age_encrypt", &input)?;
    let input_file = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "age_encrypt requires input_file, output_file, recipient",
            ))
        }
    };
    let output_file = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "age_encrypt requires an output_file as its second argument",
            ))
        }
    };
    let recipient = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "age_encrypt requires a recipient (an age1… or ssh- public key)",
            ))
        }
    };
    if !age_recipient_ok(&recipient) {
        return Err(crate::safety::bad_arg(
            "age_encrypt",
            "recipient: an age1… or ssh- public key",
            &recipient,
        ));
    }
    refuse_option("age_encrypt", &input_file)?;
    let input_file = crate::safety::resolve_path_str(&input_file);
    regular_file_arg("age_encrypt", &input_file)?;
    let output_file = guard_local_write(
        "age_encrypt",
        &crate::safety::resolve_path_str(&output_file),
    )?;
    refuse_existing("age_encrypt", &output_file)?;
    let mut cmd = std::process::Command::new("age");
    cmd.args([
        "-r",
        recipient.as_str(),
        "-o",
        output_file.as_str(),
        input_file.as_str(),
    ]);
    if let Err(e) = run_checked("age_encrypt", "age", cmd, LOCAL_DEADLINE_SECS) {
        remove_partial(&output_file);
        return Err(e);
    }
    let mut rec = BTreeMap::new();
    rec.insert("input".to_string(), Value::Str(input_file));
    rec.insert("output".to_string(), Value::Str(output_file));
    rec.insert("recipient".to_string(), Value::Str(recipient));
    rec.insert("status".to_string(), Value::Str("encrypted".to_string()));
    Ok(Value::Record(rec))
}

/// age — Decrypt a file with an identity file.
/// Usage: age_decrypt(input_file, output_file?, identity_file?). Without an
/// output the input must end in .age. The output is refused if it exists.
fn bi_age_decrypt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("age_decrypt", &input)?;
    let input_file = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("age_decrypt requires input_file")),
    };
    refuse_option("age_decrypt", &input_file)?;
    let output_file = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => match input_file.strip_suffix(".age") {
            Some(stem) => stem.to_string(),
            None => {
                return Err(crate::safety::bad_arg(
                    "age_decrypt",
                    "an input ending in .age, or an output_file",
                    &input_file,
                ))
            }
        },
    };
    let identity = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            let home = std::env::var("HOME")
                .or_else(|_| std::env::var("USERPROFILE"))
                .unwrap_or_default();
            format!("{}/.age/key.txt", home)
        }
    };
    refuse_option("age_decrypt", &identity)?;
    if output_file == input_file {
        return Err(crate::safety::bad_arg(
            "age_decrypt",
            "an output_file other than the input",
            &output_file,
        ));
    }
    let input_file = crate::safety::resolve_path_str(&input_file);
    regular_file_arg("age_decrypt", &input_file)?;
    let identity = crate::safety::resolve_path_str(&identity);
    regular_file_arg("age_decrypt", &identity)?;
    let output_file = guard_local_write(
        "age_decrypt",
        &crate::safety::resolve_path_str(&output_file),
    )?;
    refuse_existing("age_decrypt", &output_file)?;
    let mut cmd = std::process::Command::new("age");
    cmd.args([
        "-d",
        "-i",
        identity.as_str(),
        "-o",
        output_file.as_str(),
        input_file.as_str(),
    ]);
    if let Err(e) = run_checked("age_decrypt", "age", cmd, LOCAL_DEADLINE_SECS) {
        remove_partial(&output_file);
        return Err(e);
    }
    let mut rec = BTreeMap::new();
    rec.insert("input".to_string(), Value::Str(input_file));
    rec.insert("output".to_string(), Value::Str(output_file));
    rec.insert("status".to_string(), Value::Str("decrypted".to_string()));
    Ok(Value::Record(rec))
}

/// age — Generate an age identity into a new file and return its public key.
/// Usage: age_keygen(output_file). The output file is required: the private key
/// is written there and is never returned, so it cannot land in a transcript.
/// An existing file is refused.
fn bi_age_keygen(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("age_keygen", &input)?;
    let output_file = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "age_keygen requires an output_file: the private key is written there and never returned",
            ))
        }
    };
    refuse_option("age_keygen", &output_file)?;
    let output_file =
        guard_local_write("age_keygen", &crate::safety::resolve_path_str(&output_file))?;
    refuse_existing("age_keygen", &output_file)?;
    let mut cmd = std::process::Command::new("age-keygen");
    cmd.args(["-o", output_file.as_str()]);
    // With -o, age-keygen writes the identity to the file and prints the public
    // key on stderr. Its stdout is discarded, so the identity cannot be returned.
    let (_, stderr) = match run_checked("age_keygen", "age-keygen", cmd, LOCAL_DEADLINE_SECS) {
        Ok(done) => done,
        Err(e) => {
            remove_partial(&output_file);
            return Err(e);
        }
    };
    let public_key = stderr
        .lines()
        .find_map(|l| l.strip_prefix("Public key:"))
        .map(|k| k.trim().to_string())
        .filter(|k| !k.is_empty());
    let Some(public_key) = public_key else {
        remove_partial(&output_file);
        return Err(crate::safety::tool_failed(
            "age_keygen",
            "age-keygen",
            Some(0),
            &stderr,
        ));
    };
    let mut rec = BTreeMap::new();
    rec.insert("public_key".to_string(), Value::Str(public_key));
    rec.insert("identity_file".to_string(), Value::Str(output_file));
    rec.insert("status".to_string(), Value::Str("generated".to_string()));
    Ok(Value::Record(rec))
}

/// ripgrep (rg) — Fast regex-based code search.
/// Usage: rg(pattern) or rg(pattern, path) or rg(pattern, path, flags_record)
/// Runs `rg --json --regexp=PATTERN PATH` with no shell. Exit 1 is "no matches"; any other
/// nonzero exit is E_TOOL_FAILED. A missing rg is E_TOOL_MISSING (no native fallback: a
/// different matcher would answer a different question). Over 1000 matches is E_BUDGET_EXCEEDED.
fn bi_rg_search(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "rg_search";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let pattern = k8s_need(B, "a search pattern", &args, 0, search_text_check)?;
    let path = pkg_path_arg(B, &args, 1, ".")?;
    let ignore_case =
        match devtool_options(B, &args, 2, &["ignore_case"])?.and_then(|o| o.get("ignore_case")) {
            None => false,
            Some(Value::Bool(b)) => *b,
            Some(other) => {
                return Err(crate::safety::arg_err(format!(
                    "{B}: ignore_case must be a Bool, got {}",
                    other.type_name()
                )))
            }
        };
    let regexp = format!("--regexp={pattern}");
    let mut argv = vec!["--json"];
    if ignore_case {
        argv.push("-i");
    }
    argv.push(regexp.as_str());
    argv.push(path.as_str());
    let run = tool_run(
        B,
        "rg",
        None,
        &argv,
        Keep::Head(TOOL_MAX_JSON),
        TOOL_DEADLINE_SECS,
    )?;
    let command = run.command.clone();
    let text = stdout_with_exit1(B, run)?;
    let mut matches = Vec::new();
    for line in text.lines().filter(|l| !l.is_empty()) {
        let parsed = serde_json::from_str::<serde_json::Value>(line).map_err(|e| {
            crate::safety::tool_failed(
                B,
                &command,
                Some(0),
                &format!("printed a line that is not JSON ({e})"),
            )
        })?;
        if parsed.get("type").and_then(|t| t.as_str()) != Some("match") {
            continue;
        }
        let Some(data) = parsed.get("data") else {
            continue;
        };
        if matches.len() >= SEARCH_MAX_RESULTS {
            return Err(search_budget(B));
        }
        let mut rec = BTreeMap::new();
        if let Some(p) = data
            .get("path")
            .and_then(|p| p.get("text"))
            .and_then(|t| t.as_str())
        {
            rec.insert("file".to_string(), Value::Str(p.to_string()));
        }
        if let Some(n) = data.get("line_number").and_then(|n| n.as_i64()) {
            rec.insert("line".to_string(), Value::Int(n));
        }
        if let Some(t) = data
            .get("lines")
            .and_then(|l| l.get("text"))
            .and_then(|t| t.as_str())
        {
            rec.insert("text".to_string(), Value::Str(t.trim_end().to_string()));
        }
        matches.push(Value::Record(rec));
    }
    Ok(Value::Array(matches))
}

/// fd — Fast, user-friendly file finder.
/// Usage: fd(pattern) or fd(pattern, path) or fd(pattern, path, {type?, extension?})
/// Runs `fd` with the pattern after `--`, so a leading '-' is never a flag. A missing fd is
/// E_TOOL_MISSING; there is no native fallback, since find's glob is not fd's regex.
fn bi_fd_find(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "fd_find";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 3)?;
    let pattern = k8s_need(B, "a search pattern", &args, 0, search_text_check)?;
    let path = pkg_path_arg(B, &args, 1, ".")?;
    let options = devtool_options(B, &args, 2, &["type", "extension"])?;
    let kind = devtool_opt_str(B, "type", options, "type", fd_kind_check)?;
    let extension = devtool_opt_str(B, "extension", options, "extension", fd_ext_check)?;
    let mut argv: Vec<&str> = Vec::new();
    if let Some(kind) = kind.as_deref() {
        argv.extend(["--type", kind]);
    }
    if let Some(extension) = extension.as_deref() {
        argv.extend(["--extension", extension]);
    }
    // fd's pattern is positional: `--` keeps a pattern that begins with '-' from
    // being read as a flag.
    argv.extend(["--", pattern.as_str(), path.as_str()]);
    let run = tool_run(
        B,
        "fd",
        None,
        &argv,
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_DEADLINE_SECS,
    )?;
    let text = tool_text(B, run)?;
    search_list(
        B,
        text.lines()
            .filter(|l| !l.is_empty())
            .map(str::to_string)
            .collect(),
    )
}

/// sed — Stream editor for text substitution (cross-platform, native Rust).
/// Usage: sed(pattern, replacement, input_text) or sed(pattern, replacement, input_text, {global?, file?})
fn bi_sed_replace(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let mut args = args.into_iter();
    let Some(Value::Str(pattern)) = args.next() else {
        return Err(crate::safety::arg_err("sed requires pattern String"));
    };
    let Some(Value::Str(replacement)) = args.next() else {
        return Err(crate::safety::arg_err("sed requires replacement String"));
    };
    let (text, options) = match input {
        Some(Value::Str(text)) => {
            let options = args.next();
            if args.next().is_some() {
                return Err(crate::safety::arg_err(
                    "piped sed accepts pattern, replacement and optional options only",
                ));
            }
            (text, options)
        }
        Some(_) => return Err(crate::safety::arg_err("sed piped input must be String")),
        None => {
            let Some(Value::Str(text)) = args.next() else {
                return Err(crate::safety::arg_err(
                    "sed requires text or file path String",
                ));
            };
            (text, args.next())
        }
    };
    let (mut global, mut file_mode) = (true, false);
    if let Some(options) = options {
        let Value::Record(record) = options else {
            return Err(crate::safety::arg_err("sed options must be Record"));
        };
        for (key, value) in record {
            let slot = match key.as_str() {
                "global" => &mut global,
                "file" => &mut file_mode,
                _ => return Err(crate::safety::arg_err(format!("sed unknown option {key}"))),
            };
            let Value::Bool(flag) = value else {
                return Err(crate::safety::arg_err(format!("sed {key} must be Bool")));
            };
            *slot = flag;
        }
    }
    let re = regex::Regex::new(&pattern)
        .map_err(|e| crate::safety::arg_err(format!("sed invalid regex: {e}")))?;
    let file = if file_mode {
        Some((text.clone(), crate::safety::resolve_path_str(&text)))
    } else {
        None
    };
    let source = if let Some((_, path)) = &file {
        crate::safety::guard(crate::safety::GuardCtx {
            builtin: "sed_replace",
            effect: crate::safety::Effect::WriteLocal,
            what: "replace file text",
            targets: vec![path.clone()],
            blast_radius: serde_json::json!({"files":1}),
            reversible: true,
            fs_paths: true,
        })?;
        line_read("sed", path)?
    } else {
        text
    };
    let result = regex_substitute(&re, &replacement, source, global);
    if let Some((original, path)) = file {
        crate::tx::snapshot(&path);
        write_file_atomically("sed", &path, result.as_bytes())?;
        Ok(Value::Record(BTreeMap::from([
            ("file".into(), Value::Str(original)),
            ("status".into(), Value::Str("modified".into())),
        ])))
    } else {
        Ok(Value::Str(result))
    }
}

/// awk — bounded in-process awk subset (see src/awk.rs for the grammar and limits).
/// Usage: awk(program, input_text, options?) or piped: text | awk(program, options?)
/// Options: {fs: String} sets the initial field separator (default one space).
#[path = "awk.rs"]
mod awk;

fn bi_awk_process(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let mut args = args.into_iter();
    let program = match args.next() {
        Some(Value::Str(s)) => s,
        _ => return Err(crate::safety::arg_err("awk requires a program String")),
    };
    let (text, options) = match input {
        Some(Value::Str(text)) => {
            let options = args.next();
            if args.next().is_some() {
                return Err(crate::safety::arg_err(
                    "piped awk accepts program and optional options only",
                ));
            }
            (text, options)
        }
        Some(_) => return Err(crate::safety::arg_err("awk piped input must be String")),
        None => {
            let Some(Value::Str(text)) = args.next() else {
                return Err(crate::safety::arg_err("awk requires input String"));
            };
            (text, args.next())
        }
    };
    let mut separator = " ".to_string();
    if let Some(options) = options {
        let Value::Record(record) = options else {
            return Err(crate::safety::arg_err("awk options must be Record"));
        };
        for (key, value) in record {
            if key != "fs" {
                return Err(crate::safety::arg_err(format!("awk unknown option {key}")));
            }
            let Value::Str(value) = value else {
                return Err(crate::safety::arg_err("awk fs must be String"));
            };
            separator = value;
        }
    }
    let lines = awk::run(&program, &text, &separator)?;
    Ok(Value::Array(lines.into_iter().map(Value::Str).collect()))
}

/// cut — Extract columns/fields from text (cross-platform, native Rust).
/// Usage: cut(delimiter, fields, input_text) or piped: text | cut(delimiter, fields)
/// fields is a string like "1,3" or "1-3" (1-based)
fn bi_cut_columns(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if input.is_some() && args.len() > 2 {
        return Err(crate::safety::arg_err(
            "piped cut accepts delimiter and fields only",
        ));
    }
    let delimiter = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cut requires delimiter, fields, and input",
            ))
        }
    };
    let fields_spec = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        Some(Value::Int(n)) => n.to_string(),
        _ => {
            return Err(crate::safety::arg_err(
                "cut requires a fields specification (e.g., '1,3' or '1-3')",
            ))
        }
    };
    let text = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        None => match &input {
            Some(Value::Str(s)) => s.clone(),
            _ => return Err(crate::safety::arg_err("cut requires input text")),
        },
        _ => return Err(crate::safety::arg_err("cut input must be a string")),
    };
    // Parse field spec: "1,3,5" or "1-3" or "2"
    let field_indices = parse_field_spec(&fields_spec)?;
    let mut results = Vec::new();
    for line in text.lines() {
        let cols: Vec<&str> = line.split(&delimiter).collect();
        let selected: Vec<&str> = field_indices
            .iter()
            .filter_map(|&i| cols.get(i - 1).copied())
            .collect();
        results.push(Value::Str(selected.join(&delimiter)));
    }
    Ok(Value::Array(results))
}

/// Parse a field specification like "1,3,5" or "1-3" into a Vec of 1-based indices.
fn parse_field_spec(spec: &str) -> Result<Vec<usize>> {
    const MAX_FIELDS: usize = 10000;
    let invalid = || {
        crate::safety::arg_err("cut fields must be positive integers or ascending inclusive ranges, separated by commas")
    };
    let parse = |part: &str| -> Result<usize> {
        if part.is_empty() || !part.bytes().all(|b| b.is_ascii_digit()) {
            return Err(invalid());
        }
        let n = part.parse::<usize>().map_err(|_| invalid())?;
        if n == 0 {
            return Err(invalid());
        }
        Ok(n)
    };
    let mut indices = Vec::new();
    for part in spec.split(',') {
        let part = part.trim();
        let (start, end) = if let Some((left, right)) = part.split_once('-') {
            (parse(left)?, parse(right)?)
        } else {
            let n = parse(part)?;
            (n, n)
        };
        if start > end {
            return Err(invalid());
        }
        let length = end - start + 1;
        if length > MAX_FIELDS - indices.len() {
            return Err(crate::safety::budget_exceeded(
                "cut",
                "field selection exceeds 10000 entries".into(),
                "select fewer fields",
            ));
        }
        indices.extend(start..=end);
    }
    Ok(indices)
}

/// xargs — Run one program once per item, with the item as its last argument.
/// Usage: xargs_exec(command, items) or items | xargs_exec(command). items is an
/// Array of scalars, or a String read as lines. The command is split on whitespace
/// and run directly, with no shell; its program may not begin with '-', and no
/// item may either. At most 256 items, each run has a 120 s deadline, and the call
/// as a whole 600 s. Returns one Record per item: {item, exit_code, stdout, stderr}.
/// A nonzero exit is that item's exit code, which is data here.
fn bi_xargs_exec(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_max_args("xargs_exec", &args, 2)?;
    let command = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("xargs requires a command string")),
    };
    let items = match (args.get(1), &input) {
        (Some(_), Some(_)) => {
            return Err(crate::safety::arg_err(
                "xargs_exec takes its items either as an argument or piped in, not both",
            ))
        }
        (Some(v), None) | (None, Some(v)) => xargs_items("xargs_exec", v)?,
        (None, None) => return Err(crate::safety::arg_err("xargs requires input items")),
    };
    let words = argv_words("xargs_exec", &command)?;
    crate::safety::guard_exec("xargs", &command)?;
    let started = std::time::Instant::now();
    let mut results = Vec::with_capacity(items.len());
    for item in &items {
        if started.elapsed() > std::time::Duration::from_secs(XARGS_TOTAL_SECS) {
            return Err(crate::safety::budget_exceeded(
                "xargs_exec",
                format!(
                    "the items took more than {XARGS_TOTAL_SECS} s; {} of {} ran",
                    results.len(),
                    items.len()
                ),
                "run the remaining items in a separate call",
            ));
        }
        let mut argv: Vec<&str> = words.iter().skip(1).map(String::as_str).collect();
        argv.push(item.as_str());
        let run = tool_run_stderr(
            "xargs_exec",
            &words[0],
            None,
            &argv,
            Keep::Tail(XARGS_ITEM_OUT),
            XARGS_ITEM_OUT,
            TOOL_DEADLINE_SECS,
        )?;
        let mut rec = BTreeMap::new();
        rec.insert("item".to_string(), Value::Str(item.clone()));
        rec.insert("exit_code".to_string(), Value::Int(exit_code_of(&run)));
        rec.insert(
            "stdout".to_string(),
            Value::Str(run.stdout.trim().to_string()),
        );
        rec.insert("stderr".to_string(), Value::Str(run.stderr.clone()));
        results.push(Value::Record(rec));
    }
    Ok(Value::Array(results))
}

/// The JSON text a jq builtin reads: its second argument, or the piped string.
/// Text past JQ_INPUT_CAP is refused rather than parsed.
fn jq_json_arg(builtin: &str, args: &[Value], input: Option<Value>) -> Result<String> {
    let text = match (args.get(1), input) {
        (Some(Value::Str(s)), _) => s.clone(),
        (None, Some(Value::Str(s))) => s,
        (None, _) => {
            return Err(crate::safety::arg_err(format!(
                "{builtin} requires JSON input"
            )))
        }
        _ => {
            return Err(crate::safety::bad_arg(
                builtin,
                "JSON text: String",
                "a non-string",
            ))
        }
    };
    if text.len() > JQ_INPUT_CAP {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!(
                "JSON input is {} bytes; the limit is {JQ_INPUT_CAP}",
                text.len()
            ),
            "pass a smaller document",
        ));
    }
    Ok(text)
}

/// jq — Query and transform JSON data (cross-platform, native Rust).
/// Usage: jq(expression, json_string) or piped: json_str | jq(expression)
/// Evaluates the subset that eval_jq_expr documents. Anything else is refused,
/// never answered with a guess.
fn bi_jq_query(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let expr = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("jq requires a query expression")),
    };
    let json_str = jq_json_arg("jq", &args, input)?;
    let parsed: serde_json::Value = serde_json::from_str(&json_str)
        .map_err(|e| crate::safety::bad_arg("jq", "valid JSON input", &e.to_string()))?;
    let result = eval_jq_expr(&expr, &parsed)?;
    Ok(json_to_value(result))
}

/// jq filter — Apply a real jq filter to JSON, with the jq binary.
/// Usage: jq_filter(filter, json_string) or piped: json_str | jq_filter(filter)
/// A filter that begins with '-' is refused: jq would read it as an option.
/// With no jq on PATH this is E_TOOL_MISSING. It does not fall back to the native subset.
fn bi_jq_filter(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let filter = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "jq_filter requires a filter expression",
            ))
        }
    };
    refuse_option("jq_filter", &filter)?;
    let json_str = jq_json_arg("jq_filter", &args, input)?;
    let mut cmd = std::process::Command::new("jq");
    cmd.arg(filter.as_str());
    let out = std::sync::Arc::new(std::sync::Mutex::new(Vec::<u8>::new()));
    let (status, stderr) = run_tool(
        "jq_filter",
        "jq",
        cmd,
        Some(json_str.into_bytes()),
        std::sync::Arc::clone(&out),
        LOCAL_DEADLINE_SECS,
        TOOL_OUTPUT_CAP,
    )?;
    tool_ok("jq_filter", "jq", status, &stderr)?;
    let bytes = std::mem::take(
        &mut *out
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner),
    );
    let stdout = String::from_utf8_lossy(&bytes).trim().to_string();
    match serde_json::from_str::<serde_json::Value>(&stdout) {
        Ok(parsed) => Ok(json_to_value(parsed)),
        Err(_) => Ok(Value::Str(stdout)),
    }
}

/// Native jq expression evaluator. Supports `.`, `.key`, `.key.sub`, `.[n]`,
/// `.[]` (returns the elements as an array), `keys`, `length` and `|` between
/// them. `length` follows jq: the absolute value of a number, and an error for a
/// boolean. Anything else, and any index that does not fit, is refused.
fn eval_jq_expr(expr: &str, data: &serde_json::Value) -> Result<serde_json::Value> {
    let expr = expr.trim();
    let unsupported = || {
        crate::safety::bad_arg(
            "jq",
            "an expression of . .key .key.sub .[n] .[] keys length, joined by |",
            expr,
        )
    };
    if expr == "." {
        return Ok(data.clone());
    }
    if expr == "keys" {
        if let serde_json::Value::Object(m) = data {
            return Ok(serde_json::Value::Array(
                m.keys()
                    .map(|k| serde_json::Value::String(k.clone()))
                    .collect(),
            ));
        }
        return Err(crate::safety::arg_err("keys requires an object"));
    }
    if expr == "length" {
        return match data {
            serde_json::Value::Null => Ok(serde_json::json!(0)),
            serde_json::Value::Bool(_) => Err(crate::safety::bad_arg(
                "jq",
                "a value with a length (null, number, string, array or object)",
                "a boolean",
            )),
            serde_json::Value::Number(n) => Ok(match n.as_i64() {
                Some(i) => serde_json::json!(i.unsigned_abs()),
                None => serde_json::json!(n.as_f64().map_or(0.0, f64::abs)),
            }),
            // jq counts code points, not bytes.
            serde_json::Value::String(s) => Ok(serde_json::json!(s.chars().count())),
            serde_json::Value::Array(a) => Ok(serde_json::json!(a.len())),
            serde_json::Value::Object(m) => Ok(serde_json::json!(m.len())),
        };
    }
    if expr == ".[]" {
        if let serde_json::Value::Array(a) = data {
            return Ok(serde_json::Value::Array(a.clone()));
        }
        if let serde_json::Value::Object(m) = data {
            return Ok(serde_json::Value::Array(m.values().cloned().collect()));
        }
        return Err(crate::safety::bad_arg(
            "jq",
            "an array or object to iterate",
            "another value",
        ));
    }
    // Handle pipe: .key | .subkey
    if let Some(pipe_pos) = expr.find(" | ") {
        let left = &expr[..pipe_pos];
        let right = &expr[pipe_pos + 3..];
        let intermediate = eval_jq_expr(left, data)?;
        return eval_jq_expr(right, &intermediate);
    }
    // Dot-path: .key.subkey or .key
    if let Some(path) = expr.strip_prefix('.') {
        // Handle array index: .[0]
        if path.starts_with('[') && path.ends_with(']') {
            let idx_str = &path[1..path.len() - 1];
            let idx: usize = idx_str.parse().map_err(|_| {
                crate::safety::bad_arg("jq", "a numeric index in brackets", idx_str)
            })?;
            return match data {
                serde_json::Value::Array(a) => a.get(idx).cloned().ok_or_else(|| {
                    crate::safety::bad_arg(
                        "jq",
                        &format!("an index below {}", a.len()),
                        &idx.to_string(),
                    )
                }),
                _ => Err(crate::safety::bad_arg(
                    "jq",
                    "an array to index",
                    "a non-array",
                )),
            };
        }
        let mut current = data;
        for key in path.split('.') {
            if key.is_empty() {
                continue;
            }
            // Handle key[n] notation. A bracket that is not a number is refused,
            // not dropped.
            if let Some(bracket) = key.find('[').filter(|_| key.ends_with(']')) {
                let obj_key = &key[..bracket];
                let idx_str = &key[bracket + 1..key.len() - 1];
                if !obj_key.is_empty() {
                    current = current
                        .get(obj_key)
                        .ok_or_else(|| crate::safety::not_found("jq", "key", obj_key))?;
                }
                let idx: usize = idx_str.parse().map_err(|_| {
                    crate::safety::bad_arg("jq", "a numeric index in brackets", idx_str)
                })?;
                current = match current {
                    serde_json::Value::Array(a) => a.get(idx).ok_or_else(|| {
                        crate::safety::bad_arg(
                            "jq",
                            &format!("an index below {}", a.len()),
                            &idx.to_string(),
                        )
                    })?,
                    _ => {
                        return Err(crate::safety::bad_arg(
                            "jq",
                            "an array to index",
                            "a non-array",
                        ))
                    }
                };
            } else {
                current = current
                    .get(key)
                    .ok_or_else(|| crate::safety::not_found("jq", "key", key))?;
            }
        }
        return Ok(current.clone());
    }
    Err(unsupported())
}

/// yq — Query/transform YAML, TOML, XML data.
/// Usage: yq(expression, input_string) or piped input.
/// Runs `yq EXPRESSION FILE`, where FILE holds the document (a temporary file, since the
/// runner gives a child no stdin). A missing yq is E_TOOL_MISSING; nothing is parsed natively.
fn bi_yq_query(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "yq_query";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 2)?;
    let expr = k8s_need(B, "an expression", &args, 0, pkg_plain)?;
    let document = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "{B}: the document must be a String, got {}",
                other.type_name()
            )))
        }
        None => {
            return Err(crate::safety::arg_err(format!(
                "{B} requires the document text"
            )))
        }
    };
    if document.len() > TOOL_MAX_TEXT {
        return Err(crate::safety::budget_exceeded(
            B,
            format!("the document is larger than {TOOL_MAX_TEXT} bytes"),
            "pass a smaller document",
        ));
    }
    // yq reads its document from a file here, because the runner gives a child
    // no stdin. The file lives in a directory of its own, removed afterwards.
    let file = scratch_file(B, "document.yaml", document.as_bytes())?;
    let path = file.display().to_string();
    let run = tool_run(
        B,
        "yq",
        None,
        &[expr.as_str(), path.as_str()],
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_DEADLINE_SECS,
    );
    scratch_remove(&file);
    let text = tool_text(B, run?)?;
    Ok(Value::Str(text.trim().to_string()))
}

/// pager/less — Display text with pagination (cross-platform).
/// Usage: less(text) or less(file_path, {file: true})
fn bi_pager(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let mut args = args.into_iter();
    let (text, options) = match input {
        Some(Value::Str(text)) => {
            let options = args.next();
            if args.next().is_some() {
                return Err(crate::safety::arg_err(
                    "piped pager accepts optional options only",
                ));
            }
            (text, options)
        }
        Some(_) => return Err(crate::safety::arg_err("pager piped input must be String")),
        None => {
            let Some(Value::Str(text)) = args.next() else {
                return Err(crate::safety::arg_err(
                    "pager requires text or file path String",
                ));
            };
            (text, args.next())
        }
    };
    let mut file = false;
    if let Some(options) = options {
        let Value::Record(record) = options else {
            return Err(crate::safety::arg_err("pager options must be Record"));
        };
        for (key, value) in record {
            if key != "file" {
                return Err(crate::safety::arg_err(format!(
                    "pager unknown option {key}"
                )));
            }
            let Value::Bool(flag) = value else {
                return Err(crate::safety::arg_err("pager file must be Bool"));
            };
            file = flag;
        }
    }
    let content = if file {
        let path = crate::safety::resolve_path_str(&text);
        crate::safety::guard(crate::safety::GuardCtx {
            builtin: "pager",
            effect: crate::safety::Effect::ReadLocal,
            what: "read paged file text",
            targets: vec![path.clone()],
            blast_radius: serde_json::json!({"files":1}),
            reversible: true,
            fs_paths: true,
        })?;
        line_read("pager", &path)?
    } else {
        text
    };
    const PAGE_SIZE: usize = 40;
    let mut lines = content.lines();
    let first: Vec<_> = lines.by_ref().take(PAGE_SIZE).collect();
    let total = first.len() + lines.count();
    if total <= PAGE_SIZE {
        return Ok(Value::Str(content));
    }
    Ok(Value::Record(BTreeMap::from([
        ("content".into(), Value::Str(first.join("\n"))),
        ("total_lines".into(), Value::Int(total as i64)),
        ("page_size".into(), Value::Int(PAGE_SIZE as i64)),
        ("pages".into(), Value::Int(total.div_ceil(PAGE_SIZE) as i64)),
        (
            "hint".into(),
            Value::Str("Use head/tail for specific line ranges".into()),
        ),
    ])))
}

/// tee — Write input to both a file and return it (cross-platform, native Rust).
/// Usage: tee(file_path, text) or piped: text | tee(file_path)
fn bi_tee_output(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = crate::safety::resolve_path_str(&expect_string(
        "tee",
        args.first()
            .ok_or_else(|| crate::safety::arg_err("tee requires path"))?,
    )?);
    let (value, options) = match input {
        Some(value) => {
            if args.len() > 2 {
                return Err(crate::safety::arg_err(
                    "piped tee accepts path and optional options only",
                ));
            }
            (value, args.get(1))
        }
        None => (
            args.get(1)
                .cloned()
                .ok_or_else(|| crate::safety::arg_err("tee requires data"))?,
            args.get(2),
        ),
    };
    let mut append = false;
    if let Some(options) = options {
        let Value::Record(record) = options else {
            return Err(crate::safety::arg_err("tee options must be Record"));
        };
        for (key, value) in record {
            if key != "append" {
                return Err(crate::safety::arg_err(format!("tee unknown option {key}")));
            }
            let Value::Bool(flag) = value else {
                return Err(crate::safety::arg_err("tee append must be Bool"));
            };
            append = *flag;
        }
    }
    let text = match value {
        Value::Str(text) => text,
        other => format!("{other}"),
    };
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "tee_output",
        effect: crate::safety::Effect::WriteLocal,
        what: if append { "append" } else { "write" },
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({"bytes":text.len()}),
        reversible: true,
        fs_paths: true,
    })?;
    crate::tx::snapshot(&path);
    if append {
        use std::io::Write;
        let mut file = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
            .map_err(|e| crate::safety::fs_error("tee", &path, &e))?;
        file.write_all(text.as_bytes())
            .map_err(|e| crate::safety::fs_error("tee", &path, &e))?;
    } else {
        write_file_atomically("tee", &path, text.as_bytes())?;
    }
    Ok(Value::Str(text))
}

/// Longest tmux or screen session name.
const DEVTOOL_MAX_NAME: usize = 64;
/// Longest tmux target: a session, or session:window.pane.
const DEVTOOL_MAX_TARGET: usize = 256;
/// Longest key text sent to a session in one call.
const DEVTOOL_MAX_KEYS: usize = 4096;
/// Longest single argument passed through to a dev tool.
const DEVTOOL_MAX_ARG: usize = 4096;
/// Most items in any list an options Record or a call takes (cmake defines,
/// gdb commands, recipe arguments).
const DEVTOOL_MAX_ITEMS: usize = 256;
/// Longest single gdb command line.
const DEVTOOL_MAX_GDB_LINE: usize = 512;
/// Most parallel jobs a build may ask for.
const DEVTOOL_MAX_JOBS: i64 = 1024;

/// The process's working directory, as a dev tool would inherit it.
fn devtool_cwd(builtin: &str) -> Result<std::path::PathBuf> {
    std::env::current_dir().map_err(|e| crate::safety::fs_error(builtin, ".", &e))
}

/// A directory a dev tool runs in: `value` (default: the process's directory)
/// resolved against the process's directory, required to lie inside the
/// workspace, and required to exist as a directory.
fn devtool_dir(builtin: &str, value: Option<&str>) -> Result<std::path::PathBuf> {
    let cwd = devtool_cwd(builtin)?;
    let dir = workspace_path(builtin, value.unwrap_or("."), &cwd)?;
    if !dir.is_dir() {
        return Err(crate::safety::not_found(
            builtin,
            "directory",
            &dir.display().to_string(),
        ));
    }
    Ok(dir)
}

/// The options Record at `index`, when one is given. Only the keys in
/// `allowed` are accepted; any other key is refused by name, so no option is
/// silently ignored.
fn devtool_options<'a>(
    builtin: &str,
    args: &'a [Value],
    index: usize,
    allowed: &[&str],
) -> Result<Option<&'a BTreeMap<String, Value>>> {
    match args.get(index) {
        None => Ok(None),
        Some(Value::Record(map)) => {
            if let Some(key) = map.keys().find(|k| !allowed.contains(&k.as_str())) {
                return Err(crate::safety::arg_err(format!(
                    "{builtin}: unknown option '{key}'; the options are {}",
                    allowed.join(", ")
                )));
            }
            Ok(Some(map))
        }
        Some(other) => Err(crate::safety::arg_err(format!(
            "{builtin}: options must be a Record, got {}",
            other.type_name()
        ))),
    }
}

/// A String option, checked, when it is present.
fn devtool_opt_str(
    builtin: &str,
    what: &str,
    options: Option<&BTreeMap<String, Value>>,
    key: &str,
    check: K8sCheck,
) -> Result<Option<String>> {
    match options.and_then(|o| o.get(key)) {
        None => Ok(None),
        Some(Value::Str(s)) => check(builtin, what, s).map(Some),
        Some(other) => Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be a String, got {}",
            other.type_name()
        ))),
    }
}

/// An Int option, range-checked, when it is present.
fn devtool_opt_int(
    builtin: &str,
    what: &str,
    options: Option<&BTreeMap<String, Value>>,
    key: &str,
    lo: i64,
    hi: i64,
) -> Result<Option<i64>> {
    match options.and_then(|o| o.get(key)) {
        None => Ok(None),
        Some(Value::Int(n)) if (lo..=hi).contains(n) => Ok(Some(*n)),
        Some(Value::Int(n)) => Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be {lo}..={hi}, got {n}"
        ))),
        Some(other) => Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be an Int, got {}",
            other.type_name()
        ))),
    }
}

/// A tmux or screen session name: 1-64 letters, digits, '-' or '_'. Colons and
/// dots are refused because tmux reads them as target separators, and a
/// leading '-' is refused as an option.
fn devtool_session(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.len() <= DEVTOOL_MAX_NAME
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_');
    if !well_formed {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is 1-{DEVTOOL_MAX_NAME} letters, digits, '-' or '_' (got {value:?})"
        )));
    }
    Ok(value.to_string())
}

/// A tmux target: a session, or session:window.pane. One word, not option-like.
fn devtool_target(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    let well_formed = !value.is_empty()
        && value.len() <= DEVTOOL_MAX_TARGET
        && !value.chars().any(|c| c.is_whitespace() || c.is_control());
    if !well_formed {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is one word of at most {DEVTOOL_MAX_TARGET} characters (got {value:?})"
        )));
    }
    Ok(value.to_string())
}

/// Keys typed into a session: one line, no control characters (each newline
/// would be a second command), not option-like.
fn devtool_keys(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    if value.is_empty() || value.len() > DEVTOOL_MAX_KEYS || value.chars().any(char::is_control) {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is one line of 1-{DEVTOOL_MAX_KEYS} bytes with no control characters"
        )));
    }
    Ok(value.to_string())
}

/// A tool-and-version spec such as `node@20`: one word, not option-like.
fn devtool_tool_spec(builtin: &str, what: &str, value: &str) -> Result<String> {
    if value.chars().any(char::is_whitespace) {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is one word such as node@20 (got {value:?})"
        )));
    }
    tf_plain(builtin, what, value)
}

/// A string argument that goes to a tool as data: no NUL byte.
fn devtool_text_arg(builtin: &str, what: &str, value: &str) -> Result<String> {
    if value.contains('\0') {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must not contain a NUL byte"
        )));
    }
    Ok(value.to_string())
}

/// A word passed to a dev tool as one recipe or program argument. A leading
/// '-' is refused, because the tool would read it as an option.
fn devtool_word(builtin: &str, what: &str, value: &str) -> Result<String> {
    crate::safety::reject_option_like(builtin, &[value.to_string()])?;
    if value.len() > DEVTOOL_MAX_ARG || value.contains('\0') {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is at most {DEVTOOL_MAX_ARG} bytes with no NUL byte"
        )));
    }
    Ok(value.to_string())
}

/// A gdb command script, one command per line. Each line becomes one `-ex`
/// argument. gdb can run shell commands, so the call is approval-gated as an
/// exec by the central gate.
fn devtool_gdb_commands(builtin: &str, text: &str) -> Result<Vec<String>> {
    let lines: Vec<String> = text
        .lines()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty())
        .collect();
    if lines.is_empty() {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: commands must contain at least one gdb command"
        )));
    }
    if lines.len() > DEVTOOL_MAX_ITEMS {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: at most {DEVTOOL_MAX_ITEMS} gdb commands, got {}",
            lines.len()
        )));
    }
    if let Some(long) = lines.iter().find(|l| l.len() > DEVTOOL_MAX_GDB_LINE) {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: a gdb command is at most {DEVTOOL_MAX_GDB_LINE} bytes, got {}",
            long.len()
        )));
    }
    Ok(lines)
}

/// `-Dname=value` for each define in a cmake defines Record. Names are letters,
/// digits and `_.-`; values are String, Int or Bool (ON/OFF).
fn devtool_defines(builtin: &str, value: &Value) -> Result<Vec<String>> {
    let defs = match value {
        Value::Record(map) => map,
        other => {
            return Err(crate::safety::arg_err(format!(
                "{builtin}: defines must be a Record, got {}",
                other.type_name()
            )))
        }
    };
    if defs.len() > DEVTOOL_MAX_ITEMS {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: at most {DEVTOOL_MAX_ITEMS} defines, got {}",
            defs.len()
        )));
    }
    let mut out = Vec::with_capacity(defs.len());
    for (key, val) in defs {
        let well_formed = !key.is_empty()
            && key.len() <= 128
            && !key.starts_with('-')
            && key
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || "_.-".contains(c));
        if !well_formed {
            return Err(crate::safety::arg_err(format!(
                "{builtin}: a define name is letters, digits and _.- and does not start with '-' (got {key:?})"
            )));
        }
        let text = match val {
            Value::Str(s) => s.clone(),
            Value::Int(n) => n.to_string(),
            Value::Bool(b) => (if *b { "ON" } else { "OFF" }).to_string(),
            other => {
                return Err(crate::safety::arg_err(format!(
                    "{builtin}: define {key} must be a String, Int or Bool, got {}",
                    other.type_name()
                )))
            }
        };
        devtool_text_arg(builtin, "a define value", &text)?;
        out.push(format!("-D{key}={text}"));
    }
    Ok(out)
}

/// A file read whole, at most `TOOL_MAX_TEXT` bytes. A larger file is refused
/// rather than read in part, and a missing one is E_NOT_FOUND.
fn devtool_read_text(builtin: &str, kind: &str, path: &str) -> Result<String> {
    use std::io::Read;
    let file = std::fs::File::open(path).map_err(|e| devtool_io(builtin, kind, path, &e))?;
    let mut bytes = Vec::new();
    file.take(TOOL_MAX_TEXT as u64 + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| devtool_io(builtin, kind, path, &e))?;
    if bytes.len() > TOOL_MAX_TEXT {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{path}` is larger than {TOOL_MAX_TEXT} bytes"),
            "point this at a smaller file",
        ));
    }
    Ok(String::from_utf8_lossy(&bytes).into_owned())
}

/// An I/O failure on a named file: NotFound is E_NOT_FOUND, anything else is
/// the file system's own coded error.
fn devtool_io(builtin: &str, kind: &str, path: &str, e: &std::io::Error) -> anyhow::Error {
    if e.kind() == std::io::ErrorKind::NotFound {
        crate::safety::not_found(builtin, kind, path)
    } else {
        crate::safety::fs_error(builtin, path, e)
    }
}

/// A finished call that must have succeeded. A nonzero exit is E_TOOL_FAILED
/// with the tail of its stderr.
fn finished(builtin: &str, run: ToolRun) -> Result<ToolRun> {
    if run.success {
        return Ok(run);
    }
    let tail = tail_text(&run.stderr, TOOL_STDERR_TAIL);
    Err(crate::safety::tool_failed(
        builtin,
        &run.command,
        run.code,
        &tail,
    ))
}

/// The last `max` bytes of `text`, cut on a character boundary.
fn tail_text(text: &str, max: usize) -> String {
    if text.len() <= max {
        return text.to_string();
    }
    let mut start = text.len() - max;
    while !text.is_char_boundary(start) {
        start += 1;
    }
    text[start..].to_string()
}

/// The fields every successful dev-tool record carries. The output keys are
/// named by the caller, because each builtin has always named them its own
/// way; `output_truncated` says when the stdout kept was only its tail.
fn run_fields(run: ToolRun, out_key: &str, err_key: &str) -> BTreeMap<String, Value> {
    let mut rec = BTreeMap::new();
    // No code means the process was killed by a signal (the deadline is
    // refused before this). It was `0`, which read as a clean exit.
    rec.insert(
        "exit_code".to_string(),
        match run.code {
            Some(code) => Value::Int(code as i64),
            None => Value::Null,
        },
    );
    rec.insert("success".to_string(), Value::Bool(run.success));
    if run.stdout_truncated {
        rec.insert("output_truncated".to_string(), Value::Bool(true));
    }
    rec.insert(out_key.to_string(), Value::Str(run.stdout));
    rec.insert(err_key.to_string(), Value::Str(run.stderr));
    rec
}

/// An interactive attach needs a terminal on both ends. Agent mode has no
/// human to attach, and without a terminal the attach could only hang or fail,
/// so both are refused as E_NO_UI before anything is spawned.
fn devtool_terminal(builtin: &str) -> Result<()> {
    crate::safety::refuse_if_headless(builtin)?;
    use std::io::IsTerminal;
    if std::io::stdin().is_terminal() && std::io::stdout().is_terminal() {
        Ok(())
    } else {
        Err(crate::safety::no_ui(builtin))
    }
}

/// Run an attach with the terminal's streams inherited, so the user is the one
/// talking to the session. Only called after [`devtool_terminal`].
fn devtool_attach(builtin: &str, program: &str, args: &[&str], label: &str) -> Result<()> {
    let status = std::process::Command::new(program)
        .args(args)
        .status()
        .map_err(|e| crate::safety::spawn_error(builtin, program, &e))?;
    if status.success() {
        Ok(())
    } else {
        Err(crate::safety::tool_failed(
            builtin,
            label,
            status.code(),
            "its messages went to this terminal",
        ))
    }
}

/// The lines of a list-style tool output: trimmed, non-empty, kept in order.
fn devtool_lines(text: &str) -> Vec<Value> {
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .map(|l| Value::Str(l.to_string()))
        .collect()
}

/// valgrind under memcheck with the given flags. Its report is on stderr, so
/// that is the stream kept at the larger size; a nonzero exit is E_TOOL_FAILED
/// with the tail of that report.
fn devtool_valgrind(
    builtin: &str,
    flags: &[&str],
    args: &[Value],
    input: Option<Value>,
) -> Result<Value> {
    k8s_no_input(builtin, &input)?;
    let command = k8s_need(builtin, "program", args, 0, tf_plain)?;
    let mut argv: Vec<&str> = flags.to_vec();
    argv.push(command.as_str());
    let run = tool_run_stderr(
        builtin,
        "valgrind",
        None,
        &argv,
        Keep::Tail(TOOL_KEEP_TAIL),
        TOOL_KEEP_TAIL,
        TOOL_LONG_DEADLINE_SECS,
    )?;
    let mut rec = run_fields(finished(builtin, run)?, "stdout", "report");
    rec.insert("command".to_string(), Value::Str(command));
    Ok(Value::Record(rec))
}
/// make — Run one make target, or the default goal.
/// Usage: make_run() or make_run(target) or make_run(target, {dir?, file?, jobs?})
/// The target is one argv element, never a shell line, and it may not start
/// with '-'. `dir` and `file` must lie inside the workspace. Output keeps its
/// last 256 KiB. A nonzero exit is E_TOOL_FAILED. Effect Exec: a Makefile runs
/// its recipes.
fn bi_make_run(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("make_run", &input)?;
    let target = k8s_arg("make_run", "target", &args, 0, tf_plain)?;
    let options = devtool_options("make_run", &args, 1, &["dir", "file", "jobs"])?;
    let dir_opt = devtool_opt_str("make_run", "dir", options, "dir", tf_plain)?;
    let file_opt = devtool_opt_str("make_run", "file", options, "file", tf_plain)?;
    let jobs = devtool_opt_int("make_run", "jobs", options, "jobs", 1, DEVTOOL_MAX_JOBS)?;
    let dir = devtool_dir("make_run", dir_opt.as_deref())?;
    let file = match &file_opt {
        Some(f) => Some(workspace_path("make_run", f, &dir)?),
        None => None,
    };
    if let Some(f) = &file {
        if !f.is_file() {
            return Err(crate::safety::not_found(
                "make_run",
                "makefile",
                &f.display().to_string(),
            ));
        }
    }
    let mut argv: Vec<String> = Vec::new();
    if let Some(f) = &file {
        argv.push("-f".to_string());
        argv.push(f.display().to_string());
    }
    if let Some(j) = jobs {
        argv.push(format!("-j{j}"));
    }
    if let Some(t) = &target {
        argv.push(t.clone());
    }
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = finished(
        "make_run",
        tool_run(
            "make_run",
            "make",
            Some(dir.as_path()),
            &refs,
            Keep::Tail(TOOL_KEEP_TAIL),
            TOOL_LONG_DEADLINE_SECS,
        )?,
    )?;
    let mut rec = run_fields(run, "stdout", "stderr");
    if let Some(t) = target {
        rec.insert("target".to_string(), Value::Str(t));
    }
    Ok(Value::Record(rec))
}

/// make — List the targets a Makefile names, read natively without running make.
/// Usage: make_targets() or make_targets(makefile_path)
/// A missing file is E_NOT_FOUND; a file over 4 MiB is refused.
fn bi_make_targets(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("make_targets", &input)?;
    let makefile = k8s_arg("make_targets", "makefile path", &args, 0, tf_plain)?
        .unwrap_or_else(|| "Makefile".to_string());
    let content = devtool_read_text("make_targets", "makefile", &makefile)?;
    let re = regex::Regex::new(r"^([a-zA-Z_][a-zA-Z0-9_.-]*)\s*:").unwrap();
    let targets: Vec<Value> = content
        .lines()
        .filter_map(|line| re.captures(line).map(|cap| Value::Str(cap[1].to_string())))
        .collect();
    Ok(Value::Array(targets))
}

/// cmake — Configure a build directory from a source directory.
/// Usage: cmake_configure(source_dir) or cmake_configure(source_dir, build_dir, {generator?, defines?})
/// Both directories default to "." and "build" and must lie inside the
/// workspace; the build directory is created when missing. A define is
/// `-Dname=value`, one argument each. Configure runs the project's CMakeLists
/// code, yet the effect table classes cmake_configure as write_local, so the
/// central gate does not ask for approval; that classification is reported,
/// not changed here. A nonzero exit is
/// E_TOOL_FAILED. Takes no pipeline input.
fn bi_cmake_configure(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("cmake_configure", &input)?;
    let source = k8s_arg("cmake_configure", "source directory", &args, 0, tf_plain)?;
    let build = k8s_arg("cmake_configure", "build directory", &args, 1, tf_plain)?
        .unwrap_or_else(|| "build".to_string());
    let options = devtool_options("cmake_configure", &args, 2, &["generator", "defines"])?;
    let generator = devtool_opt_str(
        "cmake_configure",
        "generator",
        options,
        "generator",
        tf_plain,
    )?;
    let defines = match options.and_then(|o| o.get("defines")) {
        Some(v) => devtool_defines("cmake_configure", v)?,
        None => Vec::new(),
    };
    let source_dir = devtool_dir("cmake_configure", source.as_deref())?;
    let cwd = devtool_cwd("cmake_configure")?;
    let build_dir = workspace_path("cmake_configure", &build, &cwd)?;
    let mut argv: Vec<String> = vec![
        "-S".to_string(),
        source_dir.display().to_string(),
        "-B".to_string(),
        build_dir.display().to_string(),
    ];
    if let Some(g) = generator {
        argv.push("-G".to_string());
        argv.push(g);
    }
    argv.extend(defines);
    std::fs::create_dir_all(&build_dir)
        .map_err(|e| crate::safety::fs_error("cmake_configure", &build_dir, &e))?;
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = finished(
        "cmake_configure",
        tool_run(
            "cmake_configure",
            "cmake",
            None,
            &refs,
            Keep::Tail(TOOL_KEEP_TAIL),
            TOOL_LONG_DEADLINE_SECS,
        )?,
    )?;
    let mut rec = run_fields(run, "stdout", "stderr");
    rec.insert(
        "source_dir".to_string(),
        Value::Str(source_dir.display().to_string()),
    );
    rec.insert(
        "build_dir".to_string(),
        Value::Str(build_dir.display().to_string()),
    );
    Ok(Value::Record(rec))
}

/// cmake — Build a configured CMake build directory.
/// Usage: cmake_build(build_dir) or cmake_build(build_dir, {target?, config?, jobs?})
/// The build directory must exist and lie inside the workspace. Options are
/// one argument each and may not start with '-'. Runs the project's build
/// steps, so its effect is Exec. A nonzero exit is E_TOOL_FAILED.
fn bi_cmake_build(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("cmake_build", &input)?;
    let build = k8s_arg("cmake_build", "build directory", &args, 0, tf_plain)?
        .unwrap_or_else(|| "build".to_string());
    let options = devtool_options("cmake_build", &args, 1, &["target", "config", "jobs"])?;
    let target = devtool_opt_str("cmake_build", "target", options, "target", tf_plain)?;
    let config = devtool_opt_str("cmake_build", "config", options, "config", tf_plain)?;
    let jobs = devtool_opt_int("cmake_build", "jobs", options, "jobs", 1, DEVTOOL_MAX_JOBS)?;
    let dir = devtool_dir("cmake_build", Some(build.as_str()))?;
    let mut argv: Vec<String> = vec!["--build".to_string(), dir.display().to_string()];
    if let Some(t) = &target {
        argv.push("--target".to_string());
        argv.push(t.clone());
    }
    if let Some(c) = &config {
        argv.push("--config".to_string());
        argv.push(c.clone());
    }
    if let Some(j) = jobs {
        argv.push("-j".to_string());
        argv.push(j.to_string());
    }
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = finished(
        "cmake_build",
        tool_run(
            "cmake_build",
            "cmake",
            None,
            &refs,
            Keep::Tail(TOOL_KEEP_TAIL),
            TOOL_LONG_DEADLINE_SECS,
        )?,
    )?;
    let mut rec = run_fields(run, "stdout", "stderr");
    rec.insert(
        "build_dir".to_string(),
        Value::Str(dir.display().to_string()),
    );
    Ok(Value::Record(rec))
}

// ---------------------------------------------------------------------------
// Lint, format and search builtins: the checks and bounded results they share
// ---------------------------------------------------------------------------

/// The most results one search returns. A search with more is refused with
/// E_BUDGET_EXCEEDED, because a list cut at a cap reads as the whole answer.
const SEARCH_MAX_RESULTS: usize = 1000;
/// The most bytes of one text file a content search reads.
const SEARCH_MAX_FILE: u64 = 64 * 1024 * 1024;
/// The leading bytes a content search inspects for a NUL, as `grep -I` does.
const SEARCH_BINARY_PROBE: u64 = 8000;

/// A search pattern or other search text: non-empty, no NUL byte. It reaches
/// the tool as `--regexp=` or as a value, so a leading '-' is data, not a flag.
fn search_text_check(builtin: &str, what: &str, value: &str) -> Result<String> {
    if value.is_empty() || value.contains('\0') {
        return Err(crate::safety::arg_err(format!(
            "{builtin}: {what} must be a non-empty string with no NUL byte"
        )));
    }
    Ok(value.to_string())
}

/// The refusal for a search whose results would pass the cap.
fn search_budget(builtin: &str) -> anyhow::Error {
    crate::safety::budget_exceeded(
        builtin,
        format!("more than {SEARCH_MAX_RESULTS} results"),
        "narrow the pattern or the path so that fewer results match",
    )
}

/// Found paths or lines as the Array a search returns, refused past the cap.
fn search_list(builtin: &str, found: Vec<String>) -> Result<Value> {
    if found.len() > SEARCH_MAX_RESULTS {
        return Err(search_budget(builtin));
    }
    Ok(Value::Array(found.into_iter().map(Value::Str).collect()))
}

/// The stdout of a tool whose exit 1 is an answer rather than a failure: ripgrep
/// (and rga, which runs it) exit 1 for "no matches", mypy for "type errors".
/// Any other nonzero exit is E_TOOL_FAILED with the stderr tail.
fn stdout_with_exit1(builtin: &str, mut run: ToolRun) -> Result<String> {
    if run.code == Some(1) {
        run.success = true;
    }
    tool_text(builtin, run)
}

/// A tool whose exit 0 and exit `answer` both print a JSON report, which is the
/// answer. Any other exit is E_TOOL_FAILED, and output that is not JSON is too.
fn findings_json(builtin: &str, mut run: ToolRun, answer: i32) -> Result<Value> {
    if run.code == Some(answer) {
        run.success = true;
    }
    let command = run.command.clone();
    let code = run.code;
    let stderr = run.stderr.clone();
    let text = tool_text(builtin, run)?;
    serde_json::from_str::<serde_json::Value>(&text)
        .map(json_to_value)
        .map_err(|e| {
            let detail = if stderr.is_empty() {
                format!("printed output that is not JSON ({e})")
            } else {
                stderr
            };
            crate::safety::tool_failed(builtin, &command, code, &detail)
        })
}

/// Writes `bytes` to a new file, in a new directory under the system temporary
/// directory, for a tool that reads its input from a file rather than a pipe.
/// The caller removes the directory with [`scratch_remove`].
fn scratch_file(builtin: &str, file_name: &str, bytes: &[u8]) -> Result<std::path::PathBuf> {
    let dir = std::env::temp_dir().join(format!("ae_{builtin}_{}", uuid::Uuid::new_v4().simple()));
    std::fs::create_dir(&dir).map_err(|e| crate::safety::fs_error(builtin, &dir, &e))?;
    let file = dir.join(file_name);
    if let Err(e) = std::fs::write(&file, bytes) {
        scratch_remove(&file);
        return Err(crate::safety::fs_error(builtin, &file, &e));
    }
    Ok(file)
}

/// Removes the directory that [`scratch_file`] made for `file`.
fn scratch_remove(file: &std::path::Path) {
    if let Some(dir) = file.parent() {
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// An fd entry kind: one of fd's type letters.
fn fd_kind_check(builtin: &str, what: &str, value: &str) -> Result<String> {
    match value {
        "f" | "d" | "l" | "x" | "e" | "s" | "p" => Ok(value.to_string()),
        _ => Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is one of f, d, l, x, e, s, p (got {value:?})"
        ))),
    }
}

/// A file extension for fd: letters, digits and `_+-`, not starting with '-'.
fn fd_ext_check(builtin: &str, what: &str, value: &str) -> Result<String> {
    let well_formed = !value.is_empty()
        && value.len() <= 32
        && !value.starts_with('-')
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "_+-".contains(c));
    if well_formed {
        Ok(value.to_string())
    } else {
        Err(crate::safety::arg_err(format!(
            "{builtin}: {what} is an extension such as rs (letters, digits and _+- only), got {value:?}"
        )))
    }
}

/// The text of one file that a content search reads. A file with a NUL in its
/// first bytes is binary and is skipped, as `grep -I` skips it. A text file past
/// the size limit is refused rather than read in part.
fn search_read_text(builtin: &str, path: &std::path::Path, shown: &str) -> Result<Option<String>> {
    use std::io::Read;
    let mut file =
        std::fs::File::open(path).map_err(|e| crate::safety::fs_error(builtin, shown, &e))?;
    let mut bytes = Vec::new();
    (&mut file)
        .take(SEARCH_BINARY_PROBE)
        .read_to_end(&mut bytes)
        .map_err(|e| crate::safety::fs_error(builtin, shown, &e))?;
    if bytes.contains(&0) {
        return Ok(None);
    }
    (&mut file)
        .take(SEARCH_MAX_FILE + 1 - bytes.len() as u64)
        .read_to_end(&mut bytes)
        .map_err(|e| crate::safety::fs_error(builtin, shown, &e))?;
    if bytes.len() as u64 > SEARCH_MAX_FILE {
        return Err(crate::safety::budget_exceeded(
            builtin,
            format!("`{shown}` is larger than {} MiB", SEARCH_MAX_FILE >> 20),
            "search a narrower directory",
        ));
    }
    Ok(Some(String::from_utf8_lossy(&bytes).into_owned()))
}

fn search_pattern_builtin(builtin: &str, args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input(builtin, &input)?;
    k8s_max_args(builtin, &args, 1)?;
    let pattern = k8s_need(builtin, "a regular expression", &args, 0, search_text_check)?;
    let found = search_grep(builtin, &pattern)?;
    search_list(builtin, found)
}

/// ninja — Fast build system.
/// Usage: ninja_build() or ninja_build({dir?, target?, jobs?})
fn bi_ninja_build(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "ninja_build";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 1)?;
    let mut dir = None;
    let mut options = None;
    match args.first() {
        None => {}
        Some(Value::Str(d)) => dir = Some(pkg_plain(B, "dir", d)?),
        Some(_) => options = devtool_options(B, &args, 0, &["dir", "target", "jobs"])?,
    }
    if dir.is_none() {
        dir = devtool_opt_str(B, "dir", options, "dir", pkg_plain)?;
    }
    let target = devtool_opt_str(B, "target", options, "target", pkg_plain)?;
    let jobs = devtool_opt_int(B, "jobs", options, "jobs", 1, DEVTOOL_MAX_JOBS)?;
    let workdir = devtool_dir(B, dir.as_deref())?;
    let mut argv: Vec<String> = Vec::new();
    if let Some(j) = jobs {
        argv.push(format!("-j{j}"));
    }
    if let Some(t) = target {
        argv.push(t);
    }
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = tool_run(
        B,
        "ninja",
        Some(workdir.as_path()),
        &refs,
        Keep::Tail(TOOL_KEEP_TAIL),
        TOOL_LONG_DEADLINE_SECS,
    )?;
    pkg_done(B, run, Vec::new())
}

/// netstat — Display network connections and socket information (cross-platform).
/// Usage: netstat() or netstat({proto?, state?, port?})
fn bi_netstat_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let flags = if cfg!(target_os = "windows") {
        vec!["-an".to_string()]
    } else {
        vec!["-tuln".to_string()]
    };
    let mut cmd = std::process::Command::new("netstat");
    cmd.args(&flags);
    let out = bounded_cmd_output("netstat", "netstat", cmd, PROBE_DEADLINE_SECS)?;
    if !out.status.success() {
        return Err(crate::safety::tool_failed(
            "netstat",
            "netstat",
            out.status.code(),
            &String::from_utf8_lossy(&out.stderr),
        ));
    }
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
    // Parse netstat output into structured records
    let filter_proto = match args.first() {
        Some(Value::Record(r)) => r.get("proto").and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        }),
        _ => None,
    };
    let filter_state = match args.first() {
        Some(Value::Record(r)) => r.get("state").and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.to_uppercase())
            } else {
                None
            }
        }),
        _ => None,
    };
    let filter_port = match args.first() {
        Some(Value::Record(r)) => r.get("port").and_then(|v| {
            if let Value::Int(n) = v {
                Some(*n)
            } else {
                None
            }
        }),
        _ => None,
    };
    let mut connections = Vec::new();
    for line in stdout.lines().skip(2) {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 4 {
            continue;
        }
        let proto = parts[0].to_string();
        let local_addr = if parts.len() > 3 {
            parts[3].to_string()
        } else {
            parts[1].to_string()
        };
        let foreign_addr = if parts.len() > 4 {
            parts[4].to_string()
        } else {
            parts[2].to_string()
        };
        let state = if parts.len() > 5 {
            parts[5].to_string()
        } else {
            String::new()
        };
        // Apply filters
        if let Some(ref fp) = filter_proto {
            if !proto.to_lowercase().contains(&fp.to_lowercase()) {
                continue;
            }
        }
        if let Some(ref fs) = filter_state {
            if !state.to_uppercase().contains(fs) {
                continue;
            }
        }
        if let Some(fp) = filter_port {
            let port_str = format!(":{}", fp);
            if !local_addr.contains(&port_str) && !foreign_addr.contains(&port_str) {
                continue;
            }
        }
        let mut rec = BTreeMap::new();
        rec.insert("proto".to_string(), Value::Str(proto));
        rec.insert("local_address".to_string(), Value::Str(local_addr));
        rec.insert("foreign_address".to_string(), Value::Str(foreign_addr));
        if !state.is_empty() {
            rec.insert("state".to_string(), Value::Str(state));
        }
        connections.push(Value::Record(rec));
    }
    Ok(Value::Array(connections))
}

/// nmap — Network port scanning.
/// Usage: nmap_scan(host) or nmap_scan(host, {ports?, flags?}). ports is a list
/// such as "22,80,1000-1100" with every port in 1..=65535. flags is a
/// whitespace-separated list drawn from NMAP_FLAGS; any other flag is refused by
/// policy, because nmap's other options run scripts or write files. The host may
/// not begin with '-'. Returns {host, ports}, one Record per port, with its
/// state and service. A nonzero exit is E_TOOL_FAILED; a missing nmap is E_TOOL_MISSING.
fn bi_nmap_scan(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("nmap_scan")?;
    k8s_no_input("nmap_scan", &input)?;
    k8s_max_args("nmap_scan", &args, 2)?;
    let host = k8s_need("nmap_scan", "a host", &args, 0, net_target_host)?;
    let options = devtool_options("nmap_scan", &args, 1, &["ports", "flags"])?;
    let ports = devtool_opt_str("nmap_scan", "ports", options, "ports", nmap_ports)?;
    let flags = devtool_opt_str("nmap_scan", "flags", options, "flags", nmap_flags)?;
    let mut argv: Vec<String> = vec!["-oX".to_string(), "-".to_string()];
    if let Some(p) = ports {
        argv.push("-p".to_string());
        argv.push(p);
    }
    if let Some(f) = flags {
        argv.extend(f.split_whitespace().map(str::to_string));
    }
    argv.push(host.clone());
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = tool_run(
        "nmap_scan",
        "nmap",
        None,
        &refs,
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_LONG_DEADLINE_SECS,
    )?;
    let xml = tool_text("nmap_scan", run)?;
    let mut port_rows: Vec<Value> = Vec::new();
    for line in xml.lines() {
        let line = line.trim();
        if line.starts_with("<port ") {
            let mut rec = BTreeMap::new();
            if let Some(portid) = extract_xml_attr(line, "portid") {
                rec.insert(
                    "port".to_string(),
                    portid.parse::<i64>().map_or(Value::Null, Value::Int),
                );
            }
            if let Some(proto) = extract_xml_attr(line, "protocol") {
                rec.insert("protocol".to_string(), Value::Str(proto));
            }
            port_rows.push(Value::Record(rec));
        }
        if line.starts_with("<state ") {
            if let Some(Value::Record(rec)) = port_rows.last_mut() {
                if let Some(state) = extract_xml_attr(line, "state") {
                    rec.insert("state".to_string(), Value::Str(state));
                }
                if let Some(reason) = extract_xml_attr(line, "reason") {
                    rec.insert("reason".to_string(), Value::Str(reason));
                }
            }
        }
        if line.starts_with("<service ") {
            if let Some(Value::Record(rec)) = port_rows.last_mut() {
                if let Some(name) = extract_xml_attr(line, "name") {
                    rec.insert("service".to_string(), Value::Str(name));
                }
            }
        }
    }
    let mut result = BTreeMap::new();
    result.insert("host".to_string(), Value::Str(host));
    result.insert("ports".to_string(), Value::Array(port_rows));
    Ok(Value::Record(result))
}

/// nmap — Quick scan of the common ports, open ones only.
/// Usage: nmap_quick(host). The host may not begin with '-'. Returns {host,
/// ports, scan_type}. A nonzero exit is E_TOOL_FAILED; a missing nmap is E_TOOL_MISSING.
fn bi_nmap_quick(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("nmap_quick")?;
    k8s_no_input("nmap_quick", &input)?;
    k8s_max_args("nmap_quick", &args, 1)?;
    let host = k8s_need("nmap_quick", "a host", &args, 0, net_target_host)?;
    let run = tool_run(
        "nmap_quick",
        "nmap",
        None,
        &["-F", "--open", host.as_str()],
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_LONG_DEADLINE_SECS,
    )?;
    let stdout = tool_text("nmap_quick", run)?;
    let mut ports = Vec::new();
    for line in stdout.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 3 && parts[0].contains('/') {
            let port_proto: Vec<&str> = parts[0].split('/').collect();
            let mut rec = BTreeMap::new();
            rec.insert(
                "port".to_string(),
                port_proto[0].parse::<i64>().map_or(Value::Null, Value::Int),
            );
            rec.insert(
                "protocol".to_string(),
                Value::Str(port_proto.get(1).unwrap_or(&"").to_string()),
            );
            rec.insert("state".to_string(), Value::Str(parts[1].to_string()));
            rec.insert("service".to_string(), Value::Str(parts[2].to_string()));
            ports.push(Value::Record(rec));
        }
    }
    let mut result = BTreeMap::new();
    result.insert("host".to_string(), Value::Str(host));
    result.insert("ports".to_string(), Value::Array(ports));
    result.insert(
        "scan_type".to_string(),
        Value::Str("quick (-F --open)".to_string()),
    );
    Ok(Value::Record(result))
}

/// Helper: extract an XML attribute value from a tag line.
fn extract_xml_attr(line: &str, attr: &str) -> Option<String> {
    let pattern = format!("{}=\"", attr);
    if let Some(start) = line.find(&pattern) {
        let val_start = start + pattern.len();
        if let Some(end) = line[val_start..].find('"') {
            return Some(line[val_start..val_start + end].to_string());
        }
    }
    None
}
