// --- strings (1019) ---

/// strings — Extract printable strings from a binary file.
fn bi_strings_extract(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    // In-process on every OS, reading the file through the read checks. This
    // ran the `strings` program (absent on Windows, and handed the path
    // positionally) and fell back to this scan on any failure; the fallback's
    // errors were labelled `bat`; and a negative minimum became a huge usize,
    // so nothing matched.
    let path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "strings",
                "path: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let min_len = match args.get(1) {
        None => 4,
        Some(Value::Int(n)) if (1..=4096).contains(n) => *n as usize,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "strings",
                "a minimum length from 1 to 4096",
                &other.to_display_string(),
            ))
        }
    };
    let validated = validate_read_path(&path)?;
    let data = read_bytes_capped("strings", &validated)?;
    let mut result = Vec::new();
    let mut current = String::new();
    for &byte in &data {
        // Printable ASCII and tab, as GNU strings counts them.
        if (0x20..0x7f).contains(&byte) || byte == 0x09 {
            current.push(byte as char);
        } else {
            if current.len() >= min_len {
                result.push(Value::Str(std::mem::take(&mut current)));
            }
            current.clear();
        }
    }
    if current.len() >= min_len {
        result.push(Value::Str(current));
    }
    Ok(Value::Array(result))
}

// --- chgrp (1020) ---

/// chgrp — Change the group of one file.
/// Usage: chgrp(group, path). The group is a name or numeric id and may not begin
/// with '-'; the path must exist and is passed after `--`. The result is
/// {group, path}. A refusal by chgrp (unknown group, not permitted) is
/// E_TOOL_FAILED. On Windows the group is an account name set as the file's
/// primary group through the security API (see chgrp_windows).
///
/// It used to answer `success: false` as a value when chgrp refused, ignore
/// surplus arguments and pipeline input, and run with no deadline.
fn bi_chgrp(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("chgrp", &input)?;
    k8s_max_args("chgrp", &args, 2)?;
    let group = k8s_need("chgrp", "a group name", &args, 0, tf_plain)?;
    let path = match args.get(1) {
        Some(Value::Str(s)) if !s.is_empty() && !s.contains('\0') => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "chgrp",
                "path: a non-empty String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    #[cfg(windows)]
    {
        chgrp_windows(group, path)
    }
    #[cfg(not(windows))]
    {
        chgrp_unix(group, path)
    }
}

#[cfg(not(windows))]
fn chgrp_unix(group: String, path: String) -> Result<Value> {
    if std::fs::symlink_metadata(&path).is_err() {
        return Err(crate::safety::not_found("chgrp", "file", &path));
    }
    let run = tool_run(
        "chgrp",
        "chgrp",
        None,
        &["--", &group, &path],
        Keep::Tail(TOOL_STDERR_TAIL),
        TOOL_DEADLINE_SECS,
    )?;
    if !run.success {
        return Err(crate::safety::tool_failed(
            "chgrp",
            &run.command,
            run.code,
            &run.stderr,
        ));
    }
    let mut rec = BTreeMap::new();
    rec.insert("group".to_string(), Value::Str(group));
    rec.insert("path".to_string(), Value::Str(path));
    Ok(Value::Record(rec))
}

// --- mtr (1021) ---

/// mtr — Network diagnostic tool combining traceroute and ping.
/// Usage: mtr_trace(host) or mtr_trace(host, cycles). The host is a name or IP
/// literal and may not begin with '-'. cycles is 1..=100 and defaults to 5. The
/// result is {host, report}. A nonzero exit is E_TOOL_FAILED; a missing mtr is
/// E_TOOL_MISSING. The run has a 120 s deadline.
fn bi_mtr_trace(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("mtr_trace")?;
    k8s_no_input("mtr_trace", &input)?;
    k8s_max_args("mtr_trace", &args, 2)?;
    let host = k8s_need("mtr_trace", "a hostname", &args, 0, net_target_host)?;
    let cycles = match args.get(1) {
        None => 5,
        Some(Value::Int(n)) if (1..=100).contains(n) => *n,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "mtr_trace",
                "cycles: Int 1..=100",
                other.type_name(),
            ))
        }
    };
    let cycles_s = cycles.to_string();
    let run = tool_run(
        "mtr_trace",
        "mtr",
        None,
        &[
            "--report",
            "--report-cycles",
            cycles_s.as_str(),
            host.as_str(),
        ],
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_DEADLINE_SECS,
    )?;
    let report = tool_text("mtr_trace", run)?;
    let mut rec = BTreeMap::new();
    rec.insert("host".to_string(), Value::Str(host));
    rec.insert("report".to_string(), Value::Str(report.trim().to_string()));
    Ok(Value::Record(rec))
}

