// --- nc/netcat (1023-1024) ---

/// nc connect — Test whether a TCP port accepts a connection, using netcat.
/// Usage: nc_connect(host, port). The port is an Int 1..=65535 and the host is a
/// name or IP literal that may not begin with '-'. Returns {host, port, open,
/// output}. A refused or unanswered connection is open false: that is the answer.
/// Any other netcat failure is E_TOOL_FAILED, and a missing netcat is E_TOOL_MISSING.
fn bi_nc_connect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("nc_connect")?;
    k8s_no_input("nc_connect", &input)?;
    k8s_max_args("nc_connect", &args, 2)?;
    let host = k8s_need("nc_connect", "a host", &args, 0, net_target_host)?;
    let port = match args.get(1) {
        Some(Value::Int(n)) => net_port("nc_connect", *n)?,
        Some(other) => {
            return Err(crate::safety::bad_arg(
                "nc_connect",
                "port: Int 1..=65535",
                other.type_name(),
            ))
        }
        None => return Err(crate::safety::arg_err("nc_connect requires a port")),
    };
    let port_s = port.to_string();
    let run = tool_run_stderr(
        "nc_connect",
        "nc",
        None,
        &["-z", "-v", "-w", "5", host.as_str(), port_s.as_str()],
        Keep::Tail(NET_ERR_MAX),
        NET_ERR_MAX,
        TOOL_DEADLINE_SECS,
    )?;
    let text = format!("{}{}", run.stdout, run.stderr).trim().to_string();
    let open = if run.success {
        true
    } else if nc_refusal(&text) {
        false
    } else {
        return Err(crate::safety::tool_failed(
            "nc_connect",
            &run.command,
            run.code,
            &run.stderr,
        ));
    };
    let mut rec = BTreeMap::new();
    rec.insert("host".to_string(), Value::Str(host));
    rec.insert("port".to_string(), Value::Int(port));
    rec.insert("open".to_string(), Value::Bool(open));
    rec.insert("output".to_string(), Value::Str(text));
    Ok(Value::Record(rec))
}

/// nc_listen — accept one TCP connection on a port, read it to EOF or a byte
/// limit, then close both. Binds 127.0.0.1 unless `host` is given. The bind
/// address and the accepted peer pass the same network policy as net_listen,
/// and `timeout_ms` bounds the whole call (accept and read), so a stalled peer
/// is an E_IO error rather than a silent short read.
fn bi_nc_listen(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const NAME: &str = "nc_listen";
    if input.is_some() || !(1..=2).contains(&args.len()) {
        return Err(crate::safety::arg_err(
            "nc_listen requires a port and optional options Record, without pipeline input",
        ));
    }
    let mut args = args.into_iter();
    let port = match args.next() {
        Some(Value::Int(n)) if (1..=65535).contains(&n) => n as u16,
        _ => {
            return Err(crate::safety::arg_err(
                "nc_listen port must be an Int 1..65535",
            ))
        }
    };
    let mut host: std::net::IpAddr = std::net::Ipv4Addr::LOCALHOST.into();
    let mut timeout_ms: i64 = 1000;
    let mut max_bytes: i64 = 65536;
    if let Some(options) = args.next() {
        let Value::Record(fields) = options else {
            return Err(crate::safety::arg_err("nc_listen options must be a Record"));
        };
        for (key, value) in fields {
            match (key.as_str(), value) {
                ("host", Value::Str(text)) => {
                    host = text.parse().map_err(|_| {
                        crate::safety::arg_err(
                            "nc_listen host must be a literal IPv4 or IPv6 address; resolve hostnames separately",
                        )
                    })?;
                }
                ("timeout_ms", Value::Int(n)) if (1..=10000).contains(&n) => timeout_ms = n,
                ("max_bytes", Value::Int(n)) if (1..=1048576).contains(&n) => max_bytes = n,
                (other, _) => {
                    return Err(crate::safety::arg_err(format!(
                        "nc_listen unknown option or out-of-range value: {other} (options: host String, timeout_ms 1..10000, max_bytes 1..1048576)"
                    )))
                }
            }
        }
    }
    if crate::tx::is_active() {
        return Err(crate::safety::unimplemented(
            NAME,
            "network effects and reads cannot be rolled back",
            "finish the transaction first",
        ));
    }
    let addr = std::net::SocketAddr::new(host, port);
    guard_network(NAME, &format!("tcp://{addr}"))?;
    let io_timeout = crate::safety::bounded_io_timeout(
        NAME,
        std::time::Duration::from_millis(timeout_ms as u64),
    )?;
    let deadline = std::time::Instant::now() + io_timeout;
    let limit = max_bytes as usize;

    let listener = std::net::TcpListener::bind(addr).map_err(|e| nc_io_error(NAME, e))?;
    listener
        .set_nonblocking(true)
        .map_err(|e| nc_io_error(NAME, e))?;
    let (mut stream, peer) = loop {
        crate::safety::check_deadline()?;
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if remaining.is_zero() {
            return Err(nc_io_error(
                NAME,
                std::io::Error::new(
                    std::io::ErrorKind::TimedOut,
                    "no connection accepted before timeout",
                ),
            ));
        }
        match listener.accept() {
            Ok(pair) => break pair,
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                std::thread::sleep(remaining.min(std::time::Duration::from_millis(5)));
            }
            Err(e) => return Err(nc_io_error(NAME, e)),
        }
    };
    drop(listener);
    // The bind address does not authorize an arbitrary incoming peer.
    guard_network(NAME, &format!("tcp://{peer}"))?;
    stream
        .set_nonblocking(false)
        .map_err(|e| nc_io_error(NAME, e))?;

    let mut data: Vec<u8> = Vec::new();
    let mut chunk = [0u8; 8192];
    let mut truncated = false;
    loop {
        crate::safety::check_deadline()?;
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if remaining.is_zero() {
            return Err(nc_io_error(
                NAME,
                std::io::Error::new(
                    std::io::ErrorKind::TimedOut,
                    "read deadline exceeded before EOF",
                ),
            ));
        }
        stream
            .set_read_timeout(Some(remaining.min(std::time::Duration::from_millis(50))))
            .map_err(|e| nc_io_error(NAME, e))?;
        match std::io::Read::read(&mut stream, &mut chunk) {
            Ok(0) => break,
            Ok(n) => {
                // One byte past the limit proves more data existed, so truncated is exact.
                let room = limit + 1 - data.len();
                data.extend_from_slice(&chunk[..n.min(room)]);
                if data.len() > limit {
                    data.truncate(limit);
                    truncated = true;
                    break;
                }
            }
            Err(e)
                if matches!(
                    e.kind(),
                    std::io::ErrorKind::Interrupted
                        | std::io::ErrorKind::TimedOut
                        | std::io::ErrorKind::WouldBlock
                ) => {}
            Err(e) => return Err(nc_io_error(NAME, e)),
        }
    }
    drop(stream);

    let mut rec = BTreeMap::new();
    rec.insert("peer".to_string(), Value::Str(format!("tcp://{peer}")));
    rec.insert(
        "data".to_string(),
        Value::Str(String::from_utf8_lossy(&data).into_owned()),
    );
    rec.insert("bytes".to_string(), Value::Int(data.len() as i64));
    rec.insert("truncated".to_string(), Value::Bool(truncated));
    Ok(Value::Record(rec))
}

fn nc_io_error(name: &str, error: std::io::Error) -> anyhow::Error {
    anyhow::Error::new(crate::safety::SafetyError {
        code: crate::safety::ErrorCode::Io,
        builtin: name.into(),
        message: format!("{name}: {error}"),
        hint: "A timeout before EOF is an error, not a short read; the partial data was discarded."
            .into(),
        approval: None,
        did_you_mean: vec![],
        expected: "one complete TCP connection".into(),
        got: format!("{:?}", error.kind()),
    })
}

// --- socat (1025) ---

/// socat — Multipurpose relay between two outbound connections.
/// Usage: socat_relay(address1, address2), with addresses such as "TCP:host:port"
/// or "UDP4:host:port". Only TCP, TCP4, UDP and UDP4 connections to a host and
/// port are accepted, with no options; EXEC, SYSTEM and SHELL run programs, OPEN
/// and CREATE write files, and LISTEN forms open listeners, so they are refused.
/// The relay has a 120 s deadline and is killed at it, so no relay outlives the
/// call. Returns {addr1, addr2, stdout, stdout_truncated}.
fn bi_socat_relay(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    net_refuse_in_transaction("socat_relay")?;
    k8s_no_input("socat_relay", &input)?;
    if args.len() != 2 {
        return Err(crate::safety::arg_err(
            "socat_relay takes exactly two addresses",
        ));
    }
    let (Some(Value::Str(a)), Some(Value::Str(b))) = (args.first(), args.get(1)) else {
        return Err(crate::safety::arg_err(
            "socat_relay addresses must be Strings",
        ));
    };
    let first = socat_address("socat_relay", a)?;
    let second = socat_address("socat_relay", b)?;
    let run = tool_run_stderr(
        "socat_relay",
        "socat",
        None,
        &[first.as_str(), second.as_str()],
        Keep::Tail(TOOL_MAX_TEXT),
        NET_ERR_MAX,
        TOOL_DEADLINE_SECS,
    )?;
    let run = finished("socat_relay", run)?;
    let mut rec = BTreeMap::new();
    rec.insert("addr1".to_string(), Value::Str(first));
    rec.insert("addr2".to_string(), Value::Str(second));
    rec.insert(
        "stdout".to_string(),
        Value::Str(run.stdout.trim().to_string()),
    );
    rec.insert(
        "stdout_truncated".to_string(),
        Value::Bool(run.stdout_truncated),
    );
    Ok(Value::Record(rec))
}

