// --- just (1041-1042) ---

/// just — Run a recipe from the justfile in the process's directory.
/// Usage: just_run(recipe) or just_run(recipe, arg...)
/// The recipe and each argument are one word, not option-like, and at most 256
/// arguments are passed. A recipe runs project code, so its effect is Exec. A
/// nonzero exit is E_TOOL_FAILED.
fn bi_just_run(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("just_run", &input)?;
    let recipe = k8s_need("just_run", "recipe name", &args, 0, devtool_word)?;
    let mut argv: Vec<String> = vec![recipe.clone()];
    for value in args.iter().skip(1) {
        match value {
            Value::Str(s) => argv.push(devtool_word("just_run", "a recipe argument", s)?),
            other => {
                return Err(crate::safety::arg_err(format!(
                    "just_run: recipe arguments must be Strings, got {}",
                    other.type_name()
                )))
            }
        }
    }
    if argv.len() - 1 > DEVTOOL_MAX_ITEMS {
        return Err(crate::safety::arg_err(format!(
            "just_run: at most {DEVTOOL_MAX_ITEMS} recipe arguments, got {}",
            argv.len() - 1
        )));
    }
    let refs: Vec<&str> = argv.iter().map(String::as_str).collect();
    let run = finished(
        "just_run",
        tool_run(
            "just_run",
            "just",
            None,
            &refs,
            Keep::Tail(TOOL_KEEP_TAIL),
            TOOL_LONG_DEADLINE_SECS,
        )?,
    )?;
    let mut rec = run_fields(run, "stdout", "stderr");
    rec.insert("recipe".to_string(), Value::Str(recipe));
    Ok(Value::Record(rec))
}

/// just list — The recipes in the justfile in the process's directory.
/// Usage: just_list()
/// Answers an Array of {name, description?} Records. A failure, such as no
/// justfile, is E_TOOL_FAILED; it is never returned as a string.
fn bi_just_list(_args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    k8s_no_input("just_list", &input)?;
    let run = tool_run(
        "just_list",
        "just",
        None,
        &["--list"],
        Keep::Head(TOOL_MAX_TEXT),
        TOOL_DEADLINE_SECS,
    )?;
    let text = tool_text("just_list", run)?;
    let recipes: Vec<Value> = text
        .lines()
        .filter(|l| l.starts_with(char::is_whitespace) && !l.trim().is_empty())
        .map(|line| {
            let mut rec = BTreeMap::new();
            let mut parts = line.trim().splitn(2, '#');
            let name = parts.next().unwrap_or("").trim().to_string();
            rec.insert("name".to_string(), Value::Str(name));
            if let Some(desc) = parts.next() {
                rec.insert(
                    "description".to_string(),
                    Value::Str(desc.trim().to_string()),
                );
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(recipes))
}

// --- task (1043-1044) ---

/// task — Run a Taskfile task.
//
// The Taskfile's commands run inside `task`, under its own interpreter, so this
// is an exec of the task definition and is gated as Exec. The name goes to
// `task` positionally, so it is refused when it could be read as an option. The
// run is bounded in output and time, and stdin is closed, so a prompt cannot
// hang it. A nonzero exit is a coded failure with the stderr tail, not a record.
fn bi_task_run(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("task_run", &input)?;
    if args.len() != 1 {
        return Err(crate::safety::bad_arg(
            "task_run",
            "one task name",
            &format!("{} arguments", args.len()),
        ));
    }
    let task_name = match &args[0] {
        Value::Str(s) if !s.is_empty() && !s.chars().any(|c| c.is_whitespace() || c == '\0') => {
            s.clone()
        }
        other => {
            return Err(crate::safety::bad_arg(
                "task_run",
                "a task name: a non-empty string with no whitespace",
                other.type_name(),
            ))
        }
    };
    refuse_option("task_run", &task_name)?;

    let mut cmd = std::process::Command::new("task");
    cmd.arg(&task_name);
    let (stdout, stderr) = run_checked("task_run", "task", cmd, LOCAL_DEADLINE_SECS)?;
    let mut rec = BTreeMap::new();
    rec.insert("task".to_string(), Value::Str(task_name));
    rec.insert("stdout".to_string(), Value::Str(stdout.trim().to_string()));
    rec.insert("stderr".to_string(), Value::Str(stderr.trim().to_string()));
    Ok(Value::Record(rec))
}

/// task list — List available tasks.
fn bi_task_list(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    refuse_piped("task_list", &input)?;
    if !args.is_empty() {
        return Err(crate::safety::bad_arg(
            "task_list",
            "no arguments",
            &format!("{} argument(s)", args.len()),
        ));
    }
    let mut cmd = std::process::Command::new("task");
    cmd.arg("--list");
    let (stdout, _stderr) = run_checked("task_list", "task", cmd, LOCAL_DEADLINE_SECS)?;
    Ok(Value::Str(stdout.trim().to_string()))
}

