// --- buildah (1086-1087) ---

/// buildah_build(tag, [context]): buildah bud of a context directory inside the
/// workspace, tagged `tag`. A URL or git context is refused. Runs with a 15
/// minute deadline.
fn bi_buildah_build(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "buildah_build";
    pkg_shape(B, &args, &input, 2)?;
    let tag = k8s_need(B, "an image tag", &args, 0, ops_image_ref)?;
    let context = k8s_arg(B, "context", &args, 1, ops_scan_dir)?.unwrap_or_else(|| ".".to_string());
    let run = tool_run(
        B,
        "buildah",
        None,
        &["bud", "-t", tag.as_str(), context.as_str()],
        Keep::Tail(TOOL_KEEP_TAIL),
        TOOL_LONG_DEADLINE_SECS,
    )?;
    pkg_done(B, run, vec![("tag", Value::Str(tag))])
}

/// buildah images — List Buildah images.
fn bi_buildah_images(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut cmd = std::process::Command::new("buildah");
    cmd.args(["images", "--json"]);
    let output = bounded_cmd_output("buildah_images", "buildah", cmd, TOOL_DEADLINE_SECS);
    match output {
        Ok(o) if o.status.success() => {
            let stdout = String::from_utf8_lossy(&o.stdout);
            // Non-JSON output came back as a String, and a failure's stderr
            // as the answer.
            serde_json::from_str::<serde_json::Value>(&stdout)
                .map(json_to_value)
                .map_err(|e| {
                    crate::safety::tool_failed(
                        "buildah_images",
                        "buildah images --json",
                        o.status.code(),
                        &format!("output that is not JSON: {e}"),
                    )
                })
        }
        Ok(o) => Err(crate::safety::tool_failed(
            "buildah_images",
            "buildah images",
            o.status.code(),
            &String::from_utf8_lossy(&o.stderr),
        )),
        Err(e) => Err(crate::safety::tool_missing(
            "buildah",
            "buildah",
            &e.to_string(),
        )),
    }
}

