// --- yamllint (1095) ---

/// yamllint — Lint YAML files.
fn bi_yamllint_check(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("yamllint requires a file path")),
    };
    crate::safety::reject_option_like("yamllint", std::slice::from_ref(&path))?;
    let mut cmd = std::process::Command::new("yamllint");
    cmd.args(["-f", "parsable", &path]);
    let output = bounded_cmd_output("yamllint_check", "yamllint", cmd, TOOL_DEADLINE_SECS);
    match output {
        Ok(o) => {
            let stdout = String::from_utf8_lossy(&o.stdout);
            let issues: Vec<Value> = stdout
                .lines()
                .filter(|l| !l.is_empty())
                .map(|line| Value::Str(line.to_string()))
                .collect();
            // A file yamllint could not read answered {success: false,
            // issues: []}: failed, with nothing wrong.
            if !o.status.success() && issues.is_empty() {
                return Err(crate::safety::tool_failed(
                    "yamllint",
                    "yamllint",
                    o.status.code(),
                    &String::from_utf8_lossy(&o.stderr),
                ));
            }
            let mut rec = BTreeMap::new();
            rec.insert("success".to_string(), Value::Bool(o.status.success()));
            rec.insert("issues".to_string(), Value::Array(issues));
            Ok(Value::Record(rec))
        }
        Err(e) => Err(crate::safety::tool_missing(
            "yamllint",
            "yamllint",
            &e.to_string(),
        )),
    }
}

// --- prettier (1096) ---

/// prettier — Format code with Prettier.
fn bi_prettier_format(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    const B: &str = "prettier_format";
    k8s_no_input(B, &input)?;
    k8s_max_args(B, &args, 2)?;
    let path = k8s_need(B, "a file path", &args, 0, pkg_plain)?;
    pkg_inside(B, &path)?;
    let write = match args.get(1) {
        None => false,
        Some(Value::Str(s)) if s == "--write" => true,
        Some(Value::Str(s)) => {
            return Err(crate::safety::arg_err(format!(
                "{B}: the only option is \"--write\", got {s:?}"
            )))
        }
        Some(other) => {
            return Err(crate::safety::arg_err(format!(
                "{B}: the option must be a String, got {}",
                other.type_name()
            )))
        }
    };
    let mut argv: Vec<&str> = Vec::new();
    if write {
        argv.push("--write");
    }
    argv.push(path.as_str());
    let run = tool_run(
        B,
        node_tool("prettier"),
        None,
        &argv,
        Keep::Head(TOOL_MAX_TEXT),
        PKG_RUN_DEADLINE_SECS,
    )?;
    pkg_done(B, run, vec![("path", Value::Str(path))])
}

